--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: approve_client_offer_pricing_v1(uuid, jsonb); Type: FUNCTION; Schema: pppp_internal_api; Owner: postgres
--

CREATE FUNCTION pppp_internal_api.approve_client_offer_pricing_v1(p_project_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pppp_internal_api'
    AS $_$
declare
  v_project public.projects%rowtype;
  v_basis record;
  v_state jsonb:=coalesce(p_payload->'form_state','{}'::jsonb);
  v_positions jsonb:=coalesce(p_payload->'positions','[]'::jsonb);
  v_payment_plan jsonb:=coalesce(p_payload->'payment_plan','[]'::jsonb);
  v_pos jsonb;
  v_qty numeric;
  v_price numeric;
  v_total numeric:=0;
  v_positive_lines integer:=0;
  v_currency text:=upper(trim(coalesce(nullif(p_payload->>'currency',''),nullif(v_state->>'currency',''))));
  v_fx numeric;
  v_total_eur numeric;
  v_email text:=lower(trim(coalesce(nullif(p_payload->>'recipient_email',''),nullif(v_state->>'em',''))));
  v_client text:=trim(coalesce(nullif(p_payload->>'client',''),nullif(v_state->>'cli','')));
  v_contact text:=trim(coalesce(nullif(p_payload->>'contact',''),nullif(v_state->>'con','')));
  v_lang text:=lower(trim(coalesce(nullif(p_payload->>'language',''),nullif(v_state->>'lang',''),'en')));
  v_year integer:=extract(year from current_date)::integer;
  v_seq integer;
  v_doc_nr text;
  v_latest_doc text;
  v_doc public.documents_registry%rowtype;
  v_existing public.documents_registry%rowtype;
  v_revision integer:=1;
  v_offer_state jsonb;
  v_actor uuid:=auth.uid();
  v_actor_email text:=coalesce(auth.jwt()->>'email','');
  v_now timestamptz:=now();
begin
  if v_actor is null or not public.can_write() then
    raise exception 'Write permission required' using errcode='42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object' then
    raise exception 'Final pricing payload is required';
  end if;
  if jsonb_typeof(v_positions)<>'array' or jsonb_array_length(v_positions)=0 then
    raise exception 'At least one client-offer position is required';
  end if;
  if jsonb_array_length(v_positions)>150 then
    raise exception 'Too many client-offer positions';
  end if;
  if v_currency is null or v_currency !~ '^[A-Z]{3}$' then
    raise exception 'A valid 3-letter currency is required';
  end if;
  if v_email='' or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then
    raise exception 'A valid client email is required before preparing a Gmail draft';
  end if;

  begin
    v_fx:=replace(coalesce(p_payload->>'exchange_rate_to_eur',v_state->>'exchange_rate_to_eur',''),',','.')::numeric;
  exception when others then v_fx:=null; end;
  if v_currency='EUR' then v_fx:=1; end if;
  if v_currency<>'EUR' and coalesce(v_fx,0)<=0 then
    raise exception 'A reviewed exchange rate to EUR is required for non-EUR client pricing';
  end if;

  select * into v_project from public.projects where id=p_project_id;
  if not found then raise exception 'Project not found'; end if;
  if lower(coalesce(v_project.status,'')) in ('humbur','lost','mbyllur','closed','arkivuar','archived','realizuar','cancelled','canceled') then
    raise exception 'Client pricing cannot be approved on a terminal project';
  end if;

  select * into v_basis from public.pppp_selected_supplier_cost_basis_v1 where project_id=p_project_id limit 1;
  if not found then raise exception 'A human supplier decision with canonical cost basis is required first'; end if;
  if v_basis.cost_basis_readiness='blocked' then
    raise exception 'Selected supplier cost basis is blocked: %',coalesce(v_basis.warning_text,'verify supplier offer');
  end if;
  if not coalesce(v_basis.eligible_for_client_offer_handoff,false) then
    raise exception 'Project is not eligible for a new client-offer handoff in its current lifecycle state';
  end if;

  for v_pos in select value from jsonb_array_elements(v_positions)
  loop
    begin v_qty:=replace(coalesce(v_pos->>'qty','0'),',','.')::numeric; exception when others then raise exception 'Invalid quantity in client-offer position'; end;
    begin v_price:=replace(coalesce(v_pos->>'price','0'),',','.')::numeric; exception when others then raise exception 'Invalid price in client-offer position'; end;
    if v_qty<0 or v_price<0 then raise exception 'Negative quantity or price is not allowed'; end if;
    if v_qty>0 and v_price>0 then
      v_total:=v_total+(v_qty*v_price);
      v_positive_lines:=v_positive_lines+1;
    end if;
  end loop;
  if v_positive_lines=0 or v_total<=0 then
    raise exception 'Final client pricing must contain at least one positively priced position';
  end if;
  v_total:=round(v_total,2);
  v_total_eur:=round(v_total*v_fx,2);

  select * into v_existing
  from public.documents_registry d
  where d.project_id=p_project_id
    and d.series='QUO'
    and coalesce(d.offer_state->>'source','')='pppp-client-offer-finalization-v1'
    and coalesce(d.offer_state->>'pst_document_status','') not in ('sent','cancelled','superseded')
  order by d.created_at desc,d.seq desc
  limit 1
  for update;

  if found then
    v_revision:=case when coalesce(v_existing.offer_state->>'pst_revision','') ~ '^[0-9]+$' then (v_existing.offer_state->>'pst_revision')::integer+1 else 2 end;
    v_doc_nr:=v_existing.doc_nr;
  else
    perform pg_advisory_xact_lock(hashtext('documents_registry:QUO:'||v_year::text));
    select coalesce(max(seq),0)+1 into v_seq from public.documents_registry where series='QUO' and year=v_year;
    select doc_nr into v_latest_doc from public.documents_registry where series='QUO' and year=v_year order by seq desc limit 1;
    if coalesce(v_latest_doc,'') ~ '^PST-OFF-[0-9]{4}-[0-9]{2}-[0-9]+$' then
      v_doc_nr:='PST-OFF-'||v_year::text||'-'||to_char(current_date,'MM')||'-'||lpad(v_seq::text,3,'0');
    else
      v_doc_nr:='PST-QUO-'||v_year::text||'-'||lpad(v_seq::text,3,'0');
    end if;
  end if;

  v_offer_state:=coalesce(v_existing.offer_state,'{}'::jsonb)
    || v_state
    || jsonb_build_object(
      'source','pppp-client-offer-finalization-v1',
      'proj',coalesce(nullif(v_state->>'proj',''),v_project.name),
      'cli',coalesce(nullif(v_client,''),v_project.client),
      'con',v_contact,
      'em',v_email,
      'lang',v_lang,
      'currency',v_currency,
      'exchange_rate_to_eur',v_fx,
      'oferPos',v_positions,
      'human_pricing_approved',true,
      'human_review_required',true,
      'pricing_approval',jsonb_build_object(
        'actor_user_id',v_actor,
        'actor_email',v_actor_email,
        'approved_at',v_now,
        'server_calculated_total',v_total,
        'currency',v_currency,
        'exchange_rate_to_eur',v_fx
      ),
      'supplierBasis',jsonb_build_object(
        'supplier',v_basis.selected_supplier,
        'supplier_offer_id',v_basis.supplier_offer_id,
        'decision_id',v_basis.decision_id,
        'decision_type',v_basis.decision_type,
        'offer_ref',v_basis.offer_ref,
        'verified_on',v_basis.decided_at,
        'terms_flowed_down',true
      ),
      'supplierFlowdown',jsonb_strip_nulls(jsonb_build_object(
        'supplier',v_basis.selected_supplier,
        'offerRef',v_basis.offer_ref,
        'priceKg',v_basis.price_kg,
        'unitPrice',v_basis.unit_price,
        'currency',v_basis.currency,
        'unitCostEur',v_basis.unit_cost_eur,
        'qtyKg',v_basis.qty_kg,
        'explicitTotalEur',v_basis.explicit_total_eur,
        'incoterms',v_basis.incoterms,
        'paymentTerms',v_basis.payment_terms,
        'validityDays',v_basis.validity_days,
        'deliveryWeeks',v_basis.delivery_weeks,
        'cert',v_basis.cert,
        'inclusions',v_basis.inclusions,
        'exclusions',v_basis.exclusions,
        'decisionSource',v_basis.decision_source
      )),
      'pst_revision',v_revision,
      'revision_status','draft',
      'pst_document_status','pricing_approved',
      'pdf_status','pending',
      'gmail_draft_stale',true,
      'human_send_required',true
    );

  if v_existing.id is not null then
    update public.documents_registry
    set project=coalesce(nullif(v_state->>'proj',''),v_project.name),
        client=coalesce(nullif(v_client,''),v_project.client),
        total_eur=v_total_eur,
        payment_plan=v_payment_plan,
        offer_state=v_offer_state,
        currency=v_currency,
        total_amount=v_total,
        exchange_rate_to_eur=v_fx
    where id=v_existing.id
    returning * into v_doc;
  else
    insert into public.documents_registry(
      series,year,seq,doc_nr,project,client,total_eur,payment_plan,project_id,offer_state,currency,total_amount,exchange_rate_to_eur
    ) values (
      'QUO',v_year,v_seq,v_doc_nr,coalesce(nullif(v_state->>'proj',''),v_project.name),coalesce(nullif(v_client,''),v_project.client),
      v_total_eur,v_payment_plan,p_project_id,v_offer_state,v_currency,v_total,v_fx
    ) returning * into v_doc;
  end if;

  update public.tasks
  set status='mbyllur',done_at=coalesce(done_at,v_now)
  where project_id=p_project_id and source='client_offer_cost_basis_auto' and status='hapur';

  insert into public.tasks(project_id,title,detail,due_date,priority,status,source,category,source_ref)
  values(
    p_project_id,
    'Shqyrto dhe dërgo ofertën · '||v_doc.doc_nr,
    'Çmimi final u aprovua nga njeriu. PPPP po përgatit PDF + Gmail draft për '||v_email||E'.\nTotali i llogaritur nga pozicionet: '||round(v_total,2)::text||' '||v_currency||
    case when v_currency<>'EUR' then ' · ≈ '||round(v_total_eur,2)::text||' EUR' else '' end||
    E'.\nSupplier cost basis: '||coalesce(v_basis.selected_supplier,'—')||coalesce(' · '||round(v_basis.unit_cost_eur,4)::text||' EUR/'||upper(v_basis.pricing_basis),'')||
    E'.\nHuman gate: kontrollo PDF-në dhe Gmail draft-in. PPPP nuk e dërgon emailin automatikisht.',
    current_date,'larte','hapur','client_offer_final_review_auto','klient','COMMERCIAL:'||p_project_id::text||':client-offer-final-review'
  )
  on conflict(source,source_ref) do update
    set title=excluded.title,detail=excluded.detail,due_date=current_date,priority='larte',status='hapur',done_at=null;

  update public.projects
  set pipeline_stage=case when pipeline_stage in ('rfq_in','technical_review','supplier_selection','pricing') then 'client_offer' else pipeline_stage end,
      operational_state=case when coalesce(operational_state,'')='wait_for_client' then operational_state else 'active_work' end,
      updated_at=v_now
  where id=p_project_id;

  return jsonb_build_object(
    'ok',true,
    'document_id',v_doc.id,
    'doc_nr',v_doc.doc_nr,
    'revision',v_revision,
    'project_id',p_project_id,
    'recipient_email',v_email,
    'currency',v_currency,
    'total_amount',v_total,
    'total_eur',v_total_eur,
    'pst_document_status','pricing_approved',
    'pdf_required',true,
    'gmail_draft_required',true,
    'human_send_required',true
  );
end;
$_$;


ALTER FUNCTION pppp_internal_api.approve_client_offer_pricing_v1(p_project_id uuid, p_payload jsonb) OWNER TO postgres;

--
-- Name: record_supplier_decision_v1(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: pppp_internal_api; Owner: postgres
--

CREATE FUNCTION pppp_internal_api.record_supplier_decision_v1(p_project_id uuid, p_supplier_offer_id uuid, p_decision_type text DEFAULT 'selected_producer'::text, p_notes text DEFAULT NULL::text, p_evidence jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pppp_internal_api'
    AS $$
declare
  v_offer public.offers%rowtype;
  v_project public.projects%rowtype;
  v_decision public.project_supplier_decisions%rowtype;
  v_type text:=lower(trim(coalesce(p_decision_type,'selected_producer')));
  v_handoff jsonb;
begin
  if auth.uid() is null or not public.can_write() then
    raise exception 'Write permission required' using errcode='42501';
  end if;
  if v_type not in ('selected_producer','pricing_basis') then
    raise exception 'Unsupported supplier decision type';
  end if;

  select * into v_project from public.projects where id=p_project_id;
  if not found then raise exception 'Project not found'; end if;
  if lower(coalesce(v_project.status,'')) in ('humbur','lost','mbyllur','closed','arkivuar','archived','realizuar','cancelled','canceled') then
    raise exception 'Supplier decision cannot be recorded on a terminal project';
  end if;

  select * into v_offer from public.offers where id=p_supplier_offer_id and project_id=p_project_id;
  if not found then raise exception 'Supplier offer does not belong to this project'; end if;

  insert into public.project_supplier_decisions(
    project_id,supplier_offer_id,supplier_name,decision_type,status,source,evidence,notes,decided_at,updated_at
  ) values (
    p_project_id,p_supplier_offer_id,coalesce(nullif(trim(v_offer.supplier),''),'Unknown supplier'),v_type,'active',
    'authenticated_human_decision',
    coalesce(p_evidence,'{}'::jsonb)||jsonb_build_object(
      'human_confirmed',true,
      'actor_user_id',auth.uid(),
      'recorded_at',now(),
      'supplier_offer_id',p_supplier_offer_id
    ),
    nullif(trim(coalesce(p_notes,'')),''),now(),now()
  )
  on conflict(project_id,decision_type) do update
    set supplier_offer_id=excluded.supplier_offer_id,
        supplier_name=excluded.supplier_name,
        status='active',
        source=excluded.source,
        evidence=excluded.evidence,
        notes=excluded.notes,
        decided_at=now(),
        updated_at=now()
  returning * into v_decision;

  update public.tasks
  set status='mbyllur',done_at=coalesce(done_at,now())
  where project_id=p_project_id and source='procurement_comparison_auto' and status='hapur';

  if v_project.pipeline_stage in ('rfq_in','technical_review','supplier_selection') then
    update public.projects set pipeline_stage='pricing',updated_at=now() where id=p_project_id;
  end if;

  v_handoff:=public.pppp_selected_supplier_handoff_reconcile_v1(true,100,p_project_id);

  return jsonb_build_object(
    'ok',true,
    'decision_id',v_decision.id,
    'project_id',p_project_id,
    'supplier_offer_id',p_supplier_offer_id,
    'supplier_name',v_decision.supplier_name,
    'decision_type',v_decision.decision_type,
    'handoff',v_handoff,
    'human_gate_preserved',true
  );
end;
$$;


ALTER FUNCTION pppp_internal_api.record_supplier_decision_v1(p_project_id uuid, p_supplier_offer_id uuid, p_decision_type text, p_notes text, p_evidence jsonb) OWNER TO postgres;

--
-- Name: current_role_internal(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.current_role_internal() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select role from public.user_roles where user_id = auth.uid()),
    'viewer'
  );
$$;


ALTER FUNCTION private.current_role_internal() OWNER TO postgres;

--
-- Name: pppp_audit_legacy_offers_insert_v1(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.pppp_audit_legacy_offers_insert_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_headers jsonb := '{}'::jsonb;
  v_claims jsonb := '{}'::jsonb;
  v_raw text;
begin
  begin
    v_raw := current_setting('request.headers', true);
    if nullif(v_raw,'') is not null then
      v_headers := v_raw::jsonb;
    end if;
  exception when others then
    v_headers := '{}'::jsonb;
  end;

  begin
    v_raw := current_setting('request.jwt.claims', true);
    if nullif(v_raw,'') is not null then
      v_claims := v_raw::jsonb;
    end if;
  exception when others then
    v_claims := '{}'::jsonb;
  end;

  insert into private.pppp_legacy_offers_ingest_audit(
    gmail_msg_id,
    operation,
    db_user,
    jwt_role,
    user_agent,
    x_client_info,
    application_name
  ) values (
    new.gmail_msg_id,
    tg_op,
    current_user,
    nullif(v_claims->>'role',''),
    nullif(v_headers->>'user-agent',''),
    nullif(v_headers->>'x-client-info',''),
    nullif(current_setting('application_name', true),'')
  );

  return new;
end;
$$;


ALTER FUNCTION private.pppp_audit_legacy_offers_insert_v1() OWNER TO postgres;

--
-- Name: pppp_automation_health_internal(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.pppp_automation_health_internal() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'cron', 'pg_temp'
    AS $$
declare
  v jsonb;
begin
  select jsonb_build_object(
    'generated_at', now(),
    'crons', jsonb_build_object(
      'active', (select count(*) from cron.job where active),
      'latest_succeeded', (
        select count(*)
        from cron.job j
        left join lateral (
          select r.status from cron.job_run_details r
          where r.jobid=j.jobid order by r.start_time desc limit 1
        ) x on true
        where j.active and x.status='succeeded'
      ),
      'latest_failed', (
        select count(*)
        from cron.job j
        left join lateral (
          select r.status from cron.job_run_details r
          where r.jobid=j.jobid order by r.start_time desc limit 1
        ) x on true
        where j.active and coalesce(x.status,'') not in ('','succeeded')
      ),
      'http_recent_failed', (
        select count(*)
        from net._http_response r
        where r.created >= now() - interval '60 minutes'
          and (coalesce(r.timed_out,false) or r.error_msg is not null or coalesce(r.status_code,0) >= 400)
      ),
      'http_recent_5xx', (
        select count(*)
        from net._http_response r
        where r.created >= now() - interval '60 minutes'
          and coalesce(r.status_code,0) >= 500
      ),
      'http_latest_failed_at', (
        select max(r.created)
        from net._http_response r
        where r.created >= now() - interval '60 minutes'
          and (coalesce(r.timed_out,false) or r.error_msg is not null or coalesce(r.status_code,0) >= 400)
      ),
      'jobs', coalesce((
        select jsonb_agg(jsonb_build_object(
          'name', j.jobname,
          'schedule', j.schedule,
          'status', x.status,
          'started_at', x.start_time,
          'ended_at', x.end_time
        ) order by j.jobname)
        from cron.job j
        left join lateral (
          select r.status,r.start_time,r.end_time
          from cron.job_run_details r
          where r.jobid=j.jobid order by r.start_time desc limit 1
        ) x on true
        where j.active
      ), '[]'::jsonb)
    ),
    'workers', jsonb_build_object(
      'ocr', coalesce((select jsonb_agg(jsonb_build_object(
        'worker_id',worker_id,'enabled',enabled,'last_seen_at',last_seen_at
      ) order by worker_id) from public.local_ocr_workers),'[]'::jsonb),
      'semantic', coalesce((select jsonb_agg(jsonb_build_object(
        'label',label,'active',is_active,'last_used_at',last_used_at
      ) order by last_used_at desc nulls last) from public.semantic_worker_keys),'[]'::jsonb)
    ),
    'queues', jsonb_build_object(
      'ocr', coalesce((select jsonb_object_agg(status,cnt) from (
        select status,count(*) cnt from public.local_ocr_jobs group by status
      ) q),'{}'::jsonb),
      'semantic', coalesce((select jsonb_object_agg(state,cnt) from (
        select state,count(*) cnt from public.semantic_ai_jobs group by state
      ) q),'{}'::jsonb)
    ),
    'backlog', jsonb_build_object(
      'legacy_needs_vision', (select count(*) from public.project_attachment_links where analysis_status='needs_vision'),
      'needs_ocr', (select count(*) from public.project_attachment_links where analysis_status='needs_ocr'),
      'local_ocr_queued', (select count(*) from public.project_attachment_links where analysis_status='local_ocr_queued'),
      'local_ocr_failed', (select count(*) from public.project_attachment_links where analysis_status='local_ocr_failed'),
      'document_review_tasks', (select count(*) from public.tasks where source='document_bom_review' and lower(coalesce(status,'')) not in ('mbyllur','done','kryer')),
      'rfq_draft_review', (select count(*) from public.rfq_log where status='draft_review'),
      'projects_without_drive', (select count(*) from public.projects where lower(coalesce(status,'')) not in ('humbur','lost','arkivuar','archived','mbyllur','closed','realizuar') and coalesce(nullif(btrim(drive_folder_id),''),nullif(btrim(drive_folder_url),'')) is null),
      'project_discovery_open', (select count(*) from public.project_discovery_candidates where status in ('open','review')),
      'supplier_offers_inbox', (select count(*) from public.offers_inbox),
      'supplier_offers_normalized', (select count(*) from public.offers),
      'supplier_decisions', (select count(*) from public.project_supplier_decisions),
      'invoices_in', (select count(*) from public.invoices_in),
      'invoices_out', (select count(*) from public.invoices_out)
    ),
    'tenders', jsonb_build_object(
      'ted', (select count(*) from public.kek_tender_watch where source_key like 'TED:%'),
      'app_albania', (select count(*) from public.kek_tender_watch where source_key like 'APP_AL:%'),
      'krpp_kek', (select count(*) from public.kek_tender_watch where source_key not like 'TED:%' and source_key not like 'APP_AL:%'),
      'linked_projects', (select count(*) from public.kek_tender_watch where project_id is not null)
    )
  ) into v;
  return v;
end;
$$;


ALTER FUNCTION private.pppp_automation_health_internal() OWNER TO postgres;

--
-- Name: pppp_automation_operating_health_v1(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.pppp_automation_operating_health_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'net'
    AS $$
declare r record; payload jsonb; latest jsonb:='{}'::jsonb; key text; stamp jsonb;
begin
  if coalesce(auth.role(),'') <> 'service_role' and not coalesce(public.is_admin(),false) then
    raise exception 'forbidden' using errcode='42501';
  end if;
  for r in select status_code,timed_out,error_msg,content,created
    from net._http_response where created>=now()-interval '24 hours'
    order by created desc limit 128
  loop
    begin payload:=r.content::jsonb; exception when others then continue; end;
    key:=case
      when payload ? 'bridge' then 'command_bridge'
      when payload ? 'new_messages' and payload ? 'listed' then 'gmail_ingest'
      when payload ? 'unmatched' and payload ? 'tasks_created' then 'project_intake'
      when payload ? 'synthesized' and payload ? 'configured' then 'memory_synthesis'
      when payload ? 'provider_configured' then 'event_intelligence'
      when payload ? 'pairs_scanned' then 'attachments'
      else null end;
    if key is null or latest ? key then continue; end if;
    stamp:=jsonb_build_object('at',r.created,'http_status',r.status_code,
      'timed_out',r.timed_out,'error',left(coalesce(r.error_msg,payload->>'reason',payload->>'error'),180));
    -- Return only counters/configuration, never raw emails, URLs, credentials or provider output.
    select stamp||coalesce(jsonb_object_agg(e.key,e.value),'{}'::jsonb) into stamp
    from jsonb_each(payload) e where e.key=any(array[
      'ok','checked','processed','succeeded','failed','skipped','listed','new_messages','inserted',
      'linked','review','unmatched','identity_conflicts','tasks_created','quotes_created','analyses_created',
      'configured','synthesized','projects_checked','provider','provider_configured',
      'queued','candidates','messages_fetched','rows_registered','pairs_scanned']);
    latest:=latest||jsonb_build_object(key,stamp);
  end loop;
  return jsonb_build_object('runtime',latest,'generated_at',now(),
    'commands_7d',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (
      select action_type,status,count(*) as count,max(updated_at) as latest
      from public.pppp_chatgpt_command_receipts where created_at>=now()-interval '7 days'
      group by action_type,status) x),
    'tender_fetch',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (
      select status,count(*) as count,max(last_attempt_at) as last_attempt,min(requested_at) as oldest
      from public.pppp_tender_fetch_queue group by status) x),
    'steel_discovery',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (
      select run_date,status,discovered_count,inserted_count,finished_at,left(error_message,180) as error
      from public.pppp_steel_buyer_discovery_runs_v1 order by started_at desc limit 3) x),
    'outbound_sync',(select jsonb_build_object('status',status,'at',completed_at,'error',left(error_message,180))
      from public.pppp_automation_http_runs where automation_key='pppp-outbound-sync' order by created_at desc limit 1)
  );
end;
$$;


