-- Name: pppp_text_array_union_v1(text[], text[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.pppp_text_array_union_v1(a text[], b text[]) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select coalesce(array_agg(x order by x) filter(where x<>''),'{}'::text[])
  from (
    select distinct btrim(x) x
    from unnest(coalesce(a,'{}'::text[]) || coalesce(b,'{}'::text[])) u(x)
    where nullif(btrim(x),'') is not null
  ) s;
$$;


