--
-- Name: chatgpt_command_bridge_internal_request(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.chatgpt_command_bridge_internal_request(p_limit integer DEFAULT 50) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := least(200, greatest(1, coalesce(p_limit, 50)));
  v_secret text;
  v_request_id bigint;
begin
  select decrypted_secret
    into v_secret
  from vault.decrypted_secrets
  where name = 'gmail_tracker_cron_secret'
  limit 1;

  if nullif(v_secret, '') is null then
    raise exception using errcode = '22023', message = 'chatgpt_command_bridge_cron_secret_missing';
  end if;

  select net.http_post(
    url := 'https://awqfpnzqwfjrjefoktgd.supabase.co/functions/v1/chatgpt-command-bridge?limit=' || v_limit::text,
    body := '{}'::jsonb,
    params := '{}'::jsonb,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-pppp-cron-secret', v_secret
    ),
    timeout_milliseconds := 120000
  ) into v_request_id;

  return v_request_id;
end;
$$;


ALTER FUNCTION public.chatgpt_command_bridge_internal_request(p_limit integer) OWNER TO postgres;

