COMMENT ON FUNCTION public.gmail_tracker_cron_authorized(provided text) IS 'Validates the internal gmail-tracker cron secret stored in Supabase Vault. Browser roles cannot execute this RPC.';


--
-- Name: gmail_tracker_internal_request(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gmail_tracker_internal_request(p_action text DEFAULT 'run'::text, p_days integer DEFAULT 7, p_limit integer DEFAULT 20) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_action text; v_days integer:=least(14,greatest(1,coalesce(p_days,7))); v_limit integer:=least(40,greatest(1,coalesce(p_limit,20))); v_url text; begin
 if p_action not in ('ping','ingest_preview','ingest','body_hydrate','attachment_sync','scan_preview','scan','sla','run') then raise exception 'Unsupported gmail tracker action: %',p_action; end if;
 v_action:=p_action; v_url:='https://awqfpnzqwfjrjefoktgd.supabase.co/functions/v1/gmail-tracker?action='||v_action;
 if v_action in ('ingest_preview','ingest','scan_preview','scan') then v_url:=v_url||'&days='||v_days;
 elsif v_action in ('body_hydrate','attachment_sync') then v_url:=v_url||'&limit='||v_limit;
 elsif v_action='run' then v_url:=v_url||'&days='||v_days||'&body_limit='||v_limit||'&attachment_limit='||v_limit; end if;
 return public.pppp_enqueue_automation_http_v1('gmail-tracker-'||v_action,v_url,'gmail_tracker_cron_secret',120000,3);
end;$$;


ALTER FUNCTION public.gmail_tracker_internal_request(p_action text, p_days integer, p_limit integer) OWNER TO postgres;

