  if new.analysis_status in ('ocr_unavailable','needs_ocr','needs_vision')
     and new.storage_path is not null
     and (old.analysis_status is distinct from new.analysis_status or old.storage_path is distinct from new.storage_path) then
    perform public.local_ocr_enqueue_attachment(new.id);
  end if;
  return new;
end;
