--
-- Name: local_ocr_no_text_job_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.local_ocr_no_text_job_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare a record; v_duplicate bigint; v_is_tiny_word_artifact boolean:=false; v_is_image boolean:=false; begin
  if new.status<>'no_text' or old.status is not distinct from new.status then return new; end if;
  if new.expense_receipt_id is not null then
    update public.pppp_expense_receipts_v1 set status='no_text',last_error='OCR lokal nuk gjeti tekst të lexueshëm. Provo një foto më të qartë ose plotëso të dhënat manualisht.',updated_at=now() where id=new.expense_receipt_id and status not in ('confirmed','ignored','duplicate');
    return new;
  end if;
  select id,project_id,attachment_name,attachment_mime_type,attachment_size_bytes,content_sha256 into a from public.project_attachment_links where id=new.attachment_link_id;
  if not found then return new; end if;
  v_is_tiny_word_artifact:=coalesce(a.attachment_size_bytes,0)<=4096 and coalesce(a.attachment_name,'') ~* '^~WRD.*\.(jpe?g|png|gif|bmp)$';
  v_is_image:=coalesce(a.attachment_mime_type,'') ilike 'image/%' or coalesce(a.attachment_name,'') ~* '\.(jpe?g|png|webp|gif|bmp|tiff?)$';
  if v_is_tiny_word_artifact then
    update public.project_attachment_links set analysis_status='metadata_noise',analysis_method='local-tesseract-no-text-v2',analysis_error=null,extracted_data=coalesce(extracted_data,'{}'::jsonb)||jsonb_build_object('no_text_classification','metadata_noise'),bom_status='none',bom_applied_count=0,updated_at=now() where id=a.id;
    update public.tasks set status='mbyllur',done_at=coalesce(done_at,now()) where source='document_bom_review' and source_ref='ATTACHMENT:'||a.id::text and lower(coalesce(status,'')) not in ('kryer','mbyllur','done','closed'); return new;
  end if;
  if coalesce(a.content_sha256,'')<>'' then select x.id into v_duplicate from public.project_attachment_links x where x.project_id is not distinct from a.project_id and x.id<a.id and x.content_sha256=a.content_sha256 order by x.id asc limit 1; end if;
  if v_duplicate is not null then
    update public.project_attachment_links set analysis_status='duplicate_content',analysis_method='sha256-dedupe-after-ocr-empty-v1',analysis_error=null,extracted_data=coalesce(extracted_data,'{}'::jsonb)||jsonb_build_object('no_text_classification','duplicate_content','duplicate_of_attachment_link_id',v_duplicate),bom_status='already_present',bom_applied_count=0,updated_at=now() where id=a.id;
    update public.tasks set status='mbyllur',done_at=coalesce(done_at,now()) where source='document_bom_review' and source_ref='ATTACHMENT:'||a.id::text and lower(coalesce(status,'')) not in ('kryer','mbyllur','done','closed'); return new;
  end if;
  if v_is_image then
    update public.project_attachment_links set analysis_status='image_review',analysis_method='local-tesseract-no-text-v2',analysis_error=null,extracted_data=coalesce(extracted_data,'{}'::jsonb)||jsonb_build_object('no_text_classification','image_review'),bom_status='review',bom_applied_count=0,updated_at=now() where id=a.id;
    update public.tasks set status='mbyllur',done_at=coalesce(done_at,now()) where source='document_bom_review' and source_ref='ATTACHMENT:'||a.id::text and lower(coalesce(status,'')) not in ('kryer','mbyllur','done','closed');
    insert into public.tasks(project_id,title,detail,due_date,priority,status,source,source_ref,category)
    values(a.project_id::uuid,'[AUTO] Rishiko fotografinë: '||coalesce(a.attachment_name,'attachment'),'OCR lokal nuk gjeti tekst të lexueshëm. Kjo nuk është OCR failure. Shiko fotografinë vizualisht vetëm për të konfirmuar nëse përmban informacion teknik/quality që duhet ruajtur ose vepruar.',current_date,'mesatare','hapur','document_image_review','ATTACHMENT:'||a.id::text,'intern')
    on conflict(source,source_ref) do update set title=excluded.title,detail=excluded.detail,category=excluded.category,priority=excluded.priority,status=case when lower(coalesce(public.tasks.status,'')) in ('kryer','mbyllur','done','closed') then public.tasks.status else 'hapur' end;
  end if;
  return new;
end;$_$;


ALTER FUNCTION public.local_ocr_no_text_job_trigger() OWNER TO postgres;

--
-- Name: local_ocr_propagate_identical_content_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.local_ocr_propagate_identical_content_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  src record;
  dup record;
begin
  if new.status not in ('completed','no_text') or old.status is not distinct from new.status then
    return new;
  end if;

  -- This trigger is named zzz_* so the existing completed/no_text attachment-state
  -- trigger has already materialized the canonical result before propagation.
  select id,project_id,content_sha256,analysis_status,analysis_method,extracted_text,
         extracted_data,analysis_confidence,analysis_error,analyzed_at,bom_status
    into src
  from public.project_attachment_links
  where id=new.attachment_link_id;

  if not found or nullif(btrim(coalesce(src.content_sha256,'')),'') is null then
    return new;
  end if;

  for dup in
    select id
    from public.project_attachment_links
    where id<>src.id
      and project_id is not distinct from src.project_id
      and content_sha256=src.content_sha256
      and analysis_status='local_ocr_queued'
    order by id
  loop
    if new.status='completed' and src.analysis_status='analyzed' then
      update public.project_attachment_links
      set analysis_status='analyzed',
          analysis_method='duplicate-local-ocr-reference-v1',
          extracted_text=src.extracted_text,
          extracted_data=coalesce(src.extracted_data,'{}'::jsonb) || jsonb_build_object(
            'duplicate_of_attachment_link_id',src.id,
            'source_local_ocr_job_id',new.id
          ),
          analysis_confidence=src.analysis_confidence,
          analysis_error=null,
          analyzed_at=coalesce(src.analyzed_at,new.completed_at,now()),
          bom_status='already_present',
          bom_candidates='[]'::jsonb,
          bom_applied_count=0,
          updated_at=now()
      where id=dup.id;
    elsif new.status='no_text' then
      if src.analysis_status='metadata_noise' then
        update public.project_attachment_links
        set analysis_status='metadata_noise',
            analysis_method='duplicate-metadata-noise-v1',
            analysis_error=null,
            extracted_data=coalesce(extracted_data,'{}'::jsonb) || jsonb_build_object(
              'duplicate_of_attachment_link_id',src.id,
              'source_local_ocr_job_id',new.id
            ),
            analyzed_at=coalesce(src.analyzed_at,new.completed_at,now()),
            bom_status='none',bom_candidates='[]'::jsonb,bom_applied_count=0,updated_at=now()
        where id=dup.id;
      else
        update public.project_attachment_links
        set analysis_status='duplicate_content',
            analysis_method='sha256-dedupe-after-ocr-empty-v2',
            analysis_error=null,
            extracted_data=coalesce(extracted_data,'{}'::jsonb) || jsonb_build_object(
              'duplicate_of_attachment_link_id',src.id,
              'source_local_ocr_job_id',new.id
            ),
            analyzed_at=coalesce(src.analyzed_at,new.completed_at,now()),
            bom_status='already_present',bom_candidates='[]'::jsonb,bom_applied_count=0,updated_at=now()
        where id=dup.id;
      end if;
    end if;

    update public.local_ocr_jobs
    set status='cancelled',completed_at=coalesce(completed_at,now()),updated_at=now(),
        error='Cancelled: identical content resolved by local OCR job #'||new.id::text
    where attachment_link_id=dup.id and status='queued';

    update public.tasks
    set status='mbyllur',done_at=coalesce(done_at,now())
    where source in ('document_bom_review','document_image_review')
      and source_ref='ATTACHMENT:'||dup.id::text
      and lower(coalesce(status,'')) not in ('kryer','mbyllur','done','closed');
  end loop;

  return new;
end;
$$;


ALTER FUNCTION public.local_ocr_propagate_identical_content_trigger() OWNER TO postgres;

--
-- Name: local_ocr_submit_result(text, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.local_ocr_submit_result(p_worker_id text, p_job_id bigint, p_result_text text, p_result_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.local_ocr_jobs
     set status = 'completed',
         result_text = left(coalesce(p_result_text,''), 500000),
         result_metadata = coalesce(p_result_metadata,'{}'::jsonb),
         completed_at = now(),
         heartbeat_at = now(),
         updated_at = now(),
         error = null
   where id = p_job_id
     and worker_id = p_worker_id
     and status = 'processing';
  return found;
end;
$$;


