--
-- Name: merge_crm_contacts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.merge_crm_contacts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  n integer;
begin
  insert into contacts (kind, company, person, email, role, hubspot_id, hubspot_url, notes)
  select
    'client',
    coalesce(nullif(trim(c.company),''), split_part(c.email,'@',2)),
    nullif(trim(coalesce(c.firstname,'')||' '||coalesce(c.lastname,'')),''),
    c.email,
    c.jobtitle,
    c.hs_id,
    'https://app-eu1.hubspot.com/contacts/147958987/record/0-1/'||c.hs_id,
    'Importuar automatikisht nga HubSpot'
  from crm_contacts c
  where c.email is not null
    and c.email <> ''
    and not exists (
      select 1 from contacts t
      where lower(t.email) = lower(c.email)
         or t.hubspot_id = c.hs_id
    );

  get diagnostics n = row_count;
  return n;
end;
$$;


ALTER FUNCTION public.merge_crm_contacts() OWNER TO postgres;

--
-- Name: pppp_accept_representation_discovery_candidate_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_accept_representation_discovery_candidate_v1(p_candidate_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare c public.pppp_representation_discovery_candidates_v1%rowtype; v_target uuid; v_opportunity uuid; v_conflicts text[];
begin
  if (select auth.uid()) is null then raise exception using errcode='42501',message='authentication_required'; end if;
  select * into c from public.pppp_representation_discovery_candidates_v1 where id=p_candidate_id for update;
  if not found then raise exception using errcode='P0002',message='representation_discovery_candidate_not_found'; end if;
  if c.status='accepted' then return jsonb_build_object('ok',true,'idempotent',true,'target_id',c.target_id,'opportunity_id',c.opportunity_id); end if;
  if c.status in ('rejected','duplicate') then raise exception using errcode='22023',message='candidate_not_accept_ready:'||c.status; end if;

  if c.candidate_kind='opportunity' and not public.pppp_representation_tender_current_v1(c.tender_watch_id) then
    raise exception using errcode='22023',message='tender_not_current_or_not_relevant_for_jv';
  end if;
  if c.candidate_kind='company' and not public.pppp_representation_company_signal_fit_v1(c.company_name,c.title) then
    raise exception using errcode='22023',message='company_business_signal_required';
  end if;
  if c.candidate_kind='company' then
    if c.company_domain is null or c.company_name is null then raise exception using errcode='22023',message='verified_company_name_and_domain_required'; end if;
    v_conflicts:=public.pppp_representation_discovery_conflicts_v1(c.company_domain);
    if cardinality(v_conflicts)>0 then
      update public.pppp_representation_discovery_candidates_v1 set status='review',routing_conflicts=v_conflicts,reviewed_at=now(),reviewed_by=(select auth.uid()) where id=c.id;
      raise exception using errcode='23505',message='cross_module_identity_review_required:'||array_to_string(v_conflicts,',');
    end if;
    insert into public.pppp_representation_targets_v1(
      company_name,company_domain,company_website,country,source_key,source_name,source_url,target_type,stage,priority_score,
      why_kosovo,market_evidence,strategic_fit_notes,target_model,target_territory,created_source,identity_review_status
    ) values(
      c.company_name,c.company_domain,'https://'||c.company_domain,case when c.country_code='US' then 'United States' else c.country_code end,
      'rep:'||lower(coalesce(c.country_code,'xx'))||':'||c.company_domain,c.source_name,c.source_url,'representation','found',c.score,
      array_to_string(c.reasons,' · '),c.title,'Accepted from isolated market-entry discovery inbox. Human verification remains required.',
      'market_development_partner','Kosovo / Western Balkans','import','clear'
    ) returning id into v_target;
    update public.pppp_representation_discovery_candidates_v1 set status='accepted',target_id=v_target,reviewed_at=now(),reviewed_by=(select auth.uid()) where id=c.id;
  else
    if c.tender_watch_id is null then raise exception using errcode='22023',message='tender_watch_reference_required'; end if;
    insert into public.pppp_representation_opportunities_v1(
      source_key,project_name,funding_institution,tender_reference,official_source,total_project_value,currency,status,
      procurement_stage,tender_deadline,scope,verification_status,fact_evidence,notes
    )
    select t.source_key,t.title,coalesce(t.authority,c.source_name),coalesce(t.procurement_no,t.publication_no),coalesce(t.detail_url,t.source_url),
      t.estimated_value,t.currency,'pipeline',coalesce(t.payload->>'procurement_stage',t.document_type),t.deadline,
      coalesce(t.fpp_description,t.category,t.contract_type),'review',
      jsonb_build_object('origin','representation_discovery','source_status','confirmed','source',coalesce(t.detail_url,t.source_url),
        'tender_watch_id',t.id,'operator_acceptance_required_for_partner_research',true),
      'Accepted from isolated JV/consortium discovery inbox. No Project, Partner, Contact or outreach was created.'
    from public.kek_tender_watch t where t.id=c.tender_watch_id
    on conflict(source_key) do update set updated_at=now()
    returning id into v_opportunity;
    update public.pppp_representation_discovery_candidates_v1 set status='accepted',opportunity_id=v_opportunity,reviewed_at=now(),reviewed_by=(select auth.uid()) where id=c.id;
  end if;
  return jsonb_build_object('ok',true,'candidate_id',c.id,'target_id',v_target,'opportunity_id',v_opportunity,
    'project_created',false,'partner_created',false,'contact_created',false,'outbound_created',false,'email_sent',false);
end;
$$;


ALTER FUNCTION public.pppp_accept_representation_discovery_candidate_v1(p_candidate_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION pppp_accept_representation_discovery_candidate_v1(p_candidate_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_accept_representation_discovery_candidate_v1(p_candidate_id uuid) IS 'Human acceptance creates only the corresponding Representation target or Representation opportunity; never a Project, Partner, Contact, Supplier, draft or email.';


--
-- Name: pppp_accept_steel_buyer_discovery_candidate_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_accept_steel_buyer_discovery_candidate_v1(p_candidate_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare c public.pppp_steel_buyer_discovery_candidates_v1%rowtype; v_target uuid;
begin
  if auth.uid() is null then raise exception using errcode='42501',message='authenticated_user_required'; end if;
  select * into c from public.pppp_steel_buyer_discovery_candidates_v1 where id=p_candidate_id for update;
  if not found then raise exception using errcode='P0002',message='discovery_candidate_not_found'; end if;
  if c.target_id is not null then return jsonb_build_object('ok',true,'reused',true,'target_id',c.target_id); end if;
  if c.status<>'new' or cardinality(c.routing_conflicts)>0 then
    raise exception using errcode='23514',message='candidate_requires_routing_review';
  end if;
  if exists(select 1 from public.pppp_dach_steel_targets_v1 t where t.target_status not in('closed','rejected')
    and public.pppp_normalize_company_domain_v1(coalesce(t.company_domain,t.company_website))=c.official_domain) then
    update public.pppp_steel_buyer_discovery_candidates_v1 set status='duplicate',reason='steel_buyer_created_before_acceptance' where id=c.id;
    raise exception using errcode='23505',message='steel_buyer_already_exists';
  end if;
  insert into public.pppp_dach_steel_targets_v1(
    source_key,source_name,source_url,company_name,company_domain,company_website,country,buyer_type,
    score_band,target_status,why_now,quote_readiness,steel_scope,products,material_confidence,evidence,
    contact_status,outreach_status,next_action,last_verified_at,company_profile,company_size_band,primary_activity,
    consumption_potential,canonical_company_id,discovery_candidate_id
  ) values(
    'mt:'||lower(coalesce(c.country_code,'xx'))||':'||c.official_domain,'Wikidata public company discovery',c.source_url,
    c.company_name,c.official_domain,c.website,c.country_code,c.industry,
    case when c.consumption_potential='high' then 'B1' else 'B2' end,'watch',
    'Public company evidence indicates recurring steel-material consumption; verify procurement fit and contact before outreach.',
    'M1',coalesce(c.industry,'Steel-material demand to verify'),'{}'::text[],0.55,c.evidence,'missing','not_ready',
    'Verify company activity, consumption estimate and procurement contact. No draft is created automatically.',now(),
    jsonb_strip_nulls(jsonb_build_object('primary_activity',c.industry,'size_band',c.size_band,
      'consumption_potential',c.consumption_potential,'employees',c.employees,'revenue',c.revenue_text)),
    c.size_band,c.industry,c.consumption_potential,c.canonical_company_id,c.id
  ) returning id into v_target;
  update public.pppp_steel_buyer_discovery_candidates_v1 set status='accepted',target_id=v_target,last_seen_at=now() where id=c.id;
  insert into public.pppp_company_module_roles_v1(company_id,module,role,source_record_id,evidence)
  values(c.canonical_company_id,'steel_buyers','material_buyer',v_target::text,jsonb_build_object('discovery_candidate_id',c.id))
  on conflict(module,source_record_id) do update set company_id=excluded.company_id,active=true,updated_at=now();
  return jsonb_build_object('ok',true,'reused',false,'target_id',v_target,'outbound_created',false,
    'gmail_draft_created',false,'external_email_sent',false);
end;
$$;


ALTER FUNCTION public.pppp_accept_steel_buyer_discovery_candidate_v1(p_candidate_id uuid) OWNER TO postgres;

--
-- Name: pppp_apply_expense_receipt_ocr_v1(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_apply_expense_receipt_ocr_v1(p_receipt_id uuid, p_text text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare j jsonb; begin
  if nullif(btrim(coalesce(p_text,'')),'') is null then return false; end if;
  j:=public.pppp_parse_expense_receipt_text_v1(p_text);
  update public.pppp_expense_receipts_v1
     set ocr_text=left(p_text,120000),ocr_metadata=coalesce(p_metadata,'{}'::jsonb),parsed_data=j,
         supplier=nullif(j->>'supplier',''),invoice_nr=nullif(j->>'invoice_nr',''),
         expense_date=nullif(j->>'date','')::date,category=coalesce(nullif(j->>'category',''),'tjera'),
         amount=nullif(j->>'amount','')::numeric,net_amount=nullif(j->>'net_amount','')::numeric,
         vat_rate=nullif(j->>'vat_rate','')::numeric,vat_amount=nullif(j->>'vat_amount','')::numeric,
         currency=coalesce(nullif(j->>'currency',''),'EUR'),quantity=nullif(j->>'quantity','')::numeric,
         unit=nullif(j->>'unit',''),unit_price=nullif(j->>'unit_price','')::numeric,
         confidence=coalesce((j->>'confidence')::numeric,0),review_fields=coalesce(j->'review_fields','[]'::jsonb),
         status='review',last_error=null,updated_at=now()
   where id=p_receipt_id and status not in ('confirmed','ignored','duplicate');
  return found;
end;$$;


