--
-- Name: pppp_approve_invoice_candidate_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_approve_invoice_candidate_v1(p_candidate_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  c public.invoice_candidates%rowtype;
  p public.projects%rowtype;
  v_id uuid;
  v_nr text;
  v_currency text;
  v_total numeric;
  v_vat numeric;
  v_existing uuid;
begin
  if not public.can_write() then raise exception 'Write permission required' using errcode='42501'; end if;
  select * into c from public.invoice_candidates where id=p_candidate_id for update;
  if not found then raise exception 'Invoice candidate not found'; end if;
  if c.status='approved' and c.canonical_invoice_in_id is not null then
    return jsonb_build_object('ok',true,'status','already_approved','invoice_id',c.canonical_invoice_in_id);
  end if;
  if c.status<>'review' then raise exception 'Candidate is not in review state'; end if;
  if c.direction<>'incoming' then raise exception 'Only incoming supplier invoices may be approved here'; end if;
  select * into p from public.projects where id=c.project_id;
  if not found then raise exception 'Project not found'; end if;

  v_nr=btrim(coalesce(c.extracted->>'invoice_number',''));
  v_currency=upper(btrim(coalesce(c.extracted->>'currency','')));
  v_total=nullif(c.extracted->>'total_amount','')::numeric;
  v_vat=nullif(c.extracted->>'vat_pct','')::numeric;
  if v_nr='' then raise exception 'Invoice number must be reviewed before approval'; end if;
  if v_currency='' then raise exception 'Currency must be reviewed before approval'; end if;
  if coalesce(v_total,0)<=0 then raise exception 'Invoice total must be reviewed before approval'; end if;

  select i.id into v_existing from public.invoices_in i
  where i.project_id=c.project_id
    and lower(btrim(coalesce(i.supplier,'')))=lower(btrim(coalesce(c.party_name,c.party_email,'')))
    and btrim(coalesce(i.supplier_invoice_nr,''))=v_nr
  order by i.created_at desc limit 1;

  if v_existing is null then
    insert into public.invoices_in(
      supplier,supplier_invoice_nr,date,project,amount,currency,notes,vat_applicable,vat_rate,
      payment_terms,paid,due_date,project_id
    ) values (
      coalesce(nullif(c.party_name,''),c.party_email),v_nr,nullif(c.extracted->>'date','')::date,
      p.name,v_total,v_currency,'Approved from PPPP review candidate '||c.id::text,
      case when v_vat is null then null else v_vat>0 end,v_vat,nullif(c.extracted->>'payment_terms',''),
      false,nullif(c.extracted->>'due_date','')::date,c.project_id
    ) returning id into v_id;
    v_existing=v_id;
  end if;

  update public.invoice_candidates
  set status='approved',canonical_invoice_in_id=v_existing,reviewed_at=now(),updated_at=now()
  where id=c.id;

  if not exists(select 1 from public.invoice_candidates where project_id=c.project_id and status='review') then
    update public.tasks set status='mbyllur',done_at=coalesce(done_at,now())
    where project_id=c.project_id and source='commercial_intake_review'
      and source_ref='commercial-intake:'||c.project_id::text||':invoice' and status='hapur';
  end if;

  return jsonb_build_object('ok',true,'status','approved','invoice_id',v_existing,'project_id',c.project_id);
end;
$$;


ALTER FUNCTION public.pppp_approve_invoice_candidate_v1(p_candidate_id uuid) OWNER TO postgres;

--
-- Name: pppp_approve_outgoing_invoice_candidate_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_approve_outgoing_invoice_candidate_v1(p_candidate_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  c public.invoice_candidates%rowtype; p public.projects%rowtype; o public.documents_registry%rowtype;
  v_invoice_id uuid; v_registry_id uuid; v_existing uuid; v_offer_id uuid; v_index integer; v_amount numeric; v_pct numeric;
  v_currency text; v_fx numeric; v_days integer; v_event text; v_label text; v_year integer:=extract(year from current_date)::integer;
  v_seq integer; v_nr text; v_due date; v_actor uuid:=auth.uid();
begin
  if not public.can_write() then raise exception 'Write permission required' using errcode='42501'; end if;
  select * into c from public.invoice_candidates where id=p_candidate_id for update;
  if not found then raise exception 'Invoice candidate not found'; end if;
  if c.direction<>'outgoing' then raise exception 'Candidate is not outgoing'; end if;
  if c.status='approved' and c.canonical_invoice_out_id is not null then
    return jsonb_build_object('ok',true,'status','already_approved','invoice_id',c.canonical_invoice_out_id);
  end if;
  if c.status<>'review' then raise exception 'Candidate is not in review state'; end if;
  if coalesce(c.extracted->>'readiness','')<>'review' then raise exception 'Milestone is not ready for invoice review'; end if;

  v_offer_id=nullif(c.extracted->>'offer_id','')::uuid;
  v_index=nullif(c.extracted->>'milestone_index','')::integer;
  v_amount=nullif(c.extracted->>'amount','')::numeric;
  v_pct=nullif(c.extracted->>'milestone_pct','')::numeric;
  v_currency=upper(btrim(coalesce(c.extracted->>'currency','EUR')));
  v_fx=nullif(c.extracted->>'exchange_rate_to_eur','')::numeric;
  v_days=coalesce(nullif(c.extracted->>'payment_days','')::integer,0);
  v_event=lower(coalesce(c.extracted->>'milestone_event','milestone'));
  v_label=coalesce(nullif(c.extracted->>'milestone_label',''),'Milestone '||(v_index+1)::text);
  if v_offer_id is null or v_index is null then raise exception 'Source offer/milestone is missing'; end if;
  if coalesce(v_amount,0)<=0 then raise exception 'Invoice amount must be reviewed'; end if;

  select * into o from public.documents_registry where id=v_offer_id and series='QUO';
  if not found then raise exception 'Source quotation not found'; end if;
  if lower(coalesce(o.followup_status,''))<>'won' then raise exception 'Source quotation is not marked won'; end if;
  select * into p from public.projects where id=c.project_id;
  if not found then raise exception 'Project not found'; end if;

  select i.id into v_existing from public.invoices_out i where i.source_offer_id=v_offer_id and i.source_milestone_index=v_index limit 1;
  if v_existing is not null then
    update public.invoice_candidates set status='approved',canonical_invoice_out_id=v_existing,reviewed_at=now(),updated_at=now() where id=c.id;
    return jsonb_build_object('ok',true,'status','already_invoiced','invoice_id',v_existing);
  end if;

  perform pg_advisory_xact_lock(hashtext('pppp:invoice-number:'||v_year::text));
  select greatest(
    coalesce((select max(d.seq) from public.documents_registry d where d.series='INV' and d.year=v_year),0),
    coalesce((select max((regexp_match(i.invoice_nr,'^PST-INV-'||v_year::text||'-([0-9]+)$'))[1]::integer)
              from public.invoices_out i where i.invoice_nr ~ ('^PST-INV-'||v_year::text||'-[0-9]+$')),0)
  )+1 into v_seq;
  v_nr='PST-INV-'||v_year::text||'-'||lpad(v_seq::text,3,'0');
  v_due=current_date+greatest(v_days,0);

  insert into public.invoices_out(invoice_nr,lang,date,project,ref,client,contact,address,items,total_price,currency,payment_terms,notes,
    vat_applicable,vat_rate,net_amount,vat_amount,gross_amount,paid,invoice_type,contract_value,advance_pct,due_date,project_id,source_offer_id,
    source_offer_doc_nr,source_milestone_index,exchange_rate_to_eur)
  values(v_nr,coalesce(nullif(o.offer_state->>'lang',''),'en'),current_date,p.name,o.doc_nr,coalesce(o.client,p.client),nullif(o.offer_state->>'con',''),
    nullif(o.offer_state->>'addr',''),jsonb_build_array(jsonb_build_object('kg',0,'pcs',0,'desc',v_label||' · '||o.doc_nr,'priceKg',0)),
    v_amount,v_currency,case when v_days>0 then v_days::text||' days' else 'Due according to approved milestone' end,
    'Created from approved PPPP invoice candidate '||c.id::text||'. Human send required.',false,0,v_amount,0,v_amount,false,
    case when v_index=0 and v_event ~ '(order|advance|agreement)' then 'advance' else 'standard' end,
    coalesce(o.total_amount,o.total_eur),case when v_index=0 then v_pct else null end,v_due,c.project_id,v_offer_id,o.doc_nr,v_index,v_fx)
  returning id into v_invoice_id;

  insert into public.documents_registry(series,year,seq,doc_nr,project,client,total_eur,payment_plan,project_id,offer_state,followup_status,currency,total_amount,exchange_rate_to_eur)
  values('INV',v_year,v_seq,v_nr,p.name,coalesce(o.client,p.client),
    case when v_currency='EUR' then v_amount when v_fx is not null then round(v_amount*v_fx,2) else null end,null,c.project_id,
    jsonb_build_object('source','pppp-outgoing-invoice-workflow-v1','candidate_id',c.id,'source_offer_id',v_offer_id,'source_offer_doc_nr',o.doc_nr,
      'source_milestone_index',v_index,'milestone_label',v_label,'milestone_pct',v_pct,'human_invoice_approved',true,'approved_by',v_actor,
      'approved_at',now(),'human_send_required',true,'invoice_status','draft_ready'),'open',v_currency,v_amount,v_fx)
  returning id into v_registry_id;

  update public.invoice_candidates set status='approved',canonical_invoice_out_id=v_invoice_id,reviewed_at=now(),updated_at=now() where id=c.id;
  update public.tasks set status='mbyllur',done_at=coalesce(done_at,now())
  where source='outgoing_invoice_review' and source_ref=c.candidate_key and lower(coalesce(status,'')) not in ('kryer','done','mbyllur','closed');
  insert into public.tasks(project_id,title,detail,due_date,priority,status,source,category,source_ref)
  values(c.project_id,'Shqyrto dhe dërgo faturën · '||v_nr,
    'Fatura '||v_nr||' është krijuar nga milestone-i i aprovuar: '||v_label||'. Shuma: '||v_amount::text||' '||v_currency||'.\n\nHuman gate: kontrollo dokumentin final/PDF-në, të dhënat e klientit dhe kushtet para dërgimit. PPPP nuk e dërgon automatikisht.',
    current_date,'larte','hapur','outgoing_invoice_final_review_auto','finance','invoice:'||v_invoice_id::text)
  on conflict(source,source_ref) do update set title=excluded.title,detail=excluded.detail,due_date=excluded.due_date,priority=excluded.priority,status='hapur',done_at=null;
  return jsonb_build_object('ok',true,'status','approved','invoice_id',v_invoice_id,'registry_id',v_registry_id,'invoice_nr',v_nr,'amount',v_amount,'currency',v_currency,'human_send_required',true);
end;
$_$;


ALTER FUNCTION public.pppp_approve_outgoing_invoice_candidate_v1(p_candidate_id uuid) OWNER TO postgres;

--
-- Name: pppp_approve_supplier_offer_candidate_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_approve_supplier_offer_candidate_v1(p_candidate_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  c public.supplier_offer_candidates%rowtype;
  v_offer public.offers%rowtype;
  v_currency text;
  v_price numeric;
  v_unit_price numeric;
  v_pricing_unit text;
  v_total numeric;
  v_qty numeric;
  v_zinc numeric;
  v_transport numeric;
  v_delivery integer;
  v_validity integer;
  v_existing uuid;
  v_received_at timestamptz;
begin
  if not public.can_write() then raise exception 'Write permission required' using errcode='42501'; end if;
  select * into c from public.supplier_offer_candidates where id=p_candidate_id for update;
  if not found then raise exception 'Supplier offer candidate not found'; end if;
  if c.status='approved' and c.canonical_offer_id is not null then
    return jsonb_build_object('ok',true,'status','already_approved','offer_id',c.canonical_offer_id);
  end if;
  if c.status<>'review' then raise exception 'Candidate is not in review state'; end if;

  v_currency=upper(btrim(coalesce(c.extracted->>'currency','')));
  v_price=nullif(c.extracted->>'price_kg','')::numeric;
  v_unit_price=nullif(c.extracted->>'unit_price','')::numeric;
  v_pricing_unit=lower(btrim(coalesce(c.extracted->>'pricing_unit','')));
  v_total=nullif(c.extracted->>'total_amount','')::numeric;
  v_qty=nullif(c.extracted->>'qty_kg','')::numeric;
  v_zinc=coalesce(nullif(c.extracted->>'zinc_kg','')::numeric,nullif(c.extracted->>'zinc_eur_kg','')::numeric);
  v_transport=nullif(c.extracted->>'transport_eur','')::numeric;
  v_delivery=nullif(c.extracted->>'delivery_weeks','')::numeric::integer;
  v_validity=nullif(c.extracted->>'validity_days','')::numeric::integer;

  if coalesce(v_currency,'')='' then raise exception 'Currency must be reviewed before approval'; end if;
  if coalesce(v_price,0)<=0 and coalesce(v_unit_price,0)<=0 and coalesce(v_total,0)<=0 then
    raise exception 'A reviewed commercial unit price, kg price, or total is required before approval';
  end if;
  if coalesce(v_price,0)>0 then v_pricing_unit='kg';
  elsif coalesce(v_unit_price,0)>0 and coalesce(v_pricing_unit,'')='' then v_pricing_unit='unit';
  elsif coalesce(v_pricing_unit,'')='' then v_pricing_unit='total'; end if;

  select o.id into v_existing
  from public.offers o
  where o.project_id=c.project_id
    and lower(btrim(coalesce(o.supplier,'')))=lower(btrim(coalesce(c.supplier_name,c.supplier_email,'')))
    and coalesce(o.raw_text,'')<>''
    and o.raw_text=coalesce(c.raw_text,'')
  order by o.created_at desc limit 1;

  if v_existing is null then
    insert into public.offers(
      project_id,supplier,price_kg,unit_price,total_eur,delivery_weeks,incoterms,cert,notes,origin,
      zinc_kg,transport_eur,qty_kg,currency,pricing_unit,payment_terms,validity_days,
      offer_ref,contact_person,raw_text,total_amount,exchange_rate_to_eur
    ) values (
      c.project_id,coalesce(nullif(c.supplier_name,''),c.supplier_email),v_price,v_unit_price,
      case when v_currency='EUR' then v_total else nullif(c.extracted->>'total_eur','')::numeric end,
      v_delivery,nullif(c.extracted->>'incoterms',''),nullif(c.extracted->>'cert',''),
      'Approved from PPPP review candidate '||c.id::text,nullif(c.extracted->>'origin',''),
      v_zinc,v_transport,coalesce(v_qty,0),v_currency,v_pricing_unit,nullif(c.extracted->>'payment_terms',''),
      v_validity,nullif(c.extracted->>'offer_ref',''),c.supplier_email,c.raw_text,v_total,
      nullif(c.extracted->>'exchange_rate_to_eur','')::numeric
    ) returning * into v_offer;
    v_existing=v_offer.id;
  end if;

  update public.supplier_offer_candidates
  set status='approved',canonical_offer_id=v_existing,reviewed_at=now(),updated_at=now()
  where id=c.id;

  select e.sent_at into v_received_at
  from public.project_emails e
  where e.gmail_message_id=c.gmail_message_id
  order by e.sent_at desc limit 1;
  v_received_at=coalesce(v_received_at,now());

  if c.matched_rfq_id is not null then
    update public.rfq_log
    set status='replied',replied_at=coalesce(replied_at,v_received_at),offer_id=coalesce(offer_id,v_existing)
    where id=c.matched_rfq_id;
  end if;

  if not exists(select 1 from public.supplier_offer_candidates where project_id=c.project_id and status='review') then
    update public.tasks set status='mbyllur',done_at=coalesce(done_at,now())
    where project_id=c.project_id and source='commercial_intake_review'
      and source_ref='commercial-intake:'||c.project_id::text||':offer' and status='hapur';
  end if;

  return jsonb_build_object('ok',true,'status','approved','offer_id',v_existing,'project_id',c.project_id,'matched_rfq_id',c.matched_rfq_id);
end;
$$;


ALTER FUNCTION public.pppp_approve_supplier_offer_candidate_v1(p_candidate_id uuid) OWNER TO postgres;

--
-- Name: pppp_assistant_identity_resolver_v1(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_assistant_identity_resolver_v1(p_query text, p_limit integer DEFAULT 12) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
with inp as (
  select lower(regexp_replace(btrim(coalesce(p_query,'')),'[^[:alnum:]@._+-]+',' ','g')) as q,
         least(50,greatest(1,coalesce(p_limit,12))) as lim
), toks as (
  select tok from inp, lateral regexp_split_to_table(inp.q,'\s+') tok
  where length(tok)>=2
),
project_hits as (
  select p.id,p.name,p.client,p.ref,p.business_ref,p.status,p.pipeline_stage,p.operational_state,p.last_email_at,
         case
           when lower(coalesce(p.name,''))=(select q from inp) then 120
           when lower(coalesce(p.ref,''))=(select q from inp) then 118
           when lower(coalesce(p.business_ref,''))=(select q from inp) then 118
           when lower(coalesce(p.client,''))=(select q from inp) then 112
           else 90 + least(20,(select count(*) from toks)*4)
         end as score
  from public.projects p, inp
  where inp.q<>'' and not exists (
    select 1 from toks t
    where position(t.tok in lower(concat_ws(' ',p.name,p.client,p.ref,p.business_ref,array_to_string(p.identity_aliases,' '))))=0
  )
  order by score desc, p.updated_at desc nulls last
  limit (select lim from inp)
),
contact_hits as (
  select pc.project_id,pc.name,pc.email,pc.company,pc.role,pc.last_seen,pc.email_count,
         p.name as project_name,p.client as project_client,p.status as project_status,p.pipeline_stage,p.operational_state,
         case
           when lower(coalesce(pc.email,''))=(select q from inp) then 130
           when lower(regexp_replace(coalesce(pc.name,''),'[^[:alnum:]@._+-]+',' ','g'))=(select q from inp) then 126
           when lower(coalesce(pc.company,''))=(select q from inp) then 118
           else 108 + least(16,(select count(*) from toks)*3)
         end as score
  from public.project_contacts pc
  left join public.projects p on p.id::text=pc.project_id,
       inp
  where inp.q<>'' and coalesce(pc.status,'active')<>'archived' and not exists (
    select 1 from toks t
    where position(t.tok in lower(concat_ws(' ',pc.name,pc.email,pc.company,pc.role,p.name,p.client)))=0
  )
  order by score desc, pc.last_seen desc nulls last
  limit (select lim from inp)
),
partner_hits as (
  select pa.id as partner_id,pa.name as partner_name,pa.business_type,pa.country,pa.city,
         pc.full_name,pc.email,pc.role,pc.is_primary,
         case
           when lower(coalesce(pc.email,''))=(select q from inp) then 128
           when lower(regexp_replace(coalesce(pc.full_name,''),'[^[:alnum:]@._+-]+',' ','g'))=(select q from inp) then 124
           when lower(coalesce(pa.name,''))=(select q from inp) then 120
           else 104 + least(16,(select count(*) from toks)*3)
         end as score
  from public.partners pa
  left join public.partner_contacts pc on pc.partner_id=pa.id,
       inp
  where inp.q<>'' and not exists (
    select 1 from toks t
    where position(t.tok in lower(concat_ws(' ',pa.name,array_to_string(pa.aliases,' '),pc.full_name,pc.email,pc.email_alt,pc.role)))=0
  )
  order by score desc, pc.is_primary desc nulls last, pa.updated_at desc nulls last
  limit (select lim from inp)
),
contact_project_ids as (
  select distinct project_id from contact_hits where project_id ~* '^[0-9a-f-]{36}$'
)
select jsonb_build_object(
  'query',p_query,
  'projects',coalesce((select jsonb_agg(to_jsonb(x) order by x.score desc) from project_hits x),'[]'::jsonb),
  'project_contacts',coalesce((select jsonb_agg(to_jsonb(x) order by x.score desc) from contact_hits x),'[]'::jsonb),
  'partners',coalesce((select jsonb_agg(to_jsonb(x) order by x.score desc) from partner_hits x),'[]'::jsonb),
  'contact_project_ids',coalesce((select jsonb_agg(project_id) from contact_project_ids),'[]'::jsonb),
  'read_only',true,
  'generated_at',now()
);
$_$;


ALTER FUNCTION public.pppp_assistant_identity_resolver_v1(p_query text, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_assistant_project_context_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_assistant_project_context_v1(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with p as (
  select id,name,client,ref,business_ref,status,pipeline_stage,operational_state,last_email_at,last_activity_at,drive_folder_url,updated_at
  from public.projects where id=p_project_id
),
recent as (
  select pe.gmail_message_id,pe.gmail_thread_id,pe.from_email,pe.from_name,pe.to_emails,pe.cc_emails,pe.subject,
         left(coalesce(pe.snippet,''),5000) as snippet,pe.sent_at,pe.direction,pe.has_attachments,pe.gmail_url,
         pe.project_id,pe.suggested_project_id,pe.match_method,pe.match_confidence,pe.needs_review,
         case when pe.project_id=p_project_id then 'linked' when pe.suggested_project_id=p_project_id then 'suggested' else 'other' end as link_status
  from public.project_emails pe
  where pe.project_id=p_project_id or pe.suggested_project_id=p_project_id
  order by pe.sent_at desc
  limit 16
),
fresh as (
  select max(sent_at) as evidence_last_email_at,
         count(*) filter (where link_status='linked') as linked_count,
         count(*) filter (where link_status='suggested') as suggested_count
  from recent
),
wa as (
  select public.pppp_whatsapp_project_context_v1(p_project_id,30) as whatsapp
),
snap as (
  select coalesce(public.pppp_chatgpt_project_snapshot_v1(p_project_id,12,16,12,20),'{}'::jsonb)
         || jsonb_build_object('whatsapp',(select whatsapp from wa)) as snapshot
)
select jsonb_build_object(
  'project',(select to_jsonb(p) from p),
  'situation',public.pppp_chatgpt_project_situation_intelligence_v1(p_project_id,90),
  'snapshot',(select snapshot from snap),
  'brief',public.pppp_project_brief_v1(p_project_id),
  'recent_email_evidence',coalesce((select jsonb_agg(to_jsonb(r) order by r.sent_at desc) from recent r),'[]'::jsonb),
  'freshness',jsonb_build_object(
    'canonical_last_email_at',(select last_email_at from p),
    'evidence_last_email_at',(select evidence_last_email_at from fresh),
    'linked_recent_email_count',coalesce((select linked_count from fresh),0),
    'suggested_recent_email_count',coalesce((select suggested_count from fresh),0),
    'canonical_may_be_stale',coalesce((select evidence_last_email_at > last_email_at from fresh,p where evidence_last_email_at is not null and last_email_at is not null),false)
  ),
  'read_only',true,
  'generated_at',now()
);
$$;


ALTER FUNCTION public.pppp_assistant_project_context_v1(p_project_id uuid) OWNER TO postgres;

--
-- Name: pppp_assistant_project_resolver_v2(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_assistant_project_resolver_v2(p_query text, p_limit integer DEFAULT 8) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
with inp as (
  select lower(regexp_replace(btrim(coalesce(p_query,'')),'[^[:alnum:]@._+-]+',' ','g')) as q,
         least(20,greatest(1,coalesce(p_limit,8))) as lim
), raw_tokens as (
  select distinct regexp_replace(tok,'[^[:alnum:]]','','g') as tok
  from inp, lateral regexp_split_to_table(inp.q,'\s+') tok
), toks as (
  select tok from raw_tokens
  where length(tok)>=3
    and tok not in ('cka','çka','cfare','çfare','qka','kemi','kena','jemi','eshte','është','jane','janë','me','per','për','nga','tek','te','dhe','apo','ose','nje','një','ky','kjo','kete','këtë','atij','asaj','tani','sot','dje','ketu','këtu','duhet','dua','ma','meje','mua','na','ne','ju','si','ku','pse','kur','mbetur','lidhur','lidhje','rreth','projekt','projekti','project','email','mail','ofert','oferta','offer','angebot','rfq','dokument','document','file','furnitor','supplier','kompani','company','person','kontakt','contact','status','gjendje','analize','analiza','analysis','info','informata','informacion','trego','shiko','kontrollo','check','what','where','with','about','from','this','that','the','and','for','our','current','latest','please')
), ts as (
  select case when count(*)>0 then to_tsquery('simple', string_agg(replace(tok,'''',''),' | ')) else null end as q
  from toks
), evidence as (
  select p.id as project_id,'project'::text as source_type,p.name::text as label,p.updated_at as at,
         case when lower(coalesce(p.name,''))=(select q from inp) or lower(coalesce(p.ref,''))=(select q from inp) or lower(coalesce(p.business_ref,''))=(select q from inp) then 145 when position((select q from inp) in lower(concat_ws(' ',p.name,p.client,p.ref,p.business_ref,array_to_string(p.identity_aliases,' '))))>0 then 132 else 90 + least(30,(ts_rank_cd(to_tsvector('simple',concat_ws(' ',p.name,p.client,p.ref,p.business_ref,array_to_string(p.identity_aliases,' '))),(select q from ts))*100)::int) end as score,
         left(concat_ws(' · ',p.name,p.client,p.ref,p.business_ref),700) as excerpt
  from public.projects p, ts, inp
  where inp.q<>'' and (((select q from ts) is not null and to_tsvector('simple',concat_ws(' ',p.name,p.client,p.ref,p.business_ref,array_to_string(p.identity_aliases,' '))) @@ (select q from ts)) or position(inp.q in lower(concat_ws(' ',p.name,p.client,p.ref,p.business_ref,array_to_string(p.identity_aliases,' '))))>0)
  union all
  select p.id,'contact',coalesce(pc.name,pc.email,pc.company,'kontakt'),pc.last_seen,case when lower(coalesce(pc.email,''))=(select q from inp) then 140 when position((select q from inp) in lower(concat_ws(' ',pc.name,pc.email,pc.company,pc.role)))>0 then 128 else 92 + least(25,(ts_rank_cd(to_tsvector('simple',concat_ws(' ',pc.name,pc.email,pc.company,pc.role)),(select q from ts))*100)::int) end,left(concat_ws(' · ',pc.name,pc.company,pc.email,pc.role),700)
  from public.project_contacts pc join public.projects p on p.id::text=pc.project_id,ts,inp
  where coalesce(pc.status,'active')<>'archived' and inp.q<>'' and (((select q from ts) is not null and to_tsvector('simple',concat_ws(' ',pc.name,pc.email,pc.company,pc.role)) @@ (select q from ts)) or position(inp.q in lower(concat_ws(' ',pc.name,pc.email,pc.company,pc.role)))>0)
  union all
  select coalesce(pe.project_id,pe.suggested_project_id),'email',coalesce(pe.subject,'(pa subjekt)'),pe.sent_at,(case when pe.project_id is not null then 102 else 86 end)+case when position((select q from inp) in lower(coalesce(pe.subject,'')))>0 then 28 when position((select q from inp) in lower(coalesce(pe.snippet,'')))>0 then 16 else 0 end+least(18,(ts_rank_cd(to_tsvector('simple',concat_ws(' ',pe.subject,pe.from_name,pe.from_email,array_to_string(pe.to_emails,' '),left(coalesce(pe.snippet,''),12000))),(select q from ts))*100)::int),left(concat_ws(' · ',pe.subject,pe.from_name,pe.from_email,left(coalesce(pe.snippet,''),1100)),1600)
  from public.project_emails pe,ts,inp
  where coalesce(pe.project_id,pe.suggested_project_id) is not null and inp.q<>'' and (((select q from ts) is not null and to_tsvector('simple',concat_ws(' ',pe.subject,pe.from_name,pe.from_email,array_to_string(pe.to_emails,' '),left(coalesce(pe.snippet,''),12000))) @@ (select q from ts)) or position(inp.q in lower(concat_ws(' ',pe.subject,pe.from_name,pe.from_email,left(coalesce(pe.snippet,''),12000))))>0)
  union all
  select t.project_id,'task',coalesce(t.title,'task'),t.created_at,95+case when position((select q from inp) in lower(concat_ws(' ',t.title,t.detail,t.contact_email,t.source_ref)))>0 then 20 else 0 end+least(15,(ts_rank_cd(to_tsvector('simple',concat_ws(' ',t.title,t.detail,t.contact_email,t.source_ref)),(select q from ts))*100)::int),left(concat_ws(' · ',t.title,t.detail,t.contact_email),1200)
  from public.tasks t,ts,inp
  where t.project_id is not null and inp.q<>'' and (((select q from ts) is not null and to_tsvector('simple',concat_ws(' ',t.title,t.detail,t.contact_email,t.source_ref)) @@ (select q from ts)) or position(inp.q in lower(concat_ws(' ',t.title,t.detail,t.contact_email,t.source_ref)))>0)
  union all
  select r.project_id,'rfq',coalesce(r.subject,r.supplier_name,'RFQ'),coalesce(r.sent_at,r.created_at),103+case when position((select q from inp) in lower(concat_ws(' ',r.project_name,r.supplier_name,r.supplier_email,r.subject,r.body,r.notes)))>0 then 22 else 0 end+least(15,(ts_rank_cd(to_tsvector('simple',concat_ws(' ',r.project_name,r.supplier_name,r.supplier_email,r.subject,left(coalesce(r.body,''),10000),r.notes)),(select q from ts))*100)::int),left(concat_ws(' · ',r.supplier_name,r.subject,left(coalesce(r.body,''),900)),1300)
  from public.rfq_log r,ts,inp
  where r.project_id is not null and inp.q<>'' and (((select q from ts) is not null and to_tsvector('simple',concat_ws(' ',r.project_name,r.supplier_name,r.supplier_email,r.subject,left(coalesce(r.body,''),10000),r.notes)) @@ (select q from ts)) or position(inp.q in lower(concat_ws(' ',r.project_name,r.supplier_name,r.supplier_email,r.subject,left(coalesce(r.body,''),10000),r.notes)))>0)
  union all
  select d.project_id,'document',coalesce(d.doc_nr,d.project,'document'),d.created_at,108+case when position((select q from inp) in lower(concat_ws(' ',d.doc_nr,d.project,d.client,left(coalesce(d.offer_state::text,''),8000))))>0 then 22 else 0 end+least(12,(ts_rank_cd(to_tsvector('simple',concat_ws(' ',d.doc_nr,d.project,d.client,left(coalesce(d.offer_state::text,''),8000))),(select q from ts))*100)::int),left(concat_ws(' · ',d.doc_nr,d.project,d.client,d.series,d.total_amount,d.currency),900)
  from public.documents_registry d,ts,inp
  where d.project_id is not null and inp.q<>'' and (((select q from ts) is not null and to_tsvector('simple',concat_ws(' ',d.doc_nr,d.project,d.client,left(coalesce(d.offer_state::text,''),8000))) @@ (select q from ts)) or position(inp.q in lower(concat_ws(' ',d.doc_nr,d.project,d.client,left(coalesce(d.offer_state::text,''),8000))))>0)
  union all
  select pal.project_id::uuid,'attachment',coalesce(pal.attachment_name,'attachment'),coalesce(pal.analyzed_at,pal.created_at),106+case when position((select q from inp) in lower(concat_ws(' ',pal.attachment_name,left(coalesce(pal.extracted_text,''),8000),left(coalesce(pal.extracted_data::text,''),5000))))>0 then 24 else 0 end+least(12,(ts_rank_cd(to_tsvector('simple',concat_ws(' ',pal.attachment_name,left(coalesce(pal.extracted_text,''),8000),left(coalesce(pal.extracted_data::text,''),5000))),(select q from ts))*100)::int),left(concat_ws(' · ',pal.attachment_name,left(coalesce(pal.extracted_text,''),900)),1300)
  from public.project_attachment_links pal,ts,inp
  where pal.project_id ~* '^[0-9a-f-]{36}$' and inp.q<>'' and (((select q from ts) is not null and to_tsvector('simple',concat_ws(' ',pal.attachment_name,left(coalesce(pal.extracted_text,''),8000),left(coalesce(pal.extracted_data::text,''),5000))) @@ (select q from ts)) or position(inp.q in lower(concat_ws(' ',pal.attachment_name,left(coalesce(pal.extracted_text,''),8000),left(coalesce(pal.extracted_data::text,''),5000))))>0)
  union all
  select pr.project_id,'requirement',coalesce(pr.source_name,pr.requirement_key,'requirement'),coalesce(pr.last_seen,pr.first_seen),100+case when position((select q from inp) in lower(concat_ws(' ',pr.requirement_key,pr.category,pr.value_text,pr.source_name,left(coalesce(pr.value_json::text,''),5000))))>0 then 18 else 0 end+least(12,(ts_rank_cd(to_tsvector('simple',concat_ws(' ',pr.requirement_key,pr.category,pr.value_text,pr.source_name,left(coalesce(pr.value_json::text,''),5000))),(select q from ts))*100)::int),left(concat_ws(' · ',pr.requirement_key,pr.category,pr.value_text,pr.source_name),1200)
  from public.project_requirements pr,ts,inp
  where pr.project_id is not null and inp.q<>'' and (((select q from ts) is not null and to_tsvector('simple',concat_ws(' ',pr.requirement_key,pr.category,pr.value_text,pr.source_name,left(coalesce(pr.value_json::text,''),5000))) @@ (select q from ts)) or position(inp.q in lower(concat_ws(' ',pr.requirement_key,pr.category,pr.value_text,pr.source_name,left(coalesce(pr.value_json::text,''),5000))))>0)
  union all
  select f.project_id,'context_fact',coalesce(f.subject,f.fact_key,'fact'),f.updated_at,98+case when position((select q from inp) in lower(concat_ws(' ',f.category,f.subject,f.fact_key,f.source_ref,left(coalesce(f.value::text,''),7000))))>0 then 18 else 0 end+least(12,(ts_rank_cd(to_tsvector('simple',concat_ws(' ',f.category,f.subject,f.fact_key,f.source_ref,left(coalesce(f.value::text,''),7000))),(select q from ts))*100)::int),left(concat_ws(' · ',f.subject,f.fact_key,left(coalesce(f.value::text,''),900)),1300)
  from public.pppp_project_context_facts f,ts,inp
  where f.project_id is not null and coalesce(f.fact_status,'active')<>'superseded' and inp.q<>'' and (((select q from ts) is not null and to_tsvector('simple',concat_ws(' ',f.category,f.subject,f.fact_key,f.source_ref,left(coalesce(f.value::text,''),7000))) @@ (select q from ts)) or position(inp.q in lower(concat_ws(' ',f.category,f.subject,f.fact_key,f.source_ref,left(coalesce(f.value::text,''),7000))))>0)
  union all
  select pa.project_id::uuid,'analysis','project analysis',pa.created_at,84+least(16,(ts_rank_cd(to_tsvector('simple',left(coalesce(pa.analysis::text,''),10000)),(select q from ts))*100)::int),left(coalesce(pa.analysis::text,''),1300)
  from public.project_analyses pa,ts,inp
  where pa.project_id ~* '^[0-9a-f-]{36}$' and inp.q<>'' and (select q from ts) is not null and to_tsvector('simple',left(coalesce(pa.analysis::text,''),10000)) @@ (select q from ts)
), ranked_evidence as (
  select e.*,row_number() over(partition by e.project_id order by e.score desc,e.at desc nulls last) rn from evidence e where e.project_id is not null
), agg as (
  select e.project_id,max(e.score)+least(24,(count(*)-1)*3)::int as relevance_score,count(*)::int as evidence_count,max(e.at) as latest_evidence_at,jsonb_agg(jsonb_build_object('source_type',e.source_type,'label',e.label,'at',e.at,'score',e.score,'excerpt',e.excerpt) order by e.score desc,e.at desc nulls last) filter(where e.rn<=8) as evidence
  from ranked_evidence e group by e.project_id
), candidates as (
  select p.id,p.name,p.client,p.ref,p.business_ref,p.status,p.pipeline_stage,p.operational_state,p.last_email_at,p.last_activity_at,a.relevance_score,a.evidence_count,a.latest_evidence_at,a.evidence
  from agg a join public.projects p on p.id=a.project_id order by a.relevance_score desc,a.latest_evidence_at desc nulls last limit (select lim from inp)
)
select jsonb_build_object('query',p_query,'meaningful_tokens',coalesce((select jsonb_agg(tok order by tok) from toks),'[]'::jsonb),'projects',coalesce((select jsonb_agg(to_jsonb(c) order by c.relevance_score desc,c.latest_evidence_at desc nulls last) from candidates c),'[]'::jsonb),'read_only',true,'generated_at',now());
$_$;


ALTER FUNCTION public.pppp_assistant_project_resolver_v2(p_query text, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_automated_task_event_precedence(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_automated_task_event_precedence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_sent_at timestamptz;
  v_source_at timestamptz;
  v_newer_client_incoming timestamptz;
  v_supplier_quote_at timestamptz;
  v_supplier_name text;
  v_text text;
  v_stage text;
  v_deadline date;
  v_existing uuid;
  v_technical_subject text;
  v_latest_doc text;
  v_latest_doc_created timestamptz;
  v_latest_doc_sent timestamptz;
  v_draft_pending boolean := false;
  v_operational_state text;
  v_operational_state_at timestamptz;
  v_client_after_state timestamptz;
begin
  if new.project_id is null
     or coalesce(new.source,'') not in ('email_request_auto','supplier_update_auto','project_decision_auto','dynamic_plan_auto') then
    return new;
  end if;

  if tg_op='INSERT' and new.source='project_decision_auto' and coalesce(new.source_ref,'')<>'' then
    select id into v_existing from public.tasks
    where source=new.source and source_ref=new.source_ref
    order by created_at desc limit 1;
    if v_existing is not null then
      update public.tasks set
        title=new.title,detail=new.detail,due_date=new.due_date,priority=new.priority,
        status=new.status,done_at=new.done_at,category=new.category,contact_email=new.contact_email
      where id=v_existing;
      return null;
    end if;
  end if;

  select pipeline_stage,nullif(deadline,'')::date,operational_state,operational_state_at
    into v_stage,v_deadline,v_operational_state,v_operational_state_at
  from public.projects where id=new.project_id;

  if coalesce(v_operational_state,'')='wait_for_client' then
    select max(e.sent_at) into v_client_after_state
    from public.project_emails e
    where e.project_id=new.project_id
      and lower(coalesce(e.direction,''))='incoming'
      and e.sent_at>coalesce(v_operational_state_at,'1970-01-01'::timestamptz)
      and not exists (
        select 1 from public.rfq_log r
        where r.project_id=new.project_id
          and lower(coalesce(r.supplier_email,''))=lower(coalesce(e.from_email,''))
      );
    if v_client_after_state is null then
      new.status:='mbyllur';
      new.done_at:=coalesce(new.done_at,now());
      new.detail:=concat_ws(E'\n',nullif(new.detail,''),'PPPP: projekti është në gjendjen kanonike wait_for_client; ky veprim automatik nuk kërkohet derisa të vijë përgjigje e re nga klienti.');
      return new;
    else
      update public.projects set operational_state='action_required', operational_state_at=v_client_after_state, operational_state_source='client_reply_auto', updated_at=now()
      where id=new.project_id;
      v_operational_state:='action_required';
    end if;
  end if;

  if coalesce(v_operational_state,'')='execution' and coalesce(new.source,'')='project_decision_auto' then
    new.status:='mbyllur';
    new.done_at:=coalesce(new.done_at,now());
    new.detail:=concat_ws(E'\n',nullif(new.detail,''),'PPPP: projekti është në ekzekutim; task-et automatike të fazës së ofertimit/prodhuesit janë tejkaluar.');
    return new;
  end if;

  select d.doc_nr,d.created_at,
         coalesce((d.offer_state->>'installation_price_pending')::boolean,false)
         or (d.revenue_breakdown ? 'installation' and d.revenue_breakdown->'installation'='null'::jsonb)
    into v_latest_doc,v_latest_doc_created,v_draft_pending
  from public.documents_registry d
  where d.project_id=new.project_id and d.series='QUO'
  order by d.created_at desc limit 1;

  if v_latest_doc is not null then
    select max(e.sent_at) into v_latest_doc_sent
    from public.project_emails e
    where e.project_id=new.project_id
      and lower(coalesce(e.direction,''))='outgoing'
      and lower(coalesce(e.subject,'')||' '||coalesce(e.snippet,'')) like '%'||lower(v_latest_doc)||'%';
  end if;

  select max(e.sent_at)
    into v_sent_at
  from public.documents_registry d
  join public.project_emails e
    on e.project_id = d.project_id
   and lower(coalesce(e.direction,'')) = 'outgoing'
   and coalesce(d.doc_nr,'') <> ''
   and lower(coalesce(e.subject,'') || ' ' || coalesce(e.snippet,'')) like '%' || lower(d.doc_nr) || '%'
  where d.project_id = new.project_id and d.series='QUO';

  select e.sent_at,coalesce(r.supplier_name,e.from_name,e.from_email)
    into v_supplier_quote_at,v_supplier_name
  from public.project_emails e
  join public.rfq_log r
    on r.project_id=new.project_id
   and lower(coalesce(r.supplier_email,''))=lower(coalesce(e.from_email,''))
   and r.sent_at is not null
   and r.sent_at <= coalesce(e.sent_at,e.created_at,now())
  where e.project_id=new.project_id
    and lower(coalesce(e.direction,''))='incoming'
    and (coalesce(e.has_attachments,false) or lower(coalesce(e.subject,'')||' '||coalesce(e.snippet,'')) ~ '(ofert|ponud|quote|angebot|preis)')
  order by e.sent_at desc limit 1;

  if coalesce(new.source,'') in ('project_decision_auto','email_request_auto')
     and v_latest_doc is not null
     and v_latest_doc_sent is null
     and not v_draft_pending
     and (v_supplier_quote_at is null or v_latest_doc_created>=v_supplier_quote_at) then
    new.title := 'Kontrollo dhe dërgo ofertën '||v_latest_doc;
    new.detail := concat_ws(E'\n','PPPP: oferta është ruajtur në projekt por nuk ka provë që është dërguar klientit. Kontrolloje dhe përdor workflow-in PDF → Email → Gmail Draft.',nullif(new.detail,''));
    new.due_date := current_date;
    new.priority := 'e larte';
    new.status := 'hapur';new.done_at := null;
    return new;
  end if;

  if coalesce(new.source,'')='project_decision_auto'
     and v_supplier_quote_at is not null
     and (v_sent_at is null or v_supplier_quote_at>v_sent_at) then
    new.title := 'Përgatit ofertën PRISTEEL — '||coalesce(v_supplier_name,'furnitori');
    new.detail := concat_ws(E'\n','PPPP: oferta/përgjigjja e furnitorit është marrë dhe projekti mund të kalojë në përgatitjen e ofertës për klientin.',nullif(new.detail,''));
    new.due_date := current_date;new.priority := 'e larte';new.status := 'hapur';new.done_at := null;
    return new;
  end if;

  if coalesce(new.source,'') in ('project_decision_auto','email_request_auto')
     and v_stage='technical_review' and v_deadline is not null
     and v_deadline <= current_date + 3 and v_sent_at is null then
    select subject into v_technical_subject
    from public.project_emails
    where project_id=new.project_id and lower(coalesce(direction,''))='incoming'
      and lower(coalesce(subject,'')||' '||coalesce(snippet,'')) ~ '(exc[0-9]|en 1090|weld|ndt|galvan|bolt|anchor|toler|technical|quality|packag|documentation|requirement)'
    order by sent_at desc limit 1;
    new.title := 'Finalizo çështjet teknike para ofertës';
    new.detail := concat_ws(E'\n','PPPP: afati i ofertës është '||to_char(v_deadline,'DD.MM.YYYY')||'.',case when v_technical_subject is not null then 'Kërkesa teknike më e fundit: '||v_technical_subject else null end,'Kontrollo dhe mbyll: EXC/EN 1090, tolerancat, certifikatat EN 10204 3.1, galvanizimin, profilet/pllakat, bulonat/ankerat, saldimin/NDT, R2, paketimin, gjuhën e dokumentacionit dhe rendin e përparësisë së kërkesave.',nullif(new.detail,''));
    new.due_date := least(v_deadline,current_date);new.priority := 'e larte';new.status := 'hapur';new.done_at := null;
    return new;
  end if;

  v_text := lower(coalesce(new.title,'') || ' ' || coalesce(new.detail,''));
  if v_text !~ '(plan[[:space:]]*dinamik|dinamik|ponud|ofert|monta|plastifik|cij|cmim|price|rok[[:space:]]*realiz|rekapitul)' then return new; end if;
  if v_sent_at is null then return new; end if;

  select max(e.sent_at) into v_newer_client_incoming
  from public.project_emails e
  where e.project_id = new.project_id and lower(coalesce(e.direction,'')) = 'incoming' and e.sent_at > v_sent_at
    and not exists (select 1 from public.rfq_log r where r.project_id=new.project_id and lower(coalesce(r.supplier_email,''))=lower(coalesce(e.from_email,'')));
  if v_newer_client_incoming is not null then return new; end if;

  if coalesce(new.source,'') = 'project_decision_auto' then
    new.status := 'mbyllur';new.done_at := coalesce(new.done_at, now());
    new.detail := concat_ws(E'\n', nullif(new.detail,''), 'PPPP: ky veprim është tejkaluar nga oferta PRISTEEL e dërguar; projekti është në pritje të përgjigjes së klientit.');return new;
  end if;

  if coalesce(new.source_ref,'') <> '' then select max(e.sent_at) into v_source_at from public.project_emails e where e.project_id = new.project_id and e.gmail_message_id = new.source_ref; end if;
  v_source_at := coalesce(v_source_at,new.created_at,now());
  if v_source_at <= v_sent_at then new.status := 'mbyllur';new.done_at := coalesce(new.done_at, now());new.detail := concat_ws(E'\n', nullif(new.detail,''), 'PPPP: ky veprim është tejkaluar nga oferta PRISTEEL e dërguar.');end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_automated_task_event_precedence() OWNER TO postgres;

--
-- Name: pppp_automation_control_health_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_automation_control_health_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if coalesce(auth.role(),'')<>'service_role' and not public.is_admin() then
    raise exception 'forbidden' using errcode='42501';
  end if;

  return jsonb_build_object(
    'generated_at',now(),
    'managed_http',jsonb_build_object(
      'queued',(select count(*) from public.pppp_automation_http_runs where status='queued'),
      'retry_wait',(select count(*) from public.pppp_automation_http_runs where status='retry_wait'),
      'failed_24h',(select count(*) from public.pppp_automation_http_runs where status='failed' and updated_at>=now()-interval '24 hours'),
      'succeeded_24h',(select count(*) from public.pppp_automation_http_runs where status='succeeded' and updated_at>=now()-interval '24 hours'),
      'latest_failed_at',(select max(updated_at) from public.pppp_automation_http_runs where status='failed')
    ),
    'semantic_local',jsonb_build_object(
      'ready',public.semantic_worker_ready_v1(interval '15 minutes'),
      'active_workers',(select count(*) from public.semantic_worker_keys where is_active),
      'fresh_workers',(select count(*) from public.semantic_worker_keys where is_active and last_used_at>=now()-interval '15 minutes'),
      'pending_jobs',(select count(*) from public.semantic_ai_jobs where state='pending'),
      'claimed_jobs',(select count(*) from public.semantic_ai_jobs where state='claimed'),
      'oldest_pending_at',(select min(created_at) from public.semantic_ai_jobs where state='pending'),
      'cron_enabled',exists(select 1 from cron.job where jobname='semantic-local-orchestrator-5m' and active)
    ),
    'open_failure_tasks',(
      select count(*) from public.tasks
      where source='automation_failure' and lower(coalesce(status,'')) not in ('kryer','mbyllur','done')
    )
  );
end;
$$;


ALTER FUNCTION public.pppp_automation_control_health_v1() OWNER TO postgres;

--
-- Name: pppp_automation_health_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_automation_health_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
begin
  if coalesce(auth.role(),'') <> 'service_role' and not coalesce(public.is_admin(),false) then
    raise exception 'forbidden' using errcode='42501';
  end if;
  return private.pppp_automation_health_internal()||
    jsonb_build_object('operating',private.pppp_automation_operating_health_v1());
end;
$$;


ALTER FUNCTION public.pppp_automation_health_v1() OWNER TO postgres;

--
-- Name: pppp_automation_success_closes_failure_alerts_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_automation_success_closes_failure_alerts_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.status <> 'succeeded' or btrim(coalesce(new.automation_key,'')) = '' then
    return new;
  end if;

  if exists(
    select 1
    from public.pppp_automation_http_runs f
    where f.automation_key = new.automation_key
      and f.status = 'failed'
      and f.updated_at > new.updated_at
  ) then
    return new;
  end if;

  update public.tasks t
     set status = 'kryer',
         done_at = coalesce(t.done_at,new.updated_at,now()),
         detail = case
           when position('PPPP: automation-recovered —' in coalesce(t.detail,'')) > 0 then t.detail
           else concat_ws(E'\n',nullif(t.detail,''),
             'PPPP: automation-recovered — një ekzekutim i mëvonshëm përfundoi me sukses; alerti historik u mbyll automatikisht.')
         end
   where t.source = 'automation_failure'
     and t.title = 'Automation failure · ' || new.automation_key
     and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed')
     and t.created_at <= new.updated_at;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_automation_success_closes_failure_alerts_v1() OWNER TO postgres;

--
-- Name: FUNCTION pppp_automation_success_closes_failure_alerts_v1(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_automation_success_closes_failure_alerts_v1() IS 'Closes stale per-run automation failure tasks when the same managed automation later succeeds.';


--
-- Name: pppp_automation_watchdog_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_automation_watchdog_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'cron'
    AS $$
declare
  r record;
  v_http jsonb;
  v_opened integer:=0;
  v_closed integer:=0;
  v_rows integer:=0;
  v_ref text;
begin
  v_http:=public.pppp_reconcile_automation_http_v1(500);

  for r in
    select j.jobname,x.status,x.start_time
    from cron.job j
    left join lateral (
      select status,start_time
      from cron.job_run_details d
      where d.jobid=j.jobid
      order by start_time desc
      limit 1
    ) x on true
    where j.active
      and x.status is not null
      and (
        x.status not in ('succeeded','running')
        or (x.status='running' and x.start_time < now()-interval '15 minutes')
      )
  loop
    v_ref:='AUTOMATION:cron:'||r.jobname;
    insert into public.tasks(title,detail,due_date,priority,status,source,category,source_ref)
    values(
      'Automation failure · cron '||r.jobname,
      case when r.status='running'
        then 'Latest pg_cron run appears stuck: running since '||coalesce(r.start_time::text,'unknown')
        else 'Latest pg_cron run is '||coalesce(r.status,'unknown')||' at '||coalesce(r.start_time::text,'unknown')
      end,
      current_date,'larte','hapur','automation_failure','intern',v_ref
    )
    on conflict(source,source_ref) do update
      set title=excluded.title,detail=excluded.detail,due_date=current_date,priority='larte',status='hapur',done_at=null;
    v_opened:=v_opened+1;
  end loop;

  update public.tasks t
     set status='kryer',
         done_at=coalesce(done_at,now()),
         detail=coalesce(detail,'')||E'\nRecovered automatically: latest cron run is healthy.'
   where t.source='automation_failure'
     and t.source_ref like 'AUTOMATION:cron:%'
     and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done')
     and exists(
       select 1
       from cron.job j
       left join lateral(
         select status,start_time
         from cron.job_run_details d
         where d.jobid=j.jobid
         order by start_time desc
         limit 1
       ) x on true
       where 'AUTOMATION:cron:'||j.jobname=t.source_ref
         and j.active
         and (
           x.status='succeeded'
           or (x.status='running' and x.start_time >= now()-interval '15 minutes')
         )
     );
  get diagnostics v_rows=row_count;
  v_closed:=v_closed+v_rows;

  for r in
    select worker_id,last_seen_at
    from public.local_ocr_workers
    where enabled and (last_seen_at is null or last_seen_at<now()-interval '15 minutes')
  loop
    v_ref:='AUTOMATION:worker:ocr:'||r.worker_id;
    insert into public.tasks(title,detail,due_date,priority,status,source,category,source_ref)
    values('Automation worker stale · OCR '||r.worker_id,'OCR worker heartbeat is older than 15 minutes. Last seen: '||coalesce(r.last_seen_at::text,'never'),current_date,'larte','hapur','automation_failure','intern',v_ref)
    on conflict(source,source_ref) do update set detail=excluded.detail,due_date=current_date,priority='larte',status='hapur',done_at=null;
    v_opened:=v_opened+1;
  end loop;

  update public.tasks t
     set status='kryer',done_at=coalesce(done_at,now()),detail=coalesce(detail,'')||E'\nRecovered automatically: OCR worker heartbeat is healthy.'
   where t.source='automation_failure'
     and t.source_ref like 'AUTOMATION:worker:ocr:%'
     and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done')
     and exists(
       select 1 from public.local_ocr_workers w
       where t.source_ref='AUTOMATION:worker:ocr:'||w.worker_id
         and w.enabled
         and w.last_seen_at>=now()-interval '15 minutes'
     );
  get diagnostics v_rows=row_count;
  v_closed:=v_closed+v_rows;

  for r in
    select label,last_used_at
    from public.semantic_worker_keys
    where is_active and (last_used_at is null or last_used_at<now()-interval '15 minutes')
  loop
    v_ref:='AUTOMATION:worker:semantic:'||r.label;
    insert into public.tasks(title,detail,due_date,priority,status,source,category,source_ref)
    values('Automation worker stale · Semantic AI','Semantic worker heartbeat is older than 15 minutes. Worker: '||r.label||'. Last used: '||coalesce(r.last_used_at::text,'never'),current_date,'larte','hapur','automation_failure','intern',v_ref)
    on conflict(source,source_ref) do update set detail=excluded.detail,due_date=current_date,priority='larte',status='hapur',done_at=null;
    v_opened:=v_opened+1;
  end loop;

  update public.tasks t
     set status='kryer',done_at=coalesce(done_at,now()),detail=coalesce(detail,'')||E'\nRecovered automatically: Semantic worker heartbeat is healthy.'
   where t.source='automation_failure'
     and t.source_ref like 'AUTOMATION:worker:semantic:%'
     and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done')
     and exists(
       select 1 from public.semantic_worker_keys w
       where t.source_ref='AUTOMATION:worker:semantic:'||w.label
         and w.is_active
         and w.last_used_at>=now()-interval '15 minutes'
     );
  get diagnostics v_rows=row_count;
  v_closed:=v_closed+v_rows;

  return jsonb_build_object(
    'http',v_http,
    'alerts_opened_or_refreshed',v_opened,
    'alerts_closed',v_closed,
    'generated_at',now()
  );
end;
$$;


ALTER FUNCTION public.pppp_automation_watchdog_v1() OWNER TO postgres;

--
-- Name: pppp_canonical_task_detail_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_canonical_task_detail_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_options text;
  v_plan_week text;
  v_plan_name text;
  v_draft text;
begin
  if new.project_id is null or new.title not ilike '%Zgjidh scope-in e montimit%' then return new; end if;

  select string_agg('• '||supplier||': '||trim(to_char(rate,'FM999990.00'))||' EUR/kg — '||scope_label,E'\n' order by supplier)
  into v_options
  from (
    select o.supplier,
           coalesce((ip.elem->>'price_neg')::numeric,(ip.elem->>'price_orig')::numeric,0) rate,
           case
             when ip.elem->>'scope'='assistance_only' then 'ASISTENCË '||coalesce(ip.elem->>'persons','?')||' persona / '||coalesce(ip.elem->>'days','?')||' ditë'
             when ip.elem->>'scope'='installation_unverified' then 'MONTIM · scope për verifikim'
             else coalesce(ip.elem->>'desc','Montim')
           end scope_label
    from public.offers o
    left join lateral (
      select x elem from jsonb_array_elements(coalesce(o.positions,'[]'::jsonb)) x
      where lower(coalesce(x->>'key','')) in ('install','installation') limit 1
    ) ip on true
    where o.project_id=new.project_id and ip.elem is not null
  ) q;

  select coalesce(pal.extracted_data->'dynamic_plan'->>'last_active_week',pal.extracted_data->>'last_active_week'),pal.attachment_name
  into v_plan_week,v_plan_name
  from public.project_attachment_links pal
  where pal.project_id::text=new.project_id::text and (pal.extracted_data ? 'dynamic_plan' or pal.extracted_data->>'document_type'='dynamic_plan')
  order by pal.analyzed_at desc nulls last,pal.created_at desc limit 1;

  select doc_nr into v_draft from public.documents_registry where project_id=new.project_id and series='QUO' order by created_at desc limit 1;

  new.detail := concat_ws(E'\n',
    'Vendim komercial i kërkuar para finalizimit të ofertës:',
    nullif(v_options,''),
    case when v_plan_week is not null then '• Plani dinamik: Java 0-'||v_plan_week||' · '||coalesce(v_plan_name,'') else null end,
    '• Scope-et e montimit nuk janë të barabarta; mos zgjidh vetëm nga çmimi.',
    case when v_draft is not null then '• Pas vendimit, plotëso '||v_draft||', rikalkulo totalin/marzhin dhe vetëm pastaj përgatite për dërgim.' else null end
  );
  return new;
end;
$$;


ALTER FUNCTION public.pppp_canonical_task_detail_guard() OWNER TO postgres;

--
-- Name: pppp_chatgpt_action_orchestrator_v1(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_action_orchestrator_v1(p_days integer DEFAULT 30, p_limit integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_days integer := greatest(1,least(coalesce(p_days,30),90));
  v_limit integer := greatest(1,least(coalesce(p_limit,30),60));
  v_situations jsonb := '{}'::jsonb;
  v_proposals jsonb := '[]'::jsonb;
  v_project_proposals jsonb := '[]'::jsonb;
  v_inbox_proposals jsonb := '[]'::jsonb;
  v_proposal_count integer := 0;
  v_human_gate_count integer := 0;
  v_draftable_count integer := 0;
  v_controlled_write_count integer := 0;
begin
  v_situations := public.pppp_chatgpt_situation_intelligence_v1(v_days,least(v_limit,40));

  with src as (
    select elem,
           coalesce((elem->>'portfolio_rank_score')::integer,0) as base_score,
           lower(coalesce(elem->'recommendation'->>'decision','')) as decision
    from jsonb_array_elements(coalesce(v_situations->'project_situations','[]'::jsonb)) x(elem)
    where coalesce((elem->>'attention_required')::boolean,false)
  ), shaped as (
    select jsonb_build_object(
      'proposal_id','project:'||(elem->'project'->>'id')||':'||case
        when decision='review_and_send_offer' then 'prepare_offer_review'
        when decision='prepare_client_offer' then 'prepare_offer_review'
        when decision like 'human_gate_%' then 'request_human_project_decision'
        when elem->>'situation_state'='execution_attention' then 'review_execution_blockers'
        when elem->>'situation_state'='active_work_attention' then 'review_active_work'
        else 'review_current_actions' end,
      'proposal_version',1,
      'source_situation_id',elem->>'situation_id',
      'source_situation_kind','project',
      'priority_score',least(100, greatest(1, base_score - 40 + case
        when decision='review_and_send_offer' then 25
        when decision='prepare_client_offer' then 20
        when decision like 'human_gate_%' then 25
        when elem->>'situation_state'='execution_attention' then 20
        else 10 end)),
      'action_kind',case
        when decision='review_and_send_offer' then 'prepare_offer_review'
        when decision='prepare_client_offer' then 'prepare_offer_review'
        when decision like 'human_gate_%' then 'request_human_project_decision'
        when elem->>'situation_state'='execution_attention' then 'review_execution_blockers'
        when elem->>'situation_state'='active_work_attention' then 'review_active_work'
        else 'review_current_actions' end,
      'action_label',case
        when decision='review_and_send_offer' then 'Përgatit paketën e ofertës për review'
        when decision='prepare_client_offer' then 'Përgatit ofertën për review'
        when decision like 'human_gate_%' then 'Kërko vendim njerëzor për statusin e projektit'
        when elem->>'situation_state'='execution_attention' then 'Rishiko bllokuesit e ekzekutimit'
        when elem->>'situation_state'='active_work_attention' then 'Rishiko punën aktive dhe veprimin vijues'
        else 'Rishiko veprimet aktuale të projektit' end,
      'project',jsonb_build_object(
        'project_id',elem->'project'->>'id',
        'project_name',elem->'project'->>'name',
        'client',elem->'project'->>'client',
        'operational_state',elem->'project'->>'operational_state',
        'pipeline_stage',elem->'project'->>'pipeline_stage'
      ),
      'rationale',coalesce(elem->>'summary',''),
      'recommended_decision',coalesce(elem->'recommendation','{}'::jsonb),
      'risk',coalesce(elem->'risk','{}'::jsonb),
      'open_issues',coalesce(elem->'open_issues','[]'::jsonb),
      'artifact_to_prepare',case
        when decision in ('review_and_send_offer','prepare_client_offer') then 'offer_review_packet'
        when decision like 'human_gate_%' then 'decision_brief'
        when elem->>'situation_state'='execution_attention' then 'execution_review_brief'
        else 'action_review_brief' end,
      'draft_preparation_allowed',true,
      'controlled_write_proposal_allowed',case when elem->>'situation_state' in ('execution_attention','active_work_attention','action_required') then true else false end,
      'controlled_write_action_type',case when elem->>'situation_state' in ('execution_attention','active_work_attention','action_required') then 'task' else null end,
      'approval_gates',coalesce(elem->'gates_triggered','[]'::jsonb),
      'execution_allowed',false,
      'execution_block_reason','Action Orchestrator v1 is proposal-only. External, binding, pricing, supplier-selection and disposition actions require explicit human approval.',
      'evidence',coalesce(elem->'evidence','{}'::jsonb),
      'policy',jsonb_build_object(
        'proposal_only',true,
        'no_automatic_task_creation',true,
        'no_automatic_email_send',true,
        'no_automatic_project_write',true,
        'no_automatic_supplier_selection',true,
        'no_automatic_price_or_margin_decision',true,
        'no_automatic_project_disposition',true,
        'protected_human_gates_preserved',true
      )
    ) as proposal
    from src
  )
  select coalesce(jsonb_agg(proposal order by (proposal->>'priority_score')::integer desc),'[]'::jsonb)
    into v_project_proposals
  from shaped;

  with src as (
    select elem,
      coalesce((elem->>'priority_score')::integer,0) as priority_score,
      elem->>'situation_kind' as kind
    from jsonb_array_elements(coalesce(v_situations->'inbox_situations','[]'::jsonb)) x(elem)
  ), shaped as (
    select jsonb_build_object(
      'proposal_id',(elem->>'situation_id')||':'||case kind
        when 'new_opportunity_candidate' then 'review_new_opportunity'
        when 'supplier_offer_review' then 'review_supplier_offer'
        when 'legal_collection' then 'review_legal_matter'
        when 'project_outcome_review' then 'request_project_outcome_decision'
        when 'finance_document' then 'review_finance_document'
        when 'document_review' then 'review_received_document'
        else 'review_business_item' end,
      'proposal_version',1,
      'source_situation_id',elem->>'situation_id',
      'source_situation_kind','inbox',
      'priority_score',priority_score,
      'action_kind',case kind
        when 'new_opportunity_candidate' then 'review_new_opportunity'
        when 'supplier_offer_review' then 'review_supplier_offer'
        when 'legal_collection' then 'review_legal_matter'
        when 'project_outcome_review' then 'request_project_outcome_decision'
        when 'finance_document' then 'review_finance_document'
        when 'document_review' then 'review_received_document'
        else 'review_business_item' end,
      'action_label',case kind
        when 'new_opportunity_candidate' then 'Rishiko si opportunity të re dhe përgatit intake/reply draft'
        when 'supplier_offer_review' then 'Rishiko ofertën e furnitorit pa bërë selection/commitment'
        when 'legal_collection' then 'Rishiko çështjen juridike/inkasimin'
        when 'project_outcome_review' then 'Rishiko rezultatin e projektit dhe kërko vendim njerëzor'
        when 'finance_document' then 'Rishiko dokumentin financiar për procesim'
        when 'document_review' then 'Rishiko dokumentin e pranuar'
        else 'Rishiko çështjen e biznesit' end,
      'subject',elem->>'subject',
      'counterparty',coalesce(elem->'counterparty','{}'::jsonb),
      'project_context',coalesce(elem->'project_context','{}'::jsonb),
      'rationale',elem->>'why_now',
      'artifact_to_prepare',case kind
        when 'new_opportunity_candidate' then 'opportunity_intake_and_reply_draft'
        when 'supplier_offer_review' then 'supplier_offer_review_brief'
        when 'legal_collection' then 'legal_review_brief'
        when 'project_outcome_review' then 'project_outcome_decision_brief'
        when 'finance_document' then 'finance_document_review'
        when 'document_review' then 'document_review_brief'
        else 'business_review_brief' end,
      'draft_preparation_allowed',case when kind in ('new_opportunity_candidate','legal_collection','project_outcome_review','supplier_offer_review') then true else false end,
      'controlled_write_proposal_allowed',case
        when kind='new_opportunity_candidate' then true
        when kind='supplier_offer_review' and elem->'project_context'->>'resolution_status'='resolved' then true
        else false end,
      'controlled_write_action_type',case
        when kind='new_opportunity_candidate' then 'create_project'
        when kind='supplier_offer_review' and elem->'project_context'->>'resolution_status'='resolved' then 'supplier_offer'
        else null end,
      'approval_gates',case
        when kind='project_outcome_review' then jsonb_build_array('project_won_or_lost_decision')
        when kind='new_opportunity_candidate' then jsonb_build_array('external_email_send')
        when kind='supplier_offer_review' then jsonb_build_array('supplier_selection_or_commitment')
        when elem->>'protected_gate' is not null then jsonb_build_array(elem->>'protected_gate')
        else '[]'::jsonb end,
      'execution_allowed',false,
      'execution_block_reason',case
        when kind='new_opportunity_candidate' then 'May prepare intake and reply draft, but project creation and any external reply require explicit approval.'
        when kind='supplier_offer_review' then 'Offer may be reviewed; supplier selection or commitment is never automatic.'
        when kind='project_outcome_review' then 'Won/lost/disposition is a protected human decision.'
        else 'Action Orchestrator v1 is proposal-only.' end,
      'evidence',coalesce(elem->'evidence','{}'::jsonb),
      'policy',jsonb_build_object(
        'proposal_only',true,
        'no_automatic_task_creation',true,
        'no_automatic_email_send',true,
        'no_automatic_project_write',true,
        'no_automatic_supplier_selection',true,
        'no_automatic_price_or_margin_decision',true,
        'no_automatic_project_disposition',true,
        'protected_human_gates_preserved',true
      )
    ) as proposal
    from src
  )
  select coalesce(jsonb_agg(proposal order by (proposal->>'priority_score')::integer desc),'[]'::jsonb)
    into v_inbox_proposals
  from shaped;

  with all_proposals as (
    select elem from jsonb_array_elements(v_project_proposals) x(elem)
    union all
    select elem from jsonb_array_elements(v_inbox_proposals) x(elem)
  ), ranked as (
    select elem,
           row_number() over (order by (elem->>'priority_score')::integer desc, elem->>'proposal_id') as rn
    from all_proposals
  )
  select coalesce(jsonb_agg(elem order by (elem->>'priority_score')::integer desc, elem->>'proposal_id'),'[]'::jsonb)
    into v_proposals
  from ranked
  where rn<=v_limit;

  v_proposal_count := jsonb_array_length(v_proposals);

  select
    count(*) filter (where jsonb_array_length(coalesce(elem->'approval_gates','[]'::jsonb))>0)::integer,
    count(*) filter (where coalesce((elem->>'draft_preparation_allowed')::boolean,false))::integer,
    count(*) filter (where coalesce((elem->>'controlled_write_proposal_allowed')::boolean,false))::integer
  into v_human_gate_count,v_draftable_count,v_controlled_write_count
  from jsonb_array_elements(v_proposals) x(elem);

  return jsonb_build_object(
    'action_orchestrator_version',1,
    'mode','proposal_only',
    'read_only',true,
    'generated_at',now(),
    'days',v_days,
    'limit',v_limit,
    'summary',jsonb_build_object(
      'proposals',v_proposal_count,
      'proposals_with_human_gates',v_human_gate_count,
      'draft_preparation_candidates',v_draftable_count,
      'controlled_write_candidates',v_controlled_write_count,
      'executions_performed',0
    ),
    'proposals',v_proposals,
    'source_portfolio_summary',coalesce(v_situations->'portfolio_summary','{}'::jsonb),
    'policy',jsonb_build_object(
      'proposal_only',true,
      'execution_allowed',false,
      'drafts_may_be_prepared_but_not_sent',true,
      'controlled_writes_require_explicit_user_approval',true,
      'external_email_send_requires_human_approval',true,
      'supplier_selection_or_commitment_requires_human_approval',true,
      'final_selling_price_or_margin_requires_human_approval',true,
      'contract_or_purchase_order_commitment_requires_human_approval',true,
      'project_won_or_lost_decision_requires_human_approval',true,
      'unresolved_project_identity_blocks_project_specific_write',true,
      'protected_human_gates_preserved',true
    )
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_action_orchestrator_v1(p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_artifact_preparation_v1(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_artifact_preparation_v1(p_days integer DEFAULT 30, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_days integer := greatest(1,least(coalesce(p_days,30),90));
  v_limit integer := greatest(5,least(coalesce(p_limit,20),30));
  v_orchestrator jsonb := '{}'::jsonb;
  v_proposal jsonb;
  v_packs jsonb := '[]'::jsonb;
  v_pack jsonb;
  v_project_id uuid;
  v_project_resolution_status text;
  v_snapshot jsonb;
  v_project jsonb;
  v_latest_offer jsonb;
  v_latest_analysis jsonb;
  v_operator_actions jsonb;
  v_artifact_type text;
  v_action_kind text;
  v_artifact_status text;
  v_surface text;
  v_language_instruction text;
  v_requirements jsonb;
  v_non_invention jsonb;
  v_draft_allowed boolean;
  v_artifact_allowed boolean;
  v_ready_count integer := 0;
  v_review_count integer := 0;
  v_blocked_count integer := 0;
  v_draft_count integer := 0;
  v_gate_count integer := 0;
begin
  v_orchestrator := public.pppp_chatgpt_action_orchestrator_v1(v_days,v_limit);

  for v_proposal in
    select x.value
    from jsonb_array_elements(coalesce(v_orchestrator->'proposals','[]'::jsonb)) with ordinality x(value,ord)
    where x.ord <= v_limit
    order by x.ord
  loop
    v_artifact_type := nullif(v_proposal->>'artifact_to_prepare','');
    if v_artifact_type is null then
      continue;
    end if;

    v_action_kind := coalesce(v_proposal->>'action_kind','review');
    v_draft_allowed := coalesce((v_proposal->>'draft_preparation_allowed')::boolean,false);
    v_artifact_allowed := true;
    v_project_resolution_status := coalesce(v_proposal#>>'{project_context,resolution_status}','');
    v_project_id := null;

    begin
      if nullif(v_proposal#>>'{project,project_id}','') is not null then
        v_project_id := (v_proposal#>>'{project,project_id}')::uuid;
      elsif v_project_resolution_status='resolved'
            and nullif(v_proposal#>>'{project_context,recommended_project_id}','') is not null then
        v_project_id := (v_proposal#>>'{project_context,recommended_project_id}')::uuid;
      end if;
    exception when others then
      v_project_id := null;
    end;

    v_snapshot := null;
    v_project := null;
    v_latest_offer := null;
    v_latest_analysis := null;
    v_operator_actions := '[]'::jsonb;

    if v_project_id is not null then
      v_snapshot := public.pppp_chatgpt_project_snapshot_v1(v_project_id,5,5,10,5);
      v_project := v_snapshot->'project';
      v_operator_actions := coalesce(v_snapshot->'operator_actions','[]'::jsonb);

      select x.value into v_latest_offer
      from jsonb_array_elements(coalesce(v_snapshot->'documents','[]'::jsonb)) x(value)
      where nullif(x.value->>'doc_nr','') is not null
      order by nullif(x.value->>'created_at','')::timestamptz desc nulls last
      limit 1;

      select x.value->'value'->'latest_analysis' into v_latest_analysis
      from jsonb_array_elements(coalesce(v_snapshot->'context_facts','[]'::jsonb)) x(value)
      where x.value->>'fact_key'='project.memory.baseline.v1'
        and x.value->'value'->'latest_analysis' is not null
      order by nullif(x.value->>'updated_at','')::timestamptz desc nulls last
      limit 1;
    end if;

    v_surface := case v_artifact_type
      when 'opportunity_intake_and_reply_draft' then 'gmail_draft_candidate'
      when 'offer_review_packet' then 'offer_review_packet_with_email_candidate'
      when 'supplier_offer_review_brief' then 'review_packet'
      when 'project_outcome_decision_brief' then 'decision_brief'
      when 'execution_review_brief' then 'internal_execution_review'
      when 'action_review_brief' then 'internal_action_review'
      when 'finance_document_review' then 'internal_finance_review'
      when 'document_review_brief' then 'internal_document_review'
      when 'legal_review_brief' then 'internal_legal_review'
      else 'internal_review'
    end;

    v_artifact_status := case
      when v_artifact_type='offer_review_packet' and (v_project_id is null or v_latest_offer is null)
        then 'blocked_missing_context'
      when v_artifact_type in ('action_review_brief','execution_review_brief') and v_project_id is null
        then 'blocked_missing_context'
      when v_draft_allowed then 'ready_to_prepare'
      else 'review_only'
    end;

    v_language_instruction := case
      when v_latest_offer#>>'{offer_state,lang}' is not null and trim(v_latest_offer#>>'{offer_state,lang}')<>''
        then 'Use explicit offer language: '||lower(trim(v_latest_offer#>>'{offer_state,lang}'))||'. Preserve established conversation terminology.'
      when v_artifact_type='opportunity_intake_and_reply_draft'
        then 'Preserve the source conversation language from the incoming request. Do not infer language from country or company identity alone.'
      when nullif(v_proposal->>'subject','') is not null
        then 'Preserve the source conversation language. Do not infer language from country or company identity alone.'
      else 'Use the project/customer communication language only when explicitly evidenced; otherwise keep the artifact as an internal Albanian review brief.'
    end;

    v_requirements := case v_artifact_type
      when 'offer_review_packet' then jsonb_build_array(
        'Use the latest canonical client offer and current project state.',
        'Surface the exact offer reference, currency, total, recipient/contact, Incoterm, validity and explicit language when available.',
        'Flag any current missing information from the latest Project Memory analysis.',
        'Final selling price or margin remains a human decision even when the document already exists.',
        'An email body may be prepared for review, but external send is never allowed automatically.'
      )
      when 'opportunity_intake_and_reply_draft' then jsonb_build_array(
        'Extract the customer request, quantities, technical requirements, attachments mentioned and requested next step from the source message.',
        'Keep this as a new/unresolved business situation unless project identity is independently resolved.',
        'Prepare a reply candidate only; creating a project is a separate controlled-write proposal.',
        'Do not promise price, delivery, technical feasibility or capacity unless supported by canonical evidence.',
        'External email send remains human-gated.'
      )
      when 'supplier_offer_review_brief' then jsonb_build_array(
        'Summarize the supplier offer, inclusions, exclusions, commercial terms, technical constraints and missing fields evidenced by the source.',
        'Do not force the offer onto a project when Project Resolution is unresolved.',
        'Supplier ranking or review is never supplier selection or commitment.',
        'Do not create or send an RFQ or supplier reply automatically.'
      )
      when 'project_outcome_decision_brief' then jsonb_build_array(
        'Summarize the outcome evidence and the recommended project mapping confidence.',
        'Distinguish observed rejection/award evidence from the protected project won/lost decision.',
        'Do not change project disposition automatically.',
        'Present the human decision required and the evidence needed to support it.'
      )
      when 'execution_review_brief' then jsonb_build_array(
        'Use canonical execution state, Project Memory and current operator actions.',
        'Prioritize production, documentation, delivery and current execution blockers.',
        'Raw historical workflow-task backlog is transparency only and must not create urgency by itself.',
        'Do not revive superseded offer-stage actions.'
      )
      when 'action_review_brief' then jsonb_build_array(
        'Use canonical project state, Project Memory and current operator actions.',
        'State the next concrete review questions and missing evidence.',
        'Raw historical workflow-task backlog must not drive urgency.',
        'Do not execute controlled writes from the brief.'
      )
      when 'finance_document_review' then jsonb_build_array(
        'Classify and review the finance document only.',
        'Do not approve an invoice, execute payment, infer cash balance or change Finance core data.',
        'Missing due dates or uncertain values are review items, not overdue/payment conclusions.'
      )
      when 'document_review_brief' then jsonb_build_array(
        'Summarize the received document and identify the project-linking evidence actually present.',
        'Do not force unresolved documents into a project.',
        'Do not write BOM/project facts automatically from uncertain or OCR-only evidence.'
      )
      when 'legal_review_brief' then jsonb_build_array(
        'Summarize the legal/collection situation from available evidence.',
        'Separate facts from legal interpretation and missing documents.',
        'Do not send external correspondence or make legal commitments automatically.'
      )
      else jsonb_build_array(
        'Use only canonical and source-supported facts.',
        'Make missing context explicit.',
        'Prepare for human review; do not execute the underlying action.'
      )
    end;

    v_non_invention := jsonb_build_array(
      'Do not invent recipients, project assignment, price, margin, deadline, delivery date, technical feasibility, certificates or commercial terms.',
      'Do not treat a suggested project identity as assigned when assignment_allowed=false.',
      'Do not interpret a human approval gate as approved.',
      'Do not infer that an item is resolved merely because it is no longer present in an intelligence surface.'
    );

    v_pack := jsonb_strip_nulls(jsonb_build_object(
      'pack_id','artifact:'||coalesce(v_proposal->>'proposal_id',md5(v_proposal::text)),
      'proposal_id',v_proposal->>'proposal_id',
      'priority_score',v_proposal->'priority_score',
      'artifact_type',v_artifact_type,
      'artifact_status',v_artifact_status,
      'delivery_surface',v_surface,
      'source_action_kind',v_action_kind,
      'source_action_label',v_proposal->>'action_label',
      'source_rationale',left(coalesce(v_proposal->>'rationale',''),1500),
      'source_subject',v_proposal->>'subject',
      'counterparty',v_proposal->'counterparty',
      'project_resolution',v_proposal->'project_context',
      'project',coalesce(v_project,v_proposal->'project'),
      'language_instruction',v_language_instruction,
      'canonical_context',jsonb_strip_nulls(jsonb_build_object(
        'latest_client_offer',case when v_artifact_type='offer_review_packet' then v_latest_offer else null end,
        'latest_project_analysis',v_latest_analysis,
        'current_operator_actions',case when v_project_id is not null then v_operator_actions else null end,
        'project_drive_folder_url',v_project->>'drive_folder_url'
      )),
      'recommended_decision',v_proposal->'recommended_decision',
      'risk',v_proposal->'risk',
      'preparation_requirements',v_requirements,
      'facts_not_to_invent',v_non_invention,
      'human_gates',coalesce(v_proposal->'approval_gates','[]'::jsonb),
      'artifact_preparation_allowed',v_artifact_allowed,
      'draft_preparation_allowed',v_draft_allowed,
      'execution_allowed',false,
      'send_allowed',false,
      'controlled_write_allowed',false,
      'existing_engine_policy',jsonb_build_object(
        'reuse_existing_draft_engines_only_after_explicit_workflow_handoff',true,
        'followup_generator_called',false,
        'rfq_generator_called',false,
        'gmail_draft_created',false,
        'external_email_sent',false
      )
    ));

    v_packs := v_packs || jsonb_build_array(v_pack);

    if v_artifact_status='ready_to_prepare' then v_ready_count:=v_ready_count+1;
    elsif v_artifact_status='review_only' then v_review_count:=v_review_count+1;
    else v_blocked_count:=v_blocked_count+1;
    end if;
    if v_draft_allowed then v_draft_count:=v_draft_count+1; end if;
    if jsonb_array_length(coalesce(v_proposal->'approval_gates','[]'::jsonb))>0 then v_gate_count:=v_gate_count+1; end if;
  end loop;

  return jsonb_build_object(
    'artifact_preparation_version',1,
    'mode','read_only_preparation_packs',
    'generated_at',now(),
    'summary',jsonb_build_object(
      'packs',jsonb_array_length(v_packs),
      'ready_to_prepare',v_ready_count,
      'review_only',v_review_count,
      'blocked_missing_context',v_blocked_count,
      'draft_preparation_candidates',v_draft_count,
      'packs_with_human_gates',v_gate_count,
      'gmail_drafts_created',0,
      'external_emails_sent',0,
      'executions_performed',0
    ),
    'packs',v_packs,
    'source_orchestrator_summary',v_orchestrator->'summary',
    'policy',jsonb_build_object(
      'read_only',true,
      'preparation_only',true,
      'no_draft_side_effects',true,
      'no_email_send',true,
      'no_supplier_selection_or_commitment',true,
      'no_final_price_or_margin_decision',true,
      'no_contract_or_purchase_order_commitment',true,
      'no_project_won_or_lost_decision',true,
      'no_project_assignment_mutation',true,
      'no_finance_core_mutation',true,
      'protected_human_gates_preserved',true,
      'executions_performed',0
    )
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_artifact_preparation_v1(p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_bridge_manifest_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_bridge_manifest_v1() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select public.pppp_chatgpt_bridge_manifest_v30();
$$;


ALTER FUNCTION public.pppp_chatgpt_bridge_manifest_v1() OWNER TO postgres;

--
-- Name: pppp_chatgpt_bridge_manifest_v20(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_bridge_manifest_v20() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'bridge_version','chatgpt-command-v20',
    'purpose','Account-level PPPP bridge for live reads plus controlled approved writes. Project Resolution v2 provides read-only auditable project identity resolution. Situation Intelligence v1 adds read-only cross-project synthesis. Action Orchestrator v1 converts situations into ranked proposal-only next actions. Daily PriSteel Intelligence v1 provides the standard read-only current operating brief. Finance Intelligence v1 adds read-only finance synthesis over canonical invoices, expenses, bank guarantees and outgoing invoice milestones without changing Finance core calculations or executing financial actions. Supplier Intelligence v1 adds read-only supplier suitability, evidence/conflict classification, bounded RFQ-ready candidate ranking and external discovery recommendations without selecting or committing suppliers or sending email. Control Tower v1 adds a unified read-only PriSteel operating picture over Daily Intelligence and Finance Intelligence, surfacing current focus, human decisions, finance attention, new opportunities and waiting-external watchlists without executing actions. Historical Change Intelligence v1 stores bounded hourly intelligence snapshots and compares stable operating-surface identities without fabricating pre-snapshot history. Control Tower v2 combines the live operating picture with real historical delta when a valid baseline exists.',
    'read_functions',jsonb_build_array(
      'public.pppp_chatgpt_search_projects_v1(text,integer)',
      'public.pppp_chatgpt_project_snapshot_v1(uuid,integer,integer,integer,integer)',
      'public.pppp_chatgpt_priority_actions_v1(integer)',
