  v := jsonb_set(v,'{service_write_functions}',coalesce(v->'service_write_functions','[]'::jsonb) || '["public.pppp_chatgpt_register_representation_target_v1(text,jsonb,text,jsonb)"]'::jsonb,true);
  v := jsonb_set(
