--
-- Name: pppp_chatgpt_business_inbox_project_resolution_v1(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_business_inbox_project_resolution_v1(p_days integer DEFAULT 30, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with params as (
  select greatest(1,least(coalesce(p_days,30),90)) days,
         greatest(1,least(coalesce(p_limit,25),50)) lim
),
base as (
  select public.pppp_chatgpt_business_inbox_v2((select days from params),(select lim from params)) j
),
expanded as (
  select x.ord,x.item,
         public.pppp_chatgpt_project_resolution_v2('email',x.item->>'gmail_message_id','{}'::jsonb,5) resolution
  from base b cross join lateral jsonb_array_elements(coalesce(b.j->'items','[]'::jsonb)) with ordinality x(item,ord)
),
items as (
  select coalesce(jsonb_agg(e.item||jsonb_build_object('project_resolution',e.resolution) order by e.ord),'[]'::jsonb) value from expanded e
),
stats as (
  select count(*)::int returned,
         count(*) filter(where resolution->>'resolution_status'='resolved')::int resolved,
         count(*) filter(where resolution->>'resolution_status'='strong_suggestion')::int strong_suggestion,
         count(*) filter(where resolution->>'resolution_status'='ambiguous')::int ambiguous,
         count(*) filter(where resolution->>'resolution_status'='unresolved')::int unresolved
  from expanded
)
select jsonb_build_object(
  'business_inbox_project_resolution_version',1,'read_only',true,'generated_at',now(),
  'days',(select days from params),
  'policy',jsonb_build_object('business_inbox_behavior_unchanged',true,'resolver_is_enrichment_only',true,'bounded_item_limit',50,'project_assignment_allowed',false,'no_task_creation',true,'no_email_send',true,'protected_human_gates_preserved',true),
  'stats',to_jsonb(s),'items',(select value from items)
) from stats s;
$$;


ALTER FUNCTION public.pppp_chatgpt_business_inbox_project_resolution_v1(p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_business_inbox_v2(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_business_inbox_v2(p_days integer DEFAULT 30, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
with params as (
  select greatest(1, least(coalesce(p_days,30),90)) as days,
         greatest(1, least(coalesce(p_limit,50),200)) as lim
),
incoming_base as (
  select e.id,e.gmail_message_id,e.gmail_thread_id,e.sent_at,
    lower(btrim(e.from_email)) as email,nullif(btrim(e.from_name),'') as from_name,
    e.subject,e.snippet,e.has_attachments,e.match_method,e.match_confidence,e.needs_review,e.suggested_project_id,
    trim(regexp_replace(regexp_replace(lower(coalesce(e.subject,'')),'^((re|aw|fw|fwd)\s*:\s*)+','','g'),'[^a-z0-9]+',' ','g')) as subject_norm,
    regexp_replace(coalesce(e.snippet,''),E'(?is)(\\nfrom:|\\non .{0,200}wrote:|\\n_{5,}).*$','','g') as current_snippet
  from public.project_emails e,params p
  where e.project_id is null and e.direction='incoming'
    and e.sent_at>=now()-make_interval(days=>p.days)
    and nullif(btrim(coalesce(e.from_email,'')),'') is not null
    and public.pppp_email_sender_class_v1(e.from_email,e.from_name,e.subject)='external'
),threaded as (
  select i.*,coalesce(nullif(i.gmail_thread_id,''),'mail:'||i.email||':'||i.subject_norm) conversation_key
  from incoming_base i
),latest_incoming as (
  select * from (select t.*,row_number() over(partition by t.conversation_key order by t.sent_at desc nulls last,t.id desc) rn from threaded t) q where q.rn=1
),with_reply as (
  select l.*,exists(
    select 1 from public.project_emails o where o.direction='outgoing' and o.sent_at>l.sent_at and (
      (nullif(btrim(coalesce(l.gmail_thread_id,'')),'') is not null and o.gmail_thread_id=l.gmail_thread_id)
      or (length(l.subject_norm)>=12 and trim(regexp_replace(regexp_replace(lower(coalesce(o.subject,'')),'^((re|aw|fw|fwd)\s*:\s*)+','','g'),'[^a-z0-9]+',' ','g'))=l.subject_norm
        and exists(select 1 from unnest(coalesce(o.to_emails,'{}'::text[])) x(email) where lower(btrim(x.email))=l.email))
    )) later_outgoing_evidence
  from latest_incoming l
),contact_exact as (
  select lower(btrim(c.email)) email,c.contact_id,c.kind,c.company,c.person,c.role,c.country
  from public.pppp_contact_master_v1 c where nullif(btrim(coalesce(c.email,'')),'') is not null
),partner_group as (
  select lower(btrim(x.email)) email,count(distinct pc.partner_id)::int partner_count,min(pc.partner_id::text)::uuid partner_id
  from public.partner_contacts pc join public.partners p on p.id=pc.partner_id and p.stage='active'
  cross join lateral (values(pc.email),(pc.email_alt)) x(email)
  where nullif(btrim(coalesce(x.email,'')),'') is not null group by lower(btrim(x.email))
),partner_exact as (
  select g.email,g.partner_count,g.partner_id,p.name partner_name,p.relation,p.business_type,p.country
  from partner_group g left join public.partners p on p.id=g.partner_id and g.partner_count=1
),project_evidence as (
  select r.*,public.pppp_email_subject_explicit_project_v1(r.subject) explicit_project_id,
    (select case when count(distinct x.project_id)=1 then min(x.project_id::text)::uuid end from public.project_emails x
     where nullif(btrim(coalesce(r.gmail_thread_id,'')),'') is not null and x.gmail_thread_id=r.gmail_thread_id and x.project_id is not null) thread_anchor_project_id
  from with_reply r
),identity_enriched as (
  select p.*,c.contact_id,c.kind contact_kind,c.company contact_company,c.person contact_person,c.role contact_role,c.country contact_country,
    pe.partner_count,pe.partner_id,pe.partner_name,pe.relation partner_relation,pe.business_type partner_business_type,pe.country partner_country,
    case when p.thread_anchor_project_id is not null then p.thread_anchor_project_id when p.explicit_project_id is not null then p.explicit_project_id else p.suggested_project_id end evidence_project_id,
    case when p.thread_anchor_project_id is not null then 'unique_thread_anchor' when p.explicit_project_id is not null then 'explicit_subject_identity' when p.suggested_project_id is not null then 'existing_non_authoritative_suggestion' end project_evidence_method,
    case when p.thread_anchor_project_id is not null then 100 when p.explicit_project_id is not null then 98 when p.suggested_project_id is not null then least(coalesce(p.match_confidence,0),85) else 0 end project_evidence_confidence,
    (p.thread_anchor_project_id is not null or p.explicit_project_id is not null) project_context_strong,
    lower(coalesce(p.subject,'')||' '||coalesce(p.current_snippet,'')) current_text,
    extract(epoch from (now()-p.sent_at))/3600.0 age_hours
  from project_evidence p left join contact_exact c on c.email=p.email left join partner_exact pe on pe.email=p.email
),signals as (
  select i.*,
    (i.current_text ~ '(absage|nicht in die engere auswahl|not (selected|shortlisted)|unsuccessful|leider.{0,80}nicht berücks|we regret|nicht berücksichtigt|für einen anderen lieferanten entschieden|fuer einen anderen lieferanten entschieden|anderen lieferanten entschieden|decided.{0,60}another supplier)') rejection_signal,
    (i.current_text ~ '(dear valued partner|updated .{0,80}catalog|product catalogue|product portfolio|stock (list|availability)|telegram channel|newsletter|introduce our company|(introduce|introduction).{0,100}(company|supplier|manufacturer|steel)|leading (manufacturer|supplier)|what we can offer is the following|main activity is production|looking for .{0,80} let .{0,40} check)') marketing_signal,
    (i.current_text ~ '(application|bewerbung|curriculum|hiring manager|career|job opportun)') recruitment_signal,
    (i.current_text ~ '(invoice|rechnung|fatur[ëe]|payment|zahlung|receipt|swift|garancion|garanci[ëe]|bank guarantee)') finance_signal,
    (i.current_text ~ '(enforcement|përmbarim|permbarim|mahnung|legal notice|lawsuit|court|anwalt|prokurori|debt collection|cease and desist)') legal_signal,
    (i.current_text ~ '(potentially compromised credentials|suspicious activity alert|publicly exposed.{0,120}(api key|credential)|credential exposure|compromised.{0,80}(api key|credential))') security_signal,
    (i.current_text ~ '(we are interested.{0,180}(supply|participat|scope)|we do the design and manufacturing|interested for the supply|interested in (the )?supply)') capability_response_signal,
    (i.current_text ~ '(mehr.{0,100}stahlbau.{0,100}leider nicht|no (more|additional).{0,100}steel(work| construction)|nothing further.{0,100}steel(work| construction))') scope_closed_signal,
    ((lower(coalesce(i.subject,'')) ~ 'quotation' or (lower(coalesce(i.subject,'')) ~ '(^|[^a-z])(offer|angebot|ofert[ëe]?)([^a-z]|$)' and lower(coalesce(i.subject,'')) !~ '(request for quotation|rfq|k[ëe]rkes[ëe].{0,20}(p[ëe]r )?ofert|anfrage.{0,30}(angebot|preis))')) or i.current_text ~ '(attached.{0,100}(quotation|offer|angebot|ofert)|enclosed.{0,100}(quotation|offer|angebot)|ofert[aeë].{0,120}(tvsh|eur|euro)|price.{0,50}(eur|euro))') offer_signal,
    (i.current_text ~ '(please (send|provide|confirm|inform|advise|share|indicate|review|let me know)|could you|would you|can you|please let me know|do you have|do you|ju lutem|a mund|mbetem n[ëe] pritje|jemi n[ëe] pritje|k[ëe]rkojm[ëe].{0,100}(ofert|sh[ëe]rbim|konfirm|inform)|k[ëe]rkoje.{0,100}ofert|vrati.{0,120}ponud|sagledaj|pogledaj.{0,80}(ponud|ofert)|bitte (senden|teilen|bestätigen|informieren)|können sie|wir benötigen|benötigen wir)') request_signal,
    (i.current_text ~ '(thank you.{0,160}stay in touch|happy to stay in touch|reconnect once|look forward.{0,120}future|confirmed[, ]|see you[, ]|well received[, ]*.{0,40}(thanks|thank you)|received[, ]*.{0,40}thanks|as requested.{0,80}attached|sipas k[ëe]rkes[ëe]s.{0,80}bashkangjitur)') acknowledgement_signal,
    (i.current_text ~ '(need(s|ed)? more time|require(s|d)? more time|aufschub|will (send|provide|reply|respond)|will.{0,80}get in touch|will.{0,80}contact you|will.{0,80}prepare.{0,80}(quotation|offer)|we will check.{0,120}(prepare|submit)|proslijedit.{0,120}javit|kontaktirat.{0,80}(vas|te)|werde.{0,60}(senden|schicken)|by [a-z]+day|bis zum|bis [0-9]{1,2}[./-][0-9]{1,2}[./-]20[0-9]{2})') counterparty_commitment_signal,
    (i.current_text ~ '(invitation|einladung|ftes[ëe]|expo|b2b|zoom meeting|teams meeting|calendar invite|terminbestätigung)') event_signal,
    (coalesce(i.has_attachments,false) or i.current_text ~ '(attached|bashkangjitur|bashk[ëe]ngjitur|beigefügt|enclosed|anlage)') document_signal,
    (length(btrim(coalesce(i.current_snippet,'')))<24 and lower(btrim(coalesce(i.subject,''))) in ('','(pa subjekt)','the','re:','fw:','fwd:','test')) low_information_signal
  from identity_enriched i
),project_joined as (
  select s.*,p.name evidence_project_name,p.status evidence_project_status,p.pipeline_stage evidence_pipeline_stage,p.operational_state evidence_operational_state,
    ou.operator_value,ou.operator_at,
    (coalesce(s.project_evidence_confidence,0)>=85 and ou.operator_at is not null and ou.operator_at>s.sent_at
      and lower(coalesce(ou.operator_value->>'action_required','')) in ('false','0','no')) operator_superseded_no_action
  from signals s
  left join public.projects p on p.id=s.evidence_project_id
  left join lateral (
    select f.value operator_value,
      case when coalesce(f.value->>'source_sent_at','') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T'
        then (f.value->>'source_sent_at')::timestamptz else f.updated_at end operator_at
    from public.pppp_project_context_current_v f
    where f.project_id=s.evidence_project_id and f.category='operator_update'
      and f.fact_status='observed' and (
        f.evidence_status='confirmed'
        or (
          f.evidence_status='observed'
          and f.source_type='chatgpt'
          and coalesce(f.source_ref,'') like 'gmail:%'
          and lower(coalesce(f.value->>'action_required','')) in ('true','false','1','0','yes','no')
        )
      )
    order by f.updated_at desc limit 1
  ) ou on true
),classified as (
  select s.*,
    case when s.later_outgoing_evidence then 'handled' when public.pppp_email_is_automatic_reply_v1(s.subject,s.current_snippet,s.email) then 'informational' when s.operator_superseded_no_action then case when coalesce(s.operator_value->>'waiting_on','')<>'' or lower(coalesce(s.operator_value->>'workflow_state','')) like 'wait%' then 'waiting' else 'informational' end when s.project_context_strong and s.evidence_operational_state='closed' then 'informational'
      when s.security_signal then 'action_candidate' when s.legal_signal then 'action_candidate' when s.rejection_signal then 'action_candidate' when s.scope_closed_signal then 'informational' when s.marketing_signal then 'informational' when s.capability_response_signal then 'review_optional'
      when s.low_information_signal then 'informational' when s.recruitment_signal then 'review_optional' when s.event_signal then 'review_optional'
      when s.finance_signal then 'process_document' when s.offer_signal then 'action_candidate' when s.document_signal and lower(coalesce(s.subject,'')) ~ '(skic|drawing|plan|document|dokument|swift|konfirm|confirmation)' then 'process_document'
      when s.counterparty_commitment_signal and not s.request_signal then 'waiting' when s.request_signal then 'action_candidate'
      when s.acknowledgement_signal then 'informational' else 'semantic_review' end next_action_state,
    case when s.later_outgoing_evidence then 'already_replied' when public.pppp_email_is_automatic_reply_v1(s.subject,s.current_snippet,s.email) then 'automatic_reply_no_action' when s.operator_superseded_no_action then case when coalesce(s.operator_value->>'waiting_on','')<>'' or lower(coalesce(s.operator_value->>'workflow_state','')) like 'wait%' then 'wait_for_current_project_dependency' else 'operator_update_supersedes_email' end when s.project_context_strong and s.evidence_operational_state='closed' then 'project_already_terminal'
      when s.security_signal then 'review_security_alert' when s.legal_signal then 'review_legal_or_collection_matter' when s.rejection_signal then 'review_project_outcome' when s.scope_closed_signal then 'closed_scope_no_action' when s.marketing_signal then 'supplier_marketing_update' when s.capability_response_signal then 'review_supplier_capability_response'
      when s.low_information_signal then 'low_information_no_action' when s.recruitment_signal then 'recruitment_review_optional' when s.event_signal then 'event_invitation_review_optional'
      when s.finance_signal then 'process_finance_document' when s.offer_signal then 'review_received_offer' when s.document_signal and lower(coalesce(s.subject,'')) ~ '(skic|drawing|plan|document|dokument|swift|konfirm|confirmation)' then 'review_received_document'
      when s.counterparty_commitment_signal and not s.request_signal then 'wait_for_counterparty' when s.request_signal then 'review_and_reply'
      when s.acknowledgement_signal then 'no_reply_indicated' when s.document_signal then 'review_received_document' else 'semantic_review_needed' end recommended_action,
    case when s.later_outgoing_evidence then 0 when public.pppp_email_is_automatic_reply_v1(s.subject,s.current_snippet,s.email) then 0 when s.operator_superseded_no_action then 15 when s.project_context_strong and s.evidence_operational_state='closed' then 0 when s.security_signal then 97 when s.legal_signal then 98 when s.rejection_signal then 96
      when s.scope_closed_signal then 5 when s.marketing_signal then 5 when s.capability_response_signal then 40 when s.low_information_signal then 5 when s.recruitment_signal then 20 when s.event_signal then 20
      when s.finance_signal then 78 when s.offer_signal then 88 when s.document_signal and lower(coalesce(s.subject,'')) ~ '(skic|drawing|plan|document|dokument|swift|konfirm|confirmation)' then 58 when s.counterparty_commitment_signal and not s.request_signal then 35
      when s.request_signal then least(95,86+floor(least(s.age_hours,216)/48)::int) when s.acknowledgement_signal then 5 when s.document_signal then 58 else 48 end priority_score,
    case when s.rejection_signal then 'project_won_or_lost_decision' when s.request_signal and not s.marketing_signal then 'external_email_send' end protected_gate,
    case when s.partner_count=1 then 'canonical_partner_contact' when s.contact_id is not null then 'canonical_contact' else 'unresolved_external' end identity_status
  from project_joined s
),limited as (
  select * from classified order by priority_score desc,sent_at desc nulls last,id desc limit (select lim from params)
),items as (
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'email_row_id',l.id,'gmail_message_id',l.gmail_message_id,'gmail_thread_id',l.gmail_thread_id,'sent_at',l.sent_at,'age_hours',round(l.age_hours::numeric,1),
    'from_email',l.email,'from_name',l.from_name,'subject',l.subject,'current_snippet',left(coalesce(l.current_snippet,''),1200),'has_attachments',coalesce(l.has_attachments,false),
    'identity_status',l.identity_status,'identity',case when l.partner_count=1 then jsonb_strip_nulls(jsonb_build_object('partner_id',l.partner_id,'name',l.partner_name,'relation',l.partner_relation,'business_type',l.partner_business_type,'country',l.partner_country,'source','exact_unique_active_partner_contact')) when l.contact_id is not null then jsonb_strip_nulls(jsonb_build_object('contact_id',l.contact_id,'person',l.contact_person,'company',l.contact_company,'kind',l.contact_kind,'role',l.contact_role,'country',l.contact_country,'source','contact_master_secondary')) end,
    'project_evidence',case when l.evidence_project_id is not null then jsonb_strip_nulls(jsonb_build_object('project_id',l.evidence_project_id,'project_name',l.evidence_project_name,'method',l.project_evidence_method,'confidence',l.project_evidence_confidence,'strong_context',l.project_context_strong,'status',l.evidence_project_status,'pipeline_stage',l.evidence_pipeline_stage,'operational_state',l.evidence_operational_state,'assignment_allowed',false)) end,
    'next_action_state',l.next_action_state,'recommended_action',l.recommended_action,'priority_score',l.priority_score,'protected_gate',l.protected_gate,
    'reply_evidence',jsonb_build_object('later_outgoing',l.later_outgoing_evidence,'missing_reply_alone_is_action',false),
    'signals',jsonb_build_object('rejection',l.rejection_signal,'marketing',l.marketing_signal,'recruitment',l.recruitment_signal,'finance',l.finance_signal,'legal',l.legal_signal,'security',l.security_signal,'capability_response',l.capability_response_signal,'scope_closed',l.scope_closed_signal,'offer',l.offer_signal,'direct_request',l.request_signal,'acknowledgement',l.acknowledgement_signal,'counterparty_commitment',l.counterparty_commitment_signal,'event',l.event_signal,'document',l.document_signal,'low_information',l.low_information_signal),
    'source_review_flag',coalesce(l.needs_review,false),'action_created',false,'project_assignment_performed',false
  )) order by l.priority_score desc,l.sent_at desc nulls last,l.id desc),'[]'::jsonb) value from limited l
)
select jsonb_build_object('business_inbox_version',2,'read_only',true,'generated_at',now(),'days',(select days from params),
  'policy',jsonb_build_object('thread_level_deduplication',true,'latest_incoming_drives_state',true,'quoted_history_is_excluded_from_primary_signal_scan',true,'missing_reply_evidence_is_not_action_required',true,'identity_does_not_assign_project',true,'project_assignment_allowed',false,'may_create_task_or_action',false,'may_send_email',false,'may_change_client_supplier_role',false,'rejection_never_auto_closes_project',true,'protected_human_gates_preserved',true),
  'stats',jsonb_build_object('conversations',(select count(*) from classified),'action_candidate',(select count(*) from classified where next_action_state='action_candidate'),'process_document',(select count(*) from classified where next_action_state='process_document'),'semantic_review',(select count(*) from classified where next_action_state='semantic_review'),'waiting',(select count(*) from classified where next_action_state='waiting'),'review_optional',(select count(*) from classified where next_action_state='review_optional'),'informational',(select count(*) from classified where next_action_state='informational'),'handled',(select count(*) from classified where next_action_state='handled'),'project_outcome_reviews',(select count(*) from classified where recommended_action='review_project_outcome'),'received_offers',(select count(*) from classified where recommended_action='review_received_offer'),'direct_reply_reviews',(select count(*) from classified where recommended_action='review_and_reply')),
  'items',(select value from items));
$_$;


ALTER FUNCTION public.pppp_chatgpt_business_inbox_v2(p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_change_intelligence_v1(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_change_intelligence_v1(p_hours integer DEFAULT 24, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select public.pppp_intelligence_change_from_state_v1(
    public.pppp_intelligence_compact_state_v1(30,30),
    greatest(0,least(coalesce(p_hours,24),168)),
    greatest(5,least(coalesce(p_limit,20),30))
  );
$$;


ALTER FUNCTION public.pppp_chatgpt_change_intelligence_v1(p_hours integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_command_status_v1(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_command_status_v1(p_command_id text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS TABLE(command_id text, project_id uuid, action_type text, status text, result jsonb, requested_at timestamp with time zone, processed_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select r.command_id, r.project_id, r.action_type, r.status, r.result, r.requested_at, r.processed_at
  from public.pppp_chatgpt_command_receipts r
  where nullif(btrim(p_command_id),'') is null or r.command_id = btrim(p_command_id)
  order by r.processed_at desc nulls last, r.created_at desc
  limit least(100, greatest(1, coalesce(p_limit,20)));
$$;


ALTER FUNCTION public.pppp_chatgpt_command_status_v1(p_command_id text, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_control_tower_v1(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_control_tower_v1(p_days integer DEFAULT 30, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_days integer := greatest(1, least(coalesce(p_days,30), 90));
  v_limit integer := greatest(5, least(coalesce(p_limit,10), 30));
  v_daily jsonb := '{}'::jsonb;
  v_finance jsonb := '{}'::jsonb;
  v_focus jsonb := '[]'::jsonb;
  v_human_decisions jsonb := '[]'::jsonb;
  v_finance_attention jsonb := '[]'::jsonb;
  v_new_opportunities jsonb := '[]'::jsonb;
  v_waiting_external jsonb := '[]'::jsonb;
  v_headline text;
begin
  v_daily := public.pppp_chatgpt_daily_intelligence_v1(v_days, greatest(v_limit,20));
  v_finance := public.pppp_chatgpt_finance_intelligence_v1(v_days, greatest(v_limit,20));

  select coalesce(jsonb_agg(item order by ord),'[]'::jsonb)
    into v_focus
  from (
    select x.value as item, x.ord
    from jsonb_array_elements(coalesce(v_daily->'top_focus','[]'::jsonb)) with ordinality x(value,ord)
    where x.ord <= v_limit
  ) q;

  select coalesce(jsonb_agg(item order by ord),'[]'::jsonb)
    into v_human_decisions
  from (
    select x.value as item, x.ord
    from jsonb_array_elements(coalesce(v_daily->'human_decisions_required','[]'::jsonb)) with ordinality x(value,ord)
    where x.ord <= v_limit
  ) q;

  select coalesce(jsonb_agg(item order by ord),'[]'::jsonb)
    into v_finance_attention
  from (
    select x.value as item, x.ord
    from jsonb_array_elements(coalesce(v_finance->'attention','[]'::jsonb)) with ordinality x(value,ord)
    where x.ord <= v_limit
  ) q;

  select coalesce(jsonb_agg(item order by ord),'[]'::jsonb)
    into v_new_opportunities
  from (
    select x.value as item, x.ord
    from jsonb_array_elements(coalesce(v_daily->'new_opportunities','[]'::jsonb)) with ordinality x(value,ord)
    where x.ord <= v_limit
  ) q;

  select coalesce(jsonb_agg(item order by ord),'[]'::jsonb)
    into v_waiting_external
  from (
    select x.value as item, x.ord
    from jsonb_array_elements(coalesce(v_daily->'waiting_external_watchlist','[]'::jsonb)) with ordinality x(value,ord)
    where x.ord <= v_limit
  ) q;

  v_headline := format(
    '%s projekte kërkojnë vëmendje; %s vendime/propozime prekin human gates; %s çështje financiare kërkojnë review; %s opportunity të reja kërkojnë review.',
    coalesce((v_daily#>>'{summary,projects_requiring_attention}')::integer,0),
    coalesce((v_daily#>>'{summary,human_gated_proposals}')::integer,0),
    coalesce((v_finance#>>'{summary,attention_items}')::integer,0),
    coalesce((v_daily#>>'{summary,new_opportunity_candidates}')::integer,0)
  );

  return jsonb_build_object(
    'control_tower_version', 1,
    'mode', 'read_only_operating_picture',
    'read_only', true,
    'generated_at', coalesce(v_daily->'generated_at',v_finance->'generated_at'),
    'as_of_date', coalesce(v_finance->'as_of_date',v_daily->'brief_date'),
    'window_days', v_days,
    'limit', v_limit,
    'policy', jsonb_build_object(
      'read_only', true,
      'executions_performed', 0,
      'no_email_send', true,
      'no_task_creation', true,
      'no_project_creation', true,
      'no_supplier_selection_or_commitment', true,
      'no_finance_core_mutation', true,
      'no_price_or_margin_decision', true,
      'no_project_disposition', true,
      'protected_human_gates_preserved', true
    ),
    'headline', v_headline,
    'company_state', jsonb_build_object(
      'projects_requiring_attention', coalesce((v_daily#>>'{summary,projects_requiring_attention}')::integer,0),
      'human_gated_proposals', coalesce((v_daily#>>'{summary,human_gated_proposals}')::integer,0),
      'projects_waiting_external', coalesce((v_daily#>>'{summary,projects_waiting_external}')::integer,0),
      'new_opportunity_candidates', coalesce((v_daily#>>'{summary,new_opportunity_candidates}')::integer,0),
      'finance_attention_items', coalesce((v_finance#>>'{summary,attention_items}')::integer,0),
      'overdue_receivable_invoices', coalesce((v_finance#>>'{summary,overdue_receivable_invoices}')::integer,0),
      'open_bank_guarantees', coalesce((v_finance#>>'{summary,open_bank_guarantees}')::integer,0),
      'supplier_invoices_missing_due_date', coalesce((v_finance#>>'{summary,supplier_invoices_missing_due_date}')::integer,0)
    ),
    'focus_now', v_focus,
    'human_decisions_required', v_human_decisions,
    'finance_attention', v_finance_attention,
    'new_opportunities', v_new_opportunities,
    'waiting_external_watchlist', v_waiting_external,
    'data_quality_watch', jsonb_build_object(
      'supplier_invoices_missing_due_date', coalesce(v_finance->'supplier_invoices_missing_due_date','[]'::jsonb),
      'cash_balance_available', coalesce((v_finance->>'cash_balance_available')::boolean,false),
      'cash_balance_note', v_finance->'cash_balance_note'
    ),
    'source_layers', jsonb_build_object(
      'daily_intelligence_version', v_daily->'daily_intelligence_version',
      'situation_intelligence_version', 1,
      'action_orchestrator_version', 1,
      'finance_intelligence_version', v_finance->'finance_intelligence_version',
      'supplier_intelligence', 'on_demand_only'
    ),
    'intelligence_limits', jsonb_build_array(
      'Control Tower v1 is current-state synthesis, not historical change detection.',
      'No cash balance is inferred without a canonical bank balance source.',
      'Supplier Intelligence is request/project scoped and is not run generically across the portfolio.',
      'Unresolved inbox items are not forced into projects.',
      'Protected actions remain human-gated.'
    )
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_control_tower_v1(p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_control_tower_v2(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_control_tower_v2(p_hours integer DEFAULT 24, p_days integer DEFAULT 30, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_days integer:=greatest(1,least(coalesce(p_days,30),90));
  v_limit integer:=greatest(5,least(coalesce(p_limit,10),30));
  v_current jsonb;
  v_compact jsonb;
  v_changes jsonb;
begin
  v_current:=public.pppp_chatgpt_control_tower_v1(v_days,v_limit);
  v_compact:=public.pppp_intelligence_compact_from_control_tower_v1(v_current,v_limit);
  v_changes:=public.pppp_intelligence_change_from_state_v1(v_compact,p_hours,v_limit);
  return v_current || jsonb_build_object(
    'control_tower_version',2,'mode','read_only_operating_picture_with_historical_delta',
    'historical_delta_available',coalesce((v_changes->>'historical_delta_available')::boolean,false),'change_intelligence',v_changes,
    'intelligence_limits',jsonb_build_array(
      'Historical change detection starts only from stored intelligence snapshots; no pre-snapshot history is inferred.',
      'A no-longer-present item is not automatically treated as resolved.',
      'No cash balance is inferred without a canonical bank balance source.',
      'Supplier Intelligence remains request/project scoped and does not select or commit suppliers.',
      'Unresolved inbox items are not forced into projects.','Protected actions remain human-gated.'
    )
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_control_tower_v2(p_hours integer, p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_create_project_v1(text, text, text, text, text, date, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_create_project_v1(p_command_id text, p_name text, p_client text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_location text DEFAULT NULL::text, p_deadline date DEFAULT NULL::date, p_notes text DEFAULT NULL::text, p_deal_type text DEFAULT NULL::text, p_business_type text DEFAULT NULL::text, p_source text DEFAULT 'chatgpt'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_command_id text := nullif(btrim(p_command_id), '');
  v_name text := nullif(btrim(p_name), '');
  v_client text := nullif(btrim(p_client), '');
  v_reference text := nullif(btrim(p_reference), '');
  v_location text := nullif(btrim(p_location), '');
  v_notes text := nullif(btrim(p_notes), '');
  v_deal_type text := coalesce(nullif(btrim(p_deal_type), ''), 'full');
  v_business_type text := nullif(btrim(p_business_type), '');
  v_source text := coalesce(nullif(btrim(p_source), ''), 'chatgpt');
  v_metadata jsonb := case
    when jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) = 'object' then coalesce(p_metadata, '{}'::jsonb)
    else '{}'::jsonb
  end;
  v_receipt public.pppp_chatgpt_command_receipts%rowtype;
  v_project public.projects%rowtype;
  v_project_json jsonb;
  v_result jsonb;
  v_attempts integer := 1;
begin
  if v_command_id is null then
    raise exception using errcode = '22023', message = 'command_id_required';
  end if;
  if length(v_command_id) > 240 then
    raise exception using errcode = '22023', message = 'command_id_too_long';
  end if;
  if v_name is null then
    raise exception using errcode = '22023', message = 'project_name_required';
  end if;
  if length(v_name) > 500 then
    raise exception using errcode = '22023', message = 'project_name_too_long';
  end if;
  if v_business_type is not null and v_business_type not in ('trading','fabrication','hybrid') then
    raise exception using errcode = '22023', message = 'invalid_business_type';
  end if;
  if v_source not in ('chatgpt','pppp_ui') then
    raise exception using errcode = '22023', message = 'invalid_project_create_source';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_command_id, 0));

  select * into v_receipt
  from public.pppp_chatgpt_command_receipts
  where command_id = v_command_id;

  if found then
    if v_receipt.action_type <> 'create_project' then
      raise exception using errcode = '23505', message = 'command_id_conflict';
    end if;

    v_attempts := greatest(1, least(3, coalesce(v_receipt.attempts, 1)));

    if v_receipt.project_id is not null then
      select * into v_project
      from public.projects
      where id = v_receipt.project_id;

      if not found then
        raise exception using errcode = '23514', message = 'create_project_receipt_project_missing';
      end if;

      v_project_json := jsonb_build_object(
        'id', v_project.id,
        'name', v_project.name,
        'client', v_project.client,
        'reference', coalesce(v_project.business_ref, v_project.ref),
        'location', v_project.location,
        'deadline', v_project.deadline,
        'status', v_project.status,
        'pipeline_stage', v_project.pipeline_stage,
        'deal_type', v_project.deal_type,
        'business_type', v_project.business_type,
        'created_at', v_project.created_at
      );

      return jsonb_build_object(
        'ok', true,
        'command_id', v_command_id,
        'project_id', v_project.id,
        'created', false,
        'project', v_project_json
      );
    end if;
  end if;

  insert into public.projects(
    name, client, ref, business_ref, location, deadline, notes,
    status, pipeline_stage, deal_type, business_type
  ) values (
    v_name, v_client, v_reference, v_reference, v_location, p_deadline, v_notes,
    'pritje', 'rfq_in', v_deal_type, v_business_type
  )
  returning * into v_project;

  v_project_json := jsonb_build_object(
    'id', v_project.id,
    'name', v_project.name,
    'client', v_project.client,
    'reference', coalesce(v_project.business_ref, v_project.ref),
    'location', v_project.location,
    'deadline', v_project.deadline,
    'status', v_project.status,
    'pipeline_stage', v_project.pipeline_stage,
    'deal_type', v_project.deal_type,
    'business_type', v_project.business_type,
    'created_at', v_project.created_at
  );

  v_result := jsonb_build_object(
    'ok', true,
    'command_id', v_command_id,
    'project_id', v_project.id,
    'created', true,
    'project', v_project_json,
    'source', v_source,
    'metadata', v_metadata
  );

  insert into public.pppp_chatgpt_command_receipts(
    command_id, project_id, action_type, status, attempts, result,
    processed_at, updated_at
  ) values (
    v_command_id, v_project.id, 'create_project', 'succeeded', v_attempts, v_result,
    now(), now()
  )
  on conflict (command_id) do update
  set project_id = excluded.project_id,
      action_type = 'create_project',
      status = 'succeeded',
      attempts = greatest(1, least(3, public.pppp_chatgpt_command_receipts.attempts)),
      result = excluded.result,
      processed_at = now(),
      updated_at = now();

  return v_result;
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_create_project_v1(p_command_id text, p_name text, p_client text, p_reference text, p_location text, p_deadline date, p_notes text, p_deal_type text, p_business_type text, p_source text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: pppp_chatgpt_create_supplier_offer_v1(text, uuid, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_create_supplier_offer_v1(p_command_id text, p_project_id uuid, p_payload jsonb, p_source text DEFAULT 'chatgpt'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_command_id text := nullif(btrim(p_command_id), '');
  v_source text := coalesce(nullif(btrim(p_source), ''), 'chatgpt');
  v_metadata jsonb := case
    when jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) = 'object' then coalesce(p_metadata, '{}'::jsonb)
    else '{}'::jsonb
  end;
  v_receipt public.pppp_chatgpt_command_receipts%rowtype;
  v_project public.projects%rowtype;
  v_offer public.offers%rowtype;
  v_supplier text;
  v_currency text;
  v_price_kg numeric := 0;
  v_qty_kg numeric := 0;
  v_mechanical numeric := 0;
  v_packaging numeric := 0;
  v_transport numeric := 0;
  v_total numeric := 0;
  v_total_eur numeric := 0;
  v_fx numeric := 1;
  v_delivery integer;
  v_validity integer;
  v_extra_input jsonb;
  v_extra_positions jsonb := '[]'::jsonb;
  v_extra_total numeric := 0;
  v_extra_item jsonb;
  v_extra_label text;
  v_extra_amount numeric;
  v_extra_index integer := 0;
  v_positions jsonb;
  v_result jsonb;
  v_existing_offer_id uuid;
  v_unknown_key text;
begin
  if v_command_id is null then
    raise exception using errcode = '22023', message = 'command_id_required';
  end if;
  if length(v_command_id) > 240 then
    raise exception using errcode = '22023', message = 'command_id_too_long';
  end if;
  if p_project_id is null then
    raise exception using errcode = '22023', message = 'project_id_required';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception using errcode = '22023', message = 'supplier_offer_value_json_must_be_object';
  end if;
  if v_source <> 'chatgpt' then
    raise exception using errcode = '22023', message = 'invalid_supplier_offer_source';
  end if;

  select k into v_unknown_key
  from jsonb_object_keys(p_payload) as x(k)
  where k not in (
    'supplier','currency','price_kg','qty_kg','mechanical_eur','packaging_eur',
    'transport_eur','extra_positions','delivery_weeks','validity_days',
    'exchange_rate_to_eur','incoterms','cert','notes','payment_terms','inclusions',
    'exclusions','offer_ref','contact_person','source'
  )
  limit 1;
  if v_unknown_key is not null then
    raise exception using errcode = '22023', message = 'supplier_offer_field_not_allowed:' || v_unknown_key;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_command_id, 0));

  select * into v_receipt
  from public.pppp_chatgpt_command_receipts
  where command_id = v_command_id
  for update;

  if not found then
    raise exception using errcode = '42501', message = 'approved_bridge_receipt_required';
  end if;
  if v_receipt.action_type <> 'supplier_offer' then
    raise exception using errcode = '23505', message = 'command_id_conflict';
  end if;
  if lower(coalesce(v_receipt.approval, '')) <> 'approved' then
    raise exception using errcode = '42501', message = 'supplier_offer_command_not_approved';
  end if;

  if v_receipt.status = 'succeeded' then
    begin
      v_existing_offer_id := nullif(v_receipt.result->>'offer_id', '')::uuid;
    exception when others then
      v_existing_offer_id := null;
    end;
    if v_existing_offer_id is not null
       and exists (
         select 1 from public.offers o
         where o.id = v_existing_offer_id and o.project_id = p_project_id
       ) then
      return v_receipt.result || jsonb_build_object('created', false);
    end if;
    raise exception using errcode = '23514', message = 'supplier_offer_receipt_offer_missing';
  end if;

  if v_receipt.status <> 'processing' then
    raise exception using errcode = '42501', message = 'supplier_offer_receipt_not_processing';
  end if;

  select * into v_project from public.projects where id = p_project_id;
  if not found then
    raise exception using errcode = '22023', message = 'project_not_found';
  end if;
  if lower(coalesce(v_project.status, '')) in (
    'humbur','lost','mbyllur','closed','arkivuar','archived','realizuar','cancelled','canceled'
  ) then
    raise exception using errcode = '23514', message = 'supplier_offer_terminal_project';
  end if;

  v_supplier := nullif(btrim(coalesce(p_payload->>'supplier', '')), '');
  v_currency := upper(btrim(coalesce(nullif(p_payload->>'currency', ''), 'EUR')));
  if v_supplier is null then
    raise exception using errcode = '22023', message = 'supplier_required';
  end if;
  if v_currency !~ '^[A-Z]{3}$' then
    raise exception using errcode = '22023', message = 'valid_currency_required';
  end if;

  begin v_price_kg := replace(coalesce(nullif(p_payload->>'price_kg',''),'0'),',','.')::numeric;
  exception when others then raise exception using errcode = '22023', message = 'invalid_price_kg'; end;
  begin v_qty_kg := replace(coalesce(nullif(p_payload->>'qty_kg',''),'0'),',','.')::numeric;
  exception when others then raise exception using errcode = '22023', message = 'invalid_qty_kg'; end;
  begin v_mechanical := replace(coalesce(nullif(p_payload->>'mechanical_eur',''),'0'),',','.')::numeric;
  exception when others then raise exception using errcode = '22023', message = 'invalid_mechanical_eur'; end;
  begin v_packaging := replace(coalesce(nullif(p_payload->>'packaging_eur',''),'0'),',','.')::numeric;
  exception when others then raise exception using errcode = '22023', message = 'invalid_packaging_eur'; end;
  begin v_transport := replace(coalesce(nullif(p_payload->>'transport_eur',''),'0'),',','.')::numeric;
  exception when others then raise exception using errcode = '22023', message = 'invalid_transport_eur'; end;
  begin v_delivery := nullif(p_payload->>'delivery_weeks','')::integer;
  exception when others then raise exception using errcode = '22023', message = 'invalid_delivery_weeks'; end;
  begin v_validity := nullif(p_payload->>'validity_days','')::integer;
  exception when others then raise exception using errcode = '22023', message = 'invalid_validity_days'; end;

  if least(v_price_kg, v_qty_kg, v_mechanical, v_packaging, v_transport) < 0 then
    raise exception using errcode = '22023', message = 'negative_commercial_values_not_allowed';
  end if;
  if v_price_kg > 0 and v_qty_kg <= 0 then
    raise exception using errcode = '22023', message = 'qty_kg_required_for_kg_pricing';
  end if;
  if v_delivery is not null and v_delivery < 0 then
    raise exception using errcode = '22023', message = 'invalid_delivery_weeks';
  end if;
  if v_validity is not null and v_validity < 0 then
    raise exception using errcode = '22023', message = 'invalid_validity_days';
  end if;

  v_extra_input := coalesce(p_payload->'extra_positions', '[]'::jsonb);
  if jsonb_typeof(v_extra_input) <> 'array' then
    raise exception using errcode = '22023', message = 'extra_positions_must_be_array';
  end if;
  if jsonb_array_length(v_extra_input) > 50 then
    raise exception using errcode = '22023', message = 'too_many_extra_positions';
  end if;

  for v_extra_item in select value from jsonb_array_elements(v_extra_input)
  loop
    if jsonb_typeof(v_extra_item) <> 'object' then
      raise exception using errcode = '22023', message = 'extra_position_must_be_object';
    end if;
    v_extra_label := btrim(coalesce(v_extra_item->>'label', ''));
    if char_length(v_extra_label) > 120 then
      raise exception using errcode = '22023', message = 'extra_position_label_too_long';
    end if;
    begin
      v_extra_amount := replace(coalesce(nullif(v_extra_item->>'amount',''),'0'),',','.')::numeric;
    exception when others then
      raise exception using errcode = '22023', message = 'invalid_extra_position_amount';
    end;
    if v_extra_amount < 0 then
      raise exception using errcode = '22023', message = 'negative_extra_position_not_allowed';
    end if;
    if v_extra_amount > 0 and v_extra_label = '' then
      raise exception using errcode = '22023', message = 'extra_position_label_required';
    end if;
    if v_extra_label <> '' and v_extra_amount <= 0 then
      raise exception using errcode = '22023', message = 'extra_position_amount_must_be_positive';
    end if;
    if v_extra_amount > 0 then
      v_extra_index := v_extra_index + 1;
      v_extra_total := v_extra_total + v_extra_amount;
      v_extra_positions := v_extra_positions || jsonb_build_array(
        jsonb_build_object(
          'type','extra',
          'key','extra_' || v_extra_index::text,
          'desc',v_extra_label,
          'qty',1,
          'unit','Pauschale',
          'unit_price',v_extra_amount,
          'total',v_extra_amount
        )
      );
    end if;
  end loop;

  if v_price_kg <= 0 and (v_mechanical + v_packaging + v_transport + v_extra_total) <= 0 then
    raise exception using errcode = '22023', message = 'positive_commercial_value_required';
  end if;

  if v_currency = 'EUR' then
    v_fx := 1;
  else
    begin v_fx := replace(coalesce(nullif(p_payload->>'exchange_rate_to_eur',''),'0'),',','.')::numeric;
    exception when others then raise exception using errcode = '22023', message = 'invalid_exchange_rate_to_eur'; end;
    if coalesce(v_fx,0) <= 0 then
      raise exception using errcode = '22023', message = 'exchange_rate_to_eur_required';
    end if;
  end if;

  v_total := round((v_price_kg * v_qty_kg + v_mechanical + v_packaging + v_transport + v_extra_total)::numeric, 2);
  v_total_eur := round((v_total * v_fx)::numeric, 2);
  v_positions := jsonb_build_array(
    jsonb_build_object('type','production','desc','Fertigung / Produktion','qty',v_qty_kg,'unit','kg','unit_price',v_price_kg,'total',round(v_price_kg*v_qty_kg,2)),
    jsonb_build_object('type','mechanical','desc','Mechanische Bearbeitung','qty',1,'unit','Pauschale','unit_price',v_mechanical,'total',v_mechanical),
    jsonb_build_object('type','packaging','desc','Verpackung','qty',1,'unit','Pauschale','unit_price',v_packaging,'total',v_packaging),
    jsonb_build_object('type','transport','desc','Transport','qty',1,'unit','Pauschale','unit_price',v_transport,'total',v_transport)
  ) || v_extra_positions;

  insert into public.offers(
    project_id,supplier,price_kg,total_eur,delivery_weeks,incoterms,cert,notes,origin,
    transport_eur,vat_pct,qty_kg,positions,currency,pricing_unit,payment_terms,inclusions,
    exclusions,validity_days,offer_ref,contact_person,raw_text,exchange_rate_to_eur,total_amount,unit_price
  ) values (
    p_project_id,v_supplier,nullif(v_price_kg,0),v_total_eur,v_delivery,
    nullif(btrim(coalesce(p_payload->>'incoterms','')),''),
    nullif(btrim(coalesce(p_payload->>'cert','')),''),
    nullif(btrim(coalesce(p_payload->>'notes','')),''),'chatgpt_bridge',
    v_transport,0,v_qty_kg,v_positions,v_currency,case when v_price_kg>0 then 'kg' else 'total' end,
    nullif(btrim(coalesce(p_payload->>'payment_terms','')),''),
    nullif(btrim(coalesce(p_payload->>'inclusions','')),''),
    nullif(btrim(coalesce(p_payload->>'exclusions','')),''),v_validity,
    nullif(btrim(coalesce(p_payload->>'offer_ref','')),''),
    nullif(btrim(coalesce(p_payload->>'contact_person','')),''),
    concat(
      'ChatGPT controlled supplier offer registration', E'\ncommand_id=', v_command_id,
      E'\nsource=', coalesce(nullif(btrim(coalesce(p_payload->>'source','')),''), v_source),
      E'\nmetadata=', v_metadata::text
    ),
    v_fx,v_total,null
  ) returning * into v_offer;

  v_result := jsonb_build_object(
    'ok',true,
    'command_id',v_command_id,
    'project_id',p_project_id,
    'offer_id',v_offer.id,
    'supplier',v_supplier,
    'currency',v_currency,
    'total_amount',v_total,
    'total_eur',v_total_eur,
    'origin','chatgpt_bridge',
    'created',true,
    'selected',false,
    'human_supplier_selection_required',true
  );

  update public.pppp_chatgpt_command_receipts
  set project_id = p_project_id,
      action_type = 'supplier_offer',
      status = 'succeeded',
      result = v_result,
      processed_at = now(),
      updated_at = now()
  where command_id = v_command_id;

  return v_result;
end;
$_$;


ALTER FUNCTION public.pppp_chatgpt_create_supplier_offer_v1(p_command_id text, p_project_id uuid, p_payload jsonb, p_source text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: pppp_chatgpt_dach_steel_target_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_dach_steel_target_v1(p_source_key text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select to_jsonb(t) from public.pppp_dach_steel_targets_v1 t where t.source_key=nullif(btrim(p_source_key),'') limit 1),
    '{}'::jsonb
  );
$$;


ALTER FUNCTION public.pppp_chatgpt_dach_steel_target_v1(p_source_key text) OWNER TO postgres;

--
-- Name: pppp_chatgpt_daily_intelligence_v1(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_daily_intelligence_v1(p_days integer DEFAULT 30, p_limit integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_days integer := greatest(1,least(coalesce(p_days,30),90));
  v_limit integer := greatest(5,least(coalesce(p_limit,12),30));
  v_orchestrator jsonb := '{}'::jsonb;
  v_situations jsonb := '{}'::jsonb;
  v_top_focus jsonb := '[]'::jsonb;
  v_human_decisions jsonb := '[]'::jsonb;
  v_prepare_now jsonb := '[]'::jsonb;
  v_controlled_writes jsonb := '[]'::jsonb;
  v_waiting_external jsonb := '[]'::jsonb;
  v_attention_projects jsonb := '[]'::jsonb;
  v_new_opportunities jsonb := '[]'::jsonb;
  v_focus_count integer := 0;
  v_human_count integer := 0;
  v_waiting_count integer := 0;
  v_attention_count integer := 0;
  v_new_opportunity_count integer := 0;
  v_draft_count integer := 0;
  v_controlled_write_count integer := 0;
  v_headline text;
begin
  v_orchestrator := public.pppp_chatgpt_action_orchestrator_v1(v_days,greatest(v_limit,20));
  v_situations := public.pppp_chatgpt_situation_intelligence_v1(v_days,greatest(v_limit,20));

  select coalesce(jsonb_agg(item order by priority_score desc, proposal_id),'[]'::jsonb)
    into v_top_focus
  from (
    select elem as item,
           coalesce((elem->>'priority_score')::integer,0) as priority_score,
           coalesce(elem->>'proposal_id','') as proposal_id
    from jsonb_array_elements(coalesce(v_orchestrator->'proposals','[]'::jsonb)) x(elem)
    order by coalesce((elem->>'priority_score')::integer,0) desc, coalesce(elem->>'proposal_id','')
    limit v_limit
  ) q;

  select coalesce(jsonb_agg(item order by priority_score desc, proposal_id),'[]'::jsonb)
    into v_human_decisions
  from (
    select elem as item,
           coalesce((elem->>'priority_score')::integer,0) as priority_score,
           coalesce(elem->>'proposal_id','') as proposal_id
    from jsonb_array_elements(coalesce(v_orchestrator->'proposals','[]'::jsonb)) x(elem)
    where jsonb_array_length(coalesce(elem->'approval_gates','[]'::jsonb))>0
    order by coalesce((elem->>'priority_score')::integer,0) desc, coalesce(elem->>'proposal_id','')
    limit v_limit
  ) q;

  select coalesce(jsonb_agg(item order by priority_score desc, proposal_id),'[]'::jsonb)
    into v_prepare_now
  from (
    select elem as item,
           coalesce((elem->>'priority_score')::integer,0) as priority_score,
           coalesce(elem->>'proposal_id','') as proposal_id
    from jsonb_array_elements(coalesce(v_orchestrator->'proposals','[]'::jsonb)) x(elem)
    where coalesce((elem->>'draft_preparation_allowed')::boolean,false)
    order by coalesce((elem->>'priority_score')::integer,0) desc, coalesce(elem->>'proposal_id','')
    limit v_limit
  ) q;

  select coalesce(jsonb_agg(item order by priority_score desc, proposal_id),'[]'::jsonb)
    into v_controlled_writes
  from (
    select elem as item,
           coalesce((elem->>'priority_score')::integer,0) as priority_score,
           coalesce(elem->>'proposal_id','') as proposal_id
    from jsonb_array_elements(coalesce(v_orchestrator->'proposals','[]'::jsonb)) x(elem)
    where coalesce((elem->>'controlled_write_proposal_allowed')::boolean,false)
    order by coalesce((elem->>'priority_score')::integer,0) desc, coalesce(elem->>'proposal_id','')
    limit v_limit
  ) q;

  select coalesce(jsonb_agg(item order by rank_score desc, project_name),'[]'::jsonb)
    into v_waiting_external
  from (
    select jsonb_build_object(
             'project_id',elem->'project'->>'id',
             'project_name',elem->'project'->>'name',
             'client',elem->'project'->>'client',
             'pipeline_stage',elem->'project'->>'pipeline_stage',
             'risk_level',elem->'risk'->>'level',
             'summary',elem->>'summary',
             'recommendation',coalesce(elem->'recommendation','{}'::jsonb),
             'attention_required',coalesce((elem->>'attention_required')::boolean,false)
           ) as item,
           coalesce((elem->>'portfolio_rank_score')::integer,0) as rank_score,
           coalesce(elem->'project'->>'name','') as project_name
    from jsonb_array_elements(coalesce(v_situations->'project_situations','[]'::jsonb)) x(elem)
    where elem->>'situation_state'='waiting_external'
    order by coalesce((elem->>'portfolio_rank_score')::integer,0) desc
    limit v_limit
  ) q;

  select coalesce(jsonb_agg(item order by rank_score desc, project_name),'[]'::jsonb)
    into v_attention_projects
  from (
    select jsonb_build_object(
             'project_id',elem->'project'->>'id',
             'project_name',elem->'project'->>'name',
             'client',elem->'project'->>'client',
             'situation_state',elem->>'situation_state',
             'risk',coalesce(elem->'risk','{}'::jsonb),
             'summary',elem->>'summary',
             'recommendation',coalesce(elem->'recommendation','{}'::jsonb),
             'gates_triggered',coalesce(elem->'gates_triggered','[]'::jsonb)
           ) as item,
           coalesce((elem->>'portfolio_rank_score')::integer,0) as rank_score,
           coalesce(elem->'project'->>'name','') as project_name
    from jsonb_array_elements(coalesce(v_situations->'project_situations','[]'::jsonb)) x(elem)
    where coalesce((elem->>'attention_required')::boolean,false)
    order by coalesce((elem->>'portfolio_rank_score')::integer,0) desc
    limit v_limit
  ) q;

  select coalesce(jsonb_agg(item order by priority_score desc, proposal_id),'[]'::jsonb)
    into v_new_opportunities
  from (
    select elem as item,
           coalesce((elem->>'priority_score')::integer,0) as priority_score,
           coalesce(elem->>'proposal_id','') as proposal_id
    from jsonb_array_elements(coalesce(v_orchestrator->'proposals','[]'::jsonb)) x(elem)
    where elem->>'action_kind'='review_new_opportunity'
    order by coalesce((elem->>'priority_score')::integer,0) desc
    limit v_limit
  ) q;

  v_focus_count := jsonb_array_length(v_top_focus);
  v_human_count := jsonb_array_length(v_human_decisions);
  v_waiting_count := jsonb_array_length(v_waiting_external);
  v_attention_count := jsonb_array_length(v_attention_projects);
  v_new_opportunity_count := jsonb_array_length(v_new_opportunities);
  v_draft_count := jsonb_array_length(v_prepare_now);
  v_controlled_write_count := jsonb_array_length(v_controlled_writes);

  v_headline := concat(
    v_attention_count,' projekte kërkojnë vëmendje; ',
    v_human_count,' propozime prekin human gates; ',
    v_waiting_count,' projekte janë në pritje të palës tjetër; ',
    v_new_opportunity_count,' opportunity të reja kërkojnë review.'
  );

  return jsonb_build_object(
    'daily_intelligence_version',1,
    'brief_type','current_operating_state',
    'historical_delta_available',false,
    'historical_delta_note','Ky version nuk ruan snapshots historike dhe nuk pretendon overnight/change detection. Ai përmbledh vetëm gjendjen aktuale kanonike.',
    'read_only',true,
    'generated_at',now(),
    'brief_date',current_date,
    'window_days',v_days,
    'headline',v_headline,
    'summary',jsonb_build_object(
      'top_focus_items',v_focus_count,
      'projects_requiring_attention',v_attention_count,
      'human_gated_proposals',v_human_count,
      'draft_preparation_candidates',v_draft_count,
      'controlled_write_candidates',v_controlled_write_count,
      'projects_waiting_external',v_waiting_count,
      'new_opportunity_candidates',v_new_opportunity_count,
      'executions_performed',0
    ),
    'top_focus',v_top_focus,
    'projects_requiring_attention',v_attention_projects,
    'human_decisions_required',v_human_decisions,
    'prepare_now',v_prepare_now,
    'controlled_write_candidates',v_controlled_writes,
    'waiting_external_watchlist',v_waiting_external,
    'new_opportunities',v_new_opportunities,
    'portfolio_summary',coalesce(v_situations->'portfolio_summary','{}'::jsonb),
    'policy',jsonb_build_object(
      'brief_is_current_state_not_historical_delta',true,
      'read_only',true,
      'no_execution',true,
      'no_email_send',true,
      'no_project_creation',true,
      'no_task_creation',true,
      'no_supplier_selection',true,
      'no_price_or_margin_decision',true,
      'no_project_disposition',true,
      'controlled_writes_require_explicit_user_approval',true,
      'protected_human_gates_preserved',true
    )
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_daily_intelligence_v1(p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_druseidt_intelligence_v1(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_druseidt_intelligence_v1(p_command_id text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare target uuid; item jsonb; ctx jsonb; a jsonb; key text; fp text; lead uuid; result jsonb; ids jsonb:='[]';
begin
 if length(coalesce(p_command_id,''))<10 or jsonb_typeof(p_payload)<>'object' then raise exception 'valid command and payload required';end if;
 select id into strict target from public.pppp_representation_targets_v1 where company_domain_normalized='druseidt.de' and archived_at is null;
 for item in select value from jsonb_array_elements(coalesce(p_payload->'direct_customers','[]')) loop
  if item->>'country' not in ('XK','AL') or coalesce(item->>'domain','') !~ '^[a-z0-9.-]+\.[a-z]+$' or item->>'source_url' !~ '^https://' or length(coalesce(item->>'published_activity',''))<25 then raise exception 'published company activity and official source required';end if;
  if item::text ~* 'spie' then raise exception 'SPIE outreach blocked';end if;
  key:='direct:'||lower(item->>'domain');ctx:=jsonb_build_object('title',item->>'company','company',item->>'company','company_domain',item->>'domain','source_url',item->>'source_url','scope',item->>'published_activity','contact',coalesce(item->'contact','{}'),'closed',false,'procurement_stage','UNCONFIRMED - no open project/package assumed','source','Published company website','intake_command_id',p_command_id);
  a:=public.pppp_druseidt_match_v1(item->>'published_activity',item->>'source_url',true);a:=a||jsonb_build_object('eligible',a->>'relevance' in ('HIGH','MEDIUM'));fp:=md5(jsonb_build_array(ctx,'druseidt-rules-v1')::text);
  insert into public.pppp_druseidt_leads_v1(target_id,source_key,kind,country,fingerprint,context,analysis) values(target,key,'direct',item->>'country',fp,ctx,a)
  on conflict(source_key) do update set context=excluded.context,analysis=excluded.analysis,fingerprint=excluded.fingerprint,analyzed_at=now(),updated_at=now() where pppp_druseidt_leads_v1.fingerprint<>excluded.fingerprint returning id into lead;
  if lead is null then select id into lead from public.pppp_druseidt_leads_v1 where source_key=key;end if;ids:=ids||jsonb_build_array(lead);
 end loop;
 result:=public.pppp_druseidt_refresh_v1();
 return result||jsonb_build_object('direct_lead_ids',ids,'outbound_created',false,'human_email_approval_required',true);
end $_$;


ALTER FUNCTION public.pppp_chatgpt_druseidt_intelligence_v1(p_command_id text, p_payload jsonb) OWNER TO postgres;

--
-- Name: pppp_chatgpt_email_entity_evidence_v1(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_email_entity_evidence_v1(p_query text, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
with params as (
  select
    btrim(coalesce(p_query,'')) as q,
    lower(btrim(coalesce(p_query,''))) as ql,
    greatest(1,least(coalesce(p_limit,10),20)) as lim,
    position('@' in lower(btrim(coalesce(p_query,''))))>0 as is_email
), scored as (
  select
    e.*,
    greatest(
      case when lower(coalesce(e.from_email,''))=(select ql from params) then 100 else 0 end,
      case when exists(select 1 from unnest(coalesce(e.to_emails,'{}'::text[])) x(email) where lower(trim(x.email))=(select ql from params)) then 100 else 0 end,
      case when exists(select 1 from unnest(coalesce(e.cc_emails,'{}'::text[])) x(email) where lower(trim(x.email))=(select ql from params)) then 100 else 0 end,
      case when lower(coalesce(e.gmail_message_id,''))=(select ql from params) then 100 else 0 end,
      case when lower(coalesce(e.gmail_thread_id,''))=(select ql from params) then 98 else 0 end,
      case when not (select is_email from params) and lower(btrim(coalesce(e.from_name,'')))=(select ql from params) then 96 else 0 end,
      case when not (select is_email from params) and position('.' in (select ql from params))>0 and split_part(lower(trim(coalesce(e.from_email,''))),'@',2)=(select ql from params) then 94 else 0 end,
      case when not (select is_email from params) and position('.' in (select ql from params))>0 and exists(select 1 from unnest(coalesce(e.to_emails,'{}'::text[])) x(email) where split_part(lower(trim(x.email)),'@',2)=(select ql from params)) then 94 else 0 end,
      case when not (select is_email from params) and position('.' in (select ql from params))>0 and exists(select 1 from unnest(coalesce(e.cc_emails,'{}'::text[])) x(email) where split_part(lower(trim(x.email)),'@',2)=(select ql from params)) then 94 else 0 end,
      case when not (select is_email from params) and length((select ql from params))>=4 and lower(coalesce(e.from_name,'')) like '%'||(select ql from params)||'%' then 86 else 0 end,
      case when not (select is_email from params) and length((select ql from params))>=5 and lower(coalesce(e.subject,'')) like '%'||(select ql from params)||'%' then 76 else 0 end
    ) as match_score
  from public.project_emails e
  where (select q from params)<>''
), matched as (
  select * from scored where match_score>0
), stats as (
  select
    count(*)::int total,
    count(*) filter(where direction='incoming')::int incoming,
    count(*) filter(where direction='outgoing')::int outgoing,
    count(distinct gmail_thread_id)::int threads,
    count(*) filter(where project_id is not null)::int linked_to_project,
    count(*) filter(where project_id is null and suggested_project_id is not null)::int suggested_project,
    count(*) filter(where project_id is null)::int unresolved,
    min(sent_at) first_email_at,
    max(sent_at) last_email_at,
    max(match_score)::int best_match_score
  from matched
), addresses as (
  select lower(trim(from_email)) email from matched where nullif(trim(from_email),'') is not null
  union
  select lower(trim(x.email)) from matched m cross join lateral unnest(coalesce(m.to_emails,'{}'::text[])) x(email) where nullif(trim(x.email),'') is not null
  union
  select lower(trim(x.email)) from matched m cross join lateral unnest(coalesce(m.cc_emails,'{}'::text[])) x(email) where nullif(trim(x.email),'') is not null
), address_json as (
  select coalesce(jsonb_agg(email order by email),'[]'::jsonb) value from addresses
), names as (
  select distinct btrim(from_name) name from matched where nullif(btrim(from_name),'') is not null
), names_json as (
  select coalesce(jsonb_agg(name order by name),'[]'::jsonb) value from names
), related_projects as (
  select p.id,p.name,p.client,p.status,p.pipeline_stage,p.operational_state,'linked'::text relation
  from public.projects p
  where p.id in(select distinct project_id from matched where project_id is not null)
  union all
  select p.id,p.name,p.client,p.status,p.pipeline_stage,p.operational_state,'suggested'::text relation
  from public.projects p
  where p.id in(select distinct suggested_project_id from matched where project_id is null and suggested_project_id is not null)
    and p.id not in(select distinct project_id from matched where project_id is not null)
), projects_json as (
  select coalesce(jsonb_agg(to_jsonb(x) order by x.relation,x.name),'[]'::jsonb) value from related_projects x
), recent_json as (
  select coalesce(jsonb_agg(to_jsonb(x) order by x.sent_at desc nulls last),'[]'::jsonb) value
  from (
    select
      m.gmail_message_id,m.gmail_thread_id,m.direction,m.from_email,m.from_name,m.to_emails,m.cc_emails,
      m.subject,left(coalesce(m.snippet,''),1600) snippet,m.sent_at,m.has_attachments,
      m.project_id,p.name project_name,m.suggested_project_id,sp.name suggested_project_name,
      m.match_method,m.match_confidence,m.needs_review,m.match_score,
      (split_part(lower(trim(coalesce(m.from_email,''))),'@',1) ~ '(^|[+._-])(no-?reply|do-?not-?reply|mailer-daemon|postmaster|notifications?|dmarc)([+._-]|$)'
        or lower(coalesce(m.from_email,'')) ~ '(ted-no-reply|noreply-dmarc|email\.openai|tm\.openai|supabase\.com|bitrix24\.com|apps-scripts-notifications)') as sender_system_like
    from matched m
    left join public.projects p on p.id=m.project_id
    left join public.projects sp on sp.id=m.suggested_project_id
    order by m.match_score desc,m.sent_at desc nulls last
    limit (select lim from params)*3
  ) x
)
select jsonb_build_object(
  'query',(select q from params),
  'read_only',true,
  'generated_at',now(),
  'match_found',coalesce((select total from stats),0)>0,
  'stats',jsonb_build_object(
    'total_emails',coalesce((select total from stats),0),
    'incoming',coalesce((select incoming from stats),0),
    'outgoing',coalesce((select outgoing from stats),0),
    'threads',coalesce((select threads from stats),0),
    'linked_to_project',coalesce((select linked_to_project from stats),0),
    'suggested_project',coalesce((select suggested_project from stats),0),
    'unresolved',coalesce((select unresolved from stats),0),
    'first_email_at',(select first_email_at from stats),
    'last_email_at',(select last_email_at from stats),
    'best_match_score',(select best_match_score from stats)
  ),
  'observed_email_addresses',(select value from address_json),
  'observed_sender_names',(select value from names_json),
  'related_projects',(select value from projects_json),
  'recent_emails',(select value from recent_json),
  'classification_note','Raw communication evidence only. No person/company role, client/supplier status, or project identity is inferred by this function.'
);
$_$;


ALTER FUNCTION public.pppp_chatgpt_email_entity_evidence_v1(p_query text, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_email_identity_resolution_v1(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_email_identity_resolution_v1(p_query text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with params as (
  select lower(btrim(coalesce(p_query,''))) as q,
         greatest(1,least(coalesce(p_limit,20),50)) as lim
),
counterpart_events as (
  select lower(btrim(e.from_email)) as email,
         nullif(btrim(e.from_name),'') as display_name,
         e.sent_at,e.direction,e.project_id,e.gmail_thread_id
  from public.project_emails e
  where e.direction='incoming'
    and nullif(btrim(coalesce(e.from_email,'')),'') is not null
  union all
  select lower(btrim(x.email)) as email,
         null::text as display_name,
         e.sent_at,e.direction,e.project_id,e.gmail_thread_id
  from public.project_emails e
  cross join lateral unnest(coalesce(e.to_emails,'{}'::text[])) x(email)
  where e.direction='outgoing'
    and nullif(btrim(coalesce(x.email,'')),'') is not null
    and lower(split_part(btrim(x.email),'@',2))<>'prissteel.com'
),
email_rollup as (
  select ce.email,
         lower(split_part(ce.email,'@',2)) as domain,
         (array_agg(ce.display_name order by ce.sent_at desc nulls last)
           filter (where ce.display_name is not null))[1] as display_name,
         min(ce.sent_at) as first_seen_at,
         max(ce.sent_at) as last_seen_at,
         count(*)::int as message_count,
         count(*) filter (where ce.direction='incoming')::int as incoming_count,
         count(*) filter (where ce.direction='outgoing')::int as outgoing_count,
         count(*) filter (where ce.project_id is not null)::int as linked_project_messages,
         count(*) filter (where ce.project_id is null)::int as unresolved_messages,
         count(distinct ce.gmail_thread_id)::int as thread_count
  from counterpart_events ce
  group by ce.email
),
contact_exact as (
  select lower(btrim(c.email)) as email,
         c.contact_id,c.kind,c.company,c.person,c.role,c.country,
         c.project_email_count,c.projects
  from public.pppp_contact_master_v1 c
  where nullif(btrim(coalesce(c.email,'')),'') is not null
),
partner_email_group as (
  select lower(btrim(x.email)) as email,
         count(distinct pc.partner_id)::int as partner_count,
         min(pc.partner_id::text)::uuid as partner_id,
         bool_or(coalesce(pc.is_primary,false)) as is_primary
  from public.partner_contacts pc
  join public.partners p on p.id=pc.partner_id and p.stage='active'
  cross join lateral (values(pc.email),(pc.email_alt)) x(email)
  where nullif(btrim(coalesce(x.email,'')),'') is not null
  group by lower(btrim(x.email))
),
partner_exact as (
  select g.email,g.partner_count,g.partner_id,g.is_primary,
         p.name as partner_name,p.relation,p.business_type,p.country
  from partner_email_group g
  left join public.partners p on p.id=g.partner_id and g.partner_count=1
),
domain_partner_group as (
  select lower(split_part(btrim(x.email),'@',2)) as domain,
         count(distinct pc.partner_id)::int as partner_count,
         min(pc.partner_id::text)::uuid as partner_id
  from public.partner_contacts pc
  join public.partners p on p.id=pc.partner_id and p.stage='active'
  cross join lateral (values(pc.email),(pc.email_alt)) x(email)
  where nullif(btrim(coalesce(x.email,'')),'') is not null
    and lower(split_part(btrim(x.email),'@',2)) not in (
      'gmail.com','outlook.com','hotmail.com','yahoo.com','icloud.com','me.com','microsoft.com','prissteel.com'
    )
  group by lower(split_part(btrim(x.email),'@',2))
),
domain_partner as (
  select g.domain,g.partner_count,g.partner_id,p.name as partner_name
  from domain_partner_group g
  left join public.partners p on p.id=g.partner_id and g.partner_count=1
),
domain_company_norm as (
  select lower(split_part(btrim(c.email),'@',2)) as domain,
         public.pppp_gc_normalize_company_v1(c.company) as company_norm,
         min(c.company) as company_name
  from public.contacts c
  where nullif(btrim(coalesce(c.email,'')),'') is not null
    and nullif(btrim(coalesce(c.company,'')),'') is not null
    and lower(split_part(btrim(c.email),'@',2)) not in (
      'gmail.com','outlook.com','hotmail.com','yahoo.com','icloud.com','me.com','microsoft.com','prissteel.com'
    )
  group by lower(split_part(btrim(c.email),'@',2)),public.pppp_gc_normalize_company_v1(c.company)
),
domain_company as (
  select domain,count(*)::int as company_count,min(company_name) as company_name
  from domain_company_norm
  where nullif(company_norm,'') is not null
  group by domain
),
resolved as (
  select e.*,
         public.pppp_email_sender_class_v1(e.email,e.display_name,null) as sender_class,
         c.contact_id,c.kind as contact_kind,c.company as contact_company,c.person as contact_person,
         c.role as contact_role,c.country as contact_country,c.project_email_count,c.projects as contact_projects,
         pe.partner_count as exact_partner_count,pe.partner_id as exact_partner_id,pe.partner_name as exact_partner_name,
         pe.relation as exact_partner_relation,pe.business_type as exact_partner_business_type,pe.country as exact_partner_country,
         dp.partner_count as domain_partner_count,dp.partner_id as domain_partner_id,dp.partner_name as domain_partner_name,
         dc.company_count as domain_company_count,dc.company_name as domain_company_name,
         case
           when pe.partner_count=1 and c.contact_id is not null
             and nullif(public.pppp_gc_normalize_company_v1(c.company),'') is not null
             and public.pppp_gc_normalize_company_v1(c.company)
                 is distinct from public.pppp_gc_normalize_company_v1(pe.partner_name)
           then true else false
         end as secondary_contact_conflict
  from email_rollup e
  left join contact_exact c on c.email=e.email
  left join partner_exact pe on pe.email=e.email
  left join domain_partner dp on dp.domain=e.domain
  left join domain_company dc on dc.domain=e.domain
),
classified as (
  select r.*,
         case
           when r.sender_class='internal' then 'internal'
           when r.sender_class in ('procurement_system','automated_service') then 'system'
           when r.exact_partner_count=1 then 'canonical_partner_contact'
           when r.contact_id is not null then 'canonical_contact'
           when r.domain_partner_count=1 then 'partner_domain_hint'
           when r.domain_company_count=1 then 'company_domain_hint'
           else 'unresolved_external'
         end as identity_status,
         case
           when r.sender_class in ('internal','procurement_system','automated_service') then 100
           when r.exact_partner_count=1 then 100
           when r.contact_id is not null then 98
           when r.domain_partner_count=1 then 82
           when r.domain_company_count=1 then 78
           else 0
         end as identity_confidence,
         case
           when r.sender_class in ('internal','procurement_system','automated_service') then false
           when r.exact_partner_count=1 then r.secondary_contact_conflict
           when r.contact_id is not null then false
           else true
         end as needs_review
  from resolved r
),
scored as (
  select c.*,
         greatest(
           case when c.email=(select q from params) then 100 else 0 end,
           case when length((select q from params))>=3 and c.email like '%'||(select q from params)||'%' then 92 else 0 end,
           case when length((select q from params))>=3 and lower(coalesce(c.display_name,'')) like '%'||(select q from params)||'%' then 90 else 0 end,
           case when length((select q from params))>=3 and c.domain like '%'||(select q from params)||'%' then 86 else 0 end,
           case when length((select q from params))>=3 and lower(coalesce(c.contact_person,'')) like '%'||(select q from params)||'%' then 90 else 0 end,
           case when length((select q from params))>=3 and lower(coalesce(c.contact_company,'')) like '%'||(select q from params)||'%' then 88 else 0 end,
           case when length((select q from params))>=3 and lower(coalesce(c.exact_partner_name,'')) like '%'||(select q from params)||'%' then 88 else 0 end,
           case when length((select q from params))>=3 and lower(coalesce(c.domain_partner_name,'')) like '%'||(select q from params)||'%' then 80 else 0 end,
           case when length((select q from params))>=3 and lower(coalesce(c.domain_company_name,'')) like '%'||(select q from params)||'%' then 76 else 0 end
         ) as query_match_score
  from classified c
),
matched as (
  select * from scored
  where (select q from params)='' or query_match_score>0
  order by query_match_score desc,last_seen_at desc nulls last,email
  limit (select lim from params)
),
identity_json as (
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'email',m.email,
    'display_name',m.display_name,
    'domain',m.domain,
    'sender_class',m.sender_class,
    'identity_status',m.identity_status,
    'identity_confidence',m.identity_confidence,
    'needs_review',m.needs_review,
    'secondary_contact_conflict',m.secondary_contact_conflict,
    'message_stats',jsonb_build_object(
      'message_count',m.message_count,'incoming',m.incoming_count,'outgoing',m.outgoing_count,
      'threads',m.thread_count,'linked_project_messages',m.linked_project_messages,
      'unresolved_messages',m.unresolved_messages,'first_seen_at',m.first_seen_at,'last_seen_at',m.last_seen_at
    ),
    'canonical_contact',case when m.contact_id is not null then jsonb_strip_nulls(jsonb_build_object(
      'contact_id',m.contact_id,'person',m.contact_person,'company',m.contact_company,
      'kind',m.contact_kind,'role',m.contact_role,'country',m.contact_country,
      'project_email_count',m.project_email_count,'projects',m.contact_projects
    )) end,
    'canonical_partner',case when m.exact_partner_count=1 then jsonb_strip_nulls(jsonb_build_object(
      'partner_id',m.exact_partner_id,'name',m.exact_partner_name,'relation',m.exact_partner_relation,
      'business_type',m.exact_partner_business_type,'country',m.exact_partner_country,
      'match_method','exact_partner_contact'
    )) end,
    'company_hint',case
      when m.exact_partner_count=1 then null
      when m.domain_partner_count=1 then jsonb_build_object('name',m.domain_partner_name,'partner_id',m.domain_partner_id,'method','unique_partner_contact_domain','confidence',82)
      when m.domain_company_count=1 then jsonb_build_object('name',m.domain_company_name,'method','unique_contact_company_domain','confidence',78)
      else null end,
    'query_match_score',m.query_match_score,
    'project_identity_allowed',false,
    'raw_email_may_assign_role',false
  )) order by m.query_match_score desc,m.last_seen_at desc nulls last,m.email),'[]'::jsonb) as value
  from matched m
)
select jsonb_build_object(
  'query',p_query,
  'read_only',true,
  'generated_at',now(),
  'policy',jsonb_build_object(
    'exact_partner_contact_precedence',true,
    'domain_matches_are_hints_only',true,
    'contact_uniqueness_may_assign_project',false,
    'domain_hint_may_assign_project',false,
    'raw_email_may_assign_client_supplier_role',false,
    'project_identity_allowed',false
  ),
  'match_counts',jsonb_build_object(
    'returned',(select count(*) from matched),
    'canonical_partner_contact',(select count(*) from matched where identity_status='canonical_partner_contact'),
    'canonical_contact',(select count(*) from matched where identity_status='canonical_contact'),
    'partner_domain_hint',(select count(*) from matched where identity_status='partner_domain_hint'),
    'company_domain_hint',(select count(*) from matched where identity_status='company_domain_hint'),
    'unresolved_external',(select count(*) from matched where identity_status='unresolved_external'),
    'system',(select count(*) from matched where identity_status='system'),
    'internal',(select count(*) from matched where identity_status='internal'),
    'secondary_contact_conflicts',(select count(*) from matched where secondary_contact_conflict)
  ),
  'identities',(select value from identity_json)
);
$$;


ALTER FUNCTION public.pppp_chatgpt_email_identity_resolution_v1(p_query text, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_entity_integrity_v2(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_entity_integrity_v2(p_query text DEFAULT ''::text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with params as (
  select lower(btrim(coalesce(p_query,''))) as q,
         greatest(1,least(coalesce(p_limit,100),250)) as lim
),
contact_rows as (
  select lower(btrim(c.email)) as email,
         c.contact_id,c.kind,c.company,c.person,c.role,c.country,
         c.project_email_count,c.projects
  from public.pppp_contact_master_v1 c
  where nullif(btrim(coalesce(c.email,'')),'') is not null
),
contact_counts as (
  select email,count(*)::int as contact_count
  from contact_rows
  group by email
),
partner_groups as (
  select lower(btrim(x.email)) as email,
         count(distinct pc.partner_id)::int as partner_count,
         min(pc.partner_id::text)::uuid as partner_id,
         bool_or(coalesce(pc.is_primary,false)) as is_primary
  from public.partner_contacts pc
  join public.partners p on p.id=pc.partner_id and p.stage='active'
  cross join lateral (values(pc.email),(pc.email_alt)) x(email)
  where nullif(btrim(coalesce(x.email,'')),'') is not null
  group by lower(btrim(x.email))
),
partner_exact as (
  select g.email,g.partner_count,g.partner_id,g.is_primary,
         p.name as partner_name,p.relation,p.business_type,p.country as partner_country
  from partner_groups g
  left join public.partners p on p.id=g.partner_id and g.partner_count=1
),
overlap_base as (
  select c.*,cc.contact_count,
         pe.partner_count,pe.partner_id,pe.is_primary,pe.partner_name,
         pe.relation as partner_relation,pe.business_type as partner_business_type,
         pe.partner_country,
         lower(split_part(c.email,'@',2)) as email_domain,
         public.pppp_gc_normalize_company_v1(c.company) as contact_company_norm,
         public.pppp_gc_normalize_company_v1(pe.partner_name) as partner_name_norm
  from contact_rows c
  join contact_counts cc using(email)
  join partner_exact pe using(email)
),
company_reuse as (
  select public.pppp_gc_normalize_company_v1(c.company) as company_norm,
         count(distinct pe.partner_id)::int as mapped_partner_count
  from contact_rows c
  join partner_exact pe using(email)
  where pe.partner_count=1
    and nullif(public.pppp_gc_normalize_company_v1(c.company),'') is not null
  group by public.pppp_gc_normalize_company_v1(c.company)
),
classified as (
  select b.*,
    coalesce(cr.mapped_partner_count,0) as contact_company_partner_count,
    (b.partner_count=1) as unique_partner_authority,
    (b.contact_count>1) as contact_email_duplicate,
    (b.partner_count>1) as partner_email_ambiguous,
    (
      b.partner_count=1
      and coalesce(b.kind,'')='client'
      and coalesce(b.partner_relation,array[]::text[])
          && array['supplier','manufacturer','subcontractor']::text[]
    ) as supplier_role_conflict,
    (
      b.partner_count=1
      and coalesce(b.kind,'')='supplier'
      and coalesce(b.partner_relation,array[]::text[])
          && array['buyer','client']::text[]
    ) as buyer_role_conflict,
    (
      b.partner_count=1
      and nullif(b.contact_company_norm,'') is not null
      and nullif(b.partner_name_norm,'') is not null
      and b.contact_company_norm is distinct from b.partner_name_norm
      and position(b.contact_company_norm in b.partner_name_norm)=0
      and position(b.partner_name_norm in b.contact_company_norm)=0
    ) as company_label_review,
    (
      coalesce(b.company,'')=''
      or lower(coalesce(b.company,''))=b.email_domain
    ) as company_sparse_or_domain,
    (
      nullif(b.person,'') is not null
      and lower(btrim(b.person))=b.email
    ) as person_is_email,
    (
      coalesce(cr.mapped_partner_count,0)>1
    ) as reused_company_across_partners
  from overlap_base b
  left join company_reuse cr
    on cr.company_norm=b.contact_company_norm
),
scored as (
  select c.*,
    case
      when c.contact_email_duplicate or c.partner_email_ambiguous then 'high'
      when c.supplier_role_conflict or c.buyer_role_conflict or c.reused_company_across_partners then 'high'
      when c.company_label_review or c.company_sparse_or_domain or c.person_is_email then 'medium'
      else 'consistent'
    end as severity,
    case
      when c.unique_partner_authority then 'partner_registry'
      else 'manual_review'
    end as identity_authority,
    case
      when c.partner_count=1 and coalesce(c.partner_relation,array[]::text[])
           && array['supplier','manufacturer','subcontractor']::text[] then 'supplier'
      when c.partner_count=1 and coalesce(c.partner_relation,array[]::text[])
           && array['buyer','client']::text[] then 'client'
      else c.kind
    end as suggested_contact_kind,
    case when c.partner_count=1 then c.partner_name else null end as suggested_company,
    array_remove(array[
      case when c.contact_email_duplicate then 'contact_email_duplicate' end,
      case when c.partner_email_ambiguous then 'partner_email_ambiguous' end,
      case when c.supplier_role_conflict then 'contact_kind_client_vs_partner_supplier' end,
      case when c.buyer_role_conflict then 'contact_kind_supplier_vs_partner_buyer' end,
      case when c.company_label_review then 'contact_company_vs_partner_name_review' end,
      case when c.reused_company_across_partners then 'contact_company_reused_across_multiple_partners' end,
      case when c.company_sparse_or_domain then 'contact_company_sparse_or_domain_placeholder' end,
      case when c.person_is_email then 'contact_person_is_email_placeholder' end
    ],null)::text[] as issues,
    greatest(
      case when c.email=(select q from params) then 100 else 0 end,
      case when length((select q from params))>=3 and c.email like '%'||(select q from params)||'%' then 95 else 0 end,
      case when length((select q from params))>=3 and lower(coalesce(c.person,'')) like '%'||(select q from params)||'%' then 92 else 0 end,
      case when length((select q from params))>=3 and lower(coalesce(c.company,'')) like '%'||(select q from params)||'%' then 90 else 0 end,
      case when length((select q from params))>=3 and lower(coalesce(c.partner_name,'')) like '%'||(select q from params)||'%' then 94 else 0 end
    ) as query_match_score
  from classified c
),
matched as (
  select * from scored
  where (select q from params)='' or query_match_score>0
),
limited as (
  select * from matched
  order by
    case severity when 'high' then 0 when 'medium' then 1 else 2 end,
    query_match_score desc,email
  limit (select lim from params)
),
items as (
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'email',l.email,
    'severity',l.severity,
    'issues',to_jsonb(l.issues),
    'identity_authority',l.identity_authority,
    'partner_authority',case when l.partner_count=1 then jsonb_strip_nulls(jsonb_build_object(
      'partner_id',l.partner_id,'name',l.partner_name,'relation',l.partner_relation,
      'business_type',l.partner_business_type,'country',l.partner_country,
      'match_method','exact_unique_active_partner_contact'
    )) end,
    'contact_master',jsonb_strip_nulls(jsonb_build_object(
      'contact_id',l.contact_id,'kind',l.kind,'company',l.company,'person',l.person,
      'role',l.role,'country',l.country,'project_email_count',l.project_email_count,'projects',l.projects
    )),
    'suggested_reconciliation',jsonb_strip_nulls(jsonb_build_object(
      'suggested_kind',l.suggested_contact_kind,
      'suggested_company',l.suggested_company,
      'source','partner_registry_precedence',
      'apply_automatically',false,
      'requires_human_review',l.severity<>'consistent'
    )),
    'flags',jsonb_build_object(
      'contact_email_duplicate',l.contact_email_duplicate,
      'partner_email_ambiguous',l.partner_email_ambiguous,
      'supplier_role_conflict',l.supplier_role_conflict,
      'buyer_role_conflict',l.buyer_role_conflict,
      'company_label_review',l.company_label_review,
      'company_sparse_or_domain',l.company_sparse_or_domain,
      'person_is_email',l.person_is_email,
      'reused_company_across_partners',l.reused_company_across_partners
    ),
    'query_match_score',l.query_match_score
  )) order by case l.severity when 'high' then 0 when 'medium' then 1 else 2 end,l.query_match_score desc,l.email),'[]'::jsonb) as value
  from limited l
)
select jsonb_build_object(
  'integrity_version',2,
  'query',p_query,
  'read_only',true,
  'generated_at',now(),
  'policy',jsonb_build_object(
    'exact_unique_partner_contact_is_primary_identity_authority',true,
    'contact_master_is_secondary_when_conflicting',true,
    'company_label_difference_is_review_signal_not_auto_correction',true,
    'may_mutate_contacts',false,
    'may_mutate_partners',false,
    'may_assign_project',false,
    'may_change_client_supplier_role',false,
    'auto_reconciliation_allowed',false,
    'protected_human_gates_preserved',true
  ),
  'stats',jsonb_build_object(
    'cross_registry_overlaps',(select count(*) from scored),
    'returned',(select count(*) from limited),
    'high',(select count(*) from scored where severity='high'),
    'medium',(select count(*) from scored where severity='medium'),
    'consistent',(select count(*) from scored where severity='consistent'),
    'supplier_role_conflicts',(select count(*) from scored where supplier_role_conflict),
    'buyer_role_conflicts',(select count(*) from scored where buyer_role_conflict),
    'company_label_review',(select count(*) from scored where company_label_review),
    'company_sparse_or_domain',(select count(*) from scored where company_sparse_or_domain),
    'reused_company_across_partners',(select count(*) from scored where reused_company_across_partners),
    'contact_email_duplicates',(select count(*) from scored where contact_email_duplicate),
    'partner_email_ambiguities',(select count(*) from scored where partner_email_ambiguous)
  ),
  'items',(select value from items)
);
$$;


ALTER FUNCTION public.pppp_chatgpt_entity_integrity_v2(p_query text, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_entity_intelligence_v1(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_entity_intelligence_v1(p_query text, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with params as (
  select btrim(coalesce(p_query,'')) as q,lower(btrim(coalesce(p_query,''))) as ql,
         public.pppp_gc_normalize_company_v1(p_query) as qn,greatest(1,least(coalesce(p_limit,10),20)) as lim
),
partner_candidates as (
  select p.*,greatest(
    case when lower(coalesce(p.name,''))=(select ql from params) then 100 else 0 end,
    case when exists(select 1 from unnest(coalesce(p.aliases,'{}'::text[])) a where lower(a)=(select ql from params)) then 98 else 0 end,
    case when (select qn from params) is not null and length((select qn from params))>=3 and public.pppp_gc_normalize_company_v1(p.name)=(select qn from params) then 96 else 0 end,
    case when length((select ql from params))>=3 and lower(coalesce(p.name,'')) like '%'||(select ql from params)||'%' then 86 else 0 end,
    case when length((select ql from params))>=3 and exists(select 1 from unnest(coalesce(p.aliases,'{}'::text[])) a where lower(a) like '%'||(select ql from params)||'%') then 84 else 0 end,
    case when length((select ql from params))>=4 and lower(coalesce(p.website,'')) like '%'||(select ql from params)||'%' then 82 else 0 end
  ) as match_score from public.partners p where (select q from params)<>''
),
matched_partners as (select * from partner_candidates where match_score>0 order by match_score desc,importance desc nulls last,name limit (select lim from params)),
people_candidates as (
  select c.*,greatest(
    case when lower(coalesce(c.email,''))=(select ql from params) then 100 else 0 end,
    case when lower(coalesce(c.person,''))=(select ql from params) then 98 else 0 end,
    case when (select qn from params) is not null and length((select qn from params))>=3 and public.pppp_gc_normalize_company_v1(c.company)=(select qn from params) then 94 else 0 end,
    case when length((select ql from params))>=3 and lower(coalesce(c.person,'')) like '%'||(select ql from params)||'%' then 88 else 0 end,
    case when length((select ql from params))>=3 and lower(coalesce(c.company,'')) like '%'||(select ql from params)||'%' then 86 else 0 end,
    case when length((select ql from params))>=4 and lower(coalesce(c.email,'')) like '%'||(select ql from params)||'%' then 84 else 0 end
  ) as match_score from public.pppp_contact_master_v1 c where (select q from params)<>''
),
matched_people as (select * from people_candidates where match_score>0 order by match_score desc,project_email_count desc nulls last,last_seen_at desc nulls last limit (select lim from params)*2),
seed_emails as (
  select lower(email) email from matched_people where nullif(btrim(email),'') is not null
  union select lower(pc.email) from public.partner_contacts pc where pc.partner_id in(select id from matched_partners) and nullif(btrim(pc.email),'') is not null
  union select lower(pc.email_alt) from public.partner_contacts pc where pc.partner_id in(select id from matched_partners) and nullif(btrim(pc.email_alt),'') is not null
),
project_candidates as (
  select p.id,100 match_score,'direct_exact'::text reason from public.projects p,params x where x.q<>'' and (lower(coalesce(p.name,''))=x.ql or lower(coalesce(p.ref,''))=x.ql or lower(coalesce(p.business_ref,''))=x.ql)
  union all select p.id,94,'normalized_client' from public.projects p,params x where x.qn is not null and length(x.qn)>=3 and public.pppp_gc_normalize_company_v1(p.client)=x.qn
  union all select p.id,92,'partner_client' from public.projects p join matched_partners mp on public.pppp_gc_normalize_company_v1(p.client)=public.pppp_gc_normalize_company_v1(mp.name) where public.pppp_gc_normalize_company_v1(mp.name) is not null
  union all select p.id,90,'contact_email' from public.projects p join public.project_contacts pc on pc.project_id=p.id::text join seed_emails se on lower(coalesce(pc.email,''))=se.email
  union all select p.id,88,'contact_company' from public.projects p join public.project_contacts pc on pc.project_id=p.id::text join matched_partners mp on public.pppp_gc_normalize_company_v1(pc.company)=public.pppp_gc_normalize_company_v1(mp.name) where public.pppp_gc_normalize_company_v1(mp.name) is not null
  union all select p.id,82,'text_contains' from public.projects p,params x where length(x.ql)>=3 and (lower(coalesce(p.name,'')) like '%'||x.ql||'%' or lower(coalesce(p.client,'')) like '%'||x.ql||'%' or lower(coalesce(p.ref,'')) like '%'||x.ql||'%' or lower(coalesce(p.business_ref,'')) like '%'||x.ql||'%')
),
related_project_scores as (
  select pc.id,max(pc.match_score) match_score,string_agg(distinct pc.reason,',' order by pc.reason) match_reasons from project_candidates pc group by pc.id order by max(pc.match_score) desc,pc.id limit (select lim from params)*2
),
related_projects as (
  select p.*,rps.match_score,rps.match_reasons,
         coalesce(mf.value->>'summary',pa.analysis->>'executive_summary') memory_summary,
         case when mf.value is not null then 'project.memory.baseline.v1' when pa.analysis is not null then 'latest_project_analysis' else null end memory_source,
         mf.value->'communication' memory_communication,coalesce(mf.updated_at,pa.created_at) memory_updated_at
  from related_project_scores rps join public.projects p on p.id=rps.id
  left join public.pppp_project_context_current_v mf on mf.project_id=p.id and mf.fact_key='project.memory.baseline.v1' and mf.fact_status='observed'
  left join lateral (select a.analysis,a.created_at from public.project_analyses a where a.project_id=p.id::text and a.status='complete' order by a.created_at desc limit 1) pa on true
),
direct_entity_emails as (
  select e.* from public.project_emails e where lower(coalesce(e.from_email,'')) in(select email from seed_emails)
     or exists(select 1 from unnest(coalesce(e.to_emails,'{}'::text[])) x(email) where lower(x.email) in(select email from seed_emails))
     or exists(select 1 from unnest(coalesce(e.cc_emails,'{}'::text[])) x(email) where lower(x.email) in(select email from seed_emails))
),
project_context_emails as (select e.* from public.project_emails e where e.project_id in(select id from related_projects)),
direct_email_stats as (select count(*)::int total,count(*) filter(where direction='incoming')::int incoming,count(*) filter(where direction='outgoing')::int outgoing,count(distinct gmail_thread_id)::int threads,min(sent_at) first_email_at,max(sent_at) last_email_at from direct_entity_emails),
project_email_stats as (select count(*)::int total,count(*) filter(where direction='incoming')::int incoming,count(*) filter(where direction='outgoing')::int outgoing,count(distinct gmail_thread_id)::int threads,min(sent_at) first_email_at,max(sent_at) last_email_at from project_context_emails),
matched_supplier_offers as (
  select o.*,p.name project_name from public.offers o left join public.projects p on p.id=o.project_id
  where coalesce(o.supplier,'') !~* '(pristeel|oferta[[:space:]]+jone|our[[:space:]]+offer)'
    and (o.project_id in(select id from related_projects)
      or ((select qn from params) is not null and length((select qn from params))>=3 and public.pppp_gc_normalize_company_v1(o.supplier)=(select qn from params))
      or exists(select 1 from matched_partners mp where public.pppp_gc_normalize_company_v1(o.supplier)=public.pppp_gc_normalize_company_v1(mp.name)))
  order by o.created_at desc limit (select lim from params)*3
),
matched_client_offers as (
  select d.id,d.project_id,p.name project_name,d.doc_nr,d.client,d.currency,d.total_amount,d.total_eur,d.followup_status,d.last_followup_at,d.followup_count,d.created_at
  from public.documents_registry d left join public.projects p on p.id=d.project_id
  where d.project_id in(select id from related_projects) and upper(coalesce(d.series,''))='QUO'
  order by d.created_at desc limit (select lim from params)*3
),
partner_json as (
 select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',mp.id,'name',mp.name,'aliases',mp.aliases,'country',mp.country,'city',mp.city,'website',mp.website,'business_type',mp.business_type,'relation',mp.relation,'categories',mp.categories,'grades',mp.grades,'class_approval',mp.class_approval,'certifications',mp.certifications,'length_max_mm',mp.length_max_mm,'width_max_mm',mp.width_max_mm,'thickness_min_mm',mp.thickness_min_mm,'thickness_max_mm',mp.thickness_max_mm,'origin_countries',mp.origin_countries,'cbam_eur_per_t',mp.cbam_eur_per_t,'price_indicative',mp.price_indicative,'payment_terms',mp.payment_terms,'lead_time_days',mp.lead_time_days,'stage',mp.stage,'importance',mp.importance,'importance_reason',mp.importance_reason,'data_confidence',mp.data_confidence,'notes',mp.notes,'source',mp.source,'match_score',mp.match_score,'contacts',coalesce((select jsonb_agg(to_jsonb(x) order by x.is_primary desc nulls last,x.full_name,x.email) from (select pc.full_name,pc.email,pc.email_alt,pc.phone,pc.role,pc.language,pc.is_primary,pc.last_contact_at,pc.next_action,pc.next_action_date,pc.notes from public.partner_contacts pc where pc.partner_id=mp.id order by pc.is_primary desc nulls last,pc.created_at limit 30) x),'[]'::jsonb))) order by mp.match_score desc,mp.importance desc nulls last,mp.name),'[]'::jsonb) value from matched_partners mp
),
people_json as (
 select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('contact_id',m.contact_id,'kind',m.kind,'company',m.company,'person',m.person,'email',m.email,'phone',m.phone,'country',m.country,'role',m.role,'last_contact',m.last_contact,'project_email_count',m.project_email_count,'last_seen_at',m.last_seen_at,'projects',m.projects,'sources',m.sources,'match_score',m.match_score)) order by m.match_score desc,m.project_email_count desc nulls last,m.last_seen_at desc nulls last),'[]'::jsonb) value from matched_people m
),
projects_json as (
 select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',p.id,'name',p.name,'client',p.client,'reference',p.ref,'business_ref',p.business_ref,'location',p.location,'deadline',p.deadline,'status',p.status,'pipeline_stage',p.pipeline_stage,'operational_state',p.operational_state,'operational_state_at',p.operational_state_at,'origin_type',p.origin_type,'work_model',p.work_model,'deal_type',p.deal_type,'business_type',p.business_type,'last_activity_at',p.last_activity_at,'last_email_at',p.last_email_at,'match_score',p.match_score,'match_reasons',p.match_reasons,'memory_summary',p.memory_summary,'memory_source',p.memory_source,'memory_communication',p.memory_communication,'memory_updated_at',p.memory_updated_at)) order by p.match_score desc,p.last_activity_at desc nulls last,p.name),'[]'::jsonb) value from related_projects p
),
direct_recent_json as (
 select coalesce(jsonb_agg(to_jsonb(x) order by x.sent_at desc),'[]'::jsonb) value from (select e.project_id,p.name project_name,e.gmail_message_id,e.gmail_thread_id,e.direction,e.from_email,e.from_name,e.to_emails,e.cc_emails,e.subject,left(coalesce(e.snippet,''),1600) snippet,e.sent_at,e.has_attachments,e.match_method,e.match_confidence from direct_entity_emails e left join public.projects p on p.id=e.project_id order by e.sent_at desc limit (select lim from params)*2) x
),
project_recent_json as (
 select coalesce(jsonb_agg(to_jsonb(x) order by x.sent_at desc),'[]'::jsonb) value from (select e.project_id,p.name project_name,e.gmail_message_id,e.gmail_thread_id,e.direction,e.from_email,e.from_name,e.to_emails,e.cc_emails,e.subject,left(coalesce(e.snippet,''),1200) snippet,e.sent_at,e.has_attachments,e.match_method,e.match_confidence from project_context_emails e left join public.projects p on p.id=e.project_id order by e.sent_at desc limit (select lim from params)*2) x
),
offers_json as (
 select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) value from (select id,project_id,project_name,supplier,currency,pricing_unit,price_kg,unit_price,qty_kg,total_amount,total_eur,delivery_weeks,incoterms,payment_terms,validity_days,cert,offer_ref,contact_person,transport_eur,exchange_rate_to_eur,left(coalesce(notes,''),1200) notes,created_at from matched_supplier_offers order by created_at desc) x
),
client_offers_json as (select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) value from matched_client_offers x),
actions_json as (
 select coalesce(jsonb_agg(to_jsonb(x) order by x.due_date nulls last,x.created_at desc),'[]'::jsonb) value from (select a.id,a.project_id,a.project_name,a.client,a.title,a.detail,a.due_date,a.priority,a.source,a.source_ref,a.category,a.operational_state,a.pipeline_stage,a.created_at from public.pppp_home_current_actions_v1 a where a.project_id in(select id from related_projects) order by a.due_date nulls last,a.created_at desc limit (select lim from params)*2) x
),
attention_json as (
 select coalesce(jsonb_agg(jsonb_build_object('type','action_required_without_current_action','severity','high','project_id',p.id,'project_name',p.name,'message','Projekti është në operational_state=action_required por nuk ka veprim canonical në Home/priority actions.') order by p.last_activity_at desc nulls last),'[]'::jsonb) value
 from related_projects p where lower(coalesce(p.operational_state,''))='action_required' and not exists(select 1 from public.pppp_home_current_actions_v1 a where a.project_id=p.id)
)
select jsonb_build_object(
 'query',(select q from params),'normalized_query',(select qn from params),'read_only',true,'generated_at',now(),
 'match_counts',jsonb_build_object('partners',(select count(*) from matched_partners),'people',(select count(*) from matched_people),'projects',(select count(*) from related_projects),'direct_emails',(select total from direct_email_stats),'project_context_emails',(select total from project_email_stats),'supplier_offers',(select count(*) from matched_supplier_offers),'client_offers',(select count(*) from matched_client_offers),'current_actions',(select jsonb_array_length(value) from actions_json),'attention_flags',(select jsonb_array_length(value) from attention_json)),
 'relationship_summary',case when (select q from params)='' then 'Kërkimi është bosh.' when (select count(*) from matched_partners)+(select count(*) from matched_people)+(select count(*) from related_projects)=0 then 'Nuk u gjet evidencë e lidhur në PPPP për këtë kërkim.' else concat('PPPP gjeti ',(select count(*) from matched_partners),' profile partneri, ',(select count(*) from matched_people),' persona/kontakte dhe ',(select count(*) from related_projects),' projekte të lidhura. Komunikim direkt me entitetin: ',(select total from direct_email_stats),' email-e; kontekst i projekteve të lidhura: ',(select total from project_email_stats),' email-e.') end,
 'partners',(select value from partner_json),'people',(select value from people_json),'projects',(select value from projects_json),
 'communication',jsonb_build_object('direct_entity',jsonb_build_object('total_emails',(select total from direct_email_stats),'incoming',(select incoming from direct_email_stats),'outgoing',(select outgoing from direct_email_stats),'threads',(select threads from direct_email_stats),'first_email_at',(select first_email_at from direct_email_stats),'last_email_at',(select last_email_at from direct_email_stats),'recent_emails',(select value from direct_recent_json)),'project_context',jsonb_build_object('total_emails',(select total from project_email_stats),'incoming',(select incoming from project_email_stats),'outgoing',(select outgoing from project_email_stats),'threads',(select threads from project_email_stats),'first_email_at',(select first_email_at from project_email_stats),'last_email_at',(select last_email_at from project_email_stats),'recent_emails',(select value from project_recent_json))),
 'supplier_offers',(select value from offers_json),'client_offers',(select value from client_offers_json),'current_actions',(select value from actions_json),'attention_flags',(select value from attention_json)
);
$$;


ALTER FUNCTION public.pppp_chatgpt_entity_intelligence_v1(p_query text, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION pppp_chatgpt_entity_intelligence_v1(p_query text, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_chatgpt_entity_intelligence_v1(p_query text, p_limit integer) IS 'Read-only PPPP entity intelligence. Separates direct entity communication from project context, supplier quotes from PRISTEEL client offers, and exposes non-mutating attention flags.';


--
-- Name: pppp_chatgpt_entity_intelligence_v2(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_entity_intelligence_v2(p_query text, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with canonical as (
  select public.pppp_chatgpt_entity_intelligence_v1(p_query,p_limit) as j
), raw as (
  select public.pppp_chatgpt_email_entity_evidence_v1(p_query,p_limit) as j
), metrics as (
  select
    coalesce((c.j#>>'{match_counts,partners}')::int,0) as partners,
    coalesce((c.j#>>'{match_counts,people}')::int,0) as people,
    coalesce((c.j#>>'{match_counts,projects}')::int,0) as projects,
    coalesce((r.j#>>'{stats,total_emails}')::int,0) as raw_total,
    coalesce((r.j#>>'{stats,linked_to_project}')::int,0) as raw_linked,
    coalesce((r.j#>>'{stats,suggested_project}')::int,0) as raw_suggested,
    coalesce((r.j#>>'{stats,unresolved}')::int,0) as raw_unresolved,
    coalesce((r.j#>>'{stats,best_match_score}')::int,0) as raw_best_score,
    coalesce((
      select bool_or(coalesce((x->>'needs_review')::boolean,false))
      from jsonb_array_elements(coalesce(r.j->'recent_emails','[]'::jsonb)) x
    ),false) as raw_needs_review
  from canonical c cross join raw r
)
select c.j || jsonb_build_object(
  'entity_intelligence_version',2,
  'identity_status',case
    when m.partners+m.people+m.projects>0 then 'canonical'
    when m.raw_total>0 then 'evidence_only'
    else 'none'
  end,
  'evidence_summary',jsonb_build_object(
    'canonical_match_count',m.partners+m.people+m.projects,
    'raw_email_total',m.raw_total,
    'raw_linked_to_project',m.raw_linked,
    'raw_suggested_project',m.raw_suggested,
    'raw_unresolved',m.raw_unresolved,
    'raw_best_match_score',m.raw_best_score,
    'review_required',m.raw_needs_review or m.raw_unresolved>0 or m.raw_suggested>0,
    'raw_evidence_used_for_identity',false
  ),
  'raw_email_evidence',r.j,
  'evidence_policy',jsonb_build_object(
    'canonical_truth_source','public.pppp_chatgpt_entity_intelligence_v1(text,integer)',
    'raw_evidence_source','public.pppp_chatgpt_email_entity_evidence_v1(text,integer)',
    'raw_evidence_may_assign_person_role',false,
    'raw_evidence_may_assign_company_role',false,
    'raw_evidence_may_auto_link_project',false,
    'raw_evidence_may_create_task_or_action',false,
    'raw_evidence_may_change_project_state',false,
    'human_approval_gates_preserved',true,
    'note','Raw email evidence is contextual evidence only. Canonical partner/person/project relationships come only from the v1 canonical intelligence layer.'
  )
)
from canonical c cross join raw r cross join metrics m;
$$;


ALTER FUNCTION public.pppp_chatgpt_entity_intelligence_v2(p_query text, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_entity_intelligence_v3(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_entity_intelligence_v3(p_query text, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with base as (
  select public.pppp_chatgpt_entity_intelligence_v2(p_query,p_limit) as j
), identity as (
  select public.pppp_chatgpt_email_identity_resolution_v1(p_query,p_limit) as j
), integrity as (
  select public.pppp_chatgpt_entity_integrity_v2(p_query,p_limit) as j
)
select b.j || jsonb_build_object(
  'entity_intelligence_version',3,
  'neutral_identity_resolution',i.j,
  'contact_integrity',g.j,
  'identity_authority_policy',jsonb_build_object(
    'exact_unique_partner_contact_precedence',true,
    'contact_master_person_role_retained_as_secondary_evidence',true,
    'conflicting_contact_master_company_or_kind_is_not_authoritative',true,
    'domain_only_identity_is_hint_only',true,
    'raw_email_evidence_is_context_only',true,
    'no_automatic_contact_rewrite',true,
    'no_project_assignment_from_identity',true,
    'human_review_required_for_reconciliation',true
  )
)
from base b cross join identity i cross join integrity g;
$$;


ALTER FUNCTION public.pppp_chatgpt_entity_intelligence_v3(p_query text, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_eu_direct_targets_v1(text, boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_eu_direct_targets_v1(p_query text DEFAULT NULL::text, p_include_archived boolean DEFAULT false, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  with filtered as (
    select v.*
    from public.pppp_eu_direct_operational_v1 v
    where (coalesce(p_include_archived,false) or v.archived_at is null)
      and (
        nullif(btrim(p_query),'') is null
        or v.company_name ilike '%'||btrim(p_query)||'%'
        or v.company_domain_normalized=public.pppp_normalize_company_domain_v1(p_query)
        or v.contact_email ilike '%'||btrim(p_query)||'%'
        or v.source_key=btrim(p_query)
      )
    order by v.priority_score desc, v.updated_at desc
    limit least(500,greatest(1,coalesce(p_limit,100)))
  )
  select jsonb_build_object(
    'ok',true,
    'count',(select count(*) from filtered),
    'targets',coalesce((select jsonb_agg(to_jsonb(f) order by f.priority_score desc,f.updated_at desc) from filtered f),'[]'::jsonb),
    'routing',jsonb_build_object(
      'opportunities','Tenderë/projekte konkrete; TED jashtë Kosovës përdoret për ndjekjen e fituesve, ndërsa tenderët e Kosovës mund të ndiqen për pjesëmarrje direkte ose partneritet.',
      'material_trade','Vetëm blerës të lëndës së parë: pllaka, tuba, profile, trarë, shufra dhe materiale të ngjashme.',
      'representations','Prodhues ose kompani për përfaqësim, partner lokal, JV, konsorcium ose hyrje në tregun e Kosovës/Ballkanit.',
      'eu_direct','Klientë të drejtpërdrejtë në Evropë për paketa çeliku të fabrikuar, kapacitet prodhues ose nënkontraktim, kur nuk hyjnë në tri grupet e tjera.'
    ),
    'human_gates',jsonb_build_object('external_email_send',true,'project_creation',true,'commercial_commitment',true)
  );
$$;


ALTER FUNCTION public.pppp_chatgpt_eu_direct_targets_v1(p_query text, p_include_archived boolean, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_finance_intelligence_v1(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_finance_intelligence_v1(p_days integer DEFAULT 30, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_days integer := greatest(1,least(coalesce(p_days,30),180));
  v_limit integer := greatest(5,least(coalesce(p_limit,25),100));
  v_receivable_summary jsonb := '[]'::jsonb;
  v_payable_summary jsonb := '[]'::jsonb;
  v_expense_summary jsonb := '[]'::jsonb;
  v_overdue_receivables jsonb := '[]'::jsonb;
  v_payables_missing_due jsonb := '[]'::jsonb;
  v_expenses_unpaid jsonb := '[]'::jsonb;
  v_guarantees jsonb := '[]'::jsonb;
  v_invoice_pipeline jsonb := '[]'::jsonb;
  v_candidate_statuses jsonb := '[]'::jsonb;
  v_project_timing jsonb := '[]'::jsonb;
  v_attention jsonb := '[]'::jsonb;
  v_open_receivable_count integer := 0;
  v_overdue_receivable_count integer := 0;
  v_open_payable_count integer := 0;
  v_payable_missing_due_count integer := 0;
  v_unpaid_expense_count integer := 0;
  v_open_guarantee_count integer := 0;
  v_invoice_pipeline_count integer := 0;
  v_attention_count integer := 0;
begin
  with src as (
    select coalesce(nullif(trim(currency),''),'EUR') currency,
           coalesce(gross_amount,total_price,net_amount,0)::numeric amount,
           due_date
    from public.invoices_out
    where coalesce(paid,false)=false
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'currency',currency,
           'open_amount',open_amount,
           'open_count',open_count,
           'overdue_amount',overdue_amount,
           'overdue_count',overdue_count,
           'not_yet_due_amount',not_yet_due_amount,
           'missing_due_date_count',missing_due_date_count
         ) order by currency),'[]'::jsonb)
  into v_receivable_summary
  from (
    select currency,
           sum(amount) open_amount,
           count(*)::int open_count,
           sum(amount) filter(where due_date < current_date) overdue_amount,
           count(*) filter(where due_date < current_date)::int overdue_count,
           sum(amount) filter(where due_date >= current_date) not_yet_due_amount,
           count(*) filter(where due_date is null)::int missing_due_date_count
    from src group by currency
  ) x;

  with src as (
    select coalesce(nullif(trim(currency),''),'EUR') currency,
           coalesce(amount,0)::numeric amount,
           due_date
    from public.invoices_in
    where coalesce(paid,false)=false
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'currency',currency,
           'open_amount',open_amount,
           'open_count',open_count,
           'overdue_amount',overdue_amount,
           'overdue_count',overdue_count,
           'not_yet_due_amount',not_yet_due_amount,
           'missing_due_date_count',missing_due_date_count
         ) order by currency),'[]'::jsonb)
  into v_payable_summary
  from (
    select currency,
           sum(amount) open_amount,
           count(*)::int open_count,
           sum(amount) filter(where due_date < current_date) overdue_amount,
           count(*) filter(where due_date < current_date)::int overdue_count,
           sum(amount) filter(where due_date >= current_date) not_yet_due_amount,
           count(*) filter(where due_date is null)::int missing_due_date_count
    from src group by currency
  ) x;

  with src as (
    select coalesce(nullif(trim(currency),''),'EUR') currency,
           coalesce(amount,0)::numeric amount
    from public.expenses
    where coalesce(paid,false)=false
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'currency',currency,
           'unpaid_record_amount',unpaid_amount,
           'unpaid_record_count',unpaid_count
         ) order by currency),'[]'::jsonb)
  into v_expense_summary
  from (
    select currency,sum(amount) unpaid_amount,count(*)::int unpaid_count
    from src group by currency
  ) x;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.days_overdue desc,x.amount desc),'[]'::jsonb)
  into v_overdue_receivables
  from (
    select o.id,o.invoice_nr,o.project_id,o.project,o.client,o.date,o.due_date,
           (current_date-o.due_date)::int days_overdue,
           coalesce(o.gross_amount,o.total_price,o.net_amount,0)::numeric amount,
           coalesce(nullif(trim(o.currency),''),'EUR') currency
    from public.invoices_out o
    where coalesce(o.paid,false)=false and o.due_date < current_date
    order by o.due_date,coalesce(o.gross_amount,o.total_price,o.net_amount,0) desc
    limit v_limit
  ) x;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.date nulls last,x.amount desc),'[]'::jsonb)
  into v_payables_missing_due
  from (
    select i.id,i.supplier_invoice_nr,i.project_id,i.project,i.supplier,i.date,
           coalesce(i.amount,0)::numeric amount,
           coalesce(nullif(trim(i.currency),''),'EUR') currency,
           i.payment_terms,
           'Due date is missing; this invoice is not classified as overdue until the due date is verified.'::text as interpretation
    from public.invoices_in i
    where coalesce(i.paid,false)=false and i.due_date is null
    order by i.date nulls last,i.amount desc
    limit v_limit
  ) x;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.date desc nulls last,x.amount desc),'[]'::jsonb)
  into v_expenses_unpaid
  from (
    select e.id,e.project_id,e.supplier,e.invoice_nr,e.date,e.due_date,
           coalesce(e.amount,0)::numeric amount,
           coalesce(nullif(trim(e.currency),''),'EUR') currency,e.category,
           'Expense records are reported separately from supplier invoices to avoid double counting liabilities.'::text as interpretation
    from public.expenses e
    where coalesce(e.paid,false)=false
    order by e.date desc nulls last,e.amount desc
    limit v_limit
  ) x;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.expiry_date nulls last,x.amount_guaranteed desc),'[]'::jsonb)
  into v_guarantees
  from (
    select g.id,g.project_id,g.project,g.bank_name,g.guarantee_type,
           coalesce(g.amount_guaranteed,0)::numeric amount_guaranteed,
           g.fee_rate_pct,g.fee_amount,g.issue_date,g.expiry_date,g.status,
           case when g.expiry_date is null then null else (g.expiry_date-current_date)::int end days_to_expiry,
           case
             when g.expiry_date is not null and g.expiry_date < current_date then 'expired_date_review'
             when g.expiry_date is not null and g.expiry_date <= current_date+60 then 'expiry_within_60_days'
             when g.project_id is null then 'project_link_review'
             else 'monitor'
           end attention_state
    from public.bank_guarantees g
    where lower(coalesce(g.status,'')) not in ('closed','released','expired','mbyllur','cancelled','canceled')
    order by g.expiry_date nulls last,g.amount_guaranteed desc
    limit v_limit
  ) x;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.delivery_date nulls last,x.project_name,x.milestone_index),'[]'::jsonb)
  into v_invoice_pipeline
  from (
    select m.project_id,m.project_name,m.client,m.offer_id,m.offer_doc_nr,m.milestone_index,m.milestone_label,
           m.milestone_event,m.milestone_pct,m.milestone_amount,m.currency,m.payment_days,m.delivery_date,
           m.readiness,m.readiness_reason,m.candidate_id,m.candidate_status,
           case when lower(coalesce(m.milestone_event,''))='beforedel' and m.delivery_date is not null then m.delivery_date-14
                when m.delivery_date is not null then m.delivery_date else null end as earliest_event_date,
           'Pipeline amount only: it is not an accounts receivable balance until a canonical outgoing invoice exists.'::text as accounting_treatment
    from public.pppp_outgoing_invoice_milestones_v1 m
    where m.invoice_id is null
    order by m.delivery_date nulls last,m.project_name,m.milestone_index
    limit v_limit
  ) x;

  select coalesce(jsonb_agg(jsonb_build_object('status',status,'count',cnt) order by status),'[]'::jsonb)
  into v_candidate_statuses
  from (
    select coalesce(status,'unknown') status,count(*)::int cnt
    from public.invoice_candidates
    group by coalesce(status,'unknown')
  ) x;

  with ids as (
    select project_id from public.invoices_out where project_id is not null and coalesce(paid,false)=false
    union
    select project_id from public.invoices_in where project_id is not null and coalesce(paid,false)=false
    union
    select project_id from public.bank_guarantees where project_id is not null and lower(coalesce(status,'')) not in ('closed','released','expired','mbyllur','cancelled','canceled')
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'project_id',p.id,
           'project_name',p.name,
           'client',p.client,
           'open_receivables',coalesce(r.by_currency,'[]'::jsonb),
           'open_supplier_invoices',coalesce(pi.by_currency,'[]'::jsonb),
           'open_guarantees',coalesce(bg.guarantees,'[]'::jsonb),
           'interpretation','Amounts are shown by currency and category. No cross-currency or receivable-minus-payable net is inferred.'
         ) order by p.name),'[]'::jsonb)
  into v_project_timing
  from ids
  join public.projects p on p.id=ids.project_id
  left join lateral (
    select jsonb_agg(jsonb_build_object('currency',currency,'amount',amount,'overdue_amount',overdue_amount) order by currency) by_currency
    from (
      select coalesce(nullif(trim(o.currency),''),'EUR') currency,
             sum(coalesce(o.gross_amount,o.total_price,o.net_amount,0)) amount,
             sum(coalesce(o.gross_amount,o.total_price,o.net_amount,0)) filter(where o.due_date<current_date) overdue_amount
      from public.invoices_out o where o.project_id=p.id and coalesce(o.paid,false)=false
      group by coalesce(nullif(trim(o.currency),''),'EUR')
    ) q
  ) r on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('currency',currency,'amount',amount,'missing_due_date_count',missing_due_date_count) order by currency) by_currency
    from (
      select coalesce(nullif(trim(i.currency),''),'EUR') currency,sum(coalesce(i.amount,0)) amount,
             count(*) filter(where i.due_date is null)::int missing_due_date_count
      from public.invoices_in i where i.project_id=p.id and coalesce(i.paid,false)=false
      group by coalesce(nullif(trim(i.currency),''),'EUR')
    ) q
  ) pi on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('amount_guaranteed',g.amount_guaranteed,'status',g.status,'expiry_date',g.expiry_date,'guarantee_type',g.guarantee_type) order by g.expiry_date nulls last) guarantees
    from public.bank_guarantees g
    where g.project_id=p.id and lower(coalesce(g.status,'')) not in ('closed','released','expired','mbyllur','cancelled','canceled')
  ) bg on true;

  select count(*)::int into v_open_receivable_count from public.invoices_out where coalesce(paid,false)=false;
  select count(*)::int into v_overdue_receivable_count from public.invoices_out where coalesce(paid,false)=false and due_date<current_date;
  select count(*)::int into v_open_payable_count from public.invoices_in where coalesce(paid,false)=false;
  select count(*)::int into v_payable_missing_due_count from public.invoices_in where coalesce(paid,false)=false and due_date is null;
  select count(*)::int into v_unpaid_expense_count from public.expenses where coalesce(paid,false)=false;
  select count(*)::int into v_open_guarantee_count from public.bank_guarantees where lower(coalesce(status,'')) not in ('closed','released','expired','mbyllur','cancelled','canceled');
  select count(*)::int into v_invoice_pipeline_count from public.pppp_outgoing_invoice_milestones_v1 where invoice_id is null;

  with attention_items as (
    select 100 priority_score,
           jsonb_build_object(
             'attention_id','receivable:'||o.id::text,
             'kind','overdue_receivable',
             'priority_score',100,
             'project_id',o.project_id,
             'project_name',o.project,
             'party',o.client,
             'reference',o.invoice_nr,
             'amount',coalesce(o.gross_amount,o.total_price,o.net_amount,0),
             'currency',coalesce(nullif(trim(o.currency),''),'EUR'),
             'due_date',o.due_date,
             'days_overdue',(current_date-o.due_date)::int,
             'recommended_action','Review collection status and prepare a client follow-up if appropriate.',
             'draft_preparation_allowed',true,
             'approval_gates',jsonb_build_array('external_email_send'),
             'execution_allowed',false
           ) item
    from public.invoices_out o
    where coalesce(o.paid,false)=false and o.due_date<current_date

    union all

    select 92,
           jsonb_build_object(
             'attention_id','payable-due:'||i.id::text,
             'kind','payable_missing_due_date',
             'priority_score',92,
             'project_id',i.project_id,
             'project_name',i.project,
             'party',i.supplier,
             'reference',i.supplier_invoice_nr,
             'amount',coalesce(i.amount,0),
             'currency',coalesce(nullif(trim(i.currency),''),'EUR'),
             'recommended_action','Verify payment terms and due date before payment prioritization.',
             'approval_gates','[]'::jsonb,
             'execution_allowed',false
           ) item
    from public.invoices_in i
    where coalesce(i.paid,false)=false and i.due_date is null

    union all

    select 90,
           jsonb_build_object(
             'attention_id','guarantee-expiry:'||g.id::text,
             'kind','bank_guarantee_expiry_review',
             'priority_score',90,
             'project_id',g.project_id,
             'project_name',g.project,
             'bank',g.bank_name,
             'guarantee_type',g.guarantee_type,
             'amount_guaranteed',coalesce(g.amount_guaranteed,0),
             'expiry_date',g.expiry_date,
             'days_to_expiry',(g.expiry_date-current_date)::int,
             'recommended_action','Review guarantee release/extension requirements before expiry.',
             'approval_gates',jsonb_build_array('contract_or_purchase_order_commitment'),
             'execution_allowed',false
           ) item
    from public.bank_guarantees g
    where lower(coalesce(g.status,'')) not in ('closed','released','expired','mbyllur','cancelled','canceled')
      and g.expiry_date is not null and g.expiry_date<=current_date+60

    union all

    select 78,
           jsonb_build_object(
             'attention_id','guarantee-link:'||g.id::text,
             'kind','bank_guarantee_project_link_review',
             'priority_score',78,
             'project_id',g.project_id,
             'project_name',g.project,
             'bank',g.bank_name,
             'amount_guaranteed',coalesce(g.amount_guaranteed,0),
             'recommended_action','Reconcile this guarantee with the canonical project before project-level exposure analysis.',
             'approval_gates','[]'::jsonb,
             'execution_allowed',false
           ) item
    from public.bank_guarantees g
    where lower(coalesce(g.status,'')) not in ('closed','released','expired','mbyllur','cancelled','canceled') and g.project_id is null
  ), ranked as (
    select item,priority_score,row_number() over(order by priority_score desc,item->>'attention_id') rn
    from attention_items
  )
  select coalesce(jsonb_agg(item order by priority_score desc,item->>'attention_id'),'[]'::jsonb)
  into v_attention
  from ranked where rn<=v_limit;

  v_attention_count := jsonb_array_length(v_attention);

  return jsonb_build_object(
    'finance_intelligence_version',1,
    'mode','read_only_synthesis',
    'generated_at',now(),
    'as_of_date',current_date,
    'window_days',v_days,
    'cash_balance_available',false,
    'cash_balance_note','No canonical bank-account balance source was identified in the Finance core, so Finance Intelligence v1 does not estimate cash-on-hand.',
    'summary',jsonb_build_object(
      'open_receivable_invoices',v_open_receivable_count,
      'overdue_receivable_invoices',v_overdue_receivable_count,
      'open_supplier_invoices',v_open_payable_count,
      'supplier_invoices_missing_due_date',v_payable_missing_due_count,
      'unpaid_expense_records',v_unpaid_expense_count,
      'open_bank_guarantees',v_open_guarantee_count,
      'uninvoiced_outgoing_milestones',v_invoice_pipeline_count,
      'attention_items',v_attention_count,
      'executions_performed',0
    ),
    'receivables_by_currency',v_receivable_summary,
    'supplier_payables_by_currency',v_payable_summary,
    'unpaid_expense_records_by_currency',v_expense_summary,
    'overdue_receivables',v_overdue_receivables,
    'supplier_invoices_missing_due_date',v_payables_missing_due,
    'unpaid_expense_records',v_expenses_unpaid,
    'bank_guarantees',v_guarantees,
    'outgoing_invoice_pipeline',v_invoice_pipeline,
    'invoice_candidate_statuses',v_candidate_statuses,
    'project_cash_timing',v_project_timing,
    'attention',v_attention,
    'accounting_boundaries',jsonb_build_object(
      'currencies_never_summed_without_conversion',true,
      'outgoing_milestones_are_not_receivables_until_invoiced',true,
      'expense_records_are_not_merged_with_supplier_invoices',true,
      'missing_due_date_is_not_treated_as_overdue',true,
      'cash_balance_not_inferred',true,
      'no_profit_or_margin_inference',true
    ),
    'policy',jsonb_build_object(
      'read_only',true,
      'no_finance_core_mutation',true,
      'no_payment_execution',true,
      'no_invoice_approval',true,
      'no_email_send',true,
      'no_bank_guarantee_change',true,
      'no_price_or_margin_decision',true,
      'protected_human_gates_preserved',true,
      'executions_performed',0
    )
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_finance_intelligence_v1(p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_materialize_canonical_fact_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_materialize_canonical_fact_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_project public.projects%rowtype;
  v_items jsonb;
  v_item jsonb;
  v_drafts jsonb;
  v_draft jsonb;
  v_total numeric := 0;
  v_expected numeric := 0;
  v_code text;
  v_supplier text;
  v_email text;
  v_subject text;
  v_existing uuid;
  v_notes text;
  v_rfq_status text;
begin
  if new.source_type <> 'chatgpt' or new.created_by <> 'chatgpt_pppp_bridge' then return new; end if;
  if new.fact_key not in ('canonical.bom.create.v1', 'canonical.rfq_planned.create.v1') then return new; end if;

  select * into v_project from public.projects where id = new.project_id;
  if not found then raise exception using errcode = '22023', message = 'project_not_found'; end if;
  if lower(coalesce(v_project.status,'')) in ('humbur','lost','mbyllur','closed','arkivuar','archived','realizuar','cancelled','canceled') then
    raise exception using errcode = '23514', message = 'canonical_materialization_terminal_project';
  end if;

  if new.fact_key = 'canonical.bom.create.v1' then
    if jsonb_typeof(new.value) <> 'object' then raise exception using errcode = '22023', message = 'canonical_bom_value_must_be_object'; end if;
    v_items := coalesce(new.value->'items','[]'::jsonb);
    if jsonb_typeof(v_items) <> 'array' or jsonb_array_length(v_items) < 1 or jsonb_array_length(v_items) > 500 then raise exception using errcode = '22023', message = 'canonical_bom_items_invalid'; end if;
    if exists (select 1 from public.bom_items where project_id = new.project_id) then raise exception using errcode = '23514', message = 'canonical_bom_already_exists'; end if;
    begin v_expected := replace(coalesce(nullif(new.value->>'expected_total_kg',''),'0'),',','.')::numeric;
    exception when others then raise exception using errcode = '22023', message = 'invalid_expected_total_kg'; end;
    for v_item in select value from jsonb_array_elements(v_items) loop
      if jsonb_typeof(v_item) <> 'object' then raise exception using errcode = '22023', message = 'canonical_bom_item_must_be_object'; end if;
      v_code := nullif(btrim(coalesce(v_item->>'material_code','')), '');
      if v_code is null then raise exception using errcode = '22023', message = 'canonical_bom_material_code_required'; end if;
      if nullif(btrim(coalesce(v_item->>'grade','')), '') is null or nullif(btrim(coalesce(v_item->>'standard','')), '') is null or nullif(btrim(coalesce(v_item->>'dimensions','')), '') is null then raise exception using errcode = '22023', message = 'canonical_bom_technical_fields_required'; end if;
      begin v_total := v_total + replace(coalesce(nullif(v_item->>'kg',''),'0'),',','.')::numeric;
      exception when others then raise exception using errcode = '22023', message = 'canonical_bom_invalid_kg'; end;
      if replace(coalesce(nullif(v_item->>'kg',''),'0'),',','.')::numeric <= 0 then raise exception using errcode = '22023', message = 'canonical_bom_positive_kg_required'; end if;
    end loop;
    if v_expected > 0 and abs(v_total - v_expected) > 0.01 then raise exception using errcode = '23514', message = 'canonical_bom_total_mismatch'; end if;
    insert into public.bom_items(project_id, project_name, pozicioni, materiali, dimensionet, profile, dim, grade, std, len_mm, kg, auto_generated, needs_review, source_item_key, extraction_method, extraction_confidence)
    select new.project_id, coalesce(v_project.name,''), coalesce(x.value->>'position',''), concat_ws(' — ', nullif(x.value->>'material_code',''), nullif(x.value->>'material','')), coalesce(x.value->>'dimensions',''), coalesce(x.value->>'profile', x.value->>'material',''), coalesce(x.value->>'dimensions',''), coalesce(x.value->>'grade',''), coalesce(x.value->>'standard',''), coalesce(nullif(x.value->>'length_mm',''),'0')::integer, replace(coalesce(nullif(x.value->>'kg',''),'0'),',','.')::numeric, false, false, 'chatgpt:' || coalesce(x.value->>'material_code', x.ordinality::text), 'chatgpt_verified_tender_schedule', 1
    from jsonb_array_elements(v_items) with ordinality as x(value, ordinality);
    return new;
  end if;

  if jsonb_typeof(new.value) <> 'object' then raise exception using errcode = '22023', message = 'canonical_rfq_value_must_be_object'; end if;
  v_drafts := coalesce(new.value->'drafts','[]'::jsonb);
  if jsonb_typeof(v_drafts) <> 'array' or jsonb_array_length(v_drafts) < 1 or jsonb_array_length(v_drafts) > 100 then raise exception using errcode = '22023', message = 'canonical_rfq_drafts_invalid'; end if;
  for v_draft in select value from jsonb_array_elements(v_drafts) loop
    if jsonb_typeof(v_draft) <> 'object' then raise exception using errcode = '22023', message = 'canonical_rfq_draft_must_be_object'; end if;
    v_supplier := nullif(btrim(coalesce(v_draft->>'supplier_name','')), '');
    v_email := lower(nullif(btrim(coalesce(v_draft->>'supplier_email','')), ''));
    v_subject := nullif(btrim(coalesce(v_draft->>'subject','')), '');
    if v_supplier is null or v_email is null or v_subject is null then raise exception using errcode = '22023', message = 'canonical_rfq_supplier_email_subject_required'; end if;
    if v_email !~ '^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$' then raise exception using errcode = '22023', message = 'canonical_rfq_valid_email_required'; end if;
    v_rfq_status := case when nullif(btrim(coalesce(v_draft->>'scheduled_for','')),'') is not null then 'scheduled' else 'planned' end;
    v_notes := concat_ws(E'\n', 'PPPP state: RFQ prepared; external send is handled separately by the human-approved Gmail schedule.', case when nullif(btrim(coalesce(v_draft->>'scheduled_for','')),'') is not null then 'Scheduled: ' || btrim(v_draft->>'scheduled_for') else null end, nullif(btrim(coalesce(v_draft->>'notes','')),''));
    select id into v_existing from public.rfq_log where project_id = new.project_id and lower(coalesce(supplier_email,'')) = v_email and lower(coalesce(subject,'')) = lower(v_subject) order by created_at desc limit 1;
    if v_existing is null then
      insert into public.rfq_log(project_id, project_name, supplier_name, supplier_email, lang, subject, body, status, sent_at, notes)
      values(new.project_id, coalesce(v_project.name,''), v_supplier, v_email, coalesce(nullif(btrim(coalesce(v_draft->>'lang','')),''),'en'), v_subject, coalesce(v_draft->>'body',''), v_rfq_status, null, v_notes);
    elsif exists (select 1 from public.rfq_log where id=v_existing and lower(coalesce(status,'')) in ('planned','scheduled')) then
      update public.rfq_log set supplier_name=v_supplier, supplier_email=v_email, lang=coalesce(nullif(btrim(coalesce(v_draft->>'lang','')),''),lang,'en'), body=coalesce(v_draft->>'body',body,''), status=v_rfq_status, notes=v_notes where id=v_existing;
    end if;
  end loop;
  return new;
end;
$_$;


ALTER FUNCTION public.pppp_chatgpt_materialize_canonical_fact_v1() OWNER TO postgres;

--
-- Name: pppp_chatgpt_morning_brief_safe_v1(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_morning_brief_safe_v1(p_hours integer DEFAULT 24, p_days integer DEFAULT 30, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_ct jsonb;
  v_di jsonb;
begin
  v_ct := public.pppp_chatgpt_control_tower_v2(p_hours,p_days,p_limit);
  v_di := public.pppp_chatgpt_daily_intelligence_v1(p_days,p_limit);
  return jsonb_build_object(
    'version',1,
    'read_only',true,
    'generated_at',now(),
    'brief_date',current_date,
    'headline',v_di->'headline',
    'summary',v_di->'summary',
    'projects_requiring_attention',v_di->'projects_requiring_attention',
    'waiting_external_watchlist',v_di->'waiting_external_watchlist',
    'new_opportunities',v_di->'new_opportunities',
    'human_decisions_required',v_di->'human_decisions_required',
    'prepare_now',v_di->'prepare_now',
    'portfolio_summary',v_di->'portfolio_summary',
    'historical_delta_available',v_ct->'historical_delta_available',
    'change_intelligence',v_ct->'change_intelligence'
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_morning_brief_safe_v1(p_hours integer, p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_next_action_intelligence_v1(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_next_action_intelligence_v1(p_days integer DEFAULT 30, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with params as (select greatest(1,least(coalesce(p_limit,25),100)) lim),
base as (select public.pppp_chatgpt_business_inbox_v2(greatest(1,least(coalesce(p_days,30),90)),200) j),
expanded as (select x.item from base b cross join lateral jsonb_array_elements(coalesce(b.j->'items','[]'::jsonb)) x(item)),
ranked as (select item,coalesce((item->>'priority_score')::int,0) priority_score,item->>'next_action_state' next_action_state,item->>'recommended_action' recommended_action,(item->>'sent_at')::timestamptz sent_at from expanded where item->>'next_action_state' in ('action_candidate','process_document','semantic_review','waiting','review_optional')),
limited as (select * from ranked order by priority_score desc,sent_at desc nulls last limit (select lim from params)),
items as (select coalesce(jsonb_agg(item order by priority_score desc,sent_at desc nulls last),'[]'::jsonb) value from limited)
select jsonb_build_object('next_action_intelligence_version',1,'read_only',true,'generated_at',now(),'days',greatest(1,least(coalesce(p_days,30),90)),
 'policy',jsonb_build_object('recommendations_are_review_only',true,'missing_reply_alone_never_creates_action',true,'no_task_creation',true,'no_email_send',true,'no_project_assignment',true,'no_project_disposition',true,'no_supplier_selection',true,'no_price_or_margin_decision',true,'protected_human_gates_preserved',true),
 'stats',jsonb_build_object('returned',(select count(*) from limited),'high_priority',(select count(*) from limited where priority_score>=85),'medium_priority',(select count(*) from limited where priority_score between 50 and 84),'low_priority',(select count(*) from limited where priority_score<50),'reply_review',(select count(*) from limited where recommended_action='review_and_reply'),'offer_review',(select count(*) from limited where recommended_action='review_received_offer'),'project_outcome_review',(select count(*) from limited where recommended_action='review_project_outcome'),'finance_document',(select count(*) from limited where recommended_action='process_finance_document')),
 'items',(select value from items));
$$;


ALTER FUNCTION public.pppp_chatgpt_next_action_intelligence_v1(p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_outgoing_invoice_plan_v1(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_outgoing_invoice_plan_v1(p_project_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(x) order by x.project_name,x.milestone_index),'[]'::jsonb)
  from (
    select * from public.pppp_outgoing_invoice_milestones_v1
    where p_project_id is null or project_id=p_project_id
    order by project_name,milestone_index limit greatest(1,least(coalesce(p_limit,100),200))
  ) x;
$$;


ALTER FUNCTION public.pppp_chatgpt_outgoing_invoice_plan_v1(p_project_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_priority_actions_v1(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_priority_actions_v1(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(
    jsonb_agg(to_jsonb(x) order by x.due_date nulls last, x.created_at desc),
    '[]'::jsonb
  )
  from (
    select
      a.id,
      a.project_id,
      a.project_name,
      a.client,
      a.title,
      a.detail,
      a.due_date,
      a.priority,
      a.status,
      a.source,
      a.source_ref,
      a.category,
      a.created_at,
      a.operational_state,
      a.pipeline_stage,
      a.last_activity_at,
      a.last_email_at
    from public.pppp_home_current_actions_v1 a
    order by a.due_date nulls last, a.created_at desc
    limit greatest(1,least(coalesce(p_limit,50),100))
  ) x;
$$;


ALTER FUNCTION public.pppp_chatgpt_priority_actions_v1(p_limit integer) OWNER TO postgres;

