--
-- Name: pppp_chatgpt_project_disposition_v1(text, uuid, jsonb, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_project_disposition_v1(p_command_id text, p_project_id uuid, p_payload jsonb, p_approval text, p_source text DEFAULT 'chatgpt'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_command_id text := nullif(btrim(p_command_id), '');
  v_approval text := lower(coalesce(nullif(btrim(p_approval), ''), ''));
  v_source text := lower(coalesce(nullif(btrim(p_source), ''), 'chatgpt'));
  v_payload jsonb := case
    when jsonb_typeof(coalesce(p_payload, '{}'::jsonb)) = 'object' then coalesce(p_payload, '{}'::jsonb)
    else '{}'::jsonb
  end;
  v_metadata jsonb := case
    when jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) = 'object' then coalesce(p_metadata, '{}'::jsonb)
    else '{}'::jsonb
  end;
  v_disposition text;
  v_approved_on date;
  v_fact_key text;
  v_fact_id uuid;
  v_tasks_closed integer := 0;
  v_project public.projects%rowtype;
begin
  if v_command_id is null then
    raise exception using errcode = '22023', message = 'command_id_required';
  end if;
  if length(v_command_id) > 240 then
    raise exception using errcode = '22023', message = 'command_id_too_long';
  end if;
  if p_project_id is null then
    raise exception using errcode = '22023', message = 'project_id_required';
  end if;
  if v_approval <> 'approved' then
    raise exception using errcode = '42501', message = 'explicit_human_approval_required';
  end if;
  if v_source <> 'chatgpt' then
    raise exception using errcode = '22023', message = 'invalid_project_disposition_source';
  end if;

  v_disposition := lower(coalesce(nullif(btrim(v_payload ->> 'disposition'), ''), ''));
  if v_disposition <> 'no_bid' then
    raise exception using errcode = '22023', message = 'unsupported_project_disposition';
  end if;

  begin
    v_approved_on := nullif(btrim(v_payload ->> 'approved_on'), '')::date;
  exception when others then
    raise exception using errcode = '22023', message = 'approved_on_must_be_yyyy_mm_dd';
  end;
  v_approved_on := coalesce(v_approved_on, current_date);

  perform pg_advisory_xact_lock(hashtextextended(v_command_id, 0));

  select * into v_project
  from public.projects
  where id = p_project_id
  for update;

  if not found then
    raise exception using errcode = '22023', message = 'project_not_found';
  end if;

  if public.pppp_project_status_is_terminal_v1(v_project.status)
     and lower(btrim(coalesce(v_project.status, ''))) not in ('mbyllur', 'closed') then
    raise exception using errcode = '23514', message = 'project_already_terminal_conflict';
  end if;

  v_fact_key := 'tender_decision.no_bid.' || to_char(v_approved_on, 'YYYY-MM-DD');

  v_fact_id := public.pppp_ingest_context_fact_v1(
    p_project_id := p_project_id,
    p_fact_key := v_fact_key,
    p_value := v_payload || jsonb_build_object(
      'decision', 'no_bid',
      'disposition', 'no_bid',
      'bridge_action', 'project_disposition',
      'approval', 'approved'
    ),
    p_category := 'tender_decision',
    p_subject := coalesce(nullif(btrim(v_payload ->> 'subject'), ''), 'No Bid – ' || v_project.name),
    p_source_type := 'chatgpt',
    p_source_ref := coalesce(nullif(btrim(v_metadata ->> 'source_ref'), ''), 'chatgpt:' || v_command_id),
    p_evidence_status := 'observed',
    p_confidence := null,
    p_fact_status := 'observed',
    p_idempotency_key := 'chatgpt-project-disposition:' || v_command_id,
    p_created_by := 'chatgpt_pppp_bridge'
  );

  update public.projects
  set status = 'mbyllur',
      operational_state = 'closed',
      operational_state_at = now(),
      operational_state_source = 'chatgpt_project_disposition',
      updated_at = now()
  where id = p_project_id;

  update public.tasks
  set status = 'mbyllur',
      done_at = coalesce(done_at, now())
  where project_id = p_project_id
    and status in ('hapur', 'në proces');
  get diagnostics v_tasks_closed = row_count;

  select * into v_project
  from public.projects
  where id = p_project_id;

  return jsonb_build_object(
    'ok', true,
    'command_id', v_command_id,
    'project_id', p_project_id,
    'disposition', 'no_bid',
    'project_status', v_project.status,
    'operational_state', v_project.operational_state,
    'pipeline_stage', v_project.pipeline_stage,
    'tasks_closed', v_tasks_closed,
    'fact_id', v_fact_id,
    'approval', 'approved',
    'human_approval_gate_preserved', true,
    'source', v_source,
    'metadata', v_metadata
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_project_disposition_v1(p_command_id text, p_project_id uuid, p_payload jsonb, p_approval text, p_source text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: pppp_chatgpt_project_reconcile_v1(text, uuid, jsonb, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_project_reconcile_v1(p_command_id text, p_project_id uuid, p_payload jsonb, p_approval text, p_source text DEFAULT 'chatgpt'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_command_id text := nullif(btrim(p_command_id), '');
  v_approval text := lower(coalesce(nullif(btrim(p_approval), ''), ''));
  v_source text := lower(coalesce(nullif(btrim(p_source), ''), 'chatgpt'));
  v_payload jsonb := case when jsonb_typeof(coalesce(p_payload,'{}'::jsonb))='object' then coalesce(p_payload,'{}'::jsonb) else '{}'::jsonb end;
  v_metadata jsonb := case when jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))='object' then coalesce(p_metadata,'{}'::jsonb) else '{}'::jsonb end;
  v_operation text;
  v_operational_state text;
  v_pipeline_stage text;
  v_reason text;
  v_key text;
  v_project public.projects%rowtype;
  v_after public.projects%rowtype;
  v_fact_id uuid;
begin
  if v_command_id is null then raise exception using errcode='22023', message='command_id_required'; end if;
  if length(v_command_id) > 240 then raise exception using errcode='22023', message='command_id_too_long'; end if;
  if p_project_id is null then raise exception using errcode='22023', message='project_id_required'; end if;
  if v_approval <> 'approved' then raise exception using errcode='42501', message='explicit_human_approval_required'; end if;
  if v_source <> 'chatgpt' then raise exception using errcode='22023', message='invalid_project_reconcile_source'; end if;

  for v_key in select jsonb_object_keys(v_payload)
  loop
    if v_key not in ('operation','operational_state','pipeline_stage','reason','notes','subject','archive_category') then
      raise exception using errcode='22023', message='project_reconcile_field_not_allowed:' || v_key;
    end if;
  end loop;

  v_operation := lower(coalesce(nullif(btrim(v_payload->>'operation'),''),''));
  if v_operation not in ('reclassify','archive_non_project') then
    raise exception using errcode='22023', message='unsupported_project_reconcile_operation';
  end if;

  v_reason := nullif(btrim(v_payload->>'reason'),'');
  if v_reason is null then
    raise exception using errcode='22023', message='project_reconcile_reason_required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_command_id,0));
  select * into v_project from public.projects where id=p_project_id for update;
  if not found then raise exception using errcode='22023', message='project_not_found'; end if;

  if v_operation='archive_non_project' then
    if lower(btrim(coalesce(v_project.status,''))) in ('fituar','won','humbur','lost','realizuar','completed','complete','mbyllur','closed') then
      raise exception using errcode='23514', message='terminal_or_execution_project_cannot_be_archived_by_reconcile';
    end if;

    update public.projects
    set status='arkivuar',
        operational_state='closed',
        operational_state_at=now(),
        operational_state_source='chatgpt_project_reconcile',
        updated_at=now()
    where id=p_project_id;
  else
    if public.pppp_project_status_is_terminal_v1(v_project.status) or lower(btrim(coalesce(v_project.status,''))) in ('fituar','won') then
      raise exception using errcode='23514', message='terminal_or_won_project_cannot_be_reclassified';
    end if;

    v_operational_state := lower(coalesce(nullif(btrim(v_payload->>'operational_state'),''),''));
    if v_operational_state not in ('action_required','active_work','wait_for_client') then
      raise exception using errcode='22023', message='unsupported_operational_state';
    end if;

    if v_payload ? 'pipeline_stage' then
      v_pipeline_stage := nullif(lower(btrim(v_payload->>'pipeline_stage')),'');
      if v_pipeline_stage is not null and v_pipeline_stage not in ('rfq_in','technical_review','pricing','client_offer','commercial') then
        raise exception using errcode='22023', message='unsupported_pipeline_stage';
      end if;
    else
      v_pipeline_stage := v_project.pipeline_stage;
    end if;

    update public.projects
    set operational_state=v_operational_state,
        operational_state_at=now(),
        operational_state_source='chatgpt_project_reconcile',
        pipeline_stage=v_pipeline_stage,
        updated_at=now()
    where id=p_project_id;
  end if;

  select * into v_after from public.projects where id=p_project_id;

  v_fact_id := public.pppp_ingest_context_fact_v1(
    p_project_id := p_project_id,
    p_fact_key := 'project.reconcile.' || left(regexp_replace(v_command_id,'[^a-zA-Z0-9._-]+','-','g'),180),
    p_value := v_payload || jsonb_build_object(
      'bridge_action','project_reconcile',
      'approval','approved',
      'before',jsonb_build_object('status',v_project.status,'pipeline_stage',v_project.pipeline_stage,'operational_state',v_project.operational_state),
      'after',jsonb_build_object('status',v_after.status,'pipeline_stage',v_after.pipeline_stage,'operational_state',v_after.operational_state)
    ),
    p_category := 'project_reconciliation',
    p_subject := coalesce(nullif(btrim(v_payload->>'subject'),''),'Project reconciliation – ' || v_project.name),
    p_source_type := 'chatgpt',
    p_source_ref := coalesce(nullif(btrim(v_metadata->>'source_ref'),''),'chatgpt:' || v_command_id),
    p_evidence_status := 'observed',
    p_confidence := null,
    p_fact_status := 'observed',
    p_idempotency_key := 'chatgpt-project-reconcile:' || v_command_id,
    p_created_by := 'chatgpt_pppp_bridge'
  );

  return jsonb_build_object(
    'ok',true,
    'command_id',v_command_id,
    'project_id',p_project_id,
    'operation',v_operation,
    'before',jsonb_build_object('status',v_project.status,'pipeline_stage',v_project.pipeline_stage,'operational_state',v_project.operational_state),
    'after',jsonb_build_object('status',v_after.status,'pipeline_stage',v_after.pipeline_stage,'operational_state',v_after.operational_state),
    'fact_id',v_fact_id,
    'human_won_lost_gate_preserved',true,
    'external_email_gate_preserved',true,
    'supplier_selection_gate_preserved',true,
    'source',v_source,
    'metadata',v_metadata
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_project_reconcile_v1(p_command_id text, p_project_id uuid, p_payload jsonb, p_approval text, p_source text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: pppp_chatgpt_project_resolution_v2(text, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_project_resolution_v2(p_source_type text, p_source_ref text, p_payload jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 5) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
with params as (
  select lower(btrim(coalesce(p_source_type,''))) as stype,
         btrim(coalesce(p_source_ref,'')) as sref,
         coalesce(p_payload,'{}'::jsonb) as payload,
         greatest(1,least(coalesce(p_limit,5),10)) as lim
),
source_base as (
  select 'email'::text source_kind,e.gmail_message_id source_key,e.gmail_message_id email_id,e.gmail_thread_id thread_id,
         e.project_id direct_project_id,e.suggested_project_id legacy_suggested_project_id,e.match_method,e.match_confidence,
         lower(btrim(coalesce(e.from_email,''))) counterparty_email,e.subject,
         regexp_replace(coalesce(e.snippet,''),E'(?is)(\\nfrom:|\\non .{0,200}wrote:|\\n_{5,}).*$','','g') body_text,
         e.sent_at,
         (e.project_id is not null and coalesce(e.match_confidence,0)>=99 and lower(coalesce(e.match_method,'')) ~ '(manual|verified|gmail-intake|unique-thread|project-identity|historical-link-only)') direct_authoritative
  from public.project_emails e,params p
  where p.stype in ('email','gmail_message','gmail_message_id') and e.gmail_message_id=p.sref

  union all

  select 'conversation',p.sref,e.gmail_message_id,p.sref,null::uuid,e.suggested_project_id,e.match_method,e.match_confidence,
         lower(btrim(coalesce(e.from_email,''))),e.subject,
         regexp_replace(coalesce(e.snippet,''),E'(?is)(\\nfrom:|\\non .{0,200}wrote:|\\n_{5,}).*$','','g'),e.sent_at,false
  from params p
  cross join lateral (
    select x.* from public.project_emails x
    where p.stype in ('conversation','thread','gmail_thread','gmail_thread_id') and x.gmail_thread_id=p.sref
    order by x.sent_at desc nulls last,x.id desc limit 1
  ) e

  union all

  select 'rfq',r.id::text,null,null,r.project_id,null,null,null,lower(btrim(coalesce(r.supplier_email,''))),r.subject,coalesce(r.body,''),coalesce(r.sent_at,r.created_at),true
  from public.rfq_log r,params p
  where p.stype='rfq' and r.id::text=p.sref

  union all

  select 'offer',o.id::text,null,null,o.project_id,null,null,null,null,coalesce(o.offer_ref,o.supplier,'Offer'),coalesce(o.raw_text,'')||' '||coalesce(o.offer_ref,''),o.created_at,true
  from public.offers o,params p
  where p.stype='offer' and (o.id::text=p.sref or (nullif(btrim(coalesce(o.offer_ref,'')),'') is not null and o.offer_ref=p.sref))

  union all

  select 'document',d.id::text,null,null,d.project_id,null,null,null,null,coalesce(d.doc_nr,d.project,'Document'),
         concat_ws(' ',d.doc_nr,d.project,d.client,d.offer_state::text),d.created_at,true
  from public.documents_registry d,params p
  where p.stype in ('document','doc') and (d.id::text=p.sref or (nullif(btrim(coalesce(d.doc_nr,'')),'') is not null and d.doc_nr=p.sref))

  union all

  select 'document',d.id::text,null,null,d.project_id,null,null,null,null,coalesce(d.doc_nr,d.title,d.file_name,'Document'),
         concat_ws(' ',d.doc_nr,d.title,d.party,d.file_name,d.notes),coalesce(d.doc_date::timestamptz,d.created_at),true
  from public.project_docs d,params p
  where p.stype in ('document','doc') and (d.id::text=p.sref or (nullif(btrim(coalesce(d.doc_nr,'')),'') is not null and d.doc_nr=p.sref))

  union all

  select 'event',p.sref,null,null,null::uuid,null,null,null,lower(btrim(coalesce(p.payload->>'counterparty_email',''))),
         coalesce(p.payload->>'subject',''),concat_ws(' ',p.payload->>'body',p.payload->>'reference',p.payload->>'attachment_names'),null::timestamptz,false
  from params p where p.stype in ('event','entity_event','text_event') and p.sref<>''
),
source_rollup as (
  select count(*)::int source_count,
         min(source_kind) source_kind,min(source_key) source_key,min(email_id) email_id,min(thread_id) thread_id,
         case when count(distinct direct_project_id) filter(where direct_project_id is not null)=1 then min(direct_project_id::text)::uuid end direct_project_id,
         count(distinct direct_project_id) filter(where direct_project_id is not null)::int direct_project_count,
         bool_or(coalesce(direct_authoritative,false)) direct_authoritative,
         case when count(distinct legacy_suggested_project_id) filter(where legacy_suggested_project_id is not null)=1 then min(legacy_suggested_project_id::text)::uuid end legacy_suggested_project_id,
         max(match_method) legacy_match_method,max(match_confidence) legacy_match_confidence,
         nullif(max(counterparty_email),'') counterparty_email,
         string_agg(coalesce(subject,''),' ' order by sent_at desc nulls last) subject,
         string_agg(coalesce(body_text,''),' ' order by sent_at desc nulls last) body_text,
         max(sent_at) sent_at
  from source_base
),
source_norm as (
  select s.*,
    trim(regexp_replace(regexp_replace(lower(coalesce(s.subject,'')),'^((re|aw|fw|fwd)\s*:\s*)+','','g'),'[^a-z0-9]+',' ','g')) subject_norm,
    trim(regexp_replace(lower(concat_ws(' ',s.subject,s.body_text)),'[^a-zA-Z0-9]+',' ','g')) text_norm
  from source_rollup s
),
identity_rows as (
  select p.id project_id,'project_name' identity_kind,p.name raw_identity from public.projects p where nullif(btrim(coalesce(p.name,'')),'') is not null
  union all select p.id,'project_ref',p.ref from public.projects p where nullif(btrim(coalesce(p.ref,'')),'') is not null
  union all select p.id,'business_ref',p.business_ref from public.projects p where nullif(btrim(coalesce(p.business_ref,'')),'') is not null
  union all select p.id,'identity_alias',a.alias from public.projects p cross join lateral unnest(coalesce(p.identity_aliases,'{}'::text[])) a(alias) where nullif(btrim(coalesce(a.alias,'')),'') is not null
),
identity_norm as (
  select i.*,trim(regexp_replace(lower(i.raw_identity),'[^a-zA-Z0-9]+',' ','g')) ident_norm
  from identity_rows i
  where length(btrim(i.raw_identity))>=8
),
explicit_identity_evidence as (
  select distinct i.project_id,'A'::text tier,'strong'::text evidence_strength,
         case i.identity_kind when 'business_ref' then 'exact_business_ref' when 'project_ref' then 'exact_project_ref' when 'identity_alias' then 'unique_project_alias_phrase' else 'explicit_project_name_phrase' end method,
         case when i.identity_kind in ('business_ref','project_ref') then 100 else 98 end score,
         jsonb_build_object('identity_kind',i.identity_kind,'matched',i.raw_identity) details
  from identity_norm i cross join source_norm s
  where s.source_count>0 and length(i.ident_norm)>=8
    and i.ident_norm not in ('early warning and alarm system','structural steel fabrication','steel structure fabrication')
    and (' '||s.text_norm||' ') like '% '||i.ident_norm||' %'
),
context_anchor_evidence as (
  select distinct f.project_id,'A'::text tier,'authoritative'::text evidence_strength,'observed_project_context_anchor'::text method,100 score,
         jsonb_strip_nulls(jsonb_build_object('fact_key',f.fact_key,'source_ref',f.source_ref,'gmail_message_id',f.value->>'gmail_message_id','gmail_thread_id',f.value->>'gmail_thread_id')) details
  from public.pppp_project_context_current_v f cross join source_norm s
  where s.source_count>0 and f.fact_status='observed' and f.project_id is not null and (
    (s.email_id is not null and f.value->>'gmail_message_id'=s.email_id)
    or (s.thread_id is not null and f.value->>'gmail_thread_id'=s.thread_id)
    or f.source_ref='gmail:'||coalesce(s.email_id,'')
  )
),
thread_project_rows as (
  select e.project_id
  from public.project_emails e cross join source_norm s
  where s.thread_id is not null and e.gmail_thread_id=s.thread_id and e.project_id is not null
    and coalesce(e.match_confidence,0)>=95 and lower(coalesce(e.match_method,'')) not like '%suggest%'
  union
  select p.id
  from public.project_email_links l join public.projects p on p.id::text=l.project_id cross join source_norm s
  where s.thread_id is not null and l.gmail_thread_id=s.thread_id and coalesce(l.confidence,0)>=95
),
thread_stats as (select count(distinct project_id)::int project_count,case when count(distinct project_id)=1 then min(project_id::text)::uuid end project_id from thread_project_rows),
thread_anchor_evidence as (
  select t.project_id,'A'::text,'strong'::text,'unique_gmail_thread_anchor'::text,99,jsonb_build_object('gmail_thread_id',s.thread_id)
  from thread_stats t cross join source_norm s where t.project_count=1
),
reference_rows as (
  select d.project_id,'document_registry_ref' method,d.doc_nr raw_ref from public.documents_registry d where d.project_id is not null and nullif(btrim(coalesce(d.doc_nr,'')),'') is not null
  union all select d.project_id,'project_document_ref',d.doc_nr from public.project_docs d where d.project_id is not null and nullif(btrim(coalesce(d.doc_nr,'')),'') is not null
  union all select o.project_id,'supplier_offer_ref',o.offer_ref from public.offers o where o.project_id is not null and nullif(btrim(coalesce(o.offer_ref,'')),'') is not null
  union all select k.project_id,'tender_procurement_ref',k.procurement_no from public.kek_tender_watch k where k.project_id is not null and nullif(btrim(coalesce(k.procurement_no,'')),'') is not null
  union all select k.project_id,'tender_publication_ref',k.publication_no from public.kek_tender_watch k where k.project_id is not null and nullif(btrim(coalesce(k.publication_no,'')),'') is not null
),
reference_evidence as (
  select distinct r.project_id,'A'::text,'strong'::text,r.method,99,
         jsonb_build_object('matched_reference',r.raw_ref)
  from reference_rows r cross join source_norm s
  where s.source_count>0 and length(btrim(r.raw_ref))>=6
    and (' '||s.text_norm||' ') like '% '||trim(regexp_replace(lower(r.raw_ref),'[^a-zA-Z0-9]+',' ','g'))||' %'
),
direct_evidence as (
  select s.direct_project_id,
         case when s.direct_authoritative then 'A' else 'B' end,
         case when s.direct_authoritative then 'authoritative' else 'composite' end,
         case when s.source_kind in ('rfq','offer','document') then 'canonical_source_project_id' when s.direct_authoritative then 'verified_existing_email_project_id' else 'existing_email_project_id_non_deterministic' end,
         case when s.source_kind in ('rfq','offer','document') then 100 when s.direct_authoritative then 100 else 88 end,
         jsonb_strip_nulls(jsonb_build_object('source_kind',s.source_kind,'match_method',s.legacy_match_method,'match_confidence',s.legacy_match_confidence))
  from source_norm s where s.direct_project_id is not null
),
same_subject_rows as (
  select e.project_id,count(*)::int hit_count,max(e.sent_at) last_seen
  from public.project_emails e cross join source_norm s join public.projects p on p.id=e.project_id
  where s.source_count>0 and s.counterparty_email is not null and length(s.subject_norm)>=12
    and e.project_id is not null and p.operational_state is distinct from 'closed'
    and e.gmail_message_id is distinct from s.email_id
    and coalesce(e.match_confidence,0)>=95 and lower(coalesce(e.match_method,'')) not like '%suggest%'
    and lower(btrim(coalesce(e.from_email,'')))=s.counterparty_email
    and trim(regexp_replace(regexp_replace(lower(coalesce(e.subject,'')),'^((re|aw|fw|fwd)\s*:\s*)+','','g'),'[^a-z0-9]+',' ','g'))=s.subject_norm
    and (s.sent_at is null or e.sent_at between s.sent_at-interval '180 days' and s.sent_at+interval '30 days')
  group by e.project_id
),
same_subject_evidence as (
  select r.project_id,'B'::text,'composite'::text,'same_counterparty_same_subject_recent_history'::text,82,
         jsonb_build_object('linked_history_messages',r.hit_count,'last_seen_at',r.last_seen)
  from same_subject_rows r
),
rfq_composite_rows as (
  select r.project_id,count(*)::int hit_count,max(coalesce(r.sent_at,r.created_at)) last_seen
  from public.rfq_log r cross join source_norm s join public.projects p on p.id=r.project_id
  where s.source_count>0 and s.counterparty_email is not null and length(s.subject_norm)>=12 and r.project_id is not null
    and p.operational_state is distinct from 'closed'
    and lower(btrim(coalesce(r.supplier_email,'')))=s.counterparty_email
    and trim(regexp_replace(regexp_replace(lower(coalesce(r.subject,'')),'^((re|aw|fw|fwd)\s*:\s*)+','','g'),'[^a-z0-9]+',' ','g'))=s.subject_norm
    and (s.sent_at is null or coalesce(r.sent_at,r.created_at) between s.sent_at-interval '180 days' and s.sent_at+interval '30 days')
  group by r.project_id
),
rfq_composite_evidence as (
  select r.project_id,'B'::text,'composite'::text,'exact_supplier_plus_rfq_subject_temporal_match'::text,84,
         jsonb_build_object('rfq_records',r.hit_count,'last_seen_at',r.last_seen)
  from rfq_composite_rows r
),
legacy_evidence as (
  select s.legacy_suggested_project_id,'C'::text,'hint'::text,'legacy_suggested_project_id_non_authoritative'::text,
         least(greatest(coalesce(s.legacy_match_confidence,0),1),70),
         jsonb_strip_nulls(jsonb_build_object('match_method',s.legacy_match_method,'legacy_confidence',s.legacy_match_confidence,'authoritative',false))
  from source_norm s where s.legacy_suggested_project_id is not null
),
evidence as (
  select * from explicit_identity_evidence
  union all select * from context_anchor_evidence
  union all select * from thread_anchor_evidence
  union all select * from reference_evidence
  union all select * from direct_evidence
  union all select * from same_subject_evidence
  union all select * from rfq_composite_evidence
  union all select * from legacy_evidence
),
candidates as (
  select e.project_id,p.name project_name,p.client,p.status,p.pipeline_stage,p.operational_state,p.operational_state_at,
         bool_or(e.tier='A') has_tier_a,bool_or(e.tier='B') has_tier_b,
         max(e.score)::int base_score,count(*)::int evidence_count,
         least(100,max(e.score)+least(4,greatest(count(*)-1,0))::int)::int confidence,
         coalesce(jsonb_agg(jsonb_build_object('tier',e.tier,'strength',e.evidence_strength,'method',e.method,'score',e.score,'details',e.details) order by case e.tier when 'A' then 3 when 'B' then 2 else 1 end desc,e.score desc),'[]'::jsonb) evidence
  from evidence e join public.projects p on p.id=e.project_id
  group by e.project_id,p.name,p.client,p.status,p.pipeline_stage,p.operational_state,p.operational_state_at
),
ranked as (
  select c.*,row_number() over(order by has_tier_a desc,has_tier_b desc,confidence desc,evidence_count desc,project_name) rn,
         lead(confidence) over(order by has_tier_a desc,has_tier_b desc,confidence desc,evidence_count desc,project_name) next_confidence
  from candidates c
),
counts as (
  select count(*)::int candidate_count,count(*) filter(where has_tier_a)::int tier_a_project_count,count(*) filter(where has_tier_b)::int tier_b_project_count from candidates
),
decision as (
  select case
    when s.source_count=0 then 'unresolved'
    when c.tier_a_project_count>1 then 'ambiguous'
    when c.tier_a_project_count=1 then 'resolved'
    when r.has_tier_b and r.confidence>=75 and (r.next_confidence is null or r.confidence-r.next_confidence>=10) then 'strong_suggestion'
    when c.candidate_count>1 and r.next_confidence is not null and r.confidence-r.next_confidence<10 then 'ambiguous'
    else 'unresolved' end resolution_status,
    case
      when c.tier_a_project_count=1 then (select project_id from ranked where has_tier_a order by confidence desc,evidence_count desc limit 1)
      when c.tier_a_project_count=0 and r.has_tier_b and r.confidence>=75 and (r.next_confidence is null or r.confidence-r.next_confidence>=10) then r.project_id
      else null end recommended_project_id,
    case
      when c.tier_a_project_count=1 then (select confidence from ranked where has_tier_a order by confidence desc,evidence_count desc limit 1)
      when c.tier_a_project_count=0 and r.has_tier_b and r.confidence>=75 and (r.next_confidence is null or r.confidence-r.next_confidence>=10) then r.confidence
      else 0 end confidence
  from source_norm s cross join counts c left join ranked r on r.rn=1
),
conflict_rows as (
  select jsonb_build_object('type','multiple_tier_a_projects','severity','blocking','project_count',c.tier_a_project_count) item from counts c where c.tier_a_project_count>1
  union all select jsonb_build_object('type','thread_has_multiple_project_anchors','severity','blocking','project_count',t.project_count) from thread_stats t where t.project_count>1
  union all select jsonb_build_object('type','source_reference_matches_multiple_project_records','severity','blocking','project_count',s.direct_project_count) from source_norm s where s.direct_project_count>1
  union all select jsonb_build_object('type','legacy_suggestion_conflicts_with_tier_a','severity','informational','legacy_project_id',s.legacy_suggested_project_id,'resolved_project_id',d.recommended_project_id)
    from source_norm s cross join decision d where s.legacy_suggested_project_id is not null and d.resolution_status='resolved' and s.legacy_suggested_project_id is distinct from d.recommended_project_id
  union all select jsonb_build_object('type','future_timestamp_anomaly','severity','blocking','sent_at',s.sent_at) from source_norm s where s.sent_at>now()+interval '1 day'
),
conflicts as (select coalesce(jsonb_agg(item),'[]'::jsonb) value from conflict_rows),
identity_partner as (
  select count(distinct pc.partner_id)::int partner_count,min(pc.partner_id::text)::uuid partner_id
  from source_norm s join public.partner_contacts pc on lower(btrim(coalesce(pc.email,'')))=s.counterparty_email or lower(btrim(coalesce(pc.email_alt,'')))=s.counterparty_email
  join public.partners p on p.id=pc.partner_id and p.stage='active'
  where s.counterparty_email is not null
),
identity_context as (
  select case when ip.partner_count=1 then jsonb_strip_nulls(jsonb_build_object('identity_status','canonical_partner_contact','partner_id',ip.partner_id,'partner_name',p.name,'relation',p.relation,'business_type',p.business_type,'project_identity_allowed',false))
              when cm.contact_id is not null then jsonb_strip_nulls(jsonb_build_object('identity_status','canonical_contact','contact_id',cm.contact_id,'person',cm.person,'company',cm.company,'kind',cm.kind,'role',cm.role,'project_identity_allowed',false))
              when s.counterparty_email is not null then jsonb_build_object('identity_status','unresolved_external','email',s.counterparty_email,'project_identity_allowed',false)
              else null end value
  from source_norm s cross join identity_partner ip
  left join public.partners p on p.id=ip.partner_id and ip.partner_count=1
  left join public.pppp_contact_master_v1 cm on lower(btrim(coalesce(cm.email,'')))=s.counterparty_email
  limit 1
),
alternatives as (
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('project_id',r.project_id,'project_name',r.project_name,'client',r.client,'confidence',r.confidence,'has_tier_a',r.has_tier_a,'has_tier_b',r.has_tier_b,'evidence_count',r.evidence_count,'status',r.status,'pipeline_stage',r.pipeline_stage,'operational_state',r.operational_state,'evidence',r.evidence)) order by r.rn),'[]'::jsonb) value
  from ranked r where r.rn<=(select lim from params)
),
recommended as (
  select r.* from ranked r join decision d on d.recommended_project_id=r.project_id limit 1
)
select jsonb_strip_nulls(jsonb_build_object(
  'project_resolution_version',2,
  'read_only',true,
  'generated_at',now(),
  'source',jsonb_strip_nulls(jsonb_build_object('source_type',(select stype from params),'source_ref',(select sref from params),'source_kind',s.source_kind,'source_found',s.source_count>0,'source_record_count',s.source_count,'gmail_message_id',s.email_id,'gmail_thread_id',s.thread_id,'subject',left(s.subject,600),'counterparty_email',s.counterparty_email,'sent_at',s.sent_at)),
  'resolution_status',d.resolution_status,
  'recommended_project_id',d.recommended_project_id,
  'recommended_project_name',r.project_name,
  'confidence',d.confidence,
  'assignment_allowed',false,
  'future_auto_link_eligible',(d.resolution_status='resolved' and (select value from conflicts)='[]'::jsonb),
  'review_required',(d.resolution_status<>'resolved'),
  'assignment_recommendation',case when d.resolution_status='resolved' then 'deterministic_candidate_read_only_no_assignment' when d.resolution_status='strong_suggestion' then 'human_review_required_before_any_link' when d.resolution_status='ambiguous' then 'do_not_assign_resolve_conflict' else 'do_not_assign_insufficient_evidence' end,
  'recommended_project_state',case when r.project_id is not null then jsonb_strip_nulls(jsonb_build_object('status',r.status,'pipeline_stage',r.pipeline_stage,'operational_state',r.operational_state,'operational_state_at',r.operational_state_at)) end,
  'evidence',coalesce(r.evidence,'[]'::jsonb),
  'conflicts',(select value from conflicts),
  'alternative_candidates',(select value from alternatives),
  'identity_context',(select value from identity_context),
  'identity_is_context_only',true,
  'legacy_suggestion_authoritative',false,
  'policy',jsonb_build_object(
    'tier_a_required_for_resolved',true,
    'tier_b_is_suggestion_only',true,
    'tier_c_never_assigns_project',true,
    'company_contact_or_domain_alone_never_assigns_project',true,
    'legacy_suggested_project_id_is_hint_only',true,
    'closed_project_requires_explicit_thread_or_project_specific_strong_evidence',true,
    'closed_project_company_history_fallback_disabled',true,
    'multiple_strong_projects_are_ambiguous',true,
    'future_timestamp_guard_enabled',true,
    'project_state_is_never_mutated',true,
    'rejection_never_closes_project',true,
    'protected_human_gates_preserved',true
  )
))
from source_norm s cross join decision d left join recommended r on true;
$_$;


ALTER FUNCTION public.pppp_chatgpt_project_resolution_v2(p_source_type text, p_source_ref text, p_payload jsonb, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_project_situation_intelligence_v1(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_project_situation_intelligence_v1(p_project_id uuid, p_days integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_snapshot jsonb;
  v_project jsonb;
  v_baseline_fact jsonb := '{}'::jsonb;
  v_memory jsonb := '{}'::jsonb;
  v_analysis jsonb := '{}'::jsonb;
  v_actions jsonb := '[]'::jsonb;
  v_tasks jsonb := '[]'::jsonb;
  v_open_issues jsonb := '[]'::jsonb;
  v_risks jsonb := '[]'::jsonb;
  v_missing jsonb := '[]'::jsonb;
  v_recommendation jsonb := '{}'::jsonb;
  v_project_state text;
  v_pipeline text;
  v_status text;
  v_decision text;
  v_deadline date;
  v_deadline_days integer;
  v_last_activity timestamptz;
  v_last_email timestamptz;
  v_activity_age_days integer;
  v_email_age_days integer;
  v_workflow_task_count integer := 0;
  v_workflow_overdue_count integer := 0;
  v_action_count integer := 0;
  v_overdue_action_count integer := 0;
  v_due_7d_action_count integer := 0;
  v_high_action_count integer := 0;
  v_overdue_high_action_count integer := 0;
  v_analysis_action_count integer := 0;
  v_critical_risk_count integer := 0;
  v_high_risk_count integer := 0;
  v_risk_score integer := 0;
  v_risk_level text := 'low';
  v_situation_state text := 'monitor';
  v_attention_required boolean := false;
  v_suppressed_by_state boolean := false;
  v_summary text;
  v_operator_fact jsonb := '{}'::jsonb;
  v_operator_value jsonb := '{}'::jsonb;
  v_operator_at timestamptz;
  v_operator_applies boolean := false;
  v_operator_no_action boolean := false;
  v_operator_requires_action boolean := false;
  v_days integer := greatest(1, least(coalesce(p_days,60),180));
  v_gates jsonb := '[]'::jsonb;
begin
  if p_project_id is null then
    raise exception 'project_id_required' using errcode='22023';
  end if;

  v_snapshot := public.pppp_chatgpt_project_snapshot_v1(p_project_id, 8, 30, 40, 8);
  v_project := coalesce(v_snapshot->'project','{}'::jsonb);
  v_actions := coalesce(v_snapshot->'operator_actions','[]'::jsonb);
  v_tasks := coalesce(v_snapshot->'workflow_tasks','[]'::jsonb);

  select to_jsonb(q) into v_operator_fact
  from (
    select fact_key,value,updated_at,source_ref,evidence_status
    from public.pppp_project_context_current_v
    where project_id=p_project_id and category='operator_update' and fact_status='observed'
    order by updated_at desc limit 1
  ) q;
  v_operator_fact := coalesce(v_operator_fact,'{}'::jsonb);
  v_operator_value := coalesce(v_operator_fact->'value','{}'::jsonb);
  v_operator_at := nullif(v_operator_fact->>'updated_at','')::timestamptz;
  if coalesce(v_operator_value->>'source_sent_at','') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T' then
    begin v_operator_at := (v_operator_value->>'source_sent_at')::timestamptz; exception when others then null; end;
  end if;

  select elem into v_baseline_fact
  from jsonb_array_elements(coalesce(v_snapshot->'context_facts','[]'::jsonb)) as x(elem)
  where elem->>'fact_key'='project.memory.baseline.v1'
  order by nullif(elem->>'updated_at','')::timestamptz desc nulls last
  limit 1;

  v_baseline_fact := coalesce(v_baseline_fact,'{}'::jsonb);
  v_memory := coalesce(v_baseline_fact->'value','{}'::jsonb);
  v_analysis := coalesce(v_memory->'latest_analysis','{}'::jsonb);
  v_risks := coalesce(v_analysis->'risks','[]'::jsonb);
  v_missing := coalesce(v_analysis->'missing_information','[]'::jsonb);
  v_recommendation := coalesce(v_analysis->'recommendation','{}'::jsonb);
  v_decision := coalesce(v_recommendation->>'decision','');

  v_project_state := lower(coalesce(v_project->>'operational_state',''));
  v_pipeline := lower(coalesce(v_project->>'pipeline_stage',''));
  v_status := lower(coalesce(v_project->>'status',''));
  v_operator_applies := v_operator_fact<>'{}'::jsonb
    and v_project_state not in ('closed','mbyllur','execution')
    and v_status not in ('humbur','mbyllur','closed','realizuar','lost','cancelled','canceled','archived')
    and (nullif(v_project->>'operational_state_at','') is null
         or v_operator_at is null
         or v_operator_at>=nullif(v_project->>'operational_state_at','')::timestamptz);
  v_operator_no_action := v_operator_applies and lower(coalesce(v_operator_value->>'action_required','')) in ('false','0','no');
  v_operator_requires_action := v_operator_applies and lower(coalesce(v_operator_value->>'action_required','')) in ('true','1','yes');
  v_deadline := nullif(v_project->>'deadline','')::date;
  v_last_activity := nullif(v_project->>'last_activity_at','')::timestamptz;
  v_last_email := nullif(v_project->>'last_email_at','')::timestamptz;
  v_deadline_days := case when v_deadline is null then null else v_deadline-current_date end;
  v_activity_age_days := case when v_last_activity is null then null else greatest(0,floor(extract(epoch from (now()-v_last_activity))/86400)::integer) end;
  v_email_age_days := case when v_last_email is null then null else greatest(0,floor(extract(epoch from (now()-v_last_email))/86400)::integer) end;

  select count(*)::integer,
         count(*) filter (where nullif(elem->>'due_date','')::date < current_date)::integer
  into v_workflow_task_count,v_workflow_overdue_count
  from jsonb_array_elements(v_tasks) as x(elem);

  select
    count(*)::integer,
    count(*) filter (where nullif(elem->>'due_date','')::date < current_date)::integer,
    count(*) filter (where nullif(elem->>'due_date','')::date between current_date and current_date+7)::integer,
    count(*) filter (where lower(coalesce(elem->>'priority','')) in ('urgent','urgjent','critical','high','larte','lartë','e larte','e lartë'))::integer,
    count(*) filter (
      where nullif(elem->>'due_date','')::date < current_date
        and lower(coalesce(elem->>'priority','')) in ('urgent','urgjent','critical','high','larte','lartë','e larte','e lartë')
    )::integer
  into v_action_count,v_overdue_action_count,v_due_7d_action_count,v_high_action_count,v_overdue_high_action_count
  from jsonb_array_elements(v_actions) as x(elem);

  v_analysis_action_count := jsonb_array_length(coalesce(v_analysis->'next_actions','[]'::jsonb));

  select
    count(*) filter (where lower(coalesce(elem->>'severity',''))='critical')::integer,
    count(*) filter (where lower(coalesce(elem->>'severity',''))='high')::integer
  into v_critical_risk_count,v_high_risk_count
  from jsonb_array_elements(v_risks) as x(elem);

  select coalesce(jsonb_agg(elem order by sort_due nulls last, sort_created desc nulls last),'[]'::jsonb)
    into v_open_issues
  from (
    select elem,
      nullif(elem->>'due_date','')::date as sort_due,
      nullif(elem->>'created_at','')::timestamptz as sort_created
    from jsonb_array_elements(v_actions) as x(elem)
    order by
      case lower(coalesce(elem->>'priority',''))
        when 'urgent' then 1 when 'urgjent' then 1 when 'critical' then 1
        when 'high' then 2 when 'larte' then 2 when 'lartë' then 2 when 'e larte' then 2 when 'e lartë' then 2
        else 3 end,
      nullif(elem->>'due_date','')::date nulls last,
      nullif(elem->>'created_at','')::timestamptz desc nulls last
    limit 5
  ) q;

  v_suppressed_by_state := v_project_state in ('wait_for_client','waiting_for_client','closed','mbyllur');

  if not v_suppressed_by_state and not v_operator_no_action then
    v_risk_score := v_risk_score
      + case when v_overdue_high_action_count>0 then 5 else 0 end
      + case when v_overdue_action_count>0 then 2 else 0 end
      + case when v_due_7d_action_count>0 then 1 else 0 end
      + case when v_high_action_count>0 then 2 else 0 end
      + case when v_analysis_action_count>0 then 3 else 0 end
      + case when v_decision like 'human_gate_%' then 2 else 0 end;
  end if;

  v_risk_score := v_risk_score
    + case when v_critical_risk_count>0 then 4 else 0 end
    + case when v_high_risk_count>0 then 2 else 0 end
    + case when v_deadline_days is not null and v_deadline_days<0 and v_project_state not in ('closed','mbyllur','wait_for_client','waiting_for_client') then 4 else 0 end
    + case when v_deadline_days is not null and v_deadline_days between 0 and 7 and v_project_state not in ('closed','mbyllur','wait_for_client','waiting_for_client') then 2 else 0 end
    + case when v_project_state='action_required' and not v_operator_no_action then 3 else 0 end;

  if v_project_state in ('closed','mbyllur') or v_status in ('humbur','mbyllur','closed') then
    v_risk_level := 'informational';
    v_situation_state := 'closed';
    v_attention_required := false;
  else
    v_risk_level := case
      when v_risk_score>=7 then 'critical'
      when v_risk_score>=4 then 'high'
      when v_risk_score>=2 then 'medium'
      else 'low'
    end;

    v_situation_state := case
      when v_project_state in ('wait_for_client','waiting_for_client') then 'waiting_external'
      when v_project_state='execution' and (v_risk_score>=4 or v_analysis_action_count>0 or v_action_count>0) then 'execution_attention'
      when v_project_state='execution' then 'execution_monitor'
      when v_project_state='action_required' then 'action_required'
      when v_project_state='active_work' and (v_risk_score>=3 or v_analysis_action_count>0 or v_action_count>0) then 'active_work_attention'
      when v_project_state='active_work' then 'active_work'
      when v_action_count>0 or v_decision like 'human_gate_%' then 'action_required'
      when v_pipeline='pricing' and v_analysis_action_count>0 then 'commercial_attention'
      else 'monitor'
    end;

    v_attention_required := case
      when v_project_state in ('wait_for_client','waiting_for_client') then false
      when v_situation_state in ('execution_attention','action_required','active_work_attention','commercial_attention') then true
      else false
    end;
  end if;

  if v_operator_applies then
    if v_operator_no_action then
      v_situation_state := case when coalesce(v_operator_value->>'waiting_on','')<>'' or lower(coalesce(v_operator_value->>'workflow_state','')) like 'wait%' then 'waiting_external' else 'active_work' end;
      v_attention_required := false;
    elsif v_operator_requires_action then
      v_situation_state := 'action_required';
      v_attention_required := true;
    end if;
  end if;

  if v_decision='review_and_send_offer' then
    v_gates := jsonb_build_array('external_email_send','final_selling_price_or_margin');
  elsif v_decision='prepare_client_offer' then
    v_gates := jsonb_build_array('final_selling_price_or_margin');
  elsif v_decision like 'human_gate_%' then
    v_gates := jsonb_build_array('project_won_or_lost_decision');
  end if;

  v_summary := coalesce(
    case when v_operator_applies then nullif(coalesce(v_operator_value->>'summary',v_operator_value->>'text'),'') end,
    nullif(v_analysis->>'executive_summary',''),
    nullif(v_memory->>'summary',''),
    case
      when v_project_state='execution' then 'Projekti është në ekzekutim.'
      when v_project_state in ('wait_for_client','waiting_for_client') then 'Projekti është në pritje të palës tjetër.'
      when v_project_state='active_work' then 'Projekti është në punë aktive.'
      else 'Situata kërkon monitorim sipas gjendjes kanonike të projektit.'
    end
  );

  return jsonb_build_object(
    'situation_intelligence_version',1,
    'read_only',true,
    'generated_at',now(),
    'window_days',v_days,
    'situation_id','project:'||p_project_id::text,
    'situation_kind','project',
    'project',v_project,
    'situation_state',v_situation_state,
    'attention_required',v_attention_required,
    'risk',jsonb_build_object(
      'level',v_risk_level,
      'score',v_risk_score,
      'critical_risks',v_critical_risk_count,
      'high_risks',v_high_risk_count,
      'analysis_risks',v_risks
    ),
    'signals',jsonb_build_object(
      'workflow_open_tasks',v_workflow_task_count,
      'workflow_overdue_tasks',v_workflow_overdue_count,
      'current_operator_actions',v_action_count,
      'overdue_operator_actions',v_overdue_action_count,
      'operator_actions_due_within_7_days',v_due_7d_action_count,
      'high_priority_operator_actions',v_high_action_count,
      'overdue_high_priority_operator_actions',v_overdue_high_action_count,
      'analysis_next_actions',v_analysis_action_count,
      'deadline_days',v_deadline_days,
      'last_activity_age_days',v_activity_age_days,
      'last_email_age_days',v_email_age_days,
      'workflow_task_urgency_not_used_for_scoring',true,
      'operator_action_urgency_suppressed_by_canonical_state',v_suppressed_by_state
    ),
    'summary',v_summary,
    'recommendation',case
      when v_operator_applies then jsonb_build_object(
        'decision',case when v_operator_no_action then 'wait_for_external' when v_operator_requires_action then 'review_current_action' else 'review_operator_context' end,
        'label',coalesce(nullif(v_operator_value->>'current_action',''),nullif(v_operator_value->>'next_action',''),'Rishiko kontekstin aktual'),
        'reason',coalesce(nullif(v_operator_value->>'summary',''),nullif(v_operator_value->>'text',''),'Operator update aktual në PPPP.'),
        'source','operator_update',
        'waiting_on',nullif(v_operator_value->>'waiting_on','')
      )
      when v_recommendation<>'{}'::jsonb then v_recommendation
      when v_project_state in ('wait_for_client','waiting_for_client') then jsonb_build_object('decision','wait_for_client','label','Në pritje të palës tjetër','reason','Gjendja operative kanonike është wait_for_client.')
      when v_project_state='execution' then jsonb_build_object('decision','execution_monitor','label','Ndiq ekzekutimin','reason','Prioritetet vijnë nga prodhimi, dokumentacioni, dorëzimi dhe operator actions aktuale.')
      when v_action_count>0 then jsonb_build_object('decision','review_current_actions','label','Rishiko veprimet aktuale','reason','PPPP ka operator actions aktive për këtë projekt.')
      else jsonb_build_object('decision','review_current_state','label','Rishiko situatën aktuale','reason','Nuk ka rekomandim më specifik të konfirmuar në Project Memory.')
    end,
    'missing_information',v_missing,
    'open_issues',v_open_issues,
    'evidence',jsonb_build_object(
      'project_snapshot_generated_at',v_snapshot->'generated_at',
      'project_memory_fact_id',v_baseline_fact->>'id',
      'project_memory_updated_at',v_baseline_fact->>'updated_at',
      'project_memory_source_ref',v_baseline_fact->>'source_ref',
      'canonical_operational_state',v_project_state,
      'canonical_operational_state_at',v_project->>'operational_state_at',
      'operator_update_applied',v_operator_applies,
      'operator_update_fact_key',v_operator_fact->>'fact_key',
      'operator_update_at',v_operator_at
    ),
    'gates_triggered',v_gates,
    'policy',jsonb_build_object(
      'recommendations_are_review_only',true,
      'no_task_creation',true,
      'no_email_send',true,
      'no_project_assignment',true,
      'no_project_disposition',true,
      'no_supplier_selection',true,
      'no_price_or_margin_decision',true,
      'missing_reply_alone_never_creates_action',true,
      'canonical_operational_state_has_precedence',true,
      'workflow_tasks_do_not_drive_urgency_scoring',true,
      'protected_human_gates_preserved',true
    )
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_project_situation_intelligence_v1(p_project_id uuid, p_days integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_project_snapshot_v1(uuid, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_project_snapshot_v1(p_project_id uuid, p_email_limit integer DEFAULT 20, p_fact_limit integer DEFAULT 30, p_task_limit integer DEFAULT 25, p_document_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_project jsonb;
  v_email_limit integer := greatest(1,least(coalesce(p_email_limit,20),50));
  v_fact_limit integer := greatest(1,least(coalesce(p_fact_limit,30),80));
  v_task_limit integer := greatest(1,least(coalesce(p_task_limit,25),80));
  v_document_limit integer := greatest(1,least(coalesce(p_document_limit,20),50));
begin
  if p_project_id is null then
    raise exception 'project_id_required' using errcode='22023';
  end if;

  select to_jsonb(pj)
    into v_project
  from (
    select
      p.id,
      p.name,
      p.client,
      p.ref,
      p.business_ref,
      p.location,
      p.deadline,
      p.status,
      p.pipeline_stage,
      p.deal_type,
      p.business_type,
      p.origin_type,
      p.work_model,
      p.operational_state,
      p.operational_state_at,
      p.operational_state_source,
      p.last_activity_at,
      p.last_email_at,
      p.updated_at,
      p.drive_folder_id,
      p.drive_folder_url
    from public.projects p
    where p.id=p_project_id
    limit 1
  ) pj;

  if v_project is null then
    raise exception 'project_not_found_or_not_visible' using errcode='P0002';
  end if;

  return jsonb_build_object(
    'generated_at',now(),
    'bridge','chatgpt-plus-v1',
    'read_only_snapshot',true,
    'project',v_project,
    'operator_actions',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.due_date nulls last,x.created_at desc)
      from (
        select
          a.id,a.title,a.detail,a.due_date,a.priority,a.status,a.source,a.source_ref,a.category,a.created_at
        from public.pppp_home_current_actions_v1 a
        where a.project_id=p_project_id
        order by a.due_date nulls last,a.created_at desc
        limit v_task_limit
      ) x
    ),'[]'::jsonb),
    'workflow_tasks',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.due_date nulls last,x.created_at desc)
      from (
        select
          t.id,t.title,t.detail,t.due_date,t.priority,t.status,t.source,t.source_ref,t.category,t.created_at
        from public.tasks t
        where t.project_id=p_project_id
          and lower(coalesce(t.status,'')) not in ('kryer','done','mbyllur','closed','arkivuar','archived')
          and coalesce(t.source,'')<>'automation_failure'
        order by t.due_date nulls last,t.created_at desc
        limit v_task_limit
      ) x
    ),'[]'::jsonb),
    'context_facts',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.updated_at desc)
      from (
        select
          f.id,f.category,f.subject,f.fact_key,f.value,f.source_type,f.source_ref,
          f.evidence_status,f.confidence,f.fact_status,f.updated_at,f.created_by
        from public.pppp_project_context_current_v f
        where f.project_id=p_project_id
          and f.fact_status in ('observed','suggested')
        order by f.updated_at desc
        limit v_fact_limit
      ) x
    ),'[]'::jsonb),
    'recent_emails',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.sent_at desc nulls last,x.id desc)
      from (
        select
          e.id,e.gmail_message_id,e.gmail_thread_id,e.from_email,e.from_name,e.to_emails,e.cc_emails,
          e.subject,left(coalesce(e.snippet,''),1200) as snippet,e.sent_at,e.direction,
          e.has_attachments,e.gmail_url,e.match_method,e.match_confidence,e.needs_review,e.review_reason
        from public.project_emails e
        where e.project_id=p_project_id
        order by e.sent_at desc nulls last,e.id desc
        limit v_email_limit
      ) x
    ),'[]'::jsonb),
    'documents',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc)
      from (
        select
          d.id,d.series,d.year,d.seq,d.doc_nr,d.client,d.total_eur,d.currency,d.total_amount,
          d.offer_state,d.followup_status,d.last_followup_at,d.followup_count,d.created_at
        from public.documents_registry d
        where d.project_id=p_project_id
        order by d.created_at desc
        limit v_document_limit
      ) x
    ),'[]'::jsonb),
    'supplier_decisions',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.decided_at desc nulls last,x.created_at desc)
      from (
        select
          s.id,s.supplier_offer_id,s.supplier_name,s.decision_type,s.status,s.source,
          s.evidence,s.notes,s.decided_at,s.created_at,s.updated_at
        from public.project_supplier_decisions s
        where s.project_id=p_project_id
        order by s.decided_at desc nulls last,s.created_at desc
        limit 20
      ) x
    ),'[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_project_snapshot_v1(p_project_id uuid, p_email_limit integer, p_fact_limit integer, p_task_limit integer, p_document_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION pppp_chatgpt_project_snapshot_v1(p_project_id uuid, p_email_limit integer, p_fact_limit integer, p_task_limit integer, p_document_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_chatgpt_project_snapshot_v1(p_project_id uuid, p_email_limit integer, p_fact_limit integer, p_task_limit integer, p_document_limit integer) IS 'Internal ChatGPT Plus read-only project snapshot. Executable by service_role and the Supabase read-only connector role when present.';


--
-- Name: pppp_chatgpt_record_context_suggestion_v1(uuid, text, jsonb, text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_record_context_suggestion_v1(p_project_id uuid, p_fact_key text, p_value jsonb, p_category text DEFAULT 'chatgpt_note'::text, p_subject text DEFAULT NULL::text, p_confidence numeric DEFAULT 0.60, p_source_ref text DEFAULT 'chatgpt-plus-bridge'::text, p_idempotency_key text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_idempotency_key text;
begin
  if p_project_id is null then
    raise exception 'project_id_required' using errcode='22023';
  end if;
  if nullif(btrim(coalesce(p_fact_key,'')),'') is null then
    raise exception 'fact_key_required' using errcode='22023';
  end if;
  if p_confidence is not null and (p_confidence<0 or p_confidence>1) then
    raise exception 'confidence_out_of_range' using errcode='22023';
  end if;

  v_idempotency_key := coalesce(
    nullif(btrim(coalesce(p_idempotency_key,'')),''),
    'chatgpt-plus:' || p_project_id::text || ':' || md5(btrim(p_fact_key) || '|' || coalesce(p_value,'{}'::jsonb)::text)
  );

  return public.pppp_ingest_context_fact_v1(
    p_project_id,
    btrim(p_fact_key),
    coalesce(p_value,'{}'::jsonb),
    coalesce(nullif(btrim(coalesce(p_category,'')),''),'chatgpt_note'),
    nullif(btrim(coalesce(p_subject,'')),''),
    'chatgpt',
    coalesce(nullif(btrim(coalesce(p_source_ref,'')),''),'chatgpt-plus-bridge'),
    'unverified',
    p_confidence,
    'suggested',
    v_idempotency_key,
    'chatgpt_pppp_bridge'
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_record_context_suggestion_v1(p_project_id uuid, p_fact_key text, p_value jsonb, p_category text, p_subject text, p_confidence numeric, p_source_ref text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: FUNCTION pppp_chatgpt_record_context_suggestion_v1(p_project_id uuid, p_fact_key text, p_value jsonb, p_category text, p_subject text, p_confidence numeric, p_source_ref text, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_chatgpt_record_context_suggestion_v1(p_project_id uuid, p_fact_key text, p_value jsonb, p_category text, p_subject text, p_confidence numeric, p_source_ref text, p_idempotency_key text) IS 'Internal ChatGPT Plus bridge write boundary: records only unverified suggested context; never external commitments or approvals.';


--
-- Name: pppp_chatgpt_register_dach_steel_outreach_draft_v1(text, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_register_dach_steel_outreach_draft_v1(p_command_id text, p_payload jsonb, p_source text DEFAULT 'chatgpt'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_command_id text := nullif(btrim(p_command_id),'');
  v_source text := coalesce(nullif(btrim(p_source),''),'chatgpt');
  v_payload jsonb := coalesce(p_payload,'{}'::jsonb);
  v_metadata jsonb := case when jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))='object' then coalesce(p_metadata,'{}'::jsonb) else '{}'::jsonb end;
  v_receipt public.pppp_chatgpt_command_receipts%rowtype;
  v_target public.pppp_dach_steel_targets_v1%rowtype;
  v_queue public.pppp_outbound_queue_v1%rowtype;
  v_unknown_key text;
  v_target_source_key text;
  v_recipient_email text;
  v_recipient_name text;
  v_contact_role text;
  v_draft_id text;
  v_draft_message_id text;
  v_thread_id text;
  v_subject text;
  v_mode text;
  v_domain text;
  v_queue_key text;
  v_relevance integer;
begin
  if v_command_id is null then raise exception using errcode='22023',message='command_id_required'; end if;
  if v_source <> 'chatgpt' then raise exception using errcode='22023',message='invalid_dach_outreach_source'; end if;
  if jsonb_typeof(v_payload) <> 'object' then raise exception using errcode='22023',message='dach_outreach_value_json_must_be_object'; end if;

  select k into v_unknown_key
  from jsonb_object_keys(v_payload) x(k)
  where k not in (
    'target_source_key','recipient_email','recipient_name','contact_role',
    'gmail_draft_id','gmail_draft_message_id','gmail_thread_id',
    'subject','approach_mode'
  )
  limit 1;
  if v_unknown_key is not null then
    raise exception using errcode='22023',message='dach_outreach_field_not_allowed:'||v_unknown_key;
  end if;

  v_target_source_key := nullif(btrim(v_payload->>'target_source_key'),'');
  v_recipient_email := lower(nullif(btrim(v_payload->>'recipient_email'),''));
  v_recipient_name := nullif(btrim(v_payload->>'recipient_name'),'');
  v_contact_role := nullif(btrim(v_payload->>'contact_role'),'');
  v_draft_id := nullif(btrim(v_payload->>'gmail_draft_id'),'');
  v_draft_message_id := nullif(btrim(v_payload->>'gmail_draft_message_id'),'');
  v_thread_id := nullif(btrim(v_payload->>'gmail_thread_id'),'');
  v_subject := nullif(btrim(v_payload->>'subject'),'');
  v_mode := lower(nullif(btrim(v_payload->>'approach_mode'),''));

  if v_target_source_key is null then raise exception using errcode='22023',message='target_source_key_required'; end if;
  if v_recipient_email is null or v_recipient_email !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception using errcode='22023',message='valid_recipient_email_required';
  end if;
  if v_draft_id is null then raise exception using errcode='22023',message='gmail_draft_id_required'; end if;
  if v_subject is null then raise exception using errcode='22023',message='subject_required'; end if;
  if v_mode not in ('rfq_request','direct_offer') then raise exception using errcode='22023',message='invalid_approach_mode'; end if;

  v_domain := lower(split_part(v_recipient_email,'@',2));
  if v_domain in ('gmail.com','googlemail.com','hotmail.com','outlook.com','live.com','yahoo.com','icloud.com','aol.com',
                  'example.com','example.org','example.net') then
    raise exception using errcode='22023',message='personal_or_test_recipient_domain_not_allowed';
  end if;
  if lower(split_part(v_recipient_email,'@',1)) in
     ('jobs','careers','career','hr','privacy','gdpr','webmaster','press','presse','media','newsletter','noreply','no-reply','donotreply','dpo','security','abuse') then
    raise exception using errcode='22023',message='unsafe_recipient_localpart';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_command_id,0));
  perform pg_advisory_xact_lock(hashtextextended(v_target_source_key,1));

  select * into v_receipt
  from public.pppp_chatgpt_command_receipts
  where command_id=v_command_id
  for update;

  if not found then raise exception using errcode='42501',message='approved_bridge_receipt_required'; end if;
  if v_receipt.action_type <> 'dach_steel_outreach_draft' then raise exception using errcode='23505',message='command_id_conflict'; end if;
  if lower(coalesce(v_receipt.approval,'')) <> 'approved' then raise exception using errcode='42501',message='dach_outreach_command_not_approved'; end if;

  if v_receipt.status='succeeded' then
    return v_receipt.result || jsonb_build_object('created',false,'idempotent_replay',true);
  end if;
  if v_receipt.status <> 'processing' then raise exception using errcode='42501',message='dach_outreach_receipt_not_processing'; end if;

  select * into v_target
  from public.pppp_dach_steel_targets_v1
  where source_key=v_target_source_key
  for update;

  if not found then raise exception using errcode='23503',message='dach_target_not_found'; end if;
  if v_target.target_status in ('closed','rejected') then raise exception using errcode='23514',message='dach_target_not_active'; end if;

  if v_target.quote_readiness='M3' and v_mode<>'direct_offer' then
    raise exception using errcode='23514',message='m3_requires_direct_offer_mode';
  end if;
  if v_target.quote_readiness in ('M0','M1','M2') and v_mode<>'rfq_request' then
    raise exception using errcode='23514',message='m0_m2_require_rfq_request_mode';
  end if;

  if v_target.company_domain is not null and lower(v_target.company_domain) <> v_domain then
    raise exception using errcode='23514',message='recipient_domain_mismatch';
  end if;

  v_queue_key := 'DACH_STEEL_BUYER:'||v_target.id::text||':1';
  v_relevance := case v_target.score_band
    when 'A1' then 95 when 'A2' then 85 when 'B1' then 70 when 'B2' then 60 else 40 end;

  select * into v_queue
  from public.pppp_outbound_queue_v1
  where source='DACH_STEEL_BUYER' and source_record_id=v_target.id and touch_no=1
  for update;

  if found and (v_queue.sent_at is not null or v_queue.approved_for_send) then
    raise exception using errcode='23514',message='existing_dach_outreach_locked_after_send_or_approval';
  end if;

  if found then
    update public.pppp_outbound_queue_v1
       set source_key=v_queue_key,
           project_key=v_target.source_key,
           project_title=v_target.project_title,
           company_name=v_target.company_name,
           company_domain=coalesce(v_target.company_domain,v_domain),
           recipient_email=v_recipient_email,
           recipient_name=v_recipient_name,
           contact_role=coalesce(v_contact_role,'Project / Procurement routing'),
           relevance_score=v_relevance,
           priority_score=public.pppp_outbound_priority_v1(v_recipient_email,v_recipient_name,coalesce(v_contact_role,'Project / Procurement routing'),v_relevance),
           gmail_draft_id=v_draft_id,
           gmail_draft_message_id=v_draft_message_id,
           gmail_thread_id=v_thread_id,
           status='candidate',
           suppression_reason=null,
           planned_date=null,
           planned_at=null,
           planned_rank=null,
           approved_for_send=false,
           human_send_required=true,
           source_updated_at=v_target.updated_at,
           payload=jsonb_build_object(
             'approach_mode',v_mode,
             'target_source_key',v_target.source_key,
             'subject',v_subject,
             'quote_readiness',v_target.quote_readiness,
             'why_now',v_target.why_now,
             'steel_scope',v_target.steel_scope,
             'country',v_target.country
           ),
           updated_at=now()
     where id=v_queue.id
     returning * into v_queue;
  else
    insert into public.pppp_outbound_queue_v1(
      source,source_record_id,source_key,touch_no,project_key,project_title,
      company_name,company_domain,recipient_email,recipient_name,contact_role,
      relevance_score,priority_score,gmail_draft_id,gmail_draft_message_id,gmail_thread_id,
      status,suppression_reason,approved_for_send,human_send_required,
      source_updated_at,payload,updated_at
    ) values (
      'DACH_STEEL_BUYER',v_target.id,v_queue_key,1,v_target.source_key,v_target.project_title,
      v_target.company_name,coalesce(v_target.company_domain,v_domain),v_recipient_email,v_recipient_name,
      coalesce(v_contact_role,'Project / Procurement routing'),
      v_relevance,
      public.pppp_outbound_priority_v1(v_recipient_email,v_recipient_name,coalesce(v_contact_role,'Project / Procurement routing'),v_relevance),
      v_draft_id,v_draft_message_id,v_thread_id,
      'candidate',null,false,true,
      v_target.updated_at,
      jsonb_build_object(
        'approach_mode',v_mode,
        'target_source_key',v_target.source_key,
        'subject',v_subject,
        'quote_readiness',v_target.quote_readiness,
        'why_now',v_target.why_now,
        'steel_scope',v_target.steel_scope,
        'country',v_target.country
      ),
      now()
    )
    returning * into v_queue;
  end if;

  update public.pppp_dach_steel_targets_v1
     set company_domain=coalesce(company_domain,v_domain),
         contact_status='found',
         outreach_status='queued',
         outbound_source_key=v_queue_key,
         next_action='Review RFQ/direct-offer draft in Gmail and shared outbound preflight; sending remains human-approved.',
         updated_at=now()
   where id=v_target.id;

  return jsonb_build_object(
    'ok',true,
    'command_id',v_command_id,
    'target_id',v_target.id,
    'queue_id',v_queue.id,
    'source_key',v_queue.source_key,
    'recipient_email',v_queue.recipient_email,
    'gmail_draft_id',v_queue.gmail_draft_id,
    'approach_mode',v_mode,
    'approved_for_send',false,
    'human_send_required',true,
    'external_email_sent',false,
    'project_created',false,
    'metadata',v_metadata
  );
end;
$_$;


ALTER FUNCTION public.pppp_chatgpt_register_dach_steel_outreach_draft_v1(p_command_id text, p_payload jsonb, p_source text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: pppp_chatgpt_register_eu_direct_target_v1(text, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_register_eu_direct_target_v1(p_command_id text, p_payload jsonb, p_source text DEFAULT 'chatgpt'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_command_id text := nullif(btrim(p_command_id),'');
  v_payload jsonb := coalesce(p_payload,'{}'::jsonb);
  v_metadata jsonb := coalesce(p_metadata,'{}'::jsonb);
  v_receipt public.pppp_chatgpt_command_receipts%rowtype;
  v_existing public.pppp_eu_direct_targets_v1%rowtype;
  v_target public.pppp_eu_direct_targets_v1%rowtype;
  v_domain text;
  v_country_code text;
  v_source_key text;
  v_conflicts text[] := '{}'::text[];
  v_history boolean := false;
  v_last_contact timestamptz;
  v_contact_status text;
  v_outreach_status text;
begin
  if v_command_id is null then raise exception using errcode='22023',message='command_id_required'; end if;
  if jsonb_typeof(v_payload) <> 'object' then raise exception using errcode='22023',message='payload_must_be_object'; end if;
  if nullif(btrim(v_payload->>'company_name'),'') is null then raise exception using errcode='22023',message='company_name_required'; end if;

  v_domain := public.pppp_normalize_company_domain_v1(coalesce(nullif(v_payload->>'company_domain',''),nullif(v_payload->>'company_website','')));
  if nullif(v_domain,'') is null then raise exception using errcode='22023',message='company_domain_required'; end if;

  v_country_code := lower(nullif(btrim(v_payload->>'country_code'),''));
  if v_country_code is null or v_country_code !~ '^[a-z]{2}$' then raise exception using errcode='22023',message='country_code_required_iso2'; end if;

  v_source_key := nullif(btrim(v_payload->>'source_key'),'');
  if v_source_key is null then v_source_key := 'eud:'||v_country_code||':'||v_domain; end if;
  if v_source_key !~ '^eud:[a-z]{2}:[a-z0-9.-]+$' then raise exception using errcode='22023',message='invalid_eu_direct_source_key'; end if;

  if coalesce(nullif(v_payload->>'discovery_source',''),'web_search') not in ('web_search','company_website','industry_directory','manual_research','historical_import') then
    raise exception using errcode='22023',message='invalid_eu_direct_discovery_source';
  end if;
  if coalesce(nullif(v_payload->>'company_type',''),'gc_gu') not in ('gc_gu','epc_industrial','industrial_contractor','developer','manufacturer','steel_contractor','other_direct_client') then
    raise exception using errcode='22023',message='invalid_eu_direct_company_type';
  end if;
  if v_payload ? 'business_scope' and jsonb_typeof(v_payload->'business_scope') <> 'array' then
    raise exception using errcode='22023',message='business_scope_must_be_array';
  end if;
  if v_payload ? 'evidence' and jsonb_typeof(v_payload->'evidence') not in ('array','object') then
    raise exception using errcode='22023',message='evidence_must_be_array_or_object';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_command_id,0));
  perform pg_advisory_xact_lock(hashtextextended(v_domain,1));

  select * into v_receipt from public.pppp_chatgpt_command_receipts
  where command_id=v_command_id for update;
  if not found then raise exception using errcode='42501',message='approved_bridge_receipt_required'; end if;
  if v_receipt.action_type <> 'eu_direct_target' then raise exception using errcode='23505',message='command_id_conflict'; end if;
  if lower(coalesce(v_receipt.approval,'')) <> 'approved' then raise exception using errcode='42501',message='eu_direct_target_command_not_approved'; end if;
  if v_receipt.status not in ('processing','succeeded') then raise exception using errcode='42501',message='eu_direct_target_receipt_not_processing'; end if;

  select * into v_existing from public.pppp_eu_direct_targets_v1
  where created_source_command_id=v_command_id limit 1;
  if found then
    return jsonb_build_object(
      'ok',true,'command_id',v_command_id,'target_id',v_existing.id,'created',false,'idempotent_replay',true,
      'project_created',false,'partner_created',false,'contact_created',false,'outbound_created',false,
      'external_email_sent',false,'human_email_approval_required',true,'metadata',v_metadata
    );
  end if;

  select * into v_existing from public.pppp_eu_direct_targets_v1
  where archived_at is null and company_domain_normalized=v_domain limit 1;
  if found then
    raise exception using errcode='23505',message='duplicate_eu_direct_target_review_required:'||v_existing.id::text;
  end if;

  if exists (
    select 1 from public.pppp_gc_prospects_v1 g
    where g.discovery_source='manual_web_verified_2026-09-22'
      and public.pppp_normalize_company_domain_v1(coalesce(g.company_domain,g.website_url))=v_domain
  ) then
    raise exception using errcode='23505',message='legacy_eu_direct_company_already_known';
  end if;

  if exists(select 1 from public.pppp_dach_steel_targets_v1 m where m.target_status <> 'archived' and public.pppp_normalize_company_domain_v1(coalesce(m.company_domain,m.company_website))=v_domain) then
    v_conflicts := array_append(v_conflicts,'material_trade');
  end if;
  if exists(select 1 from public.pppp_representation_targets_v1 r where r.archived_at is null and r.company_domain_normalized=v_domain) then
    v_conflicts := array_append(v_conflicts,'representations');
  end if;
  if exists(select 1 from public.pppp_opportunity_company_profiles_v1 o where public.pppp_normalize_company_domain_v1(o.domain)=v_domain) then
    v_conflicts := array_append(v_conflicts,'opportunities');
  end if;
  if cardinality(v_conflicts)>0 then
    raise exception using errcode='23505',message='cross_module_identity_review_required:'||array_to_string(v_conflicts,',');
  end if;

  select
    coalesce(max(x.at),null),
    count(*)>0
  into v_last_contact,v_history
  from (
    select q.sent_at as at
    from public.pppp_outbound_queue_v1 q
    where public.pppp_normalize_company_domain_v1(q.company_domain)=v_domain
       or split_part(lower(coalesce(q.recipient_email,'')),'@',2)=v_domain
    union all
    select o.sent_at
    from public.pppp_opportunity_outreach_registry_v1 o
    where split_part(lower(coalesce(o.recipient_email,'')),'@',2)=v_domain
    union all
    select c.last_contact::timestamptz
    from public.pppp_contact_master_v1 c
    where split_part(lower(coalesce(c.email,'')),'@',2)=v_domain
       or lower(btrim(coalesce(c.company,'')))=lower(btrim(v_payload->>'company_name'))
  ) x
  where x.at is not null;

  v_contact_status := case
    when nullif(v_payload->>'contact_email','') is not null then 'found'
    else 'unknown'
  end;
  v_outreach_status := case
    when v_history then 'review'
    when nullif(v_payload->>'contact_email','') is not null then 'ready'
    else 'not_ready'
  end;

  insert into public.pppp_eu_direct_targets_v1(
    source_key,company_name,company_domain,company_domain_normalized,company_website,
    country,country_code,company_type,business_scope,why_relevant,evidence,source_name,source_url,
    discovery_source,stage,priority_score,contact_name,contact_role,contact_email,contact_source_url,
    contact_status,outreach_status,do_not_contact,last_contact_at,next_action,next_action_due,notes,
    last_verified_at,created_source,created_source_command_id
  ) values (
    v_source_key,btrim(v_payload->>'company_name'),v_domain,v_domain,
    coalesce(nullif(v_payload->>'company_website',''),'https://'||v_domain),
    nullif(btrim(v_payload->>'country'),''),upper(v_country_code),
    coalesce(nullif(v_payload->>'company_type',''),'gc_gu'),
    case when v_payload ? 'business_scope' then array(select jsonb_array_elements_text(v_payload->'business_scope')) else '{}'::text[] end,
    nullif(v_payload->>'why_relevant',''),
    coalesce(v_payload->'evidence','[]'::jsonb),
    nullif(v_payload->>'source_name',''),nullif(v_payload->>'source_url',''),
    coalesce(nullif(v_payload->>'discovery_source',''),'web_search'),
    case when nullif(v_payload->>'contact_email','') is not null then 'contact_ready' else 'verified' end,
    least(100,greatest(0,coalesce((v_payload->>'priority_score')::integer,0))),
    nullif(v_payload->>'contact_name',''),nullif(v_payload->>'contact_role',''),
    nullif(lower(btrim(v_payload->>'contact_email')),''),nullif(v_payload->>'contact_source_url',''),
    v_contact_status,v_outreach_status,coalesce((v_payload->>'do_not_contact')::boolean,false),
    v_last_contact,nullif(v_payload->>'next_action',''),
    case when nullif(v_payload->>'next_action_due','') is null then null else (v_payload->>'next_action_due')::date end,
    nullif(v_payload->>'notes',''),
    case when nullif(v_payload->>'last_verified_at','') is null then now() else (v_payload->>'last_verified_at')::timestamptz end,
    'chatgpt',v_command_id
  ) returning * into v_target;

  return jsonb_build_object(
    'ok',true,'command_id',v_command_id,'target_id',v_target.id,'source_key',v_target.source_key,
    'company_name',v_target.company_name,'company_domain',v_target.company_domain_normalized,
    'created',true,'idempotent_replay',false,'historical_contact_found',v_history,
    'outreach_status',v_target.outreach_status,
    'project_created',false,'partner_created',false,'contact_created',false,'outbound_created',false,
    'external_email_sent',false,'human_email_approval_required',true,'metadata',v_metadata
  );
end;
$_$;


ALTER FUNCTION public.pppp_chatgpt_register_eu_direct_target_v1(p_command_id text, p_payload jsonb, p_source text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: pppp_chatgpt_register_representation_relationship_v1(text, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_register_representation_relationship_v1(p_command_id text, p_payload jsonb, p_source text DEFAULT 'chatgpt'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_command_id text := nullif(btrim(p_command_id),'');
  v_payload jsonb := coalesce(p_payload,'{}'::jsonb);
  v_metadata jsonb := case when jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))='object'
                           then coalesce(p_metadata,'{}'::jsonb) else '{}'::jsonb end;
  v_receipt public.pppp_chatgpt_command_receipts%rowtype;
  v_unknown_key text;
  v_target_id uuid;
  v_opportunity_id uuid;
  v_source_key text;
  v_company_name text;
  v_domain text;
  v_rel public.pppp_representation_relationships_v1%rowtype;
  v_existing public.pppp_representation_relationships_v1%rowtype;
begin
  if v_command_id is null then raise exception using errcode='22023',message='command_id_required'; end if;
  if length(v_command_id)>240 then raise exception using errcode='22023',message='command_id_too_long'; end if;
  if coalesce(nullif(btrim(p_source),''),'chatgpt') <> 'chatgpt' then
    raise exception using errcode='22023',message='invalid_representation_relationship_source';
  end if;
  if jsonb_typeof(v_payload) <> 'object' then
    raise exception using errcode='22023',message='representation_relationship_value_json_must_be_object';
  end if;

  select k into v_unknown_key
  from jsonb_object_keys(v_payload) x(k)
  where k not in (
    'target_id','opportunity_id','source_key','related_company_name','related_company_domain',
    'related_company_country','relationship_type','relationship_status','project_or_tender',
    'project_reference','relationship_scope','verification_status','evidence','source_name',
    'source_url','last_verified_at','notes'
  )
  limit 1;
  if v_unknown_key is not null then
    raise exception using errcode='22023',message='representation_relationship_field_not_allowed:'||v_unknown_key;
  end if;

  begin
    v_target_id := nullif(btrim(v_payload->>'target_id'),'')::uuid;
  exception when others then
    raise exception using errcode='22023',message='valid_target_id_required';
  end;
  if v_target_id is null or not exists(select 1 from public.pppp_representation_targets_v1 where id=v_target_id) then
    raise exception using errcode='22023',message='valid_target_id_required';
  end if;

  if nullif(btrim(v_payload->>'opportunity_id'),'') is not null then
    begin
      v_opportunity_id := (v_payload->>'opportunity_id')::uuid;
    exception when others then
      raise exception using errcode='22023',message='valid_opportunity_id_required';
    end;
    if not exists(select 1 from public.pppp_representation_opportunities_v1 where id=v_opportunity_id) then
      raise exception using errcode='22023',message='valid_opportunity_id_required';
    end if;
  end if;

  v_source_key := nullif(btrim(v_payload->>'source_key'),'');
  v_company_name := nullif(btrim(v_payload->>'related_company_name'),'');
  v_domain := public.pppp_normalize_company_domain_v1(v_payload->>'related_company_domain');
  if v_source_key is null then raise exception using errcode='22023',message='source_key_required'; end if;
  if v_company_name is null then raise exception using errcode='22023',message='related_company_name_required'; end if;

  if coalesce(nullif(btrim(v_payload->>'relationship_type'),''),'unknown') not in (
    'joint_venture','consortium','subcontractor','supplier','representative','distributor',
    'implementation_partner','local_partner','other','unknown'
  ) then raise exception using errcode='22023',message='invalid_relationship_type'; end if;

  if coalesce(nullif(btrim(v_payload->>'relationship_status'),''),'unknown') not in ('current','historical','unknown') then
    raise exception using errcode='22023',message='invalid_relationship_status';
  end if;

  if coalesce(nullif(btrim(v_payload->>'verification_status'),''),'unknown') not in ('unknown','review','verified') then
    raise exception using errcode='22023',message='invalid_verification_status';
  end if;

  if v_payload ? 'evidence' and jsonb_typeof(v_payload->'evidence') <> 'object' then
    raise exception using errcode='22023',message='evidence_must_be_object';
  end if;

  if nullif(v_payload->>'source_url','') is not null and (v_payload->>'source_url') !~* '^https?://' then
    raise exception using errcode='22023',message='source_url_must_be_http_https';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_command_id,0));
  perform pg_advisory_xact_lock(hashtextextended(v_source_key,1));

  select * into v_receipt
  from public.pppp_chatgpt_command_receipts
  where command_id=v_command_id
  for update;
  if not found then raise exception using errcode='42501',message='approved_bridge_receipt_required'; end if;
  if v_receipt.action_type <> 'representation_relationship' then
    raise exception using errcode='23505',message='command_id_conflict';
  end if;
  if lower(coalesce(v_receipt.approval,'')) <> 'approved' then
    raise exception using errcode='42501',message='representation_relationship_command_not_approved';
  end if;
  if v_receipt.status not in ('processing','succeeded') then
    raise exception using errcode='42501',message='representation_relationship_receipt_not_processing';
  end if;

  select * into v_existing
  from public.pppp_representation_relationships_v1
  where created_source_command_id=v_command_id
  limit 1;
  if found then
    return jsonb_build_object(
      'ok',true,'command_id',v_command_id,'relationship_id',v_existing.id,
      'target_id',v_existing.target_id,'created',false,'idempotent_replay',true,
      'partner_created',false,'contact_created',false,'outbound_created',false,
      'external_email_sent',false,'relationship_confirmed_automatically',false,'metadata',v_metadata
    );
  end if;

  select * into v_existing
  from public.pppp_representation_relationships_v1
  where source_key=v_source_key
  limit 1;
  if found then
    raise exception using errcode='23505',
      message='duplicate_representation_relationship_review_required:'||v_existing.id::text;
  end if;

  insert into public.pppp_representation_relationships_v1(
    target_id,opportunity_id,source_key,related_company_name,related_company_domain,
    related_company_domain_normalized,related_company_country,relationship_type,
    relationship_status,project_or_tender,project_reference,relationship_scope,
    verification_status,evidence,source_name,source_url,last_verified_at,notes,
    created_source,created_source_command_id
  ) values (
    v_target_id,v_opportunity_id,v_source_key,v_company_name,
    nullif(btrim(v_payload->>'related_company_domain'),''),
    v_domain,nullif(btrim(v_payload->>'related_company_country'),''),
    coalesce(nullif(btrim(v_payload->>'relationship_type'),''),'unknown'),
    coalesce(nullif(btrim(v_payload->>'relationship_status'),''),'unknown'),
    nullif(btrim(v_payload->>'project_or_tender'),''),
    nullif(btrim(v_payload->>'project_reference'),''),
    nullif(btrim(v_payload->>'relationship_scope'),''),
    coalesce(nullif(btrim(v_payload->>'verification_status'),''),'unknown'),
    case when v_payload ? 'evidence' then v_payload->'evidence' else '{}'::jsonb end,
    nullif(btrim(v_payload->>'source_name'),''),
    nullif(btrim(v_payload->>'source_url'),''),
    case when nullif(v_payload->>'last_verified_at','') is null then null
         else (v_payload->>'last_verified_at')::timestamptz end,
    nullif(btrim(v_payload->>'notes'),''),
    'chatgpt',v_command_id
  )
  returning * into v_rel;

  return jsonb_build_object(
    'ok',true,'command_id',v_command_id,'relationship_id',v_rel.id,
    'target_id',v_rel.target_id,'opportunity_id',v_rel.opportunity_id,
    'related_company_name',v_rel.related_company_name,
    'relationship_type',v_rel.relationship_type,'verification_status',v_rel.verification_status,
    'created',true,'idempotent_replay',false,
    'partner_created',false,'contact_created',false,'outbound_created',false,
    'external_email_sent',false,'relationship_confirmed_automatically',false,
    'metadata',v_metadata
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_register_representation_relationship_v1(p_command_id text, p_payload jsonb, p_source text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: pppp_chatgpt_register_representation_target_v1(text, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_register_representation_target_v1(p_command_id text, p_payload jsonb, p_source text DEFAULT 'chatgpt'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_command_id text := nullif(btrim(p_command_id),'');
  v_payload jsonb := coalesce(p_payload,'{}'::jsonb);
  v_metadata jsonb := case when jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))='object' then coalesce(p_metadata,'{}'::jsonb) else '{}'::jsonb end;
  v_receipt public.pppp_chatgpt_command_receipts%rowtype;
  v_unknown_key text;
  v_source_key text;
  v_company_name text;
  v_country text;
  v_domain text;
  v_products text[] := '{}'::text[];
  v_existing public.pppp_representation_targets_v1%rowtype;
  v_target public.pppp_representation_targets_v1%rowtype;
begin
  if v_command_id is null then raise exception using errcode='22023',message='command_id_required'; end if;
  if length(v_command_id)>240 then raise exception using errcode='22023',message='command_id_too_long'; end if;
  if coalesce(nullif(btrim(p_source),''),'chatgpt') <> 'chatgpt' then
    raise exception using errcode='22023',message='invalid_representation_target_source';
  end if;
  if jsonb_typeof(v_payload) <> 'object' then
    raise exception using errcode='22023',message='representation_target_value_json_must_be_object';
  end if;

  select k into v_unknown_key
  from jsonb_object_keys(v_payload) x(k)
  where k not in (
    'source_key','source_name','source_url','company_name','company_domain','company_website',
    'country','headquarters','sector','product_category','products','product_summary',
    'manufacturer_description','size_band','why_kosovo','market_evidence',
    'relevant_tenders_or_projects','potential_customer_types','strategic_fit_notes',
    'kosovo_presence','existing_partner_name','existing_partner_notes','balkans_presence_notes',
    'target_model','target_territory','stock_required','minimum_purchase_required',
    'local_financing_required','credit_risk_required','estimated_capital_requirement',
    'capital_notes','capital_fit','contact_name','contact_role','contact_email','contact_phone',
    'linkedin_url','contact_source','priority_score','priority_reason','next_action',
    'next_action_due','notes','last_verified_at'
  )
  limit 1;
  if v_unknown_key is not null then
    raise exception using errcode='22023',message='representation_target_field_not_allowed:'||v_unknown_key;
  end if;

  v_source_key := nullif(btrim(v_payload->>'source_key'),'');
  v_company_name := nullif(btrim(v_payload->>'company_name'),'');
  v_country := nullif(btrim(v_payload->>'country'),'');
  v_domain := public.pppp_normalize_company_domain_v1(coalesce(v_payload->>'company_domain',v_payload->>'company_website'));
  if v_source_key is null then raise exception using errcode='22023',message='source_key_required'; end if;
  if v_company_name is null then raise exception using errcode='22023',message='company_name_required'; end if;
  if nullif(v_payload->>'company_website','') is not null and (v_payload->>'company_website') !~* '^https?://' then
    raise exception using errcode='22023',message='company_website_must_be_http_https';
  end if;
  if nullif(v_payload->>'source_url','') is not null and (v_payload->>'source_url') !~* '^https?://' then
    raise exception using errcode='22023',message='source_url_must_be_http_https';
  end if;
  if nullif(v_payload->>'contact_email','') is not null
     and (v_payload->>'contact_email') !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception using errcode='22023',message='valid_contact_email_required';
  end if;
  if v_payload ? 'products' then
    if jsonb_typeof(v_payload->'products') <> 'array' then
      raise exception using errcode='22023',message='products_must_be_array';
    end if;
    if jsonb_array_length(v_payload->'products') > 50 then
      raise exception using errcode='22023',message='too_many_products';
    end if;
    select coalesce(array_agg(nullif(btrim(value),'')) filter (where nullif(btrim(value),'') is not null),'{}'::text[])
      into v_products
    from jsonb_array_elements_text(v_payload->'products') t(value);
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_command_id,0));
  perform pg_advisory_xact_lock(hashtextextended(coalesce(v_domain,v_source_key),1));

  select * into v_receipt
  from public.pppp_chatgpt_command_receipts
  where command_id=v_command_id
  for update;
  if not found then raise exception using errcode='42501',message='approved_bridge_receipt_required'; end if;
  if v_receipt.action_type <> 'representation_target' then
    raise exception using errcode='23505',message='command_id_conflict';
  end if;
  if lower(coalesce(v_receipt.approval,'')) <> 'approved' then
    raise exception using errcode='42501',message='representation_target_command_not_approved';
  end if;
  if v_receipt.status not in ('processing','succeeded') then
    raise exception using errcode='42501',message='representation_target_receipt_not_processing';
  end if;

  select * into v_existing
  from public.pppp_representation_targets_v1
  where created_source_command_id=v_command_id
  limit 1;
  if found then
    return jsonb_build_object(
      'ok',true,'command_id',v_command_id,'target_id',v_existing.id,
      'source_key',v_existing.source_key,'company_name',v_existing.company_name,
      'created',false,'idempotent_replay',true,'stage',v_existing.stage,
      'project_created',false,'partner_created',false,'contact_created',false,
      'supplier_created',false,'outbound_created',false,'contract_created',false,
      'external_email_sent',false,'represented_automatically',false,'metadata',v_metadata
    );
  end if;

  select * into v_existing
  from public.pppp_representation_targets_v1 t
  where t.source_key=v_source_key
     or (v_domain is not null and t.company_domain_normalized=v_domain)
     or (v_country is not null and lower(btrim(t.company_name))=lower(v_company_name) and lower(btrim(t.country))=lower(v_country))
  order by case when t.source_key=v_source_key then 1 when t.company_domain_normalized=v_domain then 2 else 3 end
  limit 1;
  if found then
    raise exception using errcode='23505',
      message='duplicate_representation_target_review_required:'||v_existing.id::text;
  end if;

  insert into public.pppp_representation_targets_v1(
    company_name,company_domain,company_website,country,headquarters,
    source_key,source_name,source_url,sector,product_category,products,product_summary,
    manufacturer_description,size_band,why_kosovo,market_evidence,relevant_tenders_or_projects,
    potential_customer_types,strategic_fit_notes,kosovo_presence,existing_partner_name,
    existing_partner_notes,balkans_presence_notes,target_model,target_territory,
    stock_required,minimum_purchase_required,local_financing_required,credit_risk_required,
    estimated_capital_requirement,capital_notes,capital_fit,contact_name,contact_role,
    contact_email,contact_phone,linkedin_url,contact_source,stage,priority_score,
    priority_reason,next_action,next_action_due,notes,created_source,
    created_source_command_id,last_verified_at
  ) values (
    v_company_name,nullif(btrim(v_payload->>'company_domain'),''),
    nullif(btrim(v_payload->>'company_website'),''),v_country,
    nullif(btrim(v_payload->>'headquarters'),''),v_source_key,
    nullif(btrim(v_payload->>'source_name'),''),nullif(btrim(v_payload->>'source_url'),''),
    nullif(btrim(v_payload->>'sector'),''),nullif(btrim(v_payload->>'product_category'),''),
    v_products,nullif(btrim(v_payload->>'product_summary'),''),
    nullif(btrim(v_payload->>'manufacturer_description'),''),nullif(btrim(v_payload->>'size_band'),''),
    nullif(btrim(v_payload->>'why_kosovo'),''),nullif(btrim(v_payload->>'market_evidence'),''),
    nullif(btrim(v_payload->>'relevant_tenders_or_projects'),''),
    nullif(btrim(v_payload->>'potential_customer_types'),''),
    nullif(btrim(v_payload->>'strategic_fit_notes'),''),
    coalesce(nullif(btrim(v_payload->>'kosovo_presence'),''),'unknown'),
    nullif(btrim(v_payload->>'existing_partner_name'),''),
    nullif(btrim(v_payload->>'existing_partner_notes'),''),
    nullif(btrim(v_payload->>'balkans_presence_notes'),''),
    coalesce(nullif(btrim(v_payload->>'target_model'),''),'unknown'),
    coalesce(nullif(btrim(v_payload->>'target_territory'),''),'Kosovo'),
    case when v_payload ? 'stock_required' then (v_payload->>'stock_required')::boolean else null end,
    case when v_payload ? 'minimum_purchase_required' then (v_payload->>'minimum_purchase_required')::boolean else null end,
    case when v_payload ? 'local_financing_required' then (v_payload->>'local_financing_required')::boolean else null end,
    case when v_payload ? 'credit_risk_required' then (v_payload->>'credit_risk_required')::boolean else null end,
    nullif(btrim(v_payload->>'estimated_capital_requirement'),''),
    nullif(btrim(v_payload->>'capital_notes'),''),
    coalesce(nullif(btrim(v_payload->>'capital_fit'),''),'unknown'),
    nullif(btrim(v_payload->>'contact_name'),''),nullif(btrim(v_payload->>'contact_role'),''),
    lower(nullif(btrim(v_payload->>'contact_email'),'')),nullif(btrim(v_payload->>'contact_phone'),''),
    nullif(btrim(v_payload->>'linkedin_url'),''),nullif(btrim(v_payload->>'contact_source'),''),
    'found',
    case when nullif(v_payload->>'priority_score','') is null then null else (v_payload->>'priority_score')::integer end,
    nullif(btrim(v_payload->>'priority_reason'),''),nullif(btrim(v_payload->>'next_action'),''),
    case when nullif(v_payload->>'next_action_due','') is null then null else (v_payload->>'next_action_due')::date end,
    nullif(btrim(v_payload->>'notes'),''),'chatgpt',v_command_id,
    case when nullif(v_payload->>'last_verified_at','') is null then null else (v_payload->>'last_verified_at')::timestamptz end
  )
  returning * into v_target;

  return jsonb_build_object(
    'ok',true,'command_id',v_command_id,'target_id',v_target.id,
    'source_key',v_target.source_key,'company_name',v_target.company_name,
    'created',true,'idempotent_replay',false,'stage',v_target.stage,
    'project_created',false,'partner_created',false,'contact_created',false,
    'supplier_created',false,'outbound_created',false,'contract_created',false,
    'external_email_sent',false,'represented_automatically',false,'metadata',v_metadata
  );
end;
$_$;


ALTER FUNCTION public.pppp_chatgpt_register_representation_target_v1(p_command_id text, p_payload jsonb, p_source text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: pppp_chatgpt_representation_relationships_v1(uuid, text, boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_representation_relationships_v1(p_target_id uuid DEFAULT NULL::uuid, p_country text DEFAULT NULL::text, p_include_archived boolean DEFAULT false, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  with filtered as (
    select
      r.*,
      t.company_name as target_company_name,
      o.project_name as opportunity_project_name
    from public.pppp_representation_relationships_v1 r
    join public.pppp_representation_targets_v1 t on t.id=r.target_id
    left join public.pppp_representation_opportunities_v1 o on o.id=r.opportunity_id
    where (p_target_id is null or r.target_id=p_target_id)
      and (nullif(btrim(p_country),'') is null or lower(btrim(r.related_company_country))=lower(btrim(p_country)))
      and (coalesce(p_include_archived,false) or r.archived_at is null)
    order by
      case r.verification_status when 'verified' then 1 when 'review' then 2 else 3 end,
      r.updated_at desc
    limit least(500,greatest(1,coalesce(p_limit,100)))
  )
  select jsonb_build_object(
    'ok',true,
    'count',(select count(*) from filtered),
    'relationships',coalesce((select jsonb_agg(to_jsonb(f) order by
      case f.verification_status when 'verified' then 1 when 'review' then 2 else 3 end,
      f.updated_at desc) from filtered f),'[]'::jsonb),
    'policy',jsonb_build_object(
      'absence_is_not_proof_of_no_relationship',true,
      'outreach_requires_separate_human_decision',true,
      'relationship_registration_never_creates_partner_or_contact',true
    )
  );
$$;


ALTER FUNCTION public.pppp_chatgpt_representation_relationships_v1(p_target_id uuid, p_country text, p_include_archived boolean, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_representation_target_updates_v1(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_representation_target_updates_v1(p_target_id uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'ok', true,
    'target_id', p_target_id,
    'count', count(*),
    'updates', coalesce(jsonb_agg(
      jsonb_build_object(
        'command_id', command_id,
        'patch', patch,
        'metadata', metadata,
        'created_at', created_at
      )
      order by created_at desc
    ), '[]'::jsonb)
  )
  from (
    select command_id, patch, metadata, created_at
    from public.pppp_representation_target_update_audit
    where target_id=p_target_id
    order by created_at desc
    limit greatest(1,least(coalesce(p_limit,50),200))
  ) q;
$$;


ALTER FUNCTION public.pppp_chatgpt_representation_target_updates_v1(p_target_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_representation_targets_v1(text, text, boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_representation_targets_v1(p_query text DEFAULT NULL::text, p_stage text DEFAULT NULL::text, p_include_archived boolean DEFAULT false, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  with filtered as (
    select t.*
    from public.pppp_representation_targets_v1 t
    where (coalesce(p_include_archived,false) or t.archived_at is null)
      and (nullif(btrim(p_stage),'') is null or t.stage=btrim(p_stage))
      and (
        nullif(btrim(p_query),'') is null
        or t.company_name ilike '%'||btrim(p_query)||'%'
        or t.company_domain_normalized=public.pppp_normalize_company_domain_v1(p_query)
        or t.source_key=btrim(p_query)
      )
    order by t.priority_score desc nulls last,t.updated_at desc
    limit least(200,greatest(1,coalesce(p_limit,50)))
  ),
  enriched as (
    select
      f.priority_score,
      f.updated_at,
      to_jsonb(f) || jsonb_build_object(
        'regional_relationships',
        coalesce((
          select jsonb_agg(to_jsonb(r) order by
            case r.verification_status when 'verified' then 1 when 'review' then 2 else 3 end,
            r.updated_at desc
          )
          from public.pppp_representation_relationships_v1 r
          where r.target_id=f.id and r.archived_at is null
        ),'[]'::jsonb),
        'regional_relationship_count',
        (select count(*) from public.pppp_representation_relationships_v1 r
         where r.target_id=f.id and r.archived_at is null)
      ) as target_json
    from filtered f
  )
  select jsonb_build_object(
    'ok',true,
    'count',(select count(*) from enriched),
    'targets',coalesce((select jsonb_agg(e.target_json order by e.priority_score desc nulls last,e.updated_at desc) from enriched e),'[]'::jsonb),
    'human_gates',jsonb_build_object(
      'represented_requires_human_decision',true,
      'external_email_send',true,
      'contract_creation',true,
      'relationship_outreach_requires_human_decision',true
    )
  );
$$;


ALTER FUNCTION public.pppp_chatgpt_representation_targets_v1(p_query text, p_stage text, p_include_archived boolean, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_search_projects_v1(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_search_projects_v1(p_query text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, name text, client text, ref text, business_ref text, status text, pipeline_stage text, operational_state text, last_activity_at timestamp with time zone, last_email_at timestamp with time zone, drive_folder_url text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select
    p.id,
    p.name,
    p.client,
    p.ref,
    p.business_ref,
    p.status,
    p.pipeline_stage,
    p.operational_state,
    p.last_activity_at,
    p.last_email_at,
    p.drive_folder_url
  from public.projects p
  where nullif(btrim(coalesce(p_query,'')),'') is null
     or concat_ws(' ',p.name,p.client,p.ref,p.business_ref,p.location) ilike '%' || btrim(p_query) || '%'
  order by
    case when lower(coalesce(p.status,'')) in ('humbur','lost','arkivuar','archived','mbyllur','closed','cancelled','canceled') then 1 else 0 end,
    p.last_activity_at desc nulls last,
    p.updated_at desc nulls last,
    p.created_at desc
  limit greatest(1,least(coalesce(p_limit,20),50));
$$;


ALTER FUNCTION public.pppp_chatgpt_search_projects_v1(p_query text, p_limit integer) OWNER TO postgres;

