-- Name: FUNCTION pppp_chatgpt_search_projects_v1(p_query text, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_chatgpt_search_projects_v1(p_query text, p_limit integer) IS 'Internal ChatGPT Plus read bridge. Executable by service_role and the Supabase read-only connector role when present.';


--
-- Name: pppp_chatgpt_situation_intelligence_v1(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_situation_intelligence_v1(p_days integer DEFAULT 30, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_days integer := greatest(1,least(coalesce(p_days,30),90));
  v_limit integer := greatest(1,least(coalesce(p_limit,20),40));
  v_priority_actions jsonb := '[]'::jsonb;
  v_inbox jsonb := '{}'::jsonb;
  v_project_situations jsonb := '[]'::jsonb;
  v_inbox_situations jsonb := '[]'::jsonb;
  v_project_count integer := 0;
  v_attention_project_count integer := 0;
  v_inbox_count integer := 0;
  v_new_opportunity_count integer := 0;
  v_offer_review_count integer := 0;
  v_legal_count integer := 0;
  v_finance_count integer := 0;
begin
  v_priority_actions := public.pppp_chatgpt_priority_actions_v1(100);
  v_inbox := public.pppp_chatgpt_business_inbox_project_resolution_v1(v_days,50);

  with action_projects as (
    select
      nullif(elem->>'project_id','')::uuid as project_id,
      110
        + case lower(coalesce(elem->>'priority',''))
            when 'urgent' then 20 when 'urgjent' then 20 when 'critical' then 20
            when 'high' then 15 when 'larte' then 15 when 'lartë' then 15 when 'e larte' then 15 when 'e lartë' then 15
            else 5 end
        + case when nullif(elem->>'due_date','')::date < current_date then 15 else 0 end as rank_score
    from jsonb_array_elements(coalesce(v_priority_actions,'[]'::jsonb)) as x(elem)
    where nullif(elem->>'project_id','') is not null
  ), project_pool as (
    select p.id as project_id,
      case lower(coalesce(p.operational_state,''))
        when 'execution' then 95
        when 'action_required' then 90
        when 'active_work' then 80
        when 'wait_for_client' then 45
        else 55 end
      + case when nullif(p.deadline,'')::date between current_date and current_date+14 then 10 else 0 end
      + case when p.last_activity_at is not null and p.last_activity_at >= now()-interval '14 days' then 5 else 0 end as rank_score
    from public.projects p
    where lower(coalesce(p.status,'')) not in ('humbur','mbyllur','closed','no_bid','no bid')
      and lower(coalesce(p.operational_state,'')) not in ('closed','mbyllur')
      and (
        p.last_activity_at >= now()-interval '120 days'
        or p.updated_at >= now()-interval '120 days'
        or nullif(p.deadline,'')::date >= current_date-30
      )
  ), candidates as (
    select project_id,max(rank_score) as rank_score
    from (
      select * from action_projects
      union all
      select * from project_pool
    ) u
    where project_id is not null
    group by project_id
    order by max(rank_score) desc, project_id
    limit v_limit
  ), situations as (
    select c.rank_score, public.pppp_chatgpt_project_situation_intelligence_v1(c.project_id,v_days) as item
    from candidates c
  )
  select coalesce(jsonb_agg(item || jsonb_build_object('portfolio_rank_score',rank_score) order by rank_score desc),'[]'::jsonb)
    into v_project_situations
  from situations;

  with items as (
    select elem
    from jsonb_array_elements(coalesce(v_inbox->'items','[]'::jsonb)) as x(elem)
    where elem->>'next_action_state' in ('action_candidate','process_document','semantic_review','waiting')
    order by coalesce((elem->>'priority_score')::integer,0) desc,
             nullif(elem->>'sent_at','')::timestamptz desc nulls last
    limit v_limit
  ), shaped as (
    select jsonb_build_object(
      'situation_intelligence_version',1,
      'read_only',true,
      'situation_id','inbox:'||coalesce(elem->>'gmail_message_id',elem->>'email_row_id','unknown'),
      'situation_kind',case
        when elem->>'recommended_action'='review_legal_or_collection_matter' then 'legal_collection'
        when elem->>'recommended_action'='review_project_outcome' then 'project_outcome_review'
        when elem->>'recommended_action'='review_received_offer' then 'supplier_offer_review'
        when elem->>'recommended_action'='process_finance_document' then 'finance_document'
        when elem->>'recommended_action'='review_received_document' then 'document_review'
        when elem->>'recommended_action'='review_and_reply'
          and coalesce((elem->'signals'->>'direct_request')::boolean,false)
          and coalesce(elem->'project_resolution'->>'resolution_status','unresolved')='unresolved'
          then 'new_opportunity_candidate'
        when elem->>'recommended_action'='review_and_reply' then 'reply_review'
        else 'business_review'
      end,
      'priority_score',coalesce((elem->>'priority_score')::integer,0),
      'subject',elem->>'subject',
      'counterparty',jsonb_build_object(
        'from_name',elem->>'from_name',
        'from_email',elem->>'from_email',
        'identity_status',elem->>'identity_status',
        'identity',coalesce(elem->'identity','{}'::jsonb)
      ),
      'project_context',jsonb_build_object(
        'resolution_status',coalesce(elem->'project_resolution'->>'resolution_status','unresolved'),
        'confidence',coalesce((elem->'project_resolution'->>'confidence')::integer,0),
        'recommended_project_id',elem->'project_resolution'->>'recommended_project_id',
        'recommended_project_name',elem->'project_resolution'->>'recommended_project_name',
        'assignment_allowed',false,
        'review_required',coalesce((elem->'project_resolution'->>'review_required')::boolean,true)
      ),
      'recommended_action',elem->>'recommended_action',
      'protected_gate',elem->>'protected_gate',
      'signals',coalesce(elem->'signals','{}'::jsonb),
      'why_now',left(coalesce(elem->>'current_snippet',''),500),
      'evidence',jsonb_build_object(
        'gmail_message_id',elem->>'gmail_message_id',
        'gmail_thread_id',elem->>'gmail_thread_id',
        'sent_at',elem->>'sent_at',
        'email_row_id',elem->>'email_row_id'
      ),
      'review_required',true,
      'policy',jsonb_build_object(
        'recommendation_only',true,
        'no_email_send',true,
        'no_project_assignment',true,
        'no_project_creation',true,
        'no_supplier_selection',true,
        'no_project_disposition',true,
        'protected_human_gates_preserved',true
      )
    ) as item
    from items
  )
  select coalesce(jsonb_agg(item order by (item->>'priority_score')::integer desc),'[]'::jsonb)
    into v_inbox_situations
  from shaped;

  v_project_count := jsonb_array_length(v_project_situations);
  select count(*)::integer into v_attention_project_count
  from jsonb_array_elements(v_project_situations) x(elem)
  where coalesce((elem->>'attention_required')::boolean,false);

  v_inbox_count := jsonb_array_length(v_inbox_situations);
  select
    count(*) filter (where elem->>'situation_kind'='new_opportunity_candidate')::integer,
    count(*) filter (where elem->>'situation_kind'='supplier_offer_review')::integer,
    count(*) filter (where elem->>'situation_kind'='legal_collection')::integer,
    count(*) filter (where elem->>'situation_kind'='finance_document')::integer
  into v_new_opportunity_count,v_offer_review_count,v_legal_count,v_finance_count
  from jsonb_array_elements(v_inbox_situations) x(elem);

  return jsonb_build_object(
    'situation_intelligence_version',1,
    'read_only',true,
    'generated_at',now(),
    'days',v_days,
    'limit',v_limit,
    'portfolio_summary',jsonb_build_object(
      'project_situations',v_project_count,
      'projects_requiring_attention',v_attention_project_count,
      'inbox_situations',v_inbox_count,
      'new_opportunity_candidates',v_new_opportunity_count,
      'supplier_offer_reviews',v_offer_review_count,
      'legal_collection_reviews',v_legal_count,
      'finance_documents',v_finance_count
    ),
    'project_situations',v_project_situations,
    'inbox_situations',v_inbox_situations,
    'policy',jsonb_build_object(
      'read_only_synthesis',true,
      'project_memory_is_primary_when_available',true,
      'project_resolution_v2_controls_project_identity',true,
      'unresolved_items_are_never_forced_into_projects',true,
      'missing_reply_alone_never_creates_action',true,
      'no_task_creation',true,
      'no_email_send',true,
      'no_project_assignment',true,
      'no_project_creation',true,
      'no_project_disposition',true,
      'no_supplier_selection',true,
      'no_price_or_margin_decision',true,
      'protected_human_gates_preserved',true
    )
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_situation_intelligence_v1(p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_supplier_comparison_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_supplier_comparison_v1(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$ select public.pppp_supplier_offer_comparison_json_v1(p_project_id); $$;


ALTER FUNCTION public.pppp_chatgpt_supplier_comparison_v1(p_project_id uuid) OWNER TO postgres;

--
-- Name: pppp_chatgpt_supplier_intelligence_v1(jsonb, uuid, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_supplier_intelligence_v1(p_requirement jsonb DEFAULT '{}'::jsonb, p_project_id uuid DEFAULT NULL::uuid, p_min_qualified integer DEFAULT 3, p_threshold integer DEFAULT 70, p_limit integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_min integer := greatest(1,least(coalesce(p_min_qualified,3),20));
  v_threshold integer := greatest(0,least(coalesce(p_threshold,70),100));
  v_limit integer := greatest(3,least(coalesce(p_limit,12),50));
  v_req record;
  v_req_json jsonb;
  v_req_analysis jsonb;
  v_requirements jsonb := '[]'::jsonb;
  v_requirement_count integer := 0;
  v_all_covered boolean := true;
  v_any_discovery boolean := false;
  v_total_strict_ready integer := 0;
  v_total_review_ready integer := 0;
  v_total_conflicts integer := 0;
  v_total_evidence_gaps integer := 0;
  v_project jsonb := null;
  v_offer_comparison jsonb := null;
  v_input_mode text := 'requirement';
begin
  if p_project_id is not null then
    select to_jsonb(p) into v_project
    from (
      select id,name,client,ref,business_ref,status,pipeline_stage,operational_state
      from public.projects where id=p_project_id
    ) p;

    if v_project is null then
      return jsonb_build_object(
        'supplier_intelligence_version',1,
        'read_only',true,
        'status','project_not_found',
        'project_id',p_project_id,
        'supplier_selection_allowed',false,
        'supplier_commitment_allowed',false,
        'external_email_send_allowed',false,
        'executions_performed',0
      );
    end if;
  end if;

  if coalesce(p_requirement,'{}'::jsonb) <> '{}'::jsonb then
    v_input_mode := case when p_project_id is null then 'requirement' else 'project_requirement_override' end;
    for v_req in select coalesce(public.pppp_supplier_family_v1(coalesce(p_requirement->>'family',p_requirement->>'product_type',p_requirement->>'description')),'unspecified') as family,
                        p_requirement as requirement
    loop
      v_req_json := v_req.requirement;
      v_requirement_count := v_requirement_count + 1;

      with raw as (
        select m.*,
          cardinality(public.pppp_jsonb_text_array_v1(v_req_json->'grades') || public.pppp_jsonb_text_array_v1(v_req_json->'grade')) > 0 as asks_grade,
          cardinality(public.pppp_jsonb_text_array_v1(v_req_json->'standards') || public.pppp_jsonb_text_array_v1(v_req_json->'standard')) > 0 as asks_standard,
          cardinality(public.pppp_jsonb_text_array_v1(v_req_json->'certifications') || public.pppp_jsonb_text_array_v1(v_req_json->'cert')) > 0 as asks_cert,
          coalesce((m.match_reasons->>'family_score')::int,0) family_score,
          coalesce((m.match_reasons->>'grade_score')::int,0) grade_score,
          coalesce((m.match_reasons->>'standard_score')::int,0) standard_score,
          coalesce((m.match_reasons->>'certificate_score')::int,0) certificate_score
        from public.pppp_supplier_match_v1(v_req_json,100,v_threshold) m
      ), classified as (
        select r.*,
          (
            r.qualified and not r.dimension_conflict and r.family_score>=25
            and (not r.asks_grade or r.grade_score>=11)
            and (not r.asks_standard or r.standard_score>=15)
            and (not r.asks_cert or r.certificate_score>=5)
          ) as strict_fit,
          (
            r.qualified and not r.dimension_conflict and r.family_score>=25
            and not (r.asks_grade and r.grade_score<0)
            and not (r.asks_standard and r.standard_score<0)
            and not (r.asks_cert and r.certificate_score<0)
          ) as review_fit,
          (
            r.dimension_conflict
            or (r.asks_grade and r.grade_score<0)
            or (r.asks_standard and r.standard_score<0)
            or (r.asks_cert and r.certificate_score<0)
          ) as explicit_conflict,
          (
            (r.asks_grade and r.grade_score>=0 and r.grade_score<11)
            or (r.asks_standard and r.standard_score>=0 and r.standard_score<15)
            or (r.asks_cert and r.certificate_score>=0 and r.certificate_score<5)
          ) as evidence_gap
        from raw r
      ), enriched as (
        select c.*,
          a.profile_status,a.capability_count,a.evidence_count,a.gmail_evidence_count,a.max_confidence,a.last_evidence_at,
          coalesce(oh.offer_count,0)::int offer_count,
          coalesce(rh.rfq_count,0)::int rfq_count,
          coalesce(rh.reply_count,0)::int reply_count
        from classified c
        left join public.pppp_supplier_master_audit_v1 a on a.partner_id=c.partner_id
        left join lateral (
          select count(*)::int offer_count from public.offers o where lower(trim(o.supplier))=lower(trim(c.partner_name))
        ) oh on true
        left join lateral (
          select count(*)::int rfq_count,
                 count(*) filter(where r.replied_at is not null or lower(coalesce(r.status,''))='replied')::int reply_count
          from public.rfq_log r where lower(trim(r.supplier_name))=lower(trim(c.partner_name))
        ) rh on true
      ), counts as (
        select
          count(*)::int matched,
          count(*) filter(where strict_fit)::int strict_fit_count,
          count(*) filter(where strict_fit and primary_email is not null)::int strict_rfq_ready,
          count(*) filter(where review_fit and not strict_fit)::int review_fit_count,
          count(*) filter(where review_fit and not strict_fit and primary_email is not null)::int review_rfq_ready,
          count(*) filter(where explicit_conflict)::int conflict_count,
          count(*) filter(where evidence_gap)::int evidence_gap_count,
          count(*) filter(where strict_fit and primary_email is not null and source_tier='local')::int strict_local,
          count(*) filter(where strict_fit and primary_email is not null and source_tier='regional')::int strict_regional,
          count(*) filter(where strict_fit and primary_email is not null and source_tier='turkey')::int strict_turkey,
          count(*) filter(where strict_fit and primary_email is not null and source_tier='greece')::int strict_greece,
          count(*) filter(where strict_fit and primary_email is not null and source_tier='eu')::int strict_eu
        from enriched
      ), candidates as (
        select coalesce(jsonb_agg(jsonb_build_object(
          'partner_id',e.partner_id,
          'name',e.partner_name,
          'country',e.country,
          'city',e.city,
          'website',e.website,
          'business_type',e.business_type,
          'email',e.primary_email,
          'contact_language',e.contact_language,
          'match_score',e.match_score,
          'source_tier',e.source_tier,
          'strict_fit',e.strict_fit,
          'review_fit',e.review_fit,
          'rfq_ready',(e.strict_fit and e.primary_email is not null),
          'base_matcher_qualified',e.qualified,
          'dimension_conflict',e.dimension_conflict,
          'explicit_conflict',e.explicit_conflict,
          'evidence_gap',e.evidence_gap,
          'match_reasons',e.match_reasons,
          'profile_status',e.profile_status,
          'capability_count',coalesce(e.capability_count,0),
          'evidence_count',coalesce(e.evidence_count,0),
          'gmail_evidence_count',coalesce(e.gmail_evidence_count,0),
          'max_evidence_confidence',e.max_confidence,
          'last_evidence_at',e.last_evidence_at,
          'offer_history_count',e.offer_count,
          'rfq_history_count',e.rfq_count,
          'rfq_reply_count',e.reply_count,
          'selection_status','candidate_only'
        ) order by e.strict_fit desc,(e.primary_email is not null) desc,e.match_score desc,e.partner_name)
        filter(where rn<=v_limit),'[]'::jsonb) j
        from (
          select e.*,row_number() over(order by e.strict_fit desc,(e.primary_email is not null) desc,e.match_score desc,e.partner_name) rn
          from enriched e
        ) e
      )
      select jsonb_build_object(
        'family',v_req.family,
        'requirement',v_req_json,
        'threshold',v_threshold,
        'minimum_rfq_ready',v_min,
        'matched_existing',c.matched,
        'strict_fit_existing',c.strict_fit_count,
        'strict_rfq_ready_existing',c.strict_rfq_ready,
        'review_fit_existing',c.review_fit_count,
        'review_rfq_ready_existing',c.review_rfq_ready,
        'explicit_conflicts',c.conflict_count,
        'evidence_gaps',c.evidence_gap_count,
        'coverage_sufficient',(c.strict_rfq_ready>=v_min),
        'discovery_needed',(c.strict_rfq_ready<v_min),
        'next_external_search_tier',case when c.strict_rfq_ready>=v_min then 'complete' else 'local' end,
        'external_search_order',jsonb_build_array('local','regional','turkey','greece','eu'),
        'strict_rfq_ready_by_tier',jsonb_build_object('local',c.strict_local,'regional',c.strict_regional,'turkey',c.strict_turkey,'greece',c.strict_greece,'eu',c.strict_eu),
        'candidates',cand.j,
        'interpretation',jsonb_build_object(
          'strict_fit','All requested grade/standard/certificate evidence that is present in the requirement must be positively matched, dimensions must not conflict, and base matcher threshold must pass.',
          'review_fit','Base matcher passes and there is no explicit contradiction, but at least one requested technical attribute lacks positive evidence.',
          'explicit_conflict','A requested grade/standard/certificate or dimensional constraint conflicts with stored supplier capability evidence.',
          'candidate_only','A candidate is never an automatic supplier selection or commitment.'
        )
      ) into v_req_analysis
      from counts c cross join candidates cand;

      v_requirements := v_requirements || jsonb_build_array(v_req_analysis);
      v_all_covered := v_all_covered and coalesce((v_req_analysis->>'coverage_sufficient')::boolean,false);
      v_any_discovery := v_any_discovery or coalesce((v_req_analysis->>'discovery_needed')::boolean,false);
      v_total_strict_ready := v_total_strict_ready + coalesce((v_req_analysis->>'strict_rfq_ready_existing')::int,0);
      v_total_review_ready := v_total_review_ready + coalesce((v_req_analysis->>'review_rfq_ready_existing')::int,0);
      v_total_conflicts := v_total_conflicts + coalesce((v_req_analysis->>'explicit_conflicts')::int,0);
      v_total_evidence_gaps := v_total_evidence_gaps + coalesce((v_req_analysis->>'evidence_gaps')::int,0);
    end loop;
  elsif p_project_id is not null then
    v_input_mode := 'project_bom';
    for v_req in select family,requirement from public.pppp_project_procurement_requirements_v1(p_project_id)
    loop
      v_req_json := v_req.requirement;
      v_requirement_count := v_requirement_count + 1;

      with raw as (
        select m.*,
          cardinality(public.pppp_jsonb_text_array_v1(v_req_json->'grades') || public.pppp_jsonb_text_array_v1(v_req_json->'grade')) > 0 as asks_grade,
          cardinality(public.pppp_jsonb_text_array_v1(v_req_json->'standards') || public.pppp_jsonb_text_array_v1(v_req_json->'standard')) > 0 as asks_standard,
          cardinality(public.pppp_jsonb_text_array_v1(v_req_json->'certifications') || public.pppp_jsonb_text_array_v1(v_req_json->'cert')) > 0 as asks_cert,
          coalesce((m.match_reasons->>'family_score')::int,0) family_score,
          coalesce((m.match_reasons->>'grade_score')::int,0) grade_score,
          coalesce((m.match_reasons->>'standard_score')::int,0) standard_score,
          coalesce((m.match_reasons->>'certificate_score')::int,0) certificate_score
        from public.pppp_supplier_match_v1(v_req_json,100,v_threshold) m
      ), classified as (
        select r.*,
          (r.qualified and not r.dimension_conflict and r.family_score>=25
           and (not r.asks_grade or r.grade_score>=11)
           and (not r.asks_standard or r.standard_score>=15)
           and (not r.asks_cert or r.certificate_score>=5)) as strict_fit,
          (r.qualified and not r.dimension_conflict and r.family_score>=25
           and not (r.asks_grade and r.grade_score<0)
           and not (r.asks_standard and r.standard_score<0)
           and not (r.asks_cert and r.certificate_score<0)) as review_fit,
          (r.dimension_conflict or (r.asks_grade and r.grade_score<0) or (r.asks_standard and r.standard_score<0) or (r.asks_cert and r.certificate_score<0)) as explicit_conflict,
          ((r.asks_grade and r.grade_score>=0 and r.grade_score<11) or (r.asks_standard and r.standard_score>=0 and r.standard_score<15) or (r.asks_cert and r.certificate_score>=0 and r.certificate_score<5)) as evidence_gap
        from raw r
      ), enriched as (
        select c.*,
          a.profile_status,a.capability_count,a.evidence_count,a.gmail_evidence_count,a.max_confidence,a.last_evidence_at,
          coalesce(oh.offer_count,0)::int offer_count,
          coalesce(rh.rfq_count,0)::int rfq_count,
          coalesce(rh.reply_count,0)::int reply_count
        from classified c
        left join public.pppp_supplier_master_audit_v1 a on a.partner_id=c.partner_id
        left join lateral (select count(*)::int offer_count from public.offers o where lower(trim(o.supplier))=lower(trim(c.partner_name))) oh on true
        left join lateral (select count(*)::int rfq_count,count(*) filter(where r.replied_at is not null or lower(coalesce(r.status,''))='replied')::int reply_count from public.rfq_log r where lower(trim(r.supplier_name))=lower(trim(c.partner_name))) rh on true
      ), counts as (
        select count(*)::int matched,
          count(*) filter(where strict_fit)::int strict_fit_count,
          count(*) filter(where strict_fit and primary_email is not null)::int strict_rfq_ready,
          count(*) filter(where review_fit and not strict_fit)::int review_fit_count,
          count(*) filter(where review_fit and not strict_fit and primary_email is not null)::int review_rfq_ready,
          count(*) filter(where explicit_conflict)::int conflict_count,
          count(*) filter(where evidence_gap)::int evidence_gap_count,
          count(*) filter(where strict_fit and primary_email is not null and source_tier='local')::int strict_local,
          count(*) filter(where strict_fit and primary_email is not null and source_tier='regional')::int strict_regional,
          count(*) filter(where strict_fit and primary_email is not null and source_tier='turkey')::int strict_turkey,
          count(*) filter(where strict_fit and primary_email is not null and source_tier='greece')::int strict_greece,
          count(*) filter(where strict_fit and primary_email is not null and source_tier='eu')::int strict_eu
        from enriched
      ), candidates as (
        select coalesce(jsonb_agg(jsonb_build_object(
          'partner_id',e.partner_id,'name',e.partner_name,'country',e.country,'city',e.city,'website',e.website,'business_type',e.business_type,
          'email',e.primary_email,'contact_language',e.contact_language,'match_score',e.match_score,'source_tier',e.source_tier,
          'strict_fit',e.strict_fit,'review_fit',e.review_fit,'rfq_ready',(e.strict_fit and e.primary_email is not null),
          'base_matcher_qualified',e.qualified,'dimension_conflict',e.dimension_conflict,'explicit_conflict',e.explicit_conflict,'evidence_gap',e.evidence_gap,
          'match_reasons',e.match_reasons,'profile_status',e.profile_status,'capability_count',coalesce(e.capability_count,0),'evidence_count',coalesce(e.evidence_count,0),
          'gmail_evidence_count',coalesce(e.gmail_evidence_count,0),'max_evidence_confidence',e.max_confidence,'last_evidence_at',e.last_evidence_at,
          'offer_history_count',e.offer_count,'rfq_history_count',e.rfq_count,'rfq_reply_count',e.reply_count,'selection_status','candidate_only'
        ) order by e.strict_fit desc,(e.primary_email is not null) desc,e.match_score desc,e.partner_name) filter(where rn<=v_limit),'[]'::jsonb) j
        from (select e.*,row_number() over(order by e.strict_fit desc,(e.primary_email is not null) desc,e.match_score desc,e.partner_name) rn from enriched e) e
      )
      select jsonb_build_object(
        'family',v_req.family,'requirement',v_req_json,'threshold',v_threshold,'minimum_rfq_ready',v_min,
        'matched_existing',c.matched,'strict_fit_existing',c.strict_fit_count,'strict_rfq_ready_existing',c.strict_rfq_ready,
        'review_fit_existing',c.review_fit_count,'review_rfq_ready_existing',c.review_rfq_ready,'explicit_conflicts',c.conflict_count,'evidence_gaps',c.evidence_gap_count,
        'coverage_sufficient',(c.strict_rfq_ready>=v_min),'discovery_needed',(c.strict_rfq_ready<v_min),
        'next_external_search_tier',case when c.strict_rfq_ready>=v_min then 'complete' else 'local' end,
        'external_search_order',jsonb_build_array('local','regional','turkey','greece','eu'),
        'strict_rfq_ready_by_tier',jsonb_build_object('local',c.strict_local,'regional',c.strict_regional,'turkey',c.strict_turkey,'greece',c.strict_greece,'eu',c.strict_eu),
        'candidates',cand.j,
        'interpretation',jsonb_build_object(
          'strict_fit','All requested grade/standard/certificate evidence that is present in the requirement must be positively matched, dimensions must not conflict, and base matcher threshold must pass.',
          'review_fit','Base matcher passes and there is no explicit contradiction, but at least one requested technical attribute lacks positive evidence.',
          'explicit_conflict','A requested grade/standard/certificate or dimensional constraint conflicts with stored supplier capability evidence.',
          'candidate_only','A candidate is never an automatic supplier selection or commitment.'
        )
      ) into v_req_analysis from counts c cross join candidates cand;

      v_requirements := v_requirements || jsonb_build_array(v_req_analysis);
      v_all_covered := v_all_covered and coalesce((v_req_analysis->>'coverage_sufficient')::boolean,false);
      v_any_discovery := v_any_discovery or coalesce((v_req_analysis->>'discovery_needed')::boolean,false);
      v_total_strict_ready := v_total_strict_ready + coalesce((v_req_analysis->>'strict_rfq_ready_existing')::int,0);
      v_total_review_ready := v_total_review_ready + coalesce((v_req_analysis->>'review_rfq_ready_existing')::int,0);
      v_total_conflicts := v_total_conflicts + coalesce((v_req_analysis->>'explicit_conflicts')::int,0);
      v_total_evidence_gaps := v_total_evidence_gaps + coalesce((v_req_analysis->>'evidence_gaps')::int,0);
    end loop;
  else
    return jsonb_build_object(
      'supplier_intelligence_version',1,'read_only',true,'status','requirement_or_project_required',
      'supplier_selection_allowed',false,'supplier_commitment_allowed',false,'external_email_send_allowed',false,'executions_performed',0
    );
  end if;

  if p_project_id is not null then
    v_offer_comparison := public.pppp_chatgpt_supplier_comparison_v1(p_project_id);
  end if;

  return jsonb_build_object(
    'supplier_intelligence_version',1,
    'mode','read_only_synthesis',
    'input_mode',v_input_mode,
    'generated_at',now(),
    'project',v_project,
    'requirement_count',v_requirement_count,
    'all_requirements_covered',case when v_requirement_count=0 then false else v_all_covered end,
    'external_discovery_needed',case when v_requirement_count=0 then true else v_any_discovery end,
    'external_search_order',jsonb_build_array('local','regional','turkey','greece','eu'),
    'summary',jsonb_build_object(
      'requirements',v_requirement_count,
      'strict_rfq_ready_total',v_total_strict_ready,
      'review_rfq_ready_total',v_total_review_ready,
      'explicit_conflicts',v_total_conflicts,
      'evidence_gaps',v_total_evidence_gaps,
      'executions_performed',0
    ),
    'requirements',v_requirements,
    'project_offer_comparison',v_offer_comparison,
    'policy',jsonb_build_object(
      'read_only',true,
      'candidate_ranking_is_not_supplier_selection',true,
      'supplier_selection_allowed',false,
      'supplier_commitment_allowed',false,
      'external_email_send_allowed',false,
      'rfq_draft_preparation_allowed',true,
      'rfq_send_requires_explicit_human_approval',true,
      'supplier_selection_requires_explicit_human_approval',true,
      'external_discovery_is_recommendation_only',true,
      'no_discovery_request_created',true,
      'no_supplier_master_mutation',true,
      'no_offer_mutation',true,
      'no_rfq_mutation',true,
      'executions_performed',0
    )
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_supplier_intelligence_v1(p_requirement jsonb, p_project_id uuid, p_min_qualified integer, p_threshold integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_unresolved_business_inbox_v1(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_unresolved_business_inbox_v1(p_days integer DEFAULT 30, p_limit integer DEFAULT 30) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with params as (
  select greatest(1,least(coalesce(p_days,30),90)) as days,
         greatest(1,least(coalesce(p_limit,30),100)) as lim
),
incoming as (
  select
    e.id,
    e.gmail_message_id,
    e.gmail_thread_id,
    e.sent_at,
    lower(btrim(e.from_email)) as email,
    nullif(btrim(e.from_name),'') as from_name,
    e.subject,
    trim(regexp_replace(
      regexp_replace(lower(coalesce(e.subject,'')),'^((re|aw|fw|fwd)\s*:\s*)+','','g'),
      '[^a-z0-9]+',' ','g'
    )) as subject_norm,
    e.match_method,
    e.match_confidence,
    e.needs_review,
    e.suggested_project_id
  from public.project_emails e, params p
  where e.project_id is null
    and e.direction='incoming'
    and e.sent_at >= now() - make_interval(days => p.days)
    and nullif(btrim(coalesce(e.from_email,'')),'') is not null
    and public.pppp_email_sender_class_v1(e.from_email,e.from_name,e.subject)='external'
    and not public.pppp_email_is_automatic_reply_v1(e.subject,e.snippet,e.from_email)
    and not (lower(coalesce(e.subject,'')||' '||coalesce(e.snippet,'')) ~ '(updated .{0,80}catalog|product catalogue|product portfolio|stock (list|availability)|can.t source it.{0,80}let .{0,40}check|looking for .{0,100}let .{0,40}check)')
),
outgoing as (
  select
    e.gmail_thread_id,
    e.sent_at,
    e.to_emails,
    trim(regexp_replace(
      regexp_replace(lower(coalesce(e.subject,'')),'^((re|aw|fw|fwd)\s*:\s*)+','','g'),
      '[^a-z0-9]+',' ','g'
    )) as subject_norm
  from public.project_emails e, params p
  where e.direction='outgoing'
    and e.sent_at >= now() - make_interval(days => p.days + 7)
),
with_reply_evidence as (
  select
    i.*,
    exists(
      select 1 from outgoing o
      where o.sent_at>i.sent_at
        and nullif(btrim(coalesce(i.gmail_thread_id,'')),'') is not null
        and o.gmail_thread_id=i.gmail_thread_id
    ) as later_outgoing_same_thread,
    exists(
      select 1 from outgoing o
      where o.sent_at>i.sent_at
        and length(i.subject_norm)>=12
        and o.subject_norm=i.subject_norm
        and exists(
          select 1
          from unnest(coalesce(o.to_emails,'{}'::text[])) t(x)
          where lower(btrim(t.x))=i.email
        )
    ) as later_outgoing_same_subject
  from incoming i
),
contact_exact as (
  select lower(btrim(c.email)) as email,
         c.contact_id,c.kind,c.company,c.person,c.role,c.country
  from public.pppp_contact_master_v1 c
  where nullif(btrim(coalesce(c.email,'')),'') is not null
),
partner_group as (
  select lower(btrim(x.email)) as email,
         count(distinct pc.partner_id)::int as partner_count,
         min(pc.partner_id::text)::uuid as partner_id
  from public.partner_contacts pc
  join public.partners p on p.id=pc.partner_id and p.stage='active'
  cross join lateral (values(pc.email),(pc.email_alt)) x(email)
  where nullif(btrim(coalesce(x.email,'')),'') is not null
  group by lower(btrim(x.email))
),
partner_exact as (
  select g.email,g.partner_count,g.partner_id,p.name as partner_name,
         p.relation,p.business_type,p.country
  from partner_group g
  left join public.partners p on p.id=g.partner_id and g.partner_count=1
),
classified as (
  select
    r.*,
    c.contact_id,c.kind as contact_kind,c.company as contact_company,
    c.person as contact_person,c.role as contact_role,c.country as contact_country,
    pe.partner_count,pe.partner_id,pe.partner_name,pe.relation as partner_relation,
    pe.business_type as partner_business_type,pe.country as partner_country,
    p.name as suggested_project_name,
    case
      when pe.partner_count=1 then 'canonical_partner_contact'
      when c.contact_id is not null then 'canonical_contact'
      else 'unresolved_external'
    end as identity_status,
    case
      when r.later_outgoing_same_thread or r.later_outgoing_same_subject
        then 'handled_by_later_outgoing_evidence'
      else 'review_reply_evidence_missing'
    end as review_state,
    case
      when lower(coalesce(r.subject,'')) ~ '(invoice|rechnung|fatur|payment|zahlung)'
        then 'finance'
      when lower(coalesce(r.subject,'')) ~ '(zoll|cbam|customs|dogan)'
        then 'customs_logistics'
      when lower(coalesce(r.subject,'')) ~ '(application|bewerbung|curriculum|\bcv\b|career|job)'
        then 'recruitment'
      when lower(coalesce(r.subject,'')) ~ '(rfq|request for quotation|k[ëe]rkes[ëe] p[ëe]r ofert[ëe]|anfrage|angebot|quotation|ponud)'
        then 'procurement_commercial'
      when lower(coalesce(r.subject,'')) ~ '(cooperation|kooperation|partenaire|partnership|bashk[ëe]pun)'
        then 'partnership'
      else 'general_business'
    end as topic_hint
  from with_reply_evidence r
  left join contact_exact c on c.email=r.email
  left join partner_exact pe on pe.email=r.email
  left join public.projects p on p.id=r.suggested_project_id
),
ranked as (
  select c.*,
    case when c.review_state='review_reply_evidence_missing' then 0 else 1 end as handled_rank,
    case
      when c.partner_count=1 then 0
      when c.contact_id is not null then 1
      else 2
    end as identity_rank
  from classified c
),
limited as (
  select * from ranked
  order by handled_rank, sent_at desc nulls last, identity_rank, id desc
  limit (select lim from params)
),
items as (
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'email_row_id',l.id,
    'gmail_message_id',l.gmail_message_id,
    'gmail_thread_id',l.gmail_thread_id,
    'sent_at',l.sent_at,
    'from_email',l.email,
    'from_name',l.from_name,
    'subject',l.subject,
    'identity_status',l.identity_status,
    'identity',case
      when l.partner_count=1 then jsonb_strip_nulls(jsonb_build_object(
        'partner_id',l.partner_id,'name',l.partner_name,'relation',l.partner_relation,
        'business_type',l.partner_business_type,'country',l.partner_country,
        'source','exact_partner_contact'
      ))
      when l.contact_id is not null then jsonb_strip_nulls(jsonb_build_object(
        'contact_id',l.contact_id,'person',l.contact_person,'company',l.contact_company,
        'kind',l.contact_kind,'role',l.contact_role,'country',l.contact_country,
        'source','contact_master'
      ))
      else null end,
    'topic_hint',l.topic_hint,
    'review_state',l.review_state,
    'reply_evidence',jsonb_build_object(
      'later_outgoing_same_thread',l.later_outgoing_same_thread,
      'later_outgoing_same_subject',l.later_outgoing_same_subject
    ),
    'existing_project_hint',case when l.suggested_project_id is not null then jsonb_build_object(
      'project_id',l.suggested_project_id,'project_name',l.suggested_project_name,
      'source_match_method',l.match_method,'source_confidence',l.match_confidence,
      'authoritative',false
    ) end,
    'source_review_flag',coalesce(l.needs_review,false),
    'project_identity_allowed',false,
    'action_created',false
  )) order by l.handled_rank,l.sent_at desc nulls last,l.identity_rank,l.id desc),'[]'::jsonb) as value
  from limited l
)
select jsonb_build_object(
  'read_only',true,
  'generated_at',now(),
  'days',(select days from params),
  'policy',jsonb_build_object(
    'missing_reply_evidence_is_not_action_required',true,
    'project_hint_is_non_authoritative',true,
    'may_assign_project',false,
    'may_create_task_or_action',false,
    'may_send_email',false,
    'may_change_client_supplier_role',false,
    'protected_human_gates_preserved',true
  ),
  'stats',jsonb_build_object(
    'business_incoming',(select count(*) from classified),
    'review_reply_evidence_missing',(select count(*) from classified where review_state='review_reply_evidence_missing'),
    'handled_by_later_outgoing_evidence',(select count(*) from classified where review_state='handled_by_later_outgoing_evidence'),
    'canonical_partner_contact',(select count(*) from classified where identity_status='canonical_partner_contact'),
    'canonical_contact',(select count(*) from classified where identity_status='canonical_contact'),
    'unresolved_external',(select count(*) from classified where identity_status='unresolved_external')
  ),
  'items',(select value from items)
);
$$;


ALTER FUNCTION public.pppp_chatgpt_unresolved_business_inbox_v1(p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_chatgpt_update_representation_target_v1(text, uuid, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_update_representation_target_v1(p_command_id text, p_target_id uuid, p_payload jsonb, p_source text DEFAULT 'chatgpt'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_command_id text := nullif(btrim(p_command_id),'');
  v_payload jsonb := coalesce(p_payload,'{}'::jsonb);
  v_metadata jsonb := case when jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))='object' then coalesce(p_metadata,'{}'::jsonb) else '{}'::jsonb end;
  v_receipt public.pppp_chatgpt_command_receipts%rowtype;
  v_target public.pppp_representation_targets_v1%rowtype;
  v_before jsonb;
  v_after jsonb;
  v_unknown_key text;
  v_products text[];
  v_new_company_name text;
  v_new_country text;
  v_new_company_domain text;
  v_new_company_website text;
  v_new_domain_normalized text;
  v_duplicate uuid;
begin
  if v_command_id is null then raise exception using errcode='22023',message='command_id_required'; end if;
  if p_target_id is null then raise exception using errcode='22023',message='target_id_required'; end if;
  if coalesce(nullif(btrim(p_source),''),'chatgpt') <> 'chatgpt' then
    raise exception using errcode='22023',message='invalid_representation_target_update_source';
  end if;
  if jsonb_typeof(v_payload) <> 'object' then
    raise exception using errcode='22023',message='representation_target_update_value_json_must_be_object';
  end if;

  select k into v_unknown_key
  from jsonb_object_keys(v_payload) x(k)
  where k not in (
    'company_name','company_domain','company_website','country','headquarters',
    'source_name','source_url','sector','product_category','products','product_summary',
    'manufacturer_description','size_band','why_kosovo','market_evidence',
    'relevant_tenders_or_projects','potential_customer_types','strategic_fit_notes',
    'kosovo_presence','existing_partner_name','existing_partner_notes','balkans_presence_notes',
    'target_model','target_territory','stock_required','minimum_purchase_required',
    'local_financing_required','credit_risk_required','estimated_capital_requirement',
    'capital_notes','capital_fit','contact_name','contact_role','contact_email','contact_phone',
    'linkedin_url','contact_source','priority_score','priority_reason','next_action',
    'next_action_due','notes','last_verified_at','stage','last_contact_at',
    'gmail_thread_id','gmail_draft_id','gmail_last_message_id',
    'identity_review_status','identity_review_notes'
  )
  limit 1;
  if v_unknown_key is not null then
    raise exception using errcode='22023',message='representation_target_update_field_not_allowed:'||v_unknown_key;
  end if;

  if nullif(v_payload->>'company_website','') is not null and (v_payload->>'company_website') !~* '^https?://' then
    raise exception using errcode='22023',message='company_website_must_be_http_https';
  end if;
  if nullif(v_payload->>'source_url','') is not null and (v_payload->>'source_url') !~* '^https?://' then
    raise exception using errcode='22023',message='source_url_must_be_http_https';
  end if;
  if nullif(v_payload->>'linkedin_url','') is not null and (v_payload->>'linkedin_url') !~* '^https?://' then
    raise exception using errcode='22023',message='linkedin_url_must_be_http_https';
  end if;
  if nullif(v_payload->>'contact_email','') is not null
     and (v_payload->>'contact_email') !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception using errcode='22023',message='valid_contact_email_required';
  end if;

  if v_payload ? 'products' then
    if jsonb_typeof(v_payload->'products') <> 'array' then
      raise exception using errcode='22023',message='products_must_be_array';
    end if;
    if jsonb_array_length(v_payload->'products') > 50 then
      raise exception using errcode='22023',message='too_many_products';
    end if;
    select coalesce(array_agg(nullif(btrim(value),'')) filter (where nullif(btrim(value),'') is not null),'{}'::text[])
      into v_products
    from jsonb_array_elements_text(v_payload->'products') t(value);
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_command_id,0));
  perform pg_advisory_xact_lock(hashtextextended(p_target_id::text,1));

  select * into v_receipt
  from public.pppp_chatgpt_command_receipts
  where command_id=v_command_id
  for update;
  if not found then raise exception using errcode='42501',message='approved_bridge_receipt_required'; end if;
  if v_receipt.action_type <> 'representation_target_update' then
    raise exception using errcode='23505',message='command_id_conflict';
  end if;
  if lower(coalesce(v_receipt.approval,'')) <> 'approved' then
    raise exception using errcode='42501',message='representation_target_update_command_not_approved';
  end if;
  if v_receipt.status not in ('processing','succeeded') then
    raise exception using errcode='42501',message='representation_target_update_receipt_not_processing';
  end if;

  if v_receipt.status='succeeded' then
    select after_state into v_after
    from public.pppp_representation_target_update_audit
    where command_id=v_command_id;
    if v_after is not null then
      return jsonb_build_object(
        'ok',true,'command_id',v_command_id,'target_id',p_target_id,
        'updated',false,'idempotent_replay',true,
        'project_created',false,'partner_created',false,'contact_created',false,
        'supplier_created',false,'outbound_created',false,'contract_created',false,
        'external_email_sent',false,'represented_automatically',false,
        'metadata',v_metadata
      );
    end if;
  end if;

  select * into v_target
  from public.pppp_representation_targets_v1
  where id=p_target_id
  for update;
  if not found then raise exception using errcode='22023',message='representation_target_not_found'; end if;

  v_before := to_jsonb(v_target);

  v_new_company_name := case when v_payload ? 'company_name' then nullif(btrim(v_payload->>'company_name'),'') else v_target.company_name end;
  v_new_country := case when v_payload ? 'country' then nullif(btrim(v_payload->>'country'),'') else v_target.country end;
  v_new_company_domain := case when v_payload ? 'company_domain' then nullif(btrim(v_payload->>'company_domain'),'') else v_target.company_domain end;
  v_new_company_website := case when v_payload ? 'company_website' then nullif(btrim(v_payload->>'company_website'),'') else v_target.company_website end;

  if v_new_company_name is null then raise exception using errcode='22023',message='company_name_required'; end if;

  v_new_domain_normalized := public.pppp_normalize_company_domain_v1(coalesce(v_new_company_domain,v_new_company_website));

  select t.id into v_duplicate
  from public.pppp_representation_targets_v1 t
  where t.id <> p_target_id
    and t.archived_at is null
    and (
      (v_new_domain_normalized is not null and t.company_domain_normalized=v_new_domain_normalized)
      or (
        v_new_country is not null
        and lower(btrim(t.company_name))=lower(v_new_company_name)
        and lower(btrim(t.country))=lower(v_new_country)
      )
    )
  limit 1;
  if v_duplicate is not null then
    raise exception using errcode='23505',message='duplicate_representation_target_review_required:'||v_duplicate::text;
  end if;

  update public.pppp_representation_targets_v1
  set
    company_name = case when v_payload ? 'company_name' then v_new_company_name else company_name end,
    company_domain = case when v_payload ? 'company_domain' then v_new_company_domain else company_domain end,
    company_website = case when v_payload ? 'company_website' then v_new_company_website else company_website end,
    country = case when v_payload ? 'country' then v_new_country else country end,
    headquarters = case when v_payload ? 'headquarters' then nullif(btrim(v_payload->>'headquarters'),'') else headquarters end,
    source_name = case when v_payload ? 'source_name' then nullif(btrim(v_payload->>'source_name'),'') else source_name end,
    source_url = case when v_payload ? 'source_url' then nullif(btrim(v_payload->>'source_url'),'') else source_url end,
    sector = case when v_payload ? 'sector' then nullif(btrim(v_payload->>'sector'),'') else sector end,
    product_category = case when v_payload ? 'product_category' then nullif(btrim(v_payload->>'product_category'),'') else product_category end,
    products = case when v_payload ? 'products' then v_products else products end,
    product_summary = case when v_payload ? 'product_summary' then nullif(btrim(v_payload->>'product_summary'),'') else product_summary end,
    manufacturer_description = case when v_payload ? 'manufacturer_description' then nullif(btrim(v_payload->>'manufacturer_description'),'') else manufacturer_description end,
    size_band = case when v_payload ? 'size_band' then nullif(btrim(v_payload->>'size_band'),'') else size_band end,
    why_kosovo = case when v_payload ? 'why_kosovo' then nullif(btrim(v_payload->>'why_kosovo'),'') else why_kosovo end,
    market_evidence = case when v_payload ? 'market_evidence' then nullif(btrim(v_payload->>'market_evidence'),'') else market_evidence end,
    relevant_tenders_or_projects = case when v_payload ? 'relevant_tenders_or_projects' then nullif(btrim(v_payload->>'relevant_tenders_or_projects'),'') else relevant_tenders_or_projects end,
    potential_customer_types = case when v_payload ? 'potential_customer_types' then nullif(btrim(v_payload->>'potential_customer_types'),'') else potential_customer_types end,
    strategic_fit_notes = case when v_payload ? 'strategic_fit_notes' then nullif(btrim(v_payload->>'strategic_fit_notes'),'') else strategic_fit_notes end,
    kosovo_presence = case when v_payload ? 'kosovo_presence' then coalesce(nullif(btrim(v_payload->>'kosovo_presence'),''),'unknown') else kosovo_presence end,
    existing_partner_name = case when v_payload ? 'existing_partner_name' then nullif(btrim(v_payload->>'existing_partner_name'),'') else existing_partner_name end,
    existing_partner_notes = case when v_payload ? 'existing_partner_notes' then nullif(btrim(v_payload->>'existing_partner_notes'),'') else existing_partner_notes end,
    balkans_presence_notes = case when v_payload ? 'balkans_presence_notes' then nullif(btrim(v_payload->>'balkans_presence_notes'),'') else balkans_presence_notes end,
    target_model = case when v_payload ? 'target_model' then coalesce(nullif(btrim(v_payload->>'target_model'),''),'unknown') else target_model end,
    target_territory = case when v_payload ? 'target_territory' then coalesce(nullif(btrim(v_payload->>'target_territory'),''),'Kosovo') else target_territory end,
    stock_required = case when v_payload ? 'stock_required' then case when v_payload->'stock_required'='null'::jsonb then null else (v_payload->>'stock_required')::boolean end else stock_required end,
    minimum_purchase_required = case when v_payload ? 'minimum_purchase_required' then case when v_payload->'minimum_purchase_required'='null'::jsonb then null else (v_payload->>'minimum_purchase_required')::boolean end else minimum_purchase_required end,
    local_financing_required = case when v_payload ? 'local_financing_required' then case when v_payload->'local_financing_required'='null'::jsonb then null else (v_payload->>'local_financing_required')::boolean end else local_financing_required end,
    credit_risk_required = case when v_payload ? 'credit_risk_required' then case when v_payload->'credit_risk_required'='null'::jsonb then null else (v_payload->>'credit_risk_required')::boolean end else credit_risk_required end,
    estimated_capital_requirement = case when v_payload ? 'estimated_capital_requirement' then nullif(btrim(v_payload->>'estimated_capital_requirement'),'') else estimated_capital_requirement end,
    capital_notes = case when v_payload ? 'capital_notes' then nullif(btrim(v_payload->>'capital_notes'),'') else capital_notes end,
    capital_fit = case when v_payload ? 'capital_fit' then coalesce(nullif(btrim(v_payload->>'capital_fit'),''),'unknown') else capital_fit end,
    contact_name = case when v_payload ? 'contact_name' then nullif(btrim(v_payload->>'contact_name'),'') else contact_name end,
    contact_role = case when v_payload ? 'contact_role' then nullif(btrim(v_payload->>'contact_role'),'') else contact_role end,
    contact_email = case when v_payload ? 'contact_email' then lower(nullif(btrim(v_payload->>'contact_email'),'')) else contact_email end,
    contact_phone = case when v_payload ? 'contact_phone' then nullif(btrim(v_payload->>'contact_phone'),'') else contact_phone end,
    linkedin_url = case when v_payload ? 'linkedin_url' then nullif(btrim(v_payload->>'linkedin_url'),'') else linkedin_url end,
    contact_source = case when v_payload ? 'contact_source' then nullif(btrim(v_payload->>'contact_source'),'') else contact_source end,
    priority_score = case when v_payload ? 'priority_score' then case when nullif(v_payload->>'priority_score','') is null then null else (v_payload->>'priority_score')::integer end else priority_score end,
    priority_reason = case when v_payload ? 'priority_reason' then nullif(btrim(v_payload->>'priority_reason'),'') else priority_reason end,
    next_action = case when v_payload ? 'next_action' then nullif(btrim(v_payload->>'next_action'),'') else next_action end,
    next_action_due = case when v_payload ? 'next_action_due' then case when nullif(v_payload->>'next_action_due','') is null then null else (v_payload->>'next_action_due')::date end else next_action_due end,
    notes = case when v_payload ? 'notes' then nullif(btrim(v_payload->>'notes'),'') else notes end,
    last_verified_at = case when v_payload ? 'last_verified_at' then case when nullif(v_payload->>'last_verified_at','') is null then null else (v_payload->>'last_verified_at')::timestamptz end else last_verified_at end,
    stage = case when v_payload ? 'stage' then nullif(btrim(v_payload->>'stage'),'') else stage end,
    last_contact_at = case when v_payload ? 'last_contact_at' then case when nullif(v_payload->>'last_contact_at','') is null then null else (v_payload->>'last_contact_at')::timestamptz end else last_contact_at end,
    gmail_thread_id = case when v_payload ? 'gmail_thread_id' then nullif(btrim(v_payload->>'gmail_thread_id'),'') else gmail_thread_id end,
    gmail_draft_id = case when v_payload ? 'gmail_draft_id' then nullif(btrim(v_payload->>'gmail_draft_id'),'') else gmail_draft_id end,
    gmail_last_message_id = case when v_payload ? 'gmail_last_message_id' then nullif(btrim(v_payload->>'gmail_last_message_id'),'') else gmail_last_message_id end,
    identity_review_status = case when v_payload ? 'identity_review_status' then nullif(btrim(v_payload->>'identity_review_status'),'') else identity_review_status end,
    identity_review_notes = case when v_payload ? 'identity_review_notes' then nullif(btrim(v_payload->>'identity_review_notes'),'') else identity_review_notes end,
    updated_at = now()
  where id=p_target_id
  returning * into v_target;

  v_after := to_jsonb(v_target);

  insert into public.pppp_representation_target_update_audit(command_id,target_id,patch,before_state,after_state,metadata)
  values(v_command_id,p_target_id,v_payload,v_before,v_after,v_metadata)
  on conflict(command_id) do nothing;

  return jsonb_build_object(
    'ok',true,'command_id',v_command_id,'target_id',p_target_id,
    'updated',true,'idempotent_replay',false,'stage',v_target.stage,
    'project_created',false,'partner_created',false,'contact_created',false,
    'supplier_created',false,'outbound_created',false,'contract_created',false,
    'external_email_sent',false,'represented_automatically',false,
    'metadata',v_metadata
  );
end;
$_$;


ALTER FUNCTION public.pppp_chatgpt_update_representation_target_v1(p_command_id text, p_target_id uuid, p_payload jsonb, p_source text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: pppp_chatgpt_upsert_dach_steel_target_v1(text, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_upsert_dach_steel_target_v1(p_command_id text, p_payload jsonb, p_source text DEFAULT 'chatgpt'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_command_id text := nullif(btrim(p_command_id),'');
  v_source text := coalesce(nullif(btrim(p_source),''),'chatgpt');
  v_payload jsonb := coalesce(p_payload,'{}'::jsonb);
  v_metadata jsonb := case when jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))='object' then coalesce(p_metadata,'{}'::jsonb) else '{}'::jsonb end;
  v_receipt public.pppp_chatgpt_command_receipts%rowtype;
  v_unknown_key text;
  v_source_key text;
  v_company_name text;
  v_products text[] := '{}'::text[];
  v_material_scope jsonb := '{}'::jsonb;
  v_evidence jsonb := '[]'::jsonb;
  v_existing_id uuid;
  v_target public.pppp_dach_steel_targets_v1%rowtype;
  v_created boolean := false;
begin
  if v_command_id is null then
    raise exception using errcode='22023', message='command_id_required';
  end if;
  if length(v_command_id)>240 then
    raise exception using errcode='22023', message='command_id_too_long';
  end if;
  if v_source <> 'chatgpt' then
    raise exception using errcode='22023', message='invalid_dach_steel_target_source';
  end if;
  if jsonb_typeof(v_payload) <> 'object' then
    raise exception using errcode='22023', message='dach_steel_target_value_json_must_be_object';
  end if;

  select k into v_unknown_key
  from jsonb_object_keys(v_payload) x(k)
  where k not in (
    'source_key','source_name','source_url',
    'company_name','company_domain','company_website','country','buyer_type',
    'score_band','target_status','why_now',
    'project_title','project_reference','award_date','procurement_timing',
    'quote_readiness','steel_scope','products','estimated_tonnes',
    'material_revision','material_confidence','material_scope','evidence',
    'contact_status','outreach_status','outbound_source_key',
    'next_action','next_action_due','last_verified_at'
  )
  limit 1;
  if v_unknown_key is not null then
    raise exception using errcode='22023', message='dach_steel_target_field_not_allowed:'||v_unknown_key;
  end if;

  v_source_key := nullif(btrim(v_payload->>'source_key'),'');
  v_company_name := nullif(btrim(v_payload->>'company_name'),'');
  if v_source_key is null then raise exception using errcode='22023', message='source_key_required'; end if;
  if length(v_source_key)>500 then raise exception using errcode='22023', message='source_key_too_long'; end if;
  if v_company_name is null then raise exception using errcode='22023', message='company_name_required'; end if;
  if length(v_company_name)>500 then raise exception using errcode='22023', message='company_name_too_long'; end if;

  if nullif(v_payload->>'source_url','') is not null
     and (v_payload->>'source_url') !~* '^https?://' then
    raise exception using errcode='22023', message='source_url_must_be_http_https';
  end if;
  if nullif(v_payload->>'company_website','') is not null
     and (v_payload->>'company_website') !~* '^https?://' then
    raise exception using errcode='22023', message='company_website_must_be_http_https';
  end if;

  if v_payload ? 'products' then
    if jsonb_typeof(v_payload->'products') <> 'array' then
      raise exception using errcode='22023', message='products_must_be_array';
    end if;
    if jsonb_array_length(v_payload->'products') > 30 then
      raise exception using errcode='22023', message='too_many_products';
    end if;
    select coalesce(array_agg(value),'{}'::text[]) into v_products
    from jsonb_array_elements_text(v_payload->'products') as t(value);
  end if;

  v_material_scope := coalesce(v_payload->'material_scope','{}'::jsonb);
  if jsonb_typeof(v_material_scope) <> 'object' then
    raise exception using errcode='22023', message='material_scope_must_be_object';
  end if;
  if v_material_scope ? 'line_items' then
    if jsonb_typeof(v_material_scope->'line_items') <> 'array' then
      raise exception using errcode='22023', message='material_scope_line_items_must_be_array';
    end if;
    if jsonb_array_length(v_material_scope->'line_items') > 200 then
      raise exception using errcode='22023', message='too_many_material_line_items';
    end if;
  end if;

  v_evidence := coalesce(v_payload->'evidence','[]'::jsonb);
  if jsonb_typeof(v_evidence) <> 'array' then
    raise exception using errcode='22023', message='evidence_must_be_array';
  end if;
  if jsonb_array_length(v_evidence)>30 then
    raise exception using errcode='22023', message='too_many_evidence_items';
  end if;


  if v_payload ? 'contact_status' and coalesce(v_payload->>'contact_status','') not in ('missing','searching','found','verified') then
    raise exception using errcode='22023',message='invalid_contact_status:allowed=missing,searching,found,verified';
  end if;
  if v_payload ? 'outreach_status' and coalesce(v_payload->>'outreach_status','') not in ('not_ready','ready','queued','sent','replied','suppressed') then
    raise exception using errcode='22023',message='invalid_outreach_status';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_command_id,0));
  perform pg_advisory_xact_lock(hashtextextended(v_source_key,1));

  select * into v_receipt
  from public.pppp_chatgpt_command_receipts
  where command_id=v_command_id
  for update;

  if not found then
    raise exception using errcode='42501', message='approved_bridge_receipt_required';
  end if;
  if v_receipt.action_type <> 'dach_steel_target' then
    raise exception using errcode='23505', message='command_id_conflict';
  end if;
  if lower(coalesce(v_receipt.approval,'')) <> 'approved' then
    raise exception using errcode='42501', message='dach_steel_target_command_not_approved';
  end if;

  if v_receipt.status='succeeded' then
    begin v_existing_id := nullif(v_receipt.result->>'target_id','')::uuid;
    exception when others then v_existing_id := null; end;
    if v_existing_id is not null and exists(select 1 from public.pppp_dach_steel_targets_v1 where id=v_existing_id) then
      return v_receipt.result || jsonb_build_object('created',false,'idempotent_replay',true);
    end if;
    raise exception using errcode='23514', message='dach_steel_target_receipt_target_missing';
  end if;
  if v_receipt.status <> 'processing' then
    raise exception using errcode='42501', message='dach_steel_target_receipt_not_processing';
  end if;

  -- INSERT triggers run before ON CONFLICT. Use the locked existing identity
  -- for omitted fields without turning them into supplied patch fields.
  select * into v_target
  from public.pppp_dach_steel_targets_v1
  where source_key=v_source_key
  for update;
  v_existing_id := v_target.id;
  v_created := v_existing_id is null;

  insert into public.pppp_dach_steel_targets_v1(
    source_key,source_name,source_url,
    company_name,company_domain,company_website,country,buyer_type,
    score_band,target_status,why_now,
    project_title,project_reference,award_date,procurement_timing,
    quote_readiness,steel_scope,products,estimated_tonnes,
    material_revision,material_confidence,material_scope,evidence,
    contact_status,outreach_status,outbound_source_key,
    next_action,next_action_due,last_verified_at,updated_at
  ) values (
    v_source_key,
    nullif(btrim(v_payload->>'source_name'),''),
    nullif(btrim(v_payload->>'source_url'),''),
    v_company_name,
    coalesce(nullif(btrim(v_payload->>'company_domain'),''),v_target.company_domain),
    coalesce(nullif(btrim(v_payload->>'company_website'),''),v_target.company_website),
    coalesce(upper(nullif(btrim(v_payload->>'country'),'')),v_target.country),
    nullif(btrim(v_payload->>'buyer_type'),''),
    coalesce(nullif(btrim(v_payload->>'score_band'),''),'B1'),
    coalesce(nullif(btrim(v_payload->>'target_status'),''),'watch'),
    nullif(btrim(v_payload->>'why_now'),''),
    nullif(btrim(v_payload->>'project_title'),''),
    nullif(btrim(v_payload->>'project_reference'),''),
    case when nullif(v_payload->>'award_date','') is null then null else (v_payload->>'award_date')::date end,
    nullif(btrim(v_payload->>'procurement_timing'),''),
    coalesce(nullif(btrim(v_payload->>'quote_readiness'),''),'M0'),
    nullif(btrim(v_payload->>'steel_scope'),''),
    v_products,
    case when nullif(v_payload->>'estimated_tonnes','') is null then null else (v_payload->>'estimated_tonnes')::numeric end,
    nullif(btrim(v_payload->>'material_revision'),''),
    case when nullif(v_payload->>'material_confidence','') is null then null else (v_payload->>'material_confidence')::numeric end,
    v_material_scope,
    v_evidence,
    coalesce(nullif(btrim(v_payload->>'contact_status'),''),'missing'),
    coalesce(nullif(btrim(v_payload->>'outreach_status'),''),'not_ready'),
    nullif(btrim(v_payload->>'outbound_source_key'),''),
    nullif(btrim(v_payload->>'next_action'),''),
    case when nullif(v_payload->>'next_action_due','') is null then null else (v_payload->>'next_action_due')::date end,
    case when nullif(v_payload->>'last_verified_at','') is null then now() else (v_payload->>'last_verified_at')::timestamptz end,
    now()
  )
  on conflict(source_key) do update set
    source_name=case when v_payload ? 'source_name' then excluded.source_name else public.pppp_dach_steel_targets_v1.source_name end,
    source_url=case when v_payload ? 'source_url' then excluded.source_url else public.pppp_dach_steel_targets_v1.source_url end,
    company_name=case when v_payload ? 'company_name' then excluded.company_name else public.pppp_dach_steel_targets_v1.company_name end,
    company_domain=case when v_payload ? 'company_domain' then excluded.company_domain else public.pppp_dach_steel_targets_v1.company_domain end,
    company_website=case when v_payload ? 'company_website' then excluded.company_website else public.pppp_dach_steel_targets_v1.company_website end,
    country=case when v_payload ? 'country' then excluded.country else public.pppp_dach_steel_targets_v1.country end,
    buyer_type=case when v_payload ? 'buyer_type' then excluded.buyer_type else public.pppp_dach_steel_targets_v1.buyer_type end,
    score_band=case when v_payload ? 'score_band' then excluded.score_band else public.pppp_dach_steel_targets_v1.score_band end,
    target_status=case when v_payload ? 'target_status' then excluded.target_status else public.pppp_dach_steel_targets_v1.target_status end,
    why_now=case when v_payload ? 'why_now' then excluded.why_now else public.pppp_dach_steel_targets_v1.why_now end,
    project_title=case when v_payload ? 'project_title' then excluded.project_title else public.pppp_dach_steel_targets_v1.project_title end,
    project_reference=case when v_payload ? 'project_reference' then excluded.project_reference else public.pppp_dach_steel_targets_v1.project_reference end,
    award_date=case when v_payload ? 'award_date' then excluded.award_date else public.pppp_dach_steel_targets_v1.award_date end,
    procurement_timing=case when v_payload ? 'procurement_timing' then excluded.procurement_timing else public.pppp_dach_steel_targets_v1.procurement_timing end,
    quote_readiness=case when v_payload ? 'quote_readiness' then excluded.quote_readiness else public.pppp_dach_steel_targets_v1.quote_readiness end,
    steel_scope=case when v_payload ? 'steel_scope' then excluded.steel_scope else public.pppp_dach_steel_targets_v1.steel_scope end,
    products=case when v_payload ? 'products' then excluded.products else public.pppp_dach_steel_targets_v1.products end,
    estimated_tonnes=case when v_payload ? 'estimated_tonnes' then excluded.estimated_tonnes else public.pppp_dach_steel_targets_v1.estimated_tonnes end,
    material_revision=case when v_payload ? 'material_revision' then excluded.material_revision else public.pppp_dach_steel_targets_v1.material_revision end,
    material_confidence=case when v_payload ? 'material_confidence' then excluded.material_confidence else public.pppp_dach_steel_targets_v1.material_confidence end,
    material_scope=public.pppp_dach_steel_targets_v1.material_scope || excluded.material_scope,
    evidence=(select coalesce(jsonb_agg(item order by ord),'[]'::jsonb) from (select item,min(ord) ord from jsonb_array_elements(public.pppp_dach_steel_targets_v1.evidence || excluded.evidence) with ordinality e(item,ord) group by item) d),
    contact_status=case when v_payload ? 'contact_status' then excluded.contact_status else public.pppp_dach_steel_targets_v1.contact_status end,
    outreach_status=case when v_payload ? 'outreach_status' then excluded.outreach_status else public.pppp_dach_steel_targets_v1.outreach_status end,
    outbound_source_key=case when v_payload ? 'outbound_source_key' then excluded.outbound_source_key else public.pppp_dach_steel_targets_v1.outbound_source_key end,
    next_action=case when v_payload ? 'next_action' then excluded.next_action else public.pppp_dach_steel_targets_v1.next_action end,
    next_action_due=case when v_payload ? 'next_action_due' then excluded.next_action_due else public.pppp_dach_steel_targets_v1.next_action_due end,
    last_verified_at=case when v_payload ? 'last_verified_at' then excluded.last_verified_at else public.pppp_dach_steel_targets_v1.last_verified_at end,
    updated_at=now()
  returning * into v_target;

  return jsonb_build_object(
    'ok',true,
    'command_id',v_command_id,
    'target_id',v_target.id,
    'source_key',v_target.source_key,
    'company_name',v_target.company_name,
    'score_band',v_target.score_band,
    'quote_readiness',v_target.quote_readiness,
    'created',v_created,
    'project_created',false,
    'partner_created',false,
    'contact_created',false,
    'outbound_created',false,
    'external_email_sent',false,
    'human_email_approval_required',true,
    'metadata',v_metadata
  );
end;
$$;


ALTER FUNCTION public.pppp_chatgpt_upsert_dach_steel_target_v1(p_command_id text, p_payload jsonb, p_source text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: pppp_chatgpt_waiting_projects_v1(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_chatgpt_waiting_projects_v1(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(x) order by x.is_overdue desc,x.due_date nulls last,x.last_activity_at desc nulls last),'[]'::jsonb)
  from (select * from public.pppp_home_waiting_projects_v1 order by is_overdue desc,due_date nulls last,last_activity_at desc nulls last limit greatest(1,least(coalesce(p_limit,50),100))) x;
$$;


ALTER FUNCTION public.pppp_chatgpt_waiting_projects_v1(p_limit integer) OWNER TO postgres;

--
-- Name: pppp_claim_external_source_daily_access_v1(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_claim_external_source_daily_access_v1(p_source_key text, p_run_token text, p_trigger_name text DEFAULT NULL::text, p_timezone text DEFAULT 'Europe/Budapest'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_source text := upper(btrim(coalesce(p_source_key, '')));
  v_token text := btrim(coalesce(p_run_token, ''));
  v_timezone text := coalesce(nullif(btrim(p_timezone), ''), 'Europe/Budapest');
  v_day date;
  v_claimed_at timestamptz;
  v_existing public.pppp_external_source_daily_access_v1%rowtype;
begin
  if v_source !~ '^[A-Z0-9_:-]{2,80}$' then
    raise exception 'invalid external source key';
  end if;
  if length(v_token) not between 1 and 200 then
    raise exception 'invalid external source run token';
  end if;

  v_day := (now() at time zone v_timezone)::date;

  insert into public.pppp_external_source_daily_access_v1(
    source_key, access_day, timezone, run_token, trigger_name
  ) values (
    v_source, v_day, v_timezone, v_token, left(nullif(btrim(p_trigger_name), ''), 120)
  )
  on conflict (source_key, access_day) do nothing
  returning claimed_at into v_claimed_at;

  if v_claimed_at is not null then
    return jsonb_build_object(
      'allowed', true,
      'source_key', v_source,
      'access_day', v_day,
      'timezone', v_timezone,
      'claimed_at', v_claimed_at
    );
  end if;

  select * into v_existing
  from public.pppp_external_source_daily_access_v1
  where source_key = v_source and access_day = v_day;

  return jsonb_build_object(
    'allowed', false,
    'reason', 'daily_source_access_already_claimed',
    'source_key', v_source,
    'access_day', v_day,
    'timezone', v_timezone,
    'claimed_at', v_existing.claimed_at,
    'existing_trigger', v_existing.trigger_name
  );
end;
$_$;


ALTER FUNCTION public.pppp_claim_external_source_daily_access_v1(p_source_key text, p_run_token text, p_trigger_name text, p_timezone text) OWNER TO postgres;

--
-- Name: pppp_classify_krpp_relevance_v2(text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_classify_krpp_relevance_v2(p_title text, p_fpp text, p_fpp_description text, p_contract_type text, p_procedure text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v_text text;
  v_fpp text := regexp_replace(coalesce(p_fpp, ''), '\D', '', 'g');
  v_raw_direct boolean;
  v_structure_direct boolean;
  v_energy_context boolean;
  v_industrial_context boolean;
  v_structure_context boolean;
  v_negative boolean;
  v_layer text;
  v_score integer;
  v_category text;
  v_reason text;
begin
  v_text := regexp_replace(
    translate(lower(concat_ws(' ',
      p_title,
      p_fpp,
      p_fpp_description,
      p_contract_type,
      p_procedure,
      p_payload->>'short_description',
      p_payload->>'description',
      p_payload->>'full_description',
      p_payload->>'technical_description',
      p_payload->>'scope',
      p_payload->>'notice_summary',
      p_payload->>'object',
      p_payload->'lots',
      p_payload#>>'{dossier_analysis,analysis,steel_scope}',
      p_payload#>>'{dossier_analysis,analysis,scope_summary}',
      p_payload#>>'{dossier_analysis,analysis,technical_requirements}'
    )), 'çë', 'ce'),
    '\s+', ' ', 'g'
  );

  v_raw_direct :=
    (
      v_text ~ '(llamarin|pllak.{0,20}(celik|metal)|material.{0,20}(celik|metal)|lende e pare.{0,20}metal|profil.{0,20}(celik|metal|hekur)|shufr.{0,20}(celik|metal)|trar.{0,20}(celik|metal)|tub|gyp|pipe|coil|bobin|armatur|rebar|b500|\m(ipe|ipn|hea|heb|hem|upe|upn|unp)\M)'
      and v_text ~ '(furniz|blerj|material|produkt|lende e pare|profil|shufr|llamar|pllak|tub|gyp|pipe|trar|coil|bobin|armatur|rebar|b500)'
    )
    or v_fpp ~ '^2711';

  v_structure_direct :=
    (
      v_text ~ '(konstruks|struktur|steelwork|structural steel|hall|mbuloj|strehe|canopy|cati|platform|shkall|rrethoj|rrethim|gardh|parmak|dere|dyer|porta|grating|shtyll|rezervuar|tank|depo|tubacion|pipe rack|piperack|support|frame|ure|ura|bridge|skel)'
      and v_text ~ '(metal|celik|steel)'
    )
    or v_text ~ '(pipe rack|piperack|structural steel|steelwork|steel bridge)'
    or v_text ~ '((rezervuar|tank).{0,90}(mazut|karburant|termocentral|industrial)|(mazut|karburant|termocentral|industrial).{0,90}(rezervuar|tank))'
    or v_fpp ~ '^(44212220|44212240|44212313|44212410|44212500|45223100|45223110|45223210)';

  v_energy_context := v_text ~ '(nenstacion|substation|linj.{0,20}transmet|transmission line|lattice tower|lattice mast|shtyll.{0,20}transmet|tower|mast|gantry|rrjet.{0,20}energ)';
  v_industrial_context := v_text ~ '(transportues|conveyor|chute|hopper|silo|duct|termocentral|power plant|impiant industrial|impiant minerar|mining plant|platform.{0,20}mirembajt|industrial support|mbajtes.{0,20}industrial|mekanik.{0,20}impiant|punime mekanike|district heating|ngrohje qendrore|wastewater|ujer.{0,20}zeza|dige|dam)';
  v_structure_context := v_text ~ '(platform|walkway|catwalk|grating|shkall|stairs|handrail|parmak|rrethoj|rrethim|fence|fencing|gardh|dere|dyer|porta|mbuloj|canopy|cati|hall|warehouse|depo prefabr|konstruksion prefabr|rezervuar|tank|silo|tubacion|piping|ure|ura|bridge|footbridge|support|mbajtese|frame|skelet)';

  v_negative :=
       v_text ~ '(software|licenc|abonim|subscription|sistem informatik|aplikacion|platform.{0,50}(digjital|online|elektronik|tregt|energji|testim|nettest|inteligjenc)|platforme?.{0,50}(software|licenc|digjital|online|elektronik))'
    or v_text ~ '((makin|pajisje|vegel|aparat).{0,80}(prer|cut|sald|weld|shpim|drill).{0,50}(metal|celik|steel)|(prer|cut|sald|weld|shpim|drill).{0,50}(metal|celik|steel).{0,80}(makin|pajisje|vegel|aparat))'
    or v_text ~ '((rruge|rruga|lagj|fshat|lokacion|segment|kulle|kulla|monument|trashegimi|restaurim|konservim).{0,80}\mcelik\M|\mcelik\M.{0,80}(gjilan|rruge|rruga|lagj|fshat|lokacion|monument|trashegimi|restaurim|konservim))'
    or v_text ~ '(ventilim|klimatizim|ashensor|kushinet|bearing|gazra? (teknik|industrial)|bombol.{0,30}gaz|pelhur|thase? filtrues|filter bags)'
    or (
      v_text ~ '(renov|ripar|mirembajt|ngjyros).{0,90}(shkall|dere|dyer|parahyrje)'
      and v_text !~ '(metal|celik|steel|konstruks)'
    );

  if v_negative then
    v_layer := 'excluded';
    v_score := 0;
    v_category := 'possible';
    v_reason := 'jashtë profilit PRISTEEL sipas kontekstit';
  elsif v_raw_direct or v_structure_direct then
    v_layer := 'main';
    v_score := 86;
    v_category := case when v_structure_direct and not v_raw_direct then 'steel_structure' else 'raw_material' end;
    v_reason := case when v_structure_direct and not v_raw_direct
      then 'scope direkt PRISTEEL: strukturë/fabrikim metalik'
      else 'scope direkt PRISTEEL: furnizim me çelik/material metalik' end;
  elsif v_energy_context or v_industrial_context or v_structure_context then
    v_layer := 'review';
    v_score := 58;
    v_category := 'possible';
    v_reason := 'paketë e mundshme industriale/ndërtimore; kërkon verifikim të scope-it';
  else
    v_layer := 'excluded';
    v_score := 0;
    v_category := 'possible';
    v_reason := 'nuk ka scope të mjaftueshëm PRISTEEL';
  end if;

  return jsonb_build_object(
    'layer', v_layer,
    'score', v_score,
    'category', v_category,
    'reason', v_reason,
    'direct_evidence', v_layer = 'main',
    'review_required', v_layer = 'review',
    'version', 'krpp-authority-neutral-v2'
  );
end
$$;


ALTER FUNCTION public.pppp_classify_krpp_relevance_v2(p_title text, p_fpp text, p_fpp_description text, p_contract_type text, p_procedure text, p_payload jsonb) OWNER TO postgres;

--
-- Name: pppp_client_offer_preparation_reconcile_v1(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_client_offer_preparation_reconcile_v1(p_apply boolean DEFAULT false, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare r record;v_analysis jsonb;v_analysis_id bigint;v_seen integer:=0;v_written integer:=0;v_tasks integer:=0;v_ref jsonb;v_ref_line text;
begin for r in select c.* from public.pppp_selected_supplier_cost_basis_v1 c where c.eligible_for_client_offer_handoff order by c.decided_at desc limit least(500,greatest(1,coalesce(p_limit,100))) loop v_seen:=v_seen+1;v_analysis:=public.pppp_client_offer_preparation_v1(r.project_id);v_ref:=v_analysis->'pricing_reference';v_ref_line:=case when nullif(v_ref->>'reference_margin_pct','') is not null then 'PPPP pricing reference (JO çmim i aprovuar): historical margin '||(v_ref->>'reference_margin_pct')||'%'||coalesce(' · reference total EUR '||(v_ref->>'reference_total_eur'),'')||coalesce(' · reference unit EUR '||(v_ref->>'reference_unit_price_eur'),'')||' · confidence '||coalesce(v_analysis#>>'{historical_pricing_reference,confidence}','insufficient')||'.' else 'PPPP pricing reference: historiku i pastër është ende i pamjaftueshëm për rekomandim numerik.' end;
if p_apply then select pa.id into v_analysis_id from public.project_analyses pa where pa.project_id=r.project_id::text and pa.model='client-offer-preparation-v1' order by pa.created_at desc limit 1; if v_analysis_id is null then insert into public.project_analyses(project_id,status,engine,model,analysis,source_manifest,source_counts,created_at) values(r.project_id::text,'complete','commercial_rules','client-offer-preparation-v1',v_analysis,jsonb_build_object('decision_id',r.decision_id,'supplier_offer_id',r.supplier_offer_id),jsonb_build_object('historical_pricing_samples',coalesce((v_analysis#>>'{historical_pricing_reference,valid_sample_count}')::integer,0)),now()); else update public.project_analyses set analysis=v_analysis,source_manifest=jsonb_build_object('decision_id',r.decision_id,'supplier_offer_id',r.supplier_offer_id),source_counts=jsonb_build_object('historical_pricing_samples',coalesce((v_analysis#>>'{historical_pricing_reference,valid_sample_count}')::integer,0)),created_at=now() where id=v_analysis_id; end if;v_written:=v_written+1; insert into public.tasks(project_id,title,detail,due_date,priority,status,source,category,source_ref) values(r.project_id,'Përgatit ofertën për klientin · '||left(r.project_name,145),'Supplier i zgjedhur nga njeriu: '||coalesce(r.selected_supplier,'—')||E'\n'||'Baza e kostos: '||coalesce('EUR '||round(coalesce(r.explicit_total_eur,r.total_eur),2)::text,'shiko analizën e kostos')||E'\n'||v_ref_line||E'\n\nHuman gate: ti vendos çmimin final, marginën/markup-un, kushtet e klientit dhe inclusions/exclusions. PPPP nuk aprovon dhe nuk dërgon ofertën automatikisht.',current_date,'larte','hapur','client_offer_cost_basis_auto','ofertim','COMMERCIAL:'||r.project_id::text||':client-offer-cost-basis') on conflict(source,source_ref) do update set title=excluded.title,detail=excluded.detail,due_date=current_date,priority='larte',status='hapur',done_at=null;v_tasks:=v_tasks+1;end if;end loop; return jsonb_build_object('mode',case when p_apply then 'apply' else 'preview' end,'eligible_projects_seen',v_seen,'analyses_written',v_written,'offer_preparation_tasks_refreshed',v_tasks,'human_final_price_required',true,'generated_at',now());end;$$;


ALTER FUNCTION public.pppp_client_offer_preparation_reconcile_v1(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_client_offer_preparation_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_client_offer_preparation_v1(p_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare c record; v_n integer:=0; v_median numeric; v_won_n integer:=0; v_won_median numeric; v_margin numeric; v_confidence text; v_total_cost numeric; v_suggested_total numeric; v_suggested_unit numeric; v_history jsonb:='[]'::jsonb;
begin
select * into c from public.pppp_selected_supplier_cost_basis_v1 where project_id=p_project_id order by decided_at desc limit 1;
if c.project_id is null then return jsonb_build_object('project_id',p_project_id,'ready',false,'reason','No human-confirmed supplier cost basis exists.','human_final_price_required',true); end if;
with valid as (select * from public.price_history where margin_pct is not null and margin_pct between 0 and 40 and cost_kg is not null and cost_kg>0 and our_price_kg is not null and our_price_kg>=cost_kg)
select count(*)::int,percentile_cont(0.5) within group(order by margin_pct)::numeric,count(*) filter(where lower(coalesce(outcome,'')) in ('fituar','won'))::int,percentile_cont(0.5) within group(order by margin_pct) filter(where lower(coalesce(outcome,'')) in ('fituar','won'))::numeric,coalesce(jsonb_agg(jsonb_build_object('project',project_name,'client',client,'country',country,'work_type',work_type,'our_price_kg',our_price_kg,'cost_kg',cost_kg,'margin_pct',margin_pct,'outcome',outcome,'quoted_at',quoted_at) order by quoted_at desc nulls last),'[]'::jsonb) into v_n,v_median,v_won_n,v_won_median,v_history from valid;
v_margin:=case when v_n>=3 then greatest(0,least(25,round(v_median,2))) else null end; v_confidence:=case when v_n>=15 then 'high' when v_n>=7 then 'medium' when v_n>=3 then 'low' else 'insufficient' end;
v_total_cost:=coalesce(c.explicit_total_eur,case when upper(coalesce(c.currency,''))='EUR' then c.total_amount end,case when c.unit_cost_eur is not null and c.qty_kg is not null then c.unit_cost_eur*c.qty_kg end);
if v_margin is not null and v_margin<100 then if v_total_cost is not null then v_suggested_total:=round((v_total_cost/(1-v_margin/100))::numeric,2); end if; if c.unit_cost_eur is not null then v_suggested_unit:=round((c.unit_cost_eur/(1-v_margin/100))::numeric,4); end if; end if;
return jsonb_build_object('bridge','client-offer-preparation-v1','project_id',c.project_id,'project_name',c.project_name,'client',c.client,'ready',c.eligible_for_client_offer_handoff,'selected_supplier',c.selected_supplier,'supplier_offer_id',c.supplier_offer_id,'supplier_cost_basis',jsonb_build_object('currency',c.currency,'pricing_basis',c.pricing_basis,'unit_cost_eur',c.unit_cost_eur,'total_cost_eur',v_total_cost,'qty_kg',c.qty_kg,'transport_eur',c.transport_eur,'delivery_weeks',c.delivery_weeks,'incoterms',c.incoterms,'payment_terms',c.payment_terms,'validity_days',c.validity_days,'cert',c.cert,'inclusions',c.inclusions,'exclusions',c.exclusions,'readiness',c.cost_basis_readiness,'warnings',c.warning_text),'historical_pricing_reference',jsonb_build_object('valid_sample_count',v_n,'median_margin_pct',v_median,'won_sample_count',v_won_n,'won_median_margin_pct',v_won_median,'confidence',v_confidence,'samples',v_history),'pricing_reference',jsonb_build_object('reference_margin_pct',v_margin,'reference_unit_price_eur',v_suggested_unit,'reference_total_eur',v_suggested_total,'method','historical gross-margin median; selling price = cost / (1 - margin)','reference_only',true),'human_final_price_required',true,'human_client_terms_required',true,'human_send_required',true,'generated_at',now()); end; $$;


ALTER FUNCTION public.pppp_client_offer_preparation_v1(p_project_id uuid) OWNER TO postgres;

--
-- Name: pppp_command_center_v1(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_command_center_v1(p_limit integer DEFAULT 30) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with base as (
  select p.*,
         sw.title as supplier_wait_title,sw.due_date as supplier_wait_due,sw.contact_email as supplier_wait_email,
         t.title as task_title,t.due_date as task_due,t.priority as task_priority,t.category as task_category,t.source as task_source,
         em.subject as last_email_subject,em.direction as last_email_direction,em.from_email as last_email_from,em.sent_at as last_email_at_live,
         case p.pipeline_stage
           when 'rfq_in' then 20 when 'technical_review' then 32 when 'supplier_selection' then 42
           when 'pricing' then 55 when 'client_offer' then 72 when 'commercial' then 86
           when 'production_control' then 100 when 'factory_audit' then 100 when 'transport' then 100 else 15 end
         + case when coalesce(p.last_email_at,p.last_activity_at,p.updated_at,p.created_at) >= now()-interval '3 days' then 6 else 0 end
         as momentum_score,
         case
           when lower(coalesce(p.status,'')) in ('fituar','won') or p.operational_state='execution' then 'EXECUTION'
           when sw.title is not null then 'WAITING_SUPPLIER'
           when p.operational_state='wait_for_client' then 'WAITING_CLIENT'
           when p.operational_state='action_required' then 'ACTION_NOW'
           when p.pipeline_stage='client_offer' then 'QUOTE_SENT'
           when p.pipeline_stage='pricing' then 'QUOTE_IN_PREPARATION'
           when p.pipeline_stage='rfq_in' then 'NEW_RFQ'
           else 'ACTIVE' end as work_lane,
         case
           when p.operational_state='execution' or lower(coalesce(p.status,'')) in ('fituar','won') then 50
           when sw.title is not null and sw.due_date is not null and sw.due_date<=current_date then 90
           when sw.title is not null then 55
           when p.operational_state='action_required' then 100
           when t.due_date is not null and t.due_date<current_date then 95
           when p.pipeline_stage='pricing' then 78
           when p.pipeline_stage='rfq_in' then 72
           when p.operational_state='wait_for_client' and coalesce(p.last_email_at,p.last_activity_at,p.updated_at,p.created_at)<now()-interval '7 days' then 68
           else 40 end as attention_score
  from public.projects p
  left join lateral (
    select x.title,x.due_date,x.contact_email
    from public.tasks x
    where x.project_id=p.id and x.source='supplier_wait_auto' and x.status not in ('kryer','mbyllur','done','closed')
    order by x.due_date asc nulls last,x.created_at desc limit 1
  ) sw on true
  left join lateral (
    select x.title,x.due_date,x.priority,x.category,x.source
    from public.tasks x
    where x.project_id=p.id and x.status not in ('kryer','mbyllur','done','closed')
      and not (sw.title is not null and x.source='project_decision_auto')
    order by case when x.due_date<current_date then 0 when x.due_date=current_date then 1 else 2 end,
             x.due_date asc nulls last,x.created_at desc limit 1
  ) t on true
  left join lateral (
    select e.subject,e.direction,e.from_email,e.sent_at
    from public.project_emails e
    where e.project_id=p.id
    order by e.sent_at desc nulls last limit 1
  ) em on true
  where lower(coalesce(p.status,'')) not in ('humbur','arkivuar','mbyllur','realizuar','lost','closed','cancelled','canceled')
), ranked as (
  select *,
         case
           when work_lane='WAITING_SUPPLIER' then coalesce(supplier_wait_title,'Presim furnitorin')
           when work_lane='WAITING_CLIENT' then coalesce(task_title,'Presim përgjigjen e klientit; follow-up vetëm sipas afatit.')
           when work_lane='EXECUTION' then coalesce(task_title,'Vazhdo veprimin e ardhshëm të ekzekutimit.')
           when task_title is not null then task_title
           when work_lane='QUOTE_IN_PREPARATION' then 'Përfundo kalkulimin dhe draft-ofertën.'
           when work_lane='QUOTE_SENT' then 'Monitoro përgjigjen e klientit dhe afatin e follow-up-it.'
           when work_lane='NEW_RFQ' then 'Analizo dokumentet dhe përcakto kalkulimin/partnerin.'
           else 'Shqyrto aktivitetin e fundit dhe cakto veprimin e ardhshëm.' end as next_action
  from base
  order by attention_score desc,momentum_score desc,coalesce(last_email_at,last_activity_at,updated_at,created_at) desc
  limit greatest(1,least(coalesce(p_limit,30),100))
)
select coalesce(jsonb_agg(jsonb_build_object(
  'project_id',id,'project',name,'client',client,'ref',coalesce(business_ref,ref),
  'status',status,'pipeline_stage',pipeline_stage,'work_lane',work_lane,
  'attention_score',attention_score,'momentum_score',least(momentum_score,100),
  'next_action',next_action,
  'due_date',case when work_lane='WAITING_SUPPLIER' then supplier_wait_due else coalesce(task_due,supplier_wait_due) end,
  'supplier_wait_email',supplier_wait_email,
  'last_email',case when last_email_subject is null then null else jsonb_build_object('subject',last_email_subject,'direction',last_email_direction,'from',last_email_from,'sent_at',last_email_at_live) end,
  'last_activity_at',coalesce(last_email_at,last_activity_at,updated_at,created_at)
) order by attention_score desc,momentum_score desc), '[]'::jsonb)
from ranked;
$$;


ALTER FUNCTION public.pppp_command_center_v1(p_limit integer) OWNER TO postgres;

--
-- Name: pppp_commercial_review_intelligence_reconcile_v1(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_commercial_review_intelligence_reconcile_v1(p_apply boolean DEFAULT false, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  r record;
  v_limit integer:=least(500,greatest(1,coalesce(p_limit,100)));
  v_detail text;
  v_candidates integer;
  v_blockers integer;
  v_tasks integer:=0;
  v_closed integer:=0;
  v_projects integer:=0;
begin
  for r in
    select i.project_id,min(i.project_name) as project_name
    from public.pppp_supplier_offer_review_intelligence_v1 i
    where i.eligible_for_review_task
    group by i.project_id
    order by min(i.project_name)
    limit v_limit
  loop
    v_projects:=v_projects+1;

    select
      count(*)::int,
      count(*) filter(where i.approval_readiness='blocked')::int,
      'PPPP Commercial Review Intelligence — verifiko burimin origjinal para aprovimit.'||E'\n'||
      'Kandidatë në review: '||count(*)::text||' · blocker-a: '||count(*) filter(where i.approval_readiness='blocked')::text||E'\n\n'||
      string_agg(
        '• '||coalesce(nullif(i.supplier_name,''),nullif(i.supplier_email,''),'Furnitor i panjohur')||' · '||
        case
          when i.price_kg is not null then coalesce(i.currency,'?')||' '||round(i.price_kg,4)::text||'/kg'
          when i.unit_price is not null then coalesce(i.currency,'?')||' '||round(i.unit_price,4)::text||'/'||upper(coalesce(i.pricing_basis,'unit'))
          when i.total_amount is not null then coalesce(i.currency,'?')||' total '||round(i.total_amount,2)::text
          else 'çmimi nuk u nxor'
        end||
        coalesce(' · '||i.incoterms,'')||
        coalesce(' · delivery '||i.delivery_weeks::text||' javë','')||
        coalesce(' · valid '||i.validity_days::text||' ditë','')||
        case when coalesce(i.warning_text,'')<>'' then E'\n  '||i.warning_text else '' end,
        E'\n\n' order by i.source_at desc,i.candidate_id
      )||E'\n\nHuman gate: korrigjo/konfirmo të dhënat komerciale dhe aprovo kandidatin vetëm pasi evidenca të jetë e qartë. PPPP nuk zgjedh furnitorin dhe nuk vendos çmimin final automatikisht.'
    into v_candidates,v_blockers,v_detail
    from public.pppp_supplier_offer_review_intelligence_v1 i
    where i.project_id=r.project_id and i.eligible_for_review_task;

    if p_apply then
      insert into public.tasks(project_id,title,detail,due_date,priority,status,source,category,source_ref)
      values(
        r.project_id,
        case when v_blockers>0 then 'Verifiko ofertën e furnitorit · BLOCKER · ' else 'Verifiko ofertën e furnitorit · ' end||left(r.project_name,150),
        v_detail,
        current_date,
        'larte',
        'hapur',
        'commercial_intake_review',
        'furnitor',
        'commercial-intake:'||r.project_id::text||':offer'
      )
      on conflict(source,source_ref) do update
        set project_id=excluded.project_id,
            title=excluded.title,
            detail=excluded.detail,
            due_date=current_date,
            priority=excluded.priority,
            status='hapur',
            done_at=null;
      v_tasks:=v_tasks+1;
    end if;
  end loop;

  if p_apply then
    with closed as (
      update public.tasks t
      set status='mbyllur',done_at=coalesce(t.done_at,now())
      where t.source='commercial_intake_review'
        and t.status='hapur'
        and not exists(
          select 1
          from public.pppp_supplier_offer_review_intelligence_v1 i
          where i.project_id=t.project_id and i.eligible_for_review_task
        )
      returning t.id
    ) select count(*)::int into v_closed from closed;
  end if;

  return jsonb_build_object(
    'mode',case when p_apply then 'apply' else 'preview' end,
    'projects_with_actionable_review',v_projects,
    'tasks_opened_or_refreshed',v_tasks,
    'tasks_closed',v_closed,
    'generated_at',now()
  );
end;
$$;


ALTER FUNCTION public.pppp_commercial_review_intelligence_reconcile_v1(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_company_identity_resolve_v1(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_company_identity_resolve_v1(p_legal_name text, p_domain text DEFAULT NULL::text, p_country_code text DEFAULT NULL::text, p_legal_registration_id text DEFAULT NULL::text, p_source text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_id uuid;
  v_name text:=public.pppp_normalize_company_name_v1(p_legal_name);
  v_domain text:=public.pppp_normalize_company_domain_v1(p_domain);
  v_country text:=upper(nullif(btrim(p_country_code),''));
  v_reg text:=lower(nullif(btrim(p_legal_registration_id),''));
begin
  if nullif(v_name,'') is null then raise exception using errcode='22023',message='company_legal_name_required'; end if;
  if v_reg is not null then select id into v_id from public.pppp_company_identity_v1 where lower(legal_registration_id)=v_reg limit 1; end if;
  if v_id is null and nullif(v_domain,'') is not null then select id into v_id from public.pppp_company_identity_v1 where official_domain=v_domain limit 1; end if;
  if v_id is null then
    select id into v_id from public.pppp_company_identity_v1
    where normalized_name=v_name and coalesce(country_code,'')=coalesce(v_country,'')
    order by official_domain nulls last limit 1;
  end if;
  if v_id is null then
    insert into public.pppp_company_identity_v1(
      legal_name,normalized_name,official_domain,country_code,legal_registration_id,website,source_first_seen,last_verified_at
    ) values (
      btrim(p_legal_name),v_name,nullif(v_domain,''),v_country,v_reg,
      case when nullif(v_domain,'') is null then null else 'https://'||v_domain end,
      nullif(btrim(p_source),''),now()
    ) returning id into v_id;
  else
    update public.pppp_company_identity_v1 set
      legal_name=case when length(btrim(p_legal_name))>length(legal_name) then btrim(p_legal_name) else legal_name end,
      official_domain=coalesce(official_domain,nullif(v_domain,'')),country_code=coalesce(country_code,v_country),
      legal_registration_id=coalesce(legal_registration_id,v_reg),updated_at=now()
    where id=v_id;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION public.pppp_company_identity_resolve_v1(p_legal_name text, p_domain text, p_country_code text, p_legal_registration_id text, p_source text) OWNER TO postgres;

--
-- Name: pppp_confirm_expense_receipt_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_confirm_expense_receipt_v1(p_receipt_id uuid, p_values jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r public.pppp_expense_receipts_v1%rowtype; v_exp uuid; v_supplier text; v_date date; v_cat text; v_amount numeric; v_net numeric; v_vat numeric; v_rate numeric; v_currency text; begin
  select * into r from public.pppp_expense_receipts_v1 where id=p_receipt_id for update;
  if not found then raise exception 'Receipt not found'; end if;
  if r.expense_id is not null then return jsonb_build_object('ok',true,'already_confirmed',true,'expense_id',r.expense_id); end if;
  if r.status in ('ignored','duplicate') then raise exception 'Receipt is not confirmable'; end if;
  v_supplier:=coalesce(nullif(btrim(p_values->>'supplier'),''),r.supplier);
  v_date:=coalesce(nullif(p_values->>'date','')::date,r.expense_date);
  v_cat:=coalesce(nullif(btrim(p_values->>'category'),''),r.category,'tjera');
  v_amount:=coalesce(nullif(p_values->>'amount','')::numeric,r.amount);
  v_net:=coalesce(nullif(p_values->>'net_amount','')::numeric,r.net_amount);
  v_vat:=coalesce(nullif(p_values->>'vat_amount','')::numeric,r.vat_amount,0);
  v_rate:=coalesce(nullif(p_values->>'vat_rate','')::numeric,r.vat_rate,0);
  v_currency:=upper(coalesce(nullif(btrim(p_values->>'currency'),''),r.currency,'EUR'));
  if nullif(btrim(coalesce(v_supplier,'')),'') is null then raise exception 'Supplier is required'; end if;
  if v_date is null then raise exception 'Expense date is required'; end if;
  if v_amount is null or v_amount<=0 then raise exception 'Amount must be greater than zero'; end if;
  if v_net is null then v_net:=greatest(0,v_amount-coalesce(v_vat,0)); end if;
  insert into public.expenses(category,supplier,invoice_nr,date,amount,vat_rate,vat_amount,net_amount,currency,deductible,notes,file_name,receipt_id,project_id,vehicle_plate,quantity,unit,unit_price)
  values(v_cat,v_supplier,coalesce(nullif(btrim(p_values->>'invoice_nr'),''),r.invoice_nr),v_date,v_amount,v_rate,v_vat,v_net,v_currency,
    coalesce((p_values->>'deductible')::boolean,true),nullif(p_values->>'notes',''),r.file_name,r.id,
    coalesce(nullif(p_values->>'project_id','')::uuid,r.project_id),coalesce(nullif(btrim(p_values->>'vehicle_plate'),''),r.vehicle_plate),
    coalesce(nullif(p_values->>'quantity','')::numeric,r.quantity),coalesce(nullif(btrim(p_values->>'unit'),''),r.unit),coalesce(nullif(p_values->>'unit_price','')::numeric,r.unit_price))
  returning id into v_exp;
  update public.pppp_expense_receipts_v1 set expense_id=v_exp,status='confirmed',confirmed_at=now(),
    supplier=v_supplier,expense_date=v_date,category=v_cat,amount=v_amount,net_amount=v_net,vat_amount=v_vat,vat_rate=v_rate,currency=v_currency,
    invoice_nr=coalesce(nullif(btrim(p_values->>'invoice_nr'),''),invoice_nr),project_id=coalesce(nullif(p_values->>'project_id','')::uuid,project_id),
    vehicle_plate=coalesce(nullif(btrim(p_values->>'vehicle_plate'),''),vehicle_plate),quantity=coalesce(nullif(p_values->>'quantity','')::numeric,quantity),unit=coalesce(nullif(btrim(p_values->>'unit'),''),unit),unit_price=coalesce(nullif(p_values->>'unit_price','')::numeric,unit_price),updated_at=now(),last_error=null
  where id=r.id;
  return jsonb_build_object('ok',true,'expense_id',v_exp,'status','confirmed');
end;$$;


ALTER FUNCTION public.pppp_confirm_expense_receipt_v1(p_receipt_id uuid, p_values jsonb) OWNER TO postgres;

--
-- Name: pppp_contact_party_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_contact_party_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_email text;
  v_supplier text;
  v_partner text;
  v_buyer text;
begin
  v_email := lower(trim(coalesce(new.email,'')));
  if v_email='' then return new; end if;

  select p.name into v_supplier
  from public.partner_contacts pc
  join public.partners p on p.id=pc.partner_id
  where lower(trim(coalesce(pc.email,'')))=v_email
    and p.stage='active'
    and coalesce(p.relation,'{}'::text[]) @> array['supplier']::text[]
  order by coalesce(pc.is_primary,false) desc,coalesce(p.importance,0) desc,pc.created_at asc nulls last
  limit 1;
  if v_supplier is not null then
    new.kind := 'supplier';
    new.company := v_supplier;
    return new;
  end if;

  select p.name into v_partner
  from public.partners p
  cross join lateral unnest(array_append(coalesce(p.aliases,array[]::text[]),p.name)) a(name)
  where p.stage='active'
    and coalesce(p.relation,'{}'::text[]) @> array['supplier']::text[]
    and nullif(trim(a.name),'') is not null
    and lower(trim(a.name))=lower(trim(coalesce(new.company,'')))
  order by coalesce(p.importance,0) desc,p.created_at asc nulls last
  limit 1;
  if v_partner is not null then
    new.kind := 'supplier';
    new.company := v_partner;
    return new;
  end if;

  select p.name into v_buyer
  from public.partners p
  cross join lateral unnest(array_append(coalesce(p.aliases,array[]::text[]),p.name)) a(name)
  where p.stage='active'
    and coalesce(p.relation,'{}'::text[]) && array['buyer','lead']::text[]
    and nullif(trim(a.name),'') is not null
    and lower(trim(a.name))=lower(trim(coalesce(new.company,'')))
  order by coalesce(p.importance,0) desc,p.created_at asc nulls last
  limit 1;
  if v_buyer is not null then
    new.kind := 'client';
    new.company := v_buyer;
    return new;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_contact_party_guard_v1() OWNER TO postgres;

--
-- Name: pppp_context_fact_project_truth_reconcile_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_context_fact_project_truth_reconcile_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_event_at timestamptz := coalesce(new.updated_at,new.created_at,clock_timestamp());
  v_current_state text;
  v_state_at timestamptz;
  v_status text;
  v_workflow_state text := lower(coalesce(new.value->>'workflow_state',''));
  v_action_text text := lower(coalesce(new.value->>'action_required',''));
begin
  if new.project_id is null or coalesce(new.fact_status,'')<>'observed' then
    return new;
  end if;

  select lower(coalesce(status,'')),lower(coalesce(operational_state,'')),operational_state_at
    into v_status,v_current_state,v_state_at
  from public.projects
  where id=new.project_id;

  if not found
     or v_status in ('humbur','arkivuar','mbyllur','realizuar','lost','closed','cancelled','canceled','archived')
     or v_current_state in ('closed','execution')
  then
    return new;
  end if;

  if coalesce(new.value->>'source_sent_at','') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T' then
    begin
      v_event_at := (new.value->>'source_sent_at')::timestamptz;
    exception when others then
      v_event_at := coalesce(new.updated_at,new.created_at,clock_timestamp());
    end;
  end if;

  if new.category='commercial_offer'
     and lower(coalesce(new.value->>'status','')) in ('sent','derguar','dërguar')
  then
    update public.projects
       set pipeline_stage=case
         when pipeline_stage in ('rfq_in','technical_review','supplier_selection','pricing','commercial')
           then 'client_offer'
         else pipeline_stage
       end,
       updated_at=clock_timestamp()
     where id=new.project_id;
  end if;

  if new.category='operator_update'
     and (v_state_at is null or v_event_at>=v_state_at)
  then
    if v_action_text in ('false','0','no') then
      update public.projects
         set operational_state=case
               when v_workflow_state in ('wait_for_client','waiting_for_client') then 'wait_for_client'
               else 'active_work'
             end,
             operational_state_at=v_event_at,
             operational_state_source='operator-update-context-v1',
             updated_at=clock_timestamp()
       where id=new.project_id;
    elsif v_action_text in ('true','1','yes') then
      update public.projects
         set operational_state='action_required',
             operational_state_at=v_event_at,
             operational_state_source='operator-update-context-v1',
             updated_at=clock_timestamp()
       where id=new.project_id;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_context_fact_project_truth_reconcile_v1() OWNER TO postgres;

--
-- Name: pppp_context_no_action_reconcile_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_context_no_action_reconcile_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_text text;
begin
  if new.project_id is null or new.evidence_status<>'confirmed' or new.fact_status<>'observed' then return new; end if;
  v_text:=lower(coalesce(new.value::text,''));
  if lower(coalesce(new.category,''))='operator_update' and v_text ~ '(nuk ka.{0,80}(veprim|ndjek)|pa veprim|no action|nothing.{0,50}follow)' then
    update public.tasks t set status='mbyllur',done_at=coalesce(t.done_at,now()),detail=case when position('PPPP: superseded by confirmed no-action operator context.' in coalesce(t.detail,''))>0 then t.detail else concat_ws(E'\n',nullif(t.detail,''),'PPPP: superseded by confirmed no-action operator context.') end where t.project_id=new.project_id and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed') and coalesce(t.source,'')<>'manual';
    update public.projects set operational_state=case when operational_state='execution' then operational_state else 'wait_for_client' end,operational_state_at=case when operational_state='execution' then operational_state_at else coalesce(new.updated_at,new.created_at,now()) end,operational_state_source=case when operational_state='execution' then operational_state_source else 'operator_no_action_context_v1' end,updated_at=now() where id=new.project_id;
  end if;
  return new;
end; $$;


ALTER FUNCTION public.pppp_context_no_action_reconcile_v1() OWNER TO postgres;

--
-- Name: pppp_create_manual_supplier_offer_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_create_manual_supplier_offer_v1(p_project_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_project public.projects%rowtype;
  v_offer public.offers%rowtype;
  v_supplier text := btrim(coalesce(p_payload->>'supplier',''));
  v_currency text := upper(btrim(coalesce(p_payload->>'currency','EUR')));
  v_price_kg numeric;
  v_qty_kg numeric;
  v_mechanical numeric;
  v_packaging numeric;
  v_transport numeric;
  v_total numeric;
  v_total_eur numeric;
  v_fx numeric;
  v_delivery integer;
  v_validity integer;
  v_positions jsonb;
  v_extra_input jsonb := coalesce(p_payload->'extra_positions','[]'::jsonb);
  v_extra_positions jsonb := '[]'::jsonb;
  v_extra_total numeric := 0;
  v_extra_item jsonb;
  v_extra_label text;
  v_extra_amount numeric;
  v_extra_index integer := 0;
  v_actor uuid := auth.uid();
  v_actor_email text := coalesce(auth.jwt()->>'email','');
  v_now timestamptz := now();
begin
  if v_actor is null or not public.can_write() then
    raise exception 'Write permission required' using errcode='42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Manual supplier offer payload is required';
  end if;
  if v_supplier = '' then raise exception 'Supplier is required'; end if;
  if v_currency !~ '^[A-Z]{3}$' then raise exception 'Valid 3-letter currency is required'; end if;

  begin v_price_kg := replace(coalesce(nullif(p_payload->>'price_kg',''),'0'),',','.')::numeric; exception when others then raise exception 'Invalid price_kg'; end;
  begin v_qty_kg := replace(coalesce(nullif(p_payload->>'qty_kg',''),'0'),',','.')::numeric; exception when others then raise exception 'Invalid qty_kg'; end;
  begin v_mechanical := replace(coalesce(nullif(p_payload->>'mechanical_eur',''),'0'),',','.')::numeric; exception when others then raise exception 'Invalid mechanical_eur'; end;
  begin v_packaging := replace(coalesce(nullif(p_payload->>'packaging_eur',''),'0'),',','.')::numeric; exception when others then raise exception 'Invalid packaging_eur'; end;
  begin v_transport := replace(coalesce(nullif(p_payload->>'transport_eur',''),'0'),',','.')::numeric; exception when others then raise exception 'Invalid transport_eur'; end;
  begin v_delivery := nullif(p_payload->>'delivery_weeks','')::integer; exception when others then raise exception 'Invalid delivery_weeks'; end;
  begin v_validity := nullif(p_payload->>'validity_days','')::integer; exception when others then raise exception 'Invalid validity_days'; end;

  if least(v_price_kg,v_qty_kg,v_mechanical,v_packaging,v_transport) < 0 then
    raise exception 'Negative commercial values are not allowed';
  end if;
  if v_price_kg > 0 and v_qty_kg <= 0 then raise exception 'qty_kg is required for kg pricing'; end if;

  if jsonb_typeof(v_extra_input) <> 'array' then
    raise exception 'extra_positions must be an array';
  end if;
  if jsonb_array_length(v_extra_input) > 50 then
    raise exception 'At most 50 extra positions are allowed';
  end if;

  for v_extra_item in select value from jsonb_array_elements(v_extra_input)
  loop
    if jsonb_typeof(v_extra_item) <> 'object' then
      raise exception 'Each extra position must be an object';
    end if;
    v_extra_label := btrim(coalesce(v_extra_item->>'label',''));
    if char_length(v_extra_label) > 120 then
      raise exception 'Extra position label is too long';
    end if;
    begin
      v_extra_amount := replace(coalesce(nullif(v_extra_item->>'amount',''),'0'),',','.')::numeric;
    exception when others then
      raise exception 'Invalid extra position amount';
    end;
    if v_extra_amount < 0 then
      raise exception 'Negative extra position values are not allowed';
    end if;
    if v_extra_amount > 0 and v_extra_label = '' then
      raise exception 'Extra position label is required';
    end if;
    if v_extra_label <> '' and v_extra_amount <= 0 then
      raise exception 'Extra position amount must be positive';
    end if;
    if v_extra_amount > 0 then
      v_extra_index := v_extra_index + 1;
      v_extra_total := v_extra_total + v_extra_amount;
      v_extra_positions := v_extra_positions || jsonb_build_array(
        jsonb_build_object(
          'type','extra',
          'key','extra_' || v_extra_index::text,
          'desc',v_extra_label,
          'qty',1,
          'unit','Pauschale',
          'unit_price',v_extra_amount,
          'total',v_extra_amount
        )
      );
    end if;
  end loop;

  if v_price_kg <= 0 and (v_mechanical + v_packaging + v_transport + v_extra_total) <= 0 then
    raise exception 'At least one positive commercial value is required';
  end if;

  if v_currency='EUR' then
    v_fx := 1;
  else
    begin v_fx := replace(coalesce(nullif(p_payload->>'exchange_rate_to_eur',''),'0'),',','.')::numeric; exception when others then raise exception 'Invalid exchange_rate_to_eur'; end;
    if coalesce(v_fx,0) <= 0 then raise exception 'Reviewed exchange rate to EUR is required for non-EUR offer'; end if;
  end if;

  select * into v_project from public.projects where id=p_project_id;
  if not found then raise exception 'Project not found'; end if;
  if lower(coalesce(v_project.status,'')) in ('humbur','lost','mbyllur','closed','arkivuar','archived','realizuar','cancelled','canceled') then
    raise exception 'Manual supplier offer cannot be added to a terminal project';
  end if;

  v_total := round((v_price_kg*v_qty_kg + v_mechanical + v_packaging + v_transport + v_extra_total)::numeric,2);
  v_total_eur := round((v_total*v_fx)::numeric,2);
  v_positions := jsonb_build_array(
    jsonb_build_object('type','production','desc','Fertigung / Produktion','qty',v_qty_kg,'unit','kg','unit_price',v_price_kg,'total',round(v_price_kg*v_qty_kg,2)),
    jsonb_build_object('type','mechanical','desc','Mechanische Bearbeitung','qty',1,'unit','Pauschale','unit_price',v_mechanical,'total',v_mechanical),
    jsonb_build_object('type','packaging','desc','Verpackung','qty',1,'unit','Pauschale','unit_price',v_packaging,'total',v_packaging),
    jsonb_build_object('type','transport','desc','Transport','qty',1,'unit','Pauschale','unit_price',v_transport,'total',v_transport)
  ) || v_extra_positions;

  insert into public.offers(
    project_id,supplier,price_kg,total_eur,delivery_weeks,incoterms,cert,notes,origin,
    transport_eur,vat_pct,qty_kg,positions,currency,pricing_unit,payment_terms,inclusions,
    exclusions,validity_days,offer_ref,contact_person,raw_text,exchange_rate_to_eur,total_amount,unit_price
  ) values (
    p_project_id,v_supplier,nullif(v_price_kg,0),v_total_eur,v_delivery,nullif(btrim(coalesce(p_payload->>'incoterms','')),''),
    nullif(btrim(coalesce(p_payload->>'cert','')),''),nullif(btrim(coalesce(p_payload->>'notes','')),''),'manual',
    v_transport,0,v_qty_kg,v_positions,v_currency,case when v_price_kg>0 then 'kg' else 'total' end,
    nullif(btrim(coalesce(p_payload->>'payment_terms','')),''),nullif(btrim(coalesce(p_payload->>'inclusions','')),''),
    nullif(btrim(coalesce(p_payload->>'exclusions','')),''),v_validity,nullif(btrim(coalesce(p_payload->>'offer_ref','')),''),
    nullif(btrim(coalesce(p_payload->>'contact_person','')),''),
    concat('Manual supplier offer entered by ',coalesce(nullif(v_actor_email,''),v_actor::text),' at ',v_now::text,coalesce(E'\nSource: '||nullif(btrim(coalesce(p_payload->>'source','')),''),'')),
    v_fx,v_total,null
  ) returning * into v_offer;

  return jsonb_build_object(
    'ok',true,'offer_id',v_offer.id,'project_id',p_project_id,'supplier',v_supplier,'currency',v_currency,
    'total_amount',v_total,'total_eur',v_total_eur,'origin','manual','selected',false,
    'human_supplier_selection_required',true,'created_at',v_offer.created_at
  );
end;
$_$;


ALTER FUNCTION public.pppp_create_manual_supplier_offer_v1(p_project_id uuid, p_payload jsonb) OWNER TO postgres;

--
-- Name: pppp_dach_steel_contact_grade_v1(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_dach_steel_contact_grade_v1(p_email text, p_person text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_company_domain text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_email text := lower(nullif(btrim(p_email),''));
  v_person text := nullif(btrim(p_person),'');
  v_role text := lower(coalesce(nullif(btrim(p_role),''),''));
  v_company_domain text := lower(coalesce(nullif(btrim(p_company_domain),''),''));
  v_domain text;
  v_local text;
  v_named boolean := false;
  v_proc boolean := false;
  v_project boolean := false;
  v_rolebox boolean := false;
  v_general boolean := false;
  v_tier text := 'F';
  v_score integer := 0;
  v_kind text := 'blocked';
  v_reason text := null;
begin
  if v_email is null or v_email !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    return jsonb_build_object('email',v_email,'tier','F','score',0,'outreach_allowed',false,'kind','blocked','reason','invalid_email');
  end if;

  v_domain := split_part(v_email,'@',2);
  v_local := split_part(v_email,'@',1);

  if v_domain in ('gmail.com','googlemail.com','hotmail.com','outlook.com','live.com','yahoo.com','icloud.com','aol.com','example.com','example.org','example.net') then
    return jsonb_build_object('email',v_email,'tier','F','score',0,'outreach_allowed',false,'kind','blocked','reason','personal_or_test_domain');
  end if;

  if v_local in ('jobs','careers','career','hr','humanresources','recruiting','privacy','gdpr','webmaster','press','presse','media','marketing','newsletter','noreply','no-reply','donotreply','dpo','security','abuse') then
    return jsonb_build_object('email',v_email,'tier','F','score',0,'outreach_allowed',false,'kind','blocked','reason','unsafe_recipient_localpart');
  end if;

  if v_company_domain <> '' and v_domain <> v_company_domain then
    return jsonb_build_object('email',v_email,'tier','F','score',0,'outreach_allowed',false,'kind','blocked','reason','recipient_domain_mismatch');
  end if;

  v_named := v_person is not null
    or (
      v_local ~ '^[a-z][a-z0-9]{1,}[._-][a-z][a-z0-9]{1,}$'
      and v_local !~ '(info|office|contact|kontakt|hello|mail|admin|sekretariat|zentrale|enquir|sales|verkauf|einkauf|procurement|purchas|sourcing|material|supply|rfq|quote|quotation)'
    );

  v_proc := v_role ~ '(einkauf|procurement|purchas|sourcing|beschaffung|materialwirtschaft|buyer|achats|acquisti|nabav)'
    or v_local ~ '(einkauf|procurement|purchas|sourcing|beschaffung|material|buyer|achat|acquisti|nabav)';

  v_project := v_role ~ '(projekt|project|technical|technik|commercial|kaufm|construction|bauleit|geschäfts|geschaefts|director|owner|manager|leiter)';

  v_rolebox := v_local ~ '(sales|verkauf|anfrage|rfq|quote|quotation|tender|vergabe|steel|stahl|supply|material|procurement|purchas|einkauf|sourcing|enquir)';

  v_general := v_local in ('info','office','contact','kontakt','hello','mail','admin','sekretariat','zentrale','enquiries','enquiry','general');

  if v_proc and v_named then
    v_tier := 'A'; v_score := 95; v_kind := 'procurement_direct';
  elsif v_project and v_named then
    v_tier := 'B'; v_score := 82; v_kind := 'project_or_management_direct';
  elsif v_proc or v_rolebox then
    v_tier := 'C'; v_score := 70; v_kind := 'role_mailbox';
  elsif v_named then
    v_tier := 'D'; v_score := 60; v_kind := 'direct_public';
  elsif v_company_domain <> '' and v_domain = v_company_domain then
    v_tier := 'D'; v_score := 55; v_kind := case when v_general then 'official_company_fallback' else 'official_domain_contact' end;
  else
    v_tier := 'E'; v_score := 35; v_kind := 'unverified_public_contact';
  end if;

  return jsonb_build_object(
    'email',v_email,
    'person',v_person,
    'role',nullif(p_role,''),
    'tier',v_tier,
    'score',v_score,
    'outreach_allowed',(v_score >= 50),
    'kind',v_kind,
    'reason',v_reason
  );
end;
$_$;


ALTER FUNCTION public.pppp_dach_steel_contact_grade_v1(p_email text, p_person text, p_role text, p_company_domain text) OWNER TO postgres;

--
-- Name: pppp_dach_steel_contact_intelligence_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_dach_steel_contact_intelligence_v1(p_target_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with target as (
  select * from public.pppp_dach_steel_targets_v1 where id=p_target_id
),
resolved as (
  select t.*, x.r,
         lower(coalesce(nullif(btrim(t.company_domain),''),
               nullif(x.r->>'company_domain',''))) as resolved_domain
  from target t
  cross join lateral (select public.pppp_dach_steel_contact_resolution_v1(t.id) as r) x
),
raw_candidates as (
  select r.id, r.company_name, r.resolved_domain, c.item as candidate, c.ord
  from resolved r
  cross join lateral jsonb_array_elements(coalesce(r.r->'candidates','[]'::jsonb)) with ordinality c(item,ord)
),
with_top as (
  select * from raw_candidates
  union all
  select r.id,r.company_name,r.resolved_domain,
         jsonb_build_object(
           'email',r.r->>'email','person',r.r->>'person','role',r.r->>'role',
           'source',r.r->>'source','source_url',r.r->>'source_url','quality',r.r->>'quality'
         ), 0
  from resolved r
  where nullif(r.r->>'email','') is not null
    and not exists (
      select 1 from raw_candidates x
      where lower(x.candidate->>'email')=lower(r.r->>'email')
    )
),
graded as (
  select
    w.*,
    public.pppp_dach_steel_contact_grade_v1(
      w.candidate->>'email',
      w.candidate->>'person',
      w.candidate->>'role',
      w.resolved_domain
    ) as grade
  from with_top w
),
valid as (
  select *
  from graded
  where coalesce((grade->>'outreach_allowed')::boolean,false)
),
best as (
  select *
  from valid
  order by (grade->>'score')::int desc,
           case when candidate->>'source'='contact_master' then 0 else 1 end,
           ord,
           lower(candidate->>'email')
  limit 1
)
select jsonb_build_object(
  'target_id',r.id,
  'company_name',r.company_name,
  'company_domain',nullif(r.resolved_domain,''),
  'status',case when b.candidate is not null then 'found' else 'missing' end,
  'selected',case when b.candidate is null then null else
    b.candidate || jsonb_build_object(
      'tier',b.grade->>'tier',
      'contact_quality_score',(b.grade->>'score')::int,
      'outreach_allowed',(b.grade->>'outreach_allowed')::boolean,
      'contact_kind',b.grade->>'kind'
    ) end,
  'candidates',coalesce((
    select jsonb_agg(
      g.candidate || jsonb_build_object(
        'tier',g.grade->>'tier',
        'contact_quality_score',(g.grade->>'score')::int,
        'outreach_allowed',(g.grade->>'outreach_allowed')::boolean,
        'contact_kind',g.grade->>'kind',
        'block_reason',g.grade->>'reason'
      )
      order by (g.grade->>'score')::int desc, g.ord, lower(g.candidate->>'email')
    )
    from graded g
  ),'[]'::jsonb)
)
from resolved r
left join best b on true;
$$;


ALTER FUNCTION public.pppp_dach_steel_contact_intelligence_v1(p_target_id uuid) OWNER TO postgres;

--
-- Name: pppp_dach_steel_contact_resolution_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_dach_steel_contact_resolution_v1(p_target_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with target as (
  select * from public.pppp_dach_steel_targets_v1 where id=p_target_id
),
evidence_rows as (
  select
    t.source_url as target_source_url,
    e.item,
    concat_ws(' ',
      e.item->>'email',
      e.item->>'label',
      e.item->>'claim',
      e.item->>'title',
      e.item->>'source'
    ) as searchable_text
  from target t
  cross join lateral jsonb_array_elements(coalesce(t.evidence,'[]'::jsonb)) e(item)
),
evidence_emails as (
  select
    lower((regexp_match(searchable_text,
      '([A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,})','i'))[1]) as email,
    nullif(btrim(item->>'person'),'') as person,
    case
      -- A general mailbox mentioned alongside phone-only buyers is not a procurement mailbox.
      when lower(searchable_text) ~ '(general company email|generic contact)' then 'Public company contact'
      when lower(searchable_text) ~ '(einkauf|purchas|procurement|service achats|ufficio acquisti|nabavk|achats|compras|zakupy)' then 'Purchasing / Procurement'
      when lower(searchable_text) like '%commercial department%' then 'Commercial department'
      when lower(searchable_text) like '%official company contact%' then 'Official company contact'
      when lower(searchable_text) like '%company contact%' then 'Public company contact'
      else 'Public contact'
    end as role,
    'target_evidence'::text as source,
    coalesce(item->>'url', target_source_url) as source_url,
    item as source_payload
  from evidence_rows
  where searchable_text ~* '[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}'
),
target_domain as (
  select
    t.*,
    lower(coalesce(
      nullif(btrim(t.company_domain),''),
      (select split_part(email,'@',2) from evidence_emails where email is not null limit 1),
      ''
    )) as resolved_domain,
    regexp_replace(
      regexp_replace(lower(coalesce(t.company_name,'')),
        '\m(gmbh|mbh|ag|kg|co|und|&|stahlbau|metallbau|fahrzeug|technik|metalltechnik)\M','','g'),
      '[^a-z0-9]+','','g'
    ) as company_key
  from target t
),
contact_master_candidates as (
  select
    lower(cm.email) as email,
    nullif(btrim(cm.person),'') as person,
    nullif(btrim(cm.role),'') as role,
    'contact_master'::text as source,
    null::text as source_url,
    cm.sources as source_payload,
    case
      when lower(coalesce(cm.role,'')) ~ '(einkauf|procurement|materialwirtschaft|technischer einkauf|strategischer einkauf|purchas)' then 115
      when lower(coalesce(cm.role,'')) ~ '(kalkulation|kalkulator|projektleiter|project manager|bauleiter)' then 102
      when lower(coalesce(cm.role,'')) ~ '(geschäftsführer|geschaeftsfuehrer|inhaber|director|owner)' then 92
      when split_part(lower(cm.email),'@',1) in ('info','kontakt','office','mail','zentrale') then 62
      else 84
    end + case when nullif(btrim(cm.person),'') is not null then 8 else 0 end as score
  from public.pppp_contact_master_v1 cm
  cross join target_domain t
  where nullif(btrim(cm.email),'') is not null
    and lower(split_part(cm.email,'@',2)) not in ('gmail.com','hotmail.com','outlook.com','yahoo.com','icloud.com','example.com','example.org','example.net')
    and (
      (t.resolved_domain<>'' and lower(split_part(cm.email,'@',2))=t.resolved_domain)
      or (
        t.company_key<>'' and
        regexp_replace(
          regexp_replace(lower(coalesce(cm.company,'')),
            '\m(gmbh|mbh|ag|kg|co|und|&|stahlbau|metallbau|fahrzeug|technik|metalltechnik)\M','','g'),
          '[^a-z0-9]+','','g'
        )=t.company_key
      )
    )
),
evidence_candidates as (
  select
    ev.email, ev.person, ev.role, ev.source, ev.source_url, ev.source_payload,
    case
      when lower(coalesce(ev.role,'')) ~ '(purchas|procurement|einkauf)' then 114
      when split_part(ev.email,'@',1) ~ '(einkauf|procurement|purchas|material|kalk|achat|acquisti|nabav)' then 108
      when split_part(ev.email,'@',1) in ('info','kontakt','office','mail','zentrale') then 58
      when split_part(ev.email,'@',1) ~ '[._\-]' then 88
      else 80
    end as score
  from evidence_emails ev
),
all_candidates as (
  select * from contact_master_candidates
  union all
  select * from evidence_candidates
),
dedup as (
  select distinct on (email)
    email,person,role,source,source_url,source_payload,score
  from all_candidates
  where email is not null and email<>''
  order by email,score desc,case when source='contact_master' then 0 else 1 end
),
ranked as (
  select *,
    case
      when lower(coalesce(role,'')) ~ '(einkauf|procurement|materialwirtschaft|purchas|achats|acquisti|nabav)' or split_part(email,'@',1) ~ '(einkauf|procurement|purchas|material|achat|acquisti|nabav)' then 'procurement'
      when lower(coalesce(role,'')) ~ '(kalkulation|projektleiter|project manager|bauleiter)' then 'project'
      when lower(coalesce(role,'')) ~ '(geschäftsführer|geschaeftsfuehrer|inhaber|director|owner)' then 'management'
      when split_part(email,'@',1) in ('info','kontakt','office','mail','zentrale') then 'general'
      else 'direct_public'
    end as quality
  from dedup
  order by score desc,case when source='contact_master' then 0 else 1 end,email
),
best as (select * from ranked limit 1)
select jsonb_build_object(
  'target_id',t.id,
  'company_name',t.company_name,
  'company_domain',nullif(t.resolved_domain,''),
  'status',case when b.email is not null then 'found' else 'missing' end,
  'email',b.email,
  'person',b.person,
  'role',b.role,
  'source',b.source,
  'source_url',b.source_url,
  'quality',b.quality,
  'score',b.score,
  'candidates',coalesce((
    select jsonb_agg(jsonb_build_object(
      'email',r.email,'person',r.person,'role',r.role,'source',r.source,
      'source_url',r.source_url,'quality',r.quality,'score',r.score
    ) order by r.score desc,r.email)
    from (select * from ranked limit 8) r
  ),'[]'::jsonb)
)
from target_domain t
left join best b on true;
$$;


ALTER FUNCTION public.pppp_dach_steel_contact_resolution_v1(p_target_id uuid) OWNER TO postgres;

--
-- Name: pppp_dach_steel_refresh_draft_internal_request_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_dach_steel_refresh_draft_internal_request_v1(p_target_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_secret text;
  v_request_id bigint;
begin
  if p_target_id is null then
    raise exception using errcode='22023',message='target_id_required';
  end if;

  select decrypted_secret
    into v_secret
  from vault.decrypted_secrets
  where name='gmail_tracker_cron_secret'
  limit 1;

  if nullif(v_secret,'') is null then
    raise exception using errcode='22023',message='dach_steel_refresh_secret_missing';
  end if;

  select net.http_post(
    url := 'https://awqfpnzqwfjrjefoktgd.supabase.co/functions/v1/pppp-dach-steel-draft-generator',
    body := jsonb_build_object('mode','refresh','target_id',p_target_id::text),
    params := '{}'::jsonb,
    headers := jsonb_build_object(
      'Content-Type','application/json',
      'x-pppp-cron-secret',v_secret
    ),
    timeout_milliseconds := 120000
  ) into v_request_id;

  return v_request_id;
end;
$$;


ALTER FUNCTION public.pppp_dach_steel_refresh_draft_internal_request_v1(p_target_id uuid) OWNER TO postgres;

--
-- Name: pppp_dach_steel_refresh_intelligence_trigger_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_dach_steel_refresh_intelligence_trigger_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform public.pppp_dach_steel_refresh_intelligence_v1(new.id,null);
  return new;
end;
$$;


ALTER FUNCTION public.pppp_dach_steel_refresh_intelligence_trigger_v1() OWNER TO postgres;

--
-- Name: pppp_dach_steel_refresh_intelligence_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_dach_steel_refresh_intelligence_v1(p_target_id uuid, p_contact jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  intel jsonb;
  c jsonb;
  current_outreach text;
  current_workflow text;
begin
  intel := public.pppp_dach_steel_target_intelligence_v1(p_target_id,p_contact);
  c := intel->'contact';
  select outreach_status,workflow_state into current_outreach,current_workflow from public.pppp_dach_steel_targets_v1 where id=p_target_id;

  update public.pppp_dach_steel_targets_v1
  set canonical_contact_email = nullif(c->>'email',''),
      canonical_contact_name = nullif(c->>'person',''),
      canonical_contact_role = nullif(c->>'role',''),
      contact_tier = coalesce(nullif(intel->>'contact_tier',''),'F'),
      contact_quality_score = coalesce((intel->>'contact_quality_score')::int,0),
      company_fit_score = (intel->>'company_fit_score')::int,
      commercial_timing_score = (intel->>'commercial_timing_score')::int,
      timing_classification = intel->>'timing_classification',
      message_evidence_score = (intel->>'message_evidence_score')::int,
      outreach_readiness_score = (intel->>'outreach_readiness_score')::int,
      workflow_state = case when current_outreach in ('queued','sent','replied','suppressed') then current_workflow else intel->>'workflow_state' end,
      personalization_facts = coalesce(intel->'personalization_facts','[]'::jsonb),
      readiness_reasons = coalesce(intel->'readiness_reasons','[]'::jsonb),
      contact_status = case when c is not null and nullif(c->>'email','') is not null then 'found' else 'missing' end,
      outreach_status = case
        when current_outreach in ('queued','sent','replied','suppressed') then current_outreach
        when intel->>'workflow_state'='ready_for_outreach' then 'ready'
        else 'not_ready'
      end,
      pristeel_offer_model = coalesce(nullif(pristeel_offer_model,''),intel->>'recommended_offer_model'),
      intelligence_profile = intel,
      intelligence_refreshed_at = now(),
      updated_at = now()
  where id=p_target_id;

  return intel;
end;
$$;


ALTER FUNCTION public.pppp_dach_steel_refresh_intelligence_v1(p_target_id uuid, p_contact jsonb) OWNER TO postgres;

--
-- Name: pppp_dach_steel_target_intelligence_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_dach_steel_target_intelligence_v1(p_target_id uuid, p_contact jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  t public.pppp_dach_steel_targets_v1%rowtype;
  ci jsonb;
  selected jsonb;
  grade jsonb;
  facts jsonb := '[]'::jsonb;
  reasons text[] := '{}'::text[];
  gaps text[] := '{}'::text[];
  company_fit integer;
  timing integer;
  timing_class text;
  message_evidence integer;
  contact_score integer := 0;
  contact_tier text := 'F';
  readiness integer;
  workflow text;
  evidence_count integer := 0;
  fact_count integer := 0;
  freshness_days integer := null;
  supplier_signal boolean := false;
begin
  select * into t from public.pppp_dach_steel_targets_v1 where id=p_target_id;
  if not found then
    raise exception using errcode='23503',message='dach_target_not_found';
  end if;

  ci := public.pppp_dach_steel_contact_intelligence_v1(t.id);
  selected := ci->'selected';

  if p_contact is not null and jsonb_typeof(p_contact)='object' and nullif(btrim(p_contact->>'email'),'') is not null then
    grade := public.pppp_dach_steel_contact_grade_v1(
      p_contact->>'email',
      p_contact->>'person',
      p_contact->>'role',
      coalesce(nullif(t.company_domain,''),ci->>'company_domain')
    );
    if coalesce((grade->>'outreach_allowed')::boolean,false) then
      selected := jsonb_build_object(
        'email',lower(p_contact->>'email'),
        'person',nullif(btrim(p_contact->>'person'),''),
        'role',nullif(btrim(p_contact->>'role'),''),
        'source',coalesce(nullif(p_contact->>'source',''),'selected_contact'),
        'source_url',p_contact->>'source_url',
        'quality',coalesce(nullif(p_contact->>'quality',''),grade->>'kind'),
        'tier',grade->>'tier',
        'contact_quality_score',(grade->>'score')::int,
        'outreach_allowed',true,
        'contact_kind',grade->>'kind'
      );
    else
      selected := null;
    end if;
  end if;

  with candidates as (
    select 1 as ord, nullif(btrim(x),'') as fact
    from unnest(array[
      case when jsonb_typeof(t.personalization_facts)='array' then t.personalization_facts->>0 end,
      case when jsonb_typeof(t.personalization_facts)='array' then t.personalization_facts->>1 end,
      case when jsonb_typeof(t.personalization_facts)='array' then t.personalization_facts->>2 end,
      case when jsonb_typeof(t.personalization_facts)='array' then t.personalization_facts->>3 end,
      t.project_title,t.why_now,t.steel_scope
    ]) with ordinality u(x,ord0)
    where nullif(btrim(x),'') is not null
    union all
    select 100+e.ord::int,
           nullif(btrim(coalesce(e.item->>'claim',e.item->>'title',e.item->>'label')),'')
    from jsonb_array_elements(coalesce(t.evidence,'[]'::jsonb)) with ordinality e(item,ord)
  ),
  cleaned as (
    select fact,min(ord) ord
    from candidates
    where fact is not null
      and fact !~* '[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}'
      and lower(fact) !~ '(prepare (a )?draft|draft only|do not send|mos e dergo|përgatit draft|pergatit draft)'
    group by fact
    order by min(ord)
    limit 4
  )
  select coalesce(jsonb_agg(fact order by ord),'[]'::jsonb),count(*)
  into facts,fact_count
  from cleaned;

  evidence_count := case when jsonb_typeof(t.evidence)='array' then jsonb_array_length(t.evidence) else 0 end;

  company_fit := case upper(coalesce(t.score_band,''))
    when 'A1' then 92 when 'A2' then 82 when 'B1' then 72 when 'B2' then 58 else 50 end;

  if lower(coalesce(t.procurement_timing,'')) ~ '(now|current|immediate|active|0.?3)' then
    timing := 85; timing_class := 'active_procurement';
  elsif t.award_date is not null and t.award_date >= current_date-120 then
    timing := 65; timing_class := 'post_award_window';
  elsif nullif(btrim(t.project_title),'') is not null then
    timing := 50; timing_class := 'future_supplier_qualification';
  else
    timing := 35; timing_class := 'unknown';
  end if;

  message_evidence := case when fact_count>=2 then 78 when evidence_count>=2 then 70 else 35 end;

  if selected is not null then
    contact_score := coalesce((selected->>'contact_quality_score')::int,0);
    contact_tier := coalesce(nullif(selected->>'tier',''),'F');
  end if;

  if company_fit<65 then reasons:=array_append(reasons,'company_fit_below_65'); end if;
  if contact_score<50 then reasons:=array_append(reasons,'contact_quality_below_50'); end if;
  if message_evidence<60 then reasons:=array_append(reasons,'message_evidence_below_60'); end if;
  if fact_count<2 then reasons:=array_append(reasons,'fewer_than_two_specific_facts'); end if;
  if timing<35 then reasons:=array_append(reasons,'commercial_timing_below_35'); end if;

  readiness := round(company_fit*.32 + timing*.24 + contact_score*.28 + message_evidence*.16);

  workflow := case
    when company_fit>=65 and contact_score<50 then 'strong_company_contact_gap'
    when cardinality(reasons)=0 then 'ready_for_outreach'
    when company_fit<65 then 'disqualified'
    else 'research_required'
  end;

  supplier_signal := lower(coalesce(t.evidence::text,'')) ~ '(supplier|supplied by|source from|purchased from|procure.*from|vendor|lieferant|bezogen von|bezugsquelle)';
  if t.estimated_tonnes is null then gaps:=array_append(gaps,'capacity_or_tonnage'); end if;
  if nullif(btrim(t.procurement_timing),'') is null then gaps:=array_append(gaps,'procurement_timing'); end if;
  if selected is null or nullif(btrim(selected->>'person'),'') is null then gaps:=array_append(gaps,'named_contact'); end if;
  if selected is null or coalesce(selected->>'contact_kind','') not in ('procurement_direct','role_mailbox') then gaps:=array_append(gaps,'procurement_contact'); end if;
  if not supplier_signal then gaps:=array_append(gaps,'supplier_or_sourcing_evidence'); end if;
  if t.last_verified_at is null then
    gaps:=array_append(gaps,'verification_date');
  else
    freshness_days:=greatest(0,(current_date - t.last_verified_at::date));
    if freshness_days>90 then gaps:=array_append(gaps,'stale_verification'); end if;
  end if;

  return jsonb_build_object(
    'version','material-trade-intelligence-v1',
    'target_id',t.id,
    'company_fit_score',company_fit,
    'commercial_timing_score',timing,
    'timing_classification',timing_class,
    'message_evidence_score',message_evidence,
    'contact_quality_score',contact_score,
    'contact_tier',contact_tier,
    'outreach_readiness_score',readiness,
    'workflow_state',workflow,
    'readiness_reasons',to_jsonb(reasons),
    'personalization_facts',facts,
    'contact',selected,
    'contact_intelligence',ci,
    'intelligence_gaps',to_jsonb(gaps),
    'evidence_count',evidence_count,
    'specific_fact_count',fact_count,
    'evidence_freshness_days',freshness_days,
    'supplier_sourcing_evidence_found',supplier_signal,
    'recommended_offer_model','material_supply',
    'outreach_allowed',(workflow='ready_for_outreach'),
    'calculated_at',now()
  );
end;
$$;


ALTER FUNCTION public.pppp_dach_steel_target_intelligence_v1(p_target_id uuid, p_contact jsonb) OWNER TO postgres;

--
-- Name: pppp_data_quality_health_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_data_quality_health_v1() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'duplicate_contact_emails',(select count(*) from (select lower(btrim(email)) from public.contacts where coalesce(btrim(email),'')<>'' group by lower(btrim(email)) having count(*)>1) x),
    'project_contact_role_conflicts',(select count(*) from public.project_contacts pc join public.contacts c on lower(btrim(c.email))=lower(btrim(pc.email)) where coalesce(btrim(pc.email),'')<>'' and ((lower(coalesce(c.kind,'')) in ('supplier','furnitor') and lower(coalesce(pc.role,''))='client') or (lower(coalesce(c.kind,'')) in ('client','customer','buyer','gc') and lower(coalesce(pc.role,'')) in ('supplier','furnitor')))),
    'dangling_project_email_links',(select count(*) from public.project_email_links l left join public.projects p on p.id::text=l.project_id left join public.project_emails pe on pe.gmail_message_id=l.gmail_message_id where p.id is null or pe.id is null),
    'legacy_followups_with_reply_evidence',(select count(*) from public.tasks t where t.source='sla_auto' and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed','arkivuar') and exists(select 1 from public.rfq_log q where q.project_id=t.project_id and lower(btrim(coalesce(q.supplier_email,'')))=lower(btrim(coalesce(t.contact_email,''))) and lower(coalesce(q.status,''))='replied')),
    'open_data_integrity_exceptions',(select count(*) from public.tasks t where t.source='data_integrity_audit' and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed','arkivuar')),
    'open_automation_failures',(select count(*) from public.tasks t where t.source='automation_failure' and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed','arkivuar')),
    'followup_candidates',(select count(*) from public.pppp_followup_drafts_v1 d where d.status='candidate'),
    'followup_drafts_ready',(select count(*) from public.pppp_followup_drafts_v1 d where d.status='draft_ready' and d.human_send_required=true)
  );
$$;


ALTER FUNCTION public.pppp_data_quality_health_v1() OWNER TO postgres;

--
-- Name: pppp_document_bom_review_admin_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_document_bom_review_admin_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_attachment_id bigint;
  v_name text;
  v_text text;
  v_subject text;
begin
  if coalesce(new.source,'') <> 'document_bom_review'
     or coalesce(new.source_ref,'') !~ '^ATTACHMENT:[0-9]+$' then
    return new;
  end if;

  v_attachment_id := substring(new.source_ref from 'ATTACHMENT:([0-9]+)')::bigint;

  select a.attachment_name,a.extracted_text,
         (select e.subject
            from public.project_emails e
           where e.gmail_message_id=a.gmail_message_id
             and e.project_id::text=a.project_id
           order by e.sent_at desc
           limit 1)
    into v_name,v_text,v_subject
  from public.project_attachment_links a
  where a.id=v_attachment_id;

  if found and private.pppp_document_administrative_signal_v1(v_name,v_subject,v_text) then
    new.status := 'mbyllur';
    new.done_at := coalesce(new.done_at,now());
    new.priority := coalesce(new.priority,'mesatare');
    new.detail := coalesce(new.detail,'') || E'\nAuto-closed by PPPP: the source has a deterministic administrative/financial signal and is not a technical BOM-review action.';
  end if;

  return new;
end;
$_$;


ALTER FUNCTION public.pppp_document_bom_review_admin_guard_v1() OWNER TO postgres;

--
-- Name: pppp_documents_registry_doc_nr_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_documents_registry_doc_nr_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_doc_nr text:=lower(btrim(coalesce(new.doc_nr,'')));
begin
  if v_doc_nr='' then
    return new;
  end if;

  perform pg_advisory_xact_lock(hashtext('documents_registry:doc_nr:'||v_doc_nr));

  if exists(
    select 1
    from public.documents_registry d
    where lower(btrim(coalesce(d.doc_nr,'')))=v_doc_nr
      and d.id is distinct from new.id
  ) then
    raise exception 'Document number already exists: %',new.doc_nr using errcode='23505';
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_documents_registry_doc_nr_guard_v1() OWNER TO postgres;

