--
-- Name: pppp_email_event_canonical_state_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_email_event_canonical_state_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_state_at timestamptz;
  v_event_at timestamptz;
  v_val jsonb;
begin
  if new.project_id is null or lower(coalesce(new.category,'')) <> 'email_event_ai' then
    return new;
  end if;

  begin
    v_event_at := nullif(new.value->>'source_sent_at','')::timestamptz;
  exception when others then
    v_event_at := null;
  end;

  if v_event_at is null then return new; end if;

  select operational_state_at into v_state_at
  from public.projects
  where id=new.project_id;

  if v_state_at is not null and v_event_at <= v_state_at then
    v_val := coalesce(new.value,'{}'::jsonb);
    v_val := jsonb_set(v_val,'{action_required}','false'::jsonb,true);
    v_val := jsonb_set(v_val,'{home_visible}','false'::jsonb,true);
    v_val := jsonb_set(v_val,'{supersedes_prior_event_actions}','false'::jsonb,true);
    v_val := jsonb_set(v_val,'{workflow_state}',to_jsonb('no_change'::text),true);
    v_val := jsonb_set(v_val,'{suppressed_by_canonical_state}','true'::jsonb,true);
    v_val := jsonb_set(v_val,'{canonical_state_at}',to_jsonb(v_state_at::text),true);
    new.value := v_val;
  end if;
  return new;
end
$$;


ALTER FUNCTION public.pppp_email_event_canonical_state_guard_v1() OWNER TO postgres;

--
-- Name: pppp_email_is_automatic_reply_v1(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_email_is_automatic_reply_v1(p_subject text, p_snippet text, p_from_email text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
select
  lower(coalesce(p_subject,'')) ~
    '(automatische[[:space:]]+antwort|automatisch[[:space:]]+antwoord|automatic[[:space:]]+reply|auto[[:space:]-]*reply|autoreply|autosvar|réponse[[:space:]]+automatique|reponse[[:space:]]+automatique|out[[:space:]]+of[[:space:]]+office|abwesenheitsnotiz|vacation[[:space:]]+reply|holiday[[:space:]]+br(ea|a)k|automatically[[:space:]]+rejected)'
  or lower(coalesce(p_subject,'')||' '||coalesce(p_snippet,'')) ~
    '(ich[[:space:]]+bin[[:space:]]+(bis|vom|ab)|nicht[[:space:]]+im[[:space:]]+haus|außer[[:space:]]+haus|ausser[[:space:]]+haus|i[[:space:]]+am[[:space:]]+out[[:space:]]+of[[:space:]]+the[[:space:]]+office|will[[:space:]]+be[[:space:]]+out[[:space:]]+of[[:space:]]+the[[:space:]]+office|your[[:space:]]+message[[:space:]]+will[[:space:]]+not[[:space:]]+be[[:space:]]+forwarded|vi[[:space:]]+har[[:space:]]+mottagit[[:space:]]+(ditt|dit)[[:space:]]+mejl|quota[[:space:]]+exceeded|mailbox.{0,40}(full|quota))'
  or lower(coalesce(p_from_email,'')) ~ '(mailer-daemon|postmaster)';
$$;


ALTER FUNCTION public.pppp_email_is_automatic_reply_v1(p_subject text, p_snippet text, p_from_email text) OWNER TO postgres;

--
-- Name: pppp_email_key_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_email_key_v1(v text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select case
    when v is null or btrim(v) = '' then ''
    when lower(split_part(btrim(v),'@',2)) in ('gmail.com','googlemail.com')
      then replace(lower(split_part(btrim(v),'@',1)),'.','') || '@gmail.com'
    else lower(btrim(v))
  end
$$;


ALTER FUNCTION public.pppp_email_key_v1(v text) OWNER TO postgres;

--
-- Name: pppp_email_sender_class_v1(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_email_sender_class_v1(p_email text, p_name text DEFAULT NULL::text, p_subject text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
with x as (
  select
    lower(btrim(coalesce(p_email,''))) as email,
    lower(split_part(btrim(coalesce(p_email,'')),'@',1)) as localpart,
    lower(split_part(btrim(coalesce(p_email,'')),'@',2)) as domain,
    lower(coalesce(p_name,'')) as sender_name,
    lower(coalesce(p_subject,'')) as subject
)
select case
  when email='' then 'unknown'
  when domain='prissteel.com'
    or email in ('arianitti@me.com','prissteel@gmail.com')
    then 'internal'
  when email in ('eprokurimi@rks-gov.net','e-prokurimi@keptrust.org','bieter@dtvp.de')
    or domain='dtvp.de' or domain like '%.dtvp.de'
    then 'procurement_system'
  when localpart ~ '(^|[+._-])(no-?reply|do-?not-?reply|mailer-daemon|postmaster|notifications?|dmarc|dmarcreport|mailrobot)([+._-]|$)'
    or email ~ '(ted-no-reply|noreply-dmarc|apps-scripts-notifications)'
    or email in (
      'welcome@supabase.com','hello@purchaser.wlw.com',
      'kompass@icapcrif.com','jira@newtron-services.atlassian.net',
      'info@make.com','raksha@distillmail.com',
      'support@apollo.io','support@newtron.net',
      'formularversand@calenbergingenieure.de'
    )
    or domain in (
      'mail.xing.com','e-mail.xing.com','em.linkedin.com','m.learn.coursera.org',
      'e.mailchimp.com','engage.canva.com','mail.apollo.io','hi.pitch.com',
      'mail.goldfish.sh','connect.blinq.me','updates.resend.com','notifications.resend.com',
      'emailnotifications.microsoft.com','communication.microsoft.com',
      'invitations.mailinblack.com'
    )
    or sender_name like '%dmarc aggregate report%'
    or subject like '%report domain:%submitter:%report-id:%'
    then 'automated_service'
  else 'external'
end
from x;
$_$;


ALTER FUNCTION public.pppp_email_sender_class_v1(p_email text, p_name text, p_subject text) OWNER TO postgres;

--
-- Name: pppp_email_subject_explicit_project_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_email_subject_explicit_project_v1(p_subject text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with params as (
  select lower(regexp_replace(coalesce(p_subject,''),'[^a-zA-Z0-9]+',' ','g')) as subj_norm
), active_projects as (
  select p.id,p.name,p.ref,p.business_ref,p.identity_aliases
  from public.projects p
  where not public.pppp_project_status_is_terminal_v1(p.status)
), raw_identity as (
  select p.id as project_id,trim(x) as raw
  from active_projects p
  cross join lateral unnest(
    array_remove(
      array_cat(array[p.name,p.ref,p.business_ref],coalesce(p.identity_aliases,array[]::text[])),
      null
    )
  ) x
), phrase_identity as (
  select project_id,lower(regexp_replace(raw,'[^a-zA-Z0-9]+',' ','g')) ident
  from raw_identity
  where length(trim(raw))>=8
), hits as (
  select distinct i.project_id
  from phrase_identity i,params x
  where length(trim(i.ident))>=8
    and i.ident not in ('early warning and alarm system')
    and (' '||x.subj_norm||' ') like '% '||i.ident||' %'
)
select case when count(*)=1 then min(project_id::text)::uuid else null end
from hits;
$$;


ALTER FUNCTION public.pppp_email_subject_explicit_project_v1(p_subject text) OWNER TO postgres;

--
-- Name: pppp_enforce_procurement_program_watch_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_enforce_procurement_program_watch_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  w public.pppp_procurement_program_watches%rowtype;
  strategic_reason constant text := 'Strategic program watch: monitor future SPNs and package notices';
begin
  select *
    into w
  from public.pppp_procurement_program_watches
  where status = 'active'
    and parent_source_key = new.source_key
  order by updated_at desc, created_at desc
  limit 1;

  if not found then
    return new;
  end if;

  new.relevance_score := greatest(coalesce(new.relevance_score, 0), w.strategic_relevance);

  if not (strategic_reason = any(coalesce(new.match_reasons, '{}'::text[]))) then
    new.match_reasons := coalesce(new.match_reasons, '{}'::text[]) || strategic_reason;
  end if;

  new.payload := coalesce(new.payload, '{}'::jsonb) || jsonb_build_object(
    'program_reference', w.program_code,
    'workflow_mode', 'program_monitoring',
    'dossier_expected', false,
    'strategic_relevance', 'high',
    'partner_research_policy', w.partner_research_policy,
    'entry_routes', coalesce(
      w.notes -> 'entry_routes',
      jsonb_build_array('direct_bid','consortium_jv','local_partner','representation','subcontractor')
    ),
    'recommended_lane', 'pipeline_watch',
    'home_eligible', false,
    'notice_phase', 'pipeline',
    'human_action_required', false,
    'competition_mode', 'Program monitoring / future SPN tracking'
  );

  return new;
end;
$$;


ALTER FUNCTION public.pppp_enforce_procurement_program_watch_v1() OWNER TO postgres;

--
-- Name: pppp_enqueue_automation_http_v1(text, text, text, integer, integer, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_enqueue_automation_http_v1(p_automation_key text, p_url text, p_secret_name text DEFAULT 'gmail_tracker_cron_secret'::text, p_timeout_ms integer DEFAULT 120000, p_max_attempts integer DEFAULT 3, p_correlation_id uuid DEFAULT NULL::uuid, p_attempt integer DEFAULT 1) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'vault', 'net'
    AS $$
declare
  v_secret text;
  v_request_id bigint;
  v_correlation uuid := coalesce(p_correlation_id,gen_random_uuid());
  v_attempt integer := least(5,greatest(1,coalesce(p_attempt,1)));
  v_max integer := least(5,greatest(v_attempt,coalesce(p_max_attempts,3)));
  v_timeout integer := least(180000,greatest(5000,coalesce(p_timeout_ms,120000)));
begin
  if coalesce(btrim(p_automation_key),'')='' then raise exception 'automation_key is required'; end if;
  if coalesce(btrim(p_url),'')='' then raise exception 'url is required'; end if;
  select decrypted_secret into v_secret from vault.decrypted_secrets where name=p_secret_name limit 1;
  if coalesce(v_secret,'')='' then raise exception 'Internal cron secret % is unavailable',p_secret_name; end if;
  select net.http_get(url:=p_url,headers:=jsonb_build_object('x-pppp-cron-secret',v_secret),timeout_milliseconds:=v_timeout) into v_request_id;
  insert into public.pppp_automation_http_runs(automation_key,correlation_id,attempt,max_attempts,request_id,request_url,secret_name,timeout_ms,status,queued_at,created_at,updated_at)
  values(p_automation_key,v_correlation,v_attempt,v_max,v_request_id,p_url,p_secret_name,v_timeout,'queued',now(),now(),now())
  on conflict(correlation_id,attempt) do update set request_id=excluded.request_id,request_url=excluded.request_url,secret_name=excluded.secret_name,timeout_ms=excluded.timeout_ms,status='queued',http_status=null,timed_out=null,error_message=null,response_excerpt=null,queued_at=now(),completed_at=null,next_retry_at=null,updated_at=now();
  return v_request_id;
exception when others then
  begin
    insert into public.pppp_automation_http_runs(automation_key,correlation_id,attempt,max_attempts,request_url,secret_name,timeout_ms,status,error_message,completed_at,created_at,updated_at)
    values(coalesce(nullif(btrim(p_automation_key),''),'unknown'),v_correlation,v_attempt,v_max,coalesce(nullif(btrim(p_url),''),'unknown'),coalesce(nullif(btrim(p_secret_name),''),'unknown'),v_timeout,'failed',left(sqlerrm,1000),now(),now(),now())
    on conflict(correlation_id,attempt) do update set status='failed',error_message=left(sqlerrm,1000),completed_at=now(),updated_at=now();
    insert into public.tasks(title,detail,due_date,priority,status,source,category,source_ref)
    values('Automation failure · '||coalesce(nullif(btrim(p_automation_key),''),'unknown'),'PPPP could not enqueue the managed HTTP automation. '||left(sqlerrm,800),current_date,'larte','hapur','automation_failure','intern','AUTOMATION:http:'||v_correlation::text)
    on conflict(source,source_ref) do update set title=excluded.title,detail=excluded.detail,due_date=excluded.due_date,priority='larte',status='hapur',done_at=null;
  exception when others then null;
  end;
  raise;
end;$$;


ALTER FUNCTION public.pppp_enqueue_automation_http_v1(p_automation_key text, p_url text, p_secret_name text, p_timeout_ms integer, p_max_attempts integer, p_correlation_id uuid, p_attempt integer) OWNER TO postgres;

--
-- Name: pppp_ensure_ted_opportunity_action_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_ensure_ted_opportunity_action_v1(p_tender_watch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_t public.kek_tender_watch%rowtype;
  v_company text; v_email text; v_role text; v_route text; v_action_type text; v_action_key text; v_brief text;
  v_action public.pppp_opportunity_actions%rowtype; v_created boolean:=false; v_profile_id uuid; v_contact_count integer:=0;
begin
  select * into v_t from public.kek_tender_watch where id=p_tender_watch_id;
  if not found then raise exception using errcode='22023',message='tender_not_found'; end if;
  if upper(coalesce(v_t.payload->>'source',''))<>'TED' or coalesce(v_t.payload->>'notice_phase','')<>'award'
    then raise exception using errcode='22023',message='ted_award_required'; end if;
  v_company:=nullif(btrim(v_t.payload->'winner'->>'name'),'');
  if v_company is null then raise exception using errcode='22023',message='winner_identity_missing'; end if;

  select c.email into v_email from public.pppp_ted_contact_candidates_v1(p_tender_watch_id)c
  order by c.confidence_score desc,c.email limit 1;
  if v_email is null then raise exception using errcode='22023',message='verified_ted_winner_contact_missing'; end if;

  v_role:=lower(coalesce(nullif(v_t.payload->'winner'->>'company_type',''),nullif(v_t.payload->'winner'->'company_classification'->>'company_type',''),'unknown'));
  if v_role='unknown' and lower(coalesce(v_t.payload->'award_role'->>'type',''))='gc_epc'
     and lower(coalesce(v_t.payload->'award_role'->>'confidence','')) in('medium','high') then v_role:='gc_epc'; end if;
  if v_role='producer' then v_route:='TED_PRODUCER';v_action_type:='producer_capacity_outreach_draft';
  elsif v_role in('trader_consortium','consortium_mixed') then v_route:='TED_CONSORTIUM';v_action_type:='consortium_project_outreach_draft';
  elsif v_role='gc_epc' then v_route:='TED_GC';v_action_type:='gc_project_outreach_draft';
  else v_route:='TED_GENERAL';v_action_type:='general_project_outreach_draft'; end if;

  v_action_key:='TENDER:'||p_tender_watch_id::text||':'||v_action_type;
  v_brief:=v_company||' ka fituar “'||coalesce(v_t.title,'Opportunity')||'”. Përgatit draft neutral dhe profesional për furnizim/prodhim çeliku sipas projektit; vetëm draft, mos e dërgo automatikisht.';

  select * into v_action from public.pppp_opportunity_actions
  where tender_watch_id=p_tender_watch_id and action_type=v_action_type and status='draft_review'
  order by updated_at desc limit 1;

  if found then
    update public.pppp_opportunity_actions set
      target_company=v_company,target_email=coalesce(nullif(target_email,''),v_email),route=v_route,
      subject_hint=coalesce(nullif(subject_hint,''),'Steel fabrication support · '||left(coalesce(v_t.title,'Opportunity'),300)),
      draft_brief=coalesce(nullif(draft_brief,''),v_brief),outreach_engine_version='v2',outreach_motion='awarded_project_gc',
      payload=coalesce(payload,'{}'::jsonb)||jsonb_build_object('company_type',v_role,'project_title',v_t.title,'engine_version','manual-opportunity-action-rpc-v1','human_approval_required',true),
      updated_at=now()
    where id=v_action.id returning * into v_action;
  else
    insert into public.pppp_opportunity_actions(
      tender_watch_id,action_key,action_type,route,status,priority,target_company,target_email,subject_hint,draft_brief,payload,
      outreach_engine_version,outreach_motion,workflow_state,company_fit_score,commercial_timing_score,contact_quality_score,
      message_evidence_score,outreach_readiness_score,contact_tier,personalization_facts,readiness_reasons,pristeel_offer_model
    ) values(
      p_tender_watch_id,v_action_key,v_action_type,v_route,'draft_review','lartë',v_company,v_email,
      'Steel fabrication support · '||left(coalesce(v_t.title,'Opportunity'),300),v_brief,
      jsonb_build_object('company_type',v_role,'project_title',v_t.title,'engine_version','manual-opportunity-action-rpc-v1','human_approval_required',true),
      'v2','awarded_project_gc','strong_company_contact_gap',70,60,70,78,70,'C',jsonb_build_array(v_t.title,v_brief),'[]'::jsonb,'fabricated_steel_package'
    )
    on conflict(action_key) do update set
      target_company=excluded.target_company,
      target_email=coalesce(nullif(public.pppp_opportunity_actions.target_email,''),excluded.target_email),
      route=excluded.route,updated_at=now()
    returning * into v_action;
    v_created:=true;
  end if;

  perform public.pppp_refresh_opportunity_intelligence_v1(1);

  select s.company_profile_id into v_profile_id
  from public.pppp_opportunity_company_assessments_v1 s where s.action_id=v_action.id limit 1;

  if v_profile_id is not null then
    insert into public.pppp_opportunity_contacts_v1(
      company_profile_id,tender_watch_id,email,full_name,job_title,functional_role,source_type,source_url,
      verification_status,confidence_score,draft_eligible,last_verified_at,payload,updated_at
    )
    select v_profile_id,p_tender_watch_id,c.email,c.full_name,c.job_title,c.functional_role,c.source_type,c.source_url,
           'verified',c.confidence_score,true,now(),c.payload,now()
    from public.pppp_ted_contact_candidates_v1(p_tender_watch_id)c
    on conflict(company_profile_id,email) do update set
      tender_watch_id=excluded.tender_watch_id,
      full_name=coalesce(excluded.full_name,public.pppp_opportunity_contacts_v1.full_name),
      job_title=coalesce(excluded.job_title,public.pppp_opportunity_contacts_v1.job_title),
      functional_role=excluded.functional_role,
      source_type=coalesce(excluded.source_type,public.pppp_opportunity_contacts_v1.source_type),
      source_url=coalesce(excluded.source_url,public.pppp_opportunity_contacts_v1.source_url),
      verification_status=case when public.pppp_opportunity_contacts_v1.verification_status='rejected' then 'rejected' else 'verified' end,
      confidence_score=greatest(public.pppp_opportunity_contacts_v1.confidence_score,excluded.confidence_score),
      draft_eligible=case when public.pppp_opportunity_contacts_v1.do_not_contact then false else true end,
      last_verified_at=now(),
      payload=coalesce(public.pppp_opportunity_contacts_v1.payload,'{}'::jsonb)||excluded.payload,
      updated_at=now();

    select count(*) into v_contact_count from public.pppp_opportunity_contacts_v1
    where company_profile_id=v_profile_id and verification_status='verified' and draft_eligible and not do_not_contact;
    if v_contact_count>0 then
      update public.pppp_opportunity_actions set
        workflow_state='ready_for_outreach',
        payload=jsonb_set(coalesce(payload,'{}'::jsonb),'{outreach_readiness_v1}',
          coalesce(payload->'outreach_readiness_v1','{}'::jsonb)||jsonb_build_object('contact_identity_verified',true),true),
        updated_at=now()
      where id=v_action.id;
    end if;
  end if;

  return jsonb_build_object('ok',true,'action_id',v_action.id,'created',v_created,'tender_watch_id',p_tender_watch_id,
    'company',v_company,'contact_email',v_email,'canonical_contact_count',v_contact_count,
    'gmail_drafts_created',0,'emails_sent',0,'human_approval_required',true);
end;
$$;


ALTER FUNCTION public.pppp_ensure_ted_opportunity_action_v1(p_tender_watch_id uuid) OWNER TO postgres;

--
-- Name: pppp_eu_direct_target_normalize_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_eu_direct_target_normalize_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_domain text;
begin
  v_domain := public.pppp_normalize_company_domain_v1(coalesce(nullif(new.company_domain,''), nullif(new.company_website,'')));
  if nullif(v_domain,'') is null then
    raise exception using errcode='22023', message='company_domain_required';
  end if;
  new.company_domain_normalized := v_domain;
  new.company_domain := v_domain;
  if nullif(new.company_website,'') is null then new.company_website := 'https://' || v_domain; end if;
  if nullif(new.country_code,'') is not null then new.country_code := upper(btrim(new.country_code)); end if;
  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION public.pppp_eu_direct_target_normalize_v1() OWNER TO postgres;

--
-- Name: pppp_execution_release_confirmed_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_execution_release_confirmed_v1(p_project_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
select exists(select 1 from public.pppp_project_context_current_v f where f.project_id=p_project_id and f.evidence_status='confirmed' and f.fact_status='observed' and (lower(coalesce(f.fact_key,'')) ~ '(release|weld|saldim|freigab)' or lower(coalesce(f.value::text,'')) ~ '(drit.{0,20}gjelber.{0,80}sald|saldim.{0,60}aprov|weld.{0,60}(approv|release)|freigab.{0,100}(schwei|schweiß)|schwei.{0,100}freigab)'))
or exists(select 1 from public.project_emails e where e.project_id=p_project_id and lower(coalesce(e.direction,''))='incoming' and lower(coalesce(e.subject,'')||' '||coalesce(e.snippet,'')) ~ '(freigab.{0,140}(schwei|schweiß)|((schwei|schweiß).{0,140}freigab)|you can.{0,60}weld|can.{0,60}weld|mund.{0,80}(schwei|schweiß)|drit.{0,30}gjelber.{0,100}sald|saldim.{0,80}aprov)'); $$;


ALTER FUNCTION public.pppp_execution_release_confirmed_v1(p_project_id uuid) OWNER TO postgres;

--
-- Name: pppp_execution_release_snapshot_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_execution_release_snapshot_v1(p_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  p public.projects%rowtype;
  v_requirements_review integer:=0;
  v_requirements_confirmed integer:=0;
  v_bom_review integer:=0;
  v_attachment_review integer:=0;
  v_document_tasks integer:=0;
  v_ready boolean:=false;
begin
  select * into p from public.projects where id=p_project_id;
  if not found then raise exception 'Project not found'; end if;

  select count(*) filter(where status='review'),count(*) filter(where status='confirmed')
    into v_requirements_review,v_requirements_confirmed
  from public.project_requirements where project_id=p_project_id;

  select count(*) into v_bom_review
  from public.bom_items
  where project_id=p_project_id and needs_review is true;

  select count(*) into v_attachment_review
  from public.project_attachment_links a
  where a.project_id=p_project_id::text
    and (
      a.bom_status in ('review','conflict_review')
      or a.analysis_status in ('needs_vision','needs_ocr','local_ocr_queued','local_ocr_failed','image_review')
    );

  select count(*) into v_document_tasks
  from public.tasks t
  where t.project_id=p_project_id
    and t.source in ('document_bom_review','document_image_review')
    and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed');

  v_ready := v_requirements_review=0 and v_bom_review=0 and v_attachment_review=0 and v_document_tasks=0;
  return jsonb_build_object(
    'project_id',p.id,'project_name',p.name,'status',p.status,'pipeline_stage',p.pipeline_stage,
    'requirements_review',v_requirements_review,
    'requirements_confirmed',v_requirements_confirmed,
    'bom_review',v_bom_review,
    'attachment_review',v_attachment_review,
    'document_review_tasks',v_document_tasks,
    'ready',v_ready,
    'generated_at',now()
  );
end;
$$;


