--
-- Name: pppp_extract_requirements_from_attachment_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_extract_requirements_from_attachment_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_project uuid;
  v_facts jsonb;
  v_tier text;
  v_status text;
  v_item text;
  v_ref text;
  v_text text;
  v_inc text;
  v_deadline text[];
  v_date date;
begin
  if new.project_id is null or lower(coalesce(new.analysis_status,'')) <> 'analyzed' then return new; end if;
  begin v_project := new.project_id::uuid; exception when others then return new; end;
  v_facts := coalesce(new.extracted_data->'facts','{}'::jsonb);
  v_tier := coalesce(nullif(new.extracted_data->>'trust_tier',''),case when coalesce(new.analysis_method,'') ilike '%ocr%' then 'ocr' else 'text' end);
  v_status := case when v_tier='ocr' or lower(coalesce(new.bom_status,'')) in ('review','conflict_review') then 'review' else 'confirmed' end;
  v_ref := new.id::text;
  v_text := coalesce(new.extracted_text,'');

  if jsonb_typeof(v_facts->'standards')='array' then
    for v_item in select jsonb_array_elements_text(v_facts->'standards') loop
      if nullif(trim(v_item),'') is not null then
        insert into public.project_requirements(project_id,requirement_key,category,value_text,status,trust_tier,source_type,source_ref,source_name,last_seen,metadata)
        values(v_project,'standard:'||public.pppp_requirement_norm_v1(v_item),'standard',v_item,v_status,v_tier,'attachment',v_ref,new.attachment_name,now(),jsonb_build_object('analysis_method',new.analysis_method,'confidence',new.analysis_confidence))
        on conflict (project_id,requirement_key,source_type,source_ref) do update set value_text=excluded.value_text,status=excluded.status,trust_tier=excluded.trust_tier,source_name=excluded.source_name,last_seen=now(),metadata=excluded.metadata;
      end if;
    end loop;
  end if;

  if jsonb_typeof(v_facts->'execution_classes')='array' then
    for v_item in select jsonb_array_elements_text(v_facts->'execution_classes') loop
      if nullif(trim(v_item),'') is not null then
        insert into public.project_requirements(project_id,requirement_key,category,value_text,status,trust_tier,source_type,source_ref,source_name,last_seen,metadata)
        values(v_project,'execution_class:'||public.pppp_requirement_norm_v1(v_item),'execution_class',v_item,v_status,v_tier,'attachment',v_ref,new.attachment_name,now(),'{}'::jsonb)
        on conflict (project_id,requirement_key,source_type,source_ref) do update set status=excluded.status,trust_tier=excluded.trust_tier,last_seen=now();
      end if;
    end loop;
  end if;

  if jsonb_typeof(v_facts->'steel_grades')='array' then
    for v_item in select jsonb_array_elements_text(v_facts->'steel_grades') loop
      if nullif(trim(v_item),'') is not null then
        insert into public.project_requirements(project_id,requirement_key,category,value_text,status,trust_tier,source_type,source_ref,source_name,last_seen,metadata)
        values(v_project,'steel_grade:'||public.pppp_requirement_norm_v1(v_item),'steel_grade',v_item,v_status,v_tier,'attachment',v_ref,new.attachment_name,now(),'{}'::jsonb)
        on conflict (project_id,requirement_key,source_type,source_ref) do update set status=excluded.status,trust_tier=excluded.trust_tier,last_seen=now();
      end if;
    end loop;
  end if;

  if jsonb_typeof(v_facts->'certificates')='array' then
    for v_item in select jsonb_array_elements_text(v_facts->'certificates') loop
      if nullif(trim(v_item),'') is not null then
        insert into public.project_requirements(project_id,requirement_key,category,value_text,status,trust_tier,source_type,source_ref,source_name,last_seen,metadata)
        values(v_project,'certificate:'||public.pppp_requirement_norm_v1(v_item),'certificate',v_item,v_status,v_tier,'attachment',v_ref,new.attachment_name,now(),'{}'::jsonb)
        on conflict (project_id,requirement_key,source_type,source_ref) do update set status=excluded.status,trust_tier=excluded.trust_tier,last_seen=now();
      end if;
    end loop;
  end if;

  if jsonb_typeof(v_facts->'surface')='array' then
    for v_item in select jsonb_array_elements_text(v_facts->'surface') loop
      if nullif(trim(v_item),'') is not null then
        insert into public.project_requirements(project_id,requirement_key,category,value_text,status,trust_tier,source_type,source_ref,source_name,last_seen,metadata)
        values(v_project,'surface:'||public.pppp_requirement_norm_v1(v_item),'surface',v_item,v_status,v_tier,'attachment',v_ref,new.attachment_name,now(),'{}'::jsonb)
        on conflict (project_id,requirement_key,source_type,source_ref) do update set status=excluded.status,trust_tier=excluded.trust_tier,last_seen=now();
      end if;
    end loop;
  end if;

  if nullif(trim(v_facts->>'project_reference'),'') is not null then
    insert into public.project_requirements(project_id,requirement_key,category,value_text,status,trust_tier,source_type,source_ref,source_name,last_seen,metadata)
    values(v_project,'project_reference','reference',v_facts->>'project_reference',v_status,v_tier,'attachment',v_ref,new.attachment_name,now(),'{}'::jsonb)
    on conflict (project_id,requirement_key,source_type,source_ref) do update set value_text=excluded.value_text,status=excluded.status,last_seen=now();
  end if;

  if nullif(trim(v_facts->>'drawing_number'),'') is not null then
    insert into public.project_requirements(project_id,requirement_key,category,value_text,status,trust_tier,source_type,source_ref,source_name,last_seen,metadata)
    values(v_project,'drawing_number','reference',v_facts->>'drawing_number',v_status,v_tier,'attachment',v_ref,new.attachment_name,now(),'{}'::jsonb)
    on conflict (project_id,requirement_key,source_type,source_ref) do update set value_text=excluded.value_text,status=excluded.status,last_seen=now();
  end if;

  if new.extracted_data ? 'dynamic_plan' then
    insert into public.project_requirements(project_id,requirement_key,category,value_json,status,trust_tier,source_type,source_ref,source_name,last_seen,metadata)
    values(v_project,'dynamic_plan','schedule',new.extracted_data->'dynamic_plan',v_status,v_tier,'attachment',v_ref,new.attachment_name,now(),jsonb_build_object('preliminary',coalesce((new.extracted_data->'dynamic_plan'->>'preliminary')::boolean,false)))
    on conflict (project_id,requirement_key,source_type,source_ref) do update set value_json=excluded.value_json,status=excluded.status,last_seen=now(),metadata=excluded.metadata;
  end if;

  v_inc := upper((regexp_match(v_text,'(?i)\m(DDP|DAP|FCA|EXW|CFR|CIF|FOB|CPT|CIP)\M'))[1]);
  if nullif(v_inc,'') is not null then
    insert into public.project_requirements(project_id,requirement_key,category,value_text,status,trust_tier,source_type,source_ref,source_name,last_seen,metadata)
    values(v_project,'incoterm:'||lower(v_inc),'commercial',v_inc,v_status,v_tier,'attachment',v_ref,new.attachment_name,now(),jsonb_build_object('detected_by','regex'))
    on conflict (project_id,requirement_key,source_type,source_ref) do update set status=excluded.status,last_seen=now();
  end if;

  v_deadline := regexp_match(v_text,'(?i)(?:rok\s+za\s+ponud|offer\s+deadline|submission\s+deadline|angebotsfrist|ponud[^0-9]{0,20})([0-9]{1,2})[./-]([0-9]{1,2})[./-]([0-9]{4})');
  if v_deadline is not null then
    begin
      v_date:=make_date(v_deadline[3]::int,v_deadline[2]::int,v_deadline[1]::int);
      insert into public.project_requirements(project_id,requirement_key,category,value_text,value_json,status,trust_tier,source_type,source_ref,source_name,last_seen,metadata)
      values(v_project,'offer_deadline','deadline',v_date::text,jsonb_build_object('date',v_date,'type','offer_submission'),v_status,v_tier,'attachment',v_ref,new.attachment_name,now(),jsonb_build_object('detected_by','regex'))
      on conflict (project_id,requirement_key,source_type,source_ref) do update set value_text=excluded.value_text,value_json=excluded.value_json,status=excluded.status,last_seen=now();
    exception when others then null;
    end;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_extract_requirements_from_attachment_v1() OWNER TO postgres;

--
-- Name: pppp_extract_strong_rfq_ref_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_extract_strong_rfq_ref_v1(p_subject text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  m text[];
  token text;
begin
  m := regexp_match(coalesce(p_subject,''), '\m(ANF)[[:space:]-]*([0-9]{3,})\M', 'i');
  if m is not null then
    return upper(m[1]) || '-' || m[2];
  end if;

  m := regexp_match(coalesce(p_subject,''), '\m(RFQ|RFP)[[:space:]#:/-]*([A-Z0-9._/-]*[0-9][A-Z0-9._/-]*)', 'i');
  if m is not null then
    token := upper(regexp_replace(coalesce(m[2],''), '^[#:/ -]+|[#:/ -]+$', '', 'g'));
    if length(token) >= 3 then
      return upper(m[1]) || '-' || token;
    end if;
  end if;
  return null;
end;
$_$;


ALTER FUNCTION public.pppp_extract_strong_rfq_ref_v1(p_subject text) OWNER TO postgres;

--
-- Name: pppp_finalize_krpp_relevance_route_v2(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_finalize_krpp_relevance_route_v2() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_layer text;
begin
  if upper(coalesce(new.payload->>'source', 'KRPP')) <> 'KRPP' then return new; end if;
  v_layer := coalesce(new.payload->>'krpp_relevance_layer', 'excluded');
  new.payload := coalesce(new.payload, '{}'::jsonb) || jsonb_build_object(
    'pristeel_relevance_gate', case v_layer when 'main' then 'strong' when 'review' then 'review' else 'not_active' end,
    'route_screening_status', case v_layer when 'main' then 'pending_business_route_screening' when 'review' then 'pending_relevance_review' else 'not_active' end,
    'human_action_required', (v_layer in ('main','review') and coalesce(new.status,'new') <> 'ignored')
  );
  return new;
end
$$;


