--
-- Name: pppp_followup_rfq_identity_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_followup_rfq_identity_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_sent_date date;
  v_rfq_id uuid;
  v_ref text;
  v_existing_id uuid;
  v_subject text;
  v_supplier_domain text;
  v_subject_key text;
  v_peer_count integer:=0;
begin
  if lower(coalesce(new.source,'')) not in ('sla_auto','auto_followup')
     or new.project_id is null
     or btrim(coalesce(new.contact_email,'')) = '' then
    return new;
  end if;

  begin
    v_sent_date := nullif(substring(coalesce(new.detail,'') from '(20[0-9]{2}-[0-9]{2}-[0-9]{2})'),'')::date;
  exception when others then
    v_sent_date := null;
  end;

  select r.id,r.subject
    into v_rfq_id,v_subject
  from public.rfq_log r
  where r.project_id = new.project_id
    and lower(coalesce(r.supplier_email,'')) = lower(new.contact_email)
    and lower(coalesce(r.status,'')) = 'sent'
    and r.sent_at is not null
    and r.replied_at is null
  order by case when v_sent_date is not null and r.sent_at::date = v_sent_date then 0 else 1 end,
           r.sent_at desc,
           r.id desc
  limit 1;

  if v_rfq_id is null then
    return new;
  end if;

  v_ref := 'RFQ:' || v_rfq_id::text;
  v_supplier_domain := lower(btrim(split_part(new.contact_email,'@',2)));
  v_subject_key := lower(btrim(coalesce(v_subject,'')));

  if v_supplier_domain='' then
    new.source_ref:=v_ref;
    return new;
  end if;

  select count(*)::integer
    into v_peer_count
  from public.rfq_log r
  where r.project_id=new.project_id
    and lower(coalesce(r.status,''))='sent'
    and r.sent_at is not null
    and r.replied_at is null
    and lower(btrim(split_part(r.supplier_email,'@',2)))=v_supplier_domain
    and lower(btrim(coalesce(r.subject,'')))=v_subject_key;

  if v_peer_count>1 and position('PPPP: supplier-domain follow-up —' in coalesce(new.detail,''))=0 then
    new.detail:=concat_ws(E'\n',nullif(new.detail,''),
      'PPPP: supplier-domain follow-up — '||v_peer_count::text||' kontakte në të njëjtin domain kanë marrë këtë RFQ; shfaqet vetëm një veprim njerëzor.');
  end if;

  select t.id
    into v_existing_id
  from public.tasks t
  left join public.rfq_log er on t.source_ref='RFQ:'||er.id::text
  where t.project_id = new.project_id
    and lower(coalesce(t.source,'')) in ('sla_auto','auto_followup')
    and (
      (
        lower(coalesce(t.contact_email,'')) = lower(new.contact_email)
        and (
          t.source_ref = v_ref
          or (
            t.source_ref is null
            and (
              v_sent_date is null
              or nullif(substring(coalesce(t.detail,'') from '(20[0-9]{2}-[0-9]{2}-[0-9]{2})'),'')::date = v_sent_date
            )
          )
        )
      )
      or (
        lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed')
        and er.project_id=new.project_id
        and er.replied_at is null
        and lower(btrim(split_part(er.supplier_email,'@',2)))=v_supplier_domain
        and lower(btrim(coalesce(er.subject,'')))=v_subject_key
      )
    )
  order by case when lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed') then 0 else 1 end,
           t.created_at desc,
           t.id desc
  limit 1;

  if v_existing_id is not null then
    update public.tasks
       set title = new.title,
           detail = new.detail,
           due_date = new.due_date,
           priority = new.priority,
           status = new.status,
           done_at = new.done_at,
           contact_email = new.contact_email,
           category = new.category,
           source_ref = v_ref
     where id = v_existing_id;
    return null;
  end if;

  new.source_ref := v_ref;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_followup_rfq_identity_guard_v1() OWNER TO postgres;

