--
-- Name: pppp_gc_domain_from_email_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_gc_domain_from_email_v1(p_email text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select case
    when position('@' in coalesce(p_email,''))>1
    then public.pppp_gc_normalize_domain_v1(split_part(lower(btrim(p_email)),'@',2))
    else null
  end;
$$;


ALTER FUNCTION public.pppp_gc_domain_from_email_v1(p_email text) OWNER TO postgres;

--
-- Name: pppp_gc_followup_due_v1(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_gc_followup_due_v1(p_sent_at timestamp with time zone) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
declare
  d date;
  dow integer;
begin
  if p_sent_at is null then return null; end if;
  d := (p_sent_at at time zone 'Europe/Belgrade')::date + 7;
  dow := extract(isodow from d)::integer;
  if dow=6 then d:=d+2; elsif dow=7 then d:=d+1; end if;
  return d;
end;
$$;


ALTER FUNCTION public.pppp_gc_followup_due_v1(p_sent_at timestamp with time zone) OWNER TO postgres;

--
-- Name: pppp_gc_historical_outreach_v1(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_gc_historical_outreach_v1(p_company text, p_domain text, p_email text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_domain text:=public.pppp_gc_normalize_domain_v1(coalesce(p_domain,public.pppp_gc_domain_from_email_v1(p_email)));
  v_email text:=lower(btrim(coalesce(p_email,'')));
  v_name text:=public.pppp_gc_normalize_company_v1(p_company);
  r record;
begin
  select o.id,o.status,o.touch_1,o.touch_2,o.replied,o.bounced,o.gmail_thread_id,o.company_name,o.company_domain,o.contact_email
    into r
  from public.outreach_contacts o
  where (
      (v_domain is not null and public.pppp_gc_normalize_domain_v1(o.company_domain)=v_domain)
      or (v_email<>'' and lower(btrim(coalesce(o.contact_email,'')))=v_email)
      or (v_name is not null and public.pppp_gc_normalize_company_v1(o.company_name)=v_name)
    )
    and (
      o.touch_1 is not null or o.gmail_message_id is not null
      or lower(coalesce(o.status,'')) in ('sent','replied','meeting','bounced','dormant','closed')
    )
  order by coalesce(o.touch_2,o.touch_1) desc nulls last,o.updated_at desc nulls last,o.id desc
  limit 1;

  if found then
    return jsonb_build_object(
      'contacted',true,'outreach_contact_id',r.id,'status',r.status,'touch_1',r.touch_1,'touch_2',r.touch_2,
      'replied',coalesce(r.replied,false),'bounced',coalesce(r.bounced,false),'gmail_thread_id',r.gmail_thread_id,
      'matched_company',r.company_name,'matched_domain',r.company_domain,'matched_email',r.contact_email
    );
  end if;

  if exists(
    select 1 from public.contacts c
    where c.last_contact is not null
      and (
        (v_email<>'' and lower(btrim(coalesce(c.email,'')))=v_email)
        or (v_domain is not null and public.pppp_gc_domain_from_email_v1(c.email)=v_domain)
      )
  ) then
    return jsonb_build_object('contacted',true,'status','contact_master_last_contact','outreach_contact_id',null);
  end if;

  return jsonb_build_object('contacted',false);
end;
$$;


ALTER FUNCTION public.pppp_gc_historical_outreach_v1(p_company text, p_domain text, p_email text) OWNER TO postgres;

--
-- Name: pppp_gc_language_v1(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_gc_language_v1(p_country text, p_country_code text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select case
    when upper(coalesce(p_country_code,'')) in ('DE','AT','CH')
      or lower(coalesce(p_country,'')) in ('germany','deutschland','austria','österreich','osterreich','switzerland','schweiz','suisse') then 'de'
    when upper(coalesce(p_country_code,'')) in ('HR','ME','RS')
      or lower(coalesce(p_country,'')) in ('croatia','hrvatska','montenegro','crna gora','serbia','srbija') then 'sr'
    else 'en'
  end;
$$;


ALTER FUNCTION public.pppp_gc_language_v1(p_country text, p_country_code text) OWNER TO postgres;

--
-- Name: pppp_gc_mark_bounced_v1(uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_gc_mark_bounced_v1(p_prospect_id uuid, p_bounced_at timestamp with time zone, p_reason text DEFAULT 'gmail_bounce'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p public.pppp_gc_prospects_v1%rowtype; begin
  select * into p from public.pppp_gc_prospects_v1 where id=p_prospect_id for update;
  if not found then raise exception 'Prospect not found'; end if;
  update public.pppp_gc_prospects_v1
     set bounced_at=coalesce(bounced_at,p_bounced_at,now()),status='bounced',no_more_auto=true,followup_due_date=null,
         duplicate_reason=coalesce(duplicate_reason,p_reason),updated_at=now(),last_error=null
   where id=p.id;
  if p.outreach_contact_id is not null then
    update public.outreach_contacts set bounced=true,status='Bounced',follow_up_date=null,updated_at=now() where id=p.outreach_contact_id;
  end if;
  return jsonb_build_object('ok',true,'status','bounced','no_more_auto',true);
end;$$;


