--
-- Name: pppp_gc_mark_second_sent_v1(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_gc_mark_second_sent_v1(p_prospect_id uuid, p_message_id text, p_thread_id text, p_sent_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  p public.pppp_gc_prospects_v1%rowtype;
begin
  select * into p from public.pppp_gc_prospects_v1 where id=p_prospect_id for update;
  if not found then raise exception 'Prospect not found'; end if;
  if p.second_sent_at is not null then return jsonb_build_object('ok',true,'already_recorded',true,'second_sent_at',p.second_sent_at); end if;
  if p.first_sent_at is null then raise exception 'First send is not recorded'; end if;
  if p_sent_at is null then raise exception 'sent_at required'; end if;

  if p.outreach_contact_id is not null then
    update public.outreach_contacts
       set touch_2=coalesce(touch_2,(p_sent_at at time zone 'Europe/Belgrade')::date),
           status=case when coalesce(replied,false) then status else 'Sent 2' end,
           follow_up_date=null,
           gmail_message_id=coalesce(p_message_id,gmail_message_id),
           gmail_thread_id=coalesce(p_thread_id,gmail_thread_id),
           updated_at=now()
     where id=p.outreach_contact_id;
  end if;

  update public.pppp_gc_prospects_v1
     set second_gmail_message_id=p_message_id,
         first_gmail_thread_id=coalesce(p_thread_id,first_gmail_thread_id),
         second_sent_at=p_sent_at,
         status='contacted_2',
         no_more_auto=true,
         updated_at=now(),last_error=null
   where id=p.id;

  if p.contact_id is not null then
    update public.contacts
       set last_contact=greatest(coalesce(last_contact,(p_sent_at at time zone 'Europe/Belgrade')::date),(p_sent_at at time zone 'Europe/Belgrade')::date)
     where id=p.contact_id;
  end if;
  return jsonb_build_object('ok',true,'status','contacted_2','no_more_auto',true);
end;
$$;


ALTER FUNCTION public.pppp_gc_mark_second_sent_v1(p_prospect_id uuid, p_message_id text, p_thread_id text, p_sent_at timestamp with time zone) OWNER TO postgres;

--
-- Name: pppp_gc_normalize_company_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_gc_normalize_company_v1(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  with a as (
    select lower(btrim(coalesce(p_name,''))) as s
  ), b as (
    select regexp_replace(s,'[^a-z0-9]+',' ','g') as s from a
  ), c as (
    select btrim(regexp_replace(s,'([[:space:]]+(gmbh|mbh|ag|se|kg|co|ltd|limited|plc|llp|inc|corp|corporation|bv|nv|oy|ab|as|asa|sa|srl|spa|sas|sarl|doo|dd|kft|sp|z|o))+$','','i')) as s from b
  )
  select nullif(regexp_replace(s,'[[:space:]]+',' ','g'),'') from c;
$_$;


ALTER FUNCTION public.pppp_gc_normalize_company_v1(p_name text) OWNER TO postgres;

--
-- Name: pppp_gc_normalize_domain_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_gc_normalize_domain_v1(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  with a as (
    select lower(btrim(coalesce(p_value,''))) as s
  ), b as (
    select regexp_replace(s,'^[a-z][a-z0-9+.-]*://','','i') as s from a
  ), c as (
    select split_part(split_part(split_part(split_part(s,'/',1),'?',1),'#',1),':',1) as s from b
  )
  select nullif(regexp_replace(s,'^www[.]','','i'),'') from c;
$$;


ALTER FUNCTION public.pppp_gc_normalize_domain_v1(p_value text) OWNER TO postgres;

