--
-- Name: pppp_gc_register_contact_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_gc_register_contact_v1(p_prospect_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  p public.pppp_gc_prospects_v1%rowtype;
  c public.contacts%rowtype;
  v_email text;
  v_domain text;
begin
  select * into p from public.pppp_gc_prospects_v1 where id=p_prospect_id;
  if not found then raise exception 'Prospect not found'; end if;
  v_email:=nullif(lower(btrim(coalesce(p.contact_email,''))), '');
  v_domain:=public.pppp_gc_normalize_domain_v1(coalesce(p.company_domain,p.website_url,public.pppp_gc_domain_from_email_v1(v_email)));
  if v_email is not null then
    select * into c from public.contacts where lower(btrim(coalesce(email,'')))=v_email order by created_at limit 1;
    if found and lower(coalesce(c.kind,''))='supplier' then
      update public.pppp_gc_prospects_v1 set status='human_review',duplicate_reason='Contact exists as supplier in Contact Master',updated_at=now() where id=p.id;
      return c.id;
    end if;
  else
    if v_domain is not null then
      select * into c from public.contacts where lower(coalesce(kind,''))='client' and public.pppp_gc_domain_from_email_v1(email)=v_domain order by last_contact desc nulls last,created_at limit 1;
    end if;
    if not found then
      select * into c from public.contacts where lower(coalesce(kind,''))='client' and public.pppp_gc_normalize_company_v1(company)=public.pppp_gc_normalize_company_v1(p.company_name) order by last_contact desc nulls last,created_at limit 1;
    end if;
  end if;
  if not found then
    insert into public.contacts(kind,company,person,email,country,role,notes)
    values('client',p.company_name,nullif(p.contact_name,''),v_email,p.country,coalesce(nullif(p.contact_role,''),'GC/GU prospect'),'PPPP GC/GU Prospecting — automated public-source discovery. External email send requires human approval.') returning * into c;
  else
    update public.contacts set company=coalesce(nullif(company,''),p.company_name),country=coalesce(nullif(country,''),p.country),person=coalesce(nullif(person,''),nullif(p.contact_name,'')),role=coalesce(nullif(role,''),nullif(p.contact_role,''),'GC/GU prospect') where id=c.id;
  end if;
  if not exists(select 1 from public.contact_sources s where s.contact_id=c.id::text and s.source='gc_gu_prospecting' and s.external_id=p.id::text) then
    insert into public.contact_sources(contact_id,email,source,external_id,external_url,first_seen,last_seen,metadata)
    values(c.id::text,v_email,'gc_gu_prospecting',p.id::text,coalesce(p.contact_source_url,p.source_url),now(),now(),jsonb_build_object('company_domain',p.company_domain,'company_type',p.company_type,'relevance_score',p.relevance_score,'language',p.language,'current_projects',p.current_projects,'recent_projects',p.recent_projects,'evidence',p.evidence));
  end if;
  update public.pppp_gc_prospects_v1 set contact_id=c.id,updated_at=now() where id=p.id;
  return c.id;
end;
$$;


ALTER FUNCTION public.pppp_gc_register_contact_v1(p_prospect_id uuid) OWNER TO postgres;

--
-- Name: pppp_gc_upsert_prospect_v1(text, text, text, text, text, text, integer, text, text, text, text, integer, jsonb, jsonb, jsonb, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_gc_upsert_prospect_v1(p_company_name text, p_company_domain text DEFAULT NULL::text, p_website_url text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_country_code text DEFAULT NULL::text, p_company_type text DEFAULT 'GC/GU'::text, p_relevance_score integer DEFAULT 0, p_contact_name text DEFAULT NULL::text, p_contact_email text DEFAULT NULL::text, p_contact_role text DEFAULT NULL::text, p_contact_source_url text DEFAULT NULL::text, p_contact_confidence integer DEFAULT NULL::integer, p_current_projects jsonb DEFAULT '[]'::jsonb, p_recent_projects jsonb DEFAULT '[]'::jsonb, p_evidence jsonb DEFAULT '[]'::jsonb, p_discovery_source text DEFAULT 'web_search'::text, p_source_url text DEFAULT NULL::text, p_discovery_run_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_domain text;
  v_key text;
  v_hist jsonb;
  v_status text;
  v_reason text;
  v_id uuid;
  v_contact_id uuid;
  v_email text:=nullif(lower(btrim(coalesce(p_contact_email,''))), '');
begin
  if coalesce(btrim(p_company_name),'')='' then raise exception 'company_name_required'; end if;

  v_domain:=public.pppp_gc_normalize_domain_v1(coalesce(p_company_domain,p_website_url,public.pppp_gc_domain_from_email_v1(v_email)));
  v_key:=public.pppp_gc_company_key_v1(p_company_name,v_domain,p_country_code);
  v_hist:=public.pppp_gc_historical_outreach_v1(p_company_name,v_domain,v_email);

  if coalesce((v_hist->>'contacted')::boolean,false) then
    v_status:='already_contacted';
    v_reason:='Historical outreach already exists';
  elsif v_email is not null and p_contact_confidence is not null and p_contact_confidence>=70 then
    v_status:='contact_ready';
  else
    v_status:='research_ready';
  end if;

  insert into public.pppp_gc_prospects_v1(
    discovery_run_id,company_key,company_name,company_domain,website_url,country,country_code,company_type,relevance_score,
    status,language,contact_name,contact_email,contact_role,contact_source_url,contact_confidence,current_projects,recent_projects,evidence,
    discovery_source,source_url,outreach_contact_id,no_more_auto,duplicate_reason,last_seen_at,researched_at,updated_at
  ) values(
    p_discovery_run_id,v_key,btrim(p_company_name),v_domain,p_website_url,p_country,upper(nullif(btrim(p_country_code),'')),coalesce(nullif(p_company_type,''),'GC/GU'),
    least(100,greatest(0,coalesce(p_relevance_score,0))),v_status,public.pppp_gc_language_v1(p_country,p_country_code),
    p_contact_name,v_email,p_contact_role,p_contact_source_url,p_contact_confidence,
    coalesce(p_current_projects,'[]'::jsonb),coalesce(p_recent_projects,'[]'::jsonb),coalesce(p_evidence,'[]'::jsonb),
    coalesce(nullif(p_discovery_source,''),'web_search'),p_source_url,nullif(v_hist->>'outreach_contact_id','')::bigint,
    coalesce((v_hist->>'contacted')::boolean,false),v_reason,now(),now(),now()
  )
  on conflict(company_key) do update set
    company_name=excluded.company_name,
    company_domain=coalesce(excluded.company_domain,public.pppp_gc_prospects_v1.company_domain),
    website_url=coalesce(excluded.website_url,public.pppp_gc_prospects_v1.website_url),
    country=coalesce(excluded.country,public.pppp_gc_prospects_v1.country),
    country_code=coalesce(excluded.country_code,public.pppp_gc_prospects_v1.country_code),
    company_type=coalesce(excluded.company_type,public.pppp_gc_prospects_v1.company_type),
    relevance_score=greatest(excluded.relevance_score,public.pppp_gc_prospects_v1.relevance_score),
    contact_name=coalesce(excluded.contact_name,public.pppp_gc_prospects_v1.contact_name),
    contact_email=coalesce(excluded.contact_email,public.pppp_gc_prospects_v1.contact_email),
    contact_role=coalesce(excluded.contact_role,public.pppp_gc_prospects_v1.contact_role),
    contact_source_url=coalesce(excluded.contact_source_url,public.pppp_gc_prospects_v1.contact_source_url),
    contact_confidence=greatest(coalesce(excluded.contact_confidence,0),coalesce(public.pppp_gc_prospects_v1.contact_confidence,0)),
    current_projects=case when jsonb_array_length(coalesce(excluded.current_projects,'[]'::jsonb))>0 then excluded.current_projects else public.pppp_gc_prospects_v1.current_projects end,
    recent_projects=case when jsonb_array_length(coalesce(excluded.recent_projects,'[]'::jsonb))>0 then excluded.recent_projects else public.pppp_gc_prospects_v1.recent_projects end,
    evidence=case when jsonb_array_length(coalesce(excluded.evidence,'[]'::jsonb))>0 then excluded.evidence else public.pppp_gc_prospects_v1.evidence end,
    discovery_run_id=coalesce(excluded.discovery_run_id,public.pppp_gc_prospects_v1.discovery_run_id),
    source_url=coalesce(excluded.source_url,public.pppp_gc_prospects_v1.source_url),
    last_seen_at=now(),researched_at=now(),updated_at=now(),
    status=case
      when public.pppp_gc_prospects_v1.status in ('contacted_1','followup_due','draft_2_ready','contacted_2','replied','no_response_2','bounced','do_not_contact') then public.pppp_gc_prospects_v1.status
      when excluded.status='already_contacted' then 'already_contacted'
      when public.pppp_gc_prospects_v1.status='human_review' then 'human_review'
      else excluded.status
    end,
    no_more_auto=public.pppp_gc_prospects_v1.no_more_auto or excluded.no_more_auto,
    duplicate_reason=coalesce(excluded.duplicate_reason,public.pppp_gc_prospects_v1.duplicate_reason)
  returning id into v_id;

  v_contact_id:=public.pppp_gc_register_contact_v1(v_id);

  return jsonb_build_object(
    'ok',true,'prospect_id',v_id,'contact_id',v_contact_id,'company_key',v_key,'company_domain',v_domain,
    'status',(select status from public.pppp_gc_prospects_v1 where id=v_id),
    'language',(select language from public.pppp_gc_prospects_v1 where id=v_id),
    'historical_outreach',v_hist
  );
end;
$$;


ALTER FUNCTION public.pppp_gc_upsert_prospect_v1(p_company_name text, p_company_domain text, p_website_url text, p_country text, p_country_code text, p_company_type text, p_relevance_score integer, p_contact_name text, p_contact_email text, p_contact_role text, p_contact_source_url text, p_contact_confidence integer, p_current_projects jsonb, p_recent_projects jsonb, p_evidence jsonb, p_discovery_source text, p_source_url text, p_discovery_run_id uuid) OWNER TO postgres;

--
-- Name: pppp_global_communication_guard_v1(text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_global_communication_guard_v1(p_recipient_email text, p_company_domain text DEFAULT NULL::text, p_exclude_source text DEFAULT NULL::text, p_exclude_source_record_id uuid DEFAULT NULL::uuid, p_exclude_queue_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with pol as (
  select
    coalesce(recipient_cooldown_days,30)::integer as recipient_days,
    coalesce(domain_cooldown_days,14)::integer as domain_days
  from public.pppp_outbound_policy_v1
  where id='global'
),
ctx as (
  select
    lower(btrim(coalesce(p_recipient_email,''))) as email,
    lower(coalesce(
      nullif(btrim(p_company_domain),''),
      public.pppp_outbound_domain_v1(p_recipient_email,null),
      ''
    )) as domain,
    upper(btrim(coalesce(p_exclude_source,''))) as exclude_source,
    p_exclude_source_record_id as exclude_source_record_id,
    p_exclude_queue_id as exclude_queue_id,
    coalesce((select recipient_days from pol),30) as recipient_days,
    coalesce((select domain_days from pol),14) as domain_days
),
events as (
  select
    'QUEUE:'||upper(coalesce(q.source,'')) as source,
    q.id::text as event_id,
    lower(coalesce(q.recipient_email,'')) as email,
    lower(coalesce(public.pppp_outbound_domain_v1(q.recipient_email,q.company_domain),'')) as domain,
    'sent'::text as kind,
    q.sent_at as event_at
  from public.pppp_outbound_queue_v1 q, ctx c
  where q.sent_at is not null
    and not (
      q.id is not distinct from c.exclude_queue_id
      or (
        upper(coalesce(q.source,''))=c.exclude_source
        and q.source_record_id is not distinct from c.exclude_source_record_id
      )
    )

  union all
  select 'QUEUE:'||upper(coalesce(q.source,'')),q.id::text,
         lower(coalesce(q.recipient_email,'')),
         lower(coalesce(public.pppp_outbound_domain_v1(q.recipient_email,q.company_domain),'')),
         'replied',q.replied_at
  from public.pppp_outbound_queue_v1 q, ctx c
  where q.replied_at is not null
    and not (
      q.id is not distinct from c.exclude_queue_id
      or (
        upper(coalesce(q.source,''))=c.exclude_source
        and q.source_record_id is not distinct from c.exclude_source_record_id
      )
    )

  union all
  select 'QUEUE:'||upper(coalesce(q.source,'')),q.id::text,
         lower(coalesce(q.recipient_email,'')),
         lower(coalesce(public.pppp_outbound_domain_v1(q.recipient_email,q.company_domain),'')),
         'bounced',q.bounced_at
  from public.pppp_outbound_queue_v1 q, ctx c
  where q.bounced_at is not null
    and not (
      q.id is not distinct from c.exclude_queue_id
      or (
        upper(coalesce(q.source,''))=c.exclude_source
        and q.source_record_id is not distinct from c.exclude_source_record_id
      )
    )

  union all
  select 'QUEUE:'||upper(coalesce(q.source,'')),q.id::text,
         lower(coalesce(q.recipient_email,'')),
         lower(coalesce(public.pppp_outbound_domain_v1(q.recipient_email,q.company_domain),'')),
         'active_draft',q.updated_at
  from public.pppp_outbound_queue_v1 q, ctx c
  where q.sent_at is null and q.replied_at is null and q.bounced_at is null
    and q.gmail_draft_id is not null
    and q.status in ('candidate','planned')
    and q.suppression_reason is null
    and not (
      q.id is not distinct from c.exclude_queue_id
      or (
        upper(coalesce(q.source,''))=c.exclude_source
        and q.source_record_id is not distinct from c.exclude_source_record_id
      )
    )

  union all
  select 'GMAIL',pe.gmail_message_id,
         lower(x.email),
         lower(coalesce(public.pppp_outbound_domain_v1(x.email,null),'')),
         'sent',pe.sent_at
  from public.project_emails pe
  cross join lateral unnest(coalesce(pe.to_emails,'{}'::text[])) as x(email)
  where lower(coalesce(pe.direction,''))='outgoing'
    and pe.sent_at is not null
    and lower(coalesce(pe.from_email,'')) like '%@prissteel.com'

  union all
  select 'GMAIL',pe.gmail_message_id,
         lower(coalesce(pe.from_email,'')),
         lower(coalesce(public.pppp_outbound_domain_v1(pe.from_email,null),'')),
         'replied',pe.sent_at
  from public.project_emails pe
  where lower(coalesce(pe.direction,''))='incoming'
    and pe.sent_at is not null
    and lower(coalesce(pe.from_email,'')) not like '%@prissteel.com'

  union all
  select 'TED',r.id::text,
         lower(coalesce(r.recipient_email,'')),
         lower(coalesce(public.pppp_outbound_domain_v1(r.recipient_email,null),'')),
         'sent',r.sent_at
  from public.pppp_opportunity_outreach_registry_v1 r, ctx c
  where r.sent_at is not null
    and not (c.exclude_source='TED' and r.id is not distinct from c.exclude_source_record_id)

  union all
  select 'TED',r.id::text,
         lower(coalesce(r.recipient_email,'')),
         lower(coalesce(public.pppp_outbound_domain_v1(r.recipient_email,null),'')),
         'active_draft',coalesce(r.draft_created_at,r.updated_at)
  from public.pppp_opportunity_outreach_registry_v1 r, ctx c
  where r.sent_at is null
    and r.gmail_draft_id is not null
    and r.status in ('draft_pending','draft_created')
    and not (c.exclude_source='TED' and r.id is not distinct from c.exclude_source_record_id)

  union all
  select 'GC',g.id::text,
         lower(coalesce(g.contact_email,'')),
         lower(coalesce(public.pppp_outbound_domain_v1(g.contact_email,g.company_domain),'')),
         'sent',coalesce(g.second_sent_at,g.first_sent_at)
  from public.pppp_gc_prospects_v1 g, ctx c
  where coalesce(g.second_sent_at,g.first_sent_at) is not null
    and not (c.exclude_source='GC' and g.id is not distinct from c.exclude_source_record_id)

  union all
  select 'GC',g.id::text,
         lower(coalesce(g.contact_email,'')),
         lower(coalesce(public.pppp_outbound_domain_v1(g.contact_email,g.company_domain),'')),
         'replied',g.replied_at
  from public.pppp_gc_prospects_v1 g, ctx c
  where g.replied_at is not null
    and not (c.exclude_source='GC' and g.id is not distinct from c.exclude_source_record_id)

  union all
  select 'GC',g.id::text,
         lower(coalesce(g.contact_email,'')),
         lower(coalesce(public.pppp_outbound_domain_v1(g.contact_email,g.company_domain),'')),
         'bounced',g.bounced_at
  from public.pppp_gc_prospects_v1 g, ctx c
  where g.bounced_at is not null
    and not (c.exclude_source='GC' and g.id is not distinct from c.exclude_source_record_id)

  union all
  select 'GC',g.id::text,
         lower(coalesce(g.contact_email,'')),
         lower(coalesce(public.pppp_outbound_domain_v1(g.contact_email,g.company_domain),'')),
         'active_draft',g.updated_at
  from public.pppp_gc_prospects_v1 g, ctx c
  where g.first_sent_at is null
    and coalesce(g.first_draft_id,g.second_draft_id) is not null
    and g.status in ('draft_ready','draft_2_ready','followup_due')
    and not (c.exclude_source='GC' and g.id is not distinct from c.exclude_source_record_id)

  union all
  select 'GC',g.id::text,
         lower(coalesce(g.contact_email,'')),
         lower(coalesce(public.pppp_outbound_domain_v1(g.contact_email,g.company_domain),'')),
         'suppressed',g.updated_at
  from public.pppp_gc_prospects_v1 g, ctx c
  where (coalesce(g.do_not_contact,false) or g.status='do_not_contact')
    and not (c.exclude_source='GC' and g.id is not distinct from c.exclude_source_record_id)
),
relevant as (
  select e.*,
         (e.email=c.email and c.email<>'') as exact_recipient,
         (e.domain=c.domain and c.domain<>'') as exact_domain
  from events e cross join ctx c
  where (c.email<>'' and e.email=c.email)
     or (c.domain<>'' and e.domain=c.domain)
),
flags as (
  select
    exists(select 1 from relevant r,ctx c where r.kind='bounced' and r.exact_recipient) as bounced,
    exists(select 1 from relevant r,ctx c where r.kind='replied' and (r.exact_recipient or r.exact_domain)) as replied,
    exists(select 1 from relevant r,ctx c where r.kind='suppressed' and r.exact_recipient) as suppressed,
    exists(select 1 from relevant r,ctx c where r.kind='sent' and r.exact_recipient and r.event_at>=now()-make_interval(days=>c.recipient_days)) as recipient_sent,
    exists(select 1 from relevant r,ctx c where r.kind='sent' and r.exact_domain and r.event_at>=now()-make_interval(days=>c.domain_days)) as domain_sent,
    exists(select 1 from relevant r where r.kind='active_draft' and r.exact_recipient) as recipient_active,
    exists(select 1 from relevant r where r.kind='active_draft' and r.exact_domain) as domain_active,
    (select max(event_at) from relevant) as latest_contact_at,
    coalesce(
      (select jsonb_agg(jsonb_build_object(
        'source',r.source,'kind',r.kind,'at',r.event_at,'email',r.email,'domain',r.domain,'event_id',r.event_id
      ) order by r.event_at desc nulls last)
       from (select distinct source,kind,event_at,email,domain,event_id from relevant order by event_at desc nulls last limit 12) r),
      '[]'::jsonb
    ) as conflicts
)
select jsonb_build_object(
  'ok',
    not (
      c.email='' or c.domain='prissteel.com'
      or f.bounced or f.replied or f.suppressed
      or f.recipient_sent or f.domain_sent
      or f.recipient_active or f.domain_active
    ),
  'reason',
    case
      when c.email='' then 'recipient_email_required'
      when c.domain='prissteel.com' then 'internal_pristeel_recipient'
      when f.bounced then 'cross_source_recipient_bounced'
      when f.replied then 'cross_source_reply_history'
      when f.recipient_sent then 'cross_source_recipient_cooldown'
      when f.domain_sent then 'cross_source_domain_cooldown'
      when f.suppressed then 'cross_source_recipient_suppressed'
      when f.recipient_active then 'cross_source_active_recipient_outreach'
      when f.domain_active then 'cross_source_active_domain_outreach'
      else 'clear'
    end,
  'recipient_email',c.email,
  'company_domain',c.domain,
  'recipient_cooldown_days',c.recipient_days,
  'domain_cooldown_days',c.domain_days,
  'latest_contact_at',f.latest_contact_at,
  'conflicts',f.conflicts
)
from ctx c cross join flags f;
$$;


ALTER FUNCTION public.pppp_global_communication_guard_v1(p_recipient_email text, p_company_domain text, p_exclude_source text, p_exclude_source_record_id uuid, p_exclude_queue_id uuid) OWNER TO postgres;

--
-- Name: pppp_guard_generic_system_mail_link_insert_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_guard_generic_system_mail_link_insert_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_from_email text;
begin
  select lower(trim(coalesce(e.from_email,''))) into v_from_email
  from public.project_emails e
  where e.gmail_message_id = new.gmail_message_id
  order by e.sent_at desc nulls last
  limit 1;

  if v_from_email = 'eprokurimi@rks-gov.net'
     and (
       coalesce(new.link_method,'') = 'server-identity-auto-link-v3'
       or coalesce(new.link_method,'') = 'identity-autolink-v1'
       or coalesce(new.link_method,'') like 'project-contact-unique%'
       or coalesce(new.link_method,'') in ('contact_history_auto','gmail_thread_auto')
     ) then
    return null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_guard_generic_system_mail_link_insert_v1() OWNER TO postgres;

--
-- Name: pppp_guard_generic_system_mail_project_link_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_guard_generic_system_mail_project_link_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if lower(trim(coalesce(new.from_email,''))) = 'eprokurimi@rks-gov.net'
     and new.project_id is not null
     and (
       coalesce(new.match_method,'') = 'server-identity-auto-link-v3'
       or coalesce(new.match_method,'') like 'identity-autolink-v1:%'
       or coalesce(new.match_method,'') like 'project-contact-unique%'
       or coalesce(new.match_method,'') in ('contact_history_auto','gmail_thread_auto')
     ) then
    new.project_id := null;
    new.suggested_project_id := null;
    new.match_method := 'system-mail-detached:eprokurimi';
    new.match_confidence := 0;
    new.needs_review := true;
    new.review_reason := 'Shared e-Prokurimi notification blocked from generic project autolink; requires procurement-specific or explicit manual resolution.';
    new.updated_at := now();
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_guard_generic_system_mail_project_link_v1() OWNER TO postgres;

--
-- Name: pppp_ignore_commercial_candidate_v1(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_ignore_commercial_candidate_v1(p_kind text, p_candidate_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_project uuid; v_kind text:=lower(btrim(coalesce(p_kind,'')));
begin
  if not public.can_write() then raise exception 'Write permission required' using errcode='42501'; end if;
  if v_kind='offer' then
    update public.supplier_offer_candidates set status='ignored',reviewed_at=now(),updated_at=now()
    where id=p_candidate_id and status='review' returning project_id into v_project;
  elsif v_kind='invoice' then
    update public.invoice_candidates set status='ignored',reviewed_at=now(),updated_at=now()
    where id=p_candidate_id and status='review' returning project_id into v_project;
  else raise exception 'Unsupported candidate kind'; end if;
  if v_project is null then raise exception 'Review candidate not found'; end if;
  return jsonb_build_object('ok',true,'status','ignored','kind',v_kind,'project_id',v_project);
end;
$$;


ALTER FUNCTION public.pppp_ignore_commercial_candidate_v1(p_kind text, p_candidate_id uuid) OWNER TO postgres;

--
-- Name: pppp_ignore_expense_receipt_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_ignore_expense_receipt_v1(p_receipt_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ begin
  update public.pppp_expense_receipts_v1 set status='ignored',updated_at=now() where id=p_receipt_id and expense_id is null and status<>'confirmed';
  return jsonb_build_object('ok',found,'status',(select status from public.pppp_expense_receipts_v1 where id=p_receipt_id));
end;$$;


ALTER FUNCTION public.pppp_ignore_expense_receipt_v1(p_receipt_id uuid) OWNER TO postgres;

--
-- Name: pppp_ingest_context_fact_v1(uuid, text, jsonb, text, text, text, text, text, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_ingest_context_fact_v1(p_project_id uuid, p_fact_key text, p_value jsonb, p_category text DEFAULT 'general'::text, p_subject text DEFAULT NULL::text, p_source_type text DEFAULT 'system'::text, p_source_ref text DEFAULT NULL::text, p_evidence_status text DEFAULT 'unverified'::text, p_confidence numeric DEFAULT NULL::numeric, p_fact_status text DEFAULT 'observed'::text, p_idempotency_key text DEFAULT NULL::text, p_created_by text DEFAULT 'system'::text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_previous_id uuid;
begin
  if p_project_id is null or not exists (select 1 from public.projects where id = p_project_id) then
    raise exception 'Valid project_id is required';
  end if;
  if p_fact_key is null or btrim(p_fact_key) = '' then
    raise exception 'fact_key is required';
  end if;
  if p_fact_status not in ('observed','suggested') then
    raise exception 'Automated/context intake may only create observed or suggested facts';
  end if;
  if p_source_type not in ('chatgpt','email','phone','document','system','user','api','other') then
    raise exception 'Unsupported source_type';
  end if;
  if p_evidence_status not in ('unverified','observed','verbal','documented','confirmed') then
    raise exception 'Unsupported evidence_status';
  end if;
  if p_confidence is not null and (p_confidence < 0 or p_confidence > 1) then
    raise exception 'confidence must be between 0 and 1';
  end if;

  if p_idempotency_key is not null then
    select id into v_id from public.pppp_project_context_facts where idempotency_key = p_idempotency_key limit 1;
    if v_id is not null then
      return v_id;
    end if;
  end if;

  select id into v_previous_id
  from public.pppp_project_context_facts
  where project_id = p_project_id
    and fact_key = p_fact_key
    and fact_status <> 'dismissed'
  order by created_at desc, id desc
  limit 1;

  insert into public.pppp_project_context_facts(
    project_id, category, subject, fact_key, value, source_type, source_ref,
    evidence_status, confidence, fact_status, supersedes_id, idempotency_key, created_by
  ) values (
    p_project_id, coalesce(nullif(btrim(p_category),''),'general'), nullif(btrim(p_subject),''), btrim(p_fact_key),
    coalesce(p_value,'{}'::jsonb), p_source_type, nullif(btrim(p_source_ref),''), p_evidence_status,
    p_confidence, p_fact_status, v_previous_id, nullif(btrim(p_idempotency_key),''), coalesce(nullif(btrim(p_created_by),''),'system')
  )
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION public.pppp_ingest_context_fact_v1(p_project_id uuid, p_fact_key text, p_value jsonb, p_category text, p_subject text, p_source_type text, p_source_ref text, p_evidence_status text, p_confidence numeric, p_fact_status text, p_idempotency_key text, p_created_by text) OWNER TO postgres;

--
-- Name: pppp_intelligence_change_from_state_v1(jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_intelligence_change_from_state_v1(p_current jsonb, p_hours integer DEFAULT 24, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_hours integer:=greatest(0,least(coalesce(p_hours,24),168));
  v_limit integer:=greatest(5,least(coalesce(p_limit,20),30));
  v_current jsonb:=coalesce(p_current,'{}'::jsonb);
  v_current_hash text:=md5(coalesce(p_current,'{}'::jsonb)::text);
  v_baseline public.pppp_intelligence_snapshots_v1%rowtype;
  v_first_at timestamptz; v_latest_at timestamptz;
  v_cur_focus text[]:=array[]::text[]; v_base_focus text[]:=array[]::text[];
  v_cur_decisions text[]:=array[]::text[]; v_base_decisions text[]:=array[]::text[];
  v_cur_finance text[]:=array[]::text[]; v_base_finance text[]:=array[]::text[];
  v_cur_opps text[]:=array[]::text[]; v_base_opps text[]:=array[]::text[];
  v_cur_wait text[]:=array[]::text[]; v_base_wait text[]:=array[]::text[];
  v_new_focus text[]:=array[]::text[]; v_left_focus text[]:=array[]::text[];
  v_new_decisions text[]:=array[]::text[]; v_left_decisions text[]:=array[]::text[];
  v_new_finance text[]:=array[]::text[]; v_left_finance text[]:=array[]::text[];
  v_new_opps text[]:=array[]::text[]; v_left_opps text[]:=array[]::text[];
  v_enter_wait text[]:=array[]::text[]; v_left_wait text[]:=array[]::text[];
  j_new_focus jsonb:='[]'::jsonb; j_left_focus jsonb:='[]'::jsonb;
  j_new_decisions jsonb:='[]'::jsonb; j_left_decisions jsonb:='[]'::jsonb;
  j_new_finance jsonb:='[]'::jsonb; j_left_finance jsonb:='[]'::jsonb;
  j_new_opps jsonb:='[]'::jsonb; j_left_opps jsonb:='[]'::jsonb;
  j_enter_wait jsonb:='[]'::jsonb; j_left_wait jsonb:='[]'::jsonb;
  v_company_delta jsonb:='{}'::jsonb; v_headline text;
begin
  select min(captured_at),max(captured_at) into v_first_at,v_latest_at from public.pppp_intelligence_snapshots_v1;
  if v_hours=0 then
    select * into v_baseline from public.pppp_intelligence_snapshots_v1 order by captured_at desc limit 1;
  else
    select * into v_baseline from public.pppp_intelligence_snapshots_v1 where captured_at<=now()-make_interval(hours=>v_hours) order by captured_at desc limit 1;
  end if;
  if v_baseline.id is null then
    return jsonb_build_object('change_intelligence_version',1,'historical_delta_available',false,'requested_hours',v_hours,
      'first_snapshot_at',v_first_at,'latest_snapshot_at',v_latest_at,'current_state',v_current->'company_state',
      'reason',case when v_first_at is null then 'No intelligence snapshots exist yet.' else 'No snapshot old enough exists for the requested comparison window.' end,
      'policy',jsonb_build_object('read_only',true,'no_business_core_mutation',true,'no_inferred_pre_snapshot_history',true,'executions_performed',0));
  end if;

  select coalesce(array_agg(e->>'proposal_id') filter(where coalesce(e->>'proposal_id','')<>''),array[]::text[]) into v_cur_focus from jsonb_array_elements(coalesce(v_current->'focus_now','[]'::jsonb)) e;
  select coalesce(array_agg(e->>'proposal_id') filter(where coalesce(e->>'proposal_id','')<>''),array[]::text[]) into v_base_focus from jsonb_array_elements(coalesce(v_baseline.state->'focus_now','[]'::jsonb)) e;
  select coalesce(array_agg(e->>'proposal_id') filter(where coalesce(e->>'proposal_id','')<>''),array[]::text[]) into v_cur_decisions from jsonb_array_elements(coalesce(v_current->'human_decisions_required','[]'::jsonb)) e;
  select coalesce(array_agg(e->>'proposal_id') filter(where coalesce(e->>'proposal_id','')<>''),array[]::text[]) into v_base_decisions from jsonb_array_elements(coalesce(v_baseline.state->'human_decisions_required','[]'::jsonb)) e;
  select coalesce(array_agg(e->>'attention_id') filter(where coalesce(e->>'attention_id','')<>''),array[]::text[]) into v_cur_finance from jsonb_array_elements(coalesce(v_current->'finance_attention','[]'::jsonb)) e;
  select coalesce(array_agg(e->>'attention_id') filter(where coalesce(e->>'attention_id','')<>''),array[]::text[]) into v_base_finance from jsonb_array_elements(coalesce(v_baseline.state->'finance_attention','[]'::jsonb)) e;
  select coalesce(array_agg(e->>'proposal_id') filter(where coalesce(e->>'proposal_id','')<>''),array[]::text[]) into v_cur_opps from jsonb_array_elements(coalesce(v_current->'new_opportunities','[]'::jsonb)) e;
  select coalesce(array_agg(e->>'proposal_id') filter(where coalesce(e->>'proposal_id','')<>''),array[]::text[]) into v_base_opps from jsonb_array_elements(coalesce(v_baseline.state->'new_opportunities','[]'::jsonb)) e;
  select coalesce(array_agg(e->>'project_id') filter(where coalesce(e->>'project_id','')<>''),array[]::text[]) into v_cur_wait from jsonb_array_elements(coalesce(v_current->'waiting_external_watchlist','[]'::jsonb)) e;
  select coalesce(array_agg(e->>'project_id') filter(where coalesce(e->>'project_id','')<>''),array[]::text[]) into v_base_wait from jsonb_array_elements(coalesce(v_baseline.state->'waiting_external_watchlist','[]'::jsonb)) e;

  select coalesce(array(select unnest(v_cur_focus) except select unnest(v_base_focus)),array[]::text[]) into v_new_focus;
  select coalesce(array(select unnest(v_base_focus) except select unnest(v_cur_focus)),array[]::text[]) into v_left_focus;
  select coalesce(array(select unnest(v_cur_decisions) except select unnest(v_base_decisions)),array[]::text[]) into v_new_decisions;
  select coalesce(array(select unnest(v_base_decisions) except select unnest(v_cur_decisions)),array[]::text[]) into v_left_decisions;
  select coalesce(array(select unnest(v_cur_finance) except select unnest(v_base_finance)),array[]::text[]) into v_new_finance;
  select coalesce(array(select unnest(v_base_finance) except select unnest(v_cur_finance)),array[]::text[]) into v_left_finance;
  select coalesce(array(select unnest(v_cur_opps) except select unnest(v_base_opps)),array[]::text[]) into v_new_opps;
  select coalesce(array(select unnest(v_base_opps) except select unnest(v_cur_opps)),array[]::text[]) into v_left_opps;
  select coalesce(array(select unnest(v_cur_wait) except select unnest(v_base_wait)),array[]::text[]) into v_enter_wait;
  select coalesce(array(select unnest(v_base_wait) except select unnest(v_cur_wait)),array[]::text[]) into v_left_wait;

  select coalesce(jsonb_agg(value order by ord),'[]'::jsonb) into j_new_focus from (select x.value,x.ord from jsonb_array_elements(coalesce(v_current->'focus_now','[]'::jsonb)) with ordinality x(value,ord) where x.value->>'proposal_id'=any(v_new_focus) order by x.ord limit v_limit) q;
  select coalesce(jsonb_agg(value order by ord),'[]'::jsonb) into j_left_focus from (select x.value,x.ord from jsonb_array_elements(coalesce(v_baseline.state->'focus_now','[]'::jsonb)) with ordinality x(value,ord) where x.value->>'proposal_id'=any(v_left_focus) order by x.ord limit v_limit) q;
  select coalesce(jsonb_agg(value order by ord),'[]'::jsonb) into j_new_decisions from (select x.value,x.ord from jsonb_array_elements(coalesce(v_current->'human_decisions_required','[]'::jsonb)) with ordinality x(value,ord) where x.value->>'proposal_id'=any(v_new_decisions) order by x.ord limit v_limit) q;
  select coalesce(jsonb_agg(value order by ord),'[]'::jsonb) into j_left_decisions from (select x.value,x.ord from jsonb_array_elements(coalesce(v_baseline.state->'human_decisions_required','[]'::jsonb)) with ordinality x(value,ord) where x.value->>'proposal_id'=any(v_left_decisions) order by x.ord limit v_limit) q;
  select coalesce(jsonb_agg(value order by ord),'[]'::jsonb) into j_new_finance from (select x.value,x.ord from jsonb_array_elements(coalesce(v_current->'finance_attention','[]'::jsonb)) with ordinality x(value,ord) where x.value->>'attention_id'=any(v_new_finance) order by x.ord limit v_limit) q;
  select coalesce(jsonb_agg(value order by ord),'[]'::jsonb) into j_left_finance from (select x.value,x.ord from jsonb_array_elements(coalesce(v_baseline.state->'finance_attention','[]'::jsonb)) with ordinality x(value,ord) where x.value->>'attention_id'=any(v_left_finance) order by x.ord limit v_limit) q;
  select coalesce(jsonb_agg(value order by ord),'[]'::jsonb) into j_new_opps from (select x.value,x.ord from jsonb_array_elements(coalesce(v_current->'new_opportunities','[]'::jsonb)) with ordinality x(value,ord) where x.value->>'proposal_id'=any(v_new_opps) order by x.ord limit v_limit) q;
  select coalesce(jsonb_agg(value order by ord),'[]'::jsonb) into j_left_opps from (select x.value,x.ord from jsonb_array_elements(coalesce(v_baseline.state->'new_opportunities','[]'::jsonb)) with ordinality x(value,ord) where x.value->>'proposal_id'=any(v_left_opps) order by x.ord limit v_limit) q;
  select coalesce(jsonb_agg(value order by ord),'[]'::jsonb) into j_enter_wait from (select x.value,x.ord from jsonb_array_elements(coalesce(v_current->'waiting_external_watchlist','[]'::jsonb)) with ordinality x(value,ord) where x.value->>'project_id'=any(v_enter_wait) order by x.ord limit v_limit) q;
  select coalesce(jsonb_agg(value order by ord),'[]'::jsonb) into j_left_wait from (select x.value,x.ord from jsonb_array_elements(coalesce(v_baseline.state->'waiting_external_watchlist','[]'::jsonb)) with ordinality x(value,ord) where x.value->>'project_id'=any(v_left_wait) order by x.ord limit v_limit) q;

  v_company_delta:=jsonb_build_object(
    'projects_requiring_attention',coalesce((v_current#>>'{company_state,projects_requiring_attention}')::int,0)-coalesce((v_baseline.state#>>'{company_state,projects_requiring_attention}')::int,0),
    'human_gated_proposals',coalesce((v_current#>>'{company_state,human_gated_proposals}')::int,0)-coalesce((v_baseline.state#>>'{company_state,human_gated_proposals}')::int,0),
    'projects_waiting_external',coalesce((v_current#>>'{company_state,projects_waiting_external}')::int,0)-coalesce((v_baseline.state#>>'{company_state,projects_waiting_external}')::int,0),
    'new_opportunity_candidates',coalesce((v_current#>>'{company_state,new_opportunity_candidates}')::int,0)-coalesce((v_baseline.state#>>'{company_state,new_opportunity_candidates}')::int,0),
    'finance_attention_items',coalesce((v_current#>>'{company_state,finance_attention_items}')::int,0)-coalesce((v_baseline.state#>>'{company_state,finance_attention_items}')::int,0),
    'overdue_receivable_invoices',coalesce((v_current#>>'{company_state,overdue_receivable_invoices}')::int,0)-coalesce((v_baseline.state#>>'{company_state,overdue_receivable_invoices}')::int,0),
    'open_bank_guarantees',coalesce((v_current#>>'{company_state,open_bank_guarantees}')::int,0)-coalesce((v_baseline.state#>>'{company_state,open_bank_guarantees}')::int,0),
    'supplier_invoices_missing_due_date',coalesce((v_current#>>'{company_state,supplier_invoices_missing_due_date}')::int,0)-coalesce((v_baseline.state#>>'{company_state,supplier_invoices_missing_due_date}')::int,0)
  );
  v_headline:=format('%s focus të reja; %s nuk janë më në focus; %s finance attention të reja; %s opportunity të reja; %s projekte hynë dhe %s dolën nga waiting external.',cardinality(v_new_focus),cardinality(v_left_focus),cardinality(v_new_finance),cardinality(v_new_opps),cardinality(v_enter_wait),cardinality(v_left_wait));

  return jsonb_build_object(
    'change_intelligence_version',1,'historical_delta_available',true,'requested_hours',v_hours,'baseline_snapshot_id',v_baseline.id,
    'baseline_at',v_baseline.captured_at,'current_at',now(),'actual_baseline_age_hours',round((extract(epoch from (now()-v_baseline.captured_at))/3600.0)::numeric,2),
    'state_changed',v_current_hash<>v_baseline.state_hash,'headline',v_headline,'company_state_before',v_baseline.state->'company_state',
    'company_state_now',v_current->'company_state','company_state_delta',v_company_delta,'new_focus_items',j_new_focus,'focus_items_no_longer_present',j_left_focus,
    'new_human_decisions',j_new_decisions,'human_decisions_no_longer_present',j_left_decisions,'new_finance_attention',j_new_finance,
    'finance_attention_no_longer_present',j_left_finance,'new_opportunities',j_new_opps,'opportunities_no_longer_present',j_left_opps,
    'entered_waiting_external',j_enter_wait,'left_waiting_external',j_left_wait,
    'interpretation',jsonb_build_object('no_longer_present_does_not_mean_resolved',true,'snapshot_history_starts_at',v_first_at,'history_before_first_snapshot_is_not_inferred',true,'current_state_is_live_not_last_snapshot',true),
    'policy',jsonb_build_object('read_only',true,'no_business_core_mutation',true,'no_email_send',true,'no_task_or_project_creation',true,'no_supplier_selection_or_commitment',true,'no_finance_core_mutation',true,'protected_human_gates_preserved',true,'executions_performed',0)
  );
end;
$$;


ALTER FUNCTION public.pppp_intelligence_change_from_state_v1(p_current jsonb, p_hours integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_intelligence_compact_from_control_tower_v1(jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_intelligence_compact_from_control_tower_v1(p_tower jsonb, p_limit integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := greatest(5, least(coalesce(p_limit,30),30));
  v_focus jsonb := '[]'::jsonb;
  v_decisions jsonb := '[]'::jsonb;
  v_finance jsonb := '[]'::jsonb;
  v_opportunities jsonb := '[]'::jsonb;
  v_waiting jsonb := '[]'::jsonb;
begin
  select coalesce(jsonb_agg(item order by ord),'[]'::jsonb) into v_focus
  from (
    select x.ord,jsonb_strip_nulls(jsonb_build_object(
      'proposal_id',x.value->>'proposal_id','action_kind',x.value->>'action_kind','action_label',x.value->>'action_label',
      'priority_score',x.value->'priority_score','approval_gates',coalesce(x.value->'approval_gates','[]'::jsonb),
      'project_id',coalesce(x.value#>>'{project,project_id}',x.value#>>'{project_context,recommended_project_id}'),
      'project_name',coalesce(x.value#>>'{project,project_name}',x.value#>>'{project_context,recommended_project_name}'),
      'subject',x.value->>'subject','counterparty_email',x.value#>>'{counterparty,from_email}',
      'recommended_decision',x.value#>>'{recommended_decision,decision}','recommended_label',x.value#>>'{recommended_decision,label}',
      'risk_level',x.value#>>'{risk,level}','risk_score',x.value#>'{risk,score}'
    )) item
    from jsonb_array_elements(coalesce(p_tower->'focus_now','[]'::jsonb)) with ordinality x(value,ord)
    where x.ord<=v_limit
  ) q;

  select coalesce(jsonb_agg(item order by ord),'[]'::jsonb) into v_decisions
  from (
    select x.ord,jsonb_strip_nulls(jsonb_build_object(
      'proposal_id',x.value->>'proposal_id','action_kind',x.value->>'action_kind','action_label',x.value->>'action_label',
      'priority_score',x.value->'priority_score','approval_gates',coalesce(x.value->'approval_gates','[]'::jsonb),
      'project_id',coalesce(x.value#>>'{project,project_id}',x.value#>>'{project_context,recommended_project_id}'),
      'project_name',coalesce(x.value#>>'{project,project_name}',x.value#>>'{project_context,recommended_project_name}'),
      'subject',x.value->>'subject','counterparty_email',x.value#>>'{counterparty,from_email}'
    )) item
    from jsonb_array_elements(coalesce(p_tower->'human_decisions_required','[]'::jsonb)) with ordinality x(value,ord)
    where x.ord<=v_limit
  ) q;

  select coalesce(jsonb_agg(item order by ord),'[]'::jsonb) into v_finance
  from (
    select x.ord,jsonb_strip_nulls(jsonb_build_object(
      'attention_id',x.value->>'attention_id','kind',x.value->>'kind','priority_score',x.value->'priority_score',
      'project_id',x.value->>'project_id','project_name',x.value->>'project_name','party',x.value->>'party','bank',x.value->>'bank',
      'reference',x.value->>'reference','amount',x.value->'amount','amount_guaranteed',x.value->'amount_guaranteed','currency',x.value->>'currency',
      'due_date',x.value->>'due_date','days_overdue',x.value->'days_overdue','expiry_date',x.value->>'expiry_date','days_to_expiry',x.value->'days_to_expiry',
      'approval_gates',coalesce(x.value->'approval_gates','[]'::jsonb),'recommended_action',x.value->>'recommended_action'
    )) item
    from jsonb_array_elements(coalesce(p_tower->'finance_attention','[]'::jsonb)) with ordinality x(value,ord)
    where x.ord<=v_limit
  ) q;

  select coalesce(jsonb_agg(item order by ord),'[]'::jsonb) into v_opportunities
  from (
    select x.ord,jsonb_strip_nulls(jsonb_build_object(
      'proposal_id',x.value->>'proposal_id','subject',x.value->>'subject','priority_score',x.value->'priority_score',
      'counterparty_email',x.value#>>'{counterparty,from_email}','approval_gates',coalesce(x.value->'approval_gates','[]'::jsonb),
      'recommended_project_id',x.value#>>'{project_context,recommended_project_id}','recommended_project_name',x.value#>>'{project_context,recommended_project_name}'
    )) item
    from jsonb_array_elements(coalesce(p_tower->'new_opportunities','[]'::jsonb)) with ordinality x(value,ord)
    where x.ord<=v_limit
  ) q;

  select coalesce(jsonb_agg(item order by ord),'[]'::jsonb) into v_waiting
  from (
    select x.ord,jsonb_strip_nulls(jsonb_build_object(
      'project_id',x.value->>'project_id','project_name',x.value->>'project_name','client',x.value->>'client',
      'pipeline_stage',x.value->>'pipeline_stage','risk_level',x.value->>'risk_level',
      'recommendation_decision',x.value#>>'{recommendation,decision}','attention_required',x.value->'attention_required'
    )) item
    from jsonb_array_elements(coalesce(p_tower->'waiting_external_watchlist','[]'::jsonb)) with ordinality x(value,ord)
    where x.ord<=v_limit
  ) q;

  return jsonb_build_object(
    'state_version',1,'company_state',coalesce(p_tower->'company_state','{}'::jsonb),'focus_now',v_focus,
    'human_decisions_required',v_decisions,'finance_attention',v_finance,'new_opportunities',v_opportunities,
    'waiting_external_watchlist',v_waiting,'data_quality_watch',coalesce(p_tower->'data_quality_watch','{}'::jsonb),
    'source_layers',coalesce(p_tower->'source_layers','{}'::jsonb)
  );
end;
$$;


ALTER FUNCTION public.pppp_intelligence_compact_from_control_tower_v1(p_tower jsonb, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_intelligence_compact_state_v1(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_intelligence_compact_state_v1(p_days integer DEFAULT 30, p_limit integer DEFAULT 30) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select public.pppp_intelligence_compact_from_control_tower_v1(
    public.pppp_chatgpt_control_tower_v1(greatest(1,least(coalesce(p_days,30),90)),greatest(5,least(coalesce(p_limit,30),30))),
    greatest(5,least(coalesce(p_limit,30),30))
  );
$$;


ALTER FUNCTION public.pppp_intelligence_compact_state_v1(p_days integer, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_intelligence_snapshot_capture_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_intelligence_snapshot_capture_v1(p_source text DEFAULT 'cron'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_state jsonb;
  v_hash text;
  v_slot timestamptz := date_trunc('hour',clock_timestamp());
  v_id bigint;
  v_created boolean := false;
begin
  v_state := public.pppp_intelligence_compact_state_v1(30,30);
  v_hash := md5(v_state::text);

  insert into public.pppp_intelligence_snapshots_v1(snapshot_hour,captured_at,capture_source,state_hash,state)
  values(v_slot,clock_timestamp(),coalesce(nullif(trim(p_source),''),'unknown'),v_hash,v_state)
  on conflict(snapshot_hour) do nothing
  returning id into v_id;

  if v_id is not null then
    v_created := true;
  else
    select id into v_id
    from public.pppp_intelligence_snapshots_v1
    where snapshot_hour=v_slot;
  end if;

  return jsonb_build_object(
    'snapshot_id',v_id,
    'snapshot_hour',v_slot,
    'created',v_created,
    'state_hash',v_hash,
    'source',coalesce(nullif(trim(p_source),''),'unknown'),
    'business_core_mutations',0
  );
end;
$$;


ALTER FUNCTION public.pppp_intelligence_snapshot_capture_v1(p_source text) OWNER TO postgres;

--
-- Name: pppp_jsonb_text_array_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_jsonb_text_array_v1(p_value jsonb) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
select case
  when p_value is null or p_value='null'::jsonb then '{}'::text[]
  when jsonb_typeof(p_value)='array' then coalesce((select array_agg(x) from jsonb_array_elements_text(p_value) x),'{}'::text[])
  when jsonb_typeof(p_value)='string' then array[trim(both '"' from p_value::text)]
  else array[p_value::text]
end;
$$;


ALTER FUNCTION public.pppp_jsonb_text_array_v1(p_value jsonb) OWNER TO postgres;

--
-- Name: pppp_krpp_supersede_prior_notices_v2(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_krpp_supersede_prior_notices_v2() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_latest_id uuid;
begin
  if pg_trigger_depth() > 1 then return new; end if;
  if upper(coalesce(new.payload->>'source', 'KRPP')) <> 'KRPP'
     or nullif(new.procurement_no, '') is null then
    return new;
  end if;

  select current_notice.id
    into v_latest_id
  from public.kek_tender_watch current_notice
  where upper(coalesce(current_notice.payload->>'source', 'KRPP')) = 'KRPP'
    and current_notice.procurement_no = new.procurement_no
  order by coalesce(current_notice.published_date, current_notice.first_seen_at::date, date '0001-01-01') desc,
           coalesce(current_notice.first_seen_at, current_notice.created_at) desc,
           current_notice.created_at desc,
           current_notice.id desc
  limit 1;

  update public.kek_tender_watch prior
     set status = 'ignored',
         payload = coalesce(prior.payload, '{}'::jsonb) || jsonb_build_object(
           'krpp_superseded_by', v_latest_id,
           'krpp_superseded_at', now()
         ),
         updated_at = greatest(prior.updated_at, now())
   where prior.id <> v_latest_id
     and upper(coalesce(prior.payload->>'source', 'KRPP')) = 'KRPP'
     and prior.procurement_no = new.procurement_no
     and prior.project_id is null
     and coalesce(prior.status, 'new') <> 'promoted'
     and (
       prior.status is distinct from 'ignored'
       or coalesce(prior.payload->>'krpp_superseded_by', '') <> v_latest_id::text
     );
  return new;
end
$$;


ALTER FUNCTION public.pppp_krpp_supersede_prior_notices_v2() OWNER TO postgres;

