--
-- Name: pppp_low_egress_schedule_controller_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_low_egress_schedule_controller_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'cron'
    AS $$
declare
  r record;
  v_day boolean := public.pppp_low_egress_business_hours_v1();
  v_changed integer := 0;
  v_off_changed integer := 0;
  v_managed text[] := array[
    'automation-http-reconcile-1m','automation-watchdog-10m','chatgpt-command-bridge-10m',
    'client-offer-preparation-15m','commercial-intake-10m','commercial-review-intelligence-10m',
    'email-party-state-reconcile-30m','execution-release-readiness-hourly',
    'gmail-attachment-sync-5m','gmail-fast-ingest-5m','gmail-missing-message-reconcile-5m',
    'gmail-project-intake-5m','gmail-tracker-hourly','hubspot-sync-every-15min','merge-crm-contacts-hourly',
    'opportunity-outreach-sent-sync-15m','outgoing-invoice-candidates-30m','pppp-data-quality-daily',
    'pppp-expense-drive-inbox-10m','pppp-intelligence-snapshot-hourly-v1','procurement-comparison-15m',
    'project-action-engine-5m','project-discovery-triage-hourly','project-document-intake-5m',
    'project-drive-reconciler-30m','project-dynamic-plan-intake-5m','project-email-identity-autolink-10m',
    'project-event-intelligence-5m','project-memory-baseline-hourly','project-memory-semantic-synthesis-30m',
    'selected-supplier-handoff-15m','semantic-local-orchestrator-5m','supplier-master-background-reconcile-daily',
    'supplier-offer-precision-10m','supplier-quote-arrival-reconcile-10m','task-lifecycle-reconcile-15m',
    'tender-project-intelligence-handoff-hourly','tender-project-promotion-hourly'
  ];
  v_on_demand text[] := array[
    'opportunity-gmail-drafts-15m',
    'pppp-followup-drafts-15m',
    'pppp-gc-discovery-daily',
    'pppp-gc-outreach-hourly'
  ];
begin
  for r in
    select jobid, jobname, active from cron.job where jobname = any(v_managed)
  loop
    if r.active is distinct from v_day then
      perform cron.alter_job(r.jobid, active => v_day);
      v_changed := v_changed + 1;
    end if;
  end loop;

  for r in
    select jobid, jobname, active from cron.job where jobname = any(v_on_demand)
  loop
    if coalesce(r.active,false) then
      perform cron.alter_job(r.jobid, active => false);
      v_off_changed := v_off_changed + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'mode','low_egress',
    'local_timezone','Europe/Belgrade',
    'local_time',to_char(now() at time zone 'Europe/Belgrade','YYYY-MM-DD HH24:MI:SS'),
    'business_hours_active',v_day,
    'managed_jobs_changed',v_changed,
    'on_demand_jobs_forced_off',v_off_changed
  );
end;
$$;


ALTER FUNCTION public.pppp_low_egress_schedule_controller_v1() OWNER TO postgres;

--
-- Name: pppp_material_trade_target_defaults_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_material_trade_target_defaults_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_readiness jsonb;
  v_contact_grade jsonb;
begin
  if coalesce(new.outreach_status, '') in ('queued','draft_created','sent','replied') then
    return new;
  end if;

  new.outreach_engine_version := 'v2';
  new.outreach_motion := coalesce(nullif(new.outreach_motion, ''), 'material_buyer');
  new.company_fit_score := coalesce(new.company_fit_score,
    case upper(coalesce(new.score_band, '')) when 'A1' then 92 when 'A2' then 82 when 'B1' then 72 else 58 end);
  new.commercial_timing_score := coalesce(new.commercial_timing_score,
    case
      when lower(coalesce(new.procurement_timing, '')) ~ '(now|current|immediate|active|0.?3)' then 85
      when new.award_date >= current_date - 120 then 65
      when nullif(new.project_title, '') is not null then 50
      else 35
    end);
  new.timing_classification := coalesce(nullif(new.timing_classification, ''),
    case
      when lower(coalesce(new.procurement_timing, '')) ~ '(now|current|immediate|active|0.?3)' then 'active_procurement'
      when new.award_date >= current_date - 120 then 'post_award_window'
      when nullif(new.project_title, '') is not null then 'future_supplier_qualification'
      else 'unknown'
    end);
  new.personalization_facts := case
    when jsonb_array_length(coalesce(new.personalization_facts, '[]'::jsonb)) >= 2 then new.personalization_facts
    when nullif(new.project_title, '') is not null and nullif(new.why_now, '') is not null then jsonb_build_array(new.project_title, new.why_now)
    when nullif(new.why_now, '') is not null and nullif(new.steel_scope, '') is not null then jsonb_build_array(new.why_now, new.steel_scope)
    when nullif(new.project_title, '') is not null and nullif(new.steel_scope, '') is not null then jsonb_build_array(new.project_title, new.steel_scope)
    when nullif(new.why_now, '') is not null then jsonb_build_array(new.why_now)
    when nullif(new.steel_scope, '') is not null then jsonb_build_array(new.steel_scope)
    else '[]'::jsonb
  end;
  new.message_evidence_score := coalesce(new.message_evidence_score,
    case
      when jsonb_array_length(coalesce(new.personalization_facts, '[]'::jsonb)) >= 2 then 78
      when jsonb_array_length(coalesce(new.evidence, '[]'::jsonb)) >= 2 then 70
      else 35
    end);

  v_contact_grade := public.pppp_dach_steel_contact_grade_v1(
    new.canonical_contact_email,
    new.canonical_contact_name,
    new.canonical_contact_role,
    new.company_domain
  );
  new.contact_tier := coalesce(nullif(v_contact_grade->>'tier',''),'F');
  new.contact_quality_score := coalesce((v_contact_grade->>'score')::integer,0);

  v_readiness := public.pppp_outreach_readiness_v2(
    new.company_fit_score,
    new.commercial_timing_score,
    new.contact_quality_score,
    new.message_evidence_score,
    jsonb_array_length(coalesce(new.personalization_facts, '[]'::jsonb)),
    false,
    new.cooldown_until
  );
  new.outreach_readiness_score := (v_readiness->>'score')::integer;
  new.workflow_state := v_readiness->>'state';
  new.readiness_reasons := coalesce(v_readiness->'reasons', '[]'::jsonb);
  return new;
end;
$$;


ALTER FUNCTION public.pppp_material_trade_target_defaults_v1() OWNER TO postgres;

