--
-- Name: pppp_opportunity_domain_plausible_v1(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_opportunity_domain_plausible_v1(p_company_name text, p_domain text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_domain text;
  v_root text;
  v_key text;
  v_compact text;
  v_token text;
  v_tokens text[];
begin
  v_domain := lower(trim(coalesce(p_domain,'')));
  v_domain := regexp_replace(v_domain,'^[a-z][a-z0-9+.-]*://','','i');
  v_domain := split_part(split_part(split_part(v_domain,'/',1),'?',1),'#',1);
  v_domain := regexp_replace(v_domain,'^www\.','','i');

  if v_domain='' then return false; end if;
  if v_domain in (
    'gmail.com','googlemail.com','hotmail.com','outlook.com','live.com',
    'yahoo.com','yahoo.de','yahoo.fr','icloud.com','aol.com',
    'gmx.com','gmx.de','web.de','proton.me','protonmail.com','abv.bg',
    'example.com','example.org','example.net',
    'linkedin.com','facebook.com','instagram.com','wikipedia.org',
    'forbes.pl','aleo.com','bloomberg.com','crunchbase.com','kompass.com',
    'europages.com','lursoft.lv','company.lursoft.lv','companywall.hu',
    'openprocurements.com','es.openprocurements.com','e-licitatie.ro',
    'herold.at','emis.com','bidsfactory.com','soloindustria.com','info-brno.cz',
    'advantageaustria.org'
  ) then return false; end if;

  v_root := regexp_replace(split_part(v_domain,'.',1),'[^a-z0-9]+','','g');
  if length(v_root)<3 then return false; end if;

  v_key := public.pppp_opportunity_company_key_v1(p_company_name);
  if v_key='' then return false; end if;
  v_compact := regexp_replace(v_key,'[^a-z0-9]+','','g');

  if v_compact ~ '^[a-z0-9]+$' and position(v_root in v_compact)>0 then
    return true;
  end if;

  v_tokens := regexp_split_to_array(v_key,'\s+');
  foreach v_token in array v_tokens loop
    v_token := regexp_replace(v_token,'[^a-z0-9]+','','g');
    if length(v_token) < 3 then continue; end if;
    if v_token in (
      'gmbh','mbh','gesellschaft','company','limited','ltd','spolka','spolocnost',
      'sro','group','gruppe','holding','construction','bau','infra','engineering',
      'energy','metal','metall','steel','service','services','international',
      'industries','austria','germany','deutschland','france','italia','italy',
      'poland','polska','czechia','slovakia','slovenia','croatia','serbia',
      'romania','bulgaria','portugal','spain','norge','norway','sweden','denmark',
      'finland','estonia','latvia','lithuania','ireland','belgium','netherlands',
      'switzerland'
    ) then continue; end if;
    if position(v_token in v_root)>0 or position(v_root in v_token)>0 then
      return true;
    end if;
  end loop;

  return false;
end
$_$;


ALTER FUNCTION public.pppp_opportunity_domain_plausible_v1(p_company_name text, p_domain text) OWNER TO postgres;

--
-- Name: pppp_outbound_approve_rows_v1(uuid[], text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_approve_rows_v1(p_queue_ids uuid[], p_approved_by text, p_approval_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_requested integer:=coalesce(array_length(p_queue_ids,1),0);
  v_approved integer:=0;
begin
  if v_requested<1 or v_requested>50 then raise exception 'Approval batch must contain 1..50 queue ids'; end if;
  if nullif(trim(coalesce(p_approved_by,'')),'') is null then raise exception 'approved_by is required'; end if;

  update public.pppp_outbound_queue_v1 q
     set approved_for_send=true,
         payload=coalesce(q.payload,'{}'::jsonb)||jsonb_build_object(
           'send_approved_by',trim(p_approved_by),'send_approved_at',now(),
           'send_approval_note',nullif(trim(coalesce(p_approval_note,'')),'')
         ),updated_at=now()
   where q.id=any(p_queue_ids)
     and q.status='planned' and q.sent_at is null and q.replied_at is null and q.bounced_at is null
     and q.suppression_reason is null
     and lower(coalesce(public.pppp_outbound_domain_v1(q.recipient_email,q.company_domain),''))<>'prissteel.com'
     and coalesce((public.pppp_outbound_source_guard_v1(q.id)->>'ok')::boolean,false)
     and exists(
       select 1 from public.pppp_outbound_live_drafts_v1 d
       where d.draft_id=q.gmail_draft_id
         and lower(d.recipient_email)=lower(q.recipient_email)
         and d.captured_at>=now()-interval '4 hours'
     );
  get diagnostics v_approved=row_count;

  return jsonb_build_object(
    'ok',v_approved=v_requested,'requested',v_requested,'approved',v_approved,
    'send_enabled',(select send_enabled from public.pppp_outbound_policy_v1 where id='global'),
    'human_send_required',true
  );
end;
$$;


ALTER FUNCTION public.pppp_outbound_approve_rows_v1(p_queue_ids uuid[], p_approved_by text, p_approval_note text) OWNER TO postgres;

--
-- Name: pppp_outbound_claim_for_dispatch_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_claim_for_dispatch_v1(p_queue_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  q public.pppp_outbound_queue_v1%rowtype;
  p public.pppp_outbound_policy_v1%rowtype;
  v_today date;
  v_local_time time;
  v_sent_today integer:=0;
  v_domain_sent integer:=0;
  v_last_sent timestamptz;
  v_guard jsonb;
  v_domain text;
begin
  if p_queue_id is null or p_claim_token is null then
    return jsonb_build_object('ok',false,'reason','queue_id_and_claim_token_required');
  end if;

  select * into p from public.pppp_outbound_policy_v1 where id='global';
  if not found then return jsonb_build_object('ok',false,'reason','policy_missing'); end if;
  if not p.send_enabled then return jsonb_build_object('ok',false,'reason','send_disabled'); end if;
  if not p.human_send_required then return jsonb_build_object('ok',false,'reason','human_gate_invalid'); end if;

  v_today:=(now() at time zone p.timezone)::date;
  v_local_time:=(now() at time zone p.timezone)::time;
  if v_local_time<p.day_start or v_local_time>=p.day_end then
    return jsonb_build_object(
      'ok',false,'reason','outside_send_window',
      'local_time',v_local_time,'day_start',p.day_start,'day_end',p.day_end,'timezone',p.timezone
    );
  end if;

  select * into q
  from public.pppp_outbound_queue_v1
  where id=p_queue_id
  for update;
  if not found then return jsonb_build_object('ok',false,'reason','queue_row_missing'); end if;

  if q.status<>'planned' then return jsonb_build_object('ok',false,'reason','not_planned'); end if;
  if not q.approved_for_send then return jsonb_build_object('ok',false,'reason','not_human_approved'); end if;
  if q.sent_at is not null then return jsonb_build_object('ok',false,'reason','already_sent'); end if;
  if q.replied_at is not null then return jsonb_build_object('ok',false,'reason','reply_detected'); end if;
  if q.bounced_at is not null then return jsonb_build_object('ok',false,'reason','bounce_detected'); end if;
  if q.suppression_reason is not null then return jsonb_build_object('ok',false,'reason','suppressed','detail',q.suppression_reason); end if;
  if q.planned_date is distinct from v_today then return jsonb_build_object('ok',false,'reason','wrong_operating_day'); end if;
  if q.planned_at is null or q.planned_at>now() then return jsonb_build_object('ok',false,'reason','not_due'); end if;

  v_domain:=lower(coalesce(public.pppp_outbound_domain_v1(q.recipient_email,q.company_domain),''));
  if v_domain='prissteel.com' then
    return jsonb_build_object('ok',false,'reason','internal_pristeel_recipient');
  end if;

  v_guard:=public.pppp_outbound_source_guard_v1(q.id);
  if not coalesce((v_guard->>'ok')::boolean,false) then
    return jsonb_build_object(
      'ok',false,
      'reason',coalesce(v_guard->>'reason','source_invalid'),
      'source_guard',v_guard
    );
  end if;

  if q.dispatch_claim_token is not null
     and q.dispatch_claim_token<>p_claim_token
     and q.dispatch_claimed_at>now()-interval '15 minutes' then
    return jsonb_build_object('ok',false,'reason','already_claimed');
  end if;

  if not exists(
    select 1
    from public.pppp_outbound_live_drafts_v1 d
    where d.draft_id=q.gmail_draft_id
      and lower(d.recipient_email)=lower(q.recipient_email)
      and d.captured_at>=now()-interval '4 hours'
  ) then
    return jsonb_build_object('ok',false,'reason','live_draft_not_fresh_or_recipient_mismatch');
  end if;

  if exists(
    select 1
    from public.outreach_contacts o
    where lower(coalesce(o.contact_email,''))=lower(q.recipient_email)
      and (coalesce(o.bounced,false) or lower(coalesce(o.status,'')) like '%do not contact%')
  ) then
    return jsonb_build_object('ok',false,'reason','recipient_blocked_by_history');
  end if;

  if q.company_domain is not null and exists(
    select 1
    from public.outreach_contacts o
    where lower(coalesce(o.company_domain,''))=lower(q.company_domain)
      and coalesce(o.replied,false)
  ) then
    return jsonb_build_object('ok',false,'reason','company_reply_requires_human_followup');
  end if;

  if exists(
    select 1 from public.pppp_outbound_queue_v1 h
    where h.id<>q.id
      and h.sent_at is not null
      and lower(h.recipient_email)=lower(q.recipient_email)
      and h.sent_at>=now()-make_interval(days=>p.recipient_cooldown_days)
      and not (h.source=q.source and h.source_record_id=q.source_record_id)
  ) then
    return jsonb_build_object('ok',false,'reason','recipient_cooldown_active');
  end if;

  if v_domain<>'' and exists(
    select 1 from public.pppp_outbound_queue_v1 h
    where h.id<>q.id
      and h.sent_at is not null
      and lower(coalesce(public.pppp_outbound_domain_v1(h.recipient_email,h.company_domain),''))=v_domain
      and h.sent_at>=now()-make_interval(days=>p.domain_cooldown_days)
      and not (h.source=q.source and h.source_record_id=q.source_record_id)
  ) then
    return jsonb_build_object('ok',false,'reason','domain_cooldown_active');
  end if;

  select count(*) into v_sent_today
  from public.pppp_outbound_queue_v1 x
  where x.sent_at is not null
    and (x.sent_at at time zone p.timezone)::date=v_today;
  if v_sent_today>=p.daily_limit then return jsonb_build_object('ok',false,'reason','daily_limit_reached'); end if;

  select max(x.sent_at) into v_last_sent
  from public.pppp_outbound_queue_v1 x
  where x.sent_at is not null
    and (x.sent_at at time zone p.timezone)::date=v_today;
  if v_last_sent is not null and v_last_sent>now()-make_interval(mins=>p.min_gap_minutes) then
    return jsonb_build_object('ok',false,'reason','minimum_gap_not_elapsed','last_sent_at',v_last_sent);
  end if;

  select count(*) into v_domain_sent
  from public.pppp_outbound_queue_v1 x
  where x.sent_at is not null
    and (x.sent_at at time zone p.timezone)::date=v_today
    and lower(coalesce(public.pppp_outbound_domain_v1(x.recipient_email,x.company_domain),''))=v_domain;
  if v_domain_sent>=p.max_per_domain_per_day then
    return jsonb_build_object('ok',false,'reason','domain_daily_limit_reached');
  end if;

  update public.pppp_outbound_queue_v1
     set dispatch_claim_token=p_claim_token,
         dispatch_claimed_at=now(),
         dispatch_attempts=dispatch_attempts+1,
         dispatch_last_error=null,
         updated_at=now()
   where id=q.id;

  return jsonb_build_object(
    'ok',true,
    'queue_id',q.id,
    'draft_id',q.gmail_draft_id,
    'recipient_email',q.recipient_email,
    'company_domain',q.company_domain,
    'planned_at',q.planned_at,
    'sent_today',v_sent_today,
    'daily_limit',p.daily_limit,
    'claim_token',p_claim_token
  );
end;
$$;


ALTER FUNCTION public.pppp_outbound_claim_for_dispatch_v1(p_queue_id uuid, p_claim_token uuid) OWNER TO postgres;

--
-- Name: pppp_outbound_dispatch_internal_request(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_dispatch_internal_request() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  p public.pppp_outbound_policy_v1%rowtype;
  v_id uuid;
  v_local_time time;
begin
  select * into p from public.pppp_outbound_policy_v1 where id='global';
  if not found or not p.send_enabled or not p.human_send_required then return null; end if;

  v_local_time:=(now() at time zone p.timezone)::time;
  if v_local_time<p.day_start or v_local_time>=p.day_end then
    return null;
  end if;

  select q.id into v_id
  from public.pppp_outbound_queue_v1 q
  where q.status='planned'
    and q.approved_for_send=true
    and q.sent_at is null
    and q.replied_at is null
    and q.bounced_at is null
    and q.suppression_reason is null
    and q.planned_date=(now() at time zone p.timezone)::date
    and q.planned_at<=now()
    and (q.dispatch_claimed_at is null or q.dispatch_claimed_at<=now()-interval '15 minutes')
    and lower(coalesce(public.pppp_outbound_domain_v1(q.recipient_email,q.company_domain),''))<>'prissteel.com'
    and coalesce((public.pppp_outbound_source_guard_v1(q.id)->>'ok')::boolean,false)
    and exists(
      select 1 from public.pppp_outbound_live_drafts_v1 d
      where d.draft_id=q.gmail_draft_id
        and lower(d.recipient_email)=lower(q.recipient_email)
        and d.captured_at>=now()-interval '4 hours'
    )
  order by q.planned_rank nulls last,q.planned_at,q.id
  limit 1;

  if v_id is null then return null; end if;

  return public.pppp_enqueue_automation_http_v1(
    'pppp-outbound-dispatch',
    'https://awqfpnzqwfjrjefoktgd.supabase.co/functions/v1/pppp-outbound-dispatch?queue_id='||v_id::text,
    'gmail_tracker_cron_secret',
    120000,
    1
  );
end;
$$;


ALTER FUNCTION public.pppp_outbound_dispatch_internal_request() OWNER TO postgres;

--
-- Name: pppp_outbound_domain_v1(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_domain_v1(p_email text, p_domain text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select nullif(
    regexp_replace(
      lower(trim(coalesce(nullif(split_part(coalesce(p_email,''),'@',2),''),nullif(p_domain,'')))),
      '^www\\.','','i'
    ),
    ''
  );
$$;


ALTER FUNCTION public.pppp_outbound_domain_v1(p_email text, p_domain text) OWNER TO postgres;

--
-- Name: pppp_outbound_internal_recipient_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_internal_recipient_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.sent_at is null
     and lower(coalesce(public.pppp_outbound_domain_v1(new.recipient_email,new.company_domain),''))='prissteel.com' then
    new.status:='suppressed';
    new.suppression_reason:='internal_pristeel_recipient';
    new.planned_date:=null;
    new.planned_at:=null;
    new.planned_rank:=null;
    new.approved_for_send:=false;
    new.dispatch_claim_token:=null;
    new.dispatch_claimed_at:=null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_outbound_internal_recipient_guard_v1() OWNER TO postgres;

--
-- Name: pppp_outbound_mark_dispatch_failed_v1(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_mark_dispatch_failed_v1(p_queue_id uuid, p_claim_token uuid, p_error text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.pppp_outbound_queue_v1
     set dispatch_claim_token=null,
         dispatch_claimed_at=null,
         dispatch_last_error=left(coalesce(p_error,'dispatch_failed'),1000),
         updated_at=now()
   where id=p_queue_id
     and dispatch_claim_token=p_claim_token
     and sent_at is null;

  return jsonb_build_object('ok',found);
end;
$$;


ALTER FUNCTION public.pppp_outbound_mark_dispatch_failed_v1(p_queue_id uuid, p_claim_token uuid, p_error text) OWNER TO postgres;

--
-- Name: pppp_outbound_mark_sent_v1(uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_mark_sent_v1(p_queue_id uuid, p_claim_token uuid, p_message_id text, p_thread_id text, p_sent_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  q public.pppp_outbound_queue_v1%rowtype;
  v_sent_at timestamptz:=coalesce(p_sent_at,now());
begin
  select * into q
  from public.pppp_outbound_queue_v1
  where id=p_queue_id
  for update;
  if not found then raise exception 'Queue row not found'; end if;
  if q.sent_at is not null then
    return jsonb_build_object('ok',true,'already_recorded',true,'sent_at',q.sent_at);
  end if;
  if q.dispatch_claim_token is distinct from p_claim_token then
    raise exception 'Dispatch claim mismatch';
  end if;
  if nullif(trim(coalesce(p_message_id,'')),'') is null then raise exception 'message_id required'; end if;

  update public.pppp_outbound_queue_v1
     set status='sent',
         sent_at=v_sent_at,
         gmail_draft_message_id=coalesce(gmail_draft_message_id,p_message_id),
         gmail_thread_id=coalesce(p_thread_id,gmail_thread_id),
         approved_for_send=false,
         dispatch_claim_token=null,
         dispatch_claimed_at=null,
         dispatch_last_error=null,
         payload=coalesce(payload,'{}'::jsonb)||jsonb_build_object(
           'dispatched_at',v_sent_at,
           'gmail_sent_message_id',p_message_id,
           'gmail_sent_thread_id',p_thread_id
         ),
         updated_at=now()
   where id=q.id;

  if q.source='TED' and q.source_record_id is not null then
    update public.pppp_opportunity_outreach_registry_v1
       set status='sent',
           gmail_message_id=p_message_id,
           gmail_thread_id=coalesce(p_thread_id,gmail_thread_id),
           sent_at=v_sent_at,
           last_checked_at=now(),
           last_error=null,
           updated_at=now()
     where id=q.source_record_id;
  elsif q.source='GC' and q.source_record_id is not null then
    if q.touch_no=1 then
      perform public.pppp_gc_mark_first_sent_v1(q.source_record_id,p_message_id,p_thread_id,v_sent_at);
    elsif q.touch_no=2 then
      perform public.pppp_gc_mark_second_sent_v1(q.source_record_id,p_message_id,p_thread_id,v_sent_at);
    end if;
  end if;

  return jsonb_build_object('ok',true,'queue_id',q.id,'status','sent','sent_at',v_sent_at);
end;
$$;


ALTER FUNCTION public.pppp_outbound_mark_sent_v1(p_queue_id uuid, p_claim_token uuid, p_message_id text, p_thread_id text, p_sent_at timestamp with time zone) OWNER TO postgres;

--
-- Name: pppp_outbound_plan_day_v1(date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_plan_day_v1(p_day date DEFAULT CURRENT_DATE, p_limit integer DEFAULT NULL::integer) RETURNS TABLE(queue_id uuid, planned_rank integer, planned_at timestamp with time zone, source text, touch_no smallint, company_name text, company_domain text, recipient_email text, recipient_name text, project_title text, relevance_score integer, priority_score integer, gmail_draft_id text, approved_for_send boolean, send_enabled boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_policy public.pppp_outbound_policy_v1%rowtype;
  v_limit integer;
  v_sent integer;
  v_reserved integer;
  v_remaining integer;
begin
  select * into v_policy from public.pppp_outbound_policy_v1 where id='global';
  if p_day < v_policy.starts_on then
    raise exception 'Outbound planning starts on %',v_policy.starts_on;
  end if;

  perform public.pppp_outbound_sync_v1();

  v_limit:=least(v_policy.daily_limit,greatest(1,coalesce(p_limit,v_policy.daily_limit)));
  select count(*) into v_sent
  from public.pppp_outbound_queue_v1 q
  where q.sent_at is not null
    and (q.sent_at at time zone v_policy.timezone)::date=p_day;

  select count(*) into v_reserved
  from public.pppp_outbound_queue_v1 q
  where q.planned_date=p_day and q.status='planned' and q.approved_for_send=true and q.sent_at is null;

  v_remaining:=greatest(0,v_limit-v_sent-v_reserved);

  update public.pppp_outbound_queue_v1 q
     set status='candidate',planned_date=null,planned_at=null,planned_rank=null,updated_at=now()
   where q.planned_date=p_day and q.status='planned' and q.approved_for_send=false and q.sent_at is null;

  with ranked_recipient as (
    select q.id,
           row_number() over(
             partition by lower(q.recipient_email)
             order by q.priority_score desc,q.relevance_score desc,
                      case q.source when 'TED' then 1 else 2 end,
                      q.source_updated_at desc nulls last,q.id
           ) as rn_email
    from public.pppp_outbound_queue_v1 q
    where q.status='candidate'
      and q.suppression_reason is null
      and q.gmail_draft_id is not null
      and q.sent_at is null
      and q.replied_at is null
      and q.bounced_at is null
      and lower(public.pppp_outbound_domain_v1(q.recipient_email,q.company_domain)) <> 'prissteel.com'
      and exists (
        select 1
        from public.pppp_outbound_live_drafts_v1 d
        where d.draft_id=q.gmail_draft_id
          and lower(d.recipient_email)=lower(q.recipient_email)
          and d.captured_at>=now()-interval '4 hours'
      )
      and coalesce((public.pppp_outbound_source_guard_v1(q.id)->>'ok')::boolean,false)
  ),
  ranked_domain as (
    select q.id,
           row_number() over(
             partition by lower(coalesce(q.company_domain,public.pppp_outbound_domain_v1(q.recipient_email,null)))
             order by q.priority_score desc,q.relevance_score desc,
                      case q.source when 'TED' then 1 else 2 end,
                      q.source_updated_at desc nulls last,q.id
           ) as rn_domain
    from public.pppp_outbound_queue_v1 q
    join ranked_recipient e on e.id=q.id and e.rn_email=1
  ),
  chosen as (
    select q.id,
           row_number() over(
             order by q.priority_score desc,q.relevance_score desc,
                      case q.source when 'TED' then 1 else 2 end,
                      q.source_updated_at desc nulls last,q.id
           )::integer as rn
    from public.pppp_outbound_queue_v1 q
    join ranked_domain d on d.id=q.id and d.rn_domain<=v_policy.max_per_domain_per_day
    where not exists (
      select 1 from public.pppp_outbound_queue_v1 x
      where x.planned_date=p_day
        and x.id<>q.id
        and lower(coalesce(x.company_domain,''))=lower(coalesce(q.company_domain,''))
        and x.status in ('planned','sent')
    )
    limit v_remaining
  )
  update public.pppp_outbound_queue_v1 q
     set status='planned',
         planned_date=p_day,
         planned_rank=c.rn+v_sent+v_reserved,
         planned_at=((p_day::timestamp+v_policy.day_start)
                     + make_interval(mins=>v_policy.planned_gap_minutes*(c.rn+v_sent+v_reserved-1)))
                    at time zone v_policy.timezone,
         approved_for_send=false,
         updated_at=now()
    from chosen c
   where q.id=c.id;

  return query
  select q.id,q.planned_rank,q.planned_at,q.source,q.touch_no,q.company_name,q.company_domain,
         q.recipient_email,q.recipient_name,q.project_title,q.relevance_score,q.priority_score,
         q.gmail_draft_id,q.approved_for_send,v_policy.send_enabled
  from public.pppp_outbound_queue_v1 q
  where q.planned_date=p_day and q.status='planned'
  order by q.planned_rank,q.id;
end;
$$;


ALTER FUNCTION public.pppp_outbound_plan_day_v1(p_day date, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_outbound_preflight_v1(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_preflight_v1(p_day date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with p as (
  select * from public.pppp_outbound_policy_v1 where id='global'
),
planned0 as (
  select q.*,
         lower(coalesce(public.pppp_outbound_domain_v1(q.recipient_email,q.company_domain),'')) as eff_domain,
         public.pppp_outbound_source_guard_v1(q.id) as source_guard
  from public.pppp_outbound_queue_v1 q
  where q.planned_date=p_day and q.status='planned'
),
planned as (
  select x.*,
         count(*) over(partition by lower(x.recipient_email)) as same_recipient,
         count(*) over(partition by x.eff_domain) as same_domain,
         exists(
           select 1 from public.pppp_outbound_live_drafts_v1 d
           where d.draft_id=x.gmail_draft_id
         ) as draft_exists,
         exists(
           select 1 from public.pppp_outbound_live_drafts_v1 d
           where d.draft_id=x.gmail_draft_id
             and d.captured_at>=now()-interval '4 hours'
         ) as draft_fresh,
         exists(
           select 1 from public.pppp_outbound_live_drafts_v1 d
           where d.draft_id=x.gmail_draft_id
             and d.captured_at>=now()-interval '4 hours'
             and lower(d.recipient_email)=lower(x.recipient_email)
         ) as draft_recipient_match,
         exists(
           select 1 from public.pppp_outbound_queue_v1 h, p
           where h.id<>x.id
             and h.sent_at is not null
             and lower(h.recipient_email)=lower(x.recipient_email)
             and h.sent_at>=now()-make_interval(days=>p.recipient_cooldown_days)
             and not (h.source=x.source and h.source_record_id=x.source_record_id)
         ) as recipient_cooldown_conflict,
         exists(
           select 1 from public.pppp_outbound_queue_v1 h, p
           where h.id<>x.id
             and h.sent_at is not null
             and lower(coalesce(public.pppp_outbound_domain_v1(h.recipient_email,h.company_domain),''))=x.eff_domain
             and h.sent_at>=now()-make_interval(days=>p.domain_cooldown_days)
             and not (h.source=x.source and h.source_record_id=x.source_record_id)
         ) as domain_cooldown_conflict
  from planned0 x
),
stats as (
  select
    count(*) as planned_count,
    count(*) filter(where draft_exists) as live_draft_count,
    count(*) filter(where draft_fresh) as fresh_draft_count,
    count(*) filter(where not draft_exists) as missing_draft_count,
    count(*) filter(where draft_exists and not draft_fresh) as stale_draft_count,
    count(*) filter(where draft_fresh and not draft_recipient_match) as recipient_mismatch_count,
    count(*) filter(where not coalesce((source_guard->>'ok')::boolean,false)) as source_invalid_count,
    count(*) filter(where source_guard->>'reason' in (
      'gc_no_more_auto','gc_human_review_or_history','gc_duplicate_history_review',
      'cross_source_conflict_requires_review','gc_first_touch_not_explicit_ready',
      'gc_followup_not_explicit_ready'
    )) as human_review_block_count,
    count(*) filter(where replied_at is not null) as replied_count,
    count(*) filter(where bounced_at is not null) as bounced_count,
    count(*) filter(where suppression_reason is not null) as suppressed_count,
    count(*) filter(where lower(coalesce(eff_domain,''))='prissteel.com') as internal_recipient_count,
    count(*) filter(where recipient_cooldown_conflict) as recipient_cooldown_blocked,
    count(*) filter(where domain_cooldown_conflict) as domain_cooldown_blocked,
    count(*) filter(where approved_for_send) as approved_count,
    count(*) filter(
      where draft_recipient_match
        and coalesce((source_guard->>'ok')::boolean,false)
        and replied_at is null
        and bounced_at is null
        and suppression_reason is null
        and lower(coalesce(eff_domain,''))<>'prissteel.com'
        and not recipient_cooldown_conflict
        and not domain_cooldown_conflict
        and same_recipient=1
        and same_domain=1
    ) as guard_eligible_count,
    count(*) filter(
      where approved_for_send
        and draft_recipient_match
        and coalesce((source_guard->>'ok')::boolean,false)
        and replied_at is null
        and bounced_at is null
        and suppression_reason is null
        and lower(coalesce(eff_domain,''))<>'prissteel.com'
        and not recipient_cooldown_conflict
        and not domain_cooldown_conflict
        and same_recipient=1
        and same_domain=1
        and planned_at is not null
        and planned_at<=now()
    ) as approved_due_guard_eligible_count
  from planned
),
day_sent as (
  select count(*)::integer as sent_today
  from public.pppp_outbound_queue_v1 q,p
  where q.sent_at is not null
    and (q.sent_at at time zone p.timezone)::date=p_day
),
dups as (
  select
    (select count(*) from (
      select lower(recipient_email) e from planned group by lower(recipient_email) having count(*)>1
    ) r) as duplicate_recipient_count,
    (select count(*) from (
      select eff_domain d from planned where eff_domain<>'' group by eff_domain having count(*)>1
    ) d) as duplicate_domain_count
),
ctx as (
  select p.*,
         (now() at time zone p.timezone)::date as local_day,
         (now() at time zone p.timezone)::time as local_time
  from p
)
select jsonb_build_object(
  'day',p_day,
  'policy',(select to_jsonb(p) from p),
  'planned_count',(select planned_count from stats),
  'canonical_count',(select planned_count-source_invalid_count from stats),
  'live_draft_count',(select live_draft_count from stats),
  'fresh_draft_count',(select fresh_draft_count from stats),
  'missing_draft_count',(select missing_draft_count from stats),
  'stale_draft_count',(select stale_draft_count from stats),
  'recipient_mismatch_count',(select recipient_mismatch_count from stats),
  'source_invalid_count',(select source_invalid_count from stats),
  'human_review_block_count',(select human_review_block_count from stats),
  'replied_count',(select replied_count from stats),
  'bounced_count',(select bounced_count from stats),
  'suppressed_count',(select suppressed_count from stats),
  'internal_recipient_count',(select internal_recipient_count from stats),
  'recipient_cooldown_blocked',(select recipient_cooldown_blocked from stats),
  'domain_cooldown_blocked',(select domain_cooldown_blocked from stats),
  'duplicate_recipient_count',(select duplicate_recipient_count from dups),
  'duplicate_domain_count',(select duplicate_domain_count from dups),
  'approved_count',(select approved_count from stats),
  'guard_eligible_count',(select guard_eligible_count from stats),
  'sent_today',(select sent_today from day_sent),
  'daily_cap_remaining',greatest(0,(select daily_limit from p)-(select sent_today from day_sent)),
  'daily_cap_ok',((select planned_count from stats)+(select sent_today from day_sent)) <= (select daily_limit from p),
  'send_window_open',(
    select local_day=p_day and local_time>=day_start and local_time<day_end from ctx
  ),
  'outside_window_guard_active',true,
  'ready_to_dispatch_count',case
    when (select send_enabled from p)
     and (select human_send_required from p)
     and ((select planned_count from stats)+(select sent_today from day_sent)) <= (select daily_limit from p)
     and (select local_day=p_day and local_time>=day_start and local_time<day_end from ctx)
    then (select approved_due_guard_eligible_count from stats)
    else 0
  end,
  'send_enabled',(select send_enabled from p),
  'human_send_required',(select human_send_required from p),
  'auto_send',false
);
$$;


ALTER FUNCTION public.pppp_outbound_preflight_v1(p_day date) OWNER TO postgres;

--
-- Name: pppp_outbound_priority_v1(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_priority_v1(p_email text, p_name text, p_role text, p_relevance integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  select least(1000,
    greatest(0,coalesce(p_relevance,0)) * 5
    + case
        when lower(coalesce(p_role,'')) ~ '(procurement|purchas|einkauf|beschaffung|tender|ausschreib|kalkulation|estimating|sourcing|buyer)' then 320
        when nullif(trim(coalesce(p_name,'')),'') is not null then 240
        when lower(split_part(coalesce(p_email,''),'@',1)) ~ '^(info|office|kontakt|contact|mail|sekretariat|reception)$' then 90
        else 160
      end
  );
$_$;


ALTER FUNCTION public.pppp_outbound_priority_v1(p_email text, p_name text, p_role text, p_relevance integer) OWNER TO postgres;

--
-- Name: pppp_outbound_reconcile_live_drafts_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_reconcile_live_drafts_v1(p_drafts jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_seen integer:=0;
  v_stale integer:=0;
  v_manual integer:=0;
  v_live integer:=0;
begin
  if p_drafts is null or jsonb_typeof(p_drafts)<>'array' then
    raise exception 'p_drafts must be a JSON array';
  end if;

  perform public.pppp_outbound_sync_v1();

  delete from public.pppp_outbound_live_drafts_v1
  where draft_id is not null;

  insert into public.pppp_outbound_live_drafts_v1(
    draft_id,gmail_message_id,gmail_thread_id,recipient_email,subject,captured_at
  )
  select distinct on (x.draft_id)
    x.draft_id,x.gmail_message_id,x.gmail_thread_id,lower(x.recipient_email),x.subject,now()
  from (
    select
      nullif(trim(v->>'draft_id'),'') draft_id,
      nullif(trim(v->>'message_id'),'') gmail_message_id,
      nullif(trim(v->>'thread_id'),'') gmail_thread_id,
      nullif(trim(v->>'recipient_email'),'') recipient_email,
      nullif(trim(v->>'subject'),'') subject
    from jsonb_array_elements(p_drafts) v
  ) x
  where x.draft_id is not null
    and x.recipient_email is not null
    and x.recipient_email ~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
  order by x.draft_id;
  get diagnostics v_seen=row_count;

  update public.pppp_outbound_queue_v1 q
     set gmail_draft_message_id=coalesce(d.gmail_message_id,q.gmail_draft_message_id),
         gmail_thread_id=coalesce(d.gmail_thread_id,q.gmail_thread_id),
         recipient_email=d.recipient_email,
         company_domain=public.pppp_outbound_domain_v1(d.recipient_email,q.company_domain),
         status=case
           when q.status='stale' and q.suppression_reason='gmail_draft_missing' then 'candidate'
           else q.status end,
         suppression_reason=case
           when q.status='stale' and q.suppression_reason='gmail_draft_missing' then null
           else q.suppression_reason end,
         planned_date=case
           when q.status='stale' and q.suppression_reason='gmail_draft_missing' then null
           else q.planned_date end,
         planned_at=case
           when q.status='stale' and q.suppression_reason='gmail_draft_missing' then null
           else q.planned_at end,
         planned_rank=case
           when q.status='stale' and q.suppression_reason='gmail_draft_missing' then null
           else q.planned_rank end,
         payload=coalesce(q.payload,'{}'::jsonb)||jsonb_build_object('gmail_live_verified_at',now()),
         updated_at=now()
    from public.pppp_outbound_live_drafts_v1 d
   where q.gmail_draft_id=d.draft_id
     and q.sent_at is null;

  update public.pppp_outbound_queue_v1 q
     set status='stale',
         suppression_reason='gmail_draft_missing',
         planned_date=null,planned_at=null,planned_rank=null,
         approved_for_send=false,
         payload=coalesce(q.payload,'{}'::jsonb)||jsonb_build_object('gmail_missing_checked_at',now()),
         updated_at=now()
   where q.sent_at is null
     and q.gmail_draft_id is not null
     and q.status in ('candidate','planned','suppressed')
     and not exists (
       select 1 from public.pppp_outbound_live_drafts_v1 d where d.draft_id=q.gmail_draft_id
     );
  get diagnostics v_stale=row_count;

  insert into public.pppp_outbound_queue_v1(
    source,source_record_id,source_key,touch_no,project_key,project_title,company_name,company_domain,
    recipient_email,recipient_name,contact_role,relevance_score,priority_score,gmail_draft_id,
    gmail_draft_message_id,gmail_thread_id,status,suppression_reason,approved_for_send,human_send_required,
    source_updated_at,payload,updated_at
  )
  select
    'TED',null,'GMAIL:'||d.draft_id,1,'GMAIL:'||d.draft_id,d.subject,
    coalesce((
      select q2.company_name
      from public.pppp_outbound_queue_v1 q2
      where q2.source='TED'
        and q2.company_domain=public.pppp_outbound_domain_v1(d.recipient_email,null)
        and nullif(q2.company_name,'') is not null
      order by q2.relevance_score desc,q2.updated_at desc
      limit 1
    ),public.pppp_outbound_domain_v1(d.recipient_email,null)),
    public.pppp_outbound_domain_v1(d.recipient_email,null),
    d.recipient_email,null,'live_gmail_outreach_draft',
    case when exists(
      select 1 from public.pppp_outbound_queue_v1 q2
      where q2.source='TED' and q2.company_domain=public.pppp_outbound_domain_v1(d.recipient_email,null)
    ) then 90 else 80 end,
    public.pppp_outbound_priority_v1(
      d.recipient_email,null,'live_gmail_outreach_draft',
      case when exists(
        select 1 from public.pppp_outbound_queue_v1 q2
        where q2.source='TED' and q2.company_domain=public.pppp_outbound_domain_v1(d.recipient_email,null)
      ) then 90 else 80 end
    ),
    d.draft_id,d.gmail_message_id,d.gmail_thread_id,'stale','gmail_live_unresolved_noncanonical',false,true,now(),
    jsonb_build_object('manual_live_draft',true,'gmail_live_verified_at',now(),'subject',d.subject),
    now()
  from public.pppp_outbound_live_drafts_v1 d
  where not exists (
      select 1 from public.pppp_outbound_queue_v1 q where q.gmail_draft_id=d.draft_id
    )
    and not exists (
      select 1 from public.pppp_gc_prospects_v1 p
      where p.first_draft_id=d.draft_id or p.second_draft_id=d.draft_id
    )
    and coalesce(d.subject,'') ilike '%PRISTEEL%'
    and lower(public.pppp_outbound_domain_v1(d.recipient_email,null)) <> 'prissteel.com'
  on conflict (source_key) do update set
    gmail_draft_message_id=excluded.gmail_draft_message_id,
    gmail_thread_id=excluded.gmail_thread_id,
    recipient_email=excluded.recipient_email,
    company_domain=excluded.company_domain,
    project_title=excluded.project_title,
    status=case
      when public.pppp_outbound_queue_v1.sent_at is not null then public.pppp_outbound_queue_v1.status
      else 'stale'
    end,
    suppression_reason=case
      when public.pppp_outbound_queue_v1.sent_at is not null then public.pppp_outbound_queue_v1.suppression_reason
      else 'gmail_live_unresolved_noncanonical'
    end,
    source_updated_at=now(),
    payload=excluded.payload,
    updated_at=now();
  get diagnostics v_manual=row_count;

  update public.pppp_outbound_queue_v1 q
     set status='suppressed',suppression_reason='internal_pristeel_recipient',planned_date=null,planned_at=null,
         planned_rank=null,approved_for_send=false,updated_at=now()
   where q.sent_at is null
     and lower(public.pppp_outbound_domain_v1(q.recipient_email,q.company_domain))='prissteel.com';

  select count(*) into v_live from public.pppp_outbound_queue_v1 q
  where q.sent_at is null
    and q.status in ('candidate','planned')
    and exists(select 1 from public.pppp_outbound_live_drafts_v1 d where d.draft_id=q.gmail_draft_id);

  return jsonb_build_object(
    'ok',true,
    'gmail_drafts_seen',v_seen,
    'queue_rows_marked_stale',v_stale,
    'manual_live_drafts_registered',v_manual,
    'live_send_ready_rows',v_live,
    'human_send_required',true,
    'auto_send',false
  );
end;
$_$;


ALTER FUNCTION public.pppp_outbound_reconcile_live_drafts_v1(p_drafts jsonb) OWNER TO postgres;

--
-- Name: pppp_outbound_source_guard_legacy_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_source_guard_legacy_v1(p_queue_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  q public.pppp_outbound_queue_v1%rowtype;
  r public.pppp_opportunity_outreach_registry_v1%rowtype;
  g public.pppp_gc_prospects_v1%rowtype;
  d public.pppp_dach_steel_targets_v1%rowtype;
  v_domain text;
  v_guard jsonb;
  v_mode text;
begin
  select * into q from public.pppp_outbound_queue_v1 where id=p_queue_id;
  if not found then return jsonb_build_object('ok',false,'reason','queue_row_missing'); end if;
  v_domain:=lower(coalesce(public.pppp_outbound_domain_v1(q.recipient_email,q.company_domain),''));

  v_guard:=public.pppp_global_communication_guard_v1(
    q.recipient_email,q.company_domain,q.source,q.source_record_id,q.id
  );
  if not coalesce((v_guard->>'ok')::boolean,false) then
    return jsonb_build_object(
      'ok',false,
      'reason',coalesce(v_guard->>'reason','global_communication_guard_blocked'),
      'global_guard',v_guard
    );
  end if;

  if q.source='TED' then
    if q.source_record_id is null or q.source_key is distinct from ('TED:'||q.source_record_id::text) then return jsonb_build_object('ok',false,'reason','ted_noncanonical_identity'); end if;
    select * into r from public.pppp_opportunity_outreach_registry_v1 where id=q.source_record_id;
    if not found then return jsonb_build_object('ok',false,'reason','ted_registry_missing'); end if;
    if r.status<>'draft_created' then return jsonb_build_object('ok',false,'reason','ted_not_active_candidate','source_status',r.status); end if;
    if r.sent_at is not null then return jsonb_build_object('ok',false,'reason','ted_already_sent'); end if;
    if r.gmail_draft_id is distinct from q.gmail_draft_id then return jsonb_build_object('ok',false,'reason','ted_draft_identity_mismatch'); end if;
    if lower(coalesce(r.recipient_email,'')) is distinct from lower(coalesce(q.recipient_email,'')) then return jsonb_build_object('ok',false,'reason','ted_recipient_identity_mismatch'); end if;
    v_guard:=public.pppp_ted_outreach_history_guard_v1(q.id);
    if not coalesce((v_guard->>'ok')::boolean,false) then return v_guard; end if;
    return public.pppp_ted_outreach_readiness_v1(q.id);
  end if;

  if q.source='GC' then
    if q.source_record_id is null then return jsonb_build_object('ok',false,'reason','gc_source_identity_missing'); end if;
    select * into g from public.pppp_gc_prospects_v1 where id=q.source_record_id;
    if not found then return jsonb_build_object('ok',false,'reason','gc_source_missing'); end if;
    if coalesce(g.do_not_contact,false) or g.status='do_not_contact' then return jsonb_build_object('ok',false,'reason','gc_do_not_contact'); end if;
    if g.bounced_at is not null or g.status='bounced' then return jsonb_build_object('ok',false,'reason','gc_bounced'); end if;
    if g.replied_at is not null or g.status='replied' then return jsonb_build_object('ok',false,'reason','gc_replied'); end if;
    if coalesce(g.no_more_auto,false) then return jsonb_build_object('ok',false,'reason','gc_no_more_auto'); end if;
    if g.status in ('already_contacted','human_review') then return jsonb_build_object('ok',false,'reason','gc_human_review_or_history'); end if;
    if nullif(trim(coalesce(g.duplicate_reason,'')),'') is not null then return jsonb_build_object('ok',false,'reason','gc_duplicate_history_review'); end if;
    if q.touch_no=1 then
      if g.status<>'draft_ready' then return jsonb_build_object('ok',false,'reason','gc_first_touch_not_explicit_ready','source_status',g.status); end if;
      if g.first_sent_at is not null then return jsonb_build_object('ok',false,'reason','gc_first_touch_already_sent'); end if;
      if g.first_draft_id is distinct from q.gmail_draft_id then return jsonb_build_object('ok',false,'reason','gc_first_touch_draft_mismatch'); end if;
      return jsonb_build_object('ok',true,'reason','gc_first_touch_explicit_ready');
    elsif q.touch_no=2 then
      if g.status<>'draft_2_ready' then return jsonb_build_object('ok',false,'reason','gc_followup_not_explicit_ready','source_status',g.status); end if;
      if g.first_sent_at is null then return jsonb_build_object('ok',false,'reason','gc_followup_missing_first_send'); end if;
      if g.second_sent_at is not null then return jsonb_build_object('ok',false,'reason','gc_followup_already_sent'); end if;
      if g.second_draft_id is distinct from q.gmail_draft_id then return jsonb_build_object('ok',false,'reason','gc_followup_draft_mismatch'); end if;
      return jsonb_build_object('ok',true,'reason','gc_followup_explicit_ready');
    end if;
    return jsonb_build_object('ok',false,'reason','gc_touch_not_supported');
  end if;

  if q.source='DACH_STEEL_BUYER' then
    if q.source_record_id is null then return jsonb_build_object('ok',false,'reason','dach_source_identity_missing'); end if;
    if q.touch_no<>1 then return jsonb_build_object('ok',false,'reason','dach_touch_not_supported'); end if;
    if q.source_key is distinct from ('DACH_STEEL_BUYER:'||q.source_record_id::text||':1') then
      return jsonb_build_object('ok',false,'reason','dach_noncanonical_identity');
    end if;

    select * into d from public.pppp_dach_steel_targets_v1 where id=q.source_record_id;
    if not found then return jsonb_build_object('ok',false,'reason','dach_target_missing'); end if;
    if d.target_status in ('closed','rejected') then return jsonb_build_object('ok',false,'reason','dach_target_not_active'); end if;
    if d.outreach_status<>'queued' then return jsonb_build_object('ok',false,'reason','dach_target_not_queued','source_status',d.outreach_status); end if;
    if d.outbound_source_key is distinct from q.source_key then return jsonb_build_object('ok',false,'reason','dach_queue_identity_mismatch'); end if;
    if d.contact_status not in ('found','verified') then return jsonb_build_object('ok',false,'reason','dach_contact_not_ready'); end if;
    if q.gmail_draft_id is null then return jsonb_build_object('ok',false,'reason','dach_draft_missing'); end if;
    if d.company_domain is not null and lower(d.company_domain) is distinct from v_domain then
      return jsonb_build_object('ok',false,'reason','dach_recipient_domain_mismatch');
    end if;

    v_mode:=lower(coalesce(q.payload->>'approach_mode',''));
    if d.quote_readiness='M3' and v_mode<>'direct_offer' then
      return jsonb_build_object('ok',false,'reason','dach_m3_mode_mismatch');
    end if;
    if d.quote_readiness in ('M0','M1','M2') and v_mode<>'rfq_request' then
      return jsonb_build_object('ok',false,'reason','dach_rfq_mode_required');
    end if;

    return jsonb_build_object('ok',true,'reason','dach_target_and_draft_ready','approach_mode',v_mode);
  end if;

  return jsonb_build_object('ok',false,'reason','unsupported_source');
end;
$$;


ALTER FUNCTION public.pppp_outbound_source_guard_legacy_v1(p_queue_id uuid) OWNER TO postgres;

--
-- Name: pppp_outbound_source_guard_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_source_guard_v1(p_queue_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  q public.pppp_outbound_queue_v1%rowtype;
  d public.pppp_dach_steel_targets_v1%rowtype;
  first_touch public.pppp_outbound_queue_v1%rowtype;
  v_domain text;
  v_guard jsonb;
  v_mode text;
begin
  select * into q from public.pppp_outbound_queue_v1 where id=p_queue_id;
  if not found then return jsonb_build_object('ok',false,'reason','queue_row_missing'); end if;

  if q.source <> 'DACH_STEEL_BUYER' then
    return public.pppp_outbound_source_guard_legacy_v1(p_queue_id);
  end if;

  if q.source_record_id is null then
    return jsonb_build_object('ok',false,'reason','steel_buyer_source_identity_missing');
  end if;
  if q.touch_no not in (1,2) then
    return jsonb_build_object('ok',false,'reason','steel_buyer_touch_not_supported');
  end if;
  if q.source_key not like ('DACH_STEEL_BUYER:'||q.source_record_id::text||':'||q.touch_no::text||':%')
     and not (q.touch_no=1 and q.source_key=('DACH_STEEL_BUYER:'||q.source_record_id::text||':1')) then
    return jsonb_build_object('ok',false,'reason','steel_buyer_noncanonical_identity');
  end if;

  select * into d from public.pppp_dach_steel_targets_v1 where id=q.source_record_id;
  if not found then return jsonb_build_object('ok',false,'reason','steel_buyer_target_missing'); end if;
  if d.target_status in ('closed','rejected','project_promoted') then
    return jsonb_build_object('ok',false,'reason','steel_buyer_target_not_active');
  end if;
  if q.gmail_draft_id is null then return jsonb_build_object('ok',false,'reason','steel_buyer_draft_missing'); end if;
  v_domain:=lower(coalesce(public.pppp_outbound_domain_v1(q.recipient_email,q.company_domain),''));
  if d.company_domain is not null and public.pppp_normalize_company_domain_v1(d.company_domain) is distinct from public.pppp_normalize_company_domain_v1(v_domain) then
    return jsonb_build_object('ok',false,'reason','steel_buyer_recipient_domain_mismatch');
  end if;

  if q.touch_no=1 then
    v_guard:=public.pppp_global_communication_guard_v1(q.recipient_email,q.company_domain,q.source,q.source_record_id,q.id);
    if not coalesce((v_guard->>'ok')::boolean,false) then
      return jsonb_build_object('ok',false,'reason',coalesce(v_guard->>'reason','global_communication_guard_blocked'),'global_guard',v_guard);
    end if;
    if d.contact_status not in ('found','verified') then
      return jsonb_build_object('ok',false,'reason','steel_buyer_contact_not_ready');
    end if;
    v_mode:=lower(coalesce(q.payload->>'approach_mode',''));
    if v_mode not in ('material_buyer','external_production_capacity','future_supplier_qualification','direct_offer','rfq_request') then
      return jsonb_build_object('ok',false,'reason','steel_buyer_outreach_mode_invalid','approach_mode',v_mode);
    end if;
    return jsonb_build_object('ok',true,'reason','steel_buyer_contact_draft_ready','approach_mode',v_mode,'recipient',lower(q.recipient_email));
  end if;

  select * into first_touch
  from public.pppp_outbound_queue_v1
  where source='DACH_STEEL_BUYER'
    and source_record_id=q.source_record_id
    and touch_no=1
    and lower(recipient_email)=lower(q.recipient_email)
  order by updated_at desc
  limit 1;
  if not found or first_touch.sent_at is null then
    return jsonb_build_object('ok',false,'reason','steel_buyer_followup_missing_first_send');
  end if;
  if first_touch.replied_at is not null or first_touch.status='replied' then
    return jsonb_build_object('ok',false,'reason','steel_buyer_followup_reply_exists');
  end if;
  if first_touch.sent_at > now()-interval '7 days' then
    return jsonb_build_object('ok',false,'reason','steel_buyer_followup_not_due');
  end if;
  if lower(coalesce(q.payload->>'outreach_motion','human_reviewed_followup')) <> 'human_reviewed_followup'
     and lower(coalesce(q.outreach_motion,'')) <> 'human_reviewed_followup' then
    return jsonb_build_object('ok',false,'reason','steel_buyer_followup_mode_invalid');
  end if;
  return jsonb_build_object('ok',true,'reason','steel_buyer_followup_draft_ready','recipient',lower(q.recipient_email),'first_sent_at',first_touch.sent_at);
end;
$$;


ALTER FUNCTION public.pppp_outbound_source_guard_v1(p_queue_id uuid) OWNER TO postgres;

--
-- Name: pppp_outbound_status_v1(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_status_v1(p_day date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'policy',(select to_jsonb(p) from public.pppp_outbound_policy_v1 p where p.id='global'),
    'day',p_day,
    'queue_total',(select count(*) from public.pppp_outbound_queue_v1),
    'candidate_count',(select count(*) from public.pppp_outbound_queue_v1 where status='candidate'),
    'planned_count',(select count(*) from public.pppp_outbound_queue_v1 where status='planned' and planned_date=p_day),
    'suppressed_count',(select count(*) from public.pppp_outbound_queue_v1 where status='suppressed'),
    'sent_count',(select count(*) from public.pppp_outbound_queue_v1 q,public.pppp_outbound_policy_v1 p
                  where q.sent_at is not null and p.id='global'
                    and (q.sent_at at time zone p.timezone)::date=p_day),
    'ted_open',(select count(*) from public.pppp_outbound_queue_v1 where source='TED' and status in ('candidate','planned')),
    'gc_open',(select count(*) from public.pppp_outbound_queue_v1 where source='GC' and status in ('candidate','planned')),
    'human_send_required',true,
    'auto_send',false
  );
$$;


ALTER FUNCTION public.pppp_outbound_status_v1(p_day date) OWNER TO postgres;

--
-- Name: pppp_outbound_sync_internal_request(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_sync_internal_request() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'net', 'vault', 'pg_temp'
    AS $$
declare
  v_local timestamp;
  v_hour integer;
  v_minute integer;
  v_isodow integer;
begin
  v_local := now() at time zone 'Europe/Belgrade';
  v_hour := extract(hour from v_local)::integer;
  v_minute := extract(minute from v_local)::integer;
  v_isodow := extract(isodow from v_local)::integer;

  if v_isodow not between 1 and 5
     or v_minute <> 30
     or v_hour not in (7,11,15,18) then
    return null;
  end if;

  if exists (
    select 1
    from public.pppp_automation_http_runs r
    where r.automation_key = 'pppp-outbound-sync'
      and r.queued_at >= now() - interval '20 minutes'
  ) then
    return null;
  end if;

  return public.pppp_enqueue_automation_http_v1(
    'pppp-outbound-sync',
    'https://awqfpnzqwfjrjefoktgd.supabase.co/functions/v1/pppp-outbound-sync',
    'gmail_tracker_cron_secret',
    180000,
    1
  );
end;
$$;


ALTER FUNCTION public.pppp_outbound_sync_internal_request() OWNER TO postgres;

--
-- Name: pppp_outbound_sync_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outbound_sync_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_ted integer:=0;
  v_gc1 integer:=0;
  v_gc2 integer:=0;
  v_suppressed integer:=0;
  v_policy public.pppp_outbound_policy_v1%rowtype;
begin
  select * into v_policy from public.pppp_outbound_policy_v1 where id='global';

  insert into public.pppp_outbound_queue_v1(
    source,source_record_id,source_key,touch_no,tender_watch_id,project_key,project_title,
    company_name,company_domain,recipient_email,recipient_name,contact_role,relevance_score,priority_score,
    gmail_draft_id,gmail_draft_message_id,gmail_thread_id,status,suppression_reason,human_send_required,
    sent_at,source_updated_at,payload,updated_at
  )
  select
    'TED',r.id,'TED:'||r.id::text,1,r.tender_watch_id,
    coalesce(r.tender_watch_id::text,r.action_key),
    t.title,
    a.target_company,
    public.pppp_outbound_domain_v1(r.recipient_email,null),
    lower(r.recipient_email),
    r.recipient_name,
    coalesce(r.payload->>'recipient_purpose',a.route,a.action_type),
    greatest(0,least(100,coalesce(a.relevance_score,0))),
    public.pppp_outbound_priority_v1(r.recipient_email,r.recipient_name,coalesce(r.payload->>'recipient_purpose',a.route,a.action_type),coalesce(a.relevance_score,0)),
    r.gmail_draft_id,r.gmail_draft_message_id,r.gmail_thread_id,
    case when r.status='sent' then 'sent' else 'candidate' end,
    null,true,r.sent_at,r.updated_at,
    jsonb_build_object('action_id',r.action_id,'action_key',r.action_key,'route',a.route,'generator',r.generator),
    now()
  from public.pppp_opportunity_outreach_registry_v1 r
  join public.pppp_opportunity_action_queue_v2 a on a.id=r.action_id
  left join public.kek_tender_watch t on t.id=r.tender_watch_id
  where r.status in ('draft_created','sent')
  on conflict (source_key) do update set
    tender_watch_id=excluded.tender_watch_id,
    project_key=excluded.project_key,
    project_title=excluded.project_title,
    company_name=excluded.company_name,
    company_domain=excluded.company_domain,
    recipient_email=excluded.recipient_email,
    recipient_name=excluded.recipient_name,
    contact_role=excluded.contact_role,
    relevance_score=excluded.relevance_score,
    priority_score=excluded.priority_score,
    gmail_draft_id=excluded.gmail_draft_id,
    gmail_draft_message_id=excluded.gmail_draft_message_id,
    gmail_thread_id=excluded.gmail_thread_id,
    status=case
                when excluded.status='sent' then 'sent'
                when public.pppp_outbound_queue_v1.status in ('sent','replied','bounced','do_not_contact') then public.pppp_outbound_queue_v1.status
                when public.pppp_outbound_queue_v1.status='stale'
                 and public.pppp_outbound_queue_v1.suppression_reason='gmail_draft_missing'
                 and public.pppp_outbound_queue_v1.sent_at is null then 'stale'
                else 'candidate' end,
    suppression_reason=case
                when excluded.status='sent' then null
                when public.pppp_outbound_queue_v1.status='stale'
                 and public.pppp_outbound_queue_v1.suppression_reason='gmail_draft_missing'
                 and public.pppp_outbound_queue_v1.sent_at is null then 'gmail_draft_missing'
                else null end,
    sent_at=coalesce(excluded.sent_at,public.pppp_outbound_queue_v1.sent_at),
    source_updated_at=excluded.source_updated_at,
    payload=excluded.payload,
    updated_at=now();
  get diagnostics v_ted=row_count;

  insert into public.pppp_outbound_queue_v1(
    source,source_record_id,source_key,touch_no,project_key,project_title,company_name,company_domain,
    recipient_email,recipient_name,contact_role,relevance_score,priority_score,gmail_draft_id,
    gmail_draft_message_id,gmail_thread_id,status,suppression_reason,human_send_required,sent_at,replied_at,bounced_at,
    source_updated_at,payload,updated_at
  )
  select
    'GC',p.id,'GC:'||p.id::text||':1',1,p.id::text,
    nullif(p.current_projects->0->>'name',''),p.company_name,
    public.pppp_outbound_domain_v1(p.contact_email,p.company_domain),
    lower(p.contact_email),p.contact_name,p.contact_role,
    greatest(0,least(100,p.relevance_score)),
    public.pppp_outbound_priority_v1(p.contact_email,p.contact_name,p.contact_role,p.relevance_score),
    p.first_draft_id,p.first_gmail_message_id,p.first_gmail_thread_id,
    case
      when p.do_not_contact or p.status='do_not_contact' then 'do_not_contact'
      when p.bounced_at is not null or p.status='bounced' then 'bounced'
      when p.replied_at is not null or p.status='replied' then 'replied'
      when p.first_sent_at is not null then 'sent'
      else 'candidate'
    end,
    null,true,p.first_sent_at,p.replied_at,p.bounced_at,p.updated_at,
    jsonb_build_object('prospect_status',p.status,'discovery_source',p.discovery_source,'country',p.country,'company_type',p.company_type),
    now()
  from public.pppp_gc_prospects_v1 p
  where p.contact_email is not null
    and (p.first_draft_id is not null or p.first_sent_at is not null)
  on conflict (source_key) do update set
    project_title=excluded.project_title,company_name=excluded.company_name,company_domain=excluded.company_domain,
    recipient_email=excluded.recipient_email,recipient_name=excluded.recipient_name,contact_role=excluded.contact_role,
    relevance_score=excluded.relevance_score,priority_score=excluded.priority_score,gmail_draft_id=excluded.gmail_draft_id,
    gmail_draft_message_id=excluded.gmail_draft_message_id,gmail_thread_id=excluded.gmail_thread_id,
    status=case
      when excluded.status in ('sent','replied','bounced','do_not_contact') then excluded.status
      when public.pppp_outbound_queue_v1.status='stale'
       and public.pppp_outbound_queue_v1.suppression_reason='gmail_draft_missing'
       and public.pppp_outbound_queue_v1.sent_at is null then 'stale'
      else excluded.status end,
    suppression_reason=case
      when excluded.status in ('sent','replied','bounced','do_not_contact') then null
      when public.pppp_outbound_queue_v1.status='stale'
       and public.pppp_outbound_queue_v1.suppression_reason='gmail_draft_missing'
       and public.pppp_outbound_queue_v1.sent_at is null then 'gmail_draft_missing'
      else null end,
    sent_at=excluded.sent_at,replied_at=excluded.replied_at,bounced_at=excluded.bounced_at,
    source_updated_at=excluded.source_updated_at,payload=excluded.payload,updated_at=now();
  get diagnostics v_gc1=row_count;

  insert into public.pppp_outbound_queue_v1(
    source,source_record_id,source_key,touch_no,project_key,project_title,company_name,company_domain,
    recipient_email,recipient_name,contact_role,relevance_score,priority_score,gmail_draft_id,
    gmail_draft_message_id,gmail_thread_id,status,suppression_reason,human_send_required,sent_at,replied_at,bounced_at,
    source_updated_at,payload,updated_at
  )
  select
    'GC',p.id,'GC:'||p.id::text||':2',2,p.id::text,
    nullif(p.current_projects->0->>'name',''),p.company_name,
    public.pppp_outbound_domain_v1(p.contact_email,p.company_domain),
    lower(p.contact_email),p.contact_name,p.contact_role,
    greatest(0,least(100,p.relevance_score)),
    public.pppp_outbound_priority_v1(p.contact_email,p.contact_name,p.contact_role,p.relevance_score)+40,
    p.second_draft_id,p.second_gmail_message_id,p.first_gmail_thread_id,
    case
      when p.do_not_contact or p.status='do_not_contact' then 'do_not_contact'
      when p.bounced_at is not null or p.status='bounced' then 'bounced'
      when p.replied_at is not null or p.status='replied' then 'replied'
      when p.second_sent_at is not null then 'sent'
      else 'candidate'
    end,
    null,true,p.second_sent_at,p.replied_at,p.bounced_at,p.updated_at,
    jsonb_build_object('prospect_status',p.status,'discovery_source',p.discovery_source,'country',p.country,'company_type',p.company_type,'followup',true),
    now()
  from public.pppp_gc_prospects_v1 p
  where p.contact_email is not null
    and (p.second_draft_id is not null or p.second_sent_at is not null)
  on conflict (source_key) do update set
    project_title=excluded.project_title,company_name=excluded.company_name,company_domain=excluded.company_domain,
    recipient_email=excluded.recipient_email,recipient_name=excluded.recipient_name,contact_role=excluded.contact_role,
    relevance_score=excluded.relevance_score,priority_score=excluded.priority_score,gmail_draft_id=excluded.gmail_draft_id,
    gmail_draft_message_id=excluded.gmail_draft_message_id,gmail_thread_id=excluded.gmail_thread_id,
    status=case
      when excluded.status in ('sent','replied','bounced','do_not_contact') then excluded.status
      when public.pppp_outbound_queue_v1.status='stale'
       and public.pppp_outbound_queue_v1.suppression_reason='gmail_draft_missing'
       and public.pppp_outbound_queue_v1.sent_at is null then 'stale'
      else excluded.status end,
    suppression_reason=case
      when excluded.status in ('sent','replied','bounced','do_not_contact') then null
      when public.pppp_outbound_queue_v1.status='stale'
       and public.pppp_outbound_queue_v1.suppression_reason='gmail_draft_missing'
       and public.pppp_outbound_queue_v1.sent_at is null then 'gmail_draft_missing'
      else null end,
    sent_at=excluded.sent_at,replied_at=excluded.replied_at,bounced_at=excluded.bounced_at,
    source_updated_at=excluded.source_updated_at,payload=excluded.payload,updated_at=now();
  get diagnostics v_gc2=row_count;

  -- Retire queue rows whose canonical source is no longer send-ready.
  update public.pppp_outbound_queue_v1 q
     set status='stale',suppression_reason='canonical_source_not_send_ready',planned_date=null,planned_at=null,planned_rank=null,updated_at=now()
   where q.source='TED' and q.source_record_id is not null and q.sent_at is null
     and not exists (
       select 1 from public.pppp_opportunity_outreach_registry_v1 r
       where r.id=q.source_record_id and r.status in ('draft_created','sent')
     );

  update public.pppp_outbound_queue_v1 q
     set status='stale',suppression_reason='canonical_source_not_send_ready',planned_date=null,planned_at=null,planned_rank=null,updated_at=now()
   where q.source='GC' and q.source_record_id is not null and q.sent_at is null
     and not exists (
       select 1 from public.pppp_gc_prospects_v1 p
       where p.id=q.source_record_id
         and (
           (q.touch_no=1 and (p.first_draft_id is not null or p.first_sent_at is not null))
           or
           (q.touch_no=2 and (p.second_draft_id is not null or p.second_sent_at is not null))
         )
     );

  -- Re-evaluate only unsent/unapproved rows. Human-approved rows are never silently changed.
  update public.pppp_outbound_queue_v1 q
     set status='candidate',suppression_reason=null,planned_date=null,planned_at=null,planned_rank=null,updated_at=now()
   where q.status in ('candidate','planned','suppressed')
     and q.sent_at is null
     and q.approved_for_send=false;

  -- Invalid / unsafe recipient classes.
  update public.pppp_outbound_queue_v1 q
     set status='suppressed',suppression_reason='unsafe_or_invalid_recipient',updated_at=now()
   where q.status='candidate'
     and (
       q.recipient_email !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
       or lower(coalesce(q.company_domain,'')) in (
         'gmail.com','googlemail.com','hotmail.com','outlook.com','live.com','yahoo.com','icloud.com','aol.com',
         'lursoft.lv','implisense.com','forbes.pl','aleo.com','example.com','example.org','example.net'
       )
       or lower(split_part(q.recipient_email,'@',1)) in (
         'investorrelations','investor.relations','personalni','nabor','werken','imie.nazwisko','bieterportal-alt',
         'recruiting','jobs','careers','career','hr','humanresources','privacy','gdpr','webmaster','press','presse',
         'media','newsletter','noreply','no-reply','donotreply','dpo','security','abuse'
       )
       or lower(split_part(q.recipient_email,'@',1)) like 'u003e%'
     );

  -- Exact recipient hard suppression after bounce / explicit do-not-contact from the shared outreach history.
  update public.pppp_outbound_queue_v1 q
     set status='suppressed',suppression_reason='recipient_blocked_by_outreach_history',updated_at=now()
   where q.status='candidate'
     and exists (
       select 1 from public.outreach_contacts o
       where lower(coalesce(o.contact_email,''))=lower(q.recipient_email)
         and (coalesce(o.bounced,false) or lower(coalesce(o.status,'')) like '%do not contact%')
     );

  -- A company reply means cold outreach pauses for that domain until a human decides what to do next.
  update public.pppp_outbound_queue_v1 q
     set status='suppressed',suppression_reason='company_reply_requires_human_followup',updated_at=now()
   where q.status='candidate'
     and q.company_domain is not null
     and exists (
       select 1 from public.outreach_contacts o
       where lower(coalesce(o.company_domain,''))=lower(q.company_domain)
         and coalesce(o.replied,false)
     );

  -- Shared cooldown: TED and GC cannot independently cold-contact the same recipient/company.
  update public.pppp_outbound_queue_v1 q
     set status='suppressed',suppression_reason='recipient_cooldown_'||v_policy.recipient_cooldown_days::text||'d',updated_at=now()
   where q.status='candidate'
     and exists (
       select 1 from public.pppp_outbound_queue_v1 h
       where h.id<>q.id and h.sent_at is not null
         and lower(h.recipient_email)=lower(q.recipient_email)
         and h.sent_at >= now() - make_interval(days=>v_policy.recipient_cooldown_days)
         and not (h.source=q.source and h.source_record_id=q.source_record_id)
     );

  update public.pppp_outbound_queue_v1 q
     set status='suppressed',suppression_reason='domain_cooldown_'||v_policy.domain_cooldown_days::text||'d',updated_at=now()
   where q.status='candidate'
     and q.company_domain is not null
     and exists (
       select 1 from public.pppp_outbound_queue_v1 h
       where h.id<>q.id and h.sent_at is not null and h.company_domain is not null
         and lower(h.company_domain)=lower(q.company_domain)
         and h.sent_at >= now() - make_interval(days=>v_policy.domain_cooldown_days)
         and not (h.source=q.source and h.source_record_id=q.source_record_id)
     );

  -- Shared-boundary canonical GC safety: never revive historical/review-only GC rows.
  update public.pppp_outbound_queue_v1 q
     set status='stale',
         suppression_reason=case
           when p.status='already_contacted' then 'historical_already_contacted'
           else 'canonical_gc_not_sendable'
         end,
         planned_date=null,planned_at=null,planned_rank=null,
         approved_for_send=false,
         dispatch_claim_token=null,dispatch_claimed_at=null,
         updated_at=now()
    from public.pppp_gc_prospects_v1 p
   where q.source='GC'
     and q.source_record_id=p.id
     and q.sent_at is null
     and (
       coalesce(p.no_more_auto,false)
       or p.status in ('already_contacted','human_review','bounced','replied','do_not_contact')
     );

  select count(*) into v_suppressed from public.pppp_outbound_queue_v1 where status='suppressed';

  return jsonb_build_object(
    'ok',true,'ted_upserted',v_ted,'gc_touch1_upserted',v_gc1,'gc_touch2_upserted',v_gc2,
    'suppressed_total',v_suppressed,'send_enabled',v_policy.send_enabled,
    'human_send_required',true,'daily_limit',v_policy.daily_limit
  );
end;
$_$;


ALTER FUNCTION public.pppp_outbound_sync_v1() OWNER TO postgres;

--
-- Name: pppp_outreach_contact_score_v2(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outreach_contact_score_v2(p_email text, p_name text DEFAULT NULL::text, p_role text DEFAULT NULL::text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case public.pppp_outreach_contact_tier_v2(p_email, p_name, p_role)
    when 'A' then 95 when 'B' then 82 when 'C' then 70
    when 'D' then 55 when 'E' then 25 else 0 end;
$$;


ALTER FUNCTION public.pppp_outreach_contact_score_v2(p_email text, p_name text, p_role text) OWNER TO postgres;

--
-- Name: pppp_outreach_contact_tier_v2(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outreach_contact_tier_v2(p_email text, p_name text DEFAULT NULL::text, p_role text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  with x as (
    select
      lower(coalesce(p_email,'')) as email,
      lower(split_part(coalesce(p_email,''),'@',1)) as local_part,
      lower(coalesce(p_name,'')) as person_name,
      lower(coalesce(p_role,'')) as role_name
  )
  select case
    when email='' or email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then 'F'
    when split_part(email,'@',2) in (
      'gmail.com','googlemail.com','hotmail.com','outlook.com','live.com',
      'yahoo.com','yahoo.de','yahoo.fr','icloud.com','aol.com',
      'gmx.com','gmx.de','web.de','proton.me','protonmail.com',
      'abv.bg','example.com','example.org','example.net'
    ) then 'F'
    when local_part ~ '(marketing|press|presse|media|meedia|news|newsletter|career|karriere|jobs?|recruit|human.?resources|^hr$|privacy|datenschutz|gdpr|rodo|dpo|legal|invoice|rechnung|faktur|contabil|account|payable|support|webmaster|abuse|security|investor|noreply|no-reply|donotreply|geschichte|exporeal)'
      or role_name ~ '(marketing|press|presse|media|career|karriere|recruit|human resources|personalwesen|^hr$|privacy|datenschutz|accounting|finance|buchhaltung)'
      then 'F'
    when local_part ~ '(einkauf|procurement|purchas|sourcing|beschaffung|ausschreibung|tender|vergabe|przetarg|poptav|nabidk|compras|achats|acquisti)' then 'C'
    when local_part ~ '^(info|office|contact|kontakt|hello|mail|admin|sekretariat|zentrale|general|firmapost)$' then 'E'
    when person_name<>'' and role_name ~ '(einkauf|procurement|purchas|sourcing|beschaffung|material|supply|buyer|tender|vergabe)' then 'A'
    when person_name<>'' and role_name ~ '(project|projekt|technical|technik|commercial|kaufm|construction|bauleit|geschäfts|manag|director|leiter|engineering|production|fertigung)' then 'B'
    when person_name<>'' or local_part ~ '^[[:alpha:]]+[._-][[:alpha:]]+$' then 'D'
    else 'E'
  end
  from x
$_$;


ALTER FUNCTION public.pppp_outreach_contact_tier_v2(p_email text, p_name text, p_role text) OWNER TO postgres;

--
-- Name: pppp_outreach_readiness_v2(integer, integer, integer, integer, integer, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outreach_readiness_v2(p_company_fit integer, p_timing integer, p_contact_quality integer, p_message_evidence integer, p_fact_count integer DEFAULT 0, p_previous_contact boolean DEFAULT false, p_cooldown_until timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with s as (
    select
      greatest(0, least(100, coalesce(p_company_fit, 0))) company_fit,
      greatest(0, least(100, coalesce(p_timing, 0))) timing,
      greatest(0, least(100, coalesce(p_contact_quality, 0))) contact_quality,
      greatest(0, least(100, coalesce(p_message_evidence, 0))) message_evidence,
      greatest(0, coalesce(p_fact_count, 0)) fact_count
  ), r as (
    select *, round(company_fit * .32 + timing * .24 + contact_quality * .28 + message_evidence * .16)::integer as score,
      array_remove(array[
        case when company_fit < 65 then 'company_fit_below_65' end,
        case when contact_quality < 50 then 'contact_quality_below_50' end,
        case when message_evidence < 60 then 'message_evidence_below_60' end,
        case when fact_count < 2 then 'fewer_than_two_specific_facts' end,
        case when timing < 35 then 'commercial_timing_below_35' end,
        case when p_previous_contact then 'previous_contact_requires_thread_review' end,
        case when p_cooldown_until > now() then 'cooldown_active' end
      ], null) reasons
    from s
  )
  select jsonb_build_object(
    'score', score,
    'ready', cardinality(reasons) = 0,
    'state', case
      when p_previous_contact then 'thread_review'
      when p_cooldown_until > now() then 'cooldown'
      when company_fit >= 65 and contact_quality < 50 then 'strong_company_contact_gap'
      when cardinality(reasons) = 0 then 'ready_for_outreach'
      when company_fit < 65 then 'disqualified'
      else 'research_required'
    end,
    'reasons', to_jsonb(reasons),
    'weights', jsonb_build_object('company_fit', 32, 'commercial_timing', 24, 'contact_quality', 28, 'message_evidence', 16),
    'human_send_required', true
  ) from r;
$$;


ALTER FUNCTION public.pppp_outreach_readiness_v2(p_company_fit integer, p_timing integer, p_contact_quality integer, p_message_evidence integer, p_fact_count integer, p_previous_contact boolean, p_cooldown_until timestamp with time zone) OWNER TO postgres;

--
-- Name: pppp_outreach_reply_classification_v2(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_outreach_reply_classification_v2(p_subject text, p_snippet text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with x as (select lower(coalesce(p_subject, '') || ' ' || coalesce(p_snippet, '')) body), c as (
    select case
      when body ~ '(unsubscribe|abbestellen|keine weiteren|do not contact)' then 'opt_out'
      when body ~ '(falsche person|wrong person|nicht zuständig)' and body ~ '(kolleg|contact|zuständig|weitergeleitet|forward)' then 'referral'
      when body ~ '(angebot|quotation|quote|rfq|anfrage|ausschreibung|stückliste|bom)' then 'rfq_received'
      when body ~ '(interess|future|zukünftig|lieferantenliste|supplier list|qualif)' then 'future_interest'
      when body ~ '(bereits vergeben|already awarded|schon vergeben|verhandlungen|negotiations)' then 'project_already_covered'
      when body ~ '(kein interesse|not interested|no interest)' then 'not_interested'
      when body ~ '(termin|meeting|teams|call|telefon)' then 'meeting_requested'
      else 'needs_human_review'
    end as category, body from x
  )
  select jsonb_build_object(
    'category', category,
    'evidence', jsonb_build_object('subject', left(coalesce(p_subject, ''), 180), 'snippet', left(coalesce(p_snippet, ''), 320)),
    'human_review_required', true
  ) from c;
$$;


ALTER FUNCTION public.pppp_outreach_reply_classification_v2(p_subject text, p_snippet text) OWNER TO postgres;

--
-- Name: pppp_parse_expense_receipt_text_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_parse_expense_receipt_text_v1(p_text text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  t text:=coalesce(p_text,''); l text:=lower(coalesce(p_text,''));
  m text[]; v_date date; v_supplier text; v_invoice text; v_cat text:='tjera'; v_currency text:='EUR';
  v_total numeric; v_net numeric; v_vat numeric; v_rate numeric; v_qty numeric; v_unit_price numeric;
  v_conf integer:=0; v_review text[]:=array[]::text[];
begin
  m:=regexp_match(t,'([0-3]?[0-9])[./-]([01]?[0-9])[./-](20[0-9]{2})');
  if m is not null then begin v_date:=make_date(m[3]::int,m[2]::int,m[1]::int); exception when others then v_date:=null; end; end if;
  if v_date is null then
    m:=regexp_match(t,'(20[0-9]{2})[./-]([01]?[0-9])[./-]([0-3]?[0-9])');
    if m is not null then begin v_date:=make_date(m[1]::int,m[2]::int,m[3]::int); exception when others then v_date:=null; end; end if;
  end if;

  m:=regexp_match(t,'(?i)(?:grand[[:space:]]+total|total|totali|gesamt|summe|ukupno|za[[:space:]]+platiti|p[eë]r[[:space:]]+pages[eë])[^0-9]{0,24}([0-9][0-9 .]*[,.][0-9]{2})');
  if m is not null then v_total:=public.pppp_receipt_money_v1(m[1]); end if;
  if v_total is null then
    select max(public.pppp_receipt_money_v1(x[1])) into v_total
    from regexp_matches(t,'([0-9][0-9 .]*[,.][0-9]{2})','g') x;
  end if;

  m:=regexp_match(t,'(?i)(?:netto|neto|net|subtotal|osnovica|pa[[:space:]]+tvsh)[^0-9]{0,24}([0-9][0-9 .]*[,.][0-9]{2})');
  if m is not null then v_net:=public.pppp_receipt_money_v1(m[1]); end if;
  m:=regexp_match(t,'(?i)(?:tvsh|pdv|mwst|ust|vat)[^0-9]{0,32}([0-9][0-9 .]*[,.][0-9]{2})');
  if m is not null then v_vat:=public.pppp_receipt_money_v1(m[1]); end if;
  m:=regexp_match(t,'(?i)(?:tvsh|pdv|mwst|ust|vat)[^0-9%]{0,20}([0-9]{1,2}(?:[,.][0-9]+)?)[[:space:]]*%');
  if m is not null then v_rate:=public.pppp_receipt_money_v1(m[1]); end if;
  if v_net is null and v_total is not null and v_vat is not null and v_total>=v_vat then v_net:=v_total-v_vat; end if;
  if v_vat is null and v_total is not null and v_net is not null and v_total>=v_net then v_vat:=v_total-v_net; end if;

  m:=regexp_match(t,'(?i)(?:invoice|fatura|fatur[eë]|ra[cč]un|rechnung|beleg|receipt)[[:space:]#:.-]{0,12}([A-Z0-9][A-Z0-9/_-]{2,30})');
  if m is not null then v_invoice:=btrim(m[1]); end if;

  select btrim(x) into v_supplier
  from regexp_split_to_table(t,E'\n') x
  where length(btrim(x)) between 3 and 100
    and btrim(x) !~ '^[0-9[:space:][:punct:]]+$'
    and lower(btrim(x)) !~ '^(fiscal|fiskal|receipt|rechnung|invoice|fatura|racun|račun|total|totali|datum|date|tax|vat|tvsh|pdv|mwst)'
  limit 1;

  if l ~ '(diesel|benzin|benzine|petrol|fuel|gorivo|naft[eë]|eurodiesel|euro diesel)' then v_cat:='nafta';
  elsif l ~ '(restaurant|restoran|restorant|pizzeria|grill|cafe|coffee|ushqim|food)' then v_cat:='restorant';
  elsif l ~ '(hotel|motel|accommodation|unterkunft|smje[sš]taj)' then v_cat:='hotel';
  elsif l ~ '(parking|parkplatz|parkir)' then v_cat:='parking';
  elsif l ~ '(maut|toll|cestarina|autoput|autostrada)' then v_cat:='rruge';
  elsif l ~ '(telefon|mobile|telekom|internet)' then v_cat:='telefoni';
  elsif l ~ '(miete|qira|rent)' then v_cat:='qiraja';
  elsif l ~ '(strom|electric|rrym)' then v_cat:='rryma';
  elsif l ~ '(wasser|water|uji)' then v_cat:='uji'; end if;

  if l ~ '(chf)' then v_currency:='CHF'; elsif l ~ '(gbp|£)' then v_currency:='GBP'; elsif l ~ '(usd|\$)' then v_currency:='USD'; else v_currency:='EUR'; end if;

  if v_cat='nafta' then
    m:=regexp_match(l,'([0-9]+[,.][0-9]+)[[:space:]]*(?:l|ltr|liter|litre|litra)');
    if m is not null then v_qty:=public.pppp_receipt_money_v1(m[1]); end if;
    m:=regexp_match(l,'(?:price|preis|cijena|cena|cmim|çmim)[^0-9]{0,12}([0-9]+[,.][0-9]{2,3})');
    if m is not null then v_unit_price:=public.pppp_receipt_money_v1(m[1]); end if;
    if v_unit_price is null and v_qty is not null and v_qty>0 and v_total is not null then v_unit_price:=round(v_total/v_qty,3); end if;
  end if;

  if v_total is not null and v_total>0 then v_conf:=v_conf+30; else v_review:=array_append(v_review,'amount'); end if;
  if v_date is not null then v_conf:=v_conf+20; else v_review:=array_append(v_review,'date'); end if;
  if nullif(v_supplier,'') is not null then v_conf:=v_conf+20; else v_review:=array_append(v_review,'supplier'); end if;
  if nullif(v_invoice,'') is not null then v_conf:=v_conf+8; end if;
  if v_vat is not null or v_net is not null then v_conf:=v_conf+10; end if;
  if v_cat<>'tjera' then v_conf:=v_conf+12; else v_review:=array_append(v_review,'category'); end if;

  return jsonb_build_object(
    'supplier',v_supplier,'invoice_nr',v_invoice,'date',v_date,'category',v_cat,
    'amount',v_total,'net_amount',v_net,'vat_rate',v_rate,'vat_amount',v_vat,'currency',v_currency,
    'quantity',v_qty,'unit',case when v_qty is not null then 'L' else null end,'unit_price',v_unit_price,
    'confidence',least(100,v_conf),'review_fields',to_jsonb(v_review)
  );
end;$_$;


ALTER FUNCTION public.pppp_parse_expense_receipt_text_v1(p_text text) OWNER TO postgres;

--
-- Name: pppp_platform_snapshot_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_platform_snapshot_v1() RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
select jsonb_build_object(
  'generated_at', now(),
  'project_counts', jsonb_build_object(
    'total', (select count(*) from public.projects),
    'active', (select count(*) from public.projects where lower(coalesce(status,'')) not in ('mbyllur','humbur','arkivuar','closedlost','cancelled','canceled','realizuar','archived','lost')),
    'open_tasks', (select count(*) from public.tasks where lower(coalesce(status,'')) not in ('kryer','done','mbyllur')),
    'project_emails', (select count(*) from public.project_emails),
    'supplier_offers', (select count(*) from public.offers),
    'our_documents', (select count(*) from public.documents_registry)
  ),
  'active_projects', coalesce((
    select jsonb_agg(x order by (x->>'last_activity_at') desc nulls last)
    from (
      select jsonb_strip_nulls(jsonb_build_object(
        'id',p.id,
        'name',p.name,
        'client',p.client,
        'status',p.status,
        'pipeline_stage',p.pipeline_stage,
        'deadline',nullif(p.deadline,''),
        'last_activity_at',p.last_activity_at,
        'last_email_at',p.last_email_at,
        'latest_decision',(
          select pa.analysis->'recommendation'
          from public.project_analyses pa
          where pa.project_id=p.id::text and pa.status='complete'
          order by pa.created_at desc limit 1
        )
      )) x
      from public.projects p
      where lower(coalesce(p.status,'')) not in ('mbyllur','humbur','arkivuar','closedlost','cancelled','canceled','realizuar','archived','lost')
      order by coalesce(p.last_activity_at,p.updated_at,p.created_at) desc nulls last
      limit 30
    ) q
  ),'[]'::jsonb),
  'integrations', coalesce((select jsonb_agg(to_jsonb(i) order by i.integration_key) from public.pppp_platform_integrations i),'[]'::jsonb),
  'protected_rules', coalesce((select jsonb_agg(to_jsonb(r) order by r.rule_key) from public.pppp_platform_protected_rules r where r.active),'[]'::jsonb),
  'latest_changes', coalesce((select jsonb_agg(to_jsonb(c) order by c.occurred_at desc) from (select * from public.pppp_platform_changelog order by occurred_at desc limit 20) c),'[]'::jsonb),
  'critical_runtime_triggers', coalesce((
    select jsonb_agg(jsonb_build_object('table',c.relname,'trigger',t.tgname,'function',p.proname) order by c.relname,t.tgname)
    from pg_trigger t
    join pg_class c on c.oid=t.tgrelid
    join pg_namespace n on n.oid=c.relnamespace
    join pg_proc p on p.oid=t.tgfoid
    where n.nspname='public' and not t.tgisinternal and (t.tgname ilike 'trg_pppp%' or t.tgname ilike 'pppp_%')
  ),'[]'::jsonb)
);
$$;


ALTER FUNCTION public.pppp_platform_snapshot_v1() OWNER TO postgres;

--
-- Name: pppp_prevent_mature_stage_regression(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_prevent_mature_stage_regression() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if lower(coalesce(old.status,'')) in ('fituar','closedwon','realizuar')
     and new.pipeline_stage is distinct from old.pipeline_stage then
    new.pipeline_stage := old.pipeline_stage;
    return new;
  end if;

  if old.pipeline_stage in ('production_control','factory_audit','transport')
     and new.pipeline_stage in ('rfq_in','technical_review','supplier_selection','pricing','commercial','client_offer') then
    new.pipeline_stage := old.pipeline_stage;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_prevent_mature_stage_regression() OWNER TO postgres;

--
-- Name: pppp_pristeel_offer_model_v1(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_pristeel_offer_model_v1(p_channel text, p_company_type text DEFAULT NULL::text, p_outreach_motion text DEFAULT NULL::text, p_timing_classification text DEFAULT NULL::text, p_route text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when lower(coalesce(p_outreach_motion,''))='future_supplier_qualification'
      or lower(coalesce(p_timing_classification,''))='future_supplier_qualification'
      then 'future_supplier_qualification'
    when lower(coalesce(p_channel,'')) in ('material_trade','dach_steel_buyer','material_buyer')
      then 'material_supply'
    when upper(coalesce(p_route,''))='TED_PRODUCER'
      or lower(coalesce(p_company_type,'')) ~ '(steel.?fabricator|stahlbauer|producer|manufacturer|fabricator)'
      then 'external_production_capacity'
    when lower(coalesce(p_channel,'')) in ('gc','gc_gu','ted_awarded','awarded_project_gc')
      or upper(coalesce(p_route,'')) in ('TED_GC','TED_CONSORTIUM','TED_GENERAL')
      then 'fabricated_steel_package'
    else 'fabricated_steel_package'
  end;
$$;


ALTER FUNCTION public.pppp_pristeel_offer_model_v1(p_channel text, p_company_type text, p_outreach_motion text, p_timing_classification text, p_route text) OWNER TO postgres;

--
-- Name: pppp_procurement_comparison_reconcile_v1(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_procurement_comparison_reconcile_v1(p_apply boolean DEFAULT false, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  r record;
  v_limit integer:=least(500,greatest(1,coalesce(p_limit,100)));
  v_snapshot jsonb;
  v_analysis_id bigint;
  v_candidates integer:=0;
  v_tasks integer:=0;
  v_closed integer:=0;
  v_analyses integer:=0;
begin
  for r in
    with group_ready as (
      select c.project_id,c.pricing_basis,
             count(*) filter(where c.comparable)::int comparable_offers,
             min(c.comparison_value_eur) filter(where c.comparable) leader_value,
             (array_agg(c.supplier order by c.comparison_value_eur asc,c.created_at desc) filter(where c.comparable))[1] leader_supplier
      from public.pppp_supplier_offer_comparison_v1 c
      group by c.project_id,c.pricing_basis
      having count(*) filter(where c.comparable)>=2
    ), ranked as (
      select g.*,p.name,p.status,p.pipeline_stage,p.operational_state,
             row_number() over(partition by g.project_id order by g.comparable_offers desc,g.pricing_basis) rn
      from group_ready g
      join public.projects p on p.id=g.project_id
      where lower(coalesce(p.status,'')) not in ('humbur','lost','mbyllur','closed','arkivuar','archived','realizuar','cancelled','canceled')
        and p.pipeline_stage in ('rfq_in','technical_review','supplier_selection','pricing')
        and coalesce(p.operational_state,'') not in ('wait_for_client','execution')
        and not exists(select 1 from public.project_supplier_decisions d where d.project_id=p.id and d.status='active')
    )
    select * from ranked where rn=1
    order by comparable_offers desc,name
    limit v_limit
  loop
    v_candidates:=v_candidates+1;
    if not p_apply then continue; end if;

    v_snapshot:=public.pppp_supplier_offer_comparison_json_v1(r.project_id);
    select id into v_analysis_id
    from public.project_analyses
    where project_id=r.project_id::text and model='supplier-comparison-v1'
    order by created_at desc limit 1;

    if v_analysis_id is null then
      insert into public.project_analyses(project_id,status,engine,model,analysis,source_manifest,source_counts,created_at)
      values(
        r.project_id::text,'complete','procurement_rules','supplier-comparison-v1',v_snapshot,
        jsonb_build_object('source','canonical_offers','project_id',r.project_id),
        jsonb_build_object('offers',(select count(*) from public.offers o where o.project_id=r.project_id)),now()
      );
    else
      update public.project_analyses
         set status='complete',engine='procurement_rules',analysis=v_snapshot,
             source_manifest=jsonb_build_object('source','canonical_offers','project_id',r.project_id),
             source_counts=jsonb_build_object('offers',(select count(*) from public.offers o where o.project_id=r.project_id)),
             created_at=now()
       where id=v_analysis_id;
    end if;
    v_analyses:=v_analyses+1;

    insert into public.tasks(project_id,title,detail,due_date,priority,status,source,category,source_ref)
    values(
      r.project_id,
      'Zgjedh furnitorin · '||left(r.name,160),
      r.comparable_offers::text||' oferta janë të krahasueshme në bazën '||upper(r.pricing_basis)||'. Price leader: '||
      coalesce(r.leader_supplier,'—')||' · '||coalesce(round(r.leader_value,4)::text,'—')||' EUR/'||upper(r.pricing_basis)||
      E'.\nKy është vetëm sinjal krahasimi, jo zgjedhje automatike. Verifiko scope-in, sasinë/bazën e çmimit, delivery, Incoterms, payment terms, certifikatat dhe validitetin; pastaj regjistro supplier/pricing-basis decision me evidencë njerëzore.',
      current_date,'larte','hapur','procurement_comparison_auto','furnitor','PROCUREMENT:'||r.project_id::text||':supplier-comparison'
    )
    on conflict(source,source_ref) do update
      set project_id=excluded.project_id,title=excluded.title,detail=excluded.detail,due_date=current_date,
          priority='larte',status='hapur',done_at=null;
    v_tasks:=v_tasks+1;

    update public.projects
       set pipeline_stage=case when pipeline_stage in ('rfq_in','technical_review') then 'supplier_selection' else pipeline_stage end,
           updated_at=now()
     where id=r.project_id;
  end loop;

  if p_apply then
    with closed as (
      update public.tasks t
         set status='mbyllur',done_at=coalesce(done_at,now())
       where t.source='procurement_comparison_auto'
         and t.status='hapur'
         and (
           exists(select 1 from public.project_supplier_decisions d where d.project_id=t.project_id and d.status='active')
           or exists(select 1 from public.projects p where p.id=t.project_id and (p.pipeline_stage not in ('rfq_in','technical_review','supplier_selection','pricing') or coalesce(p.operational_state,'') in ('wait_for_client','execution') or lower(coalesce(p.status,'')) in ('humbur','lost','mbyllur','closed','arkivuar','archived','realizuar','cancelled','canceled')))
         )
      returning id
    ) select count(*) into v_closed from closed;
  end if;

  return jsonb_build_object(
    'mode',case when p_apply then 'apply' else 'preview' end,
    'comparison_ready_projects',v_candidates,'tasks_opened_or_refreshed',v_tasks,
    'tasks_closed',v_closed,'analyses_refreshed',v_analyses,'generated_at',now()
  );
end;
$$;


ALTER FUNCTION public.pppp_procurement_comparison_reconcile_v1(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_project_analysis_event_precedence_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_analysis_event_precedence_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_pid uuid;
  v_offer_sent_at timestamptz;
  v_offer_doc text;
  v_client_reply_at timestamptz;
  v_supplier_reply_at timestamptz;
  v_supplier_name text;
  v_stage text;
  v_deadline date;
  v_latest_doc text;
  v_latest_doc_created timestamptz;
  v_latest_doc_sent timestamptz;
  v_draft_pending boolean := false;
begin
  if coalesce(new.model,'') <> 'project-decision-snapshot-v1' then return new; end if;
  begin v_pid := new.project_id::uuid; exception when others then return new; end;

  select pipeline_stage,nullif(deadline,'')::date into v_stage,v_deadline from public.projects where id=v_pid;

  select d.doc_nr,d.created_at,
         coalesce((d.offer_state->>'installation_price_pending')::boolean,false)
         or (d.revenue_breakdown ? 'installation' and d.revenue_breakdown->'installation'='null'::jsonb)
    into v_latest_doc,v_latest_doc_created,v_draft_pending
  from public.documents_registry d
  where d.project_id=v_pid and d.series='QUO'
  order by d.created_at desc limit 1;

  if v_latest_doc is not null then
    select max(e.sent_at) into v_latest_doc_sent
    from public.project_emails e
    where e.project_id=v_pid and lower(coalesce(e.direction,''))='outgoing'
      and lower(coalesce(e.subject,'')||' '||coalesce(e.snippet,'')) like '%'||lower(v_latest_doc)||'%';
  end if;

  select e.sent_at,d.doc_nr into v_offer_sent_at,v_offer_doc
  from public.documents_registry d
  join public.project_emails e on e.project_id=d.project_id and lower(coalesce(e.direction,''))='outgoing'
   and lower(coalesce(e.subject,'')||' '||coalesce(e.snippet,'')) like '%'||lower(d.doc_nr)||'%'
  where d.project_id=v_pid and d.series='QUO'
  order by e.sent_at desc,d.created_at desc limit 1;

  if v_latest_doc is not null and v_latest_doc_sent is null and not v_draft_pending then
    new.analysis := coalesce(new.analysis,'{}'::jsonb) || jsonb_build_object(
      'executive_summary','Oferta '||v_latest_doc||' është ruajtur dhe pret kontrollin/dërgimin te klienti.',
      'current_stage','client_offer',
      'health',jsonb_build_object('label','ofertë gati për dërgim','score',91,'reason','Drafti i ofertës ekziston, por nuk ka provë të dërgimit.'),
      'recommendation',jsonb_build_object('decision','review_and_send_offer','label','Kontrollo dhe dërgo ofertën '||v_latest_doc,'reason','Oferta është ruajtur në PPPP dhe nuk rezulton e dërguar.','source_ids',jsonb_build_array('DRAFT')),
      'next_actions',jsonb_build_array(jsonb_build_object('text','Kontrollo ofertën dhe përdor workflow-in PDF → Email → Gmail Draft.','owner','PRISTEEL','priority','critical','status','open','source_ids',jsonb_build_array('DRAFT')))
    );
    return new;
  end if;

  if v_offer_sent_at is not null then
    select max(e.sent_at) into v_client_reply_at
    from public.project_emails e
    where e.project_id=v_pid and lower(coalesce(e.direction,''))='incoming' and e.sent_at>v_offer_sent_at
      and not exists (select 1 from public.rfq_log r where r.project_id=v_pid and lower(coalesce(r.supplier_email,''))=lower(coalesce(e.from_email,'')));
    if v_client_reply_at is null then
      new.analysis := coalesce(new.analysis,'{}'::jsonb) || jsonb_build_object(
        'executive_summary','Oferta '||coalesce(v_offer_doc,'PRISTEEL')||' është dërguar klientit. Projekti nuk kërkon veprim të ri derisa të vijë përgjigjja ose afati i follow-up-it.',
        'current_stage','client_offer',
        'health',jsonb_build_object('label','në pritje të klientit','score',94,'reason','Oferta jonë është dërguar dhe nuk ka përgjigje më të re nga klienti.'),
        'recommendation',jsonb_build_object('decision','wait_for_client','label','Në pritje të përgjigjes së klientit','reason','Oferta '||coalesce(v_offer_doc,'PRISTEEL')||' është dërguar; veprimet e vjetra të draftit/planit janë tejkaluar.','source_ids',jsonb_build_array('DRAFT')),
        'next_actions','[]'::jsonb,
        'missing_information',jsonb_build_array(jsonb_build_object('text','Përgjigjja ose konfirmimi i klientit','ask_to','client','priority','normal','why_needed','Për të vendosur hapin e ardhshëm komercial.'))
      );
      return new;
    end if;
  end if;

  select e.sent_at,coalesce(r.supplier_name,e.from_name,e.from_email) into v_supplier_reply_at,v_supplier_name
  from public.project_emails e join public.rfq_log r on r.project_id=v_pid and lower(coalesce(r.supplier_email,''))=lower(coalesce(e.from_email,'')) and r.sent_at is not null and r.sent_at <= coalesce(e.sent_at,e.created_at,now())
  where e.project_id=v_pid and lower(coalesce(e.direction,''))='incoming'
    and (coalesce(e.has_attachments,false) or lower(coalesce(e.subject,'')||' '||coalesce(e.snippet,'')) ~ '(ofert|ponud|quote|angebot|preis)')
  order by e.sent_at desc limit 1;

  if v_supplier_reply_at is not null and (v_offer_sent_at is null or v_supplier_reply_at>v_offer_sent_at) then
    new.analysis := coalesce(new.analysis,'{}'::jsonb) || jsonb_build_object(
      'executive_summary',coalesce(v_supplier_name,'Furnitori')||' ka dërguar ofertë/përgjigje të re. Projekti ka bazë për përgatitjen e ofertës PRISTEEL.',
      'current_stage','pricing','health',jsonb_build_object('label','gati për ofertim','score',92,'reason','Oferta e furnitorit është në dispozicion dhe nuk ka ofertë më të re PRISTEEL pas saj.'),
      'recommendation',jsonb_build_object('decision','prepare_client_offer','label','Përgatit ofertën PRISTEEL','reason',coalesce(v_supplier_name,'Furnitori')||' ka dërguar ofertë/përgjigje të re.','source_ids',jsonb_build_array('SUPPLIERS')),
      'next_actions',jsonb_build_array(jsonb_build_object('text','Përgatit ofertën PRISTEEL për klientin duke përdorur ofertën e furnitorit si bazë.','owner','PRISTEEL','priority','critical','status','open','source_ids',jsonb_build_array('SUPPLIERS')))
    );return new;
  end if;

  if v_stage='technical_review' and v_deadline is not null and v_deadline<=current_date+3 then
    new.analysis := coalesce(new.analysis,'{}'::jsonb) || jsonb_build_object(
      'executive_summary','Projekti është në verifikim teknik para ofertës. Afati është '||to_char(v_deadline,'DD.MM.YYYY')||' dhe çështjet teknike duhet të mbyllen para finalizimit komercial.',
      'current_stage','technical_review','health',jsonb_build_object('label','afat teknik aktiv','score',88,'reason','Afati i ofertës është afër dhe sqarimet teknike janë ende aktive.'),
      'recommendation',jsonb_build_object('decision','finish_technical_review','label','Finalizo çështjet teknike para ofertës','reason','Afati i ofertës është '||to_char(v_deadline,'DD.MM.YYYY')||'.','source_ids',jsonb_build_array('PROJECT')),
      'next_actions',jsonb_build_array(jsonb_build_object('text','Kontrollo kërkesat teknike të hapura dhe mbylli para ofertës.','owner','PRISTEEL','priority','critical','status','open','source_ids',jsonb_build_array('PROJECT')))
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_project_analysis_event_precedence_v1() OWNER TO postgres;

--
-- Name: pppp_project_analysis_operational_truth_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_analysis_operational_truth_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_state text;
  v_state_at timestamptz;
  v_state_source text;
  v_stage text;
  v_status text;
  v_terminal_label text;
  v_terminal_summary text;
begin
  if coalesce(new.model,'') <> 'project-decision-snapshot-v1' then return new; end if;

  select operational_state,operational_state_at,operational_state_source,pipeline_stage,status
    into v_state,v_state_at,v_state_source,v_stage,v_status
  from public.projects
  where id::text=new.project_id;

  if public.pppp_project_status_is_terminal_v1(v_status) then
    v_state:='closed';
    v_state_source:=case when coalesce(v_state_source,'') like 'terminal_status_%' then v_state_source else 'project_status_terminal_v1' end;
    if lower(coalesce(v_status,'')) in ('humbur','lost','cancelled','canceled','refuzuar','rejected','closedlost') then
      v_terminal_label:='opportunity e humbur';
      v_terminal_summary:='Kjo opportunity është e mbyllur si e humbur. PPPP nuk duhet ta trajtojë si projekt aktiv dhe nuk duhet të krijojë follow-up automatik për këtë opportunity.';
    elsif lower(coalesce(v_status,'')) in ('realizuar','completed','complete') then
      v_terminal_label:='projekt i realizuar';
      v_terminal_summary:='Ky projekt është shënuar i realizuar. Veprimet e fazës aktive nuk duhet të vazhdojnë.';
    elsif lower(coalesce(v_status,'')) in ('arkivuar','archived') then
      v_terminal_label:='projekt i arkivuar';
      v_terminal_summary:='Ky projekt është arkivuar dhe nuk duhet të shfaqet si aktiv.';
    else
      v_terminal_label:='projekt i mbyllur';
      v_terminal_summary:='Ky projekt është mbyllur dhe nuk duhet të shfaqet si aktiv.';
    end if;
    new.analysis := coalesce(new.analysis,'{}'::jsonb) || jsonb_build_object(
      'executive_summary',v_terminal_summary,
      'current_stage',coalesce(nullif(v_stage,''),'closed'),
      'health',jsonb_build_object('label',v_terminal_label,'score',100,'reason','Statusi terminal i konfirmuar i projektit ka përparësi ndaj pipeline-it, emailave dhe analizave të vjetra.'),
      'recommendation',jsonb_build_object('decision','terminal_no_active_followup','label','Mos e trajto si projekt aktiv','reason','PPPP po respekton statusin terminal ekzistues; ndryshimi won/lost mbetet vetëm me vendim njerëzor.','source_ids',jsonb_build_array('PROJECT_STATUS')),
      'next_actions','[]'::jsonb,
      'missing_information','[]'::jsonb,
      'operational_truth',jsonb_strip_nulls(jsonb_build_object('state','closed','at',v_state_at,'source',v_state_source,'terminal_status',v_status))
    );
    return new;
  end if;

  if coalesce(v_state,'')='wait_for_client' then
    new.analysis := coalesce(new.analysis,'{}'::jsonb) || jsonb_build_object(
      'executive_summary','Projekti është në pritje të palës tjetër. Nuk kërkohet veprim i ri derisa të vijë përgjigjja ose të aktivizohet follow-up-i.',
      'current_stage',coalesce(nullif(v_stage,''),'client_offer'),
      'health',jsonb_build_object('label','në pritje të klientit','score',96,'reason','Gjendja operative kanonike është wait_for_client.'),
      'recommendation',jsonb_build_object('decision','wait_for_client','label','Në pritje të përgjigjes së klientit','reason','Gjendja operative kanonike e projektit ka përparësi ndaj draft-eve ose task-eve më të vjetra.','source_ids',jsonb_build_array('OPERATIONAL_STATE')),
      'next_actions','[]'::jsonb,
      'missing_information',jsonb_build_array(jsonb_build_object('text','Përgjigjja ose konfirmimi i klientit','ask_to','client','priority','normal','why_needed','Për të vendosur hapin e ardhshëm.')),
      'operational_truth',jsonb_strip_nulls(jsonb_build_object('state',v_state,'at',v_state_at,'source',v_state_source))
    );
    return new;
  end if;

  if coalesce(v_state,'')='execution' then
    new.analysis := coalesce(new.analysis,'{}'::jsonb) || jsonb_build_object(
      'executive_summary','Projekti është në ekzekutim. Prioritetet operative vijnë nga prodhimi, dokumentacioni, dorëzimi dhe detyrat aktive të ekzekutimit.',
      'current_stage',coalesce(nullif(v_stage,''),'production_control'),
      'health',jsonb_build_object('label','në ekzekutim','score',96,'reason','Gjendja operative kanonike është execution.'),
      'recommendation',jsonb_build_object('decision','execution_active','label','Ndiq ekzekutimin e projektit','reason','Veprimet e fazës së ofertimit janë tejkaluar; ndiq vetëm detyrat aktive të ekzekutimit.','source_ids',jsonb_build_array('OPERATIONAL_STATE')),
      'next_actions','[]'::jsonb,
      'operational_truth',jsonb_strip_nulls(jsonb_build_object('state',v_state,'at',v_state_at,'source',v_state_source))
    );
    return new;
  end if;

  if coalesce(v_state,'')='action_required' and coalesce(v_state_source,'')='client_reply_auto' then
    new.analysis := coalesce(new.analysis,'{}'::jsonb) || jsonb_build_object(
      'executive_summary','Klienti ka dërguar përgjigje të re pas gjendjes së pritjes. Projekti kërkon rishikim dhe vendim të ri.',
      'current_stage',coalesce(nullif(v_stage,''),'client_offer'),
      'health',jsonb_build_object('label','përgjigje e re nga klienti','score',98,'reason','Gjendja operative u aktivizua nga një email i ri i klientit.'),
      'recommendation',jsonb_build_object('decision','review_client_reply','label','Shqyrto përgjigjen e klientit','reason','Emaili i ri i klientit ka përparësi ndaj gjendjes së mëparshme wait_for_client.','source_ids',jsonb_build_array('OPERATIONAL_STATE')),
      'next_actions',jsonb_build_array(jsonb_build_object('text','Hap komunikimin e projektit, shqyrto përgjigjen dhe vendos hapin e ardhshëm.','owner','PRISTEEL','priority','critical','status','open','source_ids',jsonb_build_array('OPERATIONAL_STATE'))),
      'operational_truth',jsonb_strip_nulls(jsonb_build_object('state',v_state,'at',v_state_at,'source',v_state_source))
    );
    return new;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_project_analysis_operational_truth_v1() OWNER TO postgres;

--
-- Name: pppp_project_brief_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_brief_v1(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
select jsonb_build_object(
  'project',(select to_jsonb(p) from (
    select id,name,client,ref,business_ref,status,pipeline_stage,operational_state,
           origin_type,work_model,last_activity_at,last_email_at,updated_at
    from public.projects where id=p_project_id
  ) p),
  'open_tasks',coalesce((
    select jsonb_agg(to_jsonb(t) order by t.due_date asc nulls last,t.created_at desc)
    from (
      select id,title,left(coalesce(detail,''),1500) as detail,due_date,priority,status,source,category,contact_email,created_at
      from public.tasks x
      where x.project_id=p_project_id and x.status not in ('kryer','mbyllur','done','closed')
        and not (
          x.source='project_decision_auto'
          and exists (
            select 1 from public.tasks sw
            where sw.project_id=p_project_id and sw.source='supplier_wait_auto'
              and sw.status not in ('kryer','mbyllur','done','closed')
          )
        )
      order by due_date asc nulls last,created_at desc limit 10
    ) t
  ),'[]'::jsonb),
  'recent_emails',coalesce((
    select jsonb_agg(to_jsonb(e) order by e.sent_at desc)
    from (
      select gmail_message_id,gmail_thread_id,from_email,from_name,to_emails,cc_emails,subject,
             left(coalesce(snippet,''),2500) as snippet,sent_at,direction,has_attachments,gmail_url
      from public.project_emails
      where project_id=p_project_id
      order by sent_at desc limit 8
    ) e
  ),'[]'::jsonb),
  'contacts',coalesce((
    select jsonb_agg(to_jsonb(c) order by c.is_primary desc nulls last,c.email_count desc nulls last,c.last_seen desc nulls last)
    from (
      select id,name,email,company,role,source,is_primary,status,email_count,direct_count,cc_count,last_seen
      from public.project_contacts
      where project_id=p_project_id::text and coalesce(status,'active')<>'archived'
      order by is_primary desc nulls last,email_count desc nulls last,last_seen desc nulls last limit 15
    ) c
  ),'[]'::jsonb),
  'supplier_offers',coalesce((
    select jsonb_agg(to_jsonb(o) order by o.created_at desc)
    from (
      select id,supplier,offer_ref,currency,total_amount,total_eur,price_kg,qty_kg,delivery_weeks,
             incoterms,payment_terms,validity_days,left(coalesce(notes,''),1200) as notes,created_at
      from public.offers
      where project_id=p_project_id
        and coalesce(supplier,'') !~* '(oferta jone|our offer|pristeel)'
      order by created_at desc limit 12
    ) o
  ),'[]'::jsonb),
  'registered_client_offers',coalesce((
    select jsonb_agg(to_jsonb(q) order by q.created_at desc)
    from (
      select id,doc_nr,client,currency,total_amount,total_eur,followup_status,last_followup_at,followup_count,created_at
      from public.documents_registry
      where project_id=p_project_id and upper(coalesce(series,''))='QUO'
      order by created_at desc limit 12
    ) q
  ),'[]'::jsonb),
  'sent_client_offer_emails',coalesce((
    select jsonb_agg(jsonb_build_object(
      'gmail_message_id',e.gmail_message_id,
      'subject',e.subject,
      'sent_at',e.sent_at,
      'to_emails',to_jsonb(e.to_emails),
      'gmail_url',e.gmail_url,
      'attachments',coalesce((
        select jsonb_agg(jsonb_build_object(
          'id',a.id,'name',a.attachment_name,'mime_type',a.attachment_mime_type,
          'size_bytes',a.attachment_size_bytes,'analysis_status',a.analysis_status,
          'drive_file_id',a.drive_file_id,'storage_backend',a.storage_backend
        ) order by a.id)
        from public.project_attachment_links a
        where a.project_id=p_project_id::text and a.gmail_message_id=e.gmail_message_id
          and coalesce(a.attachment_name,'') ~* '\.pdf$'
      ),'[]'::jsonb)
    ) order by e.sent_at desc)
    from (
      select gmail_message_id,subject,sent_at,to_emails,gmail_url
      from public.project_emails
      where project_id=p_project_id and direction='outgoing'
        and coalesce(subject,'') ~* '(angebot|offert|offer|quotation|ponuda)'
      order by sent_at desc limit 8
    ) e
  ),'[]'::jsonb),
  'document_status',jsonb_build_object(
    'linked_attachments',(select count(*) from public.project_attachment_links a where a.project_id=p_project_id::text),
    'analyzed_attachments',(select count(*) from public.project_attachment_links a where a.project_id=p_project_id::text and a.analysis_status='complete'),
    'pending_attachments',(select count(*) from public.project_attachment_links a where a.project_id=p_project_id::text and coalesce(a.analysis_status,'pending') in ('pending','queued','processing'))
  ),
  'latest_analysis',(
    select jsonb_build_object(
      'executive_summary',left(coalesce(a.analysis->>'executive_summary',''),3000),
      'current_stage',a.analysis->'current_stage','health',a.analysis->'health',
      'recommendation',a.analysis->'recommendation','next_actions',coalesce(a.analysis->'next_actions','[]'::jsonb),
      'risks',coalesce(a.analysis->'risks','[]'::jsonb),'missing_information',coalesce(a.analysis->'missing_information','[]'::jsonb),
      'created_at',a.created_at,'model',a.model
    )
    from public.project_analyses a
    where a.project_id=p_project_id::text
      and a.status='complete'
      and nullif(btrim(coalesce(a.analysis->>'executive_summary','')),'') is not null
      and a.created_at >= coalesce(
        (select p.operational_state_at from public.projects p where p.id=p_project_id),
        '-infinity'::timestamptz
      )
    order by a.created_at desc limit 1
  )
);
$_$;


ALTER FUNCTION public.pppp_project_brief_v1(p_project_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION pppp_project_brief_v1(p_project_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_project_brief_v1(p_project_id uuid) IS 'PPPP project brief read model. latest_analysis is state-safe: summarized complete analyses only, never older than current operational_state_at.';


--
-- Name: pppp_project_contact_party_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_contact_party_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_kind text;
  v_company text;
begin
  if lower(coalesce(new.source,'')) not in ('gmail','email-auto') then return new; end if;
  if nullif(trim(coalesce(new.email,'')),'') is null then return new; end if;

  select c.kind,c.company into v_kind,v_company
  from public.contacts c
  where lower(trim(coalesce(c.email,'')))=lower(trim(new.email))
  order by (c.hubspot_id is not null) desc,c.created_at asc nulls last
  limit 1;

  if lower(coalesce(v_kind,''))='supplier' then
    new.role := 'supplier';
    if nullif(trim(coalesce(v_company,'')),'') is not null then new.company := v_company; end if;
  elsif lower(coalesce(v_kind,''))='client' and lower(coalesce(new.role,''))='supplier' then
    new.role := 'client';
    if nullif(trim(coalesce(v_company,'')),'') is not null then new.company := v_company; end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_project_contact_party_guard_v1() OWNER TO postgres;

--
-- Name: pppp_project_contact_system_mail_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_contact_system_mail_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_email text;
begin
  v_email := lower(trim(coalesce(new.email,'')));
  if v_email='' then return new; end if;
  if split_part(v_email,'@',2) = 'prissteel.com'
     or split_part(v_email,'@',2) like '%.prissteel.com'
     or v_email in ('arianitti@me.com','arianit.vllahiu@gmail.com')
     or split_part(v_email,'@',1) ~* '(^|[+._-])(no-?reply|do-?not-?reply|mailer-daemon|postmaster|notifications?|dmarc)([+._-]|$)'
  then
    return null;
  end if;
  return new;
end;
$_$;


ALTER FUNCTION public.pppp_project_contact_system_mail_guard_v1() OWNER TO postgres;

--
-- Name: pppp_project_contact_unique_autolink_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_contact_unique_autolink_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_project uuid;
  v_count integer := 0;
begin
  if new.project_id is not null then
    return new;
  end if;

  -- Explicitly detached historical rows must stay detached. A generic contact
  -- must never re-attach them during an UPDATE.
  if coalesce(new.match_method,'') like 'project-contact-unique-detached%' then
    return new;
  end if;

  with candidates as (
    select distinct p.id
    from public.project_contacts pc
    join public.projects p on p.id::text = pc.project_id
    where lower(coalesce(pc.status,'active'))='active'
      and lower(coalesce(p.status,'')) not in ('humbur','lost','arkivuar','archived','mbyllur','closed','closedlost','cancelled','canceled','realizuar')
      and (
        (lower(coalesce(new.direction,''))='incoming' and lower(coalesce(pc.email,''))=lower(coalesce(new.from_email,'')))
        or
        (lower(coalesce(new.direction,''))='outgoing' and exists(
          select 1 from unnest(coalesce(new.to_emails,'{}'::text[])) x
          where lower(x)=lower(coalesce(pc.email,''))
        ))
      )
  ), picked as (
    select count(*)::int cnt,(array_agg(id))[1] project_id from candidates
  )
  select cnt,project_id into v_count,v_project from picked;

  if v_count=1 and v_project is not null then
    -- Contact uniqueness is useful context, but it is not project identity.
    -- Keep it as a suggestion and require stronger identity evidence or a human review.
    new.suggested_project_id := coalesce(new.suggested_project_id,v_project);
    if new.suggested_project_id = v_project
       and (coalesce(new.match_method,'')='' or new.match_method like 'project-contact-unique%') then
      new.match_method := 'project-contact-unique-suggest-v2';
      new.match_confidence := greatest(coalesce(new.match_confidence,0),80);
      new.needs_review := true;
      new.review_reason := coalesce(
        nullif(new.review_reason,''),
        'Unique project contact is suggestion-only; confirm project identity from subject, content, RFQ, or explicit project evidence.'
      );
      new.updated_at := now();
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_project_contact_unique_autolink_v1() OWNER TO postgres;

