--
-- Name: pppp_project_delivery_date_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_delivery_date_v1(p_project_id uuid) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
  with highlights as (
    select h.value as item
    from public.pppp_project_context_current_v c
    cross join lateral jsonb_array_elements(coalesce(c.value->'highlights','[]'::jsonb)) h
    where c.project_id=p_project_id
      and c.category='execution_schedule'
      and lower(coalesce(h.value->>'label','')) ~ '(transport|delivery|liefer|isporuk|dostav)'
  ), parsed as (
    select case
      when coalesce(item->>'start','') ~ '^\d{2}/\d{2}/\d{2}$' then to_date(item->>'start','DD/MM/YY')
      when coalesce(item->>'start','') ~ '^\d{2}/\d{2}/\d{4}$' then to_date(item->>'start','DD/MM/YYYY')
      when coalesce(item->>'start','') ~ '^\d{4}-\d{2}-\d{2}' then substring(item->>'start' from 1 for 10)::date
      else null::date
    end as delivery_date
    from highlights
  )
  select min(delivery_date) from parsed where delivery_date is not null;
$_$;


ALTER FUNCTION public.pppp_project_delivery_date_v1(p_project_id uuid) OWNER TO postgres;

--
-- Name: pppp_project_discovery_triage_v1(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_discovery_triage_v1(p_apply boolean DEFAULT false, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := least(500, greatest(1, coalesce(p_limit,100)));
  v_candidates integer := 0;
  v_created integer := 0;
begin
  select count(*) into v_candidates
  from (
    select 1
    from public.project_discovery_candidates c
    where c.status='open'
      and c.match_project_id is null
      and coalesce(c.score,0) >= 96
      and coalesce(c.last_seen_at,c.updated_at,c.discovered_at) >= now()-interval '30 days'
    order by c.score desc, c.last_seen_at desc nulls last
    limit v_limit
  ) x;

  if not p_apply then
    return jsonb_build_object(
      'mode','preview',
      'high_confidence_new',v_candidates,
      'created_tasks',0,
      'generated_at',now()
    );
  end if;

  with candidates as (
    select c.*
    from public.project_discovery_candidates c
    where c.status='open'
      and c.match_project_id is null
      and coalesce(c.score,0) >= 96
      and coalesce(c.last_seen_at,c.updated_at,c.discovered_at) >= now()-interval '30 days'
    order by c.score desc, c.last_seen_at desc nulls last
    limit v_limit
  ), inserted as (
    insert into public.tasks(
      title,detail,due_date,priority,status,source,category,source_ref
    )
    select
      'New project candidate · '||left(coalesce(nullif(btrim(c.title),''),coalesce(nullif(btrim(c.client),''),'Unknown opportunity')),150),
      'Project Discovery found a high-confidence new opportunity from Gmail. '
      ||'Score: '||coalesce(c.score,0)::text||'. '
      ||'Client: '||coalesce(nullif(btrim(c.client),''),'—')||'. '
      ||'Reference: '||coalesce(nullif(btrim(c.project_ref),''),'—')||'. '
      ||'Domain: '||coalesce(nullif(btrim(c.domain),''),'—')||'. '
      ||'Review the evidence and decide whether to create a canonical PPPP project. No project was created and no communication was sent automatically.',
      current_date,
      'larte',
      'hapur',
      'project_discovery_review',
      'intern',
      'DISCOVERY:new:'||c.candidate_key
    from candidates c
    on conflict(source,source_ref) do nothing
    returning 1
  )
  select count(*) into v_created from inserted;

  return jsonb_build_object(
    'mode','apply',
    'high_confidence_new',v_candidates,
    'created_tasks',v_created,
    'generated_at',now()
  );
end;
$$;


ALTER FUNCTION public.pppp_project_discovery_triage_v1(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_project_email_current_state_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_email_current_state_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_at timestamptz:=coalesce(new.sent_at,new.created_at,now());
  v_text text:=lower(coalesce(new.subject,'')||' '||coalesce(new.snippet,''));
  v_sender_role text:='unknown';
  v_supplier boolean:=false;
  v_client_recipient boolean:=false;
  v_doc_nr text;
  v_match text[];
  v_project_status text;
begin
  if new.project_id is null then return new; end if;
  if new.sent_at is not null and new.sent_at > now() + interval '5 minutes' then return new; end if;

  select status into v_project_status from public.projects where id=new.project_id;
  if public.pppp_project_status_is_terminal_v1(v_project_status) then
    update public.projects set operational_state='closed',operational_state_at=coalesce(operational_state_at,v_at),operational_state_source='terminal_status_guard_v1',updated_at=now()
     where id=new.project_id and (coalesce(operational_state,'')<>'closed' or coalesce(operational_state_source,'') not in ('terminal_status_guard_v1','terminal_status_reconcile_v1'));
    return new;
  end if;

  if lower(coalesce(new.direction,''))='incoming'
     and public.pppp_email_is_automatic_reply_v1(new.subject,new.snippet,new.from_email) then
    return new;
  end if;

  v_sender_role:=public.pppp_project_email_party_role_v1(new.project_id,new.from_email);
  v_supplier:=v_sender_role='supplier';
  v_client_recipient:=public.pppp_project_email_has_client_recipient_v1(new.project_id,new.to_emails);
  if lower(coalesce(new.direction,''))='incoming' and not v_supplier and v_sender_role<>'internal' then
    update public.projects set operational_state=case when coalesce(operational_state,'')='execution' then operational_state else 'action_required' end,
      operational_state_at=case when coalesce(operational_state,'')='execution' then operational_state_at else v_at end,
      operational_state_source=case when coalesce(operational_state,'')='execution' then operational_state_source else 'client_email_event_auto_v1' end,updated_at=now()
     where id=new.project_id and v_at>coalesce(operational_state_at,'1970-01-01'::timestamptz);
  elsif lower(coalesce(new.direction,''))='outgoing' and v_client_recipient then
    update public.projects set operational_state=case when coalesce(operational_state,'')='execution' then operational_state else 'wait_for_client' end,
      operational_state_at=case when coalesce(operational_state,'')='execution' then operational_state_at else v_at end,
      operational_state_source=case when coalesce(operational_state,'')='execution' then operational_state_source else 'client_reply_sent_auto_v1' end,updated_at=now()
     where id=new.project_id and v_at>=coalesce(operational_state_at,'1970-01-01'::timestamptz);
  end if;
  update public.tasks t set status='mbyllur',done_at=coalesce(t.done_at,now()),detail=case when position('PPPP: superseded by newer linked project email.' in coalesce(t.detail,''))>0 then t.detail else concat_ws(E'\n',nullif(t.detail,''),'PPPP: superseded by newer linked project email.') end
   where t.project_id=new.project_id and t.source='email_audit' and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed') and v_at>coalesce(t.created_at,'1970-01-01'::timestamptz);
  if lower(coalesce(new.direction,''))='outgoing' then
    v_match:=regexp_match(v_text,'(pst-(?:off|quo)-[0-9]{4}-[0-9]{2}-[0-9]{3})');
    if v_match is not null then
      v_doc_nr:=upper(v_match[1]);
      update public.tasks t set status='mbyllur',done_at=coalesce(t.done_at,now()),detail=case when position('PPPP: superseded by sent client offer '||v_doc_nr in coalesce(t.detail,''))>0 then t.detail else concat_ws(E'\n',nullif(t.detail,''),'PPPP: superseded by sent client offer '||v_doc_nr||' evidenced by linked outgoing Gmail.') end
       where t.project_id=new.project_id and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed') and t.created_at<=v_at and t.source in ('manual','project_decision_auto','email_request_auto','supplier_update_auto','dynamic_plan_auto','semantic_brain_auto') and lower(coalesce(t.title,'')||' '||coalesce(t.detail,'')) ~ '(ofert|offer|ponud|rfq|bom|finaliz|d[eë]rgo|komercial)';
      update public.documents_registry d set offer_state=coalesce(d.offer_state,'{}'::jsonb)||jsonb_build_object('pst_sent_at',v_at,'pst_document_status','sent') where d.project_id=new.project_id and d.series='QUO' and lower(coalesce(d.doc_nr,''))=lower(v_doc_nr);
    end if;
  end if;
  if lower(coalesce(new.direction,''))='incoming' and v_sender_role='client' and v_text ~ '(freigab.{0,140}(schwei|schweiß)|((schwei|schweiß).{0,140}freigab)|you can.{0,60}weld|can.{0,60}weld|mund.{0,80}(schwei|schweiß)|drit.{0,30}gjelber.{0,100}sald|saldim.{0,80}aprov)' then
    if not exists(select 1 from public.pppp_project_context_facts f where f.project_id=new.project_id and f.source_type='email' and f.source_ref=new.gmail_message_id and f.fact_key='email_event.execution_release') then
      insert into public.pppp_project_context_facts(project_id,category,subject,fact_key,value,source_type,source_ref,evidence_status,confidence,fact_status,idempotency_key,created_by)
      values(new.project_id,'execution','Execution release confirmed','email_event.execution_release',jsonb_build_object('summary','Klienti konfirmoi release-in për prodhim/saldim.','text',coalesce(new.snippet,new.subject)),'email',new.gmail_message_id,'confirmed',1,'observed','email-event:execution-release:'||new.gmail_message_id,'pppp_project_email_current_state_v1');
    end if;
    update public.projects set operational_state='execution',operational_state_at=v_at,operational_state_source='email_execution_release_auto_v1',updated_at=now() where id=new.project_id;
    update public.tasks set status='mbyllur',done_at=coalesce(done_at,now()),detail=concat_ws(E'\n',nullif(detail,''),'PPPP: release blocker superseded by confirmed client release email.') where project_id=new.project_id and source='execution_release_readiness' and lower(coalesce(status,'')) not in ('kryer','mbyllur','done','closed');
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_project_email_current_state_v1() OWNER TO postgres;

--
-- Name: pppp_project_email_event_engine_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_email_event_engine_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_text text; v_supplier text; v_rfq_id uuid; v_deadline text[]; v_deadline_date date; v_doc_nr text; v_doc_id uuid;
  v_offer_sent boolean := false; v_event boolean := false; v_is_supplier_sender boolean := false; v_sender_role text:='unknown';
begin
  if new.project_id is null then return new; end if;
  if new.sent_at is not null and new.sent_at > now() + interval '5 minutes' then return new; end if;
  v_text := lower(coalesce(new.subject,'') || ' ' || coalesce(new.snippet,''));

  if lower(coalesce(new.direction,''))='incoming'
     and public.pppp_email_is_automatic_reply_v1(new.subject,new.snippet,new.from_email) then
    return new;
  end if;

  if lower(coalesce(new.direction,''))='incoming' and coalesce(new.from_email,'')<>'' then
    v_sender_role:=public.pppp_project_email_party_role_v1(new.project_id,new.from_email);
    select r.id,r.supplier_name into v_rfq_id,v_supplier from public.rfq_log r
    where r.project_id=new.project_id
      and lower(coalesce(r.supplier_email,''))=lower(new.from_email)
      and lower(coalesce(r.status,'')) not in ('superseded','cancelled','canceled','closed','rejected')
      and r.sent_at is not null
      and r.sent_at <= coalesce(new.sent_at,new.created_at,now())
    order by r.sent_at desc nulls last,r.created_at desc limit 1;
    v_is_supplier_sender := v_sender_role='supplier';
    if v_rfq_id is not null and (v_text ~ '(ofert|ponud|quote|angebot|preis)' or coalesce(new.has_attachments,false)) then
      update public.rfq_log set status='replied',replied_at=coalesce(replied_at,new.sent_at,new.created_at,now()) where id=v_rfq_id;
      update public.projects set pipeline_stage=case when pipeline_stage in ('rfq_in','technical_review','supplier_selection') then 'pricing' else pipeline_stage end,updated_at=now() where id=new.project_id;
      v_event := true;
    end if;
    if not v_is_supplier_sender and v_sender_role<>'internal' then
      update public.projects set operational_state='action_required',operational_state_at=coalesce(new.sent_at,new.created_at,now()),operational_state_source='client_reply_auto',updated_at=now()
       where id=new.project_id and coalesce(operational_state,'')='wait_for_client' and coalesce(new.sent_at,new.created_at,now()) > coalesce(operational_state_at,'1970-01-01'::timestamptz);
      if found then v_event := true; end if;
    end if;
  end if;
  if lower(coalesce(new.direction,''))='outgoing' and v_text ~ 'pst-off-[0-9]{4}-[0-9]{2}-[0-9]{3}' then
    select d.id,d.doc_nr into v_doc_id,v_doc_nr from public.documents_registry d
    where d.project_id=new.project_id and d.series='QUO' and lower(coalesce(new.subject,'') || ' ' || coalesce(new.snippet,'')) like '%' || lower(d.doc_nr) || '%'
    order by d.created_at desc limit 1;
    v_offer_sent := v_doc_nr is not null;
    if v_offer_sent then
      update public.projects set pipeline_stage=case when pipeline_stage in ('rfq_in','technical_review','supplier_selection','pricing','commercial') then 'client_offer' else pipeline_stage end,
        operational_state=case when coalesce(operational_state,'')='execution' then operational_state else 'wait_for_client' end,
        operational_state_at=case when coalesce(operational_state,'')='execution' then operational_state_at else coalesce(new.sent_at,new.created_at,now()) end,
        operational_state_source=case when coalesce(operational_state,'')='execution' then operational_state_source else 'client_offer_sent_auto' end,updated_at=now() where id=new.project_id;
      update public.documents_registry set offer_state=coalesce(offer_state,'{}'::jsonb) || jsonb_build_object('pst_sent_at',coalesce(new.sent_at,new.created_at,now()),'pst_document_status','sent') where id=v_doc_id;
      v_deadline := regexp_match(coalesce(new.snippet,''),'(?i)(?:najkasnije[[:space:]]+do|zavr[sš]ene[^0-9]{0,40})([0-9]{1,2})[./-]([0-9]{1,2})[./-]([0-9]{4})');
      if v_deadline is not null then begin v_deadline_date := make_date(v_deadline[3]::int,v_deadline[2]::int,v_deadline[1]::int); update public.projects set deadline=v_deadline_date::text,updated_at=now() where id=new.project_id; exception when others then null; end; end if;
      update public.tasks set status='mbyllur',done_at=coalesce(done_at,now()),detail=concat_ws(E'\n',nullif(detail,''),'PPPP: veprimi u tejkalua nga oferta '||v_doc_nr||' e dërguar klientit.')
       where project_id=new.project_id and lower(coalesce(status,'')) not in ('kryer','done','mbyllur') and source in ('email_request_auto','supplier_update_auto','project_decision_auto','dynamic_plan_auto')
         and lower(coalesce(title,'') || ' ' || coalesce(detail,'')) ~ '(plan[[:space:]]*dinamik|dinamik|ponud|ofert|monta|plastifik|cij|cmim|price|rok[[:space:]]*realiz|rekapitul)' and coalesce(created_at,'-infinity'::timestamptz) <= coalesce(new.sent_at,new.created_at,now());
      v_event := true;
    end if;
  end if;
  if v_event then begin perform public.pppp_refresh_project_decision(new.project_id); exception when others then raise warning 'PPPP project decision refresh failed for %: %',new.project_id,sqlerrm; end; end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_project_email_event_engine_v1() OWNER TO postgres;

--
-- Name: pppp_project_email_has_client_recipient_v1(uuid, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_email_has_client_recipient_v1(p_project_id uuid, p_emails text[]) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(
    select 1
    from unnest(coalesce(p_emails,'{}'::text[])) x(email)
    where public.pppp_project_email_party_role_v1(p_project_id,x.email)='client'
  );
$$;


ALTER FUNCTION public.pppp_project_email_has_client_recipient_v1(p_project_id uuid, p_emails text[]) OWNER TO postgres;

--
-- Name: pppp_project_email_identity_autolink_v1(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_email_identity_autolink_v1(p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_current_linked integer := 0;
  v_historical_linked integer := 0;
  v_review_suggested integer := 0;
  v_contact_suggested integer := 0;
begin
  with active_projects as (
    select p.id,p.name,p.ref,p.business_ref,p.identity_aliases,p.operational_state_at
    from public.projects p
    where not public.pppp_project_status_is_terminal_v1(p.status)
  ), raw_identity as (
    select p.id as project_id, trim(x) as raw
    from active_projects p
    cross join lateral unnest(
      array_remove(
        array_cat(array[p.name,p.ref,p.business_ref],coalesce(p.identity_aliases,array[]::text[])),
        null
      )
    ) x
  ), phrase_identity as (
    select project_id,lower(regexp_replace(raw,'[^a-zA-Z0-9]+',' ','g')) ident
    from raw_identity
    where length(trim(raw))>=8
  ), unique_phrases as (
    select ident,min(project_id::text)::uuid project_id
    from phrase_identity
    where length(trim(ident))>=8
      and ident not in ('early warning and alarm system')
    group by ident
    having count(distinct project_id)=1
  ), acronym_raw as (
    select r.project_id,m[2] token
    from raw_identity r
    cross join lateral regexp_matches(
      r.raw,
      '(^|[^A-Z0-9])([A-Z][A-Z0-9-]{3,})([^A-Z0-9]|$)',
      'g'
    ) m
  ), acronym_identity as (
    select project_id,upper(regexp_replace(token,'[^A-Z0-9]','','g')) token
    from acronym_raw
    where length(regexp_replace(token,'[^A-Z0-9]','','g')) between 4 and 18
  ), unique_acronyms as (
    select token,min(project_id::text)::uuid project_id
    from acronym_identity
    where token not in (
      'GMBH','SHPK','SHQIP','KOSOVO','EURO','STEEL','PRISTEEL','PROJEKT','PROJECT',
      'OFFER','OFERTA','TENDER','SYSTEM','ALARM'
    )
    group by token
    having count(distinct project_id)=1
  ), contact_unique as (
    select lower(trim(pc.email)) email,min(pc.project_id)::uuid project_id
    from public.project_contacts pc
    join active_projects p on p.id::text=pc.project_id
    where coalesce(trim(pc.email),'')<>''
      and lower(coalesce(pc.status,'active'))='active'
    group by lower(trim(pc.email))
    having count(distinct pc.project_id)=1
  ), sender_history as (
    select lower(trim(e.from_email)) email,min(e.project_id::text)::uuid project_id
    from public.project_emails e
    join active_projects p on p.id=e.project_id
    where e.project_id is not null
      and coalesce(trim(e.from_email),'')<>''
    group by lower(trim(e.from_email))
    having count(distinct e.project_id)=1
  ), recipient_history as (
    select lower(trim(x.email)) email,min(e.project_id::text)::uuid project_id
    from public.project_emails e
    join active_projects p on p.id=e.project_id
    cross join lateral unnest(coalesce(e.to_emails,'{}'::text[])) x(email)
    where e.project_id is not null
      and coalesce(trim(x.email),'')<>''
    group by lower(trim(x.email))
    having count(distinct e.project_id)=1
  ), inbox as (
    select
      e.*,
      coalesce(e.sent_at,e.created_at) event_at,
      lower(regexp_replace(coalesce(e.subject,''),'[^a-zA-Z0-9]+',' ','g')) subj_norm,
      lower(regexp_replace(coalesce(e.snippet,''),'[^a-zA-Z0-9]+',' ','g')) body_norm,
      upper(regexp_replace(coalesce(e.subject,''),'[^A-Za-z0-9]+',' ','g')) subj_upper
    from public.project_emails e
    where e.project_id is null
      and e.id in (
        select id
        from public.project_emails
        where project_id is null
        order by sent_at desc nulls last
        limit greatest(1,least(coalesce(p_limit,500),2000))
      )
      and coalesce(e.sent_at,e.created_at)<=now()+interval '5 minutes'
      and split_part(lower(trim(coalesce(e.from_email,''))),'@',1) !~ '(^|[+._-])(no-?reply|do-?not-?reply|mailer-daemon|postmaster|notifications?|dmarc)([+._-]|$)'
      and lower(coalesce(e.from_email,'')) !~ '(ted-no-reply|noreply-dmarc|email\.openai|tm\.openai|supabase\.com|bitrix24\.com|apps-scripts-notifications)'
      and lower(trim(coalesce(e.from_email,'')))<>'eprokurimi@rks-gov.net'
      and coalesce(e.match_method,'') not like 'project-contact-unique-detached%'
      and coalesce(e.match_method,'') not like 'system-mail-detached:%'
      and coalesce(e.match_method,'') not in (
        'manual-ignored','mixed-project-review','reference-safety-cleared',
        'historical-overmatch-cleared','historical-gmail-panel-cleared'
      )
  ), phrase_hits as (
    select i.id,u.project_id,98 score,'unique_identity_phrase' method
    from inbox i
    join unique_phrases u on (' '||i.subj_norm||' ') like '% '||u.ident||' %'
    union all
    select i.id,u.project_id,95 score,'unique_identity_phrase_body' method
    from inbox i
    join unique_phrases u on i.direction='incoming'
      and (' '||i.body_norm||' ') like '% '||u.ident||' %'
  ), acronym_hits as (
    select i.id,u.project_id,97 score,'unique_project_acronym_subject' method
    from inbox i
    join unique_acronyms u on (' '||i.subj_upper||' ') like '% '||u.token||' %'
  ), explicit_candidates as (
    select * from phrase_hits
    union all
    select * from acronym_hits
  ), explicit_grouped as (
    select id,project_id,max(score) score,(array_agg(method order by score desc,method))[1] method
    from explicit_candidates
    group by id,project_id
  ), explicit_winners as (
    select g.id,g.project_id,g.score,g.method,i.event_at,p.operational_state_at
    from explicit_grouped g
    join inbox i on i.id=g.id
    join active_projects p on p.id=g.project_id
    join (
      select id,count(*) project_count
      from explicit_grouped
      group by id
    ) c on c.id=g.id
    where c.project_count=1 and g.score>=95
  ), incoming_contact_hits as (
    select i.id,cu.project_id,70 score,'contact_sender_history' method
    from inbox i
    join contact_unique cu on cu.email=lower(trim(i.from_email))
    join sender_history sh on sh.email=lower(trim(i.from_email)) and sh.project_id=cu.project_id
    where i.direction='incoming'
      and i.event_at>=now()-interval '30 days'
  ), outgoing_contact_rows as (
    select i.id,cu.project_id
    from inbox i
    cross join lateral unnest(coalesce(i.to_emails,'{}'::text[])) x(email)
    join contact_unique cu on cu.email=lower(trim(x.email))
    join recipient_history rh on rh.email=lower(trim(x.email)) and rh.project_id=cu.project_id
    where i.direction='outgoing'
      and i.event_at>=now()-interval '30 days'
  ), outgoing_contact_hits as (
    select id,min(project_id::text)::uuid project_id,70 score,'contact_recipient_history' method
    from outgoing_contact_rows
    group by id
    having count(distinct project_id)=1
  ), contact_candidates as (
    select * from incoming_contact_hits
    union all
    select * from outgoing_contact_hits
  ), contact_grouped as (
    select id,project_id,max(score) score,(array_agg(method order by method))[1] method
    from contact_candidates
    group by id,project_id
  ), contact_winners as (
    select g.id,g.project_id,g.score,g.method
    from contact_grouped g
    join (
      select id,count(*) project_count
      from contact_grouped
      group by id
    ) c on c.id=g.id
    where c.project_count=1
      and not exists(select 1 from explicit_winners w where w.id=g.id)
  ), current_updates as (
    update public.project_emails e
       set project_id=w.project_id,
           suggested_project_id=w.project_id,
           match_method='identity-autolink-v2:'||w.method,
           match_confidence=w.score,
           needs_review=false,
           review_reason=null,
           updated_at=now()
      from explicit_winners w
     where e.id=w.id
       and e.project_id is null
       and w.event_at>=now()-interval '7 days'
       and w.event_at<=now()+interval '5 minutes'
       and (w.operational_state_at is null or w.event_at>=w.operational_state_at)
    returning e.id
  ), historical_updates as (
    update public.project_emails e
       set project_id=w.project_id,
           suggested_project_id=w.project_id,
           match_method='historical-link-only:identity-v2:'||w.method,
           match_confidence=w.score,
           needs_review=false,
           review_reason=null,
           updated_at=now()
      from explicit_winners w
     where e.id=w.id
       and e.project_id is null
       and (
         w.event_at<now()-interval '14 days'
         or (w.operational_state_at is not null and w.event_at<w.operational_state_at)
       )
    returning e.id
  ), review_updates as (
    update public.project_emails e
       set suggested_project_id=w.project_id,
           match_method='identity-suggest-v2:'||w.method,
           match_confidence=w.score,
           needs_review=true,
           review_reason='Strong project identity evidence is present, but the email is outside the safe current-action window. Review before project linking.',
           updated_at=now()
      from explicit_winners w
     where e.id=w.id
       and e.project_id is null
       and w.event_at>=now()-interval '14 days'
       and w.event_at<now()-interval '7 days'
       and (w.operational_state_at is null or w.event_at>=w.operational_state_at)
    returning e.id
  ), contact_updates as (
    update public.project_emails e
       set suggested_project_id=w.project_id,
           match_method='entity-history-suggest-v2:'||w.method,
           match_confidence=w.score,
           needs_review=true,
           review_reason='Entity/contact history agrees with one project, but this is not project identity. Confirm from subject, reference, thread, or content before linking.',
           updated_at=now()
      from contact_winners w
     where e.id=w.id
       and e.project_id is null
    returning e.id
  )
  select
    (select count(*) from current_updates),
    (select count(*) from historical_updates),
    (select count(*) from review_updates),
    (select count(*) from contact_updates)
  into v_current_linked,v_historical_linked,v_review_suggested,v_contact_suggested;

  return jsonb_build_object(
    'ok',true,
    'linked',v_current_linked+v_historical_linked,
    'current_linked',v_current_linked,
    'historical_linked',v_historical_linked,
    'review_suggested',v_review_suggested,
    'entity_history_suggested',v_contact_suggested,
    'current_window_days',7,
    'historical_window_days',14,
    'future_guard_minutes',5,
    'ran_at',now()
  );
end;
$_$;


ALTER FUNCTION public.pppp_project_email_identity_autolink_v1(p_limit integer) OWNER TO postgres;

--
-- Name: pppp_project_email_party_role_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_email_party_role_v1(p_project_id uuid, p_email text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
  with e as (
    select lower(btrim(coalesce(p_email,''))) as email,
           lower(split_part(btrim(coalesce(p_email,'')),'@',2)) as domain
  )
  select case
    when e.email='' then 'unknown'
    when e.email ~ '@(prissteel|pristeel)\.com$' then 'internal'
    when exists(
      select 1 from public.rfq_log r
      where r.project_id=p_project_id
        and lower(btrim(coalesce(r.supplier_email,'')))=e.email
        and lower(coalesce(r.status,'')) not in ('superseded','cancelled','canceled','closed','rejected')
    ) then 'supplier'
    when e.domain<>'' and exists(
      select 1 from public.rfq_log r
      where r.project_id=p_project_id
        and lower(split_part(btrim(coalesce(r.supplier_email,'')),'@',2))=e.domain
        and lower(coalesce(r.status,'')) not in ('superseded','cancelled','canceled','closed','rejected')
    ) then 'supplier'
    when exists(
      select 1 from public.project_contacts pc
      where pc.project_id=p_project_id::text
        and lower(btrim(coalesce(pc.email,'')))=e.email
        and lower(btrim(coalesce(pc.role,''))) in ('supplier','furnitor')
    ) then 'supplier'
    when exists(
      select 1 from public.contacts c
      where lower(btrim(coalesce(c.email,'')))=e.email
        and lower(btrim(coalesce(c.kind,''))) in ('supplier','furnitor')
    ) then 'supplier'
    when exists(
      select 1 from public.project_contacts pc
      where pc.project_id=p_project_id::text
        and lower(btrim(coalesce(pc.email,'')))=e.email
        and lower(btrim(coalesce(pc.role,'')))='client'
    ) then 'client'
    when exists(
      select 1 from public.contacts c
      where lower(btrim(coalesce(c.email,'')))=e.email
        and lower(btrim(coalesce(c.kind,''))) in ('client','customer','buyer','gc')
    ) then 'client'
    else 'unknown'
  end
  from e;
$_$;


ALTER FUNCTION public.pppp_project_email_party_role_v1(p_project_id uuid, p_email text) OWNER TO postgres;

--
-- Name: pppp_project_email_thread_history_reconcile_v1(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_email_thread_history_reconcile_v1(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_attempted integer := 0;
  v_linked integer := 0;
begin
  with thread_projects as (
    select
      e.gmail_thread_id,
      min(e.project_id::text)::uuid as project_id
    from public.project_emails e
    where e.project_id is not null
      and coalesce(e.gmail_thread_id, '') <> ''
    group by e.gmail_thread_id
    having count(distinct e.project_id) = 1
  ), candidates as (
    select e.id, tp.project_id
    from public.project_emails e
    join thread_projects tp
      on tp.gmail_thread_id = e.gmail_thread_id
    join public.projects p
      on p.id = tp.project_id
    where e.project_id is null
      and coalesce(e.gmail_thread_id, '') <> ''
      and coalesce(e.sent_at, e.created_at) < now() - interval '14 days'
      and not public.pppp_project_status_is_terminal_v1(p.status)
      and coalesce(e.match_method, '') not like 'project-contact-unique-detached%'
      and lower(coalesce(e.from_email, '')) !~ '(mailer-daemon|postmaster|ted-no-reply|dmarc|noreply-dmarc|email\.openai|tm\.openai|supabase\.com|bitrix24\.com|apps-scripts-notifications)'
      and lower(trim(coalesce(e.from_email, ''))) <> 'eprokurimi@rks-gov.net'
    order by coalesce(e.sent_at, e.created_at) desc, e.id desc
    limit greatest(1, least(coalesce(p_limit, 200), 1000))
  ), updated as (
    update public.project_emails e
       set project_id = c.project_id,
           suggested_project_id = c.project_id,
           match_method = 'historical-link-only:unique-thread-v1',
           match_confidence = 99,
           needs_review = false,
           review_reason = null,
           updated_at = now()
      from candidates c
     where e.id = c.id
       and e.project_id is null
    returning e.project_id
  )
  select count(*)::integer,
         count(*) filter (where project_id is not null)::integer
    into v_attempted, v_linked
    from updated;

  return jsonb_build_object(
    'ok', true,
    'attempted', v_attempted,
    'linked', v_linked,
    'blocked_or_skipped', greatest(v_attempted - v_linked, 0),
    'method', 'historical-link-only:unique-thread-v1',
    'minimum_age_days', 14,
    'ran_at', now()
  );
end;
$$;


ALTER FUNCTION public.pppp_project_email_thread_history_reconcile_v1(p_limit integer) OWNER TO postgres;

