--
-- Name: pppp_project_memory_baseline_reconcile_v1(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_memory_baseline_reconcile_v1(p_apply boolean DEFAULT false, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  r record;
  v_fp text;
  v_old_id uuid;
  v_old_fp text;
  v_payload jsonb;
  v_created int:=0;
  v_unchanged int:=0;
  v_checked int:=0;
  v_items jsonb:='[]'::jsonb;
begin
  for r in
    select p.id,p.name,p.last_activity_at
    from public.projects p
    where lower(coalesce(p.status,'')) not in ('humbur','arkivuar','mbyllur','realizuar','lost','closed','cancelled','canceled')
    order by p.last_activity_at desc nulls last,p.updated_at desc,p.id
    limit greatest(1,least(coalesce(p_limit,25),100))
  loop
    v_checked:=v_checked+1;
    v_fp:=public.pppp_project_memory_fingerprint_v2(r.id);
    v_old_id:=null;v_old_fp:=null;

    select f.id,f.value->>'source_fingerprint' into v_old_id,v_old_fp
    from public.pppp_project_context_facts f
    where f.project_id=r.id
      and f.fact_key='project.memory.baseline.v1'
      and f.fact_status<>'dismissed'
    order by f.created_at desc,f.id desc
    limit 1;

    if v_fp is not null and v_fp=v_old_fp then
      v_unchanged:=v_unchanged+1;
      v_items:=v_items||jsonb_build_array(jsonb_build_object(
        'project_id',r.id,'name',r.name,'action','unchanged','fingerprint',v_fp,'memory_version',2
      ));
      continue;
    end if;

    if p_apply then
      v_payload:=public.pppp_project_memory_payload_v2(r.id);
      insert into public.pppp_project_context_facts(
        project_id,category,subject,fact_key,value,source_type,source_ref,evidence_status,confidence,fact_status,
        supersedes_id,idempotency_key,created_by
      ) values(
        r.id,'project_memory','Memoria bazë — '||r.name,'project.memory.baseline.v1',v_payload,
        'system',r.id::text,'observed',1,'observed',v_old_id,
        'project-memory-baseline-v2:'||r.id::text||':'||v_fp,'pppp-project-memory-baseline-v2'
      )
      on conflict do nothing;
      if found then v_created:=v_created+1; end if;
    end if;

    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'project_id',r.id,
      'name',r.name,
      'action',case when p_apply then 'baseline_refreshed' else 'would_refresh' end,
      'fingerprint',v_fp,
      'memory_version',2
    ));
  end loop;

  return jsonb_build_object(
    'apply',p_apply,
    'checked',v_checked,
    'created_or_refreshed',v_created,
    'unchanged',v_unchanged,
    'memory_version',2,
    'memory_only',true,
    'human_gates_preserved',true,
    'items',v_items,
    'generated_at',now()
  );
end;
$$;


ALTER FUNCTION public.pppp_project_memory_baseline_reconcile_v1(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION pppp_project_memory_baseline_reconcile_v1(p_apply boolean, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_project_memory_baseline_reconcile_v1(p_apply boolean, p_limit integer) IS 'Refreshes memory-only project baselines using payload/fingerprint v2. Does not create tasks, change project state, or cross protected human gates.';


--
-- Name: pppp_project_memory_fingerprint_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_memory_fingerprint_v1(p_project_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with p as (
  select id,status,pipeline_stage,operational_state,operational_state_at,last_activity_at,last_email_at,deadline
  from public.projects where id=p_project_id
), e as (
  select count(*)::text c,coalesce(max(updated_at)::text,'' ) m from public.project_emails where project_id=p_project_id
), c as (
  select count(*)::text c,coalesce(max(updated_at)::text,'' ) m from public.project_contacts where project_id=p_project_id::text
), o as (
  select count(*)::text c,coalesce(max(created_at)::text,'' ) m from public.offers where project_id=p_project_id
), q as (
  select count(*)::text c,coalesce(max(created_at)::text,'' ) m from public.documents_registry where project_id=p_project_id
), d as (
  select count(*)::text c,coalesce(max(created_at)::text,'' ) m from public.project_attachment_links where project_id=p_project_id::text
), a as (
  select count(*)::text c,coalesce(max(created_at)::text,'' ) m from public.project_analyses where project_id=p_project_id::text
), f as (
  select count(*)::text c,coalesce(max(updated_at)::text,'' ) m
  from public.pppp_project_context_facts
  where project_id=p_project_id and fact_key<>'project.memory.baseline.v1'
)
select md5(concat_ws('|',
  p.id::text,coalesce(p.status,''),coalesce(p.pipeline_stage,''),coalesce(p.operational_state,''),
  coalesce(p.operational_state_at::text,''),coalesce(p.last_activity_at::text,''),coalesce(p.last_email_at::text,''),coalesce(p.deadline,''),
  e.c,e.m,c.c,c.m,o.c,o.m,q.c,q.m,d.c,d.m,a.c,a.m,f.c,f.m
))
from p cross join e cross join c cross join o cross join q cross join d cross join a cross join f;
$$;


ALTER FUNCTION public.pppp_project_memory_fingerprint_v1(p_project_id uuid) OWNER TO postgres;

--
-- Name: pppp_project_memory_fingerprint_v2(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_memory_fingerprint_v2(p_project_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
select case
  when public.pppp_project_memory_fingerprint_v1(p_project_id) is null then null
  else md5(
    'project-memory-v2.1|primary-analysis-v1|commercial-context-counts-v1|' ||
    public.pppp_project_memory_fingerprint_v1(p_project_id)
  )
end;
$$;


ALTER FUNCTION public.pppp_project_memory_fingerprint_v2(p_project_id uuid) OWNER TO postgres;

--
-- Name: pppp_project_memory_payload_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_memory_payload_v1(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with p as (
  select id,name,client,ref,business_ref,location,deadline,status,pipeline_stage,operational_state,
         operational_state_at,operational_state_source,origin_type,work_model,deal_type,business_type,
         last_activity_at,last_email_at,created_at,updated_at
  from public.projects where id=p_project_id
), email_stats as (
  select count(*)::int as total,
         count(*) filter(where direction='incoming')::int as incoming,
         count(*) filter(where direction='outgoing')::int as outgoing,
         count(distinct gmail_thread_id)::int as threads,
         count(*) filter(where coalesce(has_attachments,false))::int as with_attachments,
         min(sent_at) as first_email_at,max(sent_at) as last_email_at
  from public.project_emails where project_id=p_project_id
), contact_stats as (
  select count(*)::int as total from public.project_contacts
  where project_id=p_project_id::text and coalesce(status,'active')<>'archived'
), supplier_stats as (
  select count(*)::int as total from public.offers
  where project_id=p_project_id and coalesce(supplier,'') !~* '(oferta jone|our offer|pristeel)'
), quote_stats as (
  select count(*)::int as total from public.documents_registry
  where project_id=p_project_id and upper(coalesce(series,''))='QUO'
), attachment_stats as (
  select count(*)::int as total,
         count(*) filter(where lower(coalesce(analysis_status,'')) in ('complete','analyzed'))::int as analyzed,
         count(*) filter(where lower(coalesce(analysis_status,'pending')) in ('pending','queued','processing'))::int as pending
  from public.project_attachment_links where project_id=p_project_id::text
), latest_analysis as (
  select a.created_at,a.engine,a.model,a.analysis
  from public.project_analyses a
  where a.project_id=p_project_id::text and a.status='complete'
  order by a.created_at desc limit 1
), base as (
  select p.*,es.total email_total,es.incoming email_incoming,es.outgoing email_outgoing,
         es.threads email_threads,es.with_attachments email_with_attachments,es.first_email_at,es.last_email_at email_last_at,
         cs.total contact_total,ss.total supplier_offer_total,qs.total client_offer_total,
         ats.total attachment_total,ats.analyzed attachment_analyzed,ats.pending attachment_pending,
         la.created_at analysis_at,la.engine analysis_engine,la.model analysis_model,la.analysis
  from p cross join email_stats es cross join contact_stats cs cross join supplier_stats ss cross join quote_stats qs cross join attachment_stats ats
  left join latest_analysis la on true
)
select jsonb_strip_nulls(jsonb_build_object(
  'version',1,
  'memory_only',true,
  'action_required',false,
  'home_visible',false,
  'generated_at',now(),
  'source_fingerprint',public.pppp_project_memory_fingerprint_v1(p_project_id),
  'summary',concat(
    'Memoria bazë e projektit: ',b.email_total,' email-e (',b.email_incoming,' hyrëse / ',b.email_outgoing,' dalëse), ',
    b.contact_total,' kontakte, ',b.supplier_offer_total,' oferta furnitorësh, ',b.client_offer_total,' oferta klienti. ',
    'Gjendja kanonike: ',coalesce(b.operational_state,'pa gjendje'),' / ',coalesce(b.pipeline_stage,'pa fazë'),'.',
    case when nullif(coalesce(b.analysis->>'executive_summary',''),'') is not null then ' Analiza e fundit: '||left(b.analysis->>'executive_summary',900) else '' end
  ),
  'project',jsonb_strip_nulls(jsonb_build_object(
    'id',b.id,'name',b.name,'client',b.client,'reference',b.ref,'business_ref',b.business_ref,'location',b.location,'deadline',b.deadline,
    'status',b.status,'pipeline_stage',b.pipeline_stage,'operational_state',b.operational_state,'operational_state_at',b.operational_state_at,
    'operational_state_source',b.operational_state_source,'origin_type',b.origin_type,'work_model',b.work_model,'deal_type',b.deal_type,
    'business_type',b.business_type,'last_activity_at',b.last_activity_at,'last_email_at',b.last_email_at
  )),
  'communication',jsonb_build_object(
    'total_emails',b.email_total,'incoming',b.email_incoming,'outgoing',b.email_outgoing,'threads',b.email_threads,
    'emails_with_attachments',b.email_with_attachments,'first_email_at',b.first_email_at,'last_email_at',b.email_last_at
  ),
  'contacts',coalesce((
    select jsonb_agg(to_jsonb(x) order by x.is_primary desc nulls last,x.email_count desc nulls last,x.last_seen desc nulls last)
    from (
      select id,name,email,company,role,source,is_primary,email_count,direct_count,cc_count,first_seen,last_seen
      from public.project_contacts
      where project_id=p_project_id::text and coalesce(status,'active')<>'archived'
      order by is_primary desc nulls last,email_count desc nulls last,last_seen desc nulls last limit 20
    ) x
  ),'[]'::jsonb),
  'recent_emails',coalesce((
    select jsonb_agg(to_jsonb(x) order by x.sent_at desc)
    from (
      select gmail_message_id,gmail_thread_id,direction,from_email,from_name,to_emails,cc_emails,subject,
             left(coalesce(snippet,''),1600) as snippet,sent_at,has_attachments,match_method,match_confidence
      from public.project_emails where project_id=p_project_id
      order by sent_at desc limit 20
    ) x
  ),'[]'::jsonb),
  'history_index',coalesce((
    select jsonb_agg(to_jsonb(x) order by x.sent_at asc)
    from (
      select gmail_message_id,gmail_thread_id,direction,from_email,subject,sent_at,has_attachments
      from public.project_emails where project_id=p_project_id
      order by sent_at desc limit 120
    ) x
  ),'[]'::jsonb),
  'supplier_offers',coalesce((
    select jsonb_agg(to_jsonb(x) order by x.created_at desc)
    from (
      select id,supplier,offer_ref,currency,total_amount,total_eur,price_kg,qty_kg,delivery_weeks,incoterms,payment_terms,validity_days,cert,
             left(coalesce(notes,''),1000) as notes,created_at
      from public.offers
      where project_id=p_project_id and coalesce(supplier,'') !~* '(oferta jone|our offer|pristeel)'
      order by created_at desc limit 12
    ) x
  ),'[]'::jsonb),
  'client_offers',coalesce((
    select jsonb_agg(to_jsonb(x) order by x.created_at desc)
    from (
      select id,doc_nr,client,currency,total_amount,total_eur,followup_status,last_followup_at,followup_count,created_at
      from public.documents_registry
      where project_id=p_project_id and upper(coalesce(series,''))='QUO'
      order by created_at desc limit 12
    ) x
  ),'[]'::jsonb),
  'documents',jsonb_build_object(
    'linked_attachments',b.attachment_total,'analyzed_attachments',b.attachment_analyzed,'pending_attachments',b.attachment_pending,
    'recent',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc)
      from (
        select id,attachment_name,analysis_status,analysis_method,analysis_confidence,bom_status,bom_applied_count,
               left(coalesce(extracted_text,''),1000) as extracted_text,created_at,analyzed_at
        from public.project_attachment_links
        where project_id=p_project_id::text
        order by created_at desc limit 20
      ) x
    ),'[]'::jsonb)
  ),
  'current_facts',coalesce((
    select jsonb_agg(to_jsonb(x) order by x.updated_at desc)
    from (
      select category,subject,fact_key,value,source_type,source_ref,evidence_status,confidence,updated_at
      from public.pppp_project_context_current_v
      where project_id=p_project_id and fact_status='observed' and fact_key<>'project.memory.baseline.v1'
      order by updated_at desc limit 15
    ) x
  ),'[]'::jsonb),
  'latest_analysis',case when b.analysis is null then null else jsonb_strip_nulls(jsonb_build_object(
    'created_at',b.analysis_at,'engine',b.analysis_engine,'model',b.analysis_model,
    'executive_summary',left(coalesce(b.analysis->>'executive_summary',''),2500),
    'current_stage',b.analysis->'current_stage','health',b.analysis->'health','recommendation',b.analysis->'recommendation',
    'next_actions',coalesce(b.analysis->'next_actions','[]'::jsonb),'risks',coalesce(b.analysis->'risks','[]'::jsonb),
    'missing_information',coalesce(b.analysis->'missing_information','[]'::jsonb)
  )) end
))
from base b;
$$;


ALTER FUNCTION public.pppp_project_memory_payload_v1(p_project_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION pppp_project_memory_payload_v1(p_project_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_project_memory_payload_v1(p_project_id uuid) IS 'Deterministic memory-only project context bundle. It creates no actions or operational changes.';


--
-- Name: pppp_project_memory_payload_v2(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_memory_payload_v2(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with base as (
  select public.pppp_project_memory_payload_v1(p_project_id) as payload
),
primary_analysis as (
  select public.pppp_project_primary_analysis_v1(p_project_id) as analysis
),
context_evidence as (
  select
    count(*) filter (
      where fact_status='observed'
        and category='supplier_pricing'
    )::int as supplier_quote_facts,
    count(*) filter (
      where fact_status='observed'
        and category='commercial_offer'
        and lower(coalesce(value->>'status','')) in ('sent','derguar','dërguar')
    )::int as sent_client_offer_facts
  from public.pppp_project_context_current_v
  where project_id=p_project_id
),
shaped as (
  select
    b.payload,
    pa.analysis,
    coalesce((b.payload->'communication'->>'total_emails')::int,0) as email_total,
    coalesce((b.payload->'communication'->>'incoming')::int,0) as email_incoming,
    coalesce((b.payload->'communication'->>'outgoing')::int,0) as email_outgoing,
    jsonb_array_length(coalesce(b.payload->'contacts','[]'::jsonb)) as contact_total,
    greatest(
      jsonb_array_length(coalesce(b.payload->'supplier_offers','[]'::jsonb)),
      coalesce(ce.supplier_quote_facts,0)
    ) as supplier_offer_total,
    greatest(
      jsonb_array_length(coalesce(b.payload->'client_offers','[]'::jsonb)),
      coalesce(ce.sent_client_offer_facts,0)
    ) as client_offer_total,
    jsonb_array_length(coalesce(b.payload->'supplier_offers','[]'::jsonb)) as legacy_supplier_offer_total,
    jsonb_array_length(coalesce(b.payload->'client_offers','[]'::jsonb)) as legacy_client_offer_total,
    coalesce(ce.supplier_quote_facts,0) as supplier_quote_fact_total,
    coalesce(ce.sent_client_offer_facts,0) as sent_client_offer_fact_total,
    coalesce(b.payload->'project'->>'operational_state','pa gjendje') as operational_state,
    coalesce(b.payload->'project'->>'pipeline_stage','pa fazë') as pipeline_stage
  from base b
  cross join primary_analysis pa
  cross join context_evidence ce
)
select
  (s.payload - 'version' - 'source_fingerprint' - 'summary' - 'latest_analysis')
  || jsonb_build_object(
    'version',2,
    'memory_only',true,
    'action_required',false,
    'home_visible',false,
    'source_fingerprint',public.pppp_project_memory_fingerprint_v2(p_project_id),
    'primary_analysis_policy','summarized_and_not_older_than_operational_state_v1',
    'commercial_evidence',jsonb_build_object(
      'supplier_quote_evidence_count',s.supplier_offer_total,
      'client_offer_sent_evidence_count',s.client_offer_total,
      'legacy_supplier_offer_rows',s.legacy_supplier_offer_total,
      'legacy_client_offer_rows',s.legacy_client_offer_total,
      'supplier_pricing_context_facts',s.supplier_quote_fact_total,
      'sent_client_offer_context_facts',s.sent_client_offer_fact_total
    ),
    'summary',concat(
      'Memoria bazë e projektit: ',s.email_total,' email-e (',s.email_incoming,' hyrëse / ',s.email_outgoing,' dalëse), ',
      s.contact_total,' kontakte, ',s.supplier_offer_total,' oferta furnitorësh, ',s.client_offer_total,' oferta klienti. ',
      'Gjendja kanonike: ',s.operational_state,' / ',s.pipeline_stage,'.',
      case
        when nullif(coalesce(s.analysis->>'executive_summary',''),'') is not null
          then ' Analiza primare: '||left(s.analysis->>'executive_summary',900)
        else ''
      end
    ),
    'latest_analysis',s.analysis
  )
from shaped s;
$$;


ALTER FUNCTION public.pppp_project_memory_payload_v2(p_project_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION pppp_project_memory_payload_v2(p_project_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_project_memory_payload_v2(p_project_id uuid) IS 'Project memory payload v2. Preserves v1 evidence/history payload but replaces raw chronological latest_analysis with a state-safe primary analysis selector.';


--
-- Name: pppp_project_memory_synthesis_internal_request(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_memory_synthesis_internal_request(p_limit integer DEFAULT 2) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_limit integer := greatest(1,least(coalesce(p_limit,2),2));
begin
  return public.pppp_enqueue_automation_http_v1(
    'project-memory-synthesis',
    format(
      'https://awqfpnzqwfjrjefoktgd.supabase.co/functions/v1/pppp-project-memory-synthesis?limit=%s',
      v_limit
    ),
    'gmail_tracker_cron_secret',
    120000,
    1
  );
end;
$$;


ALTER FUNCTION public.pppp_project_memory_synthesis_internal_request(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION pppp_project_memory_synthesis_internal_request(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_project_memory_synthesis_internal_request(p_limit integer) IS 'Queues the memory-only historical semantic synthesis worker. Max two changed projects per run and one HTTP attempt only; no operational action is authorized by this wrapper.';


--
-- Name: pppp_project_primary_analysis_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_primary_analysis_v1(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
select jsonb_strip_nulls(jsonb_build_object(
  'id',a.id,
  'created_at',a.created_at,
  'engine',a.engine,
  'model',a.model,
  'executive_summary',left(a.analysis->>'executive_summary',2500),
  'current_stage',a.analysis->'current_stage',
  'health',a.analysis->'health',
  'recommendation',a.analysis->'recommendation',
  'next_actions',coalesce(a.analysis->'next_actions','[]'::jsonb),
  'risks',coalesce(a.analysis->'risks','[]'::jsonb),
  'missing_information',coalesce(a.analysis->'missing_information','[]'::jsonb)
))
from public.project_analyses a
join public.projects p on p.id=p_project_id
where a.project_id=p_project_id::text
  and a.status='complete'
  and nullif(btrim(coalesce(a.analysis->>'executive_summary','')),'') is not null
  and a.created_at>=coalesce(p.operational_state_at,'epoch'::timestamptz)
order by a.created_at desc,a.id desc
limit 1;
$$;


ALTER FUNCTION public.pppp_project_primary_analysis_v1(p_project_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION pppp_project_primary_analysis_v1(p_project_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_project_primary_analysis_v1(p_project_id uuid) IS 'Returns the newest summarized project analysis that is not older than the canonical operational_state_at. Commercial/procurement dimension rows without executive_summary are intentionally excluded.';


--
-- Name: pppp_project_procurement_requirements_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_procurement_requirements_v1(p_project_id uuid) RETURNS TABLE(family text, requirement jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with rows as (
  select
    public.pppp_supplier_family_v1(concat_ws(' ',b.profile,b.materiali,b.pozicioni,b.dimensionet,b.dim)) family,
    nullif(trim(coalesce(b.profile,b.pozicioni,b.materiali,'')),'') product_type,
    nullif(trim(coalesce(b.grade,b.materiali,'')),'') grade,
    nullif(trim(coalesce(b.std,'')),'') standard,
    nullif(trim(coalesce(b.cert,'')),'') cert,
    nullif(trim(coalesce(b.surface,'')),'') surface,
    coalesce(b.kg,case when b.kg_unit is not null and b.sasia is not null then b.kg_unit*b.sasia else null end,0) kg,
    coalesce(b.pcs,b.sasia,0) pcs,
    b.len_mm,
    coalesce(b.needs_review,false) needs_review
  from public.bom_items b where b.project_id=p_project_id
), grouped as (
  select family,
    array_remove(array_agg(distinct product_type),null) product_types,
    array_remove(array_agg(distinct grade),null) grades,
    array_remove(array_agg(distinct standard),null) standards,
    array_remove(array_agg(distinct cert),null) certs,
    array_remove(array_agg(distinct surface),null) surfaces,
    sum(kg) quantity_kg,sum(pcs) quantity_pcs,max(len_mm) length_mm,
    count(*)::int bom_rows,count(*) filter(where needs_review)::int needs_review_rows
  from rows where family is not null group by family
)
select g.family,
  jsonb_build_object(
    'family',g.family,
    'product_type',coalesce(g.product_types[1],g.family),
    'product_types',g.product_types,
    'grades',g.grades,
    'standards',g.standards,
    'certifications',g.certs,
    'surfaces',g.surfaces,
    'quantity_kg',round(g.quantity_kg,3),
    'quantity_pcs',g.quantity_pcs,
    'length_mm',g.length_mm,
    'bom_rows',g.bom_rows,
    'needs_review_rows',g.needs_review_rows,
    'source','bom_items',
    'project_id',p_project_id
  ) requirement
from grouped g order by g.family;
$$;


ALTER FUNCTION public.pppp_project_procurement_requirements_v1(p_project_id uuid) OWNER TO postgres;

--
-- Name: pppp_project_status_is_terminal_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_project_status_is_terminal_v1(p_status text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select lower(btrim(coalesce(p_status,''))) in (
    'humbur','lost','arkivuar','archived','mbyllur','closed','closedlost',
    'cancelled','canceled','refuzuar','rejected','realizuar','completed','complete'
  );
$$;


ALTER FUNCTION public.pppp_project_status_is_terminal_v1(p_status text) OWNER TO postgres;

--
-- Name: pppp_projects_default_operational_state_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_projects_default_operational_state_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.operational_state is null
     and lower(coalesce(new.status,'pritje')) not in
       ('humbur','arkivuar','mbyllur','realizuar','lost','closed','cancelled','canceled','archived')
  then
    new.operational_state := 'active_work';
    new.operational_state_at := coalesce(new.operational_state_at, clock_timestamp());
    new.operational_state_source := coalesce(nullif(new.operational_state_source,''),'project-insert-default-v1');
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_projects_default_operational_state_v1() OWNER TO postgres;

--
-- Name: pppp_projects_set_updated_at(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_projects_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  new.updated_at := now();
  if new.last_activity_at is null then
    new.last_activity_at := coalesce(old.last_activity_at, new.created_at, now());
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_projects_set_updated_at() OWNER TO postgres;

--
-- Name: pppp_promote_new_client_rfq_v1(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_promote_new_client_rfq_v1(p_apply boolean DEFAULT false, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  r record;
  v_project_id uuid;
  v_existing_project_id uuid;
  v_company text;
  v_ref text;
  v_compact_ref text;
  v_name text;
  v_linked integer := 0;
  v_created integer := 0;
  v_existing_linked integer := 0;
  v_review integer := 0;
  v_candidates integer := 0;
  v_items jsonb := '[]'::jsonb;
begin
  for r in
    with base as (
      select e.*,
             public.pppp_extract_strong_rfq_ref_v1(e.subject) as strong_ref,
             row_number() over (
               partition by e.gmail_thread_id, public.pppp_extract_strong_rfq_ref_v1(e.subject)
               order by e.sent_at asc, e.id asc
             ) as rn
      from public.project_emails e
      where e.project_id is null
        and e.direction = 'incoming'
        and e.sent_at >= now() - interval '3 days'
        and public.pppp_extract_strong_rfq_ref_v1(e.subject) is not null
    )
    select * from base
    where rn = 1
    order by sent_at asc
    limit greatest(1, least(coalesce(p_limit,25),100))
  loop
    v_candidates := v_candidates + 1;
    v_ref := r.strong_ref;
    v_compact_ref := regexp_replace(lower(v_ref), '[^a-z0-9]+', '', 'g');
    v_project_id := null;
    v_existing_project_id := null;
    v_company := null;

    select e.project_id
      into v_existing_project_id
    from public.project_emails e
    where e.gmail_thread_id = r.gmail_thread_id
      and e.project_id is not null
    order by e.sent_at asc
    limit 1;

    if v_existing_project_id is null then
      select p.id
        into v_existing_project_id
      from public.projects p
      where regexp_replace(lower(coalesce(p.ref,'')), '[^a-z0-9]+', '', 'g') = v_compact_ref
         or regexp_replace(lower(coalesce(p.business_ref,'')), '[^a-z0-9]+', '', 'g') = v_compact_ref
         or exists (
              select 1 from unnest(coalesce(p.identity_aliases,'{}'::text[])) a
              where regexp_replace(lower(a), '[^a-z0-9]+', '', 'g') = v_compact_ref
            )
      order by p.created_at desc
      limit 1;
    end if;

    if v_existing_project_id is not null then
      if p_apply then
        update public.project_emails e
           set project_id = v_existing_project_id,
               suggested_project_id = v_existing_project_id,
               match_method = 'strong-rfq-ref-auto-v1',
               match_confidence = 100,
               needs_review = false,
               review_reason = null,
               updated_at = now()
         where e.gmail_thread_id = r.gmail_thread_id
           and e.project_id is null;
        get diagnostics v_linked = row_count;
        insert into public.project_email_links(project_id,gmail_message_id,gmail_thread_id,link_method,confidence,created_at,updated_at)
        select v_existing_project_id::text,e.gmail_message_id,e.gmail_thread_id,'strong-rfq-ref-auto-v1',100,now(),now()
        from public.project_emails e
        where e.gmail_thread_id = r.gmail_thread_id
          and e.gmail_message_id is not null
        on conflict (gmail_message_id,project_id) do update
          set gmail_thread_id=excluded.gmail_thread_id,link_method=excluded.link_method,confidence=excluded.confidence,updated_at=now();
      end if;
      v_existing_linked := v_existing_linked + 1;
      v_items := v_items || jsonb_build_array(jsonb_build_object('ref',v_ref,'thread_id',r.gmail_thread_id,'action','linked_existing','project_id',v_existing_project_id));
      continue;
    end if;

    select c.company
      into v_company
    from public.contacts c
    where lower(coalesce(c.email,'')) = lower(coalesce(r.from_email,''))
      and lower(coalesce(c.kind,'')) = 'client'
      and btrim(coalesce(c.company,'')) <> ''
    order by case when lower(c.company) ~ '^[a-z0-9.-]+\.[a-z]{2,}$' then 1 else 0 end,
             length(c.company) desc
    limit 1;

    if v_company is null then
      if p_apply then
        update public.project_emails e
           set needs_review = true,
               match_method = 'new-rfq-review-v1',
               match_confidence = 70,
               review_reason = 'RFQ/reference e re u identifikua, por dërguesi nuk është kontakt klienti i verifikuar.',
               updated_at = now()
         where e.gmail_thread_id = r.gmail_thread_id
           and e.project_id is null;
      end if;
      v_review := v_review + 1;
      v_items := v_items || jsonb_build_array(jsonb_build_object('ref',v_ref,'thread_id',r.gmail_thread_id,'action','review_new_company','from_email',r.from_email));
      continue;
    end if;

    if not p_apply then
      v_created := v_created + 1;
      v_items := v_items || jsonb_build_array(jsonb_build_object('ref',v_ref,'thread_id',r.gmail_thread_id,'action','would_create','client',v_company,'subject',r.subject));
      continue;
    end if;

    perform pg_advisory_xact_lock(hashtext(lower(v_company)||'|'||v_compact_ref));

    select p.id into v_existing_project_id
    from public.projects p
    where regexp_replace(lower(coalesce(p.ref,'')), '[^a-z0-9]+', '', 'g') = v_compact_ref
       or regexp_replace(lower(coalesce(p.business_ref,'')), '[^a-z0-9]+', '', 'g') = v_compact_ref
       or exists (
            select 1 from unnest(coalesce(p.identity_aliases,'{}'::text[])) a
            where regexp_replace(lower(a), '[^a-z0-9]+', '', 'g') = v_compact_ref
          )
    order by p.created_at desc
    limit 1;

    if v_existing_project_id is not null then
      v_project_id := v_existing_project_id;
    else
      v_name := regexp_replace(coalesce(r.subject,v_company||' — '||v_ref), '^\s*((re|fw|fwd|aw|wg)\s*:\s*)+', '', 'i');
      insert into public.projects(
        name,client,ref,business_ref,status,pipeline_stage,operational_state,
        operational_state_at,operational_state_source,origin_type,work_model,
        identity_aliases,last_email_at,last_activity_at,notes
      ) values (
        left(v_name,500),v_company,v_ref,v_ref,'pritje','rfq_in','action_required',
        now(),'project-discovery-gmail-rfq-v1','gmail_rfq','client_rfq',
        array[v_ref],r.sent_at,r.sent_at,
        'PPPP: projekt i krijuar automatikisht nga RFQ e re e një klienti të verifikuar. Human approval mbetet i detyrueshëm për ofertë/dërgim.'
      ) returning id into v_project_id;
      v_created := v_created + 1;
    end if;

    update public.project_emails e
       set project_id = v_project_id,
           suggested_project_id = v_project_id,
           match_method = 'new-client-rfq-auto-v1',
           match_confidence = 100,
           needs_review = false,
           review_reason = null,
           updated_at = now()
     where e.gmail_thread_id = r.gmail_thread_id
       and e.project_id is null;
    get diagnostics v_linked = row_count;

    insert into public.project_email_links(project_id,gmail_message_id,gmail_thread_id,link_method,confidence,created_at,updated_at)
    select v_project_id::text,e.gmail_message_id,e.gmail_thread_id,'new-client-rfq-auto-v1',100,now(),now()
    from public.project_emails e
    where e.gmail_thread_id = r.gmail_thread_id
      and e.gmail_message_id is not null
    on conflict (gmail_message_id,project_id) do update
      set gmail_thread_id=excluded.gmail_thread_id,link_method=excluded.link_method,confidence=excluded.confidence,updated_at=now();

    update public.projects p
       set last_email_at = greatest(coalesce(p.last_email_at,'epoch'::timestamptz),(select max(e.sent_at) from public.project_emails e where e.project_id=v_project_id)),
           last_activity_at = greatest(coalesce(p.last_activity_at,'epoch'::timestamptz),(select max(e.sent_at) from public.project_emails e where e.project_id=v_project_id))
     where p.id=v_project_id;

    v_items := v_items || jsonb_build_array(jsonb_build_object('ref',v_ref,'thread_id',r.gmail_thread_id,'action','created','project_id',v_project_id,'client',v_company,'linked_messages',v_linked));
  end loop;

  return jsonb_build_object(
    'apply',p_apply,'candidates',v_candidates,'projects_created',v_created,
    'existing_projects_linked',v_existing_linked,'review_required',v_review,'items',v_items
  );
end;
$_$;


ALTER FUNCTION public.pppp_promote_new_client_rfq_v1(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_promote_ted_award_to_sales_project_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_promote_ted_award_to_sales_project_v1(p_tender_watch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_tender public.kek_tender_watch%rowtype;
  v_project public.projects%rowtype;
  v_winner_name text;
  v_winner_email text;
  v_reference text;
  v_source text;
  v_phase text;
  v_contact record;
  v_created boolean := false;
begin
  if (select auth.uid()) is null
     and coalesce((select auth.jwt()->>'role'), '') <> 'service_role' then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;

  if p_tender_watch_id is null then
    raise exception using errcode = '22023', message = 'tender_watch_id_required';
  end if;

  select * into v_tender
  from public.kek_tender_watch
  where id = p_tender_watch_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'tender_not_found';
  end if;

  v_source := upper(coalesce(v_tender.payload->>'source', ''));
  v_phase := lower(coalesce(v_tender.payload->>'notice_phase', ''));
  v_winner_name := nullif(btrim(v_tender.payload #>> '{winner,name}'), '');
  v_winner_email := lower(nullif(btrim(v_tender.payload #>> '{winner,email}'), ''));
  v_reference := coalesce(
    nullif(btrim(v_tender.publication_no), ''),
    nullif(btrim(v_tender.procurement_no), ''),
    nullif(btrim(v_tender.source_key), ''),
    v_tender.id::text
  );

  if v_source <> 'TED' or v_phase <> 'award' then
    raise exception using errcode = '22023', message = 'ted_award_required';
  end if;
  if v_winner_name is null then
    raise exception using errcode = '22023', message = 'verified_winner_required';
  end if;
  if v_tender.project_id is null
     and lower(coalesce(v_tender.status, 'new')) not in ('new', 'review', 'watch') then
    raise exception using errcode = '22023', message = 'opportunity_not_approvable';
  end if;

  if v_tender.project_id is not null then
    select * into v_project from public.projects where id = v_tender.project_id;
  end if;

  if v_project.id is null then
    select p.* into v_project
    from public.projects p
    where nullif(btrim(v_tender.source_key), '') is not null
      and (
        p.business_ref = v_tender.source_key
        or v_tender.source_key = any(coalesce(p.identity_aliases, '{}'::text[]))
      )
    order by p.created_at desc nulls last
    limit 1;
  end if;

  if v_project.id is null then
    insert into public.projects(
      name, client, ref, location, notes, status, pipeline_stage,
      operational_state, operational_state_at, operational_state_source,
      business_ref, identity_aliases, origin_type, workflow_type,
      updated_at, last_activity_at
    ) values (
      v_winner_name || ' · ' || coalesce(nullif(btrim(v_tender.title), ''), 'TED award'),
      v_winner_name,
      v_reference,
      coalesce(nullif(btrim(v_tender.payload #>> '{winner,country}'), ''), nullif(btrim(v_tender.payload->>'country'), '')),
      'PPPP V2 · EU award sales.' || E'\n' ||
        'TED award: ' || coalesce(v_tender.title, '—') || E'\n' ||
        'Fituesi: ' || v_winner_name || E'\n' ||
        'Autoriteti kontraktues: ' || coalesce(v_tender.authority, '—') || E'\n' ||
        'Publikimi: ' || coalesce(v_tender.publication_no, '—') || E'\n' ||
        'Source key: ' || coalesce(v_tender.source_key, '—') || E'\n' ||
        'Asnjë email nuk u dërgua nga aprovimi i Project-it.',
      'pritje', 'rfq_in',
      'active_work', now(), 'pppp_v2_eu_award_sales_approval',
      v_tender.source_key,
      array(
        select distinct x
        from unnest(array[v_tender.source_key, v_tender.publication_no, v_tender.procurement_no]::text[]) as x
        where nullif(btrim(x), '') is not null
      ),
      'tender_award', 'eu_award_sales', now(), now()
    ) returning * into v_project;
    v_created := true;
  else
    update public.projects
    set workflow_type = coalesce(workflow_type, 'eu_award_sales'),
        updated_at = now()
    where id = v_project.id
    returning * into v_project;
  end if;

  update public.kek_tender_watch
  set project_id = v_project.id,
      status = 'promoted',
      updated_at = now()
  where id = v_tender.id;

  -- Keep already reconciled TED messages inside the new canonical Project.
  update public.project_emails pe
  set project_id = v_project.id,
      tender_watch_id = coalesce(pe.tender_watch_id, v_tender.id),
      updated_at = now()
  where pe.project_id is null
    and (
      pe.tender_watch_id = v_tender.id
      or exists (
        select 1 from public.tender_email_links tel
        where tel.tender_watch_id = v_tender.id
          and tel.gmail_message_id = pe.gmail_message_id
      )
    );

  -- Materialize only contacts backed by verified enrichment or real Gmail history.
  -- Never trust winner.email merely because it is syntactically valid.
  for v_contact in
    select distinct on (lower(x.email))
      lower(x.email) as email,
      x.name,
      x.company,
      x.role,
      x.message_id
    from (
      select
        oc.contact_email as email,
        null::text as name,
        coalesce(nullif(oc.company_name, ''), v_winner_name) as company,
        coalesce(nullif(oc.outreach_kind, ''), 'TED award contact') as role,
        oc.gmail_message_id as message_id
      from public.outreach_contacts oc
      where oc.tender_watch_id = v_tender.id
        and (
          nullif(btrim(oc.gmail_message_id), '') is not null
          or lower(coalesce(oc.status, '')) in ('sent', 'replied', 'meeting')
        )

      union all

      select
        lower(nullif(btrim(c.contact->>'value'), '')) as email,
        null::text as name,
        v_winner_name as company,
        coalesce(nullif(c.contact->>'purpose', ''), 'TED award contact') as role,
        null::text as message_id
      from jsonb_array_elements(
        coalesce(v_tender.payload #> '{winner,contact_enrichment,organizations}', '[]'::jsonb)
      ) org(organization)
      cross join lateral jsonb_array_elements(
        coalesce(org.organization->'contacts', '[]'::jsonb)
      ) c(contact)
      where c.contact->>'type' = 'email'
        and nullif(btrim(c.contact->>'value'), '') is not null
        and coalesce((c.contact->>'draft_eligible')::boolean, true)
        and lower(coalesce(c.contact->>'confidence', '')) in ('high', 'medium')
        and lower(coalesce(c.contact->>'company_attribution', '')) <> 'external_domain'
    ) x
    where x.email ~* '^[A-Z0-9._%+\\-]+@[A-Z0-9.\\-]+\\.[A-Z]{2,}$'
      and lower(split_part(x.email, '@', 2)) not in ('example.com','example.org','example.net','company.com')
      and lower(split_part(x.email, '@', 2)) not like 'yourdomain.%'
      and lower(split_part(x.email, '@', 2)) not like 'yourcompany.%'
    order by lower(x.email), x.message_id desc nulls last
  loop
    insert into public.project_contacts(
      project_id, email, name, company, role, source, source_message_ids,
      first_seen, last_seen, email_count, direct_count, cc_count,
      is_primary, status, created_at, updated_at
    ) values (
      v_project.id::text,
      v_contact.email,
      v_contact.name,
      v_contact.company,
      v_contact.role,
      'ted-award-sales-v1',
      case when v_contact.message_id is null then '[]'::jsonb else jsonb_build_array(v_contact.message_id) end,
      now(), now(), 0, 0, 0, false, 'active', now(), now()
    )
    on conflict(project_id, email) do update set
      company = coalesce(nullif(public.project_contacts.company, ''), excluded.company),
      role = coalesce(nullif(public.project_contacts.role, ''), excluded.role),
      status = 'active',
      updated_at = now();
  end loop;

  insert into public.tasks(
    project_id, title, detail, due_date, priority, status,
    source, category, source_ref
  ) values (
    v_project.id,
    'Kontakto fituesin · ' || left(v_winner_name, 140),
    'Project-i u aprovua nga TED award. Kontrollo kontaktet dhe draftin para dërgimit. Asnjë email nuk dërgohet automatikisht.',
    current_date,
    'larte', 'hapur', 'pppp_v2_eu_award_sales', 'klient',
    'TED-AWARD:' || v_tender.id::text || ':CONTACT'
  )
  on conflict(source, source_ref) do update set
    project_id = excluded.project_id,
    title = excluded.title,
    detail = excluded.detail,
    status = case
      when lower(coalesce(public.tasks.status, '')) in ('kryer', 'mbyllur', 'done') then public.tasks.status
      else 'hapur'
    end;

  return jsonb_build_object(
    'ok', true,
    'project_id', v_project.id,
    'project_created', v_created,
    'workflow_type', v_project.workflow_type,
    'tender_watch_id', v_tender.id,
    'human_send_required', true
  );
end;
$_$;


ALTER FUNCTION public.pppp_promote_ted_award_to_sales_project_v1(p_tender_watch_id uuid) OWNER TO postgres;

--
-- Name: pppp_rebuild_gmail_contact_master_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_rebuild_gmail_contact_master_v1() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  r record;
  n int := 0;
begin
  for r in
    select distinct on (lower(from_email),project_id) *
    from public.project_emails
    where project_id is not null
      and lower(coalesce(direction,''))='incoming'
      and nullif(trim(coalesce(from_email,'')),'') is not null
      and split_part(lower(trim(from_email)),'@',2) <> 'prissteel.com'
      and split_part(lower(trim(from_email)),'@',2) not like '%.prissteel.com'
      and lower(trim(from_email)) not in ('arianitti@me.com','arianit.vllahiu@gmail.com')
      and split_part(lower(trim(from_email)),'@',1) !~* '(^|[+._-])(no-?reply|do-?not-?reply|mailer-daemon|postmaster|notifications?|dmarc)([+._-]|$)'
    order by lower(from_email),project_id,coalesce(sent_at,created_at) desc
  loop
    perform public.pppp_sync_contact_from_project_email_v1_row(r.id);
    n := n + 1;
  end loop;
  return n;
end;
$_$;


ALTER FUNCTION public.pppp_rebuild_gmail_contact_master_v1() OWNER TO postgres;

--
-- Name: pppp_receipt_money_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_receipt_money_v1(p_raw text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
declare s text:=regexp_replace(coalesce(p_raw,''),'[^0-9,.-]','','g'); lc integer; ld integer; begin
  if s='' then return null; end if;
  lc:=length(s)-length(replace(s,',',''));
  ld:=length(s)-length(replace(s,'.',''));
  if position(',' in s)>0 and position('.' in s)>0 then
    if strpos(reverse(s),',') < strpos(reverse(s),'.') then s:=replace(replace(s,'.',''),',','.');
    else s:=replace(s,',',''); end if;
  elsif position(',' in s)>0 then s:=replace(s,',','.');
  elsif ld>1 then s:=replace(s,'.','');
  end if;
  begin return s::numeric; exception when others then return null; end;
end;$$;


ALTER FUNCTION public.pppp_receipt_money_v1(p_raw text) OWNER TO postgres;

--
-- Name: pppp_reconcile_automation_http_v1(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_reconcile_automation_http_v1(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'net'
    AS $$
declare
  r record;
  h record;
  v_limit integer:=least(1000,greatest(10,coalesce(p_limit,200)));
  v_succeeded integer:=0;
  v_retry_wait integer:=0;
  v_retried integer:=0;
  v_failed integer:=0;
  v_quota_blocked integer:=0;
  v_delay interval;
  v_task_ref text;
begin
  -- Retire any already-scheduled quota retries from the previous behavior.
  update public.pppp_automation_http_runs
     set status='failed',
         error_message=coalesce(error_message,'HTTP 402')||' · retry suppressed by PPPP Low-Egress Mode',
         next_retry_at=null,
         completed_at=coalesce(completed_at,now()),
         updated_at=now()
   where status='retry_wait' and http_status=402;

  for r in
    select * from public.pppp_automation_http_runs
    where status='queued'
    order by queued_at
    limit v_limit
  loop
    v_task_ref:=case
      when r.automation_key='project-drive-reconciler' then 'AUTOMATION:http:project-drive-reconciler'
      else 'AUTOMATION:http:'||r.correlation_id::text
    end;

    select id,status_code,timed_out,error_msg,content,created
      into h
      from net._http_response
     where id=r.request_id
     limit 1;

    if not found then
      if r.queued_at<now()-interval '10 minutes' then
        if r.attempt<r.max_attempts then
          update public.pppp_automation_http_runs
             set status='retry_wait',
                 error_message='No pg_net response after 10 minutes',
                 next_retry_at=now()+interval '5 minutes',
                 updated_at=now()
           where id=r.id;
          v_retry_wait:=v_retry_wait+1;
        else
          update public.pppp_automation_http_runs
             set status='failed',
                 error_message='No pg_net response after 10 minutes',
                 completed_at=now(),
                 updated_at=now()
           where id=r.id;
          insert into public.tasks(title,detail,due_date,priority,status,source,category,source_ref)
          values(
            'Automation failure · '||r.automation_key,
            'No pg_net response after 10 minutes; retries exhausted.',
            current_date,'larte','hapur','automation_failure','intern',v_task_ref
          )
          on conflict(source,source_ref) do update
             set title=excluded.title,detail=excluded.detail,due_date=current_date,
                 priority='larte',status='hapur',done_at=null;
          v_failed:=v_failed+1;
        end if;
      end if;
      continue;
    end if;

    if coalesce(h.timed_out,false)=false
       and h.error_msg is null
       and h.status_code between 200 and 399 then
      update public.pppp_automation_http_runs
         set status='succeeded',http_status=h.status_code,timed_out=coalesce(h.timed_out,false),
             error_message=null,response_excerpt=left(coalesce(h.content,''),1200),
             completed_at=coalesce(h.created,now()),updated_at=now()
       where id=r.id;

      update public.tasks
         set status='kryer',done_at=coalesce(done_at,now()),
             detail=coalesce(detail,'')||E'\nRecovered automatically: managed HTTP call succeeded.'
       where source='automation_failure' and source_ref=v_task_ref
         and lower(coalesce(status,'')) not in ('kryer','mbyllur','done');
      v_succeeded:=v_succeeded+1;

    elsif h.status_code=402 then
      update public.pppp_automation_http_runs
         set status='failed',http_status=402,timed_out=coalesce(h.timed_out,false),
             error_message='HTTP 402 · egress/quota block; retry suppressed by PPPP Low-Egress Mode',
             response_excerpt=left(coalesce(h.content,''),1200),
             completed_at=coalesce(h.created,now()),next_retry_at=null,updated_at=now()
       where id=r.id;

      insert into public.tasks(title,detail,due_date,priority,status,source,category,source_ref)
      values(
        'Automation paused · Supabase egress quota',
        'PPPP detected HTTP 402 from a managed automation. Automatic retries are suppressed to prevent additional egress until quota/service availability recovers.',
        current_date,'larte','hapur','automation_failure','intern','AUTOMATION:http:egress-quota-402'
      )
      on conflict(source,source_ref) do update
         set title=excluded.title,detail=excluded.detail,due_date=current_date,
             priority='larte',status='hapur',done_at=null;
      v_failed:=v_failed+1;
      v_quota_blocked:=v_quota_blocked+1;

    elsif r.attempt<r.max_attempts then
      v_delay:=case r.attempt
        when 1 then interval '5 minutes'
        when 2 then interval '15 minutes'
        else interval '30 minutes'
      end;
      update public.pppp_automation_http_runs
         set status='retry_wait',http_status=h.status_code,timed_out=coalesce(h.timed_out,false),
             error_message=left(coalesce(h.error_msg,'HTTP '||coalesce(h.status_code::text,'unknown')),1000),
             response_excerpt=left(coalesce(h.content,''),1200),completed_at=coalesce(h.created,now()),
             next_retry_at=now()+v_delay,updated_at=now()
       where id=r.id;
      v_retry_wait:=v_retry_wait+1;
    else
      update public.pppp_automation_http_runs
         set status='failed',http_status=h.status_code,timed_out=coalesce(h.timed_out,false),
             error_message=left(coalesce(h.error_msg,'HTTP '||coalesce(h.status_code::text,'unknown')),1000),
             response_excerpt=left(coalesce(h.content,''),1200),completed_at=coalesce(h.created,now()),updated_at=now()
       where id=r.id;
      insert into public.tasks(title,detail,due_date,priority,status,source,category,source_ref)
      values(
        'Automation failure · '||r.automation_key,
        case
          when r.automation_key='project-drive-reconciler' and coalesce(h.content,'') ilike '%Google token 401%'
            then 'Google Drive project-folder reconciliation is blocked by Google Workspace Domain-Wide Delegation. The service account cannot obtain the delegated Drive scope. PPPP will retry automatically after configuration is corrected.'
          else 'Managed HTTP automation exhausted '||r.max_attempts::text||' attempts. Last result: '||coalesce(h.error_msg,'HTTP '||coalesce(h.status_code::text,'unknown'))
        end,
        current_date,'larte','hapur','automation_failure','intern',v_task_ref
      )
      on conflict(source,source_ref) do update
         set title=excluded.title,detail=excluded.detail,due_date=current_date,
             priority='larte',status='hapur',done_at=null;
      v_failed:=v_failed+1;
    end if;
  end loop;

  for r in
    select * from public.pppp_automation_http_runs
    where status='retry_wait' and next_retry_at<=now() and coalesce(http_status,0)<>402
    order by next_retry_at
    limit v_limit
  loop
    begin
      perform public.pppp_enqueue_automation_http_v1(
        r.automation_key,r.request_url,r.secret_name,r.timeout_ms,
        r.max_attempts,r.correlation_id,r.attempt+1
      );
      update public.pppp_automation_http_runs set status='retried',updated_at=now() where id=r.id;
      v_retried:=v_retried+1;
    exception when others then
      update public.pppp_automation_http_runs
         set error_message=left('Retry enqueue failed: '||sqlerrm,1000),
             next_retry_at=now()+interval '15 minutes',updated_at=now()
       where id=r.id;
    end;
  end loop;

  return jsonb_build_object(
    'succeeded',v_succeeded,'retry_wait',v_retry_wait,'retried',v_retried,
    'failed',v_failed,'quota_402_retry_suppressed',v_quota_blocked,'generated_at',now()
  );
end;
$$;


ALTER FUNCTION public.pppp_reconcile_automation_http_v1(p_limit integer) OWNER TO postgres;

--
-- Name: pppp_reconcile_contact_role_conflicts_v1(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_reconcile_contact_role_conflicts_v1(p_apply boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record; v_checked integer:=0; v_changed integer:=0; v_items jsonb:='[]'::jsonb;
begin
  for r in
    select pc.id,pc.project_id,pc.email,pc.company,pc.role,c.kind,c.company as master_company,
           exists(select 1 from public.rfq_log q where q.project_id::text=pc.project_id and lower(btrim(coalesce(q.supplier_email,'')))=lower(btrim(pc.email)) and lower(coalesce(q.status,'')) not in ('superseded','cancelled','canceled','closed','rejected')) as active_supplier_evidence
    from public.project_contacts pc join public.contacts c on lower(btrim(c.email))=lower(btrim(pc.email))
    where coalesce(btrim(pc.email),'')<>'' and ((lower(coalesce(c.kind,'')) in ('client','customer','buyer','gc') and lower(coalesce(pc.role,'')) in ('supplier','furnitor')) or (lower(coalesce(c.kind,'')) in ('supplier','furnitor') and lower(coalesce(pc.role,''))='client'))
  loop
    v_checked:=v_checked+1;
    if lower(coalesce(r.kind,'')) in ('client','customer','buyer','gc') and not r.active_supplier_evidence then
      if p_apply then update public.project_contacts set role='client',company=case when lower(coalesce(company,'')) in ('','gmail') and coalesce(r.master_company,'')<>'' then r.master_company else company end where id=r.id; end if;
      v_changed:=v_changed+1; v_items:=v_items||jsonb_build_array(jsonb_build_object('project_id',r.project_id,'email',r.email,'from_role',r.role,'to_role','client'));
    elsif lower(coalesce(r.kind,'')) in ('supplier','furnitor') and r.active_supplier_evidence then
      if p_apply then update public.project_contacts set role='supplier' where id=r.id; end if;
      v_changed:=v_changed+1; v_items:=v_items||jsonb_build_array(jsonb_build_object('project_id',r.project_id,'email',r.email,'from_role',r.role,'to_role','supplier'));
    end if;
  end loop;
  return jsonb_build_object('apply',p_apply,'checked',v_checked,'changed_or_changeable',v_changed,'items',v_items);
end; $$;


ALTER FUNCTION public.pppp_reconcile_contact_role_conflicts_v1(p_apply boolean) OWNER TO postgres;

--
-- Name: pppp_reconcile_email_context_v1(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_reconcile_email_context_v1(p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_thread integer := 0;
  v_rfq integer := 0;
  v_review integer := 0;
  v_explicit_review integer := 0;
  v_days integer := greatest(1,least(coalesce(p_days,7),30));
begin
  with thread_map as (
    select gmail_thread_id, min(project_id::text)::uuid as project_id
    from public.project_emails
    where project_id is not null
      and gmail_thread_id is not null
      and gmail_thread_id <> ''
      and coalesce(match_method,'') not in (
        'server-context-thread-v1',
        'server-context-rfq-v1',
        'server-context-rfq-review-v1',
        'server-context-rfq-explicit-conflict-v1',
        'server-context-cross-project-review-v2'
      )
    group by gmail_thread_id
    having count(distinct project_id)=1
  ), upd as (
    update public.project_emails e
       set project_id=t.project_id,
           suggested_project_id=t.project_id,
           match_method='server-context-thread-v1',
           match_confidence=100,
           needs_review=false,
           review_reason=null,
           updated_at=now()
      from thread_map t
     where e.project_id is null
       and e.sent_at >= now() - make_interval(days=>v_days)
       and e.gmail_thread_id=t.gmail_thread_id
    returning e.gmail_message_id,e.gmail_thread_id,e.project_id
  )
  select count(*) into v_thread from upd;

  insert into public.project_email_links(project_id,gmail_message_id,gmail_thread_id,link_method,confidence,created_at)
  select e.project_id,e.gmail_message_id,e.gmail_thread_id,e.match_method,e.match_confidence,now()
  from public.project_emails e
  where e.project_id is not null
    and e.sent_at >= now()-make_interval(days=>v_days)
    and e.match_method='server-context-thread-v1'
  on conflict (gmail_message_id,project_id) do nothing;

  with recent_rfq as (
    select public.pppp_email_key_v1(r.supplier_email) email_key,
           r.project_id,
           max(r.sent_at) last_rfq
    from public.rfq_log r
    join public.projects p on p.id=r.project_id
    where coalesce(r.supplier_email,'')<>''
      and r.sent_at >= now()-interval '30 days'
      and lower(coalesce(r.status,'')) not in ('superseded','draft_review','lost','cancelled','canceled')
      and lower(coalesce(p.status,'')) not in ('humbur','arkivuar','mbyllur','realizuar','closedlost','cancelled','canceled','archived','lost')
    group by 1,2
  ), counts as (
    select email_key,count(distinct project_id) as project_count
    from recent_rfq
    where email_key<>''
    group by email_key
  ), winner as (
    select r.email_key,
           min(r.project_id::text)::uuid as project_id,
           max(r.last_rfq) as last_rfq
    from recent_rfq r
    join counts c using (email_key)
    where c.project_count=1
    group by r.email_key
  ), conflicts as (
    select e.id,
           public.pppp_email_subject_explicit_project_v1(e.subject) as explicit_project_id
    from public.project_emails e
    join winner w on public.pppp_email_key_v1(e.from_email)=w.email_key
    where e.project_id is null
      and e.direction='incoming'
      and e.sent_at >= now()-make_interval(days=>v_days)
      and public.pppp_email_subject_explicit_project_v1(e.subject) is not null
      and public.pppp_email_subject_explicit_project_v1(e.subject)<>w.project_id
  ), upd as (
    update public.project_emails e
       set suggested_project_id=c.explicit_project_id,
           match_method='server-context-rfq-explicit-conflict-v1',
           match_confidence=96,
           needs_review=true,
           review_reason='RFQ correspondent fallback conflicts with explicit project identity in the subject; automatic linking was withheld.',
           updated_at=now()
      from conflicts c
     where e.id=c.id
       and e.project_id is null
    returning e.id
  )
  select count(*) into v_explicit_review from upd;

  with recent_rfq as (
    select public.pppp_email_key_v1(r.supplier_email) email_key,
           r.project_id,
           max(r.sent_at) last_rfq
    from public.rfq_log r
    join public.projects p on p.id=r.project_id
    where coalesce(r.supplier_email,'')<>''
      and r.sent_at >= now()-interval '30 days'
      and lower(coalesce(r.status,'')) not in ('superseded','draft_review','lost','cancelled','canceled')
      and lower(coalesce(p.status,'')) not in ('humbur','arkivuar','mbyllur','realizuar','closedlost','cancelled','canceled','archived','lost')
    group by 1,2
  ), counts as (
    select email_key,count(distinct project_id) as project_count
    from recent_rfq
    where email_key<>''
    group by email_key
  ), winner as (
    select r.email_key,
           min(r.project_id::text)::uuid as project_id,
           max(r.last_rfq) as last_rfq
    from recent_rfq r
    join counts c using (email_key)
    where c.project_count=1
    group by r.email_key
  ), upd as (
    update public.project_emails e
       set project_id=w.project_id,
           suggested_project_id=w.project_id,
           match_method='server-context-rfq-v1',
           match_confidence=96,
           needs_review=false,
           review_reason=null,
           updated_at=now()
      from winner w
     where e.project_id is null
       and e.direction='incoming'
       and e.sent_at >= now()-make_interval(days=>v_days)
       and public.pppp_email_key_v1(e.from_email)=w.email_key
       and coalesce(public.pppp_email_subject_explicit_project_v1(e.subject),w.project_id)=w.project_id
       and coalesce(e.match_method,'')<>'server-context-rfq-explicit-conflict-v1'
    returning e.gmail_message_id,e.gmail_thread_id,e.project_id
  )
  select count(*) into v_rfq from upd;

  insert into public.project_email_links(project_id,gmail_message_id,gmail_thread_id,link_method,confidence,created_at)
  select e.project_id,e.gmail_message_id,e.gmail_thread_id,e.match_method,e.match_confidence,now()
  from public.project_emails e
  where e.project_id is not null
    and e.sent_at >= now()-make_interval(days=>v_days)
    and e.match_method='server-context-rfq-v1'
  on conflict (gmail_message_id,project_id) do nothing;

  with recent_rfq as (
    select public.pppp_email_key_v1(r.supplier_email) email_key,
           r.project_id,
           max(r.sent_at) last_rfq
    from public.rfq_log r
    join public.projects p on p.id=r.project_id
    where coalesce(r.supplier_email,'')<>''
      and r.sent_at >= now()-interval '30 days'
      and lower(coalesce(r.status,'')) not in ('superseded','draft_review','lost','cancelled','canceled')
      and lower(coalesce(p.status,'')) not in ('humbur','arkivuar','mbyllur','realizuar','closedlost','cancelled','canceled','archived','lost')
    group by 1,2
  ), counts as (
    select email_key,count(distinct project_id) as project_count
    from recent_rfq
    where email_key<>''
    group by email_key
  ), ranked as (
    select r.*,
           row_number() over(partition by r.email_key order by r.last_rfq desc,r.project_id) rn
    from recent_rfq r
    where r.email_key<>''
  ), ambiguous as (
    select r.email_key,r.project_id
    from ranked r
    join counts c using (email_key)
    where r.rn=1 and c.project_count>1
  ), upd as (
    update public.project_emails e
       set suggested_project_id=a.project_id,
           match_method='server-context-rfq-review-v1',
           match_confidence=74,
           needs_review=true,
           review_reason='Multiple active project RFQs exist for this correspondent; automatic linking was intentionally withheld.',
           updated_at=now()
      from ambiguous a
     where e.project_id is null
       and e.direction='incoming'
       and e.sent_at >= now()-make_interval(days=>v_days)
       and public.pppp_email_key_v1(e.from_email)=a.email_key
       and coalesce(e.match_confidence,0)<80
       and public.pppp_email_subject_explicit_project_v1(e.subject) is null
    returning e.id
  )
  select count(*) into v_review from upd;

  return jsonb_build_object(
    'ok',true,
    'thread_linked',v_thread,
    'rfq_linked',v_rfq,
    'held_for_review',v_review+v_explicit_review,
    'explicit_identity_conflicts',v_explicit_review,
    'days',v_days
  );
end
$$;


ALTER FUNCTION public.pppp_reconcile_email_context_v1(p_days integer) OWNER TO postgres;

--
-- Name: pppp_reconcile_email_party_states_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_reconcile_email_party_states_v1() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  x record;
  prior_mail record;
  v_changed integer:=0;
  v_new_state text;
  v_new_source text;
begin
  for x in
    select p.id,p.operational_state,p.operational_state_at,p.operational_state_source,
           pe.sent_at,pe.created_at,pe.gmail_message_id,pe.from_email
    from public.projects p
    join lateral (
      select e.* from public.project_emails e
      where e.project_id=p.id
      order by coalesce(e.sent_at,e.created_at) desc,e.id desc limit 1
    ) pe on true
    where coalesce(p.operational_state,'')<>'execution'
      and p.operational_state_source in ('client_email_event_auto_v1','client_reply_auto')
      and lower(coalesce(pe.direction,''))='incoming'
      and public.pppp_project_email_party_role_v1(p.id,pe.from_email)='supplier'
      and abs(extract(epoch from (coalesce(pe.sent_at,pe.created_at)-p.operational_state_at)))<=2
  loop
    select q.* into prior_mail
    from (
      select e.id,e.direction,e.sent_at,e.created_at,e.from_email,e.to_emails,
             public.pppp_project_email_party_role_v1(x.id,e.from_email) as sender_role,
             public.pppp_project_email_has_client_recipient_v1(x.id,e.to_emails) as has_client_recipient
      from public.project_emails e
      where e.project_id=x.id
        and coalesce(e.sent_at,e.created_at)<coalesce(x.sent_at,x.created_at)
      order by coalesce(e.sent_at,e.created_at) desc,e.id desc
    ) q
    where (lower(coalesce(q.direction,''))='incoming' and q.sender_role not in ('supplier','internal'))
       or (lower(coalesce(q.direction,''))='outgoing' and q.has_client_recipient)
    limit 1;

    if found then
      if lower(coalesce(prior_mail.direction,''))='incoming' then
        v_new_state:='action_required'; v_new_source:='email_party_reconcile_client_in_v1';
      else
        v_new_state:='wait_for_client'; v_new_source:='email_party_reconcile_client_out_v1';
      end if;
      update public.projects
         set operational_state=v_new_state,
             operational_state_at=coalesce(prior_mail.sent_at,prior_mail.created_at),
             operational_state_source=v_new_source,
             updated_at=now()
       where id=x.id;
    else
      update public.projects
         set operational_state='active_work',
             operational_state_at=now(),
             operational_state_source='email_party_reconcile_supplier_only_v1',
             updated_at=now()
       where id=x.id;
    end if;
    v_changed:=v_changed+1;
  end loop;

  return jsonb_build_object('ok',true,'reconciled',v_changed);
end;
$$;


ALTER FUNCTION public.pppp_reconcile_email_party_states_v1() OWNER TO postgres;

--
-- Name: pppp_reconcile_gmail_missing_http_v1(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_reconcile_gmail_missing_http_v1(p_lookback_minutes integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'net', 'pg_temp'
    AS $$
declare
  v_minutes integer := greatest(5, least(coalesce(p_lookback_minutes,30), 240));
  v_missing_ids text[] := '{}'::text[];
  v_body_marked integer := 0;
  v_scan_marked integer := 0;
begin
  select coalesce(array_agg(distinct gmail_message_id), '{}'::text[])
    into v_missing_ids
  from (
    select substring(r.content::text from 'messages/([0-9a-f]+)') as gmail_message_id
    from net._http_response r
    where r.created >= now() - make_interval(mins => v_minutes)
      and coalesce(r.status_code,0) >= 400
      and r.content::text like '%Gmail /messages/%-> 404%'
  ) q
  where gmail_message_id is not null;

  if coalesce(array_length(v_missing_ids,1),0)=0 then
    return jsonb_build_object('missing_ids',0,'body_marked',0,'scan_marked',0);
  end if;

  update public.project_emails pe
     set body_hydrated_at = coalesce(pe.body_hydrated_at, now()),
         body_hydration_method = case
           when pe.body_hydrated_at is null then 'server-full-mime-gmail-missing-v1'
           else pe.body_hydration_method
         end,
         updated_at = now()
   where pe.gmail_message_id = any(v_missing_ids)
     and pe.body_hydrated_at is null;
  get diagnostics v_body_marked = row_count;

  with linked as (
    select distinct pe.project_id::text as project_id,
           pe.gmail_message_id::text as gmail_message_id,
           nullif(pe.gmail_thread_id::text,'') as gmail_thread_id
      from public.project_emails pe
     where pe.gmail_message_id = any(v_missing_ids)
       and pe.has_attachments is true
       and pe.project_id is not null
    union
    select distinct pel.project_id::text,
           pel.gmail_message_id::text,
           nullif(coalesce(pel.gmail_thread_id,pe.gmail_thread_id)::text,'')
      from public.project_email_links pel
      join public.project_emails pe on pe.gmail_message_id=pel.gmail_message_id
     where pel.gmail_message_id = any(v_missing_ids)
       and pe.has_attachments is true
       and pel.project_id is not null
  ), upserted as (
    insert into public.project_attachment_scan_state(
      project_id,gmail_message_id,gmail_thread_id,outcome,attachment_count,scan_method,scanned_at
    )
    select project_id::uuid,gmail_message_id,gmail_thread_id,'no_downloadable',0,'server-metadata-gmail-missing-v1',now()
      from linked
    on conflict (project_id,gmail_message_id) do update
      set gmail_thread_id=coalesce(excluded.gmail_thread_id,public.project_attachment_scan_state.gmail_thread_id),
          outcome='no_downloadable',
          attachment_count=0,
          scan_method='server-metadata-gmail-missing-v1',
          scanned_at=excluded.scanned_at
    returning 1
  )
  select count(*) into v_scan_marked from upserted;

  return jsonb_build_object(
    'missing_ids',coalesce(array_length(v_missing_ids,1),0),
    'message_ids',to_jsonb(v_missing_ids),
    'body_marked',v_body_marked,
    'scan_marked',v_scan_marked
  );
end;
$$;


ALTER FUNCTION public.pppp_reconcile_gmail_missing_http_v1(p_lookback_minutes integer) OWNER TO postgres;

--
-- Name: pppp_reconcile_legacy_followups_v1(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_reconcile_legacy_followups_v1(p_apply boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r record; v_checked integer:=0; v_closed integer:=0; v_items jsonb:='[]'::jsonb;
begin
  for r in select t.id,t.project_id,t.contact_email,t.title from public.tasks t
    where t.source='sla_auto' and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed','arkivuar')
      and exists(select 1 from public.rfq_log q where q.project_id=t.project_id and lower(btrim(coalesce(q.supplier_email,'')))=lower(btrim(coalesce(t.contact_email,''))) and lower(coalesce(q.status,''))='replied')
  loop
    v_checked:=v_checked+1;
    if p_apply then update public.tasks set status='arkivuar',done_at=coalesce(done_at,now()),detail=case when position('PPPP data quality: archived because the linked supplier RFQ already has reply evidence.' in coalesce(detail,''))>0 then detail else concat_ws(E'\n',nullif(detail,''),'PPPP data quality: archived because the linked supplier RFQ already has reply evidence.') end where id=r.id; end if;
    v_closed:=v_closed+1; v_items:=v_items||jsonb_build_array(jsonb_build_object('task_id',r.id,'project_id',r.project_id,'contact_email',r.contact_email));
  end loop;
  return jsonb_build_object('apply',p_apply,'checked',v_checked,'closed_or_closeable',v_closed,'items',v_items);
end; $$;


ALTER FUNCTION public.pppp_reconcile_legacy_followups_v1(p_apply boolean) OWNER TO postgres;

--
-- Name: pppp_reconcile_supplier_waits_v1(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_reconcile_supplier_waits_v1(p_apply boolean DEFAULT false, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  r record;
  v_replied_at timestamptz;
  v_source_ref text;
  v_opened integer := 0;
  v_closed integer := 0;
  v_closed_lifecycle integer := 0;
  v_checked integer := 0;
  v_items jsonb := '[]'::jsonb;
begin
  if p_apply then
    update public.tasks t
       set status='mbyllur',
           done_at=coalesce(t.done_at,now()),
           detail=case
             when position('PPPP: supplier-wait lifecycle closed' in coalesce(t.detail,''))>0 then t.detail
             else concat_ws(E'\n',nullif(t.detail,''),
               'PPPP: supplier-wait lifecycle closed — gjendja kanonike e projektit nuk është më pritje aktive e furnitorit.')
           end
      from public.projects p
     where p.id=t.project_id
       and t.source='supplier_wait_auto'
       and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed','arkivuar','archived')
       and lower(coalesce(p.operational_state,'')) in ('wait_for_client','execution');
    get diagnostics v_closed_lifecycle = row_count;
  end if;

  for r in
    with supplier_outgoing as (
      select distinct on (e.project_id, lower(pc.email))
             e.project_id,e.gmail_message_id,e.sent_at,pc.email,
             sp.name as company,p.name as project_name,p.status,p.pipeline_stage,
             p.operational_state,sp.importance
      from public.project_emails e
      cross join lateral unnest(coalesce(e.to_emails,'{}'::text[])) recipient(email)
      join public.partner_contacts pc
        on lower(coalesce(pc.email,''))=lower(recipient.email)
      join public.partners sp
        on sp.id=pc.partner_id
       and sp.stage='active'
       and coalesce(sp.relation,'{}'::text[]) @> array['supplier']::text[]
      join public.projects p on p.id=e.project_id
      where e.project_id is not null
        and e.direction='outgoing'
        and e.sent_at >= now()-interval '14 days'
        and e.sent_at <= now()+interval '5 minutes'
        and lower(coalesce(p.status,'')) not in
            ('humbur','arkivuar','mbyllur','realizuar','lost','closed','cancelled','canceled')
      order by e.project_id,lower(pc.email),e.sent_at desc,sp.importance desc nulls last
    )
    select * from supplier_outgoing
    order by sent_at desc
    limit greatest(1,least(coalesce(p_limit,100),300))
  loop
    v_checked := v_checked + 1;
    v_source_ref := 'project:'||r.project_id::text||':supplier:'||lower(r.email);

    if lower(coalesce(r.operational_state,'')) in ('wait_for_client','execution') then
      if p_apply then
        update public.tasks
           set status='mbyllur',
               done_at=coalesce(done_at,now()),
               detail=case
                 when position('PPPP: supplier-wait lifecycle closed' in coalesce(detail,''))>0 then detail
                 else concat_ws(E'\n',nullif(detail,''),
                   'PPPP: supplier-wait lifecycle closed — gjendja kanonike e projektit nuk është më pritje aktive e furnitorit.')
               end
         where source='supplier_wait_auto'
           and source_ref=v_source_ref
           and lower(coalesce(status,'')) not in ('kryer','mbyllur','done','closed','arkivuar','archived');
        if found then v_closed_lifecycle := v_closed_lifecycle + 1; end if;
      end if;
      v_items := v_items || jsonb_build_array(jsonb_build_object(
        'project_id',r.project_id,'supplier',r.company,
        'action','lifecycle_superseded','operational_state',r.operational_state
      ));
      continue;
    end if;

    select max(e.sent_at) into v_replied_at
    from public.project_emails e
    where e.project_id=r.project_id
      and e.direction='incoming'
      and lower(coalesce(e.from_email,''))=lower(r.email)
      and e.sent_at>r.sent_at
      and e.sent_at <= now()+interval '5 minutes';

    if v_replied_at is not null then
      if p_apply then
        update public.tasks
           set status='kryer',done_at=coalesce(done_at,now())
         where source='supplier_wait_auto'
           and source_ref=v_source_ref
           and lower(coalesce(status,'')) not in ('kryer','mbyllur','done','closed');
        if found then v_closed := v_closed + 1; end if;
      end if;
      v_items := v_items || jsonb_build_array(jsonb_build_object(
        'project_id',r.project_id,'supplier',r.company,
        'action','supplier_replied','reply_at',v_replied_at
      ));
      continue;
    end if;

    if p_apply then
      insert into public.tasks(
        project_id,title,detail,due_date,priority,status,source,contact_email,category,source_ref
      )
      values(
        r.project_id,
        'Presim kalkulimin nga '||coalesce(nullif(r.company,''),r.email)||' — '||r.project_name,
        'PPPP: dokumentet/RFQ i janë dërguar furnitorit më '||
          to_char(r.sent_at at time zone 'Europe/Belgrade','YYYY-MM-DD HH24:MI')||
          '. Ende nuk ka përgjigje të lidhur me projektin. Follow-up vetëm kur të vijë afati.',
        (r.sent_at at time zone 'Europe/Belgrade')::date + 2,
        'larte','hapur','supplier_wait_auto',r.email,'furnitor',v_source_ref
      )
      on conflict (source,source_ref) do update
        set project_id=excluded.project_id,
            title=excluded.title,
            detail=excluded.detail,
            due_date=excluded.due_date,
            priority=excluded.priority,
            contact_email=excluded.contact_email,
            category=excluded.category,
            status=case
              when public.tasks.status in ('kryer','mbyllur','done','closed') then 'hapur'
              else public.tasks.status
            end,
            done_at=case
              when public.tasks.status in ('kryer','mbyllur','done','closed') then null
              else public.tasks.done_at
            end;

      update public.projects
         set pipeline_stage=case
               when pipeline_stage in ('rfq_in','technical_review','supplier_selection') then 'pricing'
               else pipeline_stage
             end,
             operational_state=case
               when operational_state in ('wait_for_client','execution') then operational_state
               else 'active_work'
             end,
             operational_state_at=case
               when operational_state in ('wait_for_client','execution') then operational_state_at
               when operational_state is distinct from 'active_work'
                 or operational_state_source is distinct from 'supplier-wait-auto-v1' then now()
               else operational_state_at
             end,
             operational_state_source=case
               when operational_state in ('wait_for_client','execution') then operational_state_source
               else 'supplier-wait-auto-v1'
             end
       where id=r.project_id;

      update public.tasks
         set status='kryer',done_at=coalesce(done_at,now())
       where project_id=r.project_id
         and source='project_discovery_auto'
         and status='hapur';
      v_opened := v_opened + 1;
    end if;

    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'project_id',r.project_id,'supplier',r.company,'supplier_email',r.email,
      'action','waiting_supplier','sent_at',r.sent_at
    ));
  end loop;

  return jsonb_build_object(
    'apply',p_apply,
    'checked',v_checked,
    'waiting_opened_or_refreshed',v_opened,
    'closed_on_reply',v_closed,
    'closed_on_lifecycle',v_closed_lifecycle,
    'items',v_items
  );
end;
$$;


