CREATE FUNCTION public.pppp_record_supplier_decision_v1(p_project_id uuid, p_supplier_offer_id uuid, p_decision_type text DEFAULT 'selected_producer'::text, p_notes text DEFAULT NULL::text, p_evidence jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
