ALTER FUNCTION public.pppp_record_supplier_decision_v1(p_project_id uuid, p_supplier_offer_id uuid, p_decision_type text, p_notes text, p_evidence jsonb) OWNER TO postgres;

--
-- Name: pppp_record_supplier_package_decision_v1(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_record_supplier_package_decision_v1(p_project_id uuid, p_supplier_offer_id uuid, p_package_key text, p_notes text DEFAULT NULL::text, p_evidence jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_offer public.offers%rowtype;
  v_project public.projects%rowtype;
  v_decision public.project_supplier_decisions%rowtype;
  v_package text:=lower(trim(coalesce(p_package_key,'')));
  v_type text;
begin
  if auth.uid() is null or not public.can_write() then
    raise exception 'Write permission required' using errcode='42501';
  end if;
  if v_package not in ('base','zinc','coating','installation','transport','other') then
    raise exception 'Unsupported sourcing package';
  end if;
  select * into v_project from public.projects where id=p_project_id;
  if not found then raise exception 'Project not found'; end if;
  if lower(coalesce(v_project.status,'')) in ('humbur','lost','mbyllur','closed','arkivuar','archived','realizuar','cancelled','canceled') then
    raise exception 'Supplier package decision cannot be recorded on a terminal project';
  end if;
  select * into v_offer from public.offers where id=p_supplier_offer_id and project_id=p_project_id;
  if not found then raise exception 'Supplier offer does not belong to this project'; end if;

  v_type:='selected_component_'||v_package;
  insert into public.project_supplier_decisions(
    project_id,supplier_offer_id,supplier_name,decision_type,status,source,evidence,notes,decided_at,updated_at
  ) values (
    p_project_id,p_supplier_offer_id,coalesce(nullif(trim(v_offer.supplier),''),'Unknown supplier'),v_type,'active',
    'authenticated_human_decision',
    coalesce(p_evidence,'{}'::jsonb)||jsonb_build_object(
      'human_confirmed',true,'package_key',v_package,'actor_user_id',auth.uid(),
      'recorded_at',now(),'supplier_offer_id',p_supplier_offer_id
    ),nullif(trim(coalesce(p_notes,'')),''),now(),now()
  )
  on conflict(project_id,decision_type) do update
    set supplier_offer_id=excluded.supplier_offer_id,
        supplier_name=excluded.supplier_name,
        status='active',source=excluded.source,evidence=excluded.evidence,
        notes=excluded.notes,decided_at=now(),updated_at=now()
  returning * into v_decision;

  return jsonb_build_object(
    'ok',true,'decision_id',v_decision.id,'project_id',p_project_id,
    'supplier_offer_id',p_supplier_offer_id,'supplier_name',v_decision.supplier_name,
    'package_key',v_package,'decision_type',v_decision.decision_type,
    'human_gate_preserved',true,'supplier_commitment_created',false
  );
end;
$$;


ALTER FUNCTION public.pppp_record_supplier_package_decision_v1(p_project_id uuid, p_supplier_offer_id uuid, p_package_key text, p_notes text, p_evidence jsonb) OWNER TO postgres;

--
-- Name: pppp_refresh_client_wait_followups_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_refresh_client_wait_followups_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record;
  v_created integer:=0;
begin
  for r in
    select p.id as project_id,p.name as project_name,p.operational_state_at,
           e.id as email_id,e.gmail_message_id,e.gmail_thread_id,e.rfc822_message_id,e.subject,e.snippet,
           coalesce((
             select x.email
             from unnest(coalesce(e.to_emails,'{}'::text[])) x(email)
             where public.pppp_project_email_party_role_v1(p.id,x.email)='client'
             limit 1
           ),'') as contact_email
    from public.projects p
    join lateral (
      select pe.*
      from public.project_emails pe
      where pe.project_id=p.id
        and lower(coalesce(pe.direction,''))='outgoing'
        and public.pppp_project_email_has_client_recipient_v1(p.id,pe.to_emails)
        and abs(extract(epoch from (coalesce(pe.sent_at,pe.created_at)-p.operational_state_at)))<=2
      order by coalesce(pe.sent_at,pe.created_at) desc,pe.id desc
      limit 1
    ) e on true
    where p.operational_state='wait_for_client'
      and p.operational_state_source in ('client_reply_sent_auto_v1','client_offer_sent_auto')
      and p.operational_state_at <= now()-interval '7 days'
      and not exists(
        select 1 from public.project_emails ni
        where ni.project_id=p.id
          and lower(coalesce(ni.direction,''))='incoming'
          and coalesce(ni.sent_at,ni.created_at)>p.operational_state_at
          and public.pppp_project_email_party_role_v1(p.id,ni.from_email) not in ('supplier','internal')
      )
  loop
    if coalesce(r.contact_email,'')='' then continue; end if;
    insert into public.tasks(project_id,title,detail,due_date,priority,status,source,contact_email,category,source_ref)
    values(
      r.project_id,
      'Follow-up klienti — '||r.project_name,
      'PPPP: kanë kaluar të paktën 7 ditë nga emaili i fundit i lidhur me klientin dhe nuk ka ardhur përgjigje e re. Përgatit follow-up, por mos e dërgo pa shqyrtim njerëzor.',
      current_date,'normal','hapur','client_wait_followup_auto',r.contact_email,'klient',
      'project:'||r.project_id::text||':client-followup:'||coalesce(r.gmail_message_id,r.email_id::text)
    )
    on conflict(source,source_ref) do update
      set contact_email=excluded.contact_email,
          due_date=least(public.tasks.due_date,excluded.due_date),
          detail=excluded.detail
    where lower(coalesce(public.tasks.status,'')) not in ('kryer','mbyllur','done','closed','arkivuar');
    if found then v_created:=v_created+1; end if;
  end loop;
  return jsonb_build_object('ok',true,'eligible_or_refreshed',v_created);
end;
$$;


ALTER FUNCTION public.pppp_refresh_client_wait_followups_v1() OWNER TO postgres;

--
-- Name: pppp_refresh_followup_draft_candidates_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_refresh_followup_draft_candidates_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_upserted integer:=0;
  v_superseded integer:=0;
begin
  perform public.pppp_refresh_client_wait_followups_v1();

  update public.pppp_followup_drafts_v1 d
     set status='superseded',updated_at=now(),last_error=null
   where d.status in ('candidate','draft_ready')
     and (
       not exists(select 1 from public.tasks t where t.id=d.task_id and t.status='hapur')
       or exists(
         select 1 from public.project_emails ri
         where ri.project_id=d.project_id
           and lower(coalesce(ri.direction,''))='incoming'
           and lower(coalesce(ri.from_email,''))=lower(d.contact_email)
           and coalesce(ri.sent_at,ri.created_at) > coalesce((select coalesce(pe.sent_at,pe.created_at) from public.project_emails pe where pe.id=d.last_outgoing_email_id),'-infinity'::timestamptz)
       )
     );
  get diagnostics v_superseded=row_count;

  insert into public.pppp_followup_drafts_v1(
    task_id,project_id,task_source,party_type,contact_email,due_date,
    last_outgoing_email_id,last_outgoing_gmail_message_id,last_outgoing_gmail_thread_id,
    last_outgoing_rfc822_message_id,last_outgoing_subject,last_outgoing_snippet,lang,status,updated_at
  )
  select t.id,t.project_id,t.source,
         case when t.source='client_wait_followup_auto' then 'client' else 'supplier' end,
         lower(btrim(t.contact_email)),t.due_date,
         oe.id,oe.gmail_message_id,oe.gmail_thread_id,oe.rfc822_message_id,oe.subject,oe.snippet,
         public.pppp_followup_language_v1(oe.subject,oe.snippet),'candidate',now()
  from public.tasks t
  join lateral (
    select pe.*
    from public.project_emails pe
    where pe.project_id=t.project_id
      and lower(coalesce(pe.direction,''))='outgoing'
      and exists(select 1 from unnest(coalesce(pe.to_emails,'{}'::text[])) x where lower(x)=lower(btrim(t.contact_email)))
    order by coalesce(pe.sent_at,pe.created_at) desc,pe.id desc
    limit 1
  ) oe on true
  where t.status='hapur'
    and t.source in ('supplier_wait_auto','client_wait_followup_auto')
    and t.project_id is not null
    and coalesce(btrim(t.contact_email),'')<>''
    and t.due_date is not null and t.due_date<=current_date
    and coalesce(oe.gmail_message_id,'')<>''
    and coalesce(oe.gmail_thread_id,'')<>''
    and not exists(
      select 1 from public.project_emails ri
      where ri.project_id=t.project_id
        and lower(coalesce(ri.direction,''))='incoming'
        and lower(coalesce(ri.from_email,''))=lower(btrim(t.contact_email))
        and coalesce(ri.sent_at,ri.created_at)>coalesce(oe.sent_at,oe.created_at)
    )
  on conflict(task_id) do update
    set project_id=excluded.project_id,task_source=excluded.task_source,party_type=excluded.party_type,
        contact_email=excluded.contact_email,due_date=excluded.due_date,
        last_outgoing_email_id=excluded.last_outgoing_email_id,
        last_outgoing_gmail_message_id=excluded.last_outgoing_gmail_message_id,
        last_outgoing_gmail_thread_id=excluded.last_outgoing_gmail_thread_id,
        last_outgoing_rfc822_message_id=excluded.last_outgoing_rfc822_message_id,
        last_outgoing_subject=excluded.last_outgoing_subject,last_outgoing_snippet=excluded.last_outgoing_snippet,
        lang=excluded.lang,
        status=case when public.pppp_followup_drafts_v1.gmail_draft_id is null then 'candidate' else public.pppp_followup_drafts_v1.status end,
        updated_at=now(),last_error=null;
  get diagnostics v_upserted=row_count;

  return jsonb_build_object('ok',true,'upserted',v_upserted,'superseded',v_superseded);
end;
$$;


ALTER FUNCTION public.pppp_refresh_followup_draft_candidates_v1() OWNER TO postgres;

--
-- Name: pppp_refresh_morning_edition_v1(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_refresh_morning_edition_v1(p_force boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  local_now timestamp;
  local_date date;
  payload jsonb;
  did_write boolean := false;
begin
  local_now := timezone('Europe/Belgrade', now());
  local_date := local_now::date;
  if not p_force and extract(hour from local_now) <> 6 then
    return jsonb_build_object('ok',true,'generated',false,'reason','outside_06_hour','local_now',local_now);
  end if;
  if exists(select 1 from public.pppp_morning_editions where edition_date=local_date) then
    return jsonb_build_object('ok',true,'generated',false,'reason','already_exists','edition_date',local_date);
  end if;
  payload := public.pppp_chatgpt_control_tower_v2(24,30,10);
  insert into public.pppp_morning_editions(edition_date,generated_at,control_tower)
  values(local_date,now(),payload)
  on conflict (edition_date) do nothing;
  get diagnostics did_write = row_count;
  return jsonb_build_object('ok',true,'generated',did_write,'edition_date',local_date);
end $$;


ALTER FUNCTION public.pppp_refresh_morning_edition_v1(p_force boolean) OWNER TO postgres;

--
-- Name: pppp_refresh_opportunity_followup_candidates_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_refresh_opportunity_followup_candidates_v1() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_added int:=0; v_superseded int:=0;
begin
  update public.pppp_opportunity_followups_v1 f set status='superseded',suppression_reason='reply_or_contact_stop',updated_at=now()
  from public.pppp_opportunity_outreach_registry_v1 r
  where f.registry_id=r.id and f.status in ('candidate','approved','snoozed') and (r.replied_at is not null or r.bounced_at is not null or r.do_not_contact_at is not null or r.status in ('replied','bounced','stopped','closed') or exists(select 1 from public.pppp_opportunity_outreach_registry_v1 x where x.action_id=r.action_id and x.id<>r.id and x.replied_at is not null));
  get diagnostics v_superseded=row_count;
  insert into public.pppp_opportunity_followups_v1(registry_id,action_id,company_profile_id,contact_id,stage,status,due_at,payload)
  select r.id,r.action_id,a.company_profile_id,r.contact_id,1,'candidate',r.sent_at+(p.first_wait_days||' days')::interval,jsonb_build_object('reason','sent_without_reply','recipient_email',r.recipient_email,'recipient_role',r.recipient_role,'offer_model',a.offer_model)
  from public.pppp_opportunity_outreach_registry_v1 r
  join public.pppp_opportunity_company_assessments_v1 a on a.action_id=r.action_id
  cross join public.pppp_opportunity_followup_policy_v1 p
  where p.id='global' and r.status='sent' and r.sent_at is not null and r.sent_at+(p.first_wait_days||' days')::interval<=now()
    and r.replied_at is null and r.bounced_at is null and r.do_not_contact_at is null
    and not exists(select 1 from public.pppp_opportunity_outreach_registry_v1 x where x.action_id=r.action_id and x.replied_at is not null)
    and not exists(select 1 from public.pppp_opportunity_followups_v1 f where f.registry_id=r.id and f.stage=1)
  on conflict(registry_id,stage) do nothing;
  get diagnostics v_added=row_count;
  return jsonb_build_object('ok',true,'candidates_added',v_added,'superseded',v_superseded,'gmail_drafts_created',0,'emails_sent',0);
end $$;


ALTER FUNCTION public.pppp_refresh_opportunity_followup_candidates_v1() OWNER TO postgres;

--
-- Name: pppp_refresh_opportunity_intelligence_v1(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_refresh_opportunity_intelligence_v1(p_limit integer DEFAULT 600) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_profiles int:=0;
  v_assessments int:=0;
  v_contacts int:=0;
  v_contacts_blocked int:=0;
  v_actions int:=0;
begin
  with src0 as (
    select
      a.*,t.title,t.authority,t.procurement_no,t.publication_no,t.estimated_value,t.currency,
      t.deadline,t.published_date,t.source_url,t.detail_url,t.payload as tender_payload,
      coalesce(nullif(a.target_company,''),nullif(t.payload->'winner'->>'name',''),t.authority) legal_name,
      public.pppp_opportunity_company_key_v1(
        coalesce(nullif(a.target_company,''),nullif(t.payload->'winner'->>'name',''),t.authority)
      ) normalized_name,
      lower(coalesce(
        nullif(a.payload->'outreach_readiness_v1'->>'verified_company_domain',''),
        nullif(t.payload->'winner'->'contact_enrichment'->'organizations'->0->>'domain',''),
        regexp_replace(coalesce(t.payload->'winner'->>'website',''),'^https?://(www\.)?|/.*$','','gi')
      )) raw_domain,
      lower(coalesce(
        nullif(t.payload->'winner'->>'company_type',''),
        nullif(t.payload->'winner'->'company_classification'->>'company_type',''),
        'unknown'
      )) company_type
    from public.pppp_opportunity_actions a
    join public.kek_tender_watch t on t.id=a.tender_watch_id
    where a.status='draft_review'
    order by a.updated_at desc
    limit least(2000,greatest(1,p_limit))
  ),
  src as (
    select src0.*,
      case
        when public.pppp_opportunity_domain_plausible_v1(legal_name,raw_domain) then raw_domain
        else null
      end as domain
    from src0
  )
  insert into public.pppp_opportunity_company_profiles_v1(
    normalized_name,legal_name,domain,country,company_type,business_summary,
    verification_status,source_urls,evidence,last_verified_at,updated_at
  )
  select
    normalized_name,
    max(legal_name),
    max(nullif(domain,'')),
    max(coalesce(tender_payload->'winner'->>'country',tender_payload->>'country')),
    max(company_type),
    max(coalesce(
      nullif(tender_payload->'winner'->'contact_enrichment'->'organizations'->0->>'business_summary',''),
      nullif(tender_payload->'winner'->'contact_enrichment'->'organizations'->0->>'description',''),
      nullif(tender_payload->'winner'->'company_classification'->>'summary',''),
      legal_name||' · '||company_type
    )),
    case
      when max(nullif(domain,'')) is not null and max(company_type)<>'unknown' then 'verified'
      when max(nullif(domain,'')) is not null then 'partial'
      else 'research_required'
    end,
    jsonb_path_query_array(
      jsonb_build_array(max(source_url),max(detail_url),max(tender_payload->'winner'->>'website')),
      '$[*] ? (@ != null && @ != "")'
    ),
    coalesce(
      (array_agg(tender_payload->'winner'->'company_classification'->'evidence')
       filter (where tender_payload->'winner'->'company_classification'->'evidence' is not null))[1],
      '[]'::jsonb
    ),
    now(),now()
  from src
  where normalized_name<>''
  group by normalized_name
  on conflict(normalized_name) do update set
    legal_name=excluded.legal_name,
    domain=case
      when excluded.domain is not null then excluded.domain
      when public.pppp_opportunity_domain_plausible_v1(
        excluded.legal_name,public.pppp_opportunity_company_profiles_v1.domain
      ) then public.pppp_opportunity_company_profiles_v1.domain
      else null
    end,
    country=coalesce(excluded.country,public.pppp_opportunity_company_profiles_v1.country),
    company_type=case
      when excluded.company_type<>'unknown' then excluded.company_type
      else public.pppp_opportunity_company_profiles_v1.company_type
    end,
    business_summary=coalesce(excluded.business_summary,public.pppp_opportunity_company_profiles_v1.business_summary),
    verification_status=case
      when coalesce(
        excluded.domain,
        case when public.pppp_opportunity_domain_plausible_v1(
          excluded.legal_name,public.pppp_opportunity_company_profiles_v1.domain
        ) then public.pppp_opportunity_company_profiles_v1.domain end
      ) is not null
      and excluded.company_type<>'unknown' then 'verified'
      when coalesce(
        excluded.domain,
        case when public.pppp_opportunity_domain_plausible_v1(
          excluded.legal_name,public.pppp_opportunity_company_profiles_v1.domain
        ) then public.pppp_opportunity_company_profiles_v1.domain end
      ) is not null then 'partial'
      else 'research_required'
    end,
    source_urls=excluded.source_urls,
    evidence=excluded.evidence,
    last_verified_at=now(),
    updated_at=now();
  get diagnostics v_profiles=row_count;

  with src as (
    select
      a.*,t.title,t.authority,t.procurement_no,t.publication_no,t.estimated_value,t.currency,
      t.deadline,t.published_date,t.source_url,t.detail_url,t.fpp_description,t.payload as tender_payload,
      p.id profile_id,p.business_summary,p.domain,p.company_type,
      upper(coalesce(t.payload->>'source','KRPP')) source_kind,
      coalesce(
        nullif(t.payload->>'scope',''),
        nullif(t.payload->>'description',''),
        nullif(t.fpp_description,''),
        t.title
      ) scope_text
    from public.pppp_opportunity_actions a
    join public.kek_tender_watch t on t.id=a.tender_watch_id
    join public.pppp_opportunity_company_profiles_v1 p
      on p.normalized_name=public.pppp_opportunity_company_key_v1(
        coalesce(nullif(a.target_company,''),nullif(t.payload->'winner'->>'name',''),t.authority)
      )
    where a.status='draft_review'
    order by a.updated_at desc
    limit least(2000,greatest(1,p_limit))
  ),
  shaped as (
    select *,
      case
        when source_kind='TED' and coalesce(tender_payload->>'notice_phase','')='award'
          then 'ted_award_outreach'
        else 'bid_opportunity'
      end workflow_track,
      case
        when source_kind<>'TED' or coalesce(tender_payload->>'notice_phase','')<>'award'
          then 'research_required'
        when coalesce(timing_classification,'')='future_supplier_qualification'
          then 'future_supplier_qualification'
        when upper(route)='DIRECT_RAW_MATERIAL' then 'material_supply'
        when upper(route)='TED_PRODUCER' then 'external_production_capacity'
        when upper(route)='TED_CONSORTIUM' then 'consortium_local_partner'
        when upper(route) in ('TED_GC','TED_GENERAL') then 'fabricated_steel_package'
        else 'research_required'
      end selected_model
    from src
  )
  insert into public.pppp_opportunity_company_assessments_v1(
    action_id,tender_watch_id,company_profile_id,workflow_track,company_role,
    tender_summary,company_summary,tender_facts,company_facts,unknowns,source_urls,
    pristeel_scope,offer_model,secondary_offer_model,timing_classification,
    decision_state,decision_reasons,draft_eligible,confidence_score,assessed_at,updated_at
  )
  select
    id,tender_watch_id,profile_id,workflow_track,company_type,
    jsonb_strip_nulls(jsonb_build_object(
      'title',title,'reference',coalesce(publication_no,procurement_no),'authority',authority,
      'estimated_value',estimated_value,'currency',currency,'deadline',deadline,
      'published_date',published_date,'scope',scope_text,'source',source_kind
    )),
    jsonb_strip_nulls(jsonb_build_object(
      'legal_name',target_company,'domain',domain,'company_type',company_type,'business_summary',business_summary
    )),
    jsonb_path_query_array(jsonb_build_array(
      jsonb_build_object('type','project','value',title,'status','confirmed','source_url',coalesce(detail_url,source_url)),
      jsonb_build_object('type','authority','value',authority,'status','confirmed','source_url',coalesce(detail_url,source_url)),
      jsonb_build_object('type','scope','value',scope_text,'status',case when scope_text=title then 'inferred' else 'confirmed' end,'source_url',coalesce(detail_url,source_url)),
      case when estimated_value is not null then jsonb_build_object('type','value','value',estimated_value||' '||coalesce(currency,''),'status','confirmed','source_url',coalesce(detail_url,source_url)) end
    ),'$[*] ? (@ != null)'),
    jsonb_path_query_array(jsonb_build_array(
      jsonb_build_object('type','company_role','value',company_type,'status',case when company_type='unknown' then 'unknown' else 'confirmed' end),
      jsonb_build_object('type','business_profile','value',business_summary,'status',case when business_summary is null then 'unknown' else 'confirmed' end),
      case when domain is not null then jsonb_build_object('type','official_domain','value',domain,'status','confirmed') end
    ),'$[*] ? (@ != null)'),
    jsonb_path_query_array(jsonb_build_array(
      case when company_type='unknown' then 'company_role' end,
      case when domain is null then 'official_domain' end,
      case when scope_text=title then 'detailed_scope' end
    ),'$[*] ? (@ != null)'),
    jsonb_path_query_array(
      jsonb_build_array(source_url,detail_url,tender_payload->'winner'->>'website'),
      '$[*] ? (@ != null && @ != "")'
    ),
    scope_text,selected_model,secondary_pristeel_offer_model,timing_classification,
    case
      when workflow_track='bid_opportunity' then 'research_required'
      when selected_model='research_required' then 'research_required'
      when domain is null then 'contact_research'
      when target_email is null then 'contact_research'
      else 'ready_for_review'
    end,
    jsonb_build_array('model selected from source, winner role, timing, scope and verified company identity'),
    workflow_track='ted_award_outreach'
      and selected_model not in ('research_required','no_outreach')
      and business_summary is not null
      and title is not null
      and domain is not null
      and company_type<>'unknown',
    least(100,
      (case when company_type<>'unknown' then 25 else 0 end)+
      (case when domain is not null then 25 else 0 end)+
      (case when scope_text<>title then 25 else 10 end)+
      (case when target_email is not null then 15 else 0 end)+10
    ),
    now(),now()
  from shaped
  on conflict(action_id) do update set
    company_profile_id=excluded.company_profile_id,
    workflow_track=excluded.workflow_track,
    company_role=excluded.company_role,
    tender_summary=excluded.tender_summary,
    company_summary=excluded.company_summary,
    tender_facts=excluded.tender_facts,
    company_facts=excluded.company_facts,
    unknowns=excluded.unknowns,
    source_urls=excluded.source_urls,
    pristeel_scope=excluded.pristeel_scope,
    offer_model=excluded.offer_model,
    secondary_offer_model=excluded.secondary_offer_model,
    timing_classification=excluded.timing_classification,
    decision_state=excluded.decision_state,
    decision_reasons=excluded.decision_reasons,
    draft_eligible=excluded.draft_eligible,
    confidence_score=excluded.confidence_score,
    assessed_at=now(),
    updated_at=now();
  get diagnostics v_assessments=row_count;

  update public.pppp_opportunity_contacts_v1 c
  set
    draft_eligible=false,
    verification_status=case
      when c.verification_status='verified' then 'review'
      else c.verification_status
    end,
    updated_at=now()
  from public.pppp_opportunity_company_profiles_v1 p
  where p.id=c.company_profile_id
    and c.draft_eligible=true
    and (
      public.pppp_outreach_contact_tier_v2(c.email,c.full_name,c.job_title)='F'
      or not public.pppp_opportunity_domain_plausible_v1(
        p.legal_name,split_part(lower(c.email),'@',2)
      )
    );
  get diagnostics v_contacts_blocked=row_count;

  insert into public.pppp_opportunity_contacts_v1(
    company_profile_id,tender_watch_id,email,full_name,job_title,functional_role,
    source_type,source_url,verification_status,confidence_score,draft_eligible,
    last_verified_at,updated_at
  )
  select distinct on (p.id,lower(trim(o.contact_email)))
    p.id,o.tender_watch_id,lower(trim(o.contact_email)),null,null,
    case
      when lower(o.contact_email)~'(procurement|purchasing|einkauf|tender|vergabe|przetarg|poptav|nabidk|compras)'
        then 'procurement'
      when lower(o.contact_email)~'(technical|technik|engineering)' then 'technical'
      when lower(o.contact_email)~'(project|projekt)' then 'project'
      when lower(o.contact_email)~'(sales|commercial|verkauf)' then 'commercial'
      else 'general'
    end,
    coalesce(o.source,'outreach_contacts'),null,'verified',
    case
      when lower(o.contact_email)~'(procurement|purchasing|einkauf|tender|vergabe|przetarg|poptav|nabidk|compras)'
        then 90
      else 70
    end,
    true,now(),now()
  from public.outreach_contacts o
  join public.pppp_opportunity_company_profiles_v1 p
    on nullif(p.normalized_name,'') is not null
   and nullif(public.pppp_opportunity_company_key_v1(o.company_name),'') is not null
   and p.normalized_name=public.pppp_opportunity_company_key_v1(o.company_name)
  where coalesce(o.contact_email,'')~*'^[^[:space:]@<>]+@[^[:space:]@<>]+\.[^[:space:]@<>]+$'
    and coalesce(o.bounced,false)=false
    and public.pppp_outreach_contact_tier_v2(lower(o.contact_email),null,null)<>'F'
    and public.pppp_opportunity_domain_plausible_v1(
      p.legal_name,split_part(lower(o.contact_email),'@',2)
    )
  order by p.id,lower(trim(o.contact_email)),o.updated_at desc nulls last
  on conflict(company_profile_id,email) do update set
    tender_watch_id=excluded.tender_watch_id,
    verification_status='verified',
    confidence_score=greatest(public.pppp_opportunity_contacts_v1.confidence_score,excluded.confidence_score),
    draft_eligible=true,
    last_verified_at=now(),
    updated_at=now();
  get diagnostics v_contacts=row_count;

  update public.pppp_opportunity_actions a
  set
    pristeel_offer_model=s.offer_model,
    personalization_facts=jsonb_path_query_array(
      jsonb_build_array(
        s.tender_summary->>'title',
        s.tender_summary->>'scope',
        s.company_summary->>'business_summary'
      ),
      '$[*] ? (@ != null && @ != "")'
    ),
    payload=jsonb_set(
      coalesce(a.payload,'{}'::jsonb),
      '{outreach_readiness_v1}',
      jsonb_strip_nulls(jsonb_build_object(
        'version','opportunity-intelligence-v1.1-safe-identity',
        'project_fact',s.tender_summary->>'title',
        'scope_evidence',s.tender_summary->>'scope',
        'company_fact',s.company_summary->>'business_summary',
        'verified_company_domain',s.company_summary->>'domain',
        'winner_role_verified',s.company_role<>'unknown',
        'pristeel_scope_fit',s.offer_model not in ('research_required','no_outreach'),
        'contact_identity_verified',exists(
          select 1
          from public.pppp_opportunity_contacts_v1 c
          where c.company_profile_id=s.company_profile_id
            and c.draft_eligible
            and c.verification_status='verified'
        ),
        'timing_fit',coalesce(s.timing_classification,'')<>'too_late',
        'assessment_id',s.id,
        'company_profile_id',s.company_profile_id
      )),
      true
    ),
    workflow_state=case
      when s.workflow_track='bid_opportunity' then 'research_required'
      when not s.draft_eligible then 'research_required'
      when exists(
        select 1
        from public.pppp_opportunity_contacts_v1 c
        where c.company_profile_id=s.company_profile_id
          and c.draft_eligible
          and c.verification_status='verified'
      ) then 'ready_for_outreach'
      else 'strong_company_contact_gap'
    end,
    updated_at=now()
  from public.pppp_opportunity_company_assessments_v1 s
  where s.action_id=a.id
    and a.status='draft_review';
  get diagnostics v_actions=row_count;

  return jsonb_build_object(
    'ok',true,
    'version','opportunity-intelligence-v1.1-safe-identity',
    'profiles',v_profiles,
    'assessments',v_assessments,
    'contacts_upserted',v_contacts,
    'contacts_blocked',v_contacts_blocked,
    'actions_refreshed',v_actions,
    'gmail_drafts_created',0,
    'emails_sent',0
  );
end
$_$;


ALTER FUNCTION public.pppp_refresh_opportunity_intelligence_v1(p_limit integer) OWNER TO postgres;

--
-- Name: pppp_refresh_outgoing_invoice_candidates_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_refresh_outgoing_invoice_candidates_v1() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record; v_candidate_id uuid; v_created integer:=0; v_review integer:=0; v_pending integer:=0;
begin
  for r in select * from public.pppp_outgoing_invoice_milestones_v1 where readiness in ('review','pending_event','waiting_previous_invoice') loop
    insert into public.invoice_candidates(candidate_key,project_id,party_name,direction,subject,extracted,confidence,status,updated_at)
    values(
      r.candidate_key,r.project_id,r.client,'outgoing','Outgoing invoice milestone · '||r.offer_doc_nr||' · '||r.milestone_label,
      jsonb_build_object(
        'workflow','pppp-outgoing-invoice-workflow-v1','offer_id',r.offer_id,'offer_doc_nr',r.offer_doc_nr,
        'project_name',r.project_name,'client',r.client,'milestone_index',r.milestone_index,'milestone_event',r.milestone_event,
        'milestone_label',r.milestone_label,'milestone_pct',r.milestone_pct,'amount',r.milestone_amount,'currency',r.currency,
        'exchange_rate_to_eur',r.exchange_rate_to_eur,'payment_days',r.payment_days,'delivery_date',r.delivery_date,
        'readiness',r.readiness,'readiness_reason',r.readiness_reason,'human_approval_required',true,'human_send_required',true
      ),case when r.readiness='review' then 100 else 90 end,case when r.readiness='review' then 'review' else 'pending_event' end,now()
    )
    on conflict(candidate_key) do update set
      project_id=excluded.project_id,party_name=excluded.party_name,direction='outgoing',subject=excluded.subject,
      extracted=excluded.extracted,confidence=excluded.confidence,
      status=case
        when public.invoice_candidates.status in ('approved','rejected') then public.invoice_candidates.status
        when public.invoice_candidates.status='review' then 'review' else excluded.status end,
      updated_at=now()
    returning id into v_candidate_id;

    if r.candidate_id is null then v_created:=v_created+1; end if;
    if r.readiness='review' then
      v_review:=v_review+1;
      insert into public.tasks(project_id,title,detail,due_date,priority,status,source,category,source_ref)
      values(r.project_id,'Aprovo faturën e radhës · '||r.offer_doc_nr||' · '||r.milestone_pct::text||'%',
        'PPPP ka përgatitur kandidatin e faturës për '||r.client||'. Milestone: '||r.milestone_label||'. Shuma: '||r.milestone_amount::text||' '||r.currency||'.\n\nHuman gate: kontrollo milestone-in, shumën dhe kushtet. Numri PST-INV gjenerohet vetëm pasi ta aprovosësh faturën.',
        current_date,'larte','hapur','outgoing_invoice_review','finance',r.candidate_key)
      on conflict(source,source_ref) do update set title=excluded.title,detail=excluded.detail,due_date=excluded.due_date,
        priority=excluded.priority,status=case when public.tasks.status in ('kryer','done','mbyllur','closed') then public.tasks.status else 'hapur' end,category='finance';
    else
      v_pending:=v_pending+1;
      update public.tasks set status='mbyllur',done_at=coalesce(done_at,now())
      where source='outgoing_invoice_review' and source_ref=r.candidate_key and lower(coalesce(status,'')) not in ('kryer','done','mbyllur','closed');
    end if;
  end loop;
  update public.tasks t set status='mbyllur',done_at=coalesce(t.done_at,now())
  where t.source='outgoing_invoice_review' and lower(coalesce(t.status,'')) not in ('kryer','done','mbyllur','closed')
    and exists(select 1 from public.invoice_candidates c where c.candidate_key=t.source_ref and c.direction='outgoing' and c.status in ('approved','rejected'));
  return jsonb_build_object('ok',true,'created_or_discovered',v_created,'review_ready',v_review,'pending_event',v_pending);
end;
$$;


ALTER FUNCTION public.pppp_refresh_outgoing_invoice_candidates_v1() OWNER TO postgres;

--
-- Name: pppp_refresh_project_decision(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_refresh_project_decision(p_project uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_project_name text;
  v_offer_count int := 0;
  v_install_count int := 0;
  v_scope_risk boolean := false;
  v_offers jsonb := '[]'::jsonb;
  v_plan_id bigint;
  v_plan_name text;
  v_plan jsonb;
  v_draft_nr text;
  v_draft_pending boolean := false;
  v_draft_total numeric;
  v_label text;
  v_reason text;
  v_actions jsonb := '[]'::jsonb;
  v_risks jsonb := '[]'::jsonb;
  v_missing jsonb := '[]'::jsonb;
  v_analysis jsonb;
  v_manifest jsonb := '[]'::jsonb;
  v_snapshot_id bigint;
  v_task_id uuid;
  v_task_detail text;
begin
  if p_project is null then return; end if;
  select name into v_project_name from public.projects where id=p_project;
  if v_project_name is null then return; end if;

  select count(*),
         count(*) filter (where coalesce((ip.elem->>'price_neg')::numeric,(ip.elem->>'price_orig')::numeric,0)>0),
         coalesce(bool_or(coalesce(ip.elem->>'scope','') in ('assistance_only','installation_unverified') or (ip.elem is not null and coalesce(ip.elem->>'scope','')='')),false),
         coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'supplier',o.supplier,
           'offer_id',o.id,
           'total_eur',o.total_eur,
           'base_rate',o.price_kg,
           'zinc_rate',o.zinc_kg,
           'installation_rate',coalesce((ip.elem->>'price_neg')::numeric,(ip.elem->>'price_orig')::numeric),
           'installation_total',coalesce((ip.elem->>'total_neg')::numeric,(ip.elem->>'total_orig')::numeric),
           'installation_scope',ip.elem->>'scope',
           'installation_persons',(ip.elem->>'persons')::numeric,
           'installation_days',(ip.elem->>'days')::numeric
         )) order by o.created_at desc),'[]'::jsonb)
    into v_offer_count,v_install_count,v_scope_risk,v_offers
  from public.offers o
  left join lateral (
    select x as elem
    from jsonb_array_elements(coalesce(o.positions,'[]'::jsonb)) x
    where lower(coalesce(x->>'key','')) in ('install','installation')
    limit 1
  ) ip on true
  where o.project_id=p_project;

  select pal.id,pal.attachment_name,
         case when pal.extracted_data ? 'dynamic_plan' then pal.extracted_data->'dynamic_plan' else pal.extracted_data end
    into v_plan_id,v_plan_name,v_plan
  from public.project_attachment_links pal
  where pal.project_id::text=p_project::text
    and (pal.extracted_data->>'document_type'='dynamic_plan' or pal.extracted_data ? 'dynamic_plan')
  order by pal.analyzed_at desc nulls last,pal.created_at desc
  limit 1;

  select d.doc_nr,d.total_eur,
         coalesce((d.offer_state->>'installation_price_pending')::boolean,false)
         or (d.revenue_breakdown ? 'installation' and d.revenue_breakdown->'installation'='null'::jsonb)
    into v_draft_nr,v_draft_total,v_draft_pending
  from public.documents_registry d
  where d.project_id=p_project and d.series='QUO'
  order by d.created_at desc
  limit 1;


  if v_offer_count=0 and v_plan_id is null and v_draft_nr is null then
    delete from public.project_analyses
    where project_id=p_project::text
      and model='project-decision-snapshot-v1';

    update public.tasks
    set status='mbyllur',
        done_at=coalesce(done_at,now()),
        detail=concat_ws(E'\n',nullif(detail,''),'PPPP: nuk ka provë komerciale aktive (ofertë furnitori, plan dinamik ose draft ofertë PRISTEEL); task-u automatik komercial u mbyll.')
    where project_id=p_project
      and source='project_decision_auto'
      and source_ref='PROJECT_STATE:'||p_project::text
      and lower(coalesce(status,'')) not in ('kryer','done','mbyllur','closed');

    update public.projects set updated_at=now() where id=p_project;
    return;
  end if;

  if v_draft_pending and v_install_count>=2 and v_scope_risk and v_plan_id is not null then
    v_label := 'Zgjidh scope-in e montimit + aprovo planin dinamik';
    v_reason := 'Ka disa çmime montimi, por scope-et nuk janë të barabarta; plani dinamik është lexuar dhe pret aprovim para finalizimit të draftit.';
  elsif v_draft_pending and v_install_count>=2 and v_scope_risk then
    v_label := 'Krahaso scope-in dhe zgjidh montimin';
    v_reason := 'Ka disa alternativa montimi me scope të ndryshëm; çmimi më i ulët nuk duhet zgjedhur automatikisht.';
  elsif v_draft_pending and v_install_count>=1 and v_plan_id is not null then
    v_label := 'Zgjidh montimin + aprovo planin dinamik';
    v_reason := 'Çmimi i montimit ekziston te furnitori dhe plani dinamik është në projekt; duhet human gate para plotësimit të ofertës së klientit.';
  elsif v_draft_pending and v_install_count>=1 then
    v_label := 'Zgjidh montimin dhe finalizo draftin';
    v_reason := 'Montimi nuk mungon më te furnitorët; duhet zgjedhur opsioni dhe pastaj të plotësohet drafti i klientit.';
  elsif v_plan_id is not null then
    v_label := 'Aprovo planin dinamik';
    v_reason := 'Plani dinamik është lexuar automatikisht dhe pret aprovim njerëzor.';
  else
    v_label := 'Rishiko gjendjen komerciale';
    v_reason := 'Nuk ka një veprim më specifik të konfirmuar nga të dhënat aktuale.';
  end if;

  if v_draft_pending and v_install_count>=1 then
    v_actions := v_actions || jsonb_build_array(jsonb_build_object(
      'text',case when v_scope_risk then 'Krahaso scope-in e montimit te furnitorëve dhe zgjidh opsionin.' else 'Zgjidh opsionin e montimit.' end,
      'owner','PRISTEEL','priority','critical','status','open','source_ids',jsonb_build_array('SUPPLIERS')
    ));
  end if;
  if v_plan_id is not null then
    v_actions := v_actions || jsonb_build_array(jsonb_build_object(
      'text','Verifiko dhe aprovo planin dinamik: Java 0-'||coalesce(v_plan->>'last_active_week','?')||'.',
      'owner','PRISTEEL','priority','high','status','open','source_ids',jsonb_build_array('PLAN')
    ));
  end if;
  if v_draft_pending then
    v_actions := v_actions || jsonb_build_array(jsonb_build_object(
      'text','Pas zgjedhjes së montimit, plotëso '||coalesce(v_draft_nr,'draftin')||' dhe rikalkulo totalin/marzhin para dërgimit.',
      'owner','PRISTEEL','priority','critical','status','open','source_ids',jsonb_build_array('DRAFT')
    ));
  end if;

  if v_scope_risk then
    v_risks := v_risks || jsonb_build_array(jsonb_build_object(
      'text','Alternativat e montimit nuk kanë scope të njëjtë. Asistenca e kufizuar nuk duhet trajtuar si montim i plotë.',
      'severity','critical','status','open','source_ids',jsonb_build_array('SUPPLIERS')
    ));
    v_missing := v_missing || jsonb_build_array(jsonb_build_object(
      'text','Scope i saktë i secilës alternativë të montimit','ask_to','supplier','priority','critical','why_needed','Për krahasim të drejtë dhe zgjedhje furnitori.','source_ids',jsonb_build_array('SUPPLIERS')
    ));
  end if;
  if v_plan_id is not null and coalesce((v_plan->>'preliminary')::boolean,false) then
    v_risks := v_risks || jsonb_build_array(jsonb_build_object(
      'text','Plani dinamik është preliminar dhe relativ; nuk është afat kontraktual pa pikënisje të konfirmuar.',
      'severity','high','status','open','source_ids',jsonb_build_array('PLAN')
    ));
  end if;

  v_manifest := jsonb_build_array(jsonb_build_object('id','P1','type','project','label',v_project_name));
  if v_offer_count>0 then v_manifest := v_manifest || jsonb_build_array(jsonb_build_object('id','SUPPLIERS','type','supplier_offers','label',v_offer_count||' oferta furnitorësh','meta',v_offers)); end if;
  if v_plan_id is not null then v_manifest := v_manifest || jsonb_build_array(jsonb_build_object('id','PLAN','type','dynamic_plan','label',v_plan_name,'meta',v_plan)); end if;
  if v_draft_nr is not null then v_manifest := v_manifest || jsonb_build_array(jsonb_build_object('id','DRAFT','type','our_offer_revision','label',v_draft_nr,'meta',jsonb_build_object('total_eur',v_draft_total,'installation_pending',v_draft_pending))); end if;

  v_analysis := jsonb_build_object(
    'event_source_ref','project-state:'||p_project::text,
    'executive_summary',v_reason,
    'current_stage','client_offer',
    'health',jsonb_build_object('label',case when v_draft_pending then 'vendim komercial aktiv' else 'projekt aktiv' end,'score',case when v_scope_risk then 82 else 90 end,'reason',v_reason),
    'confidence',jsonb_build_object('score',99,'reason','Snapshot deterministik nga ofertat furnitore, drafti aktual dhe dokumentet e lidhura.'),
    'recommendation',jsonb_build_object('decision','human_gate_project_decision','label',v_label,'reason',v_reason,'source_ids',jsonb_build_array('SUPPLIERS','PLAN','DRAFT')),
    'next_actions',v_actions,
    'risks',v_risks,
    'missing_information',v_missing,
    'requirements','[]'::jsonb,
    'changes_since_last','[]'::jsonb,
    'deadlines','[]'::jsonb,
    'decisions','[]'::jsonb,
    'assumptions','[]'::jsonb,
    'scope','[]'::jsonb,
    'supplier_options',v_offers,
    'dynamic_plan',v_plan,
    'draft_offer',jsonb_strip_nulls(jsonb_build_object('doc_nr',v_draft_nr,'total_eur',v_draft_total,'installation_pending',v_draft_pending))
  );

  select id into v_snapshot_id
  from public.project_analyses
  where project_id=p_project::text and model='project-decision-snapshot-v1'
  order by created_at desc limit 1;

  if v_snapshot_id is null then
    insert into public.project_analyses(id,project_id,status,engine,model,analysis,source_manifest,source_counts,created_at)
    values(nextval('public.project_analyses_id_seq'),p_project::text,'complete','project_state_rules','project-decision-snapshot-v1',v_analysis,v_manifest,jsonb_build_object('supplier_offers',v_offer_count,'dynamic_plans',case when v_plan_id is null then 0 else 1 end,'draft_offers',case when v_draft_nr is null then 0 else 1 end),now());
  else
    update public.project_analyses
    set status='complete',engine='project_state_rules',analysis=v_analysis,source_manifest=v_manifest,
        source_counts=jsonb_build_object('supplier_offers',v_offer_count,'dynamic_plans',case when v_plan_id is null then 0 else 1 end,'draft_offers',case when v_draft_nr is null then 0 else 1 end),created_at=now()
    where id=v_snapshot_id;
  end if;

  select id into v_task_id
  from public.tasks
  where project_id=p_project
    and lower(coalesce(status,'')) not in ('kryer','done','mbyllur')
    and source in ('email_request_auto','supplier_update_auto','project_decision_auto')
  order by case when source='email_request_auto' then 0 else 1 end, priority='e larte' desc, created_at asc
  limit 1;

  v_task_detail := v_reason||E'\n' ||
    case when v_install_count>0 then 'Alternativat e montimit: '||v_offers::text||E'\n' else '' end ||
    case when v_plan_id is not null then 'Plani dinamik: Java 0-'||coalesce(v_plan->>'last_active_week','?')||'. '||coalesce(v_plan_name,'')||E'\n' else '' end ||
    case when v_draft_pending then 'Drafti '||coalesce(v_draft_nr,'')||' mbetet i bllokuar për finalizim derisa të merret vendimi.' else '' end;

  if v_task_id is null then
    insert into public.tasks(project_id,title,detail,due_date,priority,status,source,source_ref,category)
    values(p_project,'Urgjent: '||v_label,v_task_detail,current_date,'e larte','hapur','project_decision_auto','PROJECT_STATE:'||p_project::text,'intern');
  else
    update public.tasks set title='Urgjent: '||v_label,detail=v_task_detail,due_date=current_date,priority='e larte'
    where id=v_task_id;
  end if;

  update public.tasks
  set status='kryer',detail=concat_ws(E'\n',detail,'Integruar në vendimin kanonik të projektit më '||to_char(now(),'DD.MM.YYYY HH24:MI')||'.')
  where project_id=p_project and source='dynamic_plan_auto' and lower(coalesce(status,''))='hapur';

  update public.projects set updated_at=now() where id=p_project;
end;
$$;


ALTER FUNCTION public.pppp_refresh_project_decision(p_project uuid) OWNER TO postgres;

--
-- Name: pppp_refresh_project_decision_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_refresh_project_decision_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_project uuid;
begin
  if tg_op='DELETE' then v_project:=old.project_id::uuid; else v_project:=new.project_id::uuid; end if;
  perform public.pppp_refresh_project_decision(v_project);
  return coalesce(new,old);
end;
$$;


ALTER FUNCTION public.pppp_refresh_project_decision_trigger() OWNER TO postgres;

--
-- Name: pppp_refresh_representation_opportunity_discovery_v1(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_refresh_representation_opportunity_discovery_v1(p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_run uuid; v_seen integer:=0; v_new integer:=0; v_dup integer:=0; r record; v_status text;
begin
  p_limit:=least(50,greatest(1,coalesce(p_limit,25)));
  insert into public.pppp_representation_discovery_runs_v1(lane,run_date,status,started_at,finished_at,error_message)
  values('consortium_opportunity',current_date,'running',now(),null,null)
  on conflict(lane,run_date) do update set status='running',started_at=now(),finished_at=null,error_message=null
  returning id into v_run;

  for r in
    select t.*,
      upper(coalesce(nullif(t.payload->>'source',''),split_part(t.source_key,':',1))) source_name,
      greatest(coalesce(t.relevance_score,0),case when coalesce(t.estimated_value,0)>=5000000 then 85 when coalesce(t.estimated_value,0)>=1000000 then 75 else 60 end) discovery_score
    from public.kek_tender_watch t
    where upper(coalesce(nullif(t.payload->>'source',''),split_part(t.source_key,':',1))) in
      ('KRPP','MCA_KOSOVO','KCF','RCF','EBRD_ECEPP','WORLD_BANK','UNGM','UNDP_KOSOVO','EU_OFFICE_KOSOVO')
      and public.pppp_representation_tender_current_v1(t.id)
    order by discovery_score desc,t.deadline asc nulls last,t.updated_at desc
    limit p_limit
  loop
    v_seen:=v_seen+1;
    if exists(select 1 from public.pppp_representation_opportunities_v1 o where o.archived_at is null and o.source_key=r.source_key) then
      v_status:='duplicate';v_dup:=v_dup+1;
    else v_status:='new'; end if;
    insert into public.pppp_representation_discovery_candidates_v1(
      run_id,lane,candidate_kind,source_key,source_name,source_url,title,tender_watch_id,opportunity_source_key,
      score,reasons,evidence,status,last_seen_at
    ) values(
      v_run,'consortium_opportunity','opportunity','opp:'||r.source_key,r.source_name,coalesce(r.detail_url,r.source_url),r.title,r.id,r.source_key,
      least(100,r.discovery_score),array[public.pppp_representation_tender_fit_v1(r.title,r.contract_type,r.estimated_value,r.currency)],
      jsonb_strip_nulls(jsonb_build_object('authority',r.authority,'reference',coalesce(r.procurement_no,r.publication_no),
        'estimated_value',r.estimated_value,'currency',r.currency,'deadline',r.deadline,'contract_type',r.contract_type,
        'payload_source',r.payload->>'source','source_key',r.source_key)),v_status,now()
    )
    on conflict(lane,source_key) do update set
      run_id=excluded.run_id,source_name=excluded.source_name,source_url=excluded.source_url,title=excluded.title,
      tender_watch_id=excluded.tender_watch_id,score=excluded.score,reasons=excluded.reasons,evidence=excluded.evidence,last_seen_at=now(),
      status=case when public.pppp_representation_discovery_candidates_v1.status in ('accepted','rejected') then public.pppp_representation_discovery_candidates_v1.status else excluded.status end;
    if v_status='new' then v_new:=v_new+1; end if;
  end loop;
  update public.pppp_representation_discovery_runs_v1 set status='succeeded',discovered_count=v_seen,new_count=v_new,
    duplicate_count=v_dup,finished_at=now(),payload=jsonb_build_object('filter_policy','representation_jv_relevance_v2','minimum_preparation_days',7,'read_source','kek_tender_watch','max_candidates',p_limit,
      'creates_active_opportunities',false,'creates_projects',false,'creates_outbound',false)
  where id=v_run;
  return jsonb_build_object('ok',true,'run_id',v_run,'discovered',v_seen,'new',v_new,'duplicates',v_dup,
    'active_opportunities_created',false,'projects_created',false,'outbound_created',false);
exception when others then
  if v_run is not null then update public.pppp_representation_discovery_runs_v1 set status='failed',error_message=sqlerrm,finished_at=now() where id=v_run; end if;
  raise;
end;
$$;


ALTER FUNCTION public.pppp_refresh_representation_opportunity_discovery_v1(p_limit integer) OWNER TO postgres;

--
-- Name: pppp_register_representation_market_signal_v1(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_register_representation_market_signal_v1(p_payload jsonb, p_run_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_source_key text:=nullif(btrim(p_payload->>'source_key'),'');
  v_title text:=nullif(btrim(p_payload->>'title'),'');
  v_domain text:=public.pppp_normalize_company_domain_v1(p_payload->>'company_domain');
  v_conflicts text[]; v_id uuid; v_status text;
begin
  if jsonb_typeof(p_payload)<>'object' then raise exception using errcode='22023',message='payload_object_required'; end if;
  if v_source_key is null or v_title is null then raise exception using errcode='22023',message='source_key_and_title_required'; end if;
  if nullif(p_payload->>'country_code','') is not null and (p_payload->>'country_code') !~ '^[A-Z]{2}$' then raise exception using errcode='22023',message='country_code_iso2_required'; end if;
  if not public.pppp_representation_company_signal_fit_v1(p_payload->>'company_name',v_title) then
    return jsonb_build_object('ok',true,'skipped',true,'reason','no_verified_business_signal','writes',0);
  end if;
  v_conflicts:=public.pppp_representation_discovery_conflicts_v1(v_domain);
  v_status:=case when cardinality(v_conflicts)>0 then 'review' else 'new' end;
  insert into public.pppp_representation_discovery_candidates_v1(
    run_id,lane,candidate_kind,source_key,source_name,source_url,title,company_name,company_domain,country_code,
    score,reasons,evidence,routing_conflicts,status,last_seen_at
  ) values(
    p_run_id,'market_entry','company',v_source_key,coalesce(nullif(p_payload->>'source_name',''),'public_market_signal'),
    nullif(p_payload->>'source_url',''),v_title,nullif(p_payload->>'company_name',''),v_domain,
    upper(nullif(p_payload->>'country_code','')),
    least(100,greatest(0,coalesce((p_payload->>'score')::integer,0))),
    coalesce(array(select jsonb_array_elements_text(coalesce(p_payload->'reasons','[]'::jsonb))),'{}'::text[]),
    coalesce(p_payload->'evidence','{}'::jsonb),v_conflicts,v_status,now()
  )
  on conflict(lane,source_key) do update set
    run_id=coalesce(excluded.run_id,public.pppp_representation_discovery_candidates_v1.run_id),
    source_url=coalesce(excluded.source_url,public.pppp_representation_discovery_candidates_v1.source_url),
    title=excluded.title,
    company_name=coalesce(excluded.company_name,public.pppp_representation_discovery_candidates_v1.company_name),
    company_domain=coalesce(excluded.company_domain,public.pppp_representation_discovery_candidates_v1.company_domain),
    score=greatest(public.pppp_representation_discovery_candidates_v1.score,excluded.score),
    reasons=excluded.reasons,evidence=excluded.evidence,routing_conflicts=excluded.routing_conflicts,last_seen_at=now(),
    status=case when public.pppp_representation_discovery_candidates_v1.status in ('accepted','rejected') then public.pppp_representation_discovery_candidates_v1.status else excluded.status end
  returning id,status into v_id,v_status;
  return jsonb_build_object('ok',true,'candidate_id',v_id,'status',v_status,'routing_conflicts',v_conflicts,
    'target_created',false,'project_created',false,'partner_created',false,'contact_created',false,'outbound_created',false,'email_sent',false);
end;
$_$;


ALTER FUNCTION public.pppp_register_representation_market_signal_v1(p_payload jsonb, p_run_id uuid) OWNER TO postgres;

--
-- Name: pppp_register_representation_market_signals_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_register_representation_market_signals_v1(p_payloads jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare p jsonb; v_count integer:=0; v_result jsonb;
begin
  if jsonb_typeof(p_payloads)<>'array' then raise exception using errcode='22023',message='payload_array_required'; end if;
  if jsonb_array_length(p_payloads)>25 then raise exception using errcode='22023',message='maximum_25_signals_per_batch'; end if;
  for p in select value from jsonb_array_elements(p_payloads) loop
    v_result:=public.pppp_register_representation_market_signal_v1(p,null);
    v_count:=v_count+1;
  end loop;
  return jsonb_build_object('ok',true,'processed',v_count,'active_records_created',false,
    'projects_created',false,'partners_created',false,'contacts_created',false,'outbound_created',false);
end;
$$;


ALTER FUNCTION public.pppp_register_representation_market_signals_v1(p_payloads jsonb) OWNER TO postgres;

--
-- Name: pppp_register_steel_buyer_discovery_batch_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_register_steel_buyer_discovery_batch_v1(p_run_id uuid, p_candidates jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  item jsonb; result jsonb; status_value text;
  inserted_count integer:=0; duplicate_count integer:=0; routing_review_count integer:=0;
  staged_count integer:=0; error_count integer:=0; error_samples jsonb:='[]'::jsonb;
begin
  if p_run_id is null or jsonb_typeof(p_candidates)<>'array' then
    raise exception using errcode='22023',message='invalid_discovery_batch';
  end if;
  for item in select value from jsonb_array_elements(p_candidates) loop
    begin
      result:=public.pppp_register_steel_buyer_discovery_candidate_v1(p_run_id,item);
      status_value:=coalesce(result->>'status','new');
      if status_value='accepted' then inserted_count:=inserted_count+1;
      elsif status_value='duplicate' then duplicate_count:=duplicate_count+1;
      elsif status_value='routing_review' then routing_review_count:=routing_review_count+1;
      else staged_count:=staged_count+1;
      end if;
    exception when others then
      error_count:=error_count+1;
      if jsonb_array_length(error_samples)<5 then error_samples:=error_samples||jsonb_build_array(sqlstate||':'||sqlerrm); end if;
    end;
  end loop;
  return jsonb_build_object('inserted_count',inserted_count,'duplicate_count',duplicate_count,
    'routing_review_count',routing_review_count,'staged_count',staged_count,'error_count',error_count,
    'error_samples',error_samples,'outbound_created',false,'gmail_draft_created',false,'external_email_sent',false);
end;
$$;


ALTER FUNCTION public.pppp_register_steel_buyer_discovery_batch_v1(p_run_id uuid, p_candidates jsonb) OWNER TO postgres;

--
-- Name: pppp_register_steel_buyer_discovery_candidate_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_register_steel_buyer_discovery_candidate_v1(p_run_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_domain text:=public.pppp_normalize_company_domain_v1(p_payload->>'website');
  v_name text:=nullif(btrim(p_payload->>'company_name'),'');
  v_country text:=upper(nullif(btrim(p_payload->>'country_code'),''));
  v_external text:=coalesce(nullif(p_payload->>'external_key',''),coalesce(v_domain,public.pppp_normalize_company_name_v1(v_name)));
  v_conflicts text[]:='{}'::text[]; v_company uuid; v_candidate uuid; v_target uuid;
  v_size text:=coalesce(nullif(p_payload->>'size_band',''),'unknown');
  v_potential text:=coalesce(nullif(p_payload->>'consumption_potential',''),'unknown');
begin
  if p_run_id is null or v_name is null or nullif(v_external,'') is null then raise exception using errcode='22023',message='invalid_discovery_candidate'; end if;
  if nullif(v_domain,'') is null then
    insert into public.pppp_steel_buyer_discovery_candidates_v1(
      run_id,external_key,company_name,normalized_name,country_code,industry,employees,revenue_text,size_band,
      consumption_potential,business_summary,evidence,source_url,status,reason
    ) values(
      p_run_id,v_external,v_name,public.pppp_normalize_company_name_v1(v_name),v_country,p_payload->>'industry',
      nullif(p_payload->>'employees','')::integer,p_payload->>'revenue_text',v_size,v_potential,p_payload->>'business_summary',
      coalesce(p_payload->'evidence','[]'::jsonb),p_payload->>'source_url','rejected','official_domain_missing'
    ) on conflict(external_key) do update set last_seen_at=now(),run_id=excluded.run_id returning id into v_candidate;
    return jsonb_build_object('status','rejected','reason','official_domain_missing','candidate_id',v_candidate);
  end if;
  if exists(select 1 from public.pppp_dach_steel_targets_v1 t where t.target_status not in('closed','rejected') and public.pppp_normalize_company_domain_v1(coalesce(t.company_domain,t.company_website))=v_domain) then v_conflicts:=array_append(v_conflicts,'steel_buyers'); end if;
  if exists(select 1 from public.pppp_eu_direct_targets_v1 e where e.archived_at is null and e.company_domain_normalized=v_domain) then v_conflicts:=array_append(v_conflicts,'eu_direct'); end if;
  if exists(select 1 from public.pppp_representation_targets_v1 r where r.archived_at is null and r.company_domain_normalized=v_domain) then v_conflicts:=array_append(v_conflicts,'representations'); end if;
  if exists(select 1 from public.pppp_opportunity_company_profiles_v1 o where public.pppp_normalize_company_domain_v1(o.domain)=v_domain) then v_conflicts:=array_append(v_conflicts,'opportunities'); end if;
  v_company:=public.pppp_company_identity_resolve_v1(v_name,v_domain,v_country,null,'steel_buyer_daily_discovery');
  insert into public.pppp_steel_buyer_discovery_candidates_v1(
    run_id,external_key,company_name,normalized_name,official_domain,website,country_code,industry,employees,revenue_text,
    size_band,consumption_potential,business_summary,evidence,source_url,status,canonical_company_id,routing_conflicts,reason
  ) values(
    p_run_id,v_external,v_name,public.pppp_normalize_company_name_v1(v_name),v_domain,p_payload->>'website',v_country,
    p_payload->>'industry',nullif(p_payload->>'employees','')::integer,p_payload->>'revenue_text',v_size,v_potential,
    p_payload->>'business_summary',coalesce(p_payload->'evidence','[]'::jsonb),p_payload->>'source_url',
    case when cardinality(v_conflicts)>0 then case when v_conflicts=array['steel_buyers'] then 'duplicate' else 'routing_review' end else 'new' end,
    v_company,v_conflicts,case when cardinality(v_conflicts)>0 then 'known_company_or_module_route' else null end
  ) on conflict(external_key) do update set
    run_id=excluded.run_id,last_seen_at=now(),industry=coalesce(excluded.industry,public.pppp_steel_buyer_discovery_candidates_v1.industry),
    employees=coalesce(excluded.employees,public.pppp_steel_buyer_discovery_candidates_v1.employees),
    revenue_text=coalesce(excluded.revenue_text,public.pppp_steel_buyer_discovery_candidates_v1.revenue_text),
    evidence=excluded.evidence,routing_conflicts=excluded.routing_conflicts,
    status=case when public.pppp_steel_buyer_discovery_candidates_v1.status='accepted' then 'accepted' else excluded.status end
  returning id,target_id into v_candidate,v_target;
  return jsonb_build_object('candidate_id',v_candidate,'target_id',v_target,'company_id',v_company,
    'status',(select status from public.pppp_steel_buyer_discovery_candidates_v1 where id=v_candidate),
    'routing_conflicts',v_conflicts,'outbound_created',false,'gmail_draft_created',false,'external_email_sent',false);
end;
$$;


ALTER FUNCTION public.pppp_register_steel_buyer_discovery_candidate_v1(p_run_id uuid, p_payload jsonb) OWNER TO postgres;

--
-- Name: FUNCTION pppp_register_steel_buyer_discovery_candidate_v1(p_run_id uuid, p_payload jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_register_steel_buyer_discovery_candidate_v1(p_run_id uuid, p_payload jsonb) IS 'Canonical cross-module-deduplicated Steel Buyer discovery registration. Creates no outbound communication.';


--
-- Name: pppp_representation_company_signal_fit_v1(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_representation_company_signal_fit_v1(p_name text, p_title text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select coalesce(length(btrim(p_name)) between 2 and 80
 and lower(p_name) !~ '(kosovo|balkans|serbia|albania|troops|administration|minister|president|maliqi|government|report|news)'
 and lower(p_title) !~ '(troops|military withdrawal|election|president|administration|parliament|politic|geopolitic)'
 and lower(p_title) ~ '(kosov|western balkan)'
 and lower(p_title) ~ '(expand(s|ing)? into|enter(s|ing)?|seeks? (a |local |new )?(partner|distributor|representative)|seeking (a |local )?(partner|distributor)|distribution (agreement|partner)|appoints?.*(distributor|representative)|market entry|manufactur.*invest|invest.*manufactur)'
 and (lower(p_title) ~ '(manufactur|equipment|energy|steel|industrial|engineering|technology|electric|machiner|solar|battery|medical|logistic|gmbh|corporation|\minc\M|\mltd\M)' or lower(p_title) ~ '(distributor|representative|distribution agreement)')
 ,false);
$$;


ALTER FUNCTION public.pppp_representation_company_signal_fit_v1(p_name text, p_title text) OWNER TO postgres;

--
-- Name: pppp_representation_discovery_conflicts_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_representation_discovery_conflicts_v1(p_domain text) RETURNS text[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_domain text:=public.pppp_normalize_company_domain_v1(p_domain); v_conflicts text[]:='{}'::text[];
begin
  if v_domain is null then return array['missing_official_domain']; end if;
  if exists(select 1 from public.pppp_representation_targets_v1 where archived_at is null and company_domain_normalized=v_domain) then
    v_conflicts:=array_append(v_conflicts,'representations');
  end if;
  if exists(select 1 from public.pppp_eu_direct_targets_v1 where archived_at is null and company_domain_normalized=v_domain) then
    v_conflicts:=array_append(v_conflicts,'eu_direct');
  end if;
  if exists(select 1 from public.pppp_dach_steel_targets_v1 where target_status not in ('closed','rejected','archived','project_promoted') and public.pppp_normalize_company_domain_v1(coalesce(company_domain,company_website))=v_domain) then
    v_conflicts:=array_append(v_conflicts,'material_trade');
  end if;
  if exists(select 1 from public.pppp_opportunity_company_profiles_v1 where public.pppp_normalize_company_domain_v1(domain)=v_domain) then
    v_conflicts:=array_append(v_conflicts,'opportunities');
  end if;
  if exists(select 1 from public.pppp_gc_prospects_v1 where public.pppp_normalize_company_domain_v1(coalesce(company_domain,website_url))=v_domain and status not in ('rejected','archived')) then
    v_conflicts:=array_append(v_conflicts,'gc_prospects');
  end if;
  return v_conflicts;
end;
$$;


ALTER FUNCTION public.pppp_representation_discovery_conflicts_v1(p_domain text) OWNER TO postgres;

--
-- Name: pppp_representation_discovery_inbox_v2(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_representation_discovery_inbox_v2(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 with eligible as (
 select c.id,c.lane,c.candidate_kind,c.status,
 case when c.candidate_kind='company' then c.company_name else t.title end title,
 c.company_name,c.company_domain,c.country_code,c.source_name,
 coalesce(t.detail_url,t.source_url,c.source_url) source_url,c.score,c.routing_conflicts,c.last_seen_at,
 case when c.candidate_kind='opportunity' then
 array[public.pppp_representation_tender_fit_v1(t.title,t.contract_type,t.estimated_value,t.currency)]
 else c.reasons end reasons,
 case when c.candidate_kind='opportunity' then c.evidence ||
 jsonb_strip_nulls(jsonb_build_object('authority',t.authority,'reference',t.procurement_no,
 'deadline',t.deadline,'estimated_value',t.estimated_value,'currency',t.currency))
 else c.evidence end evidence,
 case when c.candidate_kind='company' then coalesce(nullif(c.company_domain,''),lower(c.company_name))
 else coalesce(nullif(t.procurement_no,''),t.source_key) end identity_key
 from public.pppp_representation_discovery_candidates_v1 c
 left join public.kek_tender_watch t on t.id=c.tender_watch_id
 where c.status in ('new','review') and (
 (c.lane='market_entry' and c.candidate_kind='company'
 and public.pppp_representation_company_signal_fit_v1(c.company_name,c.title))
 or (c.lane='consortium_opportunity' and c.candidate_kind='opportunity'
 and public.pppp_representation_tender_current_v1(c.tender_watch_id))
 )
 ), unique_rows as (
 select distinct on (lane,identity_key) * from eligible
 order by lane,identity_key,last_seen_at desc,id
 ), limited as (
 select to_jsonb(u)-'identity_key' row from unique_rows u
 order by score desc,last_seen_at desc,id limit least(50,greatest(1,coalesce(p_limit,50)))
 )
 select jsonb_build_object('rows',coalesce((select jsonb_agg(row) from limited),'[]'::jsonb),
 'policy','representation_jv_relevance_v2','minimum_preparation_days',7);
$$;


ALTER FUNCTION public.pppp_representation_discovery_inbox_v2(p_limit integer) OWNER TO postgres;

