--
-- Name: pppp_review_representation_discovery_candidate_v1(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_review_representation_discovery_candidate_v1(p_candidate_id uuid, p_company_name text DEFAULT NULL::text, p_company_domain text DEFAULT NULL::text, p_country_code text DEFAULT NULL::text, p_status text DEFAULT 'review'::text, p_review_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  c public.pppp_representation_discovery_candidates_v1%rowtype;
  v_domain text; v_country text; v_conflicts text[];
begin
  if (select auth.uid()) is null then raise exception using errcode='42501',message='authentication_required'; end if;
  if p_status not in ('new','review','rejected','duplicate') then raise exception using errcode='22023',message='invalid_review_status'; end if;
  select * into c from public.pppp_representation_discovery_candidates_v1 where id=p_candidate_id for update;
  if not found then raise exception using errcode='P0002',message='representation_discovery_candidate_not_found'; end if;
  if c.status='accepted' then raise exception using errcode='22023',message='accepted_candidate_is_immutable'; end if;
  v_domain:=public.pppp_normalize_company_domain_v1(coalesce(p_company_domain,c.company_domain));
  v_country:=upper(coalesce(nullif(btrim(p_country_code),''),c.country_code));
  if v_country is not null and v_country !~ '^[A-Z]{2}$' then raise exception using errcode='22023',message='country_code_iso2_required'; end if;
  v_conflicts:=case when c.candidate_kind='company' then public.pppp_representation_discovery_conflicts_v1(v_domain) else '{}'::text[] end;
  update public.pppp_representation_discovery_candidates_v1 set
    company_name=case when candidate_kind='company' then coalesce(nullif(btrim(p_company_name),''),company_name) else company_name end,
    company_domain=case when candidate_kind='company' then v_domain else company_domain end,
    country_code=case when candidate_kind='company' then v_country else country_code end,
    routing_conflicts=v_conflicts,status=p_status,review_note=nullif(btrim(p_review_note),''),
    reviewed_at=now(),reviewed_by=(select auth.uid())
  where id=c.id;
  return jsonb_build_object('ok',true,'candidate_id',c.id,'status',p_status,'routing_conflicts',v_conflicts,
    'active_record_created',false,'project_created',false,'outbound_created',false);
end;
$_$;


ALTER FUNCTION public.pppp_review_representation_discovery_candidate_v1(p_candidate_id uuid, p_company_name text, p_company_domain text, p_country_code text, p_status text, p_review_note text) OWNER TO postgres;

--
-- Name: pppp_rfq_draft_quality_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_rfq_draft_quality_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  p record;
  v_bom_rows integer := 0;
  v_review_rows integer := 0;
  v_total_kg numeric := 0;
  v_profiles text := '';
  v_dims text := '';
  v_grades text := '';
  v_standards text := '';
  v_certs text := '';
  v_surfaces text := '';
  v_material_only boolean := false;
  v_doc text := '';
  v_lang text := 'en';
  v_greeting text := '';
  v_name text := '';
  v_tech text := '';
  v_review_note text := '';
  v_request text := '';
  v_signature text := E'Arianit Vllahiu\nPRISTEEL Sh.p.k.\nsales@prissteel.com\n+383 44 244 699';
begin
  if new.project_id is null
     or new.sent_at is not null
     or lower(coalesce(new.status,'')) not in ('draft','draft_review')
     or coalesce(new.notes,'') not like 'PPPP_LOCAL_SEMANTIC_V4|%'
  then
    return new;
  end if;

  select id,name,client,business_type,deal_type,notes,drive_folder_url,drive_folder_id
    into p
  from public.projects
  where id=new.project_id;

  if not found then return new; end if;

  select count(*),
         count(*) filter (where coalesce(needs_review,false)),
         coalesce(sum(kg),0)
    into v_bom_rows,v_review_rows,v_total_kg
  from public.bom_items
  where project_id=new.project_id;

  select coalesce(string_agg(x, ', ' order by x),'') into v_profiles
  from (select distinct trim(profile) x from public.bom_items where project_id=new.project_id and nullif(trim(profile),'') is not null order by 1 limit 16) s;
  select coalesce(string_agg(x, '; ' order by x),'') into v_dims
  from (select distinct trim(coalesce(dim,dimensionet)) x from public.bom_items where project_id=new.project_id and nullif(trim(coalesce(dim,dimensionet)),'') is not null order by 1 limit 16) s;
  select coalesce(string_agg(x, ', ' order by x),'') into v_grades
  from (select distinct trim(coalesce(grade,materiali)) x from public.bom_items where project_id=new.project_id and nullif(trim(coalesce(grade,materiali)),'') is not null order by 1 limit 12) s;
  select coalesce(string_agg(x, ', ' order by x),'') into v_standards
  from (select distinct trim(std) x from public.bom_items where project_id=new.project_id and nullif(trim(std),'') is not null order by 1 limit 12) s;
  select coalesce(string_agg(x, ', ' order by x),'') into v_certs
  from (select distinct trim(cert) x from public.bom_items where project_id=new.project_id and nullif(trim(cert),'') is not null order by 1 limit 12) s;
  select coalesce(string_agg(x, '; ' order by x),'') into v_surfaces
  from (select distinct trim(surface) x from public.bom_items where project_id=new.project_id and nullif(trim(surface),'') is not null order by 1 limit 12) s;

  v_material_only := (
      lower(coalesce(p.business_type,''))='trading'
      or lower(coalesce(p.name,'')||' '||coalesce(p.notes,'')) ~ '(heavy[ -]?plate|marine[- ]?grade|raw material|material supply|furnizim|supply of|steel plate)'
    ) and coalesce(v_profiles,'')='';

  v_doc := coalesce(nullif(trim(p.drive_folder_url),''),
            case when nullif(trim(p.drive_folder_id),'') is not null then 'https://drive.google.com/drive/folders/'||trim(p.drive_folder_id) else '' end);
  v_lang := lower(coalesce(nullif(trim(new.lang),''),'en'));
  v_greeting := split_part(coalesce(new.body,''), E'\n', 1);
  if trim(v_greeting)='' then
    v_greeting := case when v_lang='de' then 'Guten Tag,' when v_lang='sr' then 'Poštovani,' when v_lang='sq' then 'Përshëndetje,' else 'Hello,' end;
  elsif v_lang='sq' and lower(v_greeting) like 'hello %' then
    v_greeting := 'Përshëndetje '||regexp_replace(v_greeting,'^[Hh]ello\s+','');
  end if;

  v_name := coalesce(nullif(trim(p.name),''),nullif(trim(new.project_name),''),'Project');

  v_tech := '- Total BOM weight: '||trim(to_char(v_total_kg,'FM999G999G999G990D00'))||' kg';
  if v_grades<>'' then v_tech := v_tech||E'\n- Grade(s): '||v_grades; end if;
  if v_material_only and v_dims<>'' then v_tech := v_tech||E'\n- Plate / material dimensions: '||v_dims; end if;
  if not v_material_only and v_profiles<>'' then v_tech := v_tech||E'\n- Main profiles / items: '||v_profiles; end if;
  if v_standards<>'' then v_tech := v_tech||E'\n- Standard(s): '||v_standards; end if;
  if v_certs<>'' then v_tech := v_tech||E'\n- Certificate(s): '||v_certs; end if;
  if v_surfaces<>'' then v_tech := v_tech||E'\n- Surface treatment: '||v_surfaces; end if;

  if v_review_rows>0 then
    v_review_note := case when v_lang='sq' then E'\n\nShënim: BOM-i është paraprak dhe '||v_review_rows||' rreshta kërkojnë ende verifikim teknik. Ju lutem bazojeni ofertën në dokumentacion dhe shënoni qartë çdo supozim ose devijim.'
      when v_lang='sr' then E'\n\nNapomena: BOM je preliminaran i '||v_review_rows||' stavki još zahteva tehničku proveru. Molimo bazirajte ponudu na projektnoj dokumentaciji i jasno navedite sve pretpostavke ili odstupanja.'
      when v_lang='de' then E'\n\nHinweis: Die BOM ist vorläufig; '||v_review_rows||' Positionen benötigen noch technische Prüfung. Bitte stützen Sie Ihr Angebot auf die Projektdokumentation und kennzeichnen Sie Annahmen oder Abweichungen eindeutig.'
      else E'\n\nNote: the BOM is preliminary and '||v_review_rows||' rows still require technical verification. Please base your quotation on the project documentation and clearly identify all assumptions or deviations.' end;
    new.status := 'draft_review';
  end if;

  if v_doc='' then new.status := 'draft_review'; end if;

  if v_lang='sq' then
    v_request := case when v_material_only
      then 'Ju lutem dërgoni ofertën për furnizimin e materialit sipas specifikimit më poshtë. Përfshini çmimin për njësi dhe total, disponueshmërinë, fabrikën/origjinën, afatin e furnizimit, Incoterm-in, transportin dhe kushtet e pagesës. Konfirmoni certifikatat e kërkuara; nëse trajtimi sipërfaqësor nuk përfshihet, shënojeni qartë.'
      else 'Ju lutem dërgoni ofertën për material + fabrikim sipas dokumentacionit. Përfshini trajtimin sipërfaqësor të kërkuar, transportin, afatin e dorëzimit, Incoterm-in dhe kushtet e pagesës. Shënoni qartë çdo paqartësi, përjashtim ose devijim teknik.' end;
    new.body := v_greeting||E'\n\n'||v_request||E'\n\nProjekti:\n'||v_name||E'\n\nBaza teknike:\n'||v_tech||case when v_doc<>'' then E'\n\nDokumentacioni:\n'||v_doc else '' end||v_review_note||E'\n\nPërshëndetje,\n'||v_signature;
  elsif v_lang='sr' then
    v_request := case when v_material_only
      then 'Molimo dostavite ponudu za isporuku materijala prema specifikaciji ispod. Uključite jediničnu i ukupnu cenu, raspoloživost, proizvođača/poreklo, rok isporuke, Incoterm, transport i uslove plaćanja. Potvrdite tražene sertifikate; ako površinska zaštita nije uključena, navedite to jasno.'
      else 'Molimo dostavite ponudu za materijal + izradu prema projektnoj dokumentaciji. Uključite traženu površinsku zaštitu, transport, rok isporuke, Incoterm i uslove plaćanja. Sve nejasnoće, isključenja ili tehnička odstupanja jasno navedite.' end;
    new.body := v_greeting||E'\n\n'||v_request||E'\n\nProjekat:\n'||v_name||E'\n\nTehnička osnova:\n'||v_tech||case when v_doc<>'' then E'\n\nProjektna dokumentacija:\n'||v_doc else '' end||v_review_note||E'\n\nSrdačan pozdrav,\n'||v_signature;
  elsif v_lang='de' then
    v_request := case when v_material_only
      then 'Bitte senden Sie uns Ihr Angebot für die Materiallieferung gemäß der untenstehenden Spezifikation. Bitte geben Sie Stück-/Einheitspreis und Gesamtpreis, Verfügbarkeit, Werk/Ursprung, Lieferzeit, Incoterm, Transport und Zahlungsbedingungen an. Bestätigen Sie die geforderten Zeugnisse; falls die Oberflächenbehandlung nicht enthalten ist, kennzeichnen Sie dies eindeutig.'
      else 'Bitte senden Sie uns Ihr Angebot für Material + Fertigung gemäß Projektdokumentation. Bitte berücksichtigen Sie die erforderliche Oberflächenbehandlung, Transport, Lieferzeit, Incoterm und Zahlungsbedingungen und kennzeichnen Sie Unklarheiten, Ausschlüsse oder technische Abweichungen eindeutig.' end;
    new.body := v_greeting||E'\n\n'||v_request||E'\n\nProjekt:\n'||v_name||E'\n\nTechnische Grundlage:\n'||v_tech||case when v_doc<>'' then E'\n\nProjektdokumentation:\n'||v_doc else '' end||v_review_note||E'\n\nMit freundlichen Grüßen\n'||v_signature;
  else
    v_request := case when v_material_only
      then 'Please provide your quotation for material supply according to the specification below. Include unit and total price, availability, mill/origin, lead time, Incoterm, transport and payment terms. Confirm the required certificates; if surface treatment is not included, state this clearly.'
      else 'Please provide your quotation for material + fabrication according to the project documentation. Include the required surface treatment, transport, delivery time, Incoterm and payment terms. Clearly identify any ambiguity, exclusion or technical deviation.' end;
    new.body := v_greeting||E'\n\n'||v_request||E'\n\nProject:\n'||v_name||E'\n\nTechnical basis:\n'||v_tech||case when v_doc<>'' then E'\n\nProject documentation:\n'||v_doc else '' end||v_review_note||E'\n\nKind regards,\n'||v_signature;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_rfq_draft_quality_guard_v1() OWNER TO postgres;

--
-- Name: pppp_rfq_single_current_review_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_rfq_single_current_review_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status='draft_review' then
    update public.rfq_log r
    set status='superseded',
        notes=concat_ws(E'\n',nullif(r.notes,''),'Auto-reconciled by PPPP: superseded by a newer RFQ review revision.')
    where r.id<>new.id
      and r.status='draft_review'
      and r.project_id is not distinct from new.project_id
      and lower(btrim(coalesce(r.supplier_email,'')))=lower(btrim(coalesce(new.supplier_email,'')))
      and coalesce(r.subject,'')=coalesce(new.subject,'');
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_rfq_single_current_review_v1() OWNER TO postgres;

--
-- Name: pppp_route_tender_business_intent_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_route_tender_business_intent_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_source text := upper(coalesce(new.payload->>'source','KRPP'));
  v_phase text := lower(coalesce(new.payload->>'notice_phase','opportunity'));
  v_country text := upper(coalesce(new.payload->>'country',''));
  v_text text;
  v_company_type text;
  v_enriched boolean := false;
  v_has_winner boolean := false;
  v_next_check text;
  v_kosovo boolean := false;
  v_active boolean := coalesce(new.status,'new') <> 'ignored';
  v_low_fit boolean := false;
  v_pristeel_fit boolean := false;
  v_candidate_routes jsonb := jsonb_build_array(
    'direct_bid',
    'fabricated_steel_package',
    'material_supply',
    'external_production_capacity',
    'local_epc_partner',
    'jv_consortium',
    'representation_market_entry',
    'oem_specialist_partner',
    'competitor_intelligence'
  );
begin
  new.payload := coalesce(new.payload,'{}'::jsonb);

  v_text := lower(
    coalesce(new.title,'') || ' ' ||
    coalesce(new.fpp_description,'') || ' ' ||
    coalesce(new.payload->>'short_description','') || ' ' ||
    coalesce(new.payload->>'description','')
  );

  v_kosovo :=
       v_source in ('KRPP','MCA_KOSOVO')
    or v_country like 'XK%'
    or v_country like 'KOS%'
    or lower(coalesce(new.authority,'')) like '%kosov%'
    or lower(coalesce(new.title,'')) like '%kosov%';

  -- Strong negatives are only for partnership-expansion handoff.
  -- They do NOT remove the tender from Mundësitë.
  v_low_fit :=
       v_text ~ '(cadastre|kadastr|office furniture|mobileri|vehicle body parts repair|software development|property administration|rental scheme platform)'
    or (v_text ~ '(platform|platforme)' and v_text ~ '(software|digital|tregtim.*energj|administration|rental)')
    or (v_text ~ '(lighting system|sistem.*ndri[cç])' and v_text ~ '(office|zyr)')
    or v_text ~ '(kushineta|bearing|aparat.*saldim|welding machine)'
    or v_text ~ '(fertigungskapazit[aä]tstest|pristeel.*test)';

  v_pristeel_fit :=
    v_active
    and not v_low_fit
    and (
      coalesce(new.payload->>'capability_direct_evidence','false') = 'true'
      or (
        lower(coalesce(new.category,'')) in ('steel_structure','raw_material')
        and coalesce(new.relevance_score,0) >= 60
      )
      or v_text ~ '(çelik|celik|steel|metall|metalike|metallic|konstruks|construct.*steel|structural steel|fabricat|shufr|gyp|tube|pipe|plate|profil|rezervuar|tank|termocentral|power plant|substation|substacion|transmission|transmet|grid|rrjet.*energ|tower|pylon|pole|shtyll|gantry|bridge|urë|ure |railway|hekurudh|impiant|plant industrial|industrial plant|wastewater|ujër.*zeza|ujer.*zeza|district heating|ngrohje qendrore|conveyor|transportues|pipe rack|solar|photovolta|battery|bess|energy storage|wind farm|warehouse|hangar|steel hall|kulm|mbuloj|steel roof|facad|stair.*steel|shkall.*metal|rrethoj.*metal|guardrail|mining|processing plant)'
    );

  new.payload := new.payload || jsonb_build_object(
    'candidate_business_routes', v_candidate_routes,
    'route_screening_status',
      case when not v_active then 'not_active'
           when v_pristeel_fit then 'pending_business_route_screening'
           else 'pending_relevance_review' end,
    'business_mode_v2','multi_route_screening',
    'partnership_routes',jsonb_build_array(
      'local_epc_partner',
      'jv_consortium',
      'representation_market_entry',
      'oem_specialist_partner',
      'competitor_intelligence'
    ),
    'pristeel_relevance_gate',
      case when not v_active then 'not_active'
           when v_pristeel_fit then 'strong'
           else 'review' end,
    'partnership_expansion_required',
      (v_pristeel_fit and v_kosovo and v_phase in ('pipeline','opportunity','award')),
    'partnership_expansion_market',
      case when v_kosovo then 'kosovo' else 'regional_or_external' end,
    'partner_target_creation_requires_human_approval',true,
    'multi_route_policy','pristeel-multiroute-v1.1'
  );

  if v_source = 'TED' and v_phase = 'opportunity' then
    if v_kosovo and v_pristeel_fit then
      if coalesce(new.status,'new') in ('new','watch') then new.status := 'review'; end if;
      if new.deadline is not null then v_next_check := (new.deadline + 1)::text; else v_next_check := null; end if;
      new.payload := new.payload || jsonb_build_object(
        'workflow_track','ted_partnership_screening',
        'business_mode','watch_award',
        'human_action_required',true,
        'next_check_on',v_next_check,
        'wait_reason','Award watch continues, but JV/consortium/representation/OEM screening is active before award.'
      );
    else
      if coalesce(new.status,'new') in ('new','review') then new.status := 'watch'; end if;
      if new.deadline is not null then v_next_check := (new.deadline + 1)::text; else v_next_check := null; end if;
      new.payload := new.payload || jsonb_build_object(
        'workflow_track','ted_watch',
        'business_mode','watch_award',
        'human_action_required',false,
        'next_check_on',v_next_check,
        'wait_reason','Open TED notice: keep award watch; partnership expansion activates only after PriSteel relevance screening.'
      );
    end if;
    return new;
  end if;

  if v_source = 'TED' and v_phase = 'award' then
    v_has_winner := coalesce(new.payload#>>'{winner,name}','') <> '';
    v_enriched := jsonb_typeof(new.payload#>'{winner,contact_enrichment}') = 'object';
    v_company_type := lower(coalesce(new.payload#>>'{winner,company_type}','unknown'));
    if v_company_type not in ('producer','gc_epc','trader_consortium','unknown') then v_company_type := 'unknown'; end if;

    if jsonb_typeof(new.payload->'winner') = 'object' then
      new.payload := jsonb_set(new.payload,'{winner,company_type}',to_jsonb(v_company_type),true);
    end if;

    if not v_has_winner then
      if coalesce(new.status,'new') in ('new','review') then new.status := 'watch'; end if;
    elsif v_enriched then
      if coalesce(new.status,'new') in ('new','watch') then new.status := 'review'; end if;
    else
      if coalesce(new.status,'new') = 'new' then new.status := 'watch'; end if;
    end if;

    new.payload := new.payload || jsonb_build_object(
      'workflow_track','ted_award_sales',
      'business_mode','winner_outreach',
      'human_action_required',(new.status='review'),
      'company_verification_required',(v_company_type='unknown'),
      'cooperation_angle',case
        when v_company_type='producer' then 'additional_fabrication_capacity'
        when v_company_type='gc_epc' then 'steel_fabrication_subcontractor'
        when v_company_type='trader_consortium' then 'verify_supply_or_fabrication_role'
        else 'verify_company_role'
      end
    );
    return new;
  end if;

  if v_phase = 'opportunity' and v_source in ('KRPP','APP','APP_AL') then
    new.payload := new.payload || jsonb_build_object(
      'workflow_track','direct_tender',
      'business_mode','direct_bid',
      'human_action_required',(coalesce(new.status,'new') in ('new','review')),
      'direct_bid_is_not_exclusive',true
    );
    return new;
  end if;

  if v_phase = 'award' and v_source in ('KRPP','APP','APP_AL') then
    if new.project_id is null and coalesce(new.status,'new') in ('new','review') then new.status := 'watch'; end if;
    new.payload := new.payload || jsonb_build_object(
      'workflow_track','direct_tender_result',
      'human_action_required',(new.project_id is not null and new.status='review')
    );
    return new;
  end if;

  if v_source in ('WORLD_BANK','MCA_KOSOVO','EBRD','WBIF','EIB','KFW','UNGM','KCF') then
    new.payload := new.payload || jsonb_build_object(
      'workflow_track',coalesce(nullif(new.payload->>'workflow_track',''),'ifi_tender_screening'),
      'human_action_required',
        case when v_kosovo and v_pristeel_fit then true
             else coalesce((new.payload->>'human_action_required')::boolean,false) end
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_route_tender_business_intent_v1() OWNER TO postgres;

--
-- Name: pppp_selected_supplier_handoff_reconcile_v1(boolean, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_selected_supplier_handoff_reconcile_v1(p_apply boolean DEFAULT false, p_limit integer DEFAULT 100, p_project_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  r record;
  v_limit integer:=least(500,greatest(1,coalesce(p_limit,100)));
  v_analysis jsonb;
  v_analysis_id bigint;
  v_projects integer:=0;
  v_tasks integer:=0;
  v_closed integer:=0;
  v_analyses integer:=0;
begin
  for r in
    select *
    from public.pppp_selected_supplier_cost_basis_v1 c
    where p_project_id is null or c.project_id=p_project_id
    order by c.decided_at desc,c.project_name
    limit v_limit
  loop
    v_projects:=v_projects+1;

    v_analysis:=jsonb_build_object(
      'human_gate_required',true,
      'project_id',r.project_id,
      'project_name',r.project_name,
      'client',r.client,
      'decision',jsonb_build_object(
        'decision_id',r.decision_id,
        'decision_type',r.decision_type,
        'supplier',r.selected_supplier,
        'supplier_offer_id',r.supplier_offer_id,
        'source',r.decision_source,
        'decided_at',r.decided_at,
        'evidence',r.decision_evidence
      ),
      'supplier_cost_basis',jsonb_build_object(
        'currency',r.currency,
        'pricing_basis',r.pricing_basis,
        'price_kg',r.price_kg,
        'unit_price',r.unit_price,
        'unit_cost_eur',r.unit_cost_eur,
        'qty_kg',r.qty_kg,
        'total_amount',r.total_amount,
        'explicit_total_eur',r.explicit_total_eur,
        'exchange_rate_to_eur',r.exchange_rate_to_eur,
        'transport_eur',r.transport_eur,
        'zinc_kg',r.zinc_kg,
        'delivery_weeks',r.delivery_weeks,
        'incoterms',r.incoterms,
        'payment_terms',r.payment_terms,
        'validity_days',r.validity_days,
        'cert',r.cert,
        'offer_ref',r.offer_ref,
        'inclusions',r.inclusions,
        'exclusions',r.exclusions
      ),
      'cost_basis_readiness',r.cost_basis_readiness,
      'warnings',r.warning_text,
      'client_price_policy','Human must set markup/margin, final client price, client commercial terms and inclusions/exclusions. PPPP does not calculate or approve final client price automatically.'
    );

    if p_apply then
      select pa.id into v_analysis_id
      from public.project_analyses pa
      where pa.project_id=r.project_id::text and pa.model='selected-supplier-cost-basis-v1'
      order by pa.created_at desc limit 1;

      if v_analysis_id is null then
        insert into public.project_analyses(project_id,status,engine,model,analysis,source_manifest,source_counts,created_at)
        values(
          r.project_id::text,'complete','commercial_rules','selected-supplier-cost-basis-v1',v_analysis,
          jsonb_build_object('decision_id',r.decision_id,'supplier_offer_id',r.supplier_offer_id),
          jsonb_build_object('selected_supplier_decisions',1,'selected_offers',case when r.supplier_offer_id is null then 0 else 1 end),
          now()
        );
      else
        update public.project_analyses
        set status='complete',engine='commercial_rules',analysis=v_analysis,
            source_manifest=jsonb_build_object('decision_id',r.decision_id,'supplier_offer_id',r.supplier_offer_id),
            source_counts=jsonb_build_object('selected_supplier_decisions',1,'selected_offers',case when r.supplier_offer_id is null then 0 else 1 end),
            created_at=now()
        where id=v_analysis_id;
      end if;
      v_analyses:=v_analyses+1;

      update public.tasks
      set status='mbyllur',done_at=coalesce(done_at,now())
      where project_id=r.project_id and source='procurement_comparison_auto' and status='hapur';

      if r.eligible_for_client_offer_handoff then
        insert into public.tasks(project_id,title,detail,due_date,priority,status,source,category,source_ref)
        values(
          r.project_id,
          case when r.cost_basis_readiness='blocked' then 'Përgatit ofertën për klientin · BLOCKER · ' else 'Përgatit ofertën për klientin · ' end||left(r.project_name,145),
          'Supplier i zgjedhur nga njeriu: '||coalesce(r.selected_supplier,'—')||E'\n'||
          'Baza kanonike e kostos: '||
          case
            when r.price_kg is not null then coalesce(r.currency,'?')||' '||round(r.price_kg,4)::text||'/kg'||coalesce(' · EUR '||round(r.unit_cost_eur,4)::text||'/kg',case when upper(coalesce(r.currency,''))='EUR' then '' end)
            when r.unit_price is not null then coalesce(r.currency,'?')||' '||round(r.unit_price,4)::text||'/'||upper(coalesce(r.pricing_basis,'unit'))||coalesce(' · EUR '||round(r.unit_cost_eur,4)::text||'/'||upper(coalesce(r.pricing_basis,'unit')),case when upper(coalesce(r.currency,''))='EUR' then '' end)
            when r.explicit_total_eur is not null then 'EUR total '||round(r.explicit_total_eur,2)::text
            else '—'
          end||
          coalesce(E'\nSasia: '||round(r.qty_kg,3)::text||' kg','')||
          coalesce(E'\nSupplier total explicit EUR: '||round(r.explicit_total_eur,2)::text,'')||
          coalesce(E'\nDelivery: '||r.delivery_weeks::text||' javë','')||
          coalesce(E'\nIncoterms: '||r.incoterms,'')||
          coalesce(E'\nPayment: '||r.payment_terms,'')||
          coalesce(E'\nValidity: '||r.validity_days::text||' ditë','')||
          coalesce(E'\nCertificate: '||r.cert,'')||
          case when coalesce(r.warning_text,'')<>'' then E'\n\nKontrolle para ofertës:\n'||r.warning_text else '' end||
          E'\n\nHuman gate: vendos markup/margin, çmimin final për klientin, kushtet komerciale të klientit dhe inclusions/exclusions. PPPP nuk vendos final price dhe nuk dërgon ofertë automatikisht.',
          current_date,'larte','hapur','client_offer_cost_basis_auto','ofertim','COMMERCIAL:'||r.project_id::text||':client-offer-cost-basis'
        )
        on conflict(source,source_ref) do update
          set project_id=excluded.project_id,title=excluded.title,detail=excluded.detail,due_date=current_date,
              priority='larte',status='hapur',done_at=null;
        v_tasks:=v_tasks+1;

        update public.projects
        set pipeline_stage=case when pipeline_stage in ('rfq_in','technical_review','supplier_selection') then 'pricing' else pipeline_stage end,
            updated_at=now()
        where id=r.project_id;
      end if;
    end if;
  end loop;

  if p_apply then
    with closed as (
      update public.tasks t
      set status='mbyllur',done_at=coalesce(done_at,now())
      where t.source='client_offer_cost_basis_auto'
        and t.status='hapur'
        and (p_project_id is null or t.project_id=p_project_id)
        and not exists(
          select 1 from public.pppp_selected_supplier_cost_basis_v1 c
          where c.project_id=t.project_id and c.eligible_for_client_offer_handoff
        )
      returning id
    ) select count(*)::int into v_closed from closed;
  end if;

  return jsonb_build_object(
    'mode',case when p_apply then 'apply' else 'preview' end,
    'selected_supplier_projects_seen',v_projects,
    'analyses_refreshed',v_analyses,
    'client_offer_tasks_opened_or_refreshed',v_tasks,
    'client_offer_tasks_closed',v_closed,
    'generated_at',now()
  );
end;
$$;


ALTER FUNCTION public.pppp_selected_supplier_handoff_reconcile_v1(p_apply boolean, p_limit integer, p_project_id uuid) OWNER TO postgres;

--
-- Name: pppp_semantic_email_task_freshness_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_semantic_email_task_freshness_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_msg_id text;
  v_sent_at timestamptz;
  v_state_at timestamptz;
  v_note text := 'PPPP: semantic email action suppressed because the source email is not newer than the current canonical project state.';
begin
  if coalesce(new.source,'') <> 'semantic_brain_auto' then
    return new;
  end if;

  if coalesce(new.source_ref,'') like 'semantic:email:%' then
    v_msg_id := substring(new.source_ref from length('semantic:email:') + 1);
  elsif coalesce(new.source_ref,'') like 'email:event:%' then
    v_msg_id := substring(new.source_ref from length('email:event:') + 1);
  else
    return new;
  end if;

  select pe.sent_at, p.operational_state_at
    into v_sent_at, v_state_at
  from public.projects p
  left join public.project_emails pe
    on pe.project_id=p.id and pe.gmail_message_id=v_msg_id
  where p.id=new.project_id;

  if v_sent_at is null or (v_state_at is not null and v_sent_at <= v_state_at) then
    new.status := 'mbyllur';
    new.done_at := coalesce(new.done_at,now());
    if position(v_note in coalesce(new.detail,''))=0 then
      new.detail := concat_ws(E'\n',nullif(new.detail,''),v_note);
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_semantic_email_task_freshness_guard() OWNER TO postgres;

--
-- Name: FUNCTION pppp_semantic_email_task_freshness_guard(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_semantic_email_task_freshness_guard() IS 'Suppresses semantic email tasks whose source email is missing or not newer than the canonical project state; supports legacy semantic:email and current email:event source_ref formats.';


--
-- Name: pppp_semantic_material_routing_scope_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_semantic_material_routing_scope_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_text text := '';
  v_caps jsonb := '[]'::jsonb;
  v_profiles jsonb := '[]'::jsonb;
begin
  if new.payload is null then return new; end if;

  v_caps := coalesce(new.payload->'deterministic'->'required_capabilities','[]'::jsonb);
  v_profiles := coalesce(new.payload->'bom'->'profiles','[]'::jsonb);

  select lower(concat_ws(' ',coalesce(name,''),coalesce(notes,''),coalesce(deal_type,'')))
    into v_text
  from public.projects
  where id=new.project_id;

  -- Material-only heavy-plate procurement must route to mills/traders, not fabricators.
  -- This rule is generic: heavy_plate detected, no structural profiles in BOM,
  -- and project evidence identifies plate/material trading/import/shipbuilding scope.
  if v_caps ? 'heavy_plate'
     and jsonb_array_length(v_profiles)=0
     and v_text ~ '(heavy[ -]?plate|steel trading|plate import|marine[- ]grade|shipbuilding|marine grade|pllak[aë]?[[:space:]-]*(çel|cel)|material supply)'
  then
    new.payload := jsonb_set(new.payload,'{deterministic,required_capabilities}','["heavy_plate"]'::jsonb,true);
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_semantic_material_routing_scope_guard() OWNER TO postgres;

--
-- Name: pppp_semantic_result_safety_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_semantic_result_safety_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_text text := '';
  v_sender_role text := '';
  v_has_stop boolean := false;
begin
  if coalesce(new.state,'') <> 'completed' or new.result is null then
    return new;
  end if;

  select lower(coalesce(string_agg(coalesce(x->>'label','') || ' ' || coalesce(x->>'text',''),' '),''))
    into v_text
  from jsonb_array_elements(coalesce(new.payload->'sources','[]'::jsonb)) x;

  v_sender_role := lower(coalesce(new.payload->'meta'->'latest_incoming'->>'sender_role',''));

  v_has_stop := v_text ~ '(stop|hold|suspend|pause)[^\n]{0,120}(fabrication|production|manufactur|weld|assembly)'
             or v_text ~ '(fabrication|production|manufactur|weld|assembly)[^\n]{0,120}(stop|hold|suspend|pause)'
             or v_text ~ 'ndal[^\n]{0,90}(prodh|fabrik)'
             or v_text ~ 'zaustav[^\n]{0,90}(proizvod|izrad)'
             or v_text ~ 'produktion[^\n]{0,90}(stop|halt)';

  if coalesce(new.result->>'category','') = 'production_change' and not v_has_stop then
    new.result := jsonb_set(new.result,'{category}',to_jsonb(case when v_sender_role='supplier' then 'supplier_update' else 'client_request' end),true);
    if coalesce(new.result->>'priority','') = 'critical' then
      new.result := jsonb_set(new.result,'{priority}','"high"'::jsonb,true);
    end if;
    new.result := new.result || jsonb_build_object('deterministic_category_override','production_change_not_supported_by_source');
  elsif v_has_stop then
    new.result := jsonb_set(new.result,'{action_required}','true'::jsonb,true);
    new.result := jsonb_set(new.result,'{priority}','"critical"'::jsonb,true);
    new.result := jsonb_set(new.result,'{category}','"production_change"'::jsonb,true);
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_semantic_result_safety_v1() OWNER TO postgres;

--
-- Name: pppp_semantic_routing_truth_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_semantic_routing_truth_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_grades jsonb := '[]'::jsonb;
  v_caps jsonb := '[]'::jsonb;
begin
  if coalesce(new.state,'') <> 'completed' or new.result is null then
    return new;
  end if;

  v_grades := coalesce(new.payload->'deterministic'->'required_grades','[]'::jsonb);
  v_caps := coalesce(new.payload->'deterministic'->'required_capabilities','[]'::jsonb);

  -- Supplier eligibility inputs are deterministic platform truth.
  -- Local AI may rank/summarize, but may not invent grades/capabilities that filter suppliers.
  new.result := jsonb_set(new.result,'{required_grades}',v_grades,true);
  new.result := jsonb_set(new.result,'{required_capabilities}',v_caps,true);
  return new;
end;
$$;


ALTER FUNCTION public.pppp_semantic_routing_truth_guard() OWNER TO postgres;

