-- Name: pppp_steel_buyer_company_analysis_trg_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_steel_buyer_company_analysis_trg_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if pg_trigger_depth()>1 then return new; end if;
  perform public.pppp_steel_buyer_company_analysis_v1(new.id);
  return new;
end;
