ALTER FUNCTION public.pppp_steel_buyer_company_analysis_trg_v1() OWNER TO postgres;

--
-- Name: pppp_steel_buyer_company_analysis_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_steel_buyer_company_analysis_v1(p_target_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  t public.pppp_dach_steel_targets_v1%rowtype; c public.pppp_company_identity_v1%rowtype;
  profile jsonb; facts jsonb:='[]'::jsonb; missing jsonb:='[]'::jsonb;
  activity text; size_value text; potential text; tonnes_min numeric; tonnes_max numeric; analysis_value text;
begin
  select * into t from public.pppp_dach_steel_targets_v1 where id=p_target_id;
  if not found then raise exception using errcode='P0002',message='steel_buyer_target_not_found'; end if;
  if t.canonical_company_id is not null then select * into c from public.pppp_company_identity_v1 where id=t.canonical_company_id; end if;
  profile:=coalesce(t.company_profile,'{}'::jsonb);
  activity:=coalesce(nullif(profile->>'primary_activity',''),nullif(t.primary_activity,''),nullif(t.buyer_type,''));
  size_value:=coalesce(nullif(profile->>'size_band',''),nullif(t.company_size_band,''),nullif(c.size_band,''),'unknown');
  if size_value not in ('micro','small','medium','large','enterprise','unknown') then size_value:='unknown'; end if;
  tonnes_min:=coalesce((nullif(profile->>'annual_steel_tonnes_min',''))::numeric,t.annual_steel_tonnes_min,c.annual_steel_tonnes_min);
  tonnes_max:=coalesce((nullif(profile->>'annual_steel_tonnes_max',''))::numeric,t.annual_steel_tonnes_max,c.annual_steel_tonnes_max);
  potential:=coalesce(nullif(profile->>'consumption_potential',''),nullif(t.consumption_potential,''),nullif(c.consumption_potential,''),'unknown');
  if potential='unknown' then
    potential:=case
      when tonnes_max>=1000 or lower(coalesce(activity,''))~'(ship|rail|trailer|heavy|machin|vehicle|industrial fabrication|steel service)' then 'high'
      when tonnes_max>=250 or lower(coalesce(activity,''))~'(stahlbau|metallbau|fabricat|manufacturer|producer|construction)' then 'medium'
      when nullif(activity,'') is not null then 'low' else 'unknown' end;
  end if;
  if nullif(activity,'') is not null then facts:=facts||jsonb_build_array('Aktiviteti kryesor: '||activity); else missing:=missing||'["primary_activity"]'::jsonb; end if;
  if size_value<>'unknown' then facts:=facts||jsonb_build_array('Madhësia e kompanisë: '||size_value); else missing:=missing||'["company_size"]'::jsonb; end if;
  if potential<>'unknown' then facts:=facts||jsonb_build_array('Potenciali i konsumit të çelikut: '||potential); else missing:=missing||'["steel_consumption_potential"]'::jsonb; end if;
  if tonnes_max is not null then facts:=facts||jsonb_build_array('Konsumi vjetor i vlerësuar: '||coalesce(tonnes_min::text,'0')||'–'||tonnes_max::text||' t'); else missing:=missing||'["annual_steel_tonnage"]'::jsonb; end if;
  if nullif(coalesce(t.procurement_model,c.procurement_model),'') is null then missing:=missing||'["procurement_model"]'::jsonb; end if;
  if nullif(coalesce(t.production_capacity_summary,c.production_capacity_summary),'') is null then missing:=missing||'["production_capacity"]'::jsonb; end if;
  if coalesce(jsonb_array_length(t.personalization_facts),0)>0 then facts:=facts||t.personalization_facts; end if;
  analysis_value:=case when jsonb_array_length(missing)=0 then 'verified' when jsonb_array_length(facts)>=2 then 'partial' else 'review_required' end;
  update public.pppp_dach_steel_targets_v1 set primary_activity=activity,company_size_band=size_value,
    consumption_potential=potential,annual_steel_tonnes_min=tonnes_min,annual_steel_tonnes_max=tonnes_max,
    verified_company_facts=facts,missing_company_facts=missing,company_analysis_status=analysis_value,last_company_analysis_at=now()
  where id=t.id;
  if t.canonical_company_id is not null then
    update public.pppp_company_identity_v1 set
      size_band=case when size_value='unknown' then public.pppp_company_identity_v1.size_band else size_value end,
      primary_activity=coalesce(activity,public.pppp_company_identity_v1.primary_activity),
      consumption_potential=case when potential='unknown' then public.pppp_company_identity_v1.consumption_potential else potential end,
      annual_steel_tonnes_min=coalesce(tonnes_min,public.pppp_company_identity_v1.annual_steel_tonnes_min),
      annual_steel_tonnes_max=coalesce(tonnes_max,public.pppp_company_identity_v1.annual_steel_tonnes_max),
      last_enriched_at=now(),updated_at=now() where id=t.canonical_company_id;
  end if;
  return jsonb_build_object('target_id',t.id,'company_id',t.canonical_company_id,'status',analysis_value,
    'size_band',size_value,'primary_activity',activity,'consumption_potential',potential,
    'annual_steel_tonnes_min',tonnes_min,'annual_steel_tonnes_max',tonnes_max,
    'verified_facts',facts,'missing_facts',missing);
end;
$$;


ALTER FUNCTION public.pppp_steel_buyer_company_analysis_v1(p_target_id uuid) OWNER TO postgres;

--
-- Name: pppp_steel_buyer_discovery_enrich_existing_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_steel_buyer_discovery_enrich_existing_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_target uuid;
begin
  if new.official_domain is null or new.status not in ('duplicate','accepted') then return new; end if;
  select id into v_target from public.pppp_dach_steel_targets_v1
  where target_status not in('closed','rejected','project_promoted')
    and public.pppp_normalize_company_domain_v1(coalesce(company_domain,company_website))=new.official_domain
  order by updated_at desc limit 1;
  if v_target is null then return new; end if;
  update public.pppp_dach_steel_targets_v1 set
    company_profile=coalesce(company_profile,'{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object(
      'primary_activity',new.industry,'size_band',new.size_band,'consumption_potential',new.consumption_potential,
      'employees',new.employees,'revenue',new.revenue_text,'discovery_source','wikidata_public_sparql'
    )),
    company_size_band=case when new.size_band='unknown' then company_size_band else new.size_band end,
    primary_activity=coalesce(new.industry,primary_activity),
    consumption_potential=case when new.consumption_potential='unknown' then consumption_potential else new.consumption_potential end,
    discovery_candidate_id=coalesce(discovery_candidate_id,new.id),
    last_verified_at=greatest(coalesce(last_verified_at,'epoch'::timestamptz),now()),
    updated_at=now()
  where id=v_target;
  update public.pppp_company_identity_v1 set
    size_band=case when new.size_band='unknown' then size_band else new.size_band end,
    employees_min=coalesce(new.employees,employees_min),employees_max=coalesce(new.employees,employees_max),
    revenue_band=coalesce(new.revenue_text,revenue_band),primary_activity=coalesce(new.industry,primary_activity),
    business_summary=coalesce(new.business_summary,business_summary),
    consumption_potential=case when new.consumption_potential='unknown' then consumption_potential else new.consumption_potential end,
    evidence=coalesce(evidence,'[]'::jsonb)||coalesce(new.evidence,'[]'::jsonb),
    confidence=greatest(confidence,0.65),last_enriched_at=now(),last_verified_at=now(),updated_at=now()
  where id=new.canonical_company_id;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_steel_buyer_discovery_enrich_existing_v1() OWNER TO postgres;

--
-- Name: pppp_steel_buyer_identity_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_steel_buyer_identity_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_domain text:=public.pppp_normalize_company_domain_v1(coalesce(new.company_domain,new.company_website));
  v_company uuid; v_conflicts text[]:='{}'::text[];
begin
  if nullif(v_domain,'') is null then raise exception using errcode='22023',message='steel_buyer_official_domain_required'; end if;
  new.company_domain:=v_domain;
  new.company_website:=coalesce(nullif(new.company_website,''),'https://'||v_domain);
  if tg_op='INSERT' then
    if exists(select 1 from public.pppp_eu_direct_targets_v1 e where e.archived_at is null and e.company_domain_normalized=v_domain) then v_conflicts:=array_append(v_conflicts,'eu_direct'); end if;
    if exists(select 1 from public.pppp_representation_targets_v1 r where r.archived_at is null and r.company_domain_normalized=v_domain) then v_conflicts:=array_append(v_conflicts,'representations'); end if;
    if exists(select 1 from public.pppp_opportunity_company_profiles_v1 o where public.pppp_normalize_company_domain_v1(o.domain)=v_domain) then v_conflicts:=array_append(v_conflicts,'opportunities'); end if;
    if cardinality(v_conflicts)>0 then raise exception using errcode='23505',message='cross_module_identity_review_required:'||array_to_string(v_conflicts,','); end if;
  end if;
  v_company:=public.pppp_company_identity_resolve_v1(new.company_name,v_domain,new.country,null,'steel_buyers');
  new.canonical_company_id:=v_company;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_steel_buyer_identity_guard_v1() OWNER TO postgres;

--
-- Name: pppp_supersede_new_project_handoff_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supersede_new_project_handoff_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.project_id is null or coalesce(new.source,'')='project_discovery_auto' or coalesce(new.status,'')<>'hapur' then return new; end if;
  update public.tasks
     set status='mbyllur',
         done_at=coalesce(done_at,now()),
         detail=case when position('PPPP: handoff u zëvendësua' in coalesce(detail,''))=0
                     then concat_ws(E'\n',nullif(detail,''),'PPPP: handoff u zëvendësua automatikisht nga veprimi më konkret: '||coalesce(new.title,new.source,'.'))
                     else detail end
   where project_id=new.project_id
     and source='project_discovery_auto'
     and status='hapur';
  return new;
end;
$$;


ALTER FUNCTION public.pppp_supersede_new_project_handoff_v1() OWNER TO postgres;

--
-- Name: pppp_supplier_coverage_v1(jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_coverage_v1(p_requirement jsonb, p_min_qualified integer DEFAULT 3, p_threshold integer DEFAULT 70) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with m as (
  select * from public.pppp_supplier_match_v1(p_requirement,100,p_threshold)
), x as (
  select count(*) filter(where qualified)::int capability_q,
         count(*) filter(where qualified and primary_email is not null)::int rfq_ready_q,
         count(*)::int total,
         coalesce(jsonb_agg(jsonb_build_object(
           'partner_id',partner_id,'name',partner_name,'country',country,'city',city,'email',primary_email,
           'score',match_score,'qualified',qualified,'rfq_ready',(qualified and primary_email is not null),'source_tier',source_tier,'reasons',match_reasons
         ) order by match_score desc) filter(where partner_id is not null),'[]'::jsonb) matches
  from m
)
select jsonb_build_object(
  'requirement',coalesce(p_requirement,'{}'::jsonb),
  'threshold',p_threshold,
  'min_qualified',p_min_qualified,
  'qualified_existing',x.rfq_ready_q,
  'capability_qualified_existing',x.capability_q,
  'rfq_ready_existing',x.rfq_ready_q,
  'matched_existing',x.total,
  'sufficient',x.rfq_ready_q>=greatest(1,coalesce(p_min_qualified,3)),
  'next_tier',case when x.rfq_ready_q>=greatest(1,coalesce(p_min_qualified,3)) then 'complete' else 'local' end,
  'matches',x.matches,
  'human_supplier_selection_required',true,
  'external_email_send_requires_human_approval',true,
  'generated_at',now()
) from x;
$$;


ALTER FUNCTION public.pppp_supplier_coverage_v1(p_requirement jsonb, p_min_qualified integer, p_threshold integer) OWNER TO postgres;

--
-- Name: pppp_supplier_email_rate_reactivity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_email_rate_reactivity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_match text[];
  v_tail text;
  v_rate numeric;
  v_persons int;
  v_days int;
  v_scope text;
  v_offer public.offers%rowtype;
  v_qty numeric;
  v_old_install numeric := 0;
  v_new_install numeric := 0;
  v_positions jsonb;
  v_install jsonb;
  v_total numeric;
  v_task uuid;
  v_supplier text;
  v_plan boolean;
  v_marker text;
begin
  if new.project_id is null
     or lower(coalesce(new.direction,'')) <> 'incoming'
     or coalesce(new.gmail_message_id,'') = ''
     or coalesce(new.snippet,'') = ''
     or new.snippet !~* 'montim|monta|asistenc' then
    return new;
  end if;

  v_tail := substring(new.snippet from '(?is)(?:montim|monta|asistenc).*$');
  v_match := regexp_match(
    coalesce(v_tail,new.snippet),
    '([0-9]+(?:[\.,][0-9]+)?)[[:space:]]*(?:€|EUR)[[:space:]]*/[[:space:]]*kg'
  );
  if v_match is null then return new; end if;

  v_rate := replace(v_match[1],',','.')::numeric;
  if v_rate <= 0 or v_rate > 20 then return new; end if;

  v_match := regexp_match(new.snippet,'(?i)([0-9]+)[[:space:]]*persona');
  if v_match is not null then v_persons := v_match[1]::int; end if;
  v_match := regexp_match(new.snippet,'(?i)([0-9]+)[[:space:]]*dit');
  if v_match is not null then v_days := v_match[1]::int; end if;

  v_scope := case when new.snippet ~* 'asistenc' then 'assistance_only' else 'installation_unverified' end;
  v_plan := new.snippet ~* 'plan[^[:alnum:]]*dinamik|dinamik[^[:alnum:]]*plan|schedule|timeline|zeitplan|terminplan';
  v_marker := '[gmail:' || new.gmail_message_id || ']';

  select o.* into v_offer
  from public.offers o
  where o.project_id = new.project_id
    and upper(coalesce(o.currency,'EUR')) = 'EUR'
    and (
      lower(coalesce(new.from_name,'')) = lower(coalesce(o.contact_person,''))
      or lower(coalesce(new.from_name,'')) like '%' || lower(coalesce(o.supplier,'')) || '%'
      or lower(coalesce(o.supplier,'')) like '%' || lower(coalesce(new.from_name,'')) || '%'
      or regexp_replace(lower(split_part(coalesce(new.from_email,''),'@',1)),'[^a-z0-9]','','g') like '%' || regexp_replace(lower(coalesce(o.supplier,'')),'[^a-z0-9]','','g') || '%'
    )
  order by case
    when lower(coalesce(new.from_name,'')) = lower(coalesce(o.contact_person,'')) then 0
    when lower(coalesce(new.from_name,'')) = lower(coalesce(o.supplier,'')) then 1
    else 2 end,
    o.created_at desc
  limit 1;

  if not found or position(v_marker in coalesce(v_offer.raw_text,'')) > 0 then return new; end if;

  v_qty := coalesce(v_offer.qty_kg,0);
  if v_qty <= 0 then
    select coalesce((x->>'qty')::numeric,0) into v_qty
    from jsonb_array_elements(coalesce(v_offer.positions,'[]'::jsonb)) x
    where lower(coalesce(x->>'key',''))='base' limit 1;
  end if;
  if v_qty <= 0 then return new; end if;

  select coalesce(sum(case
      when coalesce(x->>'total_neg','') <> '' then (x->>'total_neg')::numeric
      when coalesce(x->>'total_orig','') <> '' then (x->>'total_orig')::numeric
      else coalesce((x->>'qty')::numeric,0) * coalesce(nullif(x->>'price_neg','')::numeric,nullif(x->>'price_orig','')::numeric,0)
    end),0)
  into v_old_install
  from jsonb_array_elements(coalesce(v_offer.positions,'[]'::jsonb)) x
  where lower(coalesce(x->>'key','')) in ('install','installation');

  v_new_install := round(v_qty * v_rate,2);
  v_install := jsonb_strip_nulls(jsonb_build_object(
    'key','install','qty',v_qty,'unit','kg','price_orig',v_rate,'price_neg',v_rate,
    'total_orig',v_new_install,'total_neg',v_new_install,'scope',v_scope,'persons',v_persons,'days',v_days,
    'source_gmail_message_id',new.gmail_message_id,
    'desc',case when v_scope='assistance_only'
      then 'Asistence ne montim' || case when v_persons is not null then ' - '||v_persons||' persona' else '' end || case when v_days is not null then ' / '||v_days||' dite' else '' end
      else 'Montim - scope per verifikim' end
  ));

  select coalesce(jsonb_agg(case when lower(coalesce(e.elem->>'key','')) in ('install','installation') then v_install else e.elem end order by e.ord),'[]'::jsonb)
  into v_positions
  from jsonb_array_elements(coalesce(v_offer.positions,'[]'::jsonb)) with ordinality e(elem,ord);

  if not exists (select 1 from jsonb_array_elements(coalesce(v_offer.positions,'[]'::jsonb)) x where lower(coalesce(x->>'key','')) in ('install','installation')) then
    v_positions := v_positions || jsonb_build_array(v_install);
  end if;

  v_total := round(coalesce(v_offer.total_amount,v_offer.total_eur,0) - v_old_install + v_new_install,2);
  v_supplier := coalesce(v_offer.supplier,'Furnitori');

  update public.offers
  set positions=v_positions,total_eur=v_total,total_amount=v_total,
      notes=concat_ws(E'\n',nullif(coalesce(notes,''),''),'AUTO UPDATE nga email '||to_char(coalesce(new.sent_at,now()),'DD.MM.YYYY')||': montimi '||v_rate||' EUR/kg'||case when v_scope='assistance_only' then ' (asistence'||coalesce(' '||v_persons||' persona','')||coalesce(' / '||v_days||' dite','')||')' else ' (scope per verifikim)' end||case when v_plan then '; plani dinamik eshte bashkangjitur/permendur.' else '.' end),
      raw_text=concat_ws(E'\n\n',nullif(coalesce(raw_text,''),''),v_marker||' '||coalesce(new.snippet,'')),
      inclusions=case when v_scope='assistance_only' then concat_ws('; ',nullif(coalesce(inclusions,''),''),'Asistence ne montim '||coalesce(v_persons::text,'?')||' persona / '||coalesce(v_days::text,'?')||' dite @ '||v_rate||' EUR/kg') else inclusions end,
      exclusions=case when v_scope='assistance_only' then concat_ws('; ',nullif(coalesce(exclusions,''),''),'Montimi i plote nuk duhet supozuar nga cmimi i asistences pa konfirmim scope-i.') else exclusions end
  where id=v_offer.id;

  select t.id into v_task from public.tasks t
  where t.project_id=new.project_id and lower(coalesce(t.status,'')) not in ('kryer','done','mbyllur') and t.source='email_request_auto'
  order by t.created_at desc limit 1;

  if v_task is not null then
    update public.tasks set
      title='Urgjent: rishiko montimin + update-in e furnitorit — '||v_supplier,
      detail=concat_ws(E'\n',coalesce(detail,''),'UPDATE AUTOMATIK NGA FURNITORI:','• '||v_supplier||': '||v_rate||' EUR/kg për '||case when v_scope='assistance_only' then 'ASISTENCË NË MONTIM' else 'MONTIM (scope për verifikim)' end||'.',case when v_persons is not null or v_days is not null then '• Kufizimi: '||coalesce(v_persons::text,'?')||' persona / '||coalesce(v_days::text,'?')||' ditë.' else null end,case when v_plan then '• U pranua/permend edhe plan dinamik; attachment-i duhet të lexohet dhe aprovohet.' else null end,'• Mos e plotëso automatikisht ofertën e klientit vetëm nga çmimi i furnitorit; kërkohet human gate për scope dhe marzh.'),
      due_date=current_date,priority='e larte'
    where id=v_task;
  else
    insert into public.tasks(project_id,title,detail,due_date,priority,status,source,source_ref,contact_email,category)
    values(new.project_id,'Rishiko update-in e furnitorit — '||v_supplier,'Montimi: '||v_rate||' EUR/kg. '||case when v_scope='assistance_only' then 'Scope: asistencë, jo domosdoshmërisht montim i plotë.' else 'Scope për verifikim.' end||case when v_plan then ' U pranua/permend edhe plan dinamik.' else '' end,current_date,'e larte','hapur','supplier_update_auto',new.gmail_message_id,new.from_email,'furnitor');
  end if;

  if not exists (select 1 from public.project_analyses pa where pa.project_id=new.project_id::text and pa.analysis->>'event_source_ref'=new.gmail_message_id) then
    insert into public.project_analyses(project_id,status,engine,model,analysis,source_manifest,source_counts,created_at)
    values(new.project_id::text,'complete','db_supplier_update_rules','deterministic-supplier-email-v1',
      jsonb_build_object(
        'event_source_ref',new.gmail_message_id,
        'executive_summary','U pranua update i ri nga '||v_supplier||': '||v_rate||' EUR/kg për '||case when v_scope='assistance_only' then 'asistencë në montim' else 'montim' end||case when v_plan then ' dhe plan dinamik.' else '.' end,
        'current_stage','client_offer',
        'health',jsonb_build_object('label','vendim i ri komercial','score',82,'reason','Informacioni i furnitorit ndryshon bazën e vendimit dhe duhet reflektuar para finalizimit të ofertës.'),
        'confidence',jsonb_build_object('score',97,'reason','Çmimi u nxor drejtpërdrejt nga emaili i furnitorit të lidhur me projektin.'),
        'recommendation',jsonb_build_object('decision','human_gate_supplier_update','label','Rikrahaso ofertat dhe scope-in','reason','Çmimi i ri i montimit duhet krahasuar me furnitorët e tjerë dhe me scope-in para se të përdoret në ofertën e klientit.','source_ids',jsonb_build_array('E1','O1')),
        'next_actions',jsonb_build_array(jsonb_build_object('text','Krahaso '||v_supplier||' '||v_rate||' EUR/kg me alternativat e tjera dhe verifiko scope-in.','owner','PRISTEEL','priority','critical','status','open','source_ids',jsonb_build_array('E1','O1')),jsonb_build_object('text',case when v_plan then 'Lexo dhe aprovo planin dinamik të bashkangjitur para finalizimit të ofertës.' else 'Rikalkulo koston/marzhin pas zgjedhjes së montimit.' end,'owner','PRISTEEL','priority','high','status','open','source_ids',jsonb_build_array('E1'))),
        'risks',case when v_scope='assistance_only' then jsonb_build_array(jsonb_build_object('text','Çmimi i marrë është për asistencë në montim; nuk duhet trajtuar si montim i plotë pa konfirmim.','severity','critical','status','open','source_ids',jsonb_build_array('E1','O1'))) else '[]'::jsonb end,
        'missing_information',case when v_scope='assistance_only' then jsonb_build_array(jsonb_build_object('text','Scope i plotë i montimit','ask_to','supplier','priority','critical','why_needed','Për krahasim korrekt me ofertat e tjera.','source_ids',jsonb_build_array('E1'))) else '[]'::jsonb end,
        'requirements',jsonb_build_array(jsonb_build_object('text',v_supplier||': montim '||v_rate||' EUR/kg.','status','confirmed','category','commercial','priority','critical','source_ids',jsonb_build_array('E1','O1'))),
        'changes_since_last',jsonb_build_array(jsonb_build_object('text','U regjistrua çmim i ri i montimit nga furnitori.','status','confirmed','source_ids',jsonb_build_array('E1','O1'))),
        'deadlines','[]'::jsonb,'decisions','[]'::jsonb,'assumptions','[]'::jsonb,'scope','[]'::jsonb
      ),
      jsonb_build_array(jsonb_build_object('id','E1','type','email','label',new.subject,'meta',jsonb_build_object('gmail_message_id',new.gmail_message_id,'from',coalesce(new.from_name,new.from_email))),jsonb_build_object('id','O1','type','supplier_offer','label',v_supplier,'meta',jsonb_build_object('offer_id',v_offer.id,'installation_rate',v_rate,'installation_scope',v_scope,'total_eur',v_total))),
      jsonb_build_object('event_email',1,'supplier_offers',1),now());
  end if;

  update public.projects set updated_at=now() where id=new.project_id;
  return new;
end;
$_$;


ALTER FUNCTION public.pppp_supplier_email_rate_reactivity() OWNER TO postgres;

--
-- Name: pppp_supplier_family_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_family_v1(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
select case
  when lower(trim(coalesce(p_text,''))) in ('heavy_plate','sheet','profiles','tubes','hardware','mro','fabrication','coating','galvanizing','machining') then lower(trim(coalesce(p_text,'')))
  when lower(coalesce(p_text,'')) ~ '(galvan|zink|zinc|feuerverzink)' then 'galvanizing'
  when lower(coalesce(p_text,'')) ~ '(paint|coating|powder|plastifik|lackier|surface treatment)' then 'coating'
  when lower(coalesce(p_text,'')) ~ '(bolt|bulon|screw|nut|washer|fastener|anker|anchor)' then 'hardware'
  when lower(coalesce(p_text,'')) ~ '(shtyll|pole|mast)' then 'fabrication'
  when lower(coalesce(p_text,'')) ~ '(^|[^a-z0-9])(hop|rhs|shs|chs)[[:space:]]*[0-9]|(tube|pipe|rohr|tub)' then 'tubes'
  when lower(coalesce(p_text,'')) ~ '(^|[^a-z0-9])(hea|heb|hem|ipe|ipn|ipb|upn|upe)[[:space:]]*[0-9]|(channel|angle|profil|beam|round[[:space:]]*bar|flat[[:space:]]*bar|rod)|(^|[^a-z0-9])(2l|l)[[:space:]]*[0-9]' then 'profiles'
  when lower(coalesce(p_text,'')) ~ '(heavy[ _-]?plate|quarto|plate|pllak|blech)' then 'heavy_plate'
  when lower(coalesce(p_text,'')) ~ '(^|[^0-9])[0-9]{4,}[[:space:]]*[x×][[:space:]]*[0-9]{3,4}[[:space:]]*[x×][[:space:]]*[0-9]+([.,][0-9]+)?([^0-9]|$)' then 'heavy_plate'
  when lower(coalesce(p_text,'')) ~ '(sheet|coil|llamarin|lim)' then 'sheet'
  when lower(coalesce(p_text,'')) ~ '(fabricat|weld|fabrik|prodh|steelwork|konstruksion)' then 'fabrication'
  when lower(coalesce(p_text,'')) ~ '(mro|consumable|electrode|wire|welding consum|tool|abrasive)' then 'mro'
  else null
end;
$_$;


ALTER FUNCTION public.pppp_supplier_family_v1(p_text text) OWNER TO postgres;

--
-- Name: pppp_supplier_history_autolink(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_history_autolink() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_project uuid;
  v_count int;
begin
  if new.project_id is not null
     or lower(coalesce(new.direction,'')) <> 'incoming'
     or coalesce(new.from_email,'') = '' then
    return new;
  end if;

  if lower(trim(coalesce(new.from_email,''))) = 'eprokurimi@rks-gov.net' then
    return new;
  end if;

  if trim(lower(coalesce(new.subject,''))) in ('', '(pa subjekt)', '(no subject)') then
    return new;
  end if;

  with sender_projects as (
    select distinct pe.project_id
    from public.project_emails pe
    join public.projects p on p.id = pe.project_id
    where pe.project_id is not null
      and lower(coalesce(pe.from_email,'')) = lower(new.from_email)
      and lower(coalesce(p.status,'')) not in ('humbur','arkivuar','mbyllur','realizuar')
  ),
  sender_tokens as (
    select distinct sp.project_id, tok
    from sender_projects sp
    join public.projects p on p.id = sp.project_id
    cross join lateral regexp_split_to_table(
      lower(coalesce(p.name,'') || ' ' || coalesce(p.business_ref,'') || ' ' || coalesce(p.ref,'')),
      '[^a-z0-9]+'
    ) tok
    where length(tok) >= 5
      and tok not in (
        'project','projekti','projekt','steel','stahl','construction','konstruktion','konstrukcija',
        'offer','offerte','ponuda','angebot','request','kerkese','italian','style','restoran',
        'restaurant','seafront','client','customer','furnitor','supplier','gmbh','shpk','doo',
        'production','prodhim','scope','works','civil','quality','drawing','drawings','fabrication',
        'erection','assembly','plate','plates','heavy','structural','section','sections'
      )
  ),
  unique_tokens as (
    select st.project_id, st.tok
    from sender_tokens st
    where 1 = (
      select count(distinct p2.id)
      from public.projects p2
      cross join lateral regexp_split_to_table(
        lower(coalesce(p2.name,'') || ' ' || coalesce(p2.business_ref,'') || ' ' || coalesce(p2.ref,'')),
        '[^a-z0-9]+'
      ) tok2
      where tok2 = st.tok
        and lower(coalesce(p2.status,'')) not in ('humbur','arkivuar','mbyllur','realizuar')
    )
  ),
  candidates as (
    select distinct ut.project_id
    from unique_tokens ut
    where lower(coalesce(new.subject,'')) like '%' || ut.tok || '%'
  ),
  picked as (
    select count(*)::int as cnt, (array_agg(project_id))[1] as project_id
    from candidates
  )
  select cnt, project_id into v_count, v_project from picked;

  if v_count = 1 and v_project is not null then
    new.suggested_project_id := coalesce(new.suggested_project_id, v_project);
    new.match_method := 'db-sender-history-subject-token-suggest-v3';
    new.match_confidence := greatest(coalesce(new.match_confidence,0),76);
    new.needs_review := true;
    new.review_reason := coalesce(
      nullif(new.review_reason,''),
      'Sender history plus a subject token is context only, not project identity. Confirm project/reference/thread before linking.'
    );
    new.updated_at := now();
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_supplier_history_autolink() OWNER TO postgres;

--
-- Name: pppp_supplier_identity_reconcile_v1(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_identity_reconcile_v1(p_apply boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare r jsonb;
begin
  select jsonb_build_object(
    'mode',case when p_apply then 'apply_not_available_via_readonly_connector' else 'preview' end,
    'identity_rows',count(*),
    'linked_existing',count(*) filter(where linked_partner_id is not null),
    'unlinked',count(*) filter(where linked_partner_id is null),
    'confirmed_procurement_unlinked',count(*) filter(where identity_status='confirmed_procurement_identity'),
    'needs_supplier_master',count(*) filter(where profile_status='needs_supplier_master'),
    'needs_enrichment',count(*) filter(where profile_status='needs_enrichment'),
    'profiled',count(*) filter(where profile_status='profiled'),
    'generated_at',now()
  ) into r from public.pppp_supplier_identity_reconcile_source_v1;
  return r;
end;
$$;


ALTER FUNCTION public.pppp_supplier_identity_reconcile_v1(p_apply boolean) OWNER TO postgres;

--
-- Name: pppp_supplier_master_background_reconcile_v1(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_master_background_reconcile_v1(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  r record;
  v_payload jsonb;
  v_caps jsonb;
  v_processed integer:=0;
  v_snapshot integer:=0;
  v_limit integer:=least(500,greatest(1,coalesce(p_limit,100)));
begin
  for r in
    with public_domains(domain) as (
      values ('gmail.com'),('googlemail.com'),('outlook.com'),('hotmail.com'),('live.com'),('yahoo.com'),('icloud.com'),('aol.com'),('gmx.com'),('gmx.de'),('web.de'),('mail.com'),('proton.me'),('protonmail.com')
    ), base as (
      select lower(split_part(x.supplier_email,'@',2)) domain,
             max(nullif(trim(x.supplier_name),'')) supplier_name,
             (array_agg(lower(x.supplier_email) order by coalesce(x.sent_at,x.created_at) desc))[1] email,
             max(coalesce(x.sent_at,x.created_at)) last_rfq,
             count(*) filter(where x.status='replied' or x.offer_id is not null)::int replied_or_offer
      from public.rfq_log x
      where x.supplier_email like '%@%'
      group by lower(split_part(x.supplier_email,'@',2))
    )
    select b.* from base b
    where b.domain not in (select domain from public_domains)
      and b.domain not in ('prissteel.com','pristeel.com')
    order by b.last_rfq desc
    limit v_limit
  loop
    select coalesce(jsonb_agg(cap order by cap->>'family'),'[]'::jsonb) into v_caps
    from (
      select jsonb_build_object(
        'family',q.family,
        'product_type',coalesce(q.requirement->>'product_type',q.family),
        'product_tags',coalesce(q.requirement->'product_types','[]'::jsonb),
        'standards',coalesce(q.requirement->'standards','[]'::jsonb),
        'grades',coalesce(q.requirement->'grades','[]'::jsonb),
        'certifications',coalesce(q.requirement->'certifications','[]'::jsonb),
        'length_max_mm',nullif(q.requirement->>'length_mm',''),
        'source_ref','rfq-domain:'||r.domain,
        'confidence',case when r.replied_or_offer>0 then 82 else 60 end
      ) cap
      from (
        select distinct on (req.family) req.family,req.requirement
        from public.rfq_log rl
        cross join lateral public.pppp_project_procurement_requirements_v1(rl.project_id) req
        where lower(split_part(coalesce(rl.supplier_email,''),'@',2))=r.domain and rl.project_id is not null
        order by req.family,coalesce(rl.sent_at,rl.created_at) desc
      ) q
    ) z;

    v_payload:=jsonb_build_object(
      'name',coalesce(r.supplier_name,initcap(split_part(r.domain,'.',1))),
      'email',r.email,
      'website','https://'||r.domain,
      'source','rfq_background_reconcile_v1',
      'data_confidence',case when r.replied_or_offer>0 then 'verified' else 'partial' end,
      'last_contact_at',r.last_rfq::date,
      'capabilities',v_caps,
      'evidence',jsonb_build_object(
        'source','rfq_log','source_ref','rfq-domain:'||r.domain,'evidence_type','supplier_relationship',
        'summary',case when r.replied_or_offer>0 then 'Supplier identity confirmed by PPPP RFQ history and response/offer.' else 'Supplier identity recorded as an RFQ recipient in PPPP.' end,
        'direction','outgoing_rfq','evidence_at',r.last_rfq,'confidence',case when r.replied_or_offer>0 then 95 else 88 end,
        'metadata',jsonb_build_object('domain',r.domain,'replied_or_offer',r.replied_or_offer)
      )
    );
    perform public.pppp_supplier_master_ingest_v1(v_payload);
    v_processed:=v_processed+1;
  end loop;

  insert into public.supplier_identity_candidates_v1(
    identity_key,company_name,company_domain,country,primary_email,contact_name,source_contact_ids,contact_kinds,
    procurement_messages,incoming_offer_signals,outgoing_rfq_signals,first_evidence_at,last_evidence_at,linked_partner_id,
    identity_status,profile_status,evidence,updated_at
  )
  select identity_key,company_name,company_domain,country,primary_email,contact_name,source_contact_ids,contact_kinds,
    procurement_messages,incoming_offer_signals,outgoing_rfq_signals,first_evidence_at,last_evidence_at,linked_partner_id,
    identity_status,profile_status,evidence,now()
  from public.pppp_supplier_identity_reconcile_source_v1
  on conflict(identity_key) do update set
    company_name=excluded.company_name,company_domain=excluded.company_domain,
    country=coalesce(excluded.country,public.supplier_identity_candidates_v1.country),
    primary_email=coalesce(excluded.primary_email,public.supplier_identity_candidates_v1.primary_email),
    contact_name=coalesce(excluded.contact_name,public.supplier_identity_candidates_v1.contact_name),
    source_contact_ids=excluded.source_contact_ids,contact_kinds=excluded.contact_kinds,
    procurement_messages=excluded.procurement_messages,incoming_offer_signals=excluded.incoming_offer_signals,
    outgoing_rfq_signals=excluded.outgoing_rfq_signals,first_evidence_at=excluded.first_evidence_at,
    last_evidence_at=excluded.last_evidence_at,linked_partner_id=coalesce(excluded.linked_partner_id,public.supplier_identity_candidates_v1.linked_partner_id),
    identity_status=case when public.supplier_identity_candidates_v1.identity_status in ('approved','ignored') then public.supplier_identity_candidates_v1.identity_status else excluded.identity_status end,
    profile_status=case when public.supplier_identity_candidates_v1.profile_status='profiled' then 'profiled' else excluded.profile_status end,
    evidence=excluded.evidence,updated_at=now();
  get diagnostics v_snapshot=row_count;

  return jsonb_build_object('rfq_supplier_domains_processed',v_processed,'identity_snapshot_rows',v_snapshot,'external_email_send',false,'supplier_selection',false,'generated_at',now());
end;
$$;


ALTER FUNCTION public.pppp_supplier_master_background_reconcile_v1(p_limit integer) OWNER TO postgres;

--
-- Name: pppp_supplier_master_ingest_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_master_ingest_v1(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_partner_id uuid;
  v_created boolean:=false;
  v_name text:=btrim(coalesce(p_payload->>'name',''));
  v_email text:=lower(nullif(btrim(coalesce(p_payload->>'email','')),''));
  v_full_name text:=nullif(btrim(coalesce(p_payload->>'full_name','')),'');
  v_role text:=nullif(btrim(coalesce(p_payload->>'role','')),'');
  v_language text:=nullif(btrim(coalesce(p_payload->>'language','')),'');
  v_country text:=nullif(btrim(coalesce(p_payload->>'country','')),'');
  v_city text:=nullif(btrim(coalesce(p_payload->>'city','')),'');
  v_website text:=nullif(btrim(coalesce(p_payload->>'website','')),'');
  v_business_type text:=nullif(btrim(coalesce(p_payload->>'business_type','')),'');
  v_conf text:=lower(coalesce(nullif(btrim(p_payload->>'data_confidence'),''),'partial'));
  v_source text:=coalesce(nullif(btrim(p_payload->>'source'),''),'supplier_master_ingest_v1');
  v_aliases text[]:=coalesce(array(select jsonb_array_elements_text(coalesce(p_payload->'aliases','[]'::jsonb))),'{}'::text[]);
  v_categories text[]:=coalesce(array(select jsonb_array_elements_text(coalesce(p_payload->'categories','[]'::jsonb))),'{}'::text[]);
  v_grades text[]:=coalesce(array(select jsonb_array_elements_text(coalesce(p_payload->'grades','[]'::jsonb))),'{}'::text[]);
  v_certs text[]:=coalesce(array(select jsonb_array_elements_text(coalesce(p_payload->'certifications','[]'::jsonb))),'{}'::text[]);
  v_class text[]:=coalesce(array(select jsonb_array_elements_text(coalesce(p_payload->'class_approval','[]'::jsonb))),'{}'::text[]);
  v_contact_id uuid;
  cap jsonb;
  ev jsonb;
  v_cap_id uuid;
  v_family text;
  v_source_ref text;
  v_cap_count integer:=0;
  v_evidence_count integer:=0;
begin
  if v_name='' and coalesce(p_payload->>'partner_id','')='' then raise exception 'Supplier name or partner_id is required'; end if;

  if nullif(p_payload->>'partner_id','') is not null then
    v_partner_id:=(p_payload->>'partner_id')::uuid;
    if not exists(select 1 from public.partners where id=v_partner_id) then raise exception 'Partner not found: %',v_partner_id; end if;
  end if;

  if v_partner_id is null and v_email is not null then
    select pc.partner_id into v_partner_id
    from public.partner_contacts pc
    where lower(btrim(coalesce(pc.email,'')))=v_email
    order by pc.is_primary desc nulls last,pc.created_at limit 1;
  end if;

  if v_partner_id is null and v_name<>'' then
    select p.id into v_partner_id
    from public.partners p
    where private.pppp_supplier_norm_v1(p.name)=private.pppp_supplier_norm_v1(v_name)
       or exists(select 1 from unnest(coalesce(p.aliases,'{}'::text[])) a where private.pppp_supplier_norm_v1(a)=private.pppp_supplier_norm_v1(v_name))
    order by p.created_at limit 1;
  end if;

  if v_partner_id is null then
    insert into public.partners(name,aliases,country,city,website,business_type,relation,categories,grades,class_approval,certifications,stage,data_confidence,source,notes)
    values(
      v_name,v_aliases,v_country,v_city,v_website,v_business_type,array['supplier']::text[],v_categories,v_grades,v_class,v_certs,
      'active',v_conf,v_source,'Supplier Master controlled ingest. No supplier selection or external communication is implied.'
    ) returning id into v_partner_id;
    v_created:=true;
  else
    update public.partners p set
      aliases=private.pppp_text_array_union_v1(p.aliases,private.pppp_text_array_union_v1(v_aliases,case when private.pppp_supplier_norm_v1(p.name)<>private.pppp_supplier_norm_v1(v_name) and v_name<>'' then array[v_name] else '{}'::text[] end)),
      country=coalesce(p.country,v_country),
      city=coalesce(p.city,v_city),
      website=coalesce(p.website,v_website),
      business_type=case when coalesce((p_payload->>'allow_business_type_upgrade')::boolean,false) and v_business_type is not null then v_business_type else coalesce(p.business_type,v_business_type) end,
      relation=private.pppp_text_array_union_v1(p.relation,array['supplier']::text[]),
      categories=private.pppp_text_array_union_v1(p.categories,v_categories),
      grades=private.pppp_text_array_union_v1(p.grades,v_grades),
      certifications=private.pppp_text_array_union_v1(p.certifications,v_certs),
      class_approval=private.pppp_text_array_union_v1(p.class_approval,v_class),
      data_confidence=case
        when v_conf='verified' then 'verified'
        when coalesce(p.data_confidence,'unverified')='verified' then p.data_confidence
        when v_conf='partial' then 'partial'
        else coalesce(p.data_confidence,v_conf)
      end,
      source=coalesce(p.source,v_source),
      updated_at=now()
    where p.id=v_partner_id;
  end if;

  if v_email is not null then
    select pc.id into v_contact_id from public.partner_contacts pc
    where pc.partner_id=v_partner_id and lower(btrim(coalesce(pc.email,'')))=v_email limit 1;
    if v_contact_id is null then
      insert into public.partner_contacts(partner_id,full_name,email,role,language,is_primary,last_contact_at,notes,source)
      values(v_partner_id,coalesce(v_full_name,v_email),v_email,v_role,v_language,
             not exists(select 1 from public.partner_contacts where partner_id=v_partner_id and coalesce(is_primary,false)),
             nullif(p_payload->>'last_contact_at','')::date,
             'Imported/enriched through controlled Supplier Master ingest.',v_source)
      returning id into v_contact_id;
    else
      update public.partner_contacts set
        full_name=case when full_name=email and v_full_name is not null then v_full_name else full_name end,
        role=coalesce(role,v_role), language=coalesce(language,v_language),
        last_contact_at=greatest(last_contact_at,nullif(p_payload->>'last_contact_at','')::date),
        source=coalesce(source,v_source)
      where id=v_contact_id;
    end if;
  end if;

  for cap in select value from jsonb_array_elements(coalesce(p_payload->'capabilities','[]'::jsonb)) loop
    v_family:=lower(btrim(coalesce(cap->>'family','')));
    if v_family='' then continue; end if;
    v_source_ref:=coalesce(nullif(btrim(cap->>'source_ref'),''),nullif(btrim(p_payload#>>'{evidence,source_ref}'),''));
    select c.id into v_cap_id
    from public.supplier_capabilities_v1 c
    where c.partner_id=v_partner_id and lower(c.family)=v_family and c.is_active
    order by c.confidence desc,c.updated_at desc limit 1;

    if v_cap_id is null then
      insert into public.supplier_capabilities_v1(
        partner_id,family,product_type,product_tags,standards,grades,certifications,
        thickness_min_mm,thickness_max_mm,width_max_mm,length_max_mm,diameter_min_mm,diameter_max_mm,
        source,source_ref,confidence,is_active
      ) values (
        v_partner_id,v_family,nullif(cap->>'product_type',''),
        coalesce(array(select jsonb_array_elements_text(coalesce(cap->'product_tags','[]'::jsonb))),'{}'::text[]),
        coalesce(array(select jsonb_array_elements_text(coalesce(cap->'standards','[]'::jsonb))),'{}'::text[]),
        coalesce(array(select jsonb_array_elements_text(coalesce(cap->'grades','[]'::jsonb))),'{}'::text[]),
        coalesce(array(select jsonb_array_elements_text(coalesce(cap->'certifications','[]'::jsonb))),'{}'::text[]),
        nullif(cap->>'thickness_min_mm','')::numeric,nullif(cap->>'thickness_max_mm','')::numeric,
        nullif(cap->>'width_max_mm','')::integer,nullif(cap->>'length_max_mm','')::integer,
        nullif(cap->>'diameter_min_mm','')::numeric,nullif(cap->>'diameter_max_mm','')::numeric,
        'supplier_master_enrichment',v_source_ref,coalesce(nullif(cap->>'confidence','')::integer,70),true
      ) returning id into v_cap_id;
    else
      update public.supplier_capabilities_v1 c set
        product_type=coalesce(c.product_type,nullif(cap->>'product_type','')),
        product_tags=private.pppp_text_array_union_v1(c.product_tags,coalesce(array(select jsonb_array_elements_text(coalesce(cap->'product_tags','[]'::jsonb))),'{}'::text[])),
        standards=private.pppp_text_array_union_v1(c.standards,coalesce(array(select jsonb_array_elements_text(coalesce(cap->'standards','[]'::jsonb))),'{}'::text[])),
        grades=private.pppp_text_array_union_v1(c.grades,coalesce(array(select jsonb_array_elements_text(coalesce(cap->'grades','[]'::jsonb))),'{}'::text[])),
        certifications=private.pppp_text_array_union_v1(c.certifications,coalesce(array(select jsonb_array_elements_text(coalesce(cap->'certifications','[]'::jsonb))),'{}'::text[])),
        thickness_min_mm=coalesce(c.thickness_min_mm,nullif(cap->>'thickness_min_mm','')::numeric),
        thickness_max_mm=coalesce(c.thickness_max_mm,nullif(cap->>'thickness_max_mm','')::numeric),
        width_max_mm=coalesce(c.width_max_mm,nullif(cap->>'width_max_mm','')::integer),
        length_max_mm=coalesce(c.length_max_mm,nullif(cap->>'length_max_mm','')::integer),
        diameter_min_mm=coalesce(c.diameter_min_mm,nullif(cap->>'diameter_min_mm','')::numeric),
        diameter_max_mm=coalesce(c.diameter_max_mm,nullif(cap->>'diameter_max_mm','')::numeric),
        source=case when coalesce(nullif(cap->>'confidence','')::integer,70)>=c.confidence then 'supplier_master_enrichment' else c.source end,
        source_ref=case when coalesce(nullif(cap->>'confidence','')::integer,70)>=c.confidence then coalesce(v_source_ref,c.source_ref) else c.source_ref end,
        confidence=greatest(c.confidence,coalesce(nullif(cap->>'confidence','')::integer,70)),updated_at=now()
      where c.id=v_cap_id;
    end if;
    update public.partners p set
      categories=private.pppp_text_array_union_v1(p.categories,array[v_family]),
      grades=private.pppp_text_array_union_v1(p.grades,coalesce(array(select jsonb_array_elements_text(coalesce(cap->'grades','[]'::jsonb))),'{}'::text[])),
      certifications=private.pppp_text_array_union_v1(p.certifications,coalesce(array(select jsonb_array_elements_text(coalesce(cap->'certifications','[]'::jsonb))),'{}'::text[])),
      updated_at=now()
    where p.id=v_partner_id;
    v_cap_count:=v_cap_count+1;
  end loop;

  ev:=coalesce(p_payload->'evidence','{}'::jsonb);
  if coalesce(nullif(btrim(ev->>'source_ref'),''),'')<>'' then
    insert into public.supplier_evidence_v1(partner_id,source,source_ref,evidence_type,evidence_summary,direction,evidence_at,confidence,metadata)
    values(
      v_partner_id,coalesce(nullif(ev->>'source',''),v_source),ev->>'source_ref',coalesce(nullif(ev->>'evidence_type',''),'supplier_evidence'),
      coalesce(nullif(ev->>'summary',''),'Supplier evidence'),nullif(ev->>'direction',''),nullif(ev->>'evidence_at','')::timestamptz,
      coalesce(nullif(ev->>'confidence','')::integer,70),coalesce(ev->'metadata','{}'::jsonb)
    ) on conflict(partner_id,source,source_ref,evidence_type) do update set
      evidence_summary=excluded.evidence_summary,direction=coalesce(excluded.direction,public.supplier_evidence_v1.direction),
      evidence_at=coalesce(excluded.evidence_at,public.supplier_evidence_v1.evidence_at),confidence=greatest(public.supplier_evidence_v1.confidence,excluded.confidence),
      metadata=public.supplier_evidence_v1.metadata||excluded.metadata,updated_at=now();
    v_evidence_count:=1;
  end if;

  return jsonb_build_object('ok',true,'partner_id',v_partner_id,'created',v_created,'contact_id',v_contact_id,'capabilities_processed',v_cap_count,'evidence_processed',v_evidence_count,'human_supplier_selection_required',true,'external_email_send_requires_human_approval',true);
end;
$$;


ALTER FUNCTION public.pppp_supplier_master_ingest_v1(p_payload jsonb) OWNER TO postgres;

--
-- Name: pppp_supplier_match_v1(jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_match_v1(p_requirement jsonb, p_limit integer DEFAULT 30, p_threshold integer DEFAULT 0) RETURNS TABLE(partner_id uuid, partner_name text, country text, city text, website text, business_type text, primary_email text, contact_language text, match_score integer, qualified boolean, source_tier text, dimension_conflict boolean, match_reasons jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
with req as (
  select
    array_remove(array(
      select distinct public.pppp_supplier_family_v1(v)
      from unnest(
        public.pppp_jsonb_text_array_v1(p_requirement->'families') ||
        public.pppp_jsonb_text_array_v1(p_requirement->'family')
      ) v
    ),null) families,
    lower(coalesce(p_requirement->>'product_type',p_requirement->>'description','')) product_text,
    array(select lower(x) from unnest(
      public.pppp_jsonb_text_array_v1(p_requirement->'grades') ||
      public.pppp_jsonb_text_array_v1(p_requirement->'grade')
    ) x where nullif(trim(x),'') is not null) grades,
    array(select lower(x) from unnest(
      public.pppp_jsonb_text_array_v1(p_requirement->'standards') ||
      public.pppp_jsonb_text_array_v1(p_requirement->'standard')
    ) x where nullif(trim(x),'') is not null) standards,
    array(select lower(x) from unnest(
      public.pppp_jsonb_text_array_v1(p_requirement->'certifications') ||
      public.pppp_jsonb_text_array_v1(p_requirement->'cert')
    ) x where nullif(trim(x),'') is not null) certs,
    case when trim(coalesce(p_requirement->>'thickness_mm','')) ~ '^[0-9]+([.][0-9]+)?$' then (p_requirement->>'thickness_mm')::numeric end thickness_mm,
    case when trim(coalesce(p_requirement->>'width_mm','')) ~ '^[0-9]+([.][0-9]+)?$' then (p_requirement->>'width_mm')::numeric end width_mm,
    case when trim(coalesce(p_requirement->>'length_mm','')) ~ '^[0-9]+([.][0-9]+)?$' then (p_requirement->>'length_mm')::numeric end length_mm,
    case when trim(coalesce(p_requirement->>'diameter_mm','')) ~ '^[0-9]+([.][0-9]+)?$' then (p_requirement->>'diameter_mm')::numeric end diameter_mm
), cap as (
  select
    c.partner_id,
    array_agg(distinct c.family) filter(where c.is_active) cap_families,
    array_agg(distinct lower(g)) filter(where g is not null) cap_grades,
    array_agg(distinct lower(s)) filter(where s is not null) cap_standards,
    array_agg(distinct lower(z)) filter(where z is not null) cap_certs,
    string_agg(distinct lower(coalesce(c.product_type,'')||' '||array_to_string(c.product_tags,' ')),' ') cap_product_text,
    min(c.thickness_min_mm) filter(where c.is_active) thickness_min_mm,
    max(c.thickness_max_mm) filter(where c.is_active) thickness_max_mm,
    max(c.width_max_mm) filter(where c.is_active) width_max_mm,
    max(c.length_max_mm) filter(where c.is_active) length_max_mm,
    min(c.diameter_min_mm) filter(where c.is_active) diameter_min_mm,
    max(c.diameter_max_mm) filter(where c.is_active) diameter_max_mm
  from public.supplier_capabilities_v1 c
  left join lateral unnest(coalesce(c.grades,'{}'::text[])) g on true
  left join lateral unnest(coalesce(c.standards,'{}'::text[])) s on true
  left join lateral unnest(coalesce(c.certifications,'{}'::text[])) z on true
  where c.is_active
  group by c.partner_id
), hist as (
  select p.id partner_id,
    least(6,count(distinct o.id))::int offer_history_score,
    least(4,count(distinct r.id) filter(where r.replied_at is not null or r.status='replied'))::int reply_history_score
  from public.partners p
  left join public.offers o on lower(trim(o.supplier))=lower(trim(p.name))
  left join public.rfq_log r on lower(trim(r.supplier_name))=lower(trim(p.name))
  group by p.id
), base as (
  select p.*,ct.email primary_email,ct.language contact_language,
    coalesce(cap.cap_families,'{}'::text[]) || array(
      select distinct public.pppp_supplier_family_v1(x) from unnest(coalesce(p.categories,'{}'::text[])) x
    ) all_families,
    coalesce(cap.cap_grades,'{}'::text[]) || array(select lower(x) from unnest(coalesce(p.grades,'{}'::text[])) x) all_grades,
    coalesce(cap.cap_standards,'{}'::text[]) all_standards,
    coalesce(cap.cap_certs,'{}'::text[]) || array(select lower(x) from unnest(coalesce(p.certifications,'{}'::text[])) x) all_certs,
    lower(coalesce(cap.cap_product_text,'')||' '||coalesce(p.industry_note,'')||' '||coalesce(p.notes,'')) product_haystack,
    coalesce(cap.thickness_min_mm,p.thickness_min_mm) eff_thickness_min,
    coalesce(cap.thickness_max_mm,p.thickness_max_mm) eff_thickness_max,
    coalesce(cap.width_max_mm,p.width_max_mm) eff_width_max,
    coalesce(cap.length_max_mm,p.length_max_mm) eff_length_max,
    cap.diameter_min_mm eff_diameter_min,
    cap.diameter_max_mm eff_diameter_max,
    coalesce(hist.offer_history_score,0)+coalesce(hist.reply_history_score,0) history_score
  from public.partners p
  left join cap on cap.partner_id=p.id
  left join hist on hist.partner_id=p.id
  left join lateral (
    select pc.email,pc.language from public.partner_contacts pc
    where pc.partner_id=p.id and nullif(trim(pc.email),'') is not null
    order by pc.is_primary desc nulls last,pc.created_at asc limit 1
  ) ct on true
  where 'supplier'=any(coalesce(p.relation,'{}'::text[]))
    and lower(coalesce(p.stage,'active')) not in ('inactive','blocked','rejected','archived')
), scored as (
  select b.*,
    r.families req_families,r.product_text req_product_text,r.grades req_grades,r.standards req_standards,r.certs req_certs,
    r.thickness_mm req_thickness_mm,r.width_mm req_width_mm,r.length_mm req_length_mm,r.diameter_mm req_diameter_mm,
    case
      when cardinality(r.families)=0 then 0
      when exists(select 1 from unnest(r.families) f where f=any(b.all_families)) then 35
      when exists(select 1 from unnest(r.families) f where (f='heavy_plate' and 'sheet'=any(b.all_families)) or (f='sheet' and 'heavy_plate'=any(b.all_families))) then 25
      else 0 end family_score,
    case when r.product_text='' then 10
      when b.product_haystack like '%'||r.product_text||'%' then 10
      when public.pppp_supplier_family_v1(r.product_text)=any(b.all_families) then 7
      else 0 end product_score,
    case when cardinality(r.grades)=0 then 15
      when exists(select 1 from unnest(r.grades) x where x=any(b.all_grades)) then 15
      when exists(
        select 1 from unnest(r.grades) x cross join unnest(b.all_grades) y
        where regexp_replace(x,'(jr|j0|j2|nl|ml|mc|n|m)$','','i')=regexp_replace(y,'(jr|j0|j2|nl|ml|mc|n|m)$','','i')
      ) then 11
      when cardinality(b.all_grades)=0 then 4 else -10 end grade_score,
    case when cardinality(r.standards)=0 then 15
      when exists(select 1 from unnest(r.standards) x where x=any(b.all_standards)) then 15
      when cardinality(b.all_standards)=0 then 2 else -15 end standard_score,
    case when cardinality(r.certs)=0 then 5
      when exists(select 1 from unnest(r.certs) x where x=any(b.all_certs)) then 5
      when cardinality(b.all_certs)=0 then 1 else -5 end cert_score,
    (
      (r.thickness_mm is not null and ((b.eff_thickness_min is not null and r.thickness_mm<b.eff_thickness_min) or (b.eff_thickness_max is not null and r.thickness_mm>b.eff_thickness_max)))
      or (r.width_mm is not null and b.eff_width_max is not null and r.width_mm>b.eff_width_max)
      or (r.length_mm is not null and b.eff_length_max is not null and r.length_mm>b.eff_length_max)
      or (r.diameter_mm is not null and ((b.eff_diameter_min is not null and r.diameter_mm<b.eff_diameter_min) or (b.eff_diameter_max is not null and r.diameter_mm>b.eff_diameter_max)))
    ) dim_conflict,
    case when r.thickness_mm is null and r.width_mm is null and r.length_mm is null and r.diameter_mm is null then 10
      when (b.eff_thickness_min is not null or b.eff_thickness_max is not null or b.eff_width_max is not null or b.eff_length_max is not null or b.eff_diameter_min is not null or b.eff_diameter_max is not null) then 10
      else 3 end dimension_score,
    case when b.primary_email is not null then 5 else 0 end contact_score,
    case upper(coalesce(b.country,'')) when 'XK' then 8 when 'AL' then 6 when 'MK' then 6 when 'ME' then 6 when 'RS' then 6 when 'BA' then 6 when 'HR' then 6 when 'BG' then 6 when 'RO' then 6 when 'SI' then 6 when 'TR' then 5 when 'GR' then 4 else 3 end location_score,
    least(10,b.history_score) history_bonus,
    least(5,greatest(0,coalesce(b.importance,0))) importance_score,
    case lower(coalesce(b.data_confidence,'')) when 'verified' then 5 when 'partial' then 2 else 1 end confidence_score
  from base b cross join req r
), final as (
  select s.*,
    greatest(0,least(100,
      s.family_score+s.product_score+s.grade_score+s.standard_score+s.cert_score+s.dimension_score+
      s.contact_score+s.location_score+s.history_bonus+s.importance_score+s.confidence_score
    ))::int total_score
  from scored s
)
select
  f.id,f.name,f.country,f.city,f.website,f.business_type,f.primary_email,f.contact_language,
  f.total_score,
  (f.family_score>=25 and not f.dim_conflict and f.total_score>=greatest(0,least(100,coalesce(p_threshold,0))) and (cardinality(f.req_standards)=0 or exists(select 1 from unnest(f.req_standards) x where x=any(f.all_standards) or f.product_haystack like '%'||x||'%'))) qualified,
  case upper(coalesce(f.country,'')) when 'XK' then 'local' when 'TR' then 'turkey' when 'GR' then 'greece'
    when 'AL' then 'regional' when 'MK' then 'regional' when 'ME' then 'regional' when 'RS' then 'regional' when 'BA' then 'regional' when 'HR' then 'regional' when 'BG' then 'regional' when 'RO' then 'regional' when 'SI' then 'regional' else 'eu' end source_tier,
  f.dim_conflict,
  jsonb_build_object(
    'family_score',f.family_score,'product_score',f.product_score,'grade_score',f.grade_score,
    'standard_score',f.standard_score,'certificate_score',f.cert_score,'dimension_score',f.dimension_score,
    'contact_score',f.contact_score,'location_score',f.location_score,'history_score',f.history_bonus,
    'importance_score',f.importance_score,'data_confidence_score',f.confidence_score,
    'requested_families',f.req_families,'supplier_families',f.all_families
  )
from final f
where f.family_score>0
order by f.total_score desc,f.importance desc nulls last,f.name
limit greatest(1,least(200,coalesce(p_limit,30)));
$_$;


ALTER FUNCTION public.pppp_supplier_match_v1(p_requirement jsonb, p_limit integer, p_threshold integer) OWNER TO postgres;

--
-- Name: pppp_supplier_offer_comparison_json_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_offer_comparison_json_v1(p_project_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with p as (
  select id,name,client,ref,business_ref,status,pipeline_stage,operational_state
  from public.projects where id=p_project_id
), offers as (
  select * from public.pppp_supplier_offer_comparison_v1 where project_id=p_project_id
), groups as (
  select pricing_basis,
         count(*) filter(where comparable)::int comparable_offers,
         min(comparison_value_eur) filter(where comparable) price_leader_value_eur,
         (array_agg(supplier order by comparison_value_eur asc,created_at desc) filter(where comparable))[1] price_leader_supplier
  from offers group by pricing_basis
), decisions as (
  select coalesce(jsonb_agg(jsonb_build_object(
    'decision_type',decision_type,'status',status,'supplier_name',supplier_name,
    'supplier_offer_id',supplier_offer_id,'source',source,'decided_at',decided_at,'evidence',evidence
  ) order by decided_at desc),'[]'::jsonb) j
  from public.project_supplier_decisions
  where project_id=p_project_id and status='active'
)
select jsonb_build_object(
  'project',(select to_jsonb(p) from p),
  'comparison_ready',exists(select 1 from groups where comparable_offers>=2),
  'human_gate_required',true,
  'basis_groups',coalesce((select jsonb_agg(jsonb_build_object(
    'pricing_basis',pricing_basis,'comparable_offers',comparable_offers,
    'price_leader_supplier',price_leader_supplier,'price_leader_value_eur',price_leader_value_eur,
    'note','Price leader is a comparison signal only, not an automatic supplier selection.'
  ) order by comparable_offers desc,pricing_basis) from groups),'[]'::jsonb),
  'offers',coalesce((select jsonb_agg(jsonb_build_object(
    'offer_id',offer_id,'supplier',supplier,'currency',currency,'pricing_basis',pricing_basis,
    'comparison_value_eur',comparison_value_eur,'price_rank',price_rank_within_basis,
    'comparable_count',comparable_count_in_basis,'completeness_score',completeness_score,
    'delivery_weeks',delivery_weeks,'incoterms',incoterms,'payment_terms',payment_terms,
    'validity_days',validity_days,'cert',cert,'offer_ref',offer_ref,
    'qty_kg',qty_kg,'transport_eur',transport_eur,'zinc_kg',zinc_kg
  ) order by pricing_basis,price_rank_within_basis nulls last,created_at desc) from offers),'[]'::jsonb),
  'active_decisions',(select j from decisions)
);
$$;


ALTER FUNCTION public.pppp_supplier_offer_comparison_json_v1(p_project_id uuid) OWNER TO postgres;

--
-- Name: pppp_supplier_offer_precision_reconcile_v1(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_offer_precision_reconcile_v1(p_apply boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_candidates integer := 0;
  v_superseded integer := 0;
  v_closed_tasks integer := 0;
begin
  select count(*) into v_candidates
  from public.supplier_offer_candidates c
  where c.status='review'
    and c.matched_rfq_id is null
    and lower(
      coalesce(c.subject,'')||' '||
      coalesce(c.raw_text,'')||' '||
      coalesce(c.extracted->'source_attachment_names','[]'::jsonb)::text
    ) ~ '(werkvertrag|bankgarantie|bank guarantee|bankverbindung|\bcontract\b|\bkontrat|agreement|guarantee|garanci)';

  if not p_apply then
    return jsonb_build_object(
      'mode','preview',
      'obvious_non_offer_candidates',v_candidates,
      'superseded',0,
      'closed_tasks',0,
      'generated_at',now()
    );
  end if;

  with changed as (
    update public.supplier_offer_candidates c
       set status='superseded',
           reviewed_at=coalesce(c.reviewed_at,now()),
           updated_at=now(),
           extracted=jsonb_set(
             coalesce(c.extracted,'{}'::jsonb),
             '{classification}',
             to_jsonb('non_offer_document'::text),
             true
           )
     where c.status='review'
       and c.matched_rfq_id is null
       and lower(
         coalesce(c.subject,'')||' '||
         coalesce(c.raw_text,'')||' '||
         coalesce(c.extracted->'source_attachment_names','[]'::jsonb)::text
       ) ~ '(werkvertrag|bankgarantie|bank guarantee|bankverbindung|\bcontract\b|\bkontrat|agreement|guarantee|garanci)'
    returning c.id
  )
  select count(*) into v_superseded from changed;

  with closed as (
    update public.tasks t
       set status='mbyllur',
           done_at=coalesce(t.done_at,now()),
           detail=concat_ws(E'\n',nullif(t.detail,''),'PPPP: commercial intake review auto-closed because no supplier-offer candidates remain in review for this project.')
     where t.source='commercial_intake_review'
       and t.status='hapur'
       and t.project_id is not null
       and not exists (
         select 1
         from public.supplier_offer_candidates c
         where c.project_id=t.project_id and c.status='review'
       )
    returning t.id
  )
  select count(*) into v_closed_tasks from closed;

  return jsonb_build_object(
    'mode','apply',
    'obvious_non_offer_candidates',v_candidates,
    'superseded',v_superseded,
    'closed_tasks',v_closed_tasks,
    'generated_at',now()
  );
end;
$$;


ALTER FUNCTION public.pppp_supplier_offer_precision_reconcile_v1(p_apply boolean) OWNER TO postgres;

--
-- Name: pppp_supplier_quote_arrival_reconcile_v1(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_quote_arrival_reconcile_v1(p_apply boolean DEFAULT false, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  r record;
  v_limit integer := least(1000,greatest(1,coalesce(p_limit,200)));
  v_seen integer := 0;
  v_closeable integer := 0;
  v_closed integer := 0;
  v_state_released integer := 0;
  v_review jsonb := '{}'::jsonb;
  v_compare jsonb := '{}'::jsonb;
begin
  for r in
    with open_waits as (
      select
        t.id,t.project_id,t.source_ref,
        regexp_replace(coalesce(t.source_ref,''),'^.*:supplier:','','') as supplier_email,
        p.pipeline_stage,p.operational_state,p.operational_state_source,
        exists(
          select 1 from public.rfq_log q
          where q.project_id=t.project_id
            and lower(coalesce(q.supplier_email,''))=lower(regexp_replace(coalesce(t.source_ref,''),'^.*:supplier:','',''))
            and (lower(coalesce(q.status,''))='replied' or q.replied_at is not null or q.offer_id is not null)
        ) as has_supplier_reply,
        (p.pipeline_stage in ('client_offer','commercial','production_control','factory_audit','transport') or coalesce(p.operational_state,'')='execution' or lower(coalesce(p.status,'')) in ('fituar','won')) as lifecycle_superseded
      from public.tasks t join public.projects p on p.id=t.project_id
      where t.source='supplier_wait_auto'
        and lower(coalesce(t.status,'')) <> all (array['kryer','done','mbyllur','closed','arkivuar','archived'])
      order by t.due_date nulls last,t.created_at
      limit v_limit
    ) select * from open_waits
  loop
    v_seen:=v_seen+1;
    if r.has_supplier_reply or r.lifecycle_superseded then
      v_closeable:=v_closeable+1;
      if p_apply then
        update public.tasks
           set status='mbyllur',done_at=coalesce(done_at,now()),
               detail=concat_ws(E'\n',nullif(detail,''),case when r.has_supplier_reply then 'PPPP: pritja u mbyll automatikisht sepse përgjigjja/oferta e furnitorit është regjistruar.' else 'PPPP: pritja u mbyll automatikisht sepse projekti ka kaluar përtej fazës së pritjes së furnitorit.' end)
         where id=r.id and lower(coalesce(status,'')) <> all (array['kryer','done','mbyllur','closed','arkivuar','archived']);
        if found then v_closed:=v_closed+1; end if;
      end if;
    end if;
  end loop;

  if p_apply then
    with released as (
      update public.projects p
         set operational_state='active_work',operational_state_at=now(),operational_state_source='supplier-response-reconcile-v1',updated_at=now()
       where p.operational_state_source='supplier-wait-auto-v1'
         and not exists(select 1 from public.tasks t where t.project_id=p.id and t.source='supplier_wait_auto' and lower(coalesce(t.status,'')) <> all (array['kryer','done','mbyllur','closed','arkivuar','archived']))
       returning p.id
    ) select count(*)::int into v_state_released from released;
    v_review:=public.pppp_commercial_review_intelligence_reconcile_v1(true,least(v_limit,500));
    v_compare:=public.pppp_procurement_comparison_reconcile_v1(true,least(v_limit,500));
  else
    v_review:=public.pppp_commercial_review_intelligence_reconcile_v1(false,least(v_limit,500));
    v_compare:=public.pppp_procurement_comparison_reconcile_v1(false,least(v_limit,500));
  end if;
  return jsonb_build_object('mode',case when p_apply then 'apply' else 'preview' end,'open_supplier_waits_seen',v_seen,'closeable_waits',v_closeable,'waits_closed',v_closed,'project_wait_states_released',v_state_released,'commercial_review',v_review,'supplier_comparison',v_compare,'human_supplier_selection_required',true,'generated_at',now());
end;
$$;


ALTER FUNCTION public.pppp_supplier_quote_arrival_reconcile_v1(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_supplier_rfq_gate_v1(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_rfq_gate_v1(p_project_id uuid, p_supplier_name text, p_supplier_email text DEFAULT NULL::text, p_rfq_mode text DEFAULT 'firm'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  p public.projects%rowtype;
  v_mode text:=lower(coalesce(nullif(trim(p_rfq_mode),''),'firm'));
  h record;
  v_name text:=trim(coalesce(p_supplier_name,''));
  v_name_key text:=regexp_replace(lower(trim(coalesce(p_supplier_name,''))),'[^a-z0-9]+','','g');
  v_recent record;
  v_allowed boolean:=false;
  v_reason text:='';
  v_warning text:=null;
begin
  if p_project_id is null then
    return jsonb_build_object('allowed',false,'reason','client_signal_or_project_required',
      'message','Supplier discovery may remain read-only, but an external supplier RFQ requires a real PPPP project/client opportunity.',
      'human_send_required',true);
  end if;
  if v_name='' then return jsonb_build_object('allowed',false,'reason','supplier_required','human_send_required',true); end if;
  if v_mode not in ('budgetary','firm','requote') then
    return jsonb_build_object('allowed',false,'reason','invalid_rfq_mode','allowed_modes',jsonb_build_array('budgetary','firm','requote'),'human_send_required',true);
  end if;
  select * into p from public.projects where id=p_project_id;
  if not found then return jsonb_build_object('allowed',false,'reason','project_not_found','human_send_required',true); end if;
  if lower(coalesce(p.operational_state,''))='closed'
     or lower(coalesce(p.status,'')) in ('humbur','arkivuar','mbyllur','closed','lost','realizuar') then
    return jsonb_build_object('allowed',false,'reason','project_not_active','project_stage',p.pipeline_stage,
      'operational_state',p.operational_state,'status',p.status,'human_send_required',true);
  end if;

  select * into h from public.pppp_supplier_relationship_health_v1 x
  where regexp_replace(lower(x.supplier_name),'[^a-z0-9]+','','g')=v_name_key
     or (length(v_name_key)>=5 and regexp_replace(lower(x.supplier_name),'[^a-z0-9]+','','g') like v_name_key||'%')
     or (length(regexp_replace(lower(x.supplier_name),'[^a-z0-9]+','','g'))>=5
         and v_name_key like regexp_replace(lower(x.supplier_name),'[^a-z0-9]+','','g')||'%')
  order by case when regexp_replace(lower(x.supplier_name),'[^a-z0-9]+','','g')=v_name_key then 0 else 1 end
  limit 1;

  select r.id,r.sent_at,r.replied_at,r.offer_id,r.rfq_mode into v_recent
  from public.rfq_log r
  where r.project_id=p_project_id and r.sent_at is not null
    and (regexp_replace(lower(coalesce(r.supplier_name,'')),'[^a-z0-9]+','','g')=v_name_key
         or (p_supplier_email is not null and lower(coalesce(r.supplier_email,''))=lower(p_supplier_email)))
  order by r.sent_at desc limit 1;

  if v_recent.id is not null and v_recent.sent_at>=now()-interval '7 days'
     and v_recent.replied_at is null and v_recent.offer_id is null then
    return jsonb_build_object('allowed',false,'reason','recent_supplier_rfq_same_project',
      'last_sent_at',v_recent.sent_at,'relationship_state',coalesce(h.relationship_state,'unknown'),'human_send_required',true);
  end if;

  if v_mode='budgetary' then
    if lower(coalesce(p.pipeline_stage,'')) not in ('rfq_in','technical_review','pricing') then v_reason:='budgetary_not_justified_at_project_stage';
    elsif coalesce(h.relationship_state,'')='fatigue_risk' then v_reason:='supplier_fatigue_blocks_budgetary_request';
    else v_allowed:=true;v_reason:='qualified_budgetary_check';end if;
  elsif v_mode='firm' then
    if lower(coalesce(p.pipeline_stage,'')) not in ('rfq_in','technical_review','pricing') then v_reason:='firm_rfq_requires_active_pre_offer_stage';
    else
      v_allowed:=true;v_reason:='qualified_firm_supplier_rfq';
      if coalesce(h.relationship_state,'')='fatigue_risk' then v_warning:='supplier_fatigue_risk_use_only_if_scope_is_real_and_complete';
      elsif coalesce(h.relationship_state,'')='watch' then v_warning:='supplier_relationship_watch';end if;
    end if;
  else
    if lower(coalesce(p.pipeline_stage,'')) not in ('pricing','client_offer','commercial') then v_reason:='requote_requires_pricing_or_client_offer_stage';
    else
      v_allowed:=true;v_reason:='qualified_requote';
      if coalesce(h.relationship_state,'') in ('fatigue_risk','watch') then v_warning:='supplier_relationship_requires_careful_feedback';end if;
    end if;
  end if;
  return jsonb_build_object('allowed',v_allowed,'reason',v_reason,'warning',v_warning,'rfq_mode',v_mode,
    'project_id',p.id,'project_name',p.name,'project_stage',p.pipeline_stage,'operational_state',p.operational_state,
    'supplier_name',v_name,'relationship_state',coalesce(h.relationship_state,'new_or_unmeasured'),
    'sent_rfqs',coalesce(h.sent_rfqs,0),'sent_rfqs_90d',coalesce(h.sent_rfqs_90d,0),
    'answered_rfqs',coalesce(h.answered_rfqs,0),'realized_orders',coalesce(h.realized_orders,0),
    'relationship_guidance',coalesce(h.relationship_guidance,'No measured sent-RFQ history.'),
    'human_send_required',true,'external_email_sent',false);
end;
$$;


ALTER FUNCTION public.pppp_supplier_rfq_gate_v1(p_project_id uuid, p_supplier_name text, p_supplier_email text, p_rfq_mode text) OWNER TO postgres;

--
-- Name: pppp_supplier_rfq_gate_v2(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_rfq_gate_v2(p_project_id uuid, p_tender_watch_id uuid, p_supplier_name text, p_supplier_email text DEFAULT NULL::text, p_rfq_mode text DEFAULT 'firm'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_project_gate jsonb;
  t public.kek_tender_watch%rowtype;
  pol public.pppp_procurement_source_policy%rowtype;
  h record;
  v_mode text:=lower(coalesce(nullif(trim(p_rfq_mode),''),'firm'));
  v_name text:=trim(coalesce(p_supplier_name,''));
  v_key text:=regexp_replace(lower(trim(coalesce(p_supplier_name,''))),'[^a-z0-9]+','','g');
  v_ready boolean:=false;
  v_allowed boolean:=false;
  v_reason text:='';
  v_warning text:=null;
  v_existing record;
begin
  if p_project_id is not null then
    v_project_gate:=public.pppp_supplier_rfq_gate_v1(p_project_id,p_supplier_name,p_supplier_email,p_rfq_mode);
    return v_project_gate || jsonb_build_object('context_type','project','tender_watch_id',p_tender_watch_id);
  end if;

  if p_tender_watch_id is null then
    return jsonb_build_object('allowed',false,'reason','qualified_project_or_direct_tender_required','human_send_required',true);
  end if;
  if v_name='' then return jsonb_build_object('allowed',false,'reason','supplier_required','human_send_required',true); end if;
  if v_mode not in ('budgetary','firm','requote') then
    return jsonb_build_object('allowed',false,'reason','invalid_rfq_mode','human_send_required',true);
  end if;

  select * into t from public.kek_tender_watch where id=p_tender_watch_id;
  if not found then return jsonb_build_object('allowed',false,'reason','tender_not_found','human_send_required',true); end if;

  select * into pol from public.pppp_procurement_source_policy where source=t.source_key;
  if not found or pol.participation_mode<>'bid' then
    return jsonb_build_object('allowed',false,'reason','source_not_direct_bid','source',t.source_key,
      'participation_mode',coalesce(pol.participation_mode,'unknown'),'human_send_required',true);
  end if;

  if lower(coalesce(t.status,'')) in ('ignored','rejected','closed','lost','awarded','archive','archived') then
    return jsonb_build_object('allowed',false,'reason','tender_not_active','status',t.status,'human_send_required',true);
  end if;
  if t.deadline is not null and t.deadline < current_date then
    return jsonb_build_object('allowed',false,'reason','tender_deadline_passed','deadline',t.deadline,'human_send_required',true);
  end if;
  if coalesce(t.relevance_score,0)<coalesce(pol.home_min_score,65) then
    return jsonb_build_object('allowed',false,'reason','tender_relevance_below_source_threshold',
      'relevance_score',t.relevance_score,'required_score',pol.home_min_score,'human_send_required',true);
  end if;

  v_ready :=
    lower(coalesce(t.payload->>'analysis_status',''))='ready'
    or coalesce((t.payload->>'dossier_complete')::boolean,false)
    or coalesce((t.payload#>>'{analysis,coverage,complete}')::boolean,false);

  if not v_ready then
    return jsonb_build_object('allowed',false,'reason','tender_dossier_not_ready','human_send_required',true);
  end if;

  select * into h
  from public.pppp_supplier_relationship_health_v1 x
  where regexp_replace(lower(x.supplier_name),'[^a-z0-9]+','','g')=v_key
     or (length(v_key)>=5 and regexp_replace(lower(x.supplier_name),'[^a-z0-9]+','','g') like v_key||'%')
     or (length(regexp_replace(lower(x.supplier_name),'[^a-z0-9]+','','g'))>=5
         and v_key like regexp_replace(lower(x.supplier_name),'[^a-z0-9]+','','g')||'%')
  order by case when regexp_replace(lower(x.supplier_name),'[^a-z0-9]+','','g')=v_key then 0 else 1 end
  limit 1;

  select r.id,r.created_at,r.sent_at,r.status into v_existing
  from public.rfq_log r
  where r.tender_watch_id=p_tender_watch_id
    and (regexp_replace(lower(coalesce(r.supplier_name,'')),'[^a-z0-9]+','','g')=v_key
      or (p_supplier_email is not null and lower(coalesce(r.supplier_email,''))=lower(p_supplier_email)))
    and lower(coalesce(r.status,'')) in ('planned','draft','draft_review','sent')
  order by coalesce(r.sent_at,r.created_at) desc limit 1;

  if v_existing.id is not null then
    return jsonb_build_object('allowed',false,'reason','supplier_rfq_already_registered_for_tender',
      'rfq_log_id',v_existing.id,'rfq_status',v_existing.status,'human_send_required',true);
  end if;

  if v_mode='budgetary' and coalesce(h.relationship_state,'')='fatigue_risk' then
    v_reason:='supplier_fatigue_blocks_budgetary_request';
  else
    v_allowed:=true;
    v_reason:=case when v_mode='budgetary' then 'qualified_direct_tender_budgetary_check'
                   when v_mode='requote' then 'qualified_direct_tender_requote'
                   else 'qualified_direct_tender_firm_rfq' end;
    if coalesce(h.relationship_state,'')='fatigue_risk' then
      v_warning:='supplier_fatigue_risk_use_only_if_scope_is_real_and_complete';
    elsif coalesce(h.relationship_state,'')='watch' then
      v_warning:='supplier_relationship_watch';
    end if;
  end if;

  return jsonb_build_object(
    'allowed',v_allowed,'reason',v_reason,'warning',v_warning,'context_type','direct_tender',
    'tender_watch_id',t.id,'source',t.source_key,'tender_title',t.title,'deadline',t.deadline,
    'relevance_score',t.relevance_score,'rfq_mode',v_mode,'supplier_name',v_name,
    'relationship_state',coalesce(h.relationship_state,'new_or_unmeasured'),
    'sent_rfqs',coalesce(h.sent_rfqs,0),'sent_rfqs_90d',coalesce(h.sent_rfqs_90d,0),
    'answered_rfqs',coalesce(h.answered_rfqs,0),'realized_orders',coalesce(h.realized_orders,0),
    'relationship_guidance',coalesce(h.relationship_guidance,'No measured sent-RFQ history.'),
    'human_send_required',true,'external_email_sent',false
  );
end;
$$;


ALTER FUNCTION public.pppp_supplier_rfq_gate_v2(p_project_id uuid, p_tender_watch_id uuid, p_supplier_name text, p_supplier_email text, p_rfq_mode text) OWNER TO postgres;

--
-- Name: pppp_supplier_routing_plan_v1(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_routing_plan_v1(p_project_id uuid, p_min_qualified integer DEFAULT 3, p_threshold integer DEFAULT 70) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with req as (
  select * from public.pppp_project_procurement_requirements_v1(p_project_id)
), cov as (
  select r.family,r.requirement,public.pppp_supplier_coverage_v1(r.requirement,p_min_qualified,p_threshold) coverage from req r
)
select jsonb_build_object(
  'project_id',p_project_id,
  'requirements',coalesce(jsonb_agg(jsonb_build_object('family',family,'requirement',requirement,'coverage',coverage) order by family),'[]'::jsonb),
  'all_requirements_covered',coalesce(bool_and((coverage->>'sufficient')::boolean),false),
  'human_supplier_selection_required',true,
  'external_email_send_requires_human_approval',true,
  'generated_at',now()
) from cov;
$$;


ALTER FUNCTION public.pppp_supplier_routing_plan_v1(p_project_id uuid, p_min_qualified integer, p_threshold integer) OWNER TO postgres;

--
-- Name: pppp_supplier_task_role_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_task_role_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_sender_name text;
  v_sender_email text;
  v_supplier text;
begin
  if new.source <> 'email_request_auto' or new.project_id is null or coalesce(new.source_ref,'')='' then
    return new;
  end if;

  select pe.from_name,pe.from_email into v_sender_name,v_sender_email
  from public.project_emails pe
  where pe.gmail_message_id=new.source_ref and pe.direction='incoming'
  limit 1;
  if v_sender_name is null and v_sender_email is null then return new; end if;

  if exists(
    select 1 from public.project_contacts pc
    where pc.project_id=new.project_id::text
      and lower(coalesce(pc.email,''))=lower(coalesce(v_sender_email,''))
      and lower(coalesce(pc.role,''))='client'
  ) then
    return new;
  end if;

  select coalesce(nullif(btrim(pc.company),''),nullif(btrim(pc.name),''),nullif(btrim(pc.email),''))
    into v_supplier
  from public.project_contacts pc
  where pc.project_id=new.project_id::text
    and lower(coalesce(pc.email,''))=lower(coalesce(v_sender_email,''))
    and lower(coalesce(pc.role,''))='supplier'
  order by coalesce(pc.is_primary,false) desc,pc.last_seen desc nulls last,pc.id desc
  limit 1;

  if v_supplier is null then
    select p.name into v_supplier
    from public.partner_contacts pc
    join public.partners p on p.id=pc.partner_id
    where lower(coalesce(pc.email,''))=lower(coalesce(v_sender_email,''))
      and p.stage='active'
      and coalesce(p.relation,'{}'::text[]) @> array['supplier']::text[]
    order by coalesce(pc.is_primary,false) desc,p.importance desc nulls last,p.name
    limit 1;
  end if;

  if v_supplier is null then
    select o.supplier into v_supplier
    from public.offers o
    where o.project_id=new.project_id
      and (
        lower(coalesce(v_sender_name,''))=lower(coalesce(o.contact_person,''))
        or lower(coalesce(v_sender_name,'')) like '%'||lower(coalesce(o.supplier,''))||'%'
        or lower(coalesce(o.supplier,'')) like '%'||lower(coalesce(v_sender_name,''))||'%'
        or regexp_replace(lower(split_part(coalesce(v_sender_email,''),'@',1)),'[^a-z0-9]','','g') like '%'||regexp_replace(lower(coalesce(o.supplier,'')),'[^a-z0-9]','','g')||'%'
      )
    order by o.created_at desc
    limit 1;
  end if;

  if v_supplier is not null then
    new.source := 'supplier_update_auto';
    new.category := 'furnitor';
    new.title := 'Rishiko update-in e furnitorit — '||v_supplier;
    if position('Email furnitori i lidhur me projektin; nuk është kërkesë klienti.' in coalesce(new.detail,''))=0 then
      new.detail := concat_ws(E'\n','Email furnitori i lidhur me projektin; nuk është kërkesë klienti.',new.detail);
    end if;
    if lower(coalesce(new.priority,'')) in ('mesatare','normal') then new.priority:='e larte'; end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_supplier_task_role_guard() OWNER TO postgres;

--
-- Name: FUNCTION pppp_supplier_task_role_guard(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_supplier_task_role_guard() IS 'Classifies email_request_auto supplier messages from project-specific/canonical supplier contacts, with offer matching retained only as fallback.';


--
-- Name: pppp_supplier_wait_state_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_supplier_wait_state_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_state text;
  v_status text;
begin
  if new.project_id is null or lower(coalesce(new.source,'')) <> 'supplier_wait_auto' then
    return new;
  end if;

  select lower(coalesce(p.operational_state,'')), lower(coalesce(p.status,''))
    into v_state,v_status
  from public.projects p
  where p.id=new.project_id;

  if v_state in ('wait_for_client','execution','closed')
     or v_status in ('humbur','lost','arkivuar','archived','mbyllur','closed','closedlost','cancelled','canceled','realizuar','fituar','won') then
    if tg_op='INSERT' then
      return null;
    end if;
    new.status:='mbyllur';
    new.done_at:=coalesce(new.done_at,now());
    if position('PPPP: supplier-wait-state-closed —' in coalesce(new.detail,''))=0 then
      new.detail:=concat_ws(E'\n',nullif(new.detail,''),
        'PPPP: supplier-wait-state-closed — pritja e furnitorit nuk është më veprimi aktual në gjendjen kanonike të projektit.');
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_supplier_wait_state_guard_v1() OWNER TO postgres;

--
-- Name: FUNCTION pppp_supplier_wait_state_guard_v1(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_supplier_wait_state_guard_v1() IS 'Prevents supplier_wait_auto tasks from remaining/reopening after canonical project state has moved beyond supplier waiting.';


--
-- Name: pppp_sync_contact_from_project_email_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_sync_contact_from_project_email_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_email text;
  v_contact_id uuid;
  v_company text;
  v_kind text;
  v_supplier text;
  v_project_name text;
  v_client text;
  v_first timestamptz;
  v_last timestamptz;
  v_count int;
  v_direct int;
  v_projects jsonb;
  v_latest_url text;
  v_latest_msg text;
begin
  if new.project_id is null or lower(coalesce(new.direction,'')) <> 'incoming' then return new; end if;
  v_email := lower(trim(coalesce(new.from_email,'')));
  if v_email = '' then return new; end if;

  -- Internal mailboxes and automated senders are operational traffic, not business relationships.
  -- Token-aware matching catches both `noreply@...` and forms such as `drive-shares-dm-noreply@...`
  -- or `calendar-notification@...` without treating ordinary business addresses as system mail.
  if split_part(v_email,'@',2) = 'prissteel.com'
     or split_part(v_email,'@',2) like '%.prissteel.com'
     or v_email in ('arianitti@me.com','arianit.vllahiu@gmail.com')
     or split_part(v_email,'@',1) ~* '(^|[+._-])(no-?reply|do-?not-?reply|mailer-daemon|postmaster|notifications?|dmarc)([+._-]|$)'
  then
    return new;
  end if;

  select p.name,p.client into v_project_name,v_client from public.projects p where p.id=new.project_id;
  select r.supplier_name into v_supplier
  from public.rfq_log r
  where r.project_id=new.project_id and lower(coalesce(r.supplier_email,''))=v_email
  order by r.sent_at desc nulls last,r.created_at desc limit 1;

  if v_supplier is not null then
    v_kind := 'supplier';
    v_company := v_supplier;
  else
    v_kind := 'client';
    v_company := coalesce(nullif(trim(v_client),''),nullif(split_part(v_email,'@',2),''),'Unknown');
  end if;

  select c.id into v_contact_id
  from public.contacts c
  where lower(coalesce(c.email,''))=v_email
  order by (c.hubspot_id is not null) desc,c.created_at asc nulls last
  limit 1;

  if v_contact_id is null then
    insert into public.contacts(kind,company,person,email,role,notes,last_contact)
    values(v_kind,v_company,nullif(trim(coalesce(new.from_name,'')),''),v_email,null,'Auto-linked from Gmail through PPPP project context',coalesce(new.sent_at,new.created_at,now())::date)
    returning id into v_contact_id;
  else
    update public.contacts c
       set person=case when nullif(trim(coalesce(c.person,'')),'') is null then nullif(trim(coalesce(new.from_name,'')),'') else c.person end,
           company=case when nullif(trim(coalesce(c.company,'')),'') is null then v_company else c.company end,
           kind=case when lower(coalesce(c.kind,'')) in ('','client') and v_kind='supplier' then 'supplier' else c.kind end,
           last_contact=greatest(coalesce(c.last_contact,'1900-01-01'::date),coalesce(new.sent_at,new.created_at,now())::date)
     where c.id=v_contact_id;
  end if;

  select min(coalesce(e.sent_at,e.created_at)),max(coalesce(e.sent_at,e.created_at)),count(*),
         count(*) filter (where lower(coalesce(e.from_email,''))=v_email),
         coalesce(jsonb_agg(distinct e.project_id::text) filter (where e.project_id is not null),'[]'::jsonb)
    into v_first,v_last,v_count,v_direct,v_projects
  from public.project_emails e
  where lower(coalesce(e.from_email,''))=v_email and lower(coalesce(e.direction,''))='incoming';

  select e.gmail_url,e.gmail_message_id into v_latest_url,v_latest_msg
  from public.project_emails e
  where lower(coalesce(e.from_email,''))=v_email and lower(coalesce(e.direction,''))='incoming'
  order by coalesce(e.sent_at,e.created_at) desc nulls last limit 1;

  insert into public.contact_sources(contact_id,email,source,external_id,external_url,first_seen,last_seen,metadata,created_at,updated_at)
  values(v_contact_id::text,v_email,'gmail',null,v_latest_url,coalesce(v_first,now()),coalesce(v_last,now()),
         jsonb_build_object('message_count',coalesce(v_count,1),'project_ids',coalesce(v_projects,'[]'::jsonb),'latest_gmail_message_id',v_latest_msg),now(),now())
  on conflict (contact_id,source) do update
     set email=excluded.email,external_url=excluded.external_url,
         first_seen=least(public.contact_sources.first_seen,excluded.first_seen),
         last_seen=greatest(public.contact_sources.last_seen,excluded.last_seen),
         metadata=excluded.metadata,updated_at=now();

  insert into public.project_contacts(project_id,email,name,company,role,source,source_message_ids,first_seen,last_seen,email_count,direct_count,cc_count,is_primary,status,created_at,updated_at)
  select new.project_id::text,v_email,
         nullif(trim(coalesce(new.from_name,'')),''),v_company,
         case when v_kind='supplier' then 'supplier' else 'client' end,
         'gmail',
         coalesce(jsonb_agg(e.gmail_message_id order by coalesce(e.sent_at,e.created_at)) filter (where e.gmail_message_id is not null),'[]'::jsonb),
         min(coalesce(e.sent_at,e.created_at)),max(coalesce(e.sent_at,e.created_at)),count(*),count(*),0,
         false,'active',now(),now()
  from public.project_emails e
  where e.project_id=new.project_id and lower(coalesce(e.from_email,''))=v_email and lower(coalesce(e.direction,''))='incoming'
  on conflict (project_id,email) do update
     set name=coalesce(nullif(trim(public.project_contacts.name),''),nullif(excluded.name,'')),
         company=coalesce(nullif(trim(public.project_contacts.company),''),nullif(excluded.company,'')),
         role=coalesce(nullif(trim(public.project_contacts.role),''),nullif(excluded.role,'')),
         source_message_ids=excluded.source_message_ids,
         first_seen=least(coalesce(public.project_contacts.first_seen,excluded.first_seen),excluded.first_seen),
         last_seen=greatest(coalesce(public.project_contacts.last_seen,excluded.last_seen),excluded.last_seen),
         email_count=excluded.email_count,
         direct_count=excluded.direct_count,
         status=case
           when coalesce(nullif(trim(public.project_contacts.source),''),'gmail') in ('gmail','email-auto') then 'active'
           else public.project_contacts.status
         end,
         updated_at=now();

  return new;
end;
$_$;


ALTER FUNCTION public.pppp_sync_contact_from_project_email_v1() OWNER TO postgres;

--
-- Name: pppp_sync_contact_from_project_email_v1_row(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_sync_contact_from_project_email_v1_row(p_email_row_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  r public.project_emails%rowtype;
  v_email text;
  v_contact_id uuid;
  v_company text;
  v_kind text;
  v_supplier text;
  v_client text;
  v_first timestamptz;
  v_last timestamptz;
  v_count int;
  v_projects jsonb;
  v_latest_url text;
  v_latest_msg text;
begin
  select * into r from public.project_emails where id=p_email_row_id;
  if not found or r.project_id is null or lower(coalesce(r.direction,'')) <> 'incoming' then return; end if;
  v_email := lower(trim(coalesce(r.from_email,'')));
  if v_email='' then return; end if;
  if split_part(v_email,'@',2) = 'prissteel.com'
     or split_part(v_email,'@',2) like '%.prissteel.com'
     or v_email in ('arianitti@me.com','arianit.vllahiu@gmail.com')
     or split_part(v_email,'@',1) ~* '(^|[+._-])(no-?reply|do-?not-?reply|mailer-daemon|postmaster|notifications?|dmarc)([+._-]|$)'
  then
    return;
  end if;

  select p.client into v_client from public.projects p where p.id=r.project_id;
  select q.supplier_name into v_supplier
  from public.rfq_log q
  where q.project_id=r.project_id and lower(coalesce(q.supplier_email,''))=v_email
  order by q.sent_at desc nulls last,q.created_at desc limit 1;

  if v_supplier is not null then
    v_kind:='supplier';
    v_company:=v_supplier;
  else
    v_kind:='client';
    v_company:=coalesce(nullif(trim(v_client),''),nullif(split_part(v_email,'@',2),''),'Unknown');
  end if;

  select c.id into v_contact_id
  from public.contacts c
  where lower(coalesce(c.email,''))=v_email
  order by (c.hubspot_id is not null) desc,c.created_at asc nulls last limit 1;

  if v_contact_id is null then
    insert into public.contacts(kind,company,person,email,role,notes,last_contact)
    values(v_kind,v_company,nullif(trim(coalesce(r.from_name,'')),''),v_email,null,'Auto-linked from Gmail through PPPP project context',coalesce(r.sent_at,r.created_at,now())::date)
    returning id into v_contact_id;
  else
    update public.contacts c
       set person=case when nullif(trim(coalesce(c.person,'')),'') is null then nullif(trim(coalesce(r.from_name,'')),'') else c.person end,
           company=case when nullif(trim(coalesce(c.company,'')),'') is null then v_company else c.company end,
           kind=case when lower(coalesce(c.kind,'')) in ('','client') and v_kind='supplier' then 'supplier' else c.kind end,
           last_contact=greatest(coalesce(c.last_contact,'1900-01-01'::date),coalesce(r.sent_at,r.created_at,now())::date)
     where c.id=v_contact_id;
  end if;

  select min(coalesce(e.sent_at,e.created_at)),max(coalesce(e.sent_at,e.created_at)),count(*),
         coalesce(jsonb_agg(distinct e.project_id::text) filter (where e.project_id is not null),'[]'::jsonb)
    into v_first,v_last,v_count,v_projects
  from public.project_emails e
  where lower(coalesce(e.from_email,''))=v_email and lower(coalesce(e.direction,''))='incoming';

  select e.gmail_url,e.gmail_message_id into v_latest_url,v_latest_msg
  from public.project_emails e
  where lower(coalesce(e.from_email,''))=v_email and lower(coalesce(e.direction,''))='incoming'
  order by coalesce(e.sent_at,e.created_at) desc nulls last limit 1;

  insert into public.contact_sources(contact_id,email,source,external_id,external_url,first_seen,last_seen,metadata,created_at,updated_at)
  values(v_contact_id::text,v_email,'gmail',null,v_latest_url,coalesce(v_first,now()),coalesce(v_last,now()),
         jsonb_build_object('message_count',coalesce(v_count,1),'project_ids',coalesce(v_projects,'[]'::jsonb),'latest_gmail_message_id',v_latest_msg),now(),now())
  on conflict (contact_id,source) do update
     set email=excluded.email,external_url=excluded.external_url,
         first_seen=least(public.contact_sources.first_seen,excluded.first_seen),
         last_seen=greatest(public.contact_sources.last_seen,excluded.last_seen),
         metadata=excluded.metadata,updated_at=now();

  insert into public.project_contacts(project_id,email,name,company,role,source,source_message_ids,first_seen,last_seen,email_count,direct_count,cc_count,is_primary,status,created_at,updated_at)
  select r.project_id::text,v_email,
         nullif(trim(coalesce(r.from_name,'')),''),v_company,
         case when v_kind='supplier' then 'supplier' else 'client' end,
         'gmail',
         coalesce(jsonb_agg(e.gmail_message_id order by coalesce(e.sent_at,e.created_at)) filter (where e.gmail_message_id is not null),'[]'::jsonb),
         min(coalesce(e.sent_at,e.created_at)),max(coalesce(e.sent_at,e.created_at)),count(*),count(*),0,
         false,'active',now(),now()
  from public.project_emails e
  where e.project_id=r.project_id and lower(coalesce(e.from_email,''))=v_email and lower(coalesce(e.direction,''))='incoming'
  on conflict (project_id,email) do update
     set name=coalesce(nullif(trim(public.project_contacts.name),''),nullif(excluded.name,'')),
         company=coalesce(nullif(trim(public.project_contacts.company),''),nullif(excluded.company,'')),
         role=coalesce(nullif(trim(public.project_contacts.role),''),nullif(excluded.role,'')),
         source_message_ids=excluded.source_message_ids,
         first_seen=least(coalesce(public.project_contacts.first_seen,excluded.first_seen),excluded.first_seen),
         last_seen=greatest(coalesce(public.project_contacts.last_seen,excluded.last_seen),excluded.last_seen),
         email_count=excluded.email_count,
         direct_count=excluded.direct_count,
         status=case
           when coalesce(nullif(trim(public.project_contacts.source),''),'gmail') in ('gmail','email-auto') then 'active'
           else public.project_contacts.status
         end,
         updated_at=now();
end;
$_$;


ALTER FUNCTION public.pppp_sync_contact_from_project_email_v1_row(p_email_row_id bigint) OWNER TO postgres;

--
-- Name: pppp_sync_execution_release_readiness_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_sync_execution_release_readiness_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare p record; s jsonb; v_ready boolean; v_released boolean; v_checked integer:=0; v_ready_count integer:=0; v_blocked_count integer:=0; v_released_count integer:=0; v_terminal_reviews_closed integer:=0; v_detail text;
begin
  with closed as (update public.tasks t set status='mbyllur',done_at=coalesce(done_at,now()),detail=concat_ws(E'\n',nullif(t.detail,''),'Auto-closed by PPPP: project is terminal, so document review is no longer active work.') where t.source in ('document_bom_review','document_image_review') and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed') and exists(select 1 from public.projects p0 where p0.id=t.project_id and lower(coalesce(p0.status,'')) in ('realizuar','mbyllur','closed','humbur','lost','arkivuar','archived','cancelled','canceled')) returning t.id) select count(*) into v_terminal_reviews_closed from closed;
  update public.tasks t set status='mbyllur',done_at=coalesce(done_at,now()) where t.source='execution_release_readiness' and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed') and not exists(select 1 from public.projects p0 where p0.id=t.project_id and p0.pipeline_stage in ('production_control','factory_audit','transport') and lower(coalesce(p0.status,'')) not in ('realizuar','mbyllur','closed','humbur','lost','arkivuar','archived','cancelled','canceled'));
  for p in select id,name,status,pipeline_stage from public.projects where pipeline_stage in ('production_control','factory_audit','transport') and lower(coalesce(status,'')) not in ('realizuar','mbyllur','closed','humbur','lost','arkivuar','archived','cancelled','canceled') order by name loop
    v_checked:=v_checked+1; v_released:=public.pppp_execution_release_confirmed_v1(p.id);
    if v_released then
      v_released_count:=v_released_count+1;
      update public.tasks t set status='mbyllur',done_at=coalesce(t.done_at,now()),detail=case when position('PPPP: release readiness superseded by confirmed release evidence.' in coalesce(t.detail,''))>0 then t.detail else concat_ws(E'\n',nullif(t.detail,''),'PPPP: release readiness superseded by confirmed release evidence. Evidence/document review remains available backstage but is no longer a Home blocker.') end where t.project_id=p.id and t.source='execution_release_readiness' and lower(coalesce(t.status,'')) not in ('kryer','mbyllur','done','closed');
      continue;
    end if;
    s:=public.pppp_execution_release_snapshot_v1(p.id); v_ready:=coalesce((s->>'ready')::boolean,false); if v_ready then v_ready_count:=v_ready_count+1; else v_blocked_count:=v_blocked_count+1; end if;
    v_detail:='PPPP release-readiness evidence check.'||E'\n'||'Requirements review: '||coalesce(s->>'requirements_review','0')||E'\n'||'BOM needs review: '||coalesce(s->>'bom_review','0')||E'\n'||'Attachment/document blockers: '||coalesce(s->>'attachment_review','0')||E'\n'||'Open document review tasks: '||coalesce(s->>'document_review_tasks','0')||E'\n'||'Confirmed requirements: '||coalesce(s->>'requirements_confirmed','0')||E'\n'||case when v_ready then 'Nuk ka blocker të njohur në evidence queues. HUMAN GATE: verifiko dosjen dhe bëj release/factory-audit vendimin manualisht.' else 'Ka blocker të njohur në evidence queues. Kjo mbetet kontroll teknik backstage dhe nuk duhet të trajtohet si fakt biznesor nëse release-i konfirmohet më vonë.' end;
    insert into public.tasks(project_id,title,detail,due_date,priority,status,done_at,source,source_ref,category) values(p.id,case when v_ready then '[AUTO] Evidence gati për release review — ' else '[AUTO] Release readiness blocked — ' end||p.name,v_detail,current_date,case when v_ready then 'mesatare' else 'e larte' end,case when v_ready then 'kryer' else 'hapur' end,case when v_ready then now() else null end,'execution_release_readiness',p.id::text,'intern') on conflict (source,source_ref) do update set project_id=excluded.project_id,title=excluded.title,detail=excluded.detail,due_date=excluded.due_date,priority=excluded.priority,status=excluded.status,done_at=case when excluded.status='kryer' then coalesce(public.tasks.done_at,excluded.done_at) else null end,category=excluded.category;
  end loop;
  return jsonb_build_object('checked',v_checked,'ready',v_ready_count,'blocked',v_blocked_count,'confirmed_release',v_released_count,'terminal_document_reviews_closed',v_terminal_reviews_closed,'generated_at',now());
end; $$;


ALTER FUNCTION public.pppp_sync_execution_release_readiness_v1() OWNER TO postgres;

--
-- Name: pppp_sync_project_email_link(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_sync_project_email_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.project_id is not null and coalesce(new.gmail_message_id,'') <> '' then
    insert into public.project_email_links(
      gmail_message_id,gmail_thread_id,project_id,link_method,confidence,created_at,updated_at
    )
    select
      new.gmail_message_id,
      new.gmail_thread_id,
      new.project_id::text,
      coalesce(nullif(new.match_method,''),'db-project-email-sync-v1'),
      coalesce(new.match_confidence,95),
      now(),now()
    where not exists (
      select 1 from public.project_email_links l
      where l.gmail_message_id = new.gmail_message_id
        and l.project_id = new.project_id::text
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_sync_project_email_link() OWNER TO postgres;

--
-- Name: pppp_sync_ted_contacts_after_assessment_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_sync_ted_contacts_after_assessment_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.workflow_track<>'ted_award_outreach' or new.company_profile_id is null then return new; end if;
  insert into public.pppp_opportunity_contacts_v1(
    company_profile_id,tender_watch_id,email,full_name,job_title,functional_role,source_type,source_url,
    verification_status,confidence_score,draft_eligible,last_verified_at,payload,updated_at
  )
  select new.company_profile_id,new.tender_watch_id,c.email,c.full_name,c.job_title,c.functional_role,c.source_type,c.source_url,
         'verified',c.confidence_score,true,now(),c.payload,now()
  from public.pppp_ted_contact_candidates_v1(new.tender_watch_id) c
  on conflict(company_profile_id,email) do update set
    tender_watch_id=excluded.tender_watch_id,
    full_name=coalesce(excluded.full_name,public.pppp_opportunity_contacts_v1.full_name),
    job_title=coalesce(excluded.job_title,public.pppp_opportunity_contacts_v1.job_title),
    functional_role=excluded.functional_role,
    source_type=coalesce(excluded.source_type,public.pppp_opportunity_contacts_v1.source_type),
    source_url=coalesce(excluded.source_url,public.pppp_opportunity_contacts_v1.source_url),
    verification_status=case when public.pppp_opportunity_contacts_v1.verification_status='rejected' then 'rejected' else 'verified' end,
    confidence_score=greatest(public.pppp_opportunity_contacts_v1.confidence_score,excluded.confidence_score),
    draft_eligible=case when public.pppp_opportunity_contacts_v1.do_not_contact then false else true end,
    last_verified_at=now(),
    payload=coalesce(public.pppp_opportunity_contacts_v1.payload,'{}'::jsonb)||excluded.payload,
    updated_at=now();
  return new;
end;
$$;


ALTER FUNCTION public.pppp_sync_ted_contacts_after_assessment_v1() OWNER TO postgres;

--
-- Name: pppp_task_detail_trace_dedupe_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_task_detail_trace_dedupe_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_line text;
  v_key text;
  v_seen text[] := array[]::text[];
  v_out text := '';
begin
  if new.detail is null or new.detail='' then return new; end if;

  foreach v_line in array regexp_split_to_array(new.detail,E'\n') loop
    v_key := btrim(v_line);

    /* Keep human/source prose untouched. Collapse only repeated PPPP trace/audit lines. */
    if (v_key like 'PPPP:%' or v_key like '[PPPP%') and v_key = any(v_seen) then
      continue;
    end if;

    if v_key like 'PPPP:%' or v_key like '[PPPP%' then
      v_seen := array_append(v_seen,v_key);
    end if;

    if v_out='' then v_out:=v_line; else v_out:=v_out||E'\n'||v_line; end if;
  end loop;

  new.detail:=v_out;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_task_detail_trace_dedupe_v1() OWNER TO postgres;

--
-- Name: pppp_task_lifecycle_close_enforcer_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_task_lifecycle_close_enforcer_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_downstream_offer boolean:=false;
begin
  if position('PPPP: lifecycle-auto-closed —' in coalesce(new.detail,'')) > 0
     or position('PPPP: lifecycle-dedup —' in coalesce(new.detail,'')) > 0
     or position('PPPP: handoff u zëvendësua nga veprimi konkret i projektit.' in coalesce(new.detail,'')) > 0
     or position('PPPP: downstream-client-offer-auto-closed —' in coalesce(new.detail,'')) > 0 then
    new.status := 'mbyllur';
    new.done_at := coalesce(new.done_at, now());
    return new;
  end if;

  if new.project_id is not null
     and new.source='project_decision_auto'
     and lower(coalesce(new.status,'')) not in ('kryer','mbyllur','done','closed') then
    select
      exists(
        select 1
        from public.documents_registry d
        where d.project_id=new.project_id
          and d.series='QUO'
          and (
            lower(coalesce(d.offer_state->>'pst_document_status',''))='sent'
            or nullif(d.offer_state->>'sent_at','') is not null
          )
      )
      or exists(
        select 1
        from public.project_emails e
        where e.project_id=new.project_id
          and e.direction='outgoing'
          and e.sent_at >= coalesce(new.created_at,'epoch'::timestamptz)
          and coalesce(e.has_attachments,false)
          and lower(coalesce(e.subject,'')||' '||coalesce(e.snippet,''))
              ~ '(offer|quotation|quote|angebot|offerte|ponuda|ofert[aeë])'
      )
    into v_downstream_offer;

    if v_downstream_offer then
      new.status:='mbyllur';
      new.done_at:=coalesce(new.done_at,now());
      new.detail:=concat_ws(E'\n',nullif(new.detail,''),
        'PPPP: downstream-client-offer-auto-closed — një ofertë outbound e lidhur me të njëjtin projekt e ka zëvendësuar këtë quote/decision task.');
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_task_lifecycle_close_enforcer_v1() OWNER TO postgres;

--
-- Name: pppp_task_lifecycle_project_trigger_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_task_lifecycle_project_trigger_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if pg_trigger_depth() > 1 then return new; end if;
  perform public.pppp_task_lifecycle_reconcile_v1(new.id);
  return new;
end;
$$;


ALTER FUNCTION public.pppp_task_lifecycle_project_trigger_v1() OWNER TO postgres;

--
-- Name: pppp_task_lifecycle_reconcile_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_task_lifecycle_reconcile_v1(p_project_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_terminal_closed integer := 0;
  v_execution_closed integer := 0;
  v_handoff_closed integer := 0;
  v_duplicates_closed integer := 0;
begin
  update public.tasks t
     set status = 'mbyllur',
         done_at = coalesce(t.done_at, now()),
         detail = case
           when position('PPPP: lifecycle-auto-closed — project terminal.' in coalesce(t.detail,'')) > 0 then t.detail
           else concat_ws(E'\n', nullif(t.detail,''), 'PPPP: lifecycle-auto-closed — project terminal.')
         end
    from public.projects p
   where p.id = t.project_id
     and (p_project_id is null or p.id = p_project_id)
     and t.status = 'hapur'
     and lower(coalesce(p.status,'')) in ('humbur','lost','arkivuar','archived','mbyllur','closed','closedlost','cancelled','canceled','realizuar')
     and t.source in ('project_decision_auto','email_request_auto','supplier_update_auto','dynamic_plan_auto','sla_auto','auto_followup','semantic_brain_auto','commercial_intake_review','project_discovery_auto','execution_won','execution_release_readiness','document_bom_review','opportunity_engine_v2');
  get diagnostics v_terminal_closed = row_count;

  update public.tasks t
     set status = 'mbyllur',
         done_at = coalesce(t.done_at, now()),
         detail = case
           when position('PPPP: lifecycle-auto-closed — execution superseded this pre-award action.' in coalesce(t.detail,'')) > 0 then t.detail
           else concat_ws(E'\n', nullif(t.detail,''), 'PPPP: lifecycle-auto-closed — execution superseded this pre-award action.')
         end
    from public.projects p
   where p.id = t.project_id
     and (p_project_id is null or p.id = p_project_id)
     and t.status = 'hapur'
     and lower(coalesce(p.operational_state,'')) = 'execution'
     and t.source in ('project_decision_auto','email_request_auto','supplier_update_auto','dynamic_plan_auto','sla_auto','auto_followup','semantic_brain_auto','commercial_intake_review','project_discovery_auto','opportunity_engine_v2');
  get diagnostics v_execution_closed = row_count;

  update public.tasks h
     set status = 'mbyllur',
         done_at = coalesce(h.done_at, now()),
         detail = case
           when position('PPPP: handoff u zëvendësua nga veprimi konkret i projektit.' in coalesce(h.detail,'')) > 0 then h.detail
           else concat_ws(E'\n', nullif(h.detail,''), 'PPPP: handoff u zëvendësua nga veprimi konkret i projektit.')
         end
   where h.status = 'hapur'
     and h.source = 'project_discovery_auto'
     and h.project_id is not null
     and (p_project_id is null or h.project_id = p_project_id)
     and exists (select 1 from public.tasks t2 where t2.project_id = h.project_id and t2.status = 'hapur' and coalesce(t2.source,'') <> 'project_discovery_auto');
  get diagnostics v_handoff_closed = row_count;

  with ranked as (
    select t.id,
           row_number() over (
             partition by t.project_id, t.source, regexp_replace(lower(btrim(coalesce(t.title,''))), '[[:space:]]+', ' ', 'g')
             order by t.created_at desc, t.id desc
           ) as rn
      from public.tasks t
     where t.status = 'hapur'
       and t.project_id is not null
       and (p_project_id is null or t.project_id = p_project_id)
       and btrim(coalesce(t.title,'')) <> ''
       and t.source in ('project_decision_auto','email_request_auto','supplier_update_auto','dynamic_plan_auto','sla_auto','auto_followup','semantic_brain_auto','commercial_intake_review','project_discovery_auto','execution_won','execution_release_readiness','document_bom_review','opportunity_engine_v2')
  ), duplicates as (select id from ranked where rn > 1)
  update public.tasks t
     set status = 'mbyllur',
         done_at = coalesce(t.done_at, now()),
         detail = case
           when position('PPPP: lifecycle-dedup — superseded by newer equivalent automated action.' in coalesce(t.detail,'')) > 0 then t.detail
           else concat_ws(E'\n', nullif(t.detail,''), 'PPPP: lifecycle-dedup — superseded by newer equivalent automated action.')
         end
    from duplicates d
   where t.id = d.id;
  get diagnostics v_duplicates_closed = row_count;

  return jsonb_build_object('project_id',p_project_id,'terminal_closed',v_terminal_closed,'execution_closed',v_execution_closed,'handoff_closed',v_handoff_closed,'duplicates_closed',v_duplicates_closed,'total_closed',v_terminal_closed+v_execution_closed+v_handoff_closed+v_duplicates_closed,'reconciled_at',now());
end;
$$;


ALTER FUNCTION public.pppp_task_lifecycle_reconcile_v1(p_project_id uuid) OWNER TO postgres;

--
-- Name: pppp_task_lifecycle_task_trigger_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_task_lifecycle_task_trigger_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if pg_trigger_depth() > 1 then return new; end if;
  if new.project_id is not null then perform public.pppp_task_lifecycle_reconcile_v1(new.project_id); end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_task_lifecycle_task_trigger_v1() OWNER TO postgres;

--
-- Name: pppp_ted_action_communication_guard_v1(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_ted_action_communication_guard_v1(p_action_id uuid, p_recipient_email text, p_company_domain text, p_exclude_registry_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_guard jsonb;
  v_has_same_action_draft boolean := false;
  v_has_other_conflict boolean := false;
begin
  v_guard := public.pppp_global_communication_guard_v1(
    p_recipient_email,
    p_company_domain,
    'TED',
    p_exclude_registry_id,
    null
  );

  if coalesce((v_guard->>'ok')::boolean,false) then
    return v_guard;
  end if;

  if coalesce(v_guard->>'reason','') not in (
    'cross_source_active_recipient_outreach',
    'cross_source_active_domain_outreach'
  ) then
    return v_guard;
  end if;

  select
    coalesce(bool_or(
      c->>'source'='TED'
      and c->>'kind'='active_draft'
      and r.action_id=p_action_id
    ),false),
    coalesce(bool_or(not (
      c->>'source'='TED'
      and c->>'kind'='active_draft'
      and r.action_id=p_action_id
    )),false)
  into v_has_same_action_draft,v_has_other_conflict
  from jsonb_array_elements(coalesce(v_guard->'conflicts','[]'::jsonb)) c
  left join public.pppp_opportunity_outreach_registry_v1 r
    on r.id::text=c->>'event_id';

  if v_has_same_action_draft and not v_has_other_conflict then
    return v_guard || jsonb_build_object(
      'ok',true,
      'reason','same_ted_action_draft_batch',
      'same_action_id',p_action_id
    );
  end if;

  return v_guard;
end;
$$;


ALTER FUNCTION public.pppp_ted_action_communication_guard_v1(p_action_id uuid, p_recipient_email text, p_company_domain text, p_exclude_registry_id uuid) OWNER TO postgres;

--
-- Name: pppp_ted_award_candidates_by_email_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_ted_award_candidates_by_email_v1(p_email text) RETURNS TABLE(tender_watch_id uuid, publication_no text, authority text, title text, status text, payload jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select k.id, k.publication_no, k.authority, k.title, k.status, k.payload
  from public.kek_tender_watch k
  where length(trim(coalesce(p_email,''))) >= 5
    and upper(coalesce(k.payload->>'source',''))='TED'
    and coalesce(k.payload->>'notice_phase','')='award'
    and lower(k.payload::text) like '%' || lower(trim(p_email)) || '%'
  order by k.published_date desc nulls last, k.updated_at desc;
$$;


