--
-- Name: pppp_ted_company_role_context_v2(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_ted_company_role_context_v2(p_winner jsonb, p_award_role jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_role jsonb := public.pppp_ted_company_role_v2(p_winner);
  v_award_type text := lower(coalesce(p_award_role->>'type',''));
  v_award_conf text := lower(coalesce(p_award_role->>'confidence',''));
begin
  if coalesce(v_role->>'category','other_unclear')='other_unclear'
     and v_award_type='gc_epc'
     and v_award_conf in ('medium','high') then
    return v_role || jsonb_build_object(
      'category','gc_epc',
      'subcategory','general_contractor_or_epc',
      'confidence',v_award_conf,
      'outreach_model','steel_package_subcontracting',
      'approach','Approach as GC/EPC: offer PRISTEEL as a subcontractor/supplier for a defined fabricated-steel package with coordinated DAP delivery.',
      'evidence',jsonb_build_array('TED award-role evidence identifies GC/EPC with '||v_award_conf||' confidence'),
      'requires_role_verification',false
    );
  end if;
  return v_role;
end;
$$;


ALTER FUNCTION public.pppp_ted_company_role_context_v2(p_winner jsonb, p_award_role jsonb) OWNER TO postgres;

--
-- Name: pppp_ted_company_role_v2(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_ted_company_role_v2(p_winner jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_winner jsonb := coalesce(p_winner,'{}'::jsonb);
  v_name text := lower(coalesce(p_winner->>'name',''));
  v_domain text := lower(coalesce(
    p_winner#>>'{contact_enrichment,organizations,0,domain}',
    p_winner->>'website',
    ''
  ));
  v_org_text text := '';
  v_text text := '';
  v_legacy text := lower(coalesce(
    p_winner->>'company_type',
    p_winner#>>'{company_classification,company_type}',
    'unknown'
  ));
  v_category text := 'other_unclear';
  v_subcategory text := 'unresolved';
  v_confidence text := 'low';
  v_outreach_model text := 'verify_company_role_before_outreach';
  v_approach text := 'Verify the company role before preparing targeted outreach.';
  v_evidence jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(v_winner#>'{contact_enrichment,organizations}')='array' then
    select lower(coalesce(string_agg(
      concat_ws(' ',
        o->>'name',
        o->>'domain',
        o->>'business_summary',
        o->>'description'
      ), ' '
    ),''))
    into v_org_text
    from jsonb_array_elements(v_winner#>'{contact_enrichment,organizations}') o;
  end if;

  v_text := lower(concat_ws(' ',v_name,v_domain,v_org_text));

  if v_name ~ '(consortium|konsortium|konsorc|consorzio|groupement|coentreprise|joint[ -]?venture|(^|[^a-z])jv([^a-z]|$)|(^|[^a-z])arge([^a-z]|$)|arbeitsgemeinschaft)' then
    v_category := 'consortium_jv';
    v_subcategory := 'joint_venture_or_consortium';
    v_confidence := 'high';
    v_outreach_model := 'identify_steel_scope_member';
    v_approach := 'Identify which consortium member owns the steel scope before targeted outreach.';
    v_evidence := jsonb_build_array('company name explicitly indicates consortium/JV');

  elsif v_text ~ '(trading|trader|(^|[^a-z])handel([^a-z]|$)|handels|distribut|stockhold|service[ -]?cent(er|re)|grosshandel|großhandel|wholesale|n[eé]goce|suministros)' then
    v_category := 'trader_distributor';
    v_subcategory := 'trader_distributor_service_center';
    v_confidence := case when v_name ~ '(trading|trader|handel|handels|distribut|stockhold|service[ -]?cent(er|re)|grosshandel|großhandel|wholesale|n[eé]goce|suministros)' then 'high' else 'medium' end;
    v_outreach_model := 'fabrication_and_processing_partner';
    v_approach := 'Approach as a material/trading company: offer fabrication, processing and project delivery support without assuming in-house fabrication.';
    v_evidence := jsonb_build_array('company evidence indicates trading/distribution/service-center activity');

  elsif v_text ~ '(stahlwerk|steel[ -]?works|steel[ -]?mill|rolling[ -]?mill|walzwerk|aci[eé]rie|siderurg|smelter|foundry|fonderie|metallurg)' then
    v_category := 'steel_mill_producer';
    v_subcategory := 'primary_steel_producer';
    v_confidence := case when v_name ~ '(stahlwerk|steel[ -]?works|steel[ -]?mill|rolling[ -]?mill|walzwerk|aci[eé]rie|siderurg|smelter|foundry|fonderie|metallurg)' then 'high' else 'medium' end;
    v_outreach_model := 'downstream_fabrication_partner';
    v_approach := 'Approach as a primary steel producer: position PRISTEEL for downstream fabrication, processing, documentation and project delivery.';
    v_evidence := jsonb_build_array('company evidence indicates primary steel production/mill activity');

  elsif v_text ~ '(fenster|window|fassad|facade|façade|verglas|glazing|glasbau|flachdach|dachbau|roof|trockenbau|drywall|tischler|carpentry|joinery|bauelemente|t[uü]renbau|door)' then
    v_category := 'specialist_contractor';
    v_subcategory := 'facade_windows_roofing_or_specialist_trade';
    v_confidence := case when v_name ~ '(fenster|window|fassad|facade|façade|verglas|glazing|glasbau|flachdach|dachbau|roof|trockenbau|drywall|tischler|carpentry|joinery|bauelemente|t[uü]renbau|door)' then 'high' else 'medium' end;
    v_outreach_model := 'specialist_scope_fabrication_support';
    v_approach := 'Approach only around the specialist package and any clearly separable fabricated-steel components.';
    v_evidence := jsonb_build_array('company evidence indicates a specialist construction trade');

  elsif v_text ~ '(stahlbau|metallbau|steel[ -]?(fabricat|construction)|structural[ -]?steel|metal[ -]?fabricat|metal[ -]?construction|charpente[^ ]*[ -]?m[eé]tall|konstrukcj[^ ]*[ -]?stal|konstrukc[^ ]*[ -]?ocel|kovov[^ ]*[ -]?konstruk|schlosserei)' then
    v_category := 'steel_fabricator';
    v_subcategory := 'structural_steel_or_metal_fabrication';
    v_confidence := case when v_name ~ '(stahlbau|metallbau|steel[ -]?(fabricat|construction)|structural[ -]?steel|metal[ -]?fabricat|metal[ -]?construction|charpente[^ ]*[ -]?m[eé]tall|konstrukcj[^ ]*[ -]?stal|konstrukc[^ ]*[ -]?ocel|kovov[^ ]*[ -]?konstruk|schlosserei)' then 'high' else 'medium' end;
    v_outreach_model := 'external_fabrication_capacity';
    v_approach := 'Approach as a steel fabricator: offer overflow/external fabrication capacity for clearly separated packages without interfering in the client relationship.';
    v_evidence := jsonb_build_array('company evidence indicates structural-steel/metal fabrication');

  elsif v_text ~ '(bauunternehmen|bauunternehmung|baugesellschaft|general[ -]?contractor|(^|[^a-z])epc([^a-z]|$)|construction|construct|entreprise[^ ]*[ -]?(g[eé]n[eé]rale|construction)|budowlan|entrepren|bygg|obras|bouwbedrijf|anlagenbau)' then
    v_category := 'gc_epc';
    v_subcategory := 'general_contractor_or_epc';
    v_confidence := case when v_name ~ '(bauunternehmen|bauunternehmung|baugesellschaft|general[ -]?contractor|(^|[^a-z])epc([^a-z]|$)|construction|construct|entreprise[^ ]*[ -]?(g[eé]n[eé]rale|construction)|budowlan|entrepren|bygg|obras|bouwbedrijf|anlagenbau)' then 'high' else 'medium' end;
    v_outreach_model := 'steel_package_subcontracting';
    v_approach := 'Approach as GC/EPC: offer PRISTEEL as a subcontractor/supplier for a defined fabricated-steel package with coordinated DAP delivery.';
    v_evidence := jsonb_build_array('company evidence indicates general-contractor/EPC activity');

  elsif v_legacy='gc_epc' then
    v_category := 'gc_epc';
    v_subcategory := 'general_contractor_or_epc';
    v_confidence := 'medium';
    v_outreach_model := 'steel_package_subcontracting';
    v_approach := 'Approach as GC/EPC, while retaining a medium-confidence verification flag.';
    v_evidence := jsonb_build_array('legacy GC/EPC classification retained as medium-confidence fallback');

  elsif v_legacy='producer' then
    v_evidence := jsonb_build_array('legacy producer classification is too broad to distinguish fabricator from mill/manufacturer');

  elsif v_legacy in ('trader_consortium','consortium_mixed') then
    v_evidence := jsonb_build_array('legacy trader/consortium bucket is intentionally not trusted without specific company evidence');
  end if;

  return jsonb_build_object(
    'version','ted-company-role-v2',
    'category',v_category,
    'subcategory',v_subcategory,
    'confidence',v_confidence,
    'evidence',v_evidence,
    'outreach_model',v_outreach_model,
    'approach',v_approach,
    'legacy_company_type',v_legacy,
    'requires_role_verification',(v_category='other_unclear')
  );
end;
$_$;


ALTER FUNCTION public.pppp_ted_company_role_v2(p_winner jsonb) OWNER TO postgres;

--
-- Name: pppp_ted_company_segment_v2(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_ted_company_segment_v2(p_company_name text, p_legacy_type text DEFAULT NULL::text, p_cooperation_angle text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  v_name text := lower(coalesce(p_company_name,''));
  v_legacy text := lower(coalesce(p_legacy_type,''));
  v_category text := 'other_unclear';
  v_label text := 'Other / Unclear';
  v_confidence text := 'review';
  v_score integer := 30;
  v_source text := 'insufficient_evidence';
  v_evidence jsonb := '[]'::jsonb;
begin
  if v_name ~ '(consortium|konsortium|joint[ -]?venture|arbeitsgemeinschaft|(^|[^a-z])arge([^a-z]|$))'
     or v_legacy = 'consortium_mixed' then
    v_category := 'consortium_jv'; v_label := 'Consortium / JV'; v_confidence := 'high'; v_score := 90; v_source := 'company_identity';
    v_evidence := jsonb_build_array('Company identity explicitly indicates consortium/JV');

  elsif v_name ~ '(stahlwerk|steelworks|steel[ -]?mill|rolling[ -]?mill|walzwerk|tube[ -]?mill|pipe[ -]?mill|plate[ -]?mill)' then
    v_category := 'steel_producer_mill'; v_label := 'Steel Producer / Mill'; v_confidence := 'high'; v_score := 90; v_source := 'company_identity';
    v_evidence := jsonb_build_array('Company identity indicates primary steel production/mill activity');

  elsif v_name ~ '(stahlhandel|metallhandel|steel[ -]?(trading|trader)|metal[ -]?(trading|trader)|stockholder|service[ -]?cent(er|re)|distribut|wholesal)' then
    v_category := 'trader_distributor'; v_label := 'Trader / Distributor'; v_confidence := 'high'; v_score := 88; v_source := 'company_identity';
    v_evidence := jsonb_build_array('Company identity indicates trading/distribution/service-center activity');

  elsif v_name ~ '(generalunternehmer|general[ -]?contractor|bauunternehmen|baugesellschaft|construction[ -]?(company|group)|epc[ -]?contractor|turnkey[ -]?contractor)'
        or v_legacy = 'gc_epc' then
    v_category := 'gc_epc'; v_label := 'GC / EPC';
    v_confidence := case when v_name ~ '(generalunternehmer|general[ -]?contractor|bauunternehmen|baugesellschaft|construction[ -]?(company|group)|epc[ -]?contractor|turnkey[ -]?contractor)' then 'high' else 'medium' end;
    v_score := case when v_confidence='high' then 88 else 68 end;
    v_source := case when v_confidence='high' then 'company_identity' else 'legacy_classification' end;
    v_evidence := jsonb_build_array(case when v_confidence='high' then 'Company identity indicates GC/EPC/construction contractor activity' else 'Legacy TED classification indicates GC/EPC; company identity still needs confirmation' end);

  elsif v_name ~ '(trockenbau|fensterbau|glasbau|(^|[^a-z])glas([^a-z]|$)|bauelemente|fassadenbau|flachdach|dachbau|roofing|glazing|facade|fassade|fenster|tischler|carpentr|joinery|drywall|holzhandwerk|door|türen|tueren)' then
    v_category := 'specialist_contractor'; v_label := 'Specialist Contractor'; v_confidence := 'medium'; v_score := 74; v_source := 'company_identity';
    v_evidence := jsonb_build_array('Company identity indicates a specialist trade rather than general steel fabrication');

  elsif v_name ~ '(stahl[ -]?und[ -]?metallbau|stahlbau|metallbau|metalbau|steel[ -]?fabricat|structural[ -]?steel[ -]?fabricat|steel[ -]?construction|metal[ -]?construction|schlosserei)' then
    v_category := 'steel_fabricator'; v_label := 'Steel / Metal Fabricator'; v_confidence := 'medium'; v_score := 78; v_source := 'company_identity';
    v_evidence := jsonb_build_array('Company identity strongly indicates steel/metal fabrication; production scope should be confirmed from company evidence');

  else
    if v_legacy = 'producer' then
      v_evidence := jsonb_build_array('Legacy type is producer, but it does not distinguish fabricator from steel mill/producer');
      v_source := 'legacy_ambiguous'; v_score := 40;
    elsif v_legacy = 'trader_consortium' then
      v_evidence := jsonb_build_array('Legacy type combines trader and consortium and must be split before outreach');
      v_source := 'legacy_ambiguous'; v_score := 35;
    else
      v_evidence := jsonb_build_array('No sufficiently strong company-role evidence is available yet');
    end if;
  end if;

  return jsonb_build_object(
    'category',v_category,'label',v_label,'confidence',v_confidence,'score',v_score,
    'source',v_source,'evidence',v_evidence,'legacy_type',nullif(v_legacy,''),
    'cooperation_angle',nullif(p_cooperation_angle,'')
  );
end;
$_$;


ALTER FUNCTION public.pppp_ted_company_segment_v2(p_company_name text, p_legacy_type text, p_cooperation_angle text) OWNER TO postgres;

--
-- Name: pppp_ted_company_segment_v3(text, text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_ted_company_segment_v3(p_company_name text, p_company_domain text DEFAULT NULL::text, p_legacy_type text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_scope_text text DEFAULT NULL::text, p_class_evidence jsonb DEFAULT '[]'::jsonb, p_cooperation_angle text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  nm text := lower(coalesce(p_company_name,''));
  dm text := lower(coalesce(p_company_domain,''));
  legacy text := lower(coalesce(p_legacy_type,''));
  ttl text := lower(coalesce(p_title,''));
  scp text := lower(coalesce(p_scope_text,''));
  ev text := lower(coalesce(p_class_evidence::text,'[]'));
  cat text := 'other_unclear';
  lbl text := 'Other / Unclear';
  conf text := 'review';
  score int := 30;
  src text := 'insufficient_evidence';
  evid jsonb := '[]'::jsonb;
begin
  if nm ~ '(consortium|konsortium|joint[ -]?venture|arbeitsgemeinschaft|(^|[^a-z])arge([^a-z]|$)|bige )' then
    cat:='consortium_jv'; lbl:='Consortium / JV'; conf:='high'; score:=90; src:='company_identity';
    evid:=jsonb_build_array('Company identity explicitly indicates a consortium/JV entity');

  elsif nm ~ '(stahlwerk|steelworks|steel[ -]?mill|walzwerk|rolling[ -]?mill|tube[ -]?mill|pipe[ -]?mill)' then
    cat:='steel_producer_mill'; lbl:='Steel Producer / Mill'; conf:='high'; score:=90; src:='company_identity';
    evid:=jsonb_build_array('Company identity indicates primary steel production/mill activity');

  elsif nm ~ '(stahlhandel|metallhandel|steel[ -]?(trading|trade|trader)|metal[ -]?(trading|trade|trader)|stockholder|service[ -]?cent(er|re)|distribut|wholesal)'
        or dm ~ '(steeltrade|stahlhandel|metallhandel)' then
    cat:='trader_distributor'; lbl:='Trader / Distributor'; conf:='high'; score:=88; src:='company_identity';
    evid:=jsonb_build_array('Company identity/domain indicates trading, distribution or service-center activity');

  elsif nm ~ '(stahl[ -]?und[ -]?metallbau|stahlbau|metallbau|metalbau|schlosserei|steel[ -]?fabricat|structural[ -]?steel)'
        or dm ~ '(stahlbau|metallbau|bauschlosserei)'
        or ev ~ '(explicit steel-fabrication|stahlbau|schlosserei)' then
    cat:='steel_fabricator'; lbl:='Steel / Metal Fabricator'; conf:='high'; score:=90; src:='company_identity';
    evid:=jsonb_build_array('Company identity/domain or enrichment explicitly indicates steel/metal fabrication');

  elsif (ttl||' '||scp) ~ '(structural steelworks|installation of metal structures|stahlbau|schlosser|metalworking|welding|fertigung.*(träger|traeger)|steel structure)'
        and (legacy='producer' or ev ~ '(manufacturing/fabrication|fabrication processes|production)') then
    cat:='steel_fabricator'; lbl:='Steel / Metal Fabricator'; conf:='medium'; score:=76; src:='award_plus_enrichment';
    evid:=jsonb_build_array('Award scope is steel/metal fabrication and existing enrichment supports production/fabrication capability');

  elsif nm ~ '(anlagenbau|maschinenbau|engineering|technik|technical|industry|industrial|energy|hydro|railtec)'
        or dm ~ '(andritz|siemens-energy|abindustry|zahnen-technik)' then
    cat:='industrial_oem_engineering'; lbl:='Industrial OEM / Engineering'; conf:='medium'; score:=74; src:='company_identity';
    evid:=jsonb_build_array('Company identity/domain indicates industrial plant, machinery, engineering or OEM activity');

  elsif nm ~ '(trockenbau|fensterbau|glasbau|fassadenbau|flachdach|dachbau|tischler|maler|painting|roof|glazing|facade)'
        or ttl ~ '(trockenbau|painting work|roofing|glazing|facade|drywall|fenster|türen|tueren)' then
    cat:='specialist_contractor'; lbl:='Specialist Contractor'; conf:='medium'; score:=72; src:='company_or_award_trade';
    evid:=jsonb_build_array('Company identity or awarded trade indicates a specialist contractor');

  elsif nm ~ '(bauunternehmen|tiefbau|strassenbau|straßenbau|bygg|stavby|construction|edil|eurovia|metrostav|repont|road|infra)'
        or ttl ~ '(construction work|bridge construction|roadworks|railway bridge|substation construction|overhead line construction|works for complete or part construction|structures construction work|building construction work|civil engineering work)' then
    cat:='gc_epc'; lbl:='GC / EPC / Contractor'; conf:='medium'; score:=68; src:='company_or_award_role';
    evid:=jsonb_build_array('Company identity or awarded works scope supports contractor/GC/EPC treatment for outreach');

  else
    evid:=jsonb_build_array(
      case
        when legacy='trader_consortium' then 'Legacy trader_consortium label is not treated as company type because it often only reflects multi-award/consortium structure'
        when legacy='producer' then 'Legacy producer label is insufficient to distinguish fabricator, OEM and primary steel producer'
        else 'No sufficiently strong company-role evidence is available yet'
      end
    );
  end if;

  return jsonb_build_object(
    'category',cat,'label',lbl,'confidence',conf,'score',score,'source',src,'evidence',evid,
    'legacy_type',nullif(legacy,''),'cooperation_angle',nullif(p_cooperation_angle,'')
  );
end;
$_$;


ALTER FUNCTION public.pppp_ted_company_segment_v3(p_company_name text, p_company_domain text, p_legacy_type text, p_title text, p_scope_text text, p_class_evidence jsonb, p_cooperation_angle text) OWNER TO postgres;

--
-- Name: pppp_ted_contact_candidates_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_ted_contact_candidates_v1(p_tender_watch_id uuid) RETURNS TABLE(email text, full_name text, job_title text, functional_role text, source_type text, source_url text, confidence_score integer, payload jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
with t as (
  select id,title,source_url,detail_url,payload
  from public.kek_tender_watch
  where id=p_tender_watch_id
    and upper(coalesce(payload->>'source',''))='TED'
    and coalesce(payload->>'notice_phase','')='award'
    and nullif(btrim(payload->'winner'->>'name'),'') is not null
),
w as (
  select t.*,t.payload->'winner' winner,
         public.pppp_opportunity_company_key_v1(t.payload->'winner'->>'name') winner_key
  from t
),
declared as (
  select
    w.*,
    lower(btrim(e.value)) as email,
    e.ord::int as ord,
    coalesce(
      nullif(w.winner->'names'->>((e.ord-1)::int),''),
      nullif(w.winner->>'name','')
    ) as owner_name
  from w
  cross join lateral jsonb_array_elements_text(coalesce(w.winner->'emails','[]'::jsonb))
    with ordinality as e(value,ord)
  union all
  select
    w.*,
    lower(btrim(w.winner->>'email')) as email,
    1 as ord,
    nullif(w.winner->>'name','') as owner_name
  from w
  where nullif(btrim(w.winner->>'email'),'') is not null
    and coalesce(jsonb_array_length(coalesce(w.winner->'names','[]'::jsonb)),0)<=1
),
direct_raw as (
  select distinct
    d.email,
    null::text full_name,
    null::text job_title,
    case when lower(d.email)~'(procurement|purchasing|einkauf|tender|vergabe|przetarg|poptav|nabidk|compras)' then 'procurement'
         when lower(d.email)~'(technical|technik|engineering)' then 'technical'
         when lower(d.email)~'(project|projekt)' then 'project'
         when lower(d.email)~'(sales|commercial|verkauf)' then 'commercial'
         else 'general' end functional_role,
    'ted_winner_organization'::text source_type,
    coalesce(d.detail_url,d.source_url) source_url,
    95 confidence_score,
    jsonb_build_object(
      'company_attribution','ted_winner_organization',
      'recipient_company_name',d.owner_name,
      'recipient_company_identifier',d.winner->>'identifier',
      'identity_version',d.winner->>'identity_version'
    ) payload
  from declared d
  where coalesce(d.winner->>'identity_version','')='ted-winner-canonical-v2'
    and nullif(btrim(d.winner->>'identifier'),'') is not null
    and coalesce(d.email,'')~*'^[^[:space:]@<>]+@[^[:space:]@<>]+\.[^[:space:]@<>]+$'
    and public.pppp_opportunity_company_key_v1(d.owner_name)=d.winner_key
    and (
      public.pppp_opportunity_domain_plausible_v1(d.owner_name,split_part(d.email,'@',2))
      or (
        public.pppp_opportunity_company_key_v1(d.owner_name)=d.winner_key
        and exists (
          select 1
          from jsonb_array_elements_text(coalesce(d.winner->'ted_declared_emails','[]'::jsonb)) proof(email)
          where lower(btrim(proof.email))=d.email
        )
      )
    )
    and public.pppp_outreach_contact_tier_v2(d.email,null,null)<>'F'
),
orgs as (
  select w.*,o.org,count(*) over(partition by w.id) org_count,
         public.pppp_opportunity_company_key_v1(o.org->>'name') org_key,
         lower(regexp_replace(
           coalesce(nullif(o.org->>'domain',''),nullif(o.org->>'official_website','')),
           '^https?://(www\.)?|/.*$','','gi'
         )) org_domain
  from w
  cross join lateral jsonb_array_elements(coalesce(w.winner->'contact_enrichment'->'organizations','[]'::jsonb)) o(org)
),
enriched_raw as (
  select
    lower(btrim(c.contact->>'value')) email,
    nullif(coalesce(c.contact->>'name',c.contact->>'full_name',c.contact->>'person_name'),'') full_name,
    nullif(coalesce(c.contact->>'job_title',c.contact->>'title'),'') job_title,
    case when lower(coalesce(c.contact->>'purpose',''))~'(procurement|purchasing|einkauf|tender|vergabe|sourcing)' then 'procurement'
         when lower(coalesce(c.contact->>'purpose',''))~'(technical|technik|engineering)' then 'technical'
         when lower(coalesce(c.contact->>'purpose',''))~'(project|projekt)' then 'project'
         when lower(coalesce(c.contact->>'purpose',''))~'(production|fertigung)' then 'production'
         when lower(coalesce(c.contact->>'purpose',''))~'(sales|commercial|verkauf)' then 'commercial'
         when lower(coalesce(c.contact->>'purpose',''))~'(management|director|geschäfts|geschaefts)' then 'management'
         else 'general' end functional_role,
    coalesce(nullif(c.contact->>'source_type',''),'ted_contact_enrichment') source_type,
    coalesce(nullif(c.contact->>'source_url',''),o.detail_url,o.source_url) source_url,
    greatest(0,least(100,
      case when coalesce(c.contact->>'score','')~'^[0-9]+(\.[0-9]+)?$'
           then round((c.contact->>'score')::numeric)::int
           when lower(coalesce(c.contact->>'confidence',''))='high' then 90
           when lower(coalesce(c.contact->>'confidence',''))='medium' then 80
           else 75 end
    )) confidence_score,
    jsonb_build_object(
      'company_attribution','contact_enrichment',
      'recipient_company_name',o.org->>'name',
      'organization_name',o.org->>'name',
      'organization_domain',nullif(o.org_domain,'')
    ) payload
  from orgs o
  cross join lateral jsonb_array_elements(coalesce(o.org->'contacts','[]'::jsonb)) c(contact)
  where coalesce(c.contact->>'type','')='email'
    and coalesce(c.contact->>'value','')~*'^[^[:space:]@<>]+@[^[:space:]@<>]+\.[^[:space:]@<>]+$'
    and lower(coalesce(c.contact->>'draft_eligible','true'))<>'false'
    and (
      lower(coalesce(c.contact->>'confidence','')) in ('high','medium')
      or (
        coalesce(c.contact->>'score','')~'^[0-9]+(\.[0-9]+)?$'
        and (c.contact->>'score')::numeric>=80
      )
    )
    and nullif(o.org_key,'') is not null
    and nullif(o.winner_key,'') is not null
    and (o.org_key=o.winner_key or o.org_count=1)
    and nullif(o.org_domain,'') is not null
    and public.pppp_opportunity_domain_plausible_v1(o.org->>'name',o.org_domain)
    and (
      split_part(lower(c.contact->>'value'),'@',2)=o.org_domain
      or split_part(lower(c.contact->>'value'),'@',2) like '%.'||o.org_domain
    )
    and public.pppp_outreach_contact_tier_v2(
      lower(btrim(c.contact->>'value')),
      nullif(coalesce(c.contact->>'name',c.contact->>'full_name',c.contact->>'person_name'),''),
      nullif(coalesce(c.contact->>'job_title',c.contact->>'title'),'')
    )<>'F'
),
outreach_raw as (
  select
    lower(btrim(o.contact_email)) email,
    null::text full_name,
    null::text job_title,
    case when lower(o.contact_email)~'(procurement|purchasing|einkauf|tender|vergabe|sourcing|przetarg|poptav|nabidk|compras)' then 'procurement'
         when lower(o.contact_email)~'(technical|technik|engineering)' then 'technical'
         when lower(o.contact_email)~'(project|projekt)' then 'project'
         when lower(o.contact_email)~'(sales|commercial|verkauf)' then 'commercial'
         else 'general' end functional_role,
    coalesce(nullif(o.source,''),'outreach_contacts') source_type,
    coalesce(w.detail_url,w.source_url) source_url,
    85 confidence_score,
    jsonb_build_object(
      'company_attribution','outreach_contacts',
      'recipient_company_name',w.winner->>'name'
    ) payload
  from w
  join public.outreach_contacts o
    on nullif(w.winner_key,'') is not null
   and nullif(public.pppp_opportunity_company_key_v1(o.company_name),'') is not null
   and public.pppp_opportunity_company_key_v1(o.company_name)=w.winner_key
  where coalesce(o.contact_email,'')~*'^[^[:space:]@<>]+@[^[:space:]@<>]+\.[^[:space:]@<>]+$'
    and coalesce(o.bounced,false)=false
    and public.pppp_opportunity_domain_plausible_v1(
      w.winner->>'name',
      split_part(lower(o.contact_email),'@',2)
    )
    and public.pppp_outreach_contact_tier_v2(lower(o.contact_email),null,null)<>'F'
),
allc as (
  select * from direct_raw
  union all select * from enriched_raw
  union all select * from outreach_raw
)
select distinct on(email)
  email,full_name,job_title,functional_role,source_type,source_url,confidence_score,payload
from allc
where nullif(email,'') is not null
order by email,confidence_score desc,source_type
$_$;


ALTER FUNCTION public.pppp_ted_contact_candidates_v1(p_tender_watch_id uuid) OWNER TO postgres;

--
-- Name: pppp_ted_outreach_history_guard_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_ted_outreach_history_guard_v1(p_queue_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  q public.pppp_outbound_queue_v1%rowtype;
  p public.pppp_outbound_policy_v1%rowtype;
  v_email text;
  v_domain text;
begin
  select * into q from public.pppp_outbound_queue_v1 where id=p_queue_id;
  if not found then return jsonb_build_object('ok',false,'reason','queue_row_missing'); end if;
  select * into p from public.pppp_outbound_policy_v1 where id='global';
  v_email:=lower(coalesce(q.recipient_email,''));
  v_domain:=lower(coalesce(public.pppp_outbound_domain_v1(q.recipient_email,q.company_domain),''));

  if exists(
    select 1 from public.outreach_contacts h
    where lower(coalesce(h.contact_email,''))=v_email and coalesce(h.bounced,false)
  ) or exists(
    select 1 from public.pppp_outbound_queue_v1 h
    where h.id<>q.id and lower(coalesce(h.recipient_email,''))=v_email and h.bounced_at is not null
  ) then
    return jsonb_build_object('ok',false,'reason','ted_recipient_historical_bounce');
  end if;

  if exists(
    select 1 from public.outreach_contacts h
    where lower(coalesce(h.contact_email,''))=v_email and coalesce(h.replied,false)
  ) or exists(
    select 1 from public.pppp_outbound_queue_v1 h
    where h.id<>q.id and lower(coalesce(h.recipient_email,''))=v_email and h.replied_at is not null
  ) then
    return jsonb_build_object('ok',false,'reason','ted_recipient_has_reply_requires_human');
  end if;

  if exists(
    select 1 from public.pppp_outbound_queue_v1 h
    where h.id<>q.id
      and lower(coalesce(h.recipient_email,''))=v_email
      and h.sent_at>=now()-make_interval(days=>coalesce(p.recipient_cooldown_days,30))
  ) or exists(
    select 1 from public.outreach_contacts h
    where lower(coalesce(h.contact_email,''))=v_email
      and coalesce(h.touch_3,h.touch_2,h.touch_1)>=current_date-coalesce(p.recipient_cooldown_days,30)
  ) then
    return jsonb_build_object('ok',false,'reason','ted_recipient_cooldown_active');
  end if;

  if v_domain<>'' and (
    exists(
      select 1 from public.pppp_outbound_queue_v1 h
      where h.id<>q.id
        and lower(coalesce(public.pppp_outbound_domain_v1(h.recipient_email,h.company_domain),''))=v_domain
        and h.sent_at>=now()-make_interval(days=>coalesce(p.domain_cooldown_days,14))
    ) or exists(
      select 1 from public.outreach_contacts h
      where lower(coalesce(public.pppp_outbound_domain_v1(h.contact_email,h.company_domain),''))=v_domain
        and coalesce(h.touch_3,h.touch_2,h.touch_1)>=current_date-coalesce(p.domain_cooldown_days,14)
    )
  ) then
    return jsonb_build_object('ok',false,'reason','ted_domain_cooldown_active');
  end if;

  return jsonb_build_object('ok',true,'reason','ted_history_clear');
end;
$$;


ALTER FUNCTION public.pppp_ted_outreach_history_guard_v1(p_queue_id uuid) OWNER TO postgres;

--
-- Name: pppp_ted_outreach_readiness_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_ted_outreach_readiness_v1(p_queue_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  q public.pppp_outbound_queue_v1%rowtype;
  r public.pppp_opportunity_outreach_registry_v1%rowtype;
  a public.pppp_opportunity_actions%rowtype;
  t public.kek_tender_watch%rowtype;
  ready jsonb;
  winner_type text;
  angle text;
  recipient_domain text;
  verified_domain text;
  local_part text;
  self_risk text;
  contact_quality text;
begin
  select * into q from public.pppp_outbound_queue_v1 where id=p_queue_id;
  if not found then return jsonb_build_object('ok',false,'reason','queue_row_missing'); end if;
  if q.source <> 'TED' then return jsonb_build_object('ok',false,'reason','not_ted'); end if;
  if q.source_record_id is null then return jsonb_build_object('ok',false,'reason','ted_registry_identity_missing'); end if;

  select * into r from public.pppp_opportunity_outreach_registry_v1 where id=q.source_record_id;
  if not found then return jsonb_build_object('ok',false,'reason','ted_registry_missing'); end if;

  select * into a from public.pppp_opportunity_actions where id=r.action_id;
  if not found then return jsonb_build_object('ok',false,'reason','ted_action_missing'); end if;

  select * into t from public.kek_tender_watch where id=coalesce(r.tender_watch_id,a.tender_watch_id,q.tender_watch_id);
  if not found then return jsonb_build_object('ok',false,'reason','ted_tender_missing'); end if;

  winner_type:=lower(coalesce(nullif(t.payload #>> '{winner,company_type}',''),nullif(t.payload #>> '{winner,company_classification,company_type}',''),''));
  angle:=lower(coalesce(nullif(t.payload->>'cooperation_angle',''),''));

  if winner_type='' or winner_type='unknown' then return jsonb_build_object('ok',false,'reason','ted_winner_role_unverified','winner_company_type',winner_type); end if;
  if angle in ('verify_company_role','verify_supply_or_fabrication_role') then return jsonb_build_object('ok',false,'reason','ted_cooperation_role_requires_verification','cooperation_angle',angle); end if;

  ready:=coalesce(r.payload->'outreach_readiness_v1',a.payload->'outreach_readiness_v1',t.payload->'outreach_readiness_v1');
  if ready is null or jsonb_typeof(ready)<>'object' then return jsonb_build_object('ok',false,'reason','ted_readiness_evidence_missing'); end if;

  if coalesce((ready->>'winner_role_verified')::boolean,false) is not true then return jsonb_build_object('ok',false,'reason','ted_winner_role_not_verified'); end if;
  if coalesce((ready->>'exact_lot_match')::boolean,false) is not true then return jsonb_build_object('ok',false,'reason','ted_exact_lot_not_verified'); end if;
  if coalesce((ready->>'pristeel_scope_fit')::boolean,false) is not true or nullif(trim(coalesce(ready->>'pristeel_scope','')),'') is null then return jsonb_build_object('ok',false,'reason','ted_pristeel_scope_not_concrete'); end if;
  if nullif(trim(coalesce(ready->>'scope_evidence','')),'') is null then return jsonb_build_object('ok',false,'reason','ted_scope_evidence_missing'); end if;
  if coalesce((ready->>'contact_identity_verified')::boolean,false) is not true then return jsonb_build_object('ok',false,'reason','ted_contact_identity_not_verified'); end if;
  if nullif(trim(coalesce(ready->>'buyer_function','')),'') is null then return jsonb_build_object('ok',false,'reason','ted_buyer_function_missing'); end if;
  if nullif(trim(coalesce(ready->>'concrete_question','')),'') is null then return jsonb_build_object('ok',false,'reason','ted_concrete_question_missing'); end if;
  if coalesce((ready->>'timing_fit')::boolean,false) is not true then return jsonb_build_object('ok',false,'reason','ted_timing_not_fit'); end if;
  if coalesce((ready->>'previous_contact_guard')::boolean,false) is not true then return jsonb_build_object('ok',false,'reason','ted_previous_contact_guard_missing'); end if;
  if coalesce((ready->>'bounce_suppression_guard')::boolean,false) is not true then return jsonb_build_object('ok',false,'reason','ted_bounce_guard_missing'); end if;

  self_risk:=lower(coalesce(ready->>'self_perform_risk','unknown'));
  if self_risk='high' and coalesce((ready->>'outsourcing_evidence')::boolean,false) is not true then return jsonb_build_object('ok',false,'reason','ted_self_perform_risk_high'); end if;
  if coalesce((ready->>'qualification_required')::boolean,false) and coalesce((ready->>'qualification_fit')::boolean,false) is not true then return jsonb_build_object('ok',false,'reason','ted_qualification_not_verified'); end if;

  recipient_domain:=lower(split_part(coalesce(q.recipient_email,''),'@',2));
  verified_domain:=lower(regexp_replace(coalesce(ready->>'verified_company_domain',''),'^www\.','','i'));
  if verified_domain='' then return jsonb_build_object('ok',false,'reason','ted_verified_company_domain_missing'); end if;
  if recipient_domain<>verified_domain and recipient_domain not like '%.'||verified_domain and verified_domain not like '%.'||recipient_domain then
    return jsonb_build_object('ok',false,'reason','ted_contact_domain_company_mismatch','recipient_domain',recipient_domain,'verified_company_domain',verified_domain);
  end if;

  local_part:=lower(split_part(coalesce(q.recipient_email,''),'@',1));
  contact_quality:=lower(coalesce(ready->>'contact_quality',''));
  if local_part in ('info','office','contact','kontakt','mail','hello','post','service','sales') and contact_quality<>'generic_fallback_reviewed' then
    return jsonb_build_object('ok',false,'reason','ted_generic_contact_not_reviewed');
  end if;

  return jsonb_build_object(
    'ok',true,'reason','ted_manual_readiness_verified',
    'winner_company_type',winner_type,'cooperation_angle',angle,
    'pristeel_scope',ready->>'pristeel_scope','scope_evidence',ready->>'scope_evidence',
    'buyer_function',ready->>'buyer_function','contact_quality',contact_quality,
    'verified_company_domain',verified_domain,'self_perform_risk',self_risk,'readiness',ready
  );
end;
$$;


ALTER FUNCTION public.pppp_ted_outreach_readiness_v1(p_queue_id uuid) OWNER TO postgres;

--
-- Name: pppp_ted_watch_task_guard_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_ted_watch_task_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_is_ted_watch boolean := false;
begin
  if coalesce(new.source,'') <> 'tender_deadline_auto' or coalesce(new.source_ref,'') = '' then return new; end if;

  select exists(
    select 1 from public.kek_tender_watch k
    where k.source_key = new.source_ref
      and upper(coalesce(k.payload->>'source',''))='TED'
      and lower(coalesce(k.payload->>'notice_phase','opportunity'))='opportunity'
  ) into v_is_ted_watch;

  if not v_is_ted_watch then return new; end if;

  if tg_op='INSERT' then return null; end if;
  new.status := 'mbyllur';
  new.done_at := coalesce(new.done_at,now());
  if position('PPPP: TED Watch' in coalesce(new.detail,''))=0 then
    new.detail := concat_ws(E'\n',nullif(new.detail,''),'PPPP: TED Watch — ky tender nuk kërkon ofertim direkt nga PRISTEEL; kontrolli i award-it bëhet automatikisht pas afatit.');
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_ted_watch_task_guard_v1() OWNER TO postgres;

--
-- Name: pppp_tender_archive_count_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_tender_archive_count_v1(p_payload jsonb) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select case
    when jsonb_typeof(p_payload -> 'protected_archive') = 'array'
      then jsonb_array_length(p_payload -> 'protected_archive')
    when jsonb_typeof(p_payload #> '{protected_archive,documents}') = 'array'
      then jsonb_array_length(p_payload #> '{protected_archive,documents}')
    else 0
  end;
$$;


