--
-- Name: pppp_tender_fetch_queue_action_reconcile_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_tender_fetch_queue_action_reconcile_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  update public.pppp_opportunity_actions
  set
    status = case
      when new.status = 'analyzed' then 'resolved'
      when new.status = 'failed' then 'review'
      else status
    end,
    priority = case when new.status = 'failed' then 'larte' else priority end,
    payload = coalesce(payload,'{}'::jsonb) || jsonb_build_object(
      'fetch_queue_status', new.status,
      'fetch_queue_updated_at', new.updated_at,
      'fetch_attempt_count', new.attempt_count,
      'fetch_last_error', new.last_error
    ),
    updated_at = now()
  where tender_watch_id = new.tender_watch_id
    and action_type = 'krpp_authenticated_fetch_required'
    and status not in ('closed','done');

  if new.status = 'analyzed' then
    update public.tasks
    set status='mbyllur', done_at=coalesce(done_at,now())
    where source='opportunity_engine_v2'
      and source_ref='OPPORTUNITY:'||new.tender_watch_id::text||':krpp_authenticated_fetch_required'
      and status not in ('mbyllur','kryer','arkivuar');
  elsif new.status = 'failed' then
    update public.tasks
    set status='hapur', done_at=null, priority='larte',
        detail=coalesce(detail,'')||E'\n\nKRPP authenticated fetch failed after retries: '||coalesce(new.last_error,'unknown error')
    where source='opportunity_engine_v2'
      and source_ref='OPPORTUNITY:'||new.tender_watch_id::text||':krpp_authenticated_fetch_required';
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.pppp_tender_fetch_queue_action_reconcile_v1() OWNER TO postgres;

--
-- Name: pppp_tender_fetch_queue_no_canonical_reopen_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_tender_fetch_queue_no_canonical_reopen_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_payload jsonb;
  v_ready boolean := false;
begin
  select coalesce(payload, '{}'::jsonb)
  into v_payload
  from public.kek_tender_watch
  where id = new.tender_watch_id;

  v_ready := public.pppp_tender_canonical_protected_ready_v1(coalesce(v_payload, '{}'::jsonb));

  if v_ready
     and (
       coalesce(new.auth_required, false)
       or new.status in ('queued', 'retry', 'processing')
     )
     and coalesce(new.payload ->> 'force_authenticated_refetch', 'false') <> 'true' then
    new.status := case
      when old.status in ('analyzed', 'ready') then old.status
      else 'analyzed'
    end;
    new.auth_required := false;
    new.last_error := null;
    new.payload := coalesce(new.payload, '{}'::jsonb) || jsonb_build_object(
      'canonical_archive_guard', 'preserved',
      'canonical_archive_guard_at', now()
    );
  end if;

  return new;
end;
$$;


