COMMENT ON FUNCTION public.pppp_tender_fetch_queue_no_canonical_reopen_v1() IS 'PPPP P0 guard: prevents KRPP auth queue from reopening after a complete canonical authenticated archive exists.';


--
-- Name: pppp_tender_partnership_expansion_sync_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_tender_partnership_expansion_sync_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  v_required boolean := coalesce(new.payload->>'partnership_expansion_required','false') = 'true';
  v_phase text := lower(coalesce(new.payload->>'notice_phase','opportunity'));
  v_source text := upper(coalesce(new.payload->>'source','KRPP'));
  v_official_source text;
  v_status text;
  v_currency text;
  v_identity text := coalesce(nullif(btrim(new.procurement_no),''), nullif(btrim(new.publication_no),''), new.source_key);
  v_canonical_key text;
begin
  v_canonical_key := 'tenderproc:' || v_identity;

  if not v_required or coalesce(new.status,'new') = 'ignored' then
    update public.pppp_representation_opportunities_v1
    set status='closed',
        fact_evidence = fact_evidence || jsonb_build_object(
          'current_partnership_expansion_required',false,
          'last_screened_at',now()
        ),
        updated_at=now()
    where (
        source_key=v_canonical_key
        or source_key='tender:' || new.source_key
      )
      and fact_evidence->>'origin'='mundesite'
      and status in ('pipeline','waiting_procurement','procurement','tender_open','partner_search_ready');
    return new;
  end if;

  update public.pppp_representation_opportunities_v1
  set status='closed',
      fact_evidence = fact_evidence || jsonb_build_object(
        'superseded_by',v_canonical_key,
        'identity_basis',case when nullif(btrim(new.procurement_no),'') is not null then 'procurement_no'
                              when nullif(btrim(new.publication_no),'') is not null then 'publication_no'
                              else 'source_key' end,
        'last_screened_at',now()
      ),
      updated_at=now()
  where source_key='tender:' || new.source_key
    and source_key<>v_canonical_key
    and fact_evidence->>'origin'='mundesite';

  v_official_source := case
    when coalesce(new.detail_url,'') ~* '^https?://' then new.detail_url
    when coalesce(new.source_url,'') ~* '^https?://' then new.source_url
    else null
  end;

  v_status := case
    when v_phase = 'award' then 'partner_search_ready'
    when v_phase = 'opportunity' then 'tender_open'
    when v_phase = 'pipeline' then 'pipeline'
    else 'pipeline'
  end;

  v_currency := case
    when upper(coalesce(new.currency,'')) ~ '^[A-Z]{3}$' then upper(new.currency)
    else null
  end;

  insert into public.pppp_representation_opportunities_v1(
    source_key,project_name,funding_institution,tender_reference,official_source,
    total_project_value,currency,status,procurement_stage,tender_deadline,scope,
    verification_status,fact_evidence,last_verified_at,notes
  )
  values (
    v_canonical_key,
    left(coalesce(nullif(btrim(new.title),''),new.source_key),500),
    coalesce(nullif(new.payload->>'funding_institution',''), nullif(new.payload->>'financier',''), v_source),
    v_identity,
    v_official_source,new.estimated_value,v_currency,v_status,v_phase,
    case when new.deadline is null then null else new.deadline::timestamp at time zone 'Europe/Belgrade' end,
    coalesce(nullif(new.payload->>'short_description',''),nullif(new.payload->>'description',''),nullif(new.fpp_description,''),new.title),
    'review',
    jsonb_build_object(
      'origin','mundesite',
      'tender_watch_id',new.id,
      'tender_source',v_source,
      'tender_status',new.status,
      'canonical_tender_identity',v_identity,
      'identity_basis',case when nullif(btrim(new.procurement_no),'') is not null then 'procurement_no'
                            when nullif(btrim(new.publication_no),'') is not null then 'publication_no'
                            else 'source_key' end,
      'latest_notice_source_key',new.source_key,
      'candidate_business_routes',new.payload->'candidate_business_routes',
      'partnership_routes',new.payload->'partnership_routes',
      'partnership_expansion_market',new.payload->>'partnership_expansion_market',
      'pristeel_relevance_gate',new.payload->>'pristeel_relevance_gate',
      'current_partnership_expansion_required',true,
      'target_creation_requires_human_approval',true,
      'auto_target_creation',false,
      'multi_route_policy',new.payload->>'multi_route_policy'
    ),
    now(),
    'Canonical procurement-level handoff from Mundësitë for partnership/JV/consortium/representation screening. No company/target/partner/outbound is created automatically.'
  )
  on conflict (source_key) do update
  set project_name = excluded.project_name,
      funding_institution = coalesce(excluded.funding_institution, public.pppp_representation_opportunities_v1.funding_institution),
      tender_reference = excluded.tender_reference,
      official_source = coalesce(excluded.official_source, public.pppp_representation_opportunities_v1.official_source),
      total_project_value = coalesce(excluded.total_project_value, public.pppp_representation_opportunities_v1.total_project_value),
      currency = coalesce(excluded.currency, public.pppp_representation_opportunities_v1.currency),
      status = case
        when public.pppp_representation_opportunities_v1.status in ('pipeline','waiting_procurement','procurement','tender_open','closed')
          then excluded.status
        else public.pppp_representation_opportunities_v1.status
      end,
      procurement_stage = excluded.procurement_stage,
      tender_deadline = coalesce(excluded.tender_deadline, public.pppp_representation_opportunities_v1.tender_deadline),
      scope = coalesce(excluded.scope, public.pppp_representation_opportunities_v1.scope),
      fact_evidence = public.pppp_representation_opportunities_v1.fact_evidence || excluded.fact_evidence,
      last_verified_at = now(),
      updated_at = now();

  return new;
end;
$_$;


