COMMENT ON FUNCTION public.pppp_tender_partnership_expansion_sync_v1() IS 'Legacy automatic Mundesite-to-Representations handoff. Trigger disabled 2026-09-27 to keep modules operationally separate; retained only for audit/history.';


--
-- Name: pppp_tender_preserve_canonical_dossier_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_tender_preserve_canonical_dossier_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_old_ready boolean := public.pppp_tender_canonical_protected_ready_v1(coalesce(old.payload, '{}'::jsonb));
  v_new_ready boolean := public.pppp_tender_canonical_protected_ready_v1(coalesce(new.payload, '{}'::jsonb));
  v_force_cleanup boolean := coalesce(new.payload #>> '{dossier_integrity,force_archive_cleanup}', 'false') = 'true';
  v_integrity jsonb;
begin
  new.payload := coalesce(new.payload, '{}'::jsonb);

  -- This escape hatch is intentionally explicit and self-clearing. It exists only
  -- for verified contamination cleanup; ordinary public refreshes never set it.
  if v_force_cleanup then
    v_integrity := case
      when jsonb_typeof(new.payload -> 'dossier_integrity') = 'object' then new.payload -> 'dossier_integrity'
      else '{}'::jsonb
    end;
    v_integrity := v_integrity - 'force_archive_cleanup';
    new.payload := jsonb_set(new.payload, '{dossier_integrity}', v_integrity, true);
  end if;

  if v_old_ready and not v_new_ready and not v_force_cleanup then
    new.payload := new.payload || jsonb_build_object(
      'dossier_analysis', old.payload -> 'dossier_analysis',
      'dossier_analysis_version', old.payload -> 'dossier_analysis_version',
      'dossier_analyzed_at', old.payload -> 'dossier_analyzed_at',
      'dossier_documents', old.payload -> 'dossier_documents',
      'dossier_analysis_status', 'ready',
      'protected_archive_analyzed_at', old.payload -> 'protected_archive_analyzed_at',
      'protected_archive_analysis_version', old.payload -> 'protected_archive_analysis_version'
    );

    if jsonb_typeof(old.payload -> 'dossier_integrity') = 'object' then
      new.payload := jsonb_set(
        new.payload,
        '{dossier_integrity}',
        case when jsonb_typeof(new.payload -> 'dossier_integrity') = 'object' then new.payload -> 'dossier_integrity' else '{}'::jsonb end
        || old.payload -> 'dossier_integrity'
        || jsonb_build_object(
          'canonical_rank', 100,
          'canonical_archive_present', true,
          'downgrade_prevented_at', now()
        ),
        true
      );
    else
      new.payload := jsonb_set(
        new.payload,
        '{dossier_integrity}',
        case when jsonb_typeof(new.payload -> 'dossier_integrity') = 'object' then new.payload -> 'dossier_integrity' else '{}'::jsonb end
        || jsonb_build_object(
          'version', 'v2',
          'canonical_rank', 100,
          'canonical_archive_present', true,
          'downgrade_prevented_at', now()
        ),
        true
      );
    end if;
  end if;

  -- Never silently drop an authenticated archive during an unrelated public refresh.
  -- A proven-contamination cleanup must opt in through the self-clearing flag above.
  if not v_force_cleanup
     and public.pppp_tender_archive_count_v1(coalesce(old.payload, '{}'::jsonb)) > 0
     and public.pppp_tender_archive_count_v1(coalesce(new.payload, '{}'::jsonb)) = 0 then
    new.payload := jsonb_set(new.payload, '{protected_archive}', old.payload -> 'protected_archive', true);
    if old.payload ? 'protected_archive_updated_at' then
      new.payload := new.payload || jsonb_build_object('protected_archive_updated_at', old.payload -> 'protected_archive_updated_at');
    end if;
    if old.payload ? 'protected_archive_import_version' then
      new.payload := new.payload || jsonb_build_object('protected_archive_import_version', old.payload -> 'protected_archive_import_version');
    end if;
    if old.payload ? 'protected_archive_imported_at' then
      new.payload := new.payload || jsonb_build_object('protected_archive_imported_at', old.payload -> 'protected_archive_imported_at');
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_tender_preserve_canonical_dossier_v1() OWNER TO postgres;

--
-- Name: FUNCTION pppp_tender_preserve_canonical_dossier_v1(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.pppp_tender_preserve_canonical_dossier_v1() IS 'PPPP P0 guard: prevents weaker public refreshes from overwriting canonical/manual dossier state; an explicit self-clearing force_archive_cleanup flag permits verified contamination cleanup.';


--
-- Name: pppp_tender_project_intelligence_handoff_v1(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_tender_project_intelligence_handoff_v1(p_apply boolean DEFAULT false, p_limit integer DEFAULT 250) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  r record;
  q record;
  v_limit integer:=least(1000,greatest(1,coalesce(p_limit,250)));
  v_analysis jsonb;
  v_dossier jsonb;
  v_source_ref text;
  v_snapshot_ref text;
  v_analyzed_at text;
  v_complete boolean;
  v_confidence text;
  v_req_status text;
  v_candidates integer:=0;
  v_new_snapshots integer:=0;
  v_analyses integer:=0;
  v_requirements integer:=0;
  v_deleted_old integer:=0;
  v_rows integer:=0;
begin
  select count(*) into v_candidates
  from public.kek_tender_watch t
  where t.project_id is not null
    and t.payload ? 'dossier_analysis'
    and jsonb_typeof(t.payload->'dossier_analysis')='object';

  for r in
    select t.*
    from public.kek_tender_watch t
    where t.project_id is not null
      and t.payload ? 'dossier_analysis'
      and jsonb_typeof(t.payload->'dossier_analysis')='object'
    order by t.updated_at desc nulls last
    limit v_limit
  loop
    v_dossier:=r.payload->'dossier_analysis';
    v_analysis:=coalesce(v_dossier->'analysis','{}'::jsonb);
    v_analyzed_at:=coalesce(nullif(v_dossier->>'analyzed_at',''),r.updated_at::text);
    v_source_ref:='TENDER:'||r.id::text;
    v_snapshot_ref:=v_source_ref||':'||v_analyzed_at;
    v_complete:=coalesce((v_dossier->>'dossier_complete')::boolean,false);
    v_confidence:=lower(coalesce(v_analysis->>'confidence','low'));
    v_req_status:=case when v_complete and v_confidence in ('high','medium') then 'confirmed' else 'review' end;

    if exists(
      select 1 from public.project_analyses a
      where a.project_id=r.project_id::text
        and a.engine='opportunity-tender-dossier-v1'
        and a.source_manifest->>'source_ref'=v_snapshot_ref
    ) then
      continue;
    end if;

    v_new_snapshots:=v_new_snapshots+1;
    if not p_apply then
      continue;
    end if;

    insert into public.project_analyses(
      project_id,status,engine,model,analysis,source_counts,source_manifest,created_at
    ) values (
      r.project_id::text,
      'complete',
      'opportunity-tender-dossier-v1',
      nullif(v_dossier->'provider'->>'model',''),
      jsonb_build_object(
        'tender_watch_id',r.id,
        'tender_title',r.title,
        'authority',r.authority,
        'deadline',r.deadline,
        'opportunity_route',r.payload->>'opportunity_route',
        'opportunity_gate',r.payload->>'opportunity_gate',
        'dossier_complete',v_complete,
        'dossier_analysis',v_dossier
      ),
      jsonb_build_object(
        'documents',case when jsonb_typeof(v_dossier->'documents')='array' then jsonb_array_length(v_dossier->'documents') else 0 end,
        'files_analyzed',case when jsonb_typeof(v_dossier->'files_analyzed')='array' then jsonb_array_length(v_dossier->'files_analyzed') else 0 end,
        'protected_documents',case when jsonb_typeof(v_dossier->'protected_documents')='array' then jsonb_array_length(v_dossier->'protected_documents') else 0 end,
        'technical_requirements',case when jsonb_typeof(v_analysis->'technical_requirements')='array' then jsonb_array_length(v_analysis->'technical_requirements') else 0 end,
        'commercial_requirements',case when jsonb_typeof(v_analysis->'commercial_requirements')='array' then jsonb_array_length(v_analysis->'commercial_requirements') else 0 end
      ),
      jsonb_build_object(
        'source_type','tender_dossier',
        'source_ref',v_snapshot_ref,
        'tender_watch_id',r.id,
        'source',v_dossier->>'source',
        'source_url',v_dossier->>'source_url',
        'analyzed_at',v_analyzed_at,
        'dossier_version',v_dossier->>'version',
        'dossier_complete',v_complete,
        'opportunity_route',r.payload->>'opportunity_route',
        'opportunity_gate',r.payload->>'opportunity_gate'
      ),
      now()
    )
    on conflict do nothing;
    get diagnostics v_rows=row_count;
    v_analyses:=v_analyses+v_rows;

    delete from public.project_requirements pr
    where pr.project_id=r.project_id
      and pr.source_type='tender_dossier'
      and pr.source_ref=v_source_ref;
    get diagnostics v_rows=row_count;
    v_deleted_old:=v_deleted_old+v_rows;

    for q in
      select x.category,x.value_text
      from (
        select 'technical'::text category,value::text value_text
        from jsonb_array_elements_text(case when jsonb_typeof(v_analysis->'technical_requirements')='array' then v_analysis->'technical_requirements' else '[]'::jsonb end) value
        union all
        select 'commercial',value::text
        from jsonb_array_elements_text(case when jsonb_typeof(v_analysis->'commercial_requirements')='array' then v_analysis->'commercial_requirements' else '[]'::jsonb end) value
        union all
        select 'submission',value::text
        from jsonb_array_elements_text(case when jsonb_typeof(v_analysis->'submission_requirements')='array' then v_analysis->'submission_requirements' else '[]'::jsonb end) value
        union all
        select 'deadline',value::text
        from jsonb_array_elements_text(case when jsonb_typeof(v_analysis->'deadlines')='array' then v_analysis->'deadlines' else '[]'::jsonb end) value
        union all
        select 'risk',value::text
        from jsonb_array_elements_text(case when jsonb_typeof(v_analysis->'risks')='array' then v_analysis->'risks' else '[]'::jsonb end) value
        union all
        select 'missing',value::text
        from jsonb_array_elements_text(case when jsonb_typeof(v_analysis->'missing_information')='array' then v_analysis->'missing_information' else '[]'::jsonb end) value
        union all
        select 'quantity_spec',value::text
        from jsonb_array_elements_text(case when jsonb_typeof(v_analysis->'known_quantities_specs')='array' then v_analysis->'known_quantities_specs' else '[]'::jsonb end) value
        union all
        select 'steel_scope',value::text
        from jsonb_array_elements_text(case when jsonb_typeof(v_analysis->'steel_scope')='array' then v_analysis->'steel_scope' else '[]'::jsonb end) value
        union all
        select 'reference','Protected dossier document: '||value::text
        from jsonb_array_elements_text(case when jsonb_typeof(v_dossier->'protected_documents')='array' then v_dossier->'protected_documents' else '[]'::jsonb end) value
      ) x
      where char_length(btrim(x.value_text)) between 3 and 1200
    loop
      insert into public.project_requirements(
        project_id,category,requirement_key,value_text,value_json,
        source_type,source_ref,source_name,trust_tier,status,first_seen,last_seen,metadata
      ) values (
        r.project_id,
        q.category,
        'tender:'||q.category||':'||md5(lower(btrim(q.value_text))),
        btrim(q.value_text),
        jsonb_build_object('text',btrim(q.value_text)),
        'tender_dossier',
        v_source_ref,
        r.title,
        'text',
        v_req_status,
        now(),now(),
        jsonb_build_object(
          'tender_watch_id',r.id,
          'analyzed_at',v_analyzed_at,
          'dossier_complete',v_complete,
          'confidence',v_confidence,
          'recommendation',v_analysis->>'recommendation',
          'opportunity_route',r.payload->>'opportunity_route',
          'opportunity_gate',r.payload->>'opportunity_gate',
          'snapshot_ref',v_snapshot_ref
        )
      )
      on conflict(project_id,requirement_key,source_type,source_ref) do update
        set value_text=excluded.value_text,
            value_json=excluded.value_json,
            source_name=excluded.source_name,
            trust_tier=excluded.trust_tier,
            status=excluded.status,
            last_seen=now(),
            metadata=excluded.metadata;
      v_requirements:=v_requirements+1;
    end loop;
  end loop;

  return jsonb_build_object(
    'mode',case when p_apply then 'apply' else 'preview' end,
    'candidates',v_candidates,
    'new_snapshots',v_new_snapshots,
    'analyses_materialized',v_analyses,
    'requirements_materialized',v_requirements,
    'old_requirements_replaced',v_deleted_old,
    'generated_at',now()
  );
end;
$$;


ALTER FUNCTION public.pppp_tender_project_intelligence_handoff_v1(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_tender_project_promotion_reconcile_v1(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_tender_project_promotion_reconcile_v1(p_apply boolean DEFAULT false, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  r record;
  v_project uuid;
  v_limit integer:=least(500,greatest(1,coalesce(p_limit,100)));
  v_candidates integer:=0;
  v_promoted integer:=0;
  v_linked integer:=0;
  v_skipped integer:=0;
  v_errors integer:=0;
  v_due date;
  v_reason text;
begin
  -- Keep a durable candidate record for every active direct-tender lane.
  insert into public.pppp_tender_project_promotions(tender_watch_id,operating_lane,promotion_state,eligibility_reason,last_evaluated_at,metadata,updated_at)
  select v.id,v.operating_lane,
         case when v.status='ignored' or (v.deadline is not null and v.deadline<current_date) then 'skipped' else 'candidate' end,
         case
           when v.status='ignored' then 'Tender is ignored by current business rules.'
           when v.deadline is not null and v.deadline<current_date then 'Tender deadline has passed.'
           when v.status='review' then 'Direct tender is in review and is eligible for canonical project promotion.'
           else 'Direct tender remains a candidate until it reaches review.'
         end,
         now(),
         jsonb_build_object('source_key',v.source_key,'procurement_no',v.procurement_no,'publication_no',v.publication_no,'authority',v.authority,'title',v.title,'relevance_score',v.relevance_score,'deadline',v.deadline,'status',v.status),
         now()
  from public.pppp_tender_operating_lanes_v1 v
  where v.operating_lane='direct_tender'
  on conflict(tender_watch_id) do update set
    operating_lane=excluded.operating_lane,
    promotion_state=case when public.pppp_tender_project_promotions.promotion_state in ('promoted','linked_existing') then public.pppp_tender_project_promotions.promotion_state else excluded.promotion_state end,
    eligibility_reason=excluded.eligibility_reason,
    last_evaluated_at=now(),
    metadata=excluded.metadata,
    updated_at=now();

  select count(*) into v_candidates from public.pppp_tender_project_promotions where promotion_state='candidate';
  select count(*) into v_skipped from public.pppp_tender_project_promotions where promotion_state='skipped';

  if not p_apply then
    return jsonb_build_object('mode','preview','candidates',v_candidates,'skipped',v_skipped,'promoted',0,'linked_existing',0,'errors',0,'generated_at',now());
  end if;

  -- First, deterministically link an existing project if its exact tender identity is already present.
  for r in
    select v.* from public.pppp_tender_operating_lanes_v1 v
    where v.project_id is null and v.operating_lane='direct_tender' and v.status<>'ignored'
      and (v.deadline is null or v.deadline>=current_date)
    order by case when v.status='review' then 0 else 1 end,v.relevance_score desc,v.published_date desc nulls last
    limit v_limit
  loop
    v_project:=null;
    select p.id into v_project
      from public.projects p
     where p.id is not null and (
       coalesce(nullif(btrim(p.business_ref),''),'')=coalesce(r.source_key,'')
       or lower(coalesce(nullif(btrim(p.ref),''),''))=lower(coalesce(nullif(btrim(r.procurement_no),''),''))
       or lower(coalesce(nullif(btrim(p.ref),''),''))=lower(coalesce(nullif(btrim(r.publication_no),''),''))
       or coalesce(r.source_key,'')=any(coalesce(p.identity_aliases,'{}'::text[]))
       or coalesce(r.procurement_no,'')=any(coalesce(p.identity_aliases,'{}'::text[]))
       or coalesce(r.publication_no,'')=any(coalesce(p.identity_aliases,'{}'::text[]))
     )
     order by p.created_at desc nulls last
     limit 1;
    if v_project is not null then
      update public.kek_tender_watch set project_id=v_project,updated_at=now() where id=r.id and project_id is null;
      update public.pppp_tender_project_promotions set promotion_state='linked_existing',project_id=v_project,promoted_at=coalesce(promoted_at,now()),eligibility_reason='Exact tender identity matched an existing canonical project.',last_evaluated_at=now(),updated_at=now() where tender_watch_id=r.id;
      v_linked:=v_linked+1;
      continue;
    end if;

    -- Creation is intentionally gated by the existing business state `review`.
    if r.status<>'review' then continue; end if;

    begin
      insert into public.projects(name,client,ref,deadline,notes,status,pipeline_stage,business_ref,identity_aliases,updated_at,last_activity_at,origin_type)
      values(
        r.title,
        r.authority,
        r.procurement_no,
        case when r.deadline is null then null else r.deadline::text end,
        'Auto-promoted from PPPP tender review. Source: '||r.source_key||E'\nPublication: '||coalesce(r.publication_no,'—')||E'\nRelevance score: '||coalesce(r.relevance_score,0)::text||E'\nNo outbound communication was sent by this promotion.',
        'pritje',
        'technical_review',
        r.source_key,
        array_remove(array[r.source_key,r.procurement_no,r.publication_no]::text[],null),
        now(),now(),'tender'
      ) returning id into v_project;

      update public.kek_tender_watch set project_id=v_project,updated_at=now() where id=r.id;
      v_due:=greatest(current_date,coalesce(r.deadline-7,current_date));
      insert into public.tasks(project_id,title,detail,due_date,priority,status,source,category,source_ref)
      values(v_project,'Tender review · '||left(r.title,160),'Canonical project created from a direct tender already in review. Confirm participation strategy, dossier completeness, partner/subcontracting angle and next action before deadline '||coalesce(r.deadline::text,'—')||'.',v_due,'larte','hapur','tender_project_promotion','intern','TENDER:'||r.id::text)
      on conflict(source,source_ref) do update set project_id=excluded.project_id,title=excluded.title,detail=excluded.detail,due_date=excluded.due_date,priority='larte',status='hapur',done_at=null;
      update public.pppp_tender_project_promotions set promotion_state='promoted',project_id=v_project,promoted_at=now(),eligibility_reason='Direct tender was already in review; canonical project created automatically.',last_evaluated_at=now(),updated_at=now() where tender_watch_id=r.id;
      v_promoted:=v_promoted+1;
    exception when others then
      v_reason:=left(sqlerrm,1000);
      update public.pppp_tender_project_promotions set promotion_state='error',eligibility_reason=v_reason,last_evaluated_at=now(),updated_at=now() where tender_watch_id=r.id;
      insert into public.tasks(title,detail,due_date,priority,status,source,category,source_ref)
      values('Tender promotion failure · '||left(r.title,140),'PPPP could not promote tender '||r.source_key||' to a canonical project. '||v_reason,current_date,'larte','hapur','automation_failure','intern','AUTOMATION:tender-promotion:'||r.id::text)
      on conflict(source,source_ref) do update set title=excluded.title,detail=excluded.detail,due_date=current_date,priority='larte',status='hapur',done_at=null;
      v_errors:=v_errors+1;
    end;
  end loop;

  select count(*) into v_candidates from public.pppp_tender_project_promotions where promotion_state='candidate';
  select count(*) into v_skipped from public.pppp_tender_project_promotions where promotion_state='skipped';
  return jsonb_build_object('mode','apply','candidates',v_candidates,'skipped',v_skipped,'promoted',v_promoted,'linked_existing',v_linked,'errors',v_errors,'generated_at',now());
end;$$;


ALTER FUNCTION public.pppp_tender_project_promotion_reconcile_v1(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_tender_project_promotion_reconcile_v2(boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_tender_project_promotion_reconcile_v2(p_apply boolean DEFAULT false, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  r record;
  v_project uuid;
  v_limit integer := least(500,greatest(1,coalesce(p_limit,100)));
  v_candidates integer := 0;
  v_promoted integer := 0;
  v_linked integer := 0;
  v_skipped integer := 0;
  v_blocked integer := 0;
  v_errors integer := 0;
  v_due date;
  v_reason text;
begin
  insert into public.pppp_tender_project_promotions(
    tender_watch_id,operating_lane,promotion_state,eligibility_reason,last_evaluated_at,metadata,updated_at
  )
  select
    v.id,
    v.operating_lane,
    case
      when v.status='ignored' or (v.deadline is not null and v.deadline<current_date) then 'skipped'
      when coalesce(v.payload->>'opportunity_gate','unassessed')='qualified' then 'candidate'
      else 'candidate'
    end,
    case
      when v.status='ignored' then 'Tender is ignored by current business rules.'
      when v.deadline is not null and v.deadline<current_date then 'Tender deadline has passed.'
      when coalesce(v.payload->>'opportunity_gate','unassessed')='qualified' then 'Dossier and Opportunity Engine gate are qualified for project promotion.'
      else 'Waiting for Opportunity Engine dossier/qualification gate.'
    end,
    now(),
    jsonb_build_object(
      'source_key',v.source_key,
      'procurement_no',v.procurement_no,
      'publication_no',v.publication_no,
      'authority',v.authority,
      'title',v.title,
      'relevance_score',v.relevance_score,
      'deadline',v.deadline,
      'status',v.status,
      'opportunity_route',v.payload->>'opportunity_route',
      'opportunity_gate',v.payload->>'opportunity_gate'
    ),
    now()
  from public.pppp_tender_operating_lanes_v1 v
  where v.operating_lane='direct_tender'
  on conflict(tender_watch_id) do update set
    operating_lane=excluded.operating_lane,
    promotion_state=case
      when public.pppp_tender_project_promotions.promotion_state in ('promoted','linked_existing')
        then public.pppp_tender_project_promotions.promotion_state
      else excluded.promotion_state
    end,
    eligibility_reason=excluded.eligibility_reason,
    last_evaluated_at=now(),
    metadata=excluded.metadata,
    updated_at=now();

  if not p_apply then
    select count(*) into v_candidates from public.pppp_tender_project_promotions where promotion_state='candidate';
    select count(*) into v_skipped from public.pppp_tender_project_promotions where promotion_state='skipped';
    return jsonb_build_object('mode','preview','candidates',v_candidates,'skipped',v_skipped,'promoted',0,'linked_existing',0,'blocked',0,'errors',0,'generated_at',now());
  end if;

  for r in
    select v.*
    from public.pppp_tender_operating_lanes_v1 v
    where v.project_id is null
      and v.operating_lane='direct_tender'
      and v.status<>'ignored'
      and (v.deadline is null or v.deadline>=current_date)
    order by
      case when coalesce(v.payload->>'opportunity_gate','')='qualified' then 0 else 1 end,
      v.relevance_score desc,
      v.published_date desc nulls last
    limit v_limit
  loop
    v_project := null;

    select p.id into v_project
    from public.projects p
    where p.id is not null and (
      coalesce(nullif(btrim(p.business_ref),''),'')=coalesce(r.source_key,'')
      or lower(coalesce(nullif(btrim(p.ref),''),''))=lower(coalesce(nullif(btrim(r.procurement_no),''),''))
      or lower(coalesce(nullif(btrim(p.ref),''),''))=lower(coalesce(nullif(btrim(r.publication_no),''),''))
      or coalesce(r.source_key,'')=any(coalesce(p.identity_aliases,'{}'::text[]))
      or coalesce(r.procurement_no,'')=any(coalesce(p.identity_aliases,'{}'::text[]))
      or coalesce(r.publication_no,'')=any(coalesce(p.identity_aliases,'{}'::text[]))
    )
    order by p.created_at desc nulls last
    limit 1;

    if v_project is not null then
      update public.kek_tender_watch set project_id=v_project,updated_at=now() where id=r.id and project_id is null;
      update public.pppp_tender_project_promotions
      set promotion_state='linked_existing',project_id=v_project,promoted_at=coalesce(promoted_at,now()),
          eligibility_reason='Exact tender identity matched an existing canonical project.',last_evaluated_at=now(),updated_at=now()
      where tender_watch_id=r.id;
      update public.pppp_opportunity_actions set project_id=v_project,updated_at=now() where tender_watch_id=r.id and project_id is null;
      v_linked := v_linked + 1;
      continue;
    end if;

    if r.status<>'review' or coalesce(r.payload->>'opportunity_gate','unassessed')<>'qualified' then
      v_blocked := v_blocked + 1;
      continue;
    end if;

    begin
      insert into public.projects(
        name,client,ref,deadline,notes,status,pipeline_stage,business_ref,identity_aliases,updated_at,last_activity_at,origin_type
      ) values (
        r.title,
        r.authority,
        r.procurement_no,
        case when r.deadline is null then null else r.deadline::text end,
        'Auto-promoted by PPPP Opportunity Engine v2 after dossier qualification. Source: '||r.source_key||E'\nPublication: '||coalesce(r.publication_no,'—')||E'\nRoute: '||coalesce(r.payload->>'opportunity_route','—')||E'\nRelevance score: '||coalesce(r.relevance_score,0)::text||E'\nNo outbound communication was sent by this promotion.',
        'pritje',
        'technical_review',
        r.source_key,
        array_remove(array[r.source_key,r.procurement_no,r.publication_no]::text[],null),
        now(),now(),'tender'
      ) returning id into v_project;

      update public.kek_tender_watch set project_id=v_project,updated_at=now() where id=r.id;
      update public.pppp_opportunity_actions set project_id=v_project,updated_at=now() where tender_watch_id=r.id and project_id is null;
      v_due := greatest(current_date,coalesce(r.deadline-7,current_date));
      insert into public.tasks(project_id,title,detail,due_date,priority,status,source,category,source_ref)
      values(
        v_project,
        'Opportunity qualified · '||left(r.title,150),
        'PPPP created this canonical project only after Opportunity Engine qualification. Confirm participation strategy, final commercial decision, supplier/partner commitments and submission plan before deadline '||coalesce(r.deadline::text,'—')||'.',
        v_due,'larte','hapur','tender_project_promotion','intern','TENDER:'||r.id::text
      )
      on conflict(source,source_ref) do update set
        project_id=excluded.project_id,title=excluded.title,detail=excluded.detail,due_date=excluded.due_date,
        priority='larte',status='hapur',done_at=null;

      update public.pppp_tender_project_promotions
      set promotion_state='promoted',project_id=v_project,promoted_at=now(),
          eligibility_reason='Opportunity Engine dossier/qualification gate passed; canonical project created.',
          last_evaluated_at=now(),updated_at=now()
      where tender_watch_id=r.id;
      v_promoted := v_promoted + 1;
    exception when others then
      v_reason := left(sqlerrm,1000);
      update public.pppp_tender_project_promotions
      set promotion_state='error',eligibility_reason=v_reason,last_evaluated_at=now(),updated_at=now()
      where tender_watch_id=r.id;
      insert into public.tasks(title,detail,due_date,priority,status,source,category,source_ref)
      values(
        'Tender promotion failure · '||left(r.title,140),
        'PPPP Opportunity Engine could not promote tender '||r.source_key||' to a canonical project. '||v_reason,
        current_date,'larte','hapur','automation_failure','intern','AUTOMATION:tender-promotion:'||r.id::text
      )
      on conflict(source,source_ref) do update set
        title=excluded.title,detail=excluded.detail,due_date=current_date,priority='larte',status='hapur',done_at=null;
      v_errors := v_errors + 1;
    end;
  end loop;

  select count(*) into v_candidates from public.pppp_tender_project_promotions where promotion_state='candidate';
  select count(*) into v_skipped from public.pppp_tender_project_promotions where promotion_state='skipped';
  return jsonb_build_object('mode','apply','candidates',v_candidates,'skipped',v_skipped,'promoted',v_promoted,'linked_existing',v_linked,'blocked',v_blocked,'errors',v_errors,'generated_at',now());
end;
$$;


ALTER FUNCTION public.pppp_tender_project_promotion_reconcile_v2(p_apply boolean, p_limit integer) OWNER TO postgres;

--
-- Name: pppp_tender_saved_archive_complete_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_tender_saved_archive_complete_v1(p_payload jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when coalesce((p_payload->'dossier_integrity'->>'storage_files_available')::boolean, true) = false
      or coalesce((p_payload->'dossier_integrity'->>'storage_missing')::boolean, false) = true
      then false
    when jsonb_typeof(coalesce(p_payload,'{}'::jsonb)->'protected_archive') <> 'array'
      or jsonb_array_length(coalesce(p_payload,'{}'::jsonb)->'protected_archive') = 0
      then false
    when coalesce((p_payload->'dossier_integrity'->>'manual_full_zip_uploaded')::boolean, false) = true
      and coalesce((p_payload->'dossier_integrity'->>'storage_files_available')::boolean, false) = true
      and exists (
        select 1
        from jsonb_array_elements(coalesce(p_payload,'{}'::jsonb)->'protected_archive') as a(doc)
        where coalesce(a.doc->>'identity_status','legacy') <> 'mismatch'
          and coalesce(a.doc->>'storage_status','available') = 'available'
      )
      then true
    when jsonb_typeof(coalesce(p_payload,'{}'::jsonb)->'dossier_integrity'->'remaining_expected') = 'array'
      and jsonb_array_length(coalesce(p_payload,'{}'::jsonb)->'dossier_integrity'->'remaining_expected') = 0
      then true
    when jsonb_typeof(coalesce(p_payload,'{}'::jsonb)->'dossier_analysis'->'protected_documents') = 'array'
      and jsonb_array_length(coalesce(p_payload,'{}'::jsonb)->'dossier_analysis'->'protected_documents') > 0
      and not exists (
        select 1
        from jsonb_array_elements_text(coalesce(p_payload,'{}'::jsonb)->'dossier_analysis'->'protected_documents') as exp(name)
        where not exists (
          select 1
          from jsonb_array_elements(coalesce(p_payload,'{}'::jsonb)->'protected_archive') as a(doc)
          where coalesce(a.doc->>'identity_status','legacy') <> 'mismatch'
            and coalesce(a.doc->>'storage_status','available') <> 'missing_blob'
            and lower(regexp_replace(trim(coalesce(a.doc->>'expected_name',a.doc->>'name','')), '\s+', ' ', 'g'))
              = lower(regexp_replace(trim(exp.name), '\s+', ' ', 'g'))
        )
      )
      then true
    else false
  end
$$;


ALTER FUNCTION public.pppp_tender_saved_archive_complete_v1(p_payload jsonb) OWNER TO postgres;

--
-- Name: pppp_touch_project_from_analysis(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_touch_project_from_analysis() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
declare v_project uuid;
begin
  if new.project_id is null or new.project_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then return new; end if;
  v_project := new.project_id::uuid;
  update public.projects
     set last_activity_at = greatest(coalesce(last_activity_at, created_at, '-infinity'::timestamptz), coalesce(new.created_at, now()))
   where id = v_project;
  return new;
end;
$_$;


