     set last_email_at = greatest(coalesce(last_email_at, '-infinity'::timestamptz), v_ts),
         last_activity_at = greatest(coalesce(last_activity_at, created_at, '-infinity'::timestamptz), v_ts)
   where id = new.project_id;
