--
-- Name: pppp_wait_state_automated_task_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_wait_state_automated_task_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_state text;
  v_state_at timestamptz;
  v_pipeline text;
  v_client_reply timestamptz;
  v_active_rfq boolean;
begin
  if new.project_id is null or coalesce(new.source,'')='manual' then
    return new;
  end if;

  select operational_state, operational_state_at, pipeline_stage
    into v_state, v_state_at, v_pipeline
  from public.projects
  where id=new.project_id;

  /* Supplier follow-up tasks are valid only for a still-open sent RFQ in an active sourcing stage. */
  if lower(coalesce(new.source,'')) in ('sla_auto','auto_followup') then
    select exists(
      select 1
      from public.rfq_log r
      where r.project_id=new.project_id
        and lower(coalesce(r.supplier_email,''))=lower(coalesce(new.contact_email,''))
        and lower(coalesce(r.status,''))='sent'
        and r.sent_at is not null
        and r.replied_at is null
    ) into v_active_rfq;

    if coalesce(v_state,'') in ('wait_for_client','execution')
       or lower(coalesce(v_pipeline,'')) not in ('rfq_in','technical_review','supplier_selection','pricing')
       or not coalesce(v_active_rfq,false) then
      if tg_op='INSERT' then
        return null;
      end if;
      new.status:='mbyllur';
      new.done_at:=coalesce(new.done_at,now());
      if position('PPPP: auto-mbyllur sepse RFQ nuk është më aktiv' in coalesce(new.detail,''))=0 then
        new.detail:=concat_ws(E'\n',nullif(new.detail,''),'PPPP: auto-mbyllur sepse RFQ nuk është më aktiv për follow-up në gjendjen aktuale të projektit.');
      end if;
      return new;
    end if;
  end if;

  if coalesce(v_state,'') <> 'wait_for_client' then
    return new;
  end if;

  select max(e.sent_at) into v_client_reply
  from public.project_emails e
  where e.project_id=new.project_id
    and lower(coalesce(e.direction,''))='incoming'
    and e.sent_at>coalesce(v_state_at,'1970-01-01'::timestamptz)
    and not exists (
      select 1 from public.rfq_log r
      where r.project_id=new.project_id
        and lower(coalesce(r.supplier_email,''))=lower(coalesce(e.from_email,''))
    );

  if v_client_reply is null then
    if tg_op='INSERT' and coalesce(new.source,'') <> 'semantic_brain_auto' then
      return null;
    end if;
    new.status:='mbyllur';
    new.done_at:=coalesce(new.done_at,now());
    if position('PPPP: auto-mbyllur sepse projekti është në wait_for_client' in coalesce(new.detail,''))=0 then
      new.detail:=concat_ws(E'\n',nullif(new.detail,''),'PPPP: auto-mbyllur sepse projekti është në wait_for_client dhe nuk ka përgjigje të re nga blerësi.');
    end if;
    return new;
  end if;

  update public.projects
  set operational_state='action_required',
      operational_state_at=v_client_reply,
      operational_state_source='client_reply_auto',
      updated_at=now()
  where id=new.project_id;

  return new;
end;
$$;


ALTER FUNCTION public.pppp_wait_state_automated_task_guard() OWNER TO postgres;

--
-- Name: pppp_whatsapp_project_context_v1(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pppp_whatsapp_project_context_v1(p_project_id uuid, p_limit integer DEFAULT 40) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with bounded as (
  select
    id,
    import_batch_id,
    source_file_name,
    sender_name,
    sender_phone,
    message_text,
    sent_at,
    direction,
    created_at
  from public.pppp_whatsapp_messages_v1
  where project_id = p_project_id
  order by sent_at desc nulls last, created_at desc, id desc
  limit least(100, greatest(1, coalesce(p_limit, 40)))
), ordered as (
  select * from bounded
  order by sent_at asc nulls first, created_at asc, id asc
)
select jsonb_build_object(
  'project_id', p_project_id,
  'message_count', (select count(*) from bounded),
  'messages', coalesce((
    select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'id', id,
      'import_batch_id', import_batch_id,
      'source_file_name', source_file_name,
      'sender_name', sender_name,
      'sender_phone', sender_phone,
      'message_text', message_text,
      'sent_at', sent_at,
      'direction', direction,
      'created_at', created_at
    )) order by sent_at asc nulls first, created_at asc, id asc)
    from ordered
  ), '[]'::jsonb),
  'read_only', true,
  'generated_at', now()
);
$$;


ALTER FUNCTION public.pppp_whatsapp_project_context_v1(p_project_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: project_document_intake_internal_process(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.project_document_intake_internal_process(p_link_id bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'net'
    AS $$
declare
  v_secret text;
  v_request_id bigint;
begin
  if p_link_id is null or p_link_id <= 0 then
    raise exception 'Invalid attachment link id';
  end if;
  select decrypted_secret into v_secret
  from vault.decrypted_secrets
  where name='gmail_tracker_cron_secret'
  limit 1;
  if v_secret is null or v_secret='' then
    raise exception 'Internal cron secret is unavailable';
  end if;
  select net.http_get(
    url := 'https://awqfpnzqwfjrjefoktgd.supabase.co/functions/v1/project-document-intake?action=process_id&id='||p_link_id,
    headers := jsonb_build_object('x-pppp-cron-secret',v_secret),
    timeout_milliseconds := 120000
  ) into v_request_id;
  return v_request_id;
end;
$$;


