--
-- Name: semantic_claim_job(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.semantic_claim_job(p_worker_label text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job public.semantic_ai_jobs%rowtype;
begin
  update public.semantic_ai_jobs
  set state='superseded',
      error=coalesce(error,'') || case when coalesce(error,'')='' then '' else E'\n' end || 'Claim expired after 30 minutes',
      updated_at=now()
  where state='claimed'
    and claimed_at < now()-interval '30 minutes';

  select * into v_job
  from public.semantic_ai_jobs
  where state='pending'
  order by created_at asc
  for update skip locked
  limit 1;

  if not found then return null; end if;

  update public.semantic_ai_jobs
  set state='claimed',
      worker_id=p_worker_label,
      attempts=coalesce(attempts,0)+1,
      claimed_at=now(),
      updated_at=now(),
      error=null
  where id=v_job.id
  returning * into v_job;

  return to_jsonb(v_job);
end;
$$;


ALTER FUNCTION public.semantic_claim_job(p_worker_label text) OWNER TO postgres;

--
-- Name: semantic_complete_job(uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.semantic_complete_job(p_job_id uuid, p_worker_label text, p_model text DEFAULT NULL::text, p_result jsonb DEFAULT NULL::jsonb, p_error text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_state text;
begin
  select state into v_state
  from public.semantic_ai_jobs
  where id=p_job_id
    and coalesce(worker_id,'')=coalesce(p_worker_label,'')
  for update;

  if not found or v_state not in ('claimed','superseded') then
    return false;
  end if;

  if v_state='superseded' then
    update public.semantic_ai_jobs
    set model=coalesce(nullif(p_model,''),model),
        result=case when nullif(p_error,'') is null then coalesce(p_result,result) else result end,
        error=coalesce(error,nullif(p_error,'')),
        completed_at=coalesce(completed_at,now()),
        updated_at=now()
    where id=p_job_id;
    return true;
  end if;

  update public.semantic_ai_jobs
  set state=case when nullif(p_error,'') is null then 'completed' else 'failed' end,
      model=coalesce(nullif(p_model,''),model),
      result=case when nullif(p_error,'') is null then coalesce(p_result,'{}'::jsonb) else result end,
      error=nullif(p_error,''),completed_at=now(),updated_at=now()
  where id=p_job_id;
  return true;
end;
$$;


ALTER FUNCTION public.semantic_complete_job(p_job_id uuid, p_worker_label text, p_model text, p_result jsonb, p_error text) OWNER TO postgres;

