--
-- Name: semantic_worker_ready_v1(interval); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.semantic_worker_ready_v1(p_max_age interval DEFAULT '00:15:00'::interval) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(
    select 1
    from public.semantic_worker_keys w
    where w.is_active
      and w.last_used_at is not null
      and w.last_used_at >= now() - greatest(coalesce(p_max_age,interval '15 minutes'),interval '1 minute')
  );
$$;


