--
-- Name: pppp_contact_master_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_contact_master_v1 WITH (security_invoker='true') AS
 WITH ranked AS (
         SELECT c_1.id,
            c_1.created_at,
            c_1.kind,
            c_1.company,
            c_1.person,
            c_1.email,
            c_1.phone,
            c_1.country,
            c_1.role,
            c_1.notes,
            c_1.hubspot_id,
            c_1.last_contact,
            c_1.hubspot_url,
            row_number() OVER (PARTITION BY COALESCE(NULLIF(lower(TRIM(BOTH FROM c_1.email)), ''::text), ('__id__'::text || (c_1.id)::text)) ORDER BY (c_1.hubspot_id IS NOT NULL) DESC, c_1.created_at, c_1.id) AS rn
           FROM public.contacts c_1
        ), canonical AS (
         SELECT ranked.id,
            ranked.created_at,
            ranked.kind,
            ranked.company,
            ranked.person,
            ranked.email,
            ranked.phone,
            ranked.country,
            ranked.role,
            ranked.notes,
            ranked.hubspot_id,
            ranked.last_contact,
            ranked.hubspot_url,
            ranked.rn
           FROM ranked
          WHERE (ranked.rn = 1)
        )
 SELECT id AS contact_id,
    kind,
    company,
    person,
    email,
    phone,
    country,
    role,
    last_contact,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('source', s.source, 'external_id', s.external_id, 'external_url', s.external_url, 'first_seen', s.first_seen, 'last_seen', s.last_seen, 'metadata', s.metadata) ORDER BY s.source, s.last_seen DESC NULLS LAST) AS jsonb_agg
           FROM public.contact_sources s
          WHERE (((NULLIF(TRIM(BOTH FROM COALESCE(c.email, ''::text)), ''::text) IS NOT NULL) AND (lower(COALESCE(s.email, ''::text)) = lower(c.email))) OR (s.contact_id IN ( SELECT (d.id)::text AS id
                   FROM public.contacts d
                  WHERE ((NULLIF(TRIM(BOTH FROM COALESCE(c.email, ''::text)), ''::text) IS NOT NULL) AND (lower(d.email) = lower(c.email))))))), '[]'::jsonb) AS sources,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('project_id', pc.project_id, 'name', p.name, 'role', pc.role, 'first_seen', pc.first_seen, 'last_seen', pc.last_seen, 'email_count', pc.email_count) ORDER BY pc.last_seen DESC NULLS LAST) AS jsonb_agg
           FROM (public.project_contacts pc
             LEFT JOIN public.projects p ON (((p.id)::text = pc.project_id)))
          WHERE ((NULLIF(TRIM(BOTH FROM COALESCE(c.email, ''::text)), ''::text) IS NOT NULL) AND (lower(pc.email) = lower(c.email)))), '[]'::jsonb) AS projects,
    COALESCE(( SELECT sum(pc.email_count) AS sum
           FROM public.project_contacts pc
          WHERE ((NULLIF(TRIM(BOTH FROM COALESCE(c.email, ''::text)), ''::text) IS NOT NULL) AND (lower(pc.email) = lower(c.email)))), (0)::bigint) AS project_email_count,
    GREATEST(COALESCE(created_at, '1900-01-01 00:00:00+00'::timestamp with time zone), COALESCE(( SELECT max(s.last_seen) AS max
           FROM public.contact_sources s
          WHERE (((NULLIF(TRIM(BOTH FROM COALESCE(c.email, ''::text)), ''::text) IS NOT NULL) AND (lower(COALESCE(s.email, ''::text)) = lower(c.email))) OR (s.contact_id IN ( SELECT (d.id)::text AS id
                   FROM public.contacts d
                  WHERE ((NULLIF(TRIM(BOTH FROM COALESCE(c.email, ''::text)), ''::text) IS NOT NULL) AND (lower(d.email) = lower(c.email))))))), '1900-01-01 00:00:00+00'::timestamp with time zone)) AS last_seen_at
   FROM canonical c;


ALTER VIEW public.pppp_contact_master_v1 OWNER TO postgres;

