-- Name: pppp_dach_steel_home_summary_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_dach_steel_home_summary_v1 AS
 WITH active AS (
         SELECT t.id,
            t.source_key,
            t.source_name,
            t.source_url,
            t.partner_id,
            t.project_id,
            t.company_name,
            t.company_domain,
            t.company_website,
            t.country,
            t.buyer_type,
            t.score_band,
            t.target_status,
            t.why_now,
            t.project_title,
            t.project_reference,
            t.award_date,
            t.procurement_timing,
            t.quote_readiness,
            t.steel_scope,
            t.products,
            t.estimated_tonnes,
            t.material_revision,
            t.material_confidence,
            t.material_scope,
            t.evidence,
            t.contact_status,
            t.outreach_status,
            t.outbound_source_key,
            t.next_action,
            t.next_action_due,
            t.last_verified_at,
            t.created_at,
            t.updated_at,
            t.outreach_engine_version,
            t.outreach_motion,
            t.workflow_state,
            t.company_fit_score,
            t.commercial_timing_score,
            t.contact_quality_score,
            t.message_evidence_score,
            t.outreach_readiness_score,
            t.contact_tier,
            t.timing_classification,
            t.canonical_contact_email,
            t.canonical_contact_name,
            t.canonical_contact_role,
            t.personalization_facts,
            t.readiness_reasons,
            t.reply_classification,
            t.reply_evidence,
            t.cooldown_until,
            t.pristeel_offer_model,
            t.secondary_pristeel_offer_model,
            t.intelligence_profile,
            t.intelligence_refreshed_at,
            ((NULLIF(t.canonical_contact_email, ''::text) IS NOT NULL) AND (COALESCE(t.contact_quality_score, 0) >= 50)) AS has_resolved_contact
           FROM public.pppp_dach_steel_targets_v1 t
          WHERE ((t.target_status <> ALL (ARRAY['closed'::text, 'rejected'::text, 'project_promoted'::text])) AND (t.project_id IS NULL) AND ((t.source_key ~~ 'eu:%'::text) OR (t.source_key ~~ 'mt:%'::text)))
        ), hot AS (
         SELECT a.id,
            a.company_name,
            a.project_title,
            a.quote_readiness,
            a.why_now,
            a.estimated_tonnes,
            a.procurement_timing
           FROM active a
          WHERE ((a.workflow_state = 'ready_for_outreach'::text) AND (a.outreach_status = ANY (ARRAY['not_ready'::text, 'ready'::text, 'queued'::text])))
          ORDER BY
                CASE a.score_band
                    WHEN 'A1'::text THEN 1
                    WHEN 'A2'::text THEN 2
                    WHEN 'B1'::text THEN 3
                    WHEN 'B2'::text THEN 4
                    ELSE 5
                END, a.outreach_readiness_score DESC NULLS LAST,
                CASE a.quote_readiness
                    WHEN 'M3'::text THEN 1
                    WHEN 'M2'::text THEN 2
                    WHEN 'M1'::text THEN 3
                    ELSE 4
                END, a.next_action_due, a.updated_at DESC
         LIMIT 1
        ), outbound AS (
         SELECT (count(*) FILTER (WHERE ((q.sent_at IS NOT NULL) OR (q.status = 'sent'::text))))::integer AS sent,
            (count(*) FILTER (WHERE ((q.replied_at IS NOT NULL) OR (q.status = 'replied'::text))))::integer AS replies
           FROM (public.pppp_outbound_queue_v1 q
             JOIN active a ON ((a.id = q.source_record_id)))
          WHERE (q.source = 'DACH_STEEL_BUYER'::text)
        )
 SELECT ( SELECT (count(*))::integer AS count
           FROM active) AS targets,
    ( SELECT (count(*))::integer AS count
           FROM active
          WHERE (active.score_band = 'A1'::text)) AS a1_targets,
    ( SELECT (count(*))::integer AS count
           FROM active
          WHERE (active.quote_readiness = 'M3'::text)) AS quote_ready,
    ( SELECT (count(*))::integer AS count
           FROM active
          WHERE (NOT active.has_resolved_contact)) AS needs_contact,
    ( SELECT (count(*))::integer AS count
           FROM active
          WHERE ((active.workflow_state = 'ready_for_outreach'::text) AND (active.outreach_status = ANY (ARRAY['not_ready'::text, 'ready'::text, 'queued'::text])))) AS ready_for_outreach,
    COALESCE(( SELECT outbound.sent
           FROM outbound), 0) AS sent,
    COALESCE(( SELECT outbound.replies
           FROM outbound), 0) AS replies,
    COALESCE(( SELECT round(sum(active.estimated_tonnes), 3) AS round
           FROM active
          WHERE (active.estimated_tonnes IS NOT NULL)), (0)::numeric) AS identified_tonnes,
    ( SELECT hot.id
           FROM hot) AS hot_target_id,
    ( SELECT hot.company_name
           FROM hot) AS hot_company_name,
    ( SELECT hot.project_title
           FROM hot) AS hot_project_title,
    ( SELECT hot.quote_readiness
           FROM hot) AS hot_quote_readiness,
    ( SELECT hot.why_now
           FROM hot) AS hot_why_now,
    ( SELECT hot.estimated_tonnes
           FROM hot) AS hot_estimated_tonnes,
    ( SELECT hot.procurement_timing
           FROM hot) AS hot_procurement_timing,
    now() AS calculated_at;


ALTER VIEW public.pppp_dach_steel_home_summary_v1 OWNER TO postgres;

--
-- Name: pppp_dach_steel_operational_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_dach_steel_operational_v1 WITH (security_invoker='true') AS
 SELECT t.id,
    t.source_key,
    t.source_name,
    t.source_url,
    t.partner_id,
    t.project_id,
    t.company_name,
    t.company_domain,
    t.company_website,
    t.country,
    t.buyer_type,
    t.score_band,
    t.target_status,
    t.why_now,
    t.project_title,
    t.project_reference,
    t.award_date,
    t.procurement_timing,
    t.quote_readiness,
    t.steel_scope,
    t.products,
    t.estimated_tonnes,
    t.material_revision,
    t.material_confidence,
    t.material_scope,
    t.evidence,
    t.contact_status,
    t.outreach_status,
    t.outbound_source_key,
    t.next_action,
    t.next_action_due,
    t.last_verified_at,
    t.created_at,
    t.updated_at,
    c.contact_resolution,
    NULLIF((c.contact_resolution ->> 'email'::text), ''::text) AS resolved_contact_email,
    NULLIF((c.contact_resolution ->> 'person'::text), ''::text) AS resolved_contact_name,
    NULLIF((c.contact_resolution ->> 'role'::text), ''::text) AS resolved_contact_role,
    NULLIF((c.contact_resolution ->> 'source'::text), ''::text) AS resolved_contact_source,
    NULLIF((c.contact_resolution ->> 'quality'::text), ''::text) AS resolved_contact_quality,
        CASE
            WHEN ((c.contact_resolution ->> 'score'::text) ~ '^[0-9]+$'::text) THEN ((c.contact_resolution ->> 'score'::text))::integer
            ELSE NULL::integer
        END AS resolved_contact_score,
        CASE
            WHEN (NULLIF((c.contact_resolution ->> 'email'::text), ''::text) IS NOT NULL) THEN 'found'::text
            ELSE t.contact_status
        END AS operational_contact_status
   FROM (public.pppp_dach_steel_targets_v1 t
     CROSS JOIN LATERAL ( SELECT public.pppp_dach_steel_contact_resolution_v1(t.id) AS contact_resolution) c);


ALTER VIEW public.pppp_dach_steel_operational_v1 OWNER TO postgres;

