    CONSTRAINT pppp_representation_targets_v1_proposed_commission_pct_check CHECK (((proposed_commission_pct IS NULL) OR ((proposed_commission_pct >= (0)::numeric) AND (proposed_commission_pct <= (100)::numeric)))),
    CONSTRAINT pppp_representation_targets_v1_proposed_retainer_check CHECK (((proposed_retainer IS NULL) OR (proposed_retainer >= (0)::numeric))),
    CONSTRAINT pppp_representation_targets_v1_source_key_check CHECK (((length(btrim(source_key)) >= 1) AND (length(btrim(source_key)) <= 500))),
    CONSTRAINT pppp_representation_targets_v1_stage_check CHECK ((stage = ANY (ARRAY['found'::text, 'verified'::text, 'contact_ready'::text, 'draft_ready'::text, 'contacted'::text, 'replied'::text, 'meeting'::text, 'negotiation'::text, 'pilot'::text, 'represented'::text, 'closed'::text]))),
    CONSTRAINT pppp_representation_targets_v1_target_model_check CHECK ((target_model = ANY (ARRAY['commercial_agent'::text, 'market_development_partner'::text, 'distributor_no_stock'::text, 'distributor_with_stock'::text, 'project_based_representation'::text, 'unknown'::text]))),
    CONSTRAINT pppp_representation_targets_v1_target_type_check CHECK ((target_type = ANY (ARRAY['lead_epc_candidate'::text, 'oem_specialist_partner'::text, 'representation'::text]))),
    CONSTRAINT pppp_representation_website_url_check CHECK (((company_website IS NULL) OR (company_website ~* '^https?://'::text)))
);


