--
-- Name: pppp_eu_direct_operational_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_eu_direct_operational_v1 WITH (security_invoker='true') AS
 WITH base AS (
         SELECT t.id,
            'canonical'::text AS record_origin,
            t.source_key,
            t.company_name,
            t.company_domain,
            t.company_domain_normalized,
            t.company_website,
            t.country,
            t.country_code,
            t.company_type,
            t.business_scope,
            t.why_relevant,
            t.evidence,
            t.source_name,
            t.source_url,
            t.discovery_source,
            t.stage,
            t.priority_score,
            t.contact_name,
            t.contact_role,
            t.contact_email,
            t.contact_source_url,
            t.contact_status,
            t.outreach_status,
            t.do_not_contact,
            t.gmail_draft_id,
            t.gmail_thread_id,
            t.last_contact_at,
            t.next_action,
            t.next_action_due,
            t.notes,
            t.last_verified_at,
            t.archived_at,
            t.archive_reason,
            t.created_at,
            t.updated_at
           FROM public.pppp_eu_direct_targets_v1 t
        UNION ALL
         SELECT g.id,
            'historike_gc'::text AS text,
            ('legacy-gc:'::text || (g.id)::text) AS text,
            g.company_name,
            public.pppp_normalize_company_domain_v1(COALESCE(g.company_domain, g.website_url)) AS pppp_normalize_company_domain_v1,
            public.pppp_normalize_company_domain_v1(COALESCE(g.company_domain, g.website_url)) AS pppp_normalize_company_domain_v1,
            g.website_url,
            g.country,
            g.country_code,
                CASE
                    WHEN ((lower(COALESCE(g.company_type, ''::text)) ~~ '%gc%'::text) OR (lower(COALESCE(g.company_type, ''::text)) ~~ '%gu%'::text)) THEN 'gc_gu'::text
                    ELSE 'other_direct_client'::text
                END AS "case",
            array_remove(ARRAY[NULLIF(g.pristeel_offer_model, ''::text), NULLIF(g.secondary_pristeel_offer_model, ''::text)], NULL::text) AS array_remove,
            COALESCE(NULLIF(g.pristeel_offer_model, ''::text), 'Klient i drejtpërdrejtë për kapacitet dhe paketa çeliku të fabrikuar.'::text) AS "coalesce",
            g.evidence,
            g.discovery_source,
            g.source_url,
            g.discovery_source,
                CASE
                    WHEN (g.replied_at IS NOT NULL) THEN 'replied'::text
                    WHEN ((g.first_sent_at IS NOT NULL) OR (g.second_sent_at IS NOT NULL)) THEN 'contacted'::text
                    WHEN ((g.first_draft_id IS NOT NULL) OR (g.second_draft_id IS NOT NULL)) THEN 'draft_ready'::text
                    WHEN (NULLIF(g.contact_email, ''::text) IS NOT NULL) THEN 'contact_ready'::text
                    ELSE 'verified'::text
                END AS "case",
            GREATEST(0, LEAST(100, COALESCE(g.relevance_score, 0))) AS "greatest",
            g.contact_name,
            g.contact_role,
            g.contact_email,
            g.contact_source_url,
                CASE
                    WHEN (NULLIF(g.contact_email, ''::text) IS NOT NULL) THEN 'verified'::text
                    ELSE 'unknown'::text
                END AS "case",
                CASE
                    WHEN (g.replied_at IS NOT NULL) THEN 'replied'::text
                    WHEN ((g.first_sent_at IS NOT NULL) OR (g.second_sent_at IS NOT NULL)) THEN 'contacted'::text
                    WHEN ((g.first_draft_id IS NOT NULL) OR (g.second_draft_id IS NOT NULL)) THEN 'draft'::text
                    ELSE 'not_ready'::text
                END AS "case",
            g.do_not_contact,
            COALESCE(g.second_draft_id, g.first_draft_id) AS "coalesce",
            g.first_gmail_thread_id,
            GREATEST(g.second_sent_at, g.first_sent_at, g.replied_at) AS "greatest",
            NULL::text AS text,
            g.followup_due_date,
            NULL::text AS text,
            g.researched_at,
            NULL::timestamp with time zone AS timestamptz,
            NULL::text AS text,
            g.first_discovered_at,
            g.updated_at
           FROM public.pppp_gc_prospects_v1 g
          WHERE ((g.discovery_source = 'manual_web_verified_2026-09-22'::text) AND (NOT (EXISTS ( SELECT 1
                   FROM public.pppp_eu_direct_targets_v1 t
                  WHERE ((t.archived_at IS NULL) AND (t.company_domain_normalized = public.pppp_normalize_company_domain_v1(COALESCE(g.company_domain, g.website_url))))))))
        ), flags AS (
         SELECT b.id,
            b.record_origin,
            b.source_key,
            b.company_name,
            b.company_domain,
            b.company_domain_normalized,
            b.company_website,
            b.country,
            b.country_code,
            b.company_type,
            b.business_scope,
            b.why_relevant,
            b.evidence,
            b.source_name,
            b.source_url,
            b.discovery_source,
            b.stage,
            b.priority_score,
            b.contact_name,
            b.contact_role,
            b.contact_email,
            b.contact_source_url,
            b.contact_status,
            b.outreach_status,
            b.do_not_contact,
            b.gmail_draft_id,
            b.gmail_thread_id,
            b.last_contact_at,
            b.next_action,
            b.next_action_due,
            b.notes,
            b.last_verified_at,
            b.archived_at,
            b.archive_reason,
            b.created_at,
            b.updated_at,
            (EXISTS ( SELECT 1
                   FROM public.pppp_dach_steel_targets_v1 m
                  WHERE ((m.target_status <> 'archived'::text) AND (public.pppp_normalize_company_domain_v1(COALESCE(m.company_domain, m.company_website)) = b.company_domain_normalized)))) AS in_material_trade,
            (EXISTS ( SELECT 1
                   FROM public.pppp_representation_targets_v1 r
                  WHERE ((r.archived_at IS NULL) AND (r.company_domain_normalized = b.company_domain_normalized)))) AS in_representations,
            (EXISTS ( SELECT 1
                   FROM public.pppp_opportunity_company_profiles_v1 o
                  WHERE (public.pppp_normalize_company_domain_v1(o.domain) = b.company_domain_normalized))) AS in_opportunities,
            (EXISTS ( SELECT 1
                   FROM public.pppp_outbound_queue_v1 q
                  WHERE (((public.pppp_normalize_company_domain_v1(q.company_domain) = b.company_domain_normalized) OR (split_part(lower(COALESCE(q.recipient_email, ''::text)), '@'::text, 2) = b.company_domain_normalized)) AND (q.gmail_draft_id IS NOT NULL) AND (q.sent_at IS NULL) AND (COALESCE(q.status, ''::text) <> ALL (ARRAY['suppressed'::text, 'closed'::text]))))) AS has_active_draft,
            GREATEST(( SELECT max(q.sent_at) AS max
                   FROM public.pppp_outbound_queue_v1 q
                  WHERE ((public.pppp_normalize_company_domain_v1(q.company_domain) = b.company_domain_normalized) OR (split_part(lower(COALESCE(q.recipient_email, ''::text)), '@'::text, 2) = b.company_domain_normalized))), ( SELECT max(o.sent_at) AS max
                   FROM public.pppp_opportunity_outreach_registry_v1 o
                  WHERE (split_part(lower(COALESCE(o.recipient_email, ''::text)), '@'::text, 2) = b.company_domain_normalized)), b.last_contact_at) AS last_outbound_at,
            ( SELECT (max(c.last_contact))::timestamp with time zone AS max
                   FROM public.pppp_contact_master_v1 c
                  WHERE ((split_part(lower(COALESCE(c.email, ''::text)), '@'::text, 2) = b.company_domain_normalized) OR (lower(btrim(COALESCE(c.company, ''::text))) = lower(btrim(b.company_name))))) AS contact_master_last_contact,
            (EXISTS ( SELECT 1
                   FROM public.pppp_contact_master_v1 c
                  WHERE ((split_part(lower(COALESCE(c.email, ''::text)), '@'::text, 2) = b.company_domain_normalized) OR (lower(btrim(COALESCE(c.company, ''::text))) = lower(btrim(b.company_name)))))) AS known_in_contact_master
           FROM base b
        )
 SELECT id,
    record_origin,
    source_key,
    company_name,
    company_domain,
    company_domain_normalized,
    company_website,
    country,
    country_code,
    company_type,
    business_scope,
    why_relevant,
    evidence,
    source_name,
    source_url,
    discovery_source,
    stage,
    priority_score,
    contact_name,
    contact_role,
    contact_email,
    contact_source_url,
    contact_status,
    outreach_status,
    do_not_contact,
    gmail_draft_id,
    gmail_thread_id,
    last_contact_at,
    next_action,
    next_action_due,
    notes,
    last_verified_at,
    archived_at,
    archive_reason,
    created_at,
    updated_at,
    in_material_trade,
    in_representations,
    in_opportunities,
    has_active_draft,
    last_outbound_at,
    contact_master_last_contact,
    known_in_contact_master,
    array_remove(ARRAY[
        CASE
            WHEN in_material_trade THEN 'material_trade'::text
            ELSE NULL::text
        END,
        CASE
            WHEN in_representations THEN 'representations'::text
            ELSE NULL::text
        END,
        CASE
            WHEN in_opportunities THEN 'opportunities'::text
            ELSE NULL::text
        END], NULL::text) AS routing_conflicts,
        CASE
            WHEN do_not_contact THEN 'blocked'::text
            WHEN (GREATEST(last_outbound_at, contact_master_last_contact) >= (now() - '30 days'::interval)) THEN 'cooldown_30d'::text
            WHEN has_active_draft THEN 'existing_draft'::text
            WHEN (in_material_trade OR in_representations OR in_opportunities) THEN 'routing_review'::text
            WHEN (GREATEST(last_outbound_at, contact_master_last_contact) IS NOT NULL) THEN 'contacted_before'::text
            ELSE 'clear'::text
        END AS outreach_guard,
        CASE
            WHEN (in_material_trade OR in_representations OR in_opportunities) THEN 'review'::text
            ELSE 'clear'::text
        END AS routing_state
   FROM flags f;


ALTER VIEW public.pppp_eu_direct_operational_v1 OWNER TO postgres;

