    supplier text,
    invoice_nr text,
    expense_date date,
    category text,
    amount numeric,
    net_amount numeric,
    vat_rate numeric,
    vat_amount numeric,
    currency text DEFAULT 'EUR'::text,
    project_id uuid,
    vehicle_plate text,
    quantity numeric,
    unit text,
    unit_price numeric,
    confidence numeric,
