    CONSTRAINT pppp_expense_receipts_v1_source_type_check CHECK ((source_type = ANY (ARRAY['camera'::text, 'upload'::text, 'drive'::text]))),
    CONSTRAINT pppp_expense_receipts_v1_status_check CHECK ((status = ANY (ARRAY['needs_ocr'::text, 'ocr_queued'::text, 'ocr_processing'::text, 'review'::text, 'confirmed'::text, 'duplicate'::text, 'failed'::text, 'no_text'::text, 'ignored'::text])))
);


ALTER TABLE public.pppp_expense_receipts_v1 OWNER TO postgres;

--
-- Name: pppp_expense_receipt_review_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_expense_receipt_review_v1 WITH (security_invoker='true') AS
 SELECT id,
    source_type,
    source_ref,
    drive_file_id,
    drive_file_url,
    file_name,
    mime_type,
    size_bytes,
    status,
    supplier,
    invoice_nr,
    expense_date,
    category,
    amount,
    net_amount,
    vat_rate,
    vat_amount,
    currency,
    project_id,
    vehicle_plate,
    quantity,
    unit,
    unit_price,
    confidence,
    review_fields,
    expense_id,
    last_error,
    created_at,
    updated_at,
    confirmed_at
   FROM public.pppp_expense_receipts_v1
  WHERE (status <> ALL (ARRAY['ignored'::text, 'duplicate'::text]))
  ORDER BY
        CASE status
            WHEN 'review'::text THEN 1
            WHEN 'no_text'::text THEN 2
            WHEN 'failed'::text THEN 3
            WHEN 'ocr_processing'::text THEN 4
            WHEN 'ocr_queued'::text THEN 5
            ELSE 9
        END, created_at DESC;


