--
-- Name: pppp_followup_draft_queue_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_followup_draft_queue_v1 WITH (security_invoker='true') AS
 SELECT d.id,
    d.task_id,
    d.project_id,
    d.task_source,
    d.party_type,
    d.contact_email,
    d.due_date,
    d.last_outgoing_email_id,
    d.last_outgoing_gmail_message_id,
    d.last_outgoing_gmail_thread_id,
    d.last_outgoing_rfc822_message_id,
    d.last_outgoing_subject,
    d.last_outgoing_snippet,
    d.lang,
    d.status,
    d.gmail_draft_id,
    d.gmail_message_id,
    d.gmail_thread_id,
    d.human_send_required,
    d.last_error,
    d.created_at,
    d.updated_at,
    p.name AS project_name,
    p.client,
    t.title AS task_title,
    t.detail AS task_detail
   FROM ((public.pppp_followup_drafts_v1 d
     JOIN public.tasks t ON ((t.id = d.task_id)))
     LEFT JOIN public.projects p ON ((p.id = d.project_id)))
  WHERE ((d.status = 'candidate'::text) AND (t.status = 'hapur'::text) AND (d.due_date <= CURRENT_DATE));


