--

CREATE VIEW public.pppp_gc_outreach_review_v1 WITH (security_invoker='true') AS
 SELECT id,
    company_name,
    company_domain,
    country,
    country_code,
    company_type,
    relevance_score,
    status,
    language,
    contact_name,
    contact_email,
    contact_role,
    contact_source_url,
    contact_confidence,
    current_projects,
    recent_projects,
    evidence,
    first_draft_id,
