    second_draft_created_at,
    second_gmail_message_id,
    second_sent_at,
    replied_at,
    bounced_at,
    do_not_contact,
    no_more_auto,
    human_send_required,
    duplicate_reason,
    last_error,
    first_discovered_at,
    last_seen_at,
    updated_at
   FROM public.pppp_gc_prospects_v1 p
  WHERE (status = ANY (ARRAY['contact_ready'::text, 'draft_ready'::text, 'contacted_1'::text, 'followup_due'::text, 'draft_2_ready'::text, 'contacted_2'::text, 'replied'::text, 'no_response_2'::text, 'already_contacted'::text, 'bounced'::text, 'human_review'::text]))
  ORDER BY
        CASE status
            WHEN 'draft_ready'::text THEN 1
            WHEN 'draft_2_ready'::text THEN 2
            WHEN 'followup_due'::text THEN 3
            WHEN 'contact_ready'::text THEN 4
            ELSE 9
        END, relevance_score DESC, updated_at DESC;


