    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    document_id uuid,
    supplier_offer_id uuid,
    scenario_key text NOT NULL,
    project_name text NOT NULL,
    customer text NOT NULL,
    scope_category text NOT NULL,
    variant_label text DEFAULT 'Basis'::text NOT NULL,
    weight_kg numeric,
    production_cost_eur numeric DEFAULT 0 NOT NULL,
    treatment_cost_eur numeric DEFAULT 0 NOT NULL,
    bought_out_cost_eur numeric DEFAULT 0 NOT NULL,
    mechanical_cost_eur numeric DEFAULT 0 NOT NULL,
    packaging_cost_eur numeric DEFAULT 0 NOT NULL,
    transport_cost_eur numeric DEFAULT 0 NOT NULL,
    other_cost_eur numeric DEFAULT 0 NOT NULL,
    landed_cost_eur numeric NOT NULL,
    selling_price_eur numeric NOT NULL,
    outcome text NOT NULL,
    reason text,
    cost_confidence text NOT NULL,
    selling_confidence text NOT NULL,
    outcome_confidence text NOT NULL,
    sent_evidence_status text,
    technical_condition text,
    source_notes text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
