    CONSTRAINT pppp_german_commercial_benchmarks_cost_confidence_check CHECK ((cost_confidence = ANY (ARRAY['confirmed'::text, 'reconstructed'::text, 'estimated'::text, 'missing'::text, 'conflicting'::text]))),
    CONSTRAINT pppp_german_commercial_benchmarks_outcome_check CHECK ((outcome = ANY (ARRAY['win'::text, 'price_loss'::text, 'landed_economics_loss'::text, 'scope_mismatch'::text, 'client_self_perform'::text, 'open'::text, 'open_stale'::text, 'unknown'::text]))),
    CONSTRAINT pppp_german_commercial_benchmarks_outcome_confidence_check CHECK ((outcome_confidence = ANY (ARRAY['confirmed'::text, 'reconstructed'::text, 'estimated'::text, 'missing'::text, 'conflicting'::text]))),
    CONSTRAINT pppp_german_commercial_benchmarks_selling_confidence_check CHECK ((selling_confidence = ANY (ARRAY['confirmed'::text, 'reconstructed'::text, 'estimated'::text, 'missing'::text, 'conflicting'::text])))
);


