-- Name: pppp_project_context_facts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.pppp_project_context_facts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    category text DEFAULT 'general'::text NOT NULL,
    subject text,
    fact_key text NOT NULL,
    value jsonb DEFAULT '{}'::jsonb NOT NULL,
    source_type text DEFAULT 'system'::text NOT NULL,
    source_ref text,
    evidence_status text DEFAULT 'unverified'::text NOT NULL,
    confidence numeric,
    fact_status text DEFAULT 'observed'::text NOT NULL,
    supersedes_id uuid,
    idempotency_key text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by text DEFAULT 'system'::text NOT NULL,
    CONSTRAINT pppp_project_context_facts_confidence_check CHECK (((confidence IS NULL) OR ((confidence >= (0)::numeric) AND (confidence <= (1)::numeric)))),
    CONSTRAINT pppp_project_context_facts_evidence_status_check CHECK ((evidence_status = ANY (ARRAY['unverified'::text, 'observed'::text, 'verbal'::text, 'documented'::text, 'confirmed'::text]))),
    CONSTRAINT pppp_project_context_facts_fact_key_nonempty CHECK ((btrim(fact_key) <> ''::text)),
    CONSTRAINT pppp_project_context_facts_fact_status_check CHECK ((fact_status = ANY (ARRAY['observed'::text, 'suggested'::text, 'dismissed'::text]))),
    CONSTRAINT pppp_project_context_facts_source_type_check CHECK ((source_type = ANY (ARRAY['chatgpt'::text, 'email'::text, 'phone'::text, 'document'::text, 'system'::text, 'user'::text, 'api'::text, 'other'::text])))
);


