--
-- Name: pppp_home_current_actions_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_home_current_actions_v1 WITH (security_invoker='true') AS
 WITH eligible AS (
         SELECT t.id,
            t.project_id,
            p.name AS project_name,
            p.client,
            t.title,
            t.detail,
            t.due_date,
            t.priority,
            t.status,
            t.source,
            t.source_ref,
            t.category,
            t.created_at,
            p.operational_state,
            p.operational_state_at,
            p.pipeline_stage,
            p.last_activity_at,
            p.last_email_at
           FROM (public.tasks t
             JOIN public.projects p ON ((p.id = t.project_id)))
          WHERE ((lower(COALESCE(t.status, ''::text)) <> ALL (ARRAY['kryer'::text, 'done'::text, 'mbyllur'::text, 'closed'::text, 'arkivuar'::text, 'archived'::text])) AND (lower(COALESCE(p.status, ''::text)) <> ALL (ARRAY['humbur'::text, 'lost'::text, 'arkivuar'::text, 'archived'::text, 'mbyllur'::text, 'closed'::text, 'closedlost'::text, 'cancelled'::text, 'canceled'::text, 'realizuar'::text])) AND (NOT ((lower(COALESCE(p.operational_state, ''::text)) = ANY (ARRAY['wait_for_client'::text, 'waiting_for_client'::text])) AND (COALESCE(t.source, ''::text) = ANY (ARRAY['email_request_auto'::text, 'supplier_update_auto'::text, 'commercial_intake_review'::text, 'procurement_comparison_auto'::text, 'client_offer_cost_basis_auto'::text, 'client_offer_final_review_auto'::text, 'project_decision_auto'::text, 'semantic_brain_auto'::text, 'data_integrity_audit'::text, 'supplier_wait_auto'::text, 'auto_followup'::text, 'sla_auto'::text, 'project_discovery_auto'::text, 'opportunity_engine_v2'::text, 'document_bom_review'::text, 'document_image_review'::text, 'dynamic_plan_review'::text])))) AND (NOT (EXISTS ( SELECT 1
                   FROM public.pppp_project_context_current_v f
                  WHERE ((f.project_id = t.project_id) AND (f.category = 'operator_update'::text) AND (f.fact_status = 'observed'::text) AND (lower(COALESCE((f.value ->> 'action_required'::text), ''::text)) = ANY (ARRAY['false'::text, '0'::text, 'no'::text])) AND (COALESCE(t.source, ''::text) = ANY (ARRAY['email_request_auto'::text, 'supplier_update_auto'::text, 'commercial_intake_review'::text, 'procurement_comparison_auto'::text, 'client_offer_cost_basis_auto'::text, 'client_offer_final_review_auto'::text, 'project_decision_auto'::text, 'semantic_brain_auto'::text, 'data_integrity_audit'::text, 'supplier_wait_auto'::text, 'auto_followup'::text, 'sla_auto'::text, 'project_discovery_auto'::text, 'opportunity_engine_v2'::text, 'document_bom_review'::text, 'document_image_review'::text, 'dynamic_plan_review'::text])) AND (((COALESCE((f.value ->> 'source_sent_at'::text), ''::text) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T'::text) AND (((f.value ->> 'source_sent_at'::text))::timestamp with time zone >= t.created_at)) OR ((NOT (COALESCE((f.value ->> 'source_sent_at'::text), ''::text) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T'::text)) AND (f.updated_at >= t.created_at))))))) AND (NOT (EXISTS ( SELECT 1
                   FROM public.pppp_project_context_current_v f
                  WHERE ((f.project_id = t.project_id) AND (f.category = 'operator_update'::text) AND (f.evidence_status = 'confirmed'::text) AND (f.fact_status = 'observed'::text) AND (f.updated_at >= t.created_at) AND (lower(COALESCE((f.value)::text, ''::text)) ~ '(nuk ka.{0,80}(veprim|ndjek)|pa veprim|no action|nothing.{0,50}follow)'::text))))))
        ), direct_candidates AS (
         SELECT e.id,
            e.project_id,
            e.project_name,
            e.client,
            e.title,
            e.detail,
            e.due_date,
            e.priority,
            e.status,
            e.source,
            e.source_ref,
            e.category,
            e.created_at,
            e.operational_state,
            e.operational_state_at,
            e.pipeline_stage,
            e.last_activity_at,
            e.last_email_at,
            row_number() OVER (PARTITION BY e.project_id ORDER BY
                CASE e.source
                    WHEN 'manual'::text THEN 0
                    WHEN 'chatgpt_bridge'::text THEN 1
                    WHEN 'email_request_auto'::text THEN 2
                    WHEN 'supplier_update_auto'::text THEN 3
                    WHEN 'outgoing_invoice_final_review_auto'::text THEN 4
                    WHEN 'outgoing_invoice_review'::text THEN 5
                    WHEN 'commercial_intake_review'::text THEN 6
                    WHEN 'procurement_comparison_auto'::text THEN 7
                    WHEN 'client_offer_cost_basis_auto'::text THEN 8
                    WHEN 'client_offer_final_review_auto'::text THEN 9
                    WHEN 'project_decision_auto'::text THEN 10
                    WHEN 'kontrate'::text THEN 11
                    WHEN 'semantic_brain_auto'::text THEN 12
                    WHEN 'data_integrity_audit'::text THEN 13
                    ELSE 99
                END, e.due_date NULLS FIRST, e.created_at DESC, e.id) AS direct_rn
           FROM eligible e
          WHERE ((e.source = ANY (ARRAY['outgoing_invoice_final_review_auto'::text, 'outgoing_invoice_review'::text, 'commercial_intake_review'::text, 'procurement_comparison_auto'::text, 'client_offer_cost_basis_auto'::text, 'client_offer_final_review_auto'::text])) OR ((e.source = ANY (ARRAY['manual'::text, 'chatgpt_bridge'::text, 'email_request_auto'::text, 'supplier_update_auto'::text])) AND ((e.due_date IS NULL) OR (e.due_date <= (CURRENT_DATE + 7)) OR (lower(COALESCE(e.priority, ''::text)) ~ '(urgjent|urgent|critical|e larte|larte|high)'::text))) OR ((e.source = 'project_decision_auto'::text) AND (lower(COALESCE(e.operational_state, ''::text)) = 'action_required'::text) AND (e.created_at >= COALESCE(e.operational_state_at, e.created_at)) AND ((e.due_date IS NULL) OR (e.due_date <= (CURRENT_DATE + 7)) OR (lower(COALESCE(e.priority, ''::text)) ~ '(urgjent|urgent|critical|e larte|larte|high)'::text))) OR ((e.source = ANY (ARRAY['semantic_brain_auto'::text, 'data_integrity_audit'::text])) AND (lower(COALESCE(e.operational_state, ''::text)) = 'action_required'::text) AND (e.created_at >= COALESCE(e.operational_state_at, e.created_at)) AND ((e.due_date IS NULL) OR (e.due_date <= (CURRENT_DATE + 7)) OR (lower(COALESCE(e.priority, ''::text)) ~ '(urgjent|urgent|critical|e larte|larte|high)'::text))) OR ((e.source = 'kontrate'::text) AND (lower(COALESCE(e.operational_state, ''::text)) = 'execution'::text) AND ((e.due_date IS NULL) OR (e.due_date <= (CURRENT_DATE + 7)) OR (lower(COALESCE(e.priority, ''::text)) ~ '(urgjent|urgent|critical|e larte|larte|high)'::text))))
        ), direct_actions AS (
         SELECT direct_candidates.id,
            direct_candidates.project_id,
            direct_candidates.project_name,
            direct_candidates.client,
            direct_candidates.title,
            direct_candidates.detail,
            direct_candidates.due_date,
            direct_candidates.priority,
            direct_candidates.status,
            direct_candidates.source,
            direct_candidates.source_ref,
            direct_candidates.category,
            direct_candidates.created_at,
            direct_candidates.operational_state,
            direct_candidates.operational_state_at,
            direct_candidates.pipeline_stage,
            direct_candidates.last_activity_at,
            direct_candidates.last_email_at
           FROM direct_candidates
          WHERE (direct_candidates.direct_rn = 1)
        ), overdue_wait_candidates AS (
         SELECT e.id,
            e.project_id,
            e.project_name,
            e.client,
            e.title,
            e.detail,
            e.due_date,
            e.priority,
            e.status,
            e.source,
            e.source_ref,
            e.category,
            e.created_at,
            e.operational_state,
            e.operational_state_at,
            e.pipeline_stage,
            e.last_activity_at,
            e.last_email_at,
            row_number() OVER (PARTITION BY e.project_id ORDER BY e.due_date, e.created_at DESC, e.id) AS wait_rn
           FROM eligible e
          WHERE ((e.source = ANY (ARRAY['supplier_wait_auto'::text, 'invoice_receivable'::text, 'email_followup'::text, 'auto_followup'::text])) AND (e.due_date IS NOT NULL) AND (e.due_date < CURRENT_DATE) AND (NOT (EXISTS ( SELECT 1
                   FROM direct_actions d
                  WHERE (d.project_id = e.project_id)))))
        ), overdue_waits AS (
         SELECT overdue_wait_candidates.id,
            overdue_wait_candidates.project_id,
            overdue_wait_candidates.project_name,
            overdue_wait_candidates.client,
            overdue_wait_candidates.title,
            overdue_wait_candidates.detail,
            overdue_wait_candidates.due_date,
            overdue_wait_candidates.priority,
            overdue_wait_candidates.status,
            overdue_wait_candidates.source,
            overdue_wait_candidates.source_ref,
            overdue_wait_candidates.category,
            overdue_wait_candidates.created_at,
            overdue_wait_candidates.operational_state,
            overdue_wait_candidates.operational_state_at,
            overdue_wait_candidates.pipeline_stage,
            overdue_wait_candidates.last_activity_at,
            overdue_wait_candidates.last_email_at
           FROM overdue_wait_candidates
          WHERE (overdue_wait_candidates.wait_rn = 1)
        )
 SELECT direct_actions.id,
    direct_actions.project_id,
    direct_actions.project_name,
    direct_actions.client,
    direct_actions.title,
    direct_actions.detail,
    direct_actions.due_date,
    direct_actions.priority,
    direct_actions.status,
    direct_actions.source,
    direct_actions.source_ref,
    direct_actions.category,
    direct_actions.created_at,
    direct_actions.operational_state,
    direct_actions.operational_state_at,
    direct_actions.pipeline_stage,
    direct_actions.last_activity_at,
    direct_actions.last_email_at
   FROM direct_actions
UNION ALL
 SELECT overdue_waits.id,
    overdue_waits.project_id,
    overdue_waits.project_name,
    overdue_waits.client,
    overdue_waits.title,
    overdue_waits.detail,
    overdue_waits.due_date,
    overdue_waits.priority,
    overdue_waits.status,
    overdue_waits.source,
    overdue_waits.source_ref,
    overdue_waits.category,
    overdue_waits.created_at,
    overdue_waits.operational_state,
    overdue_waits.operational_state_at,
    overdue_waits.pipeline_stage,
    overdue_waits.last_activity_at,
    overdue_waits.last_email_at
   FROM overdue_waits;


