);


ALTER TABLE public.pppp_procurement_program_watches OWNER TO postgres;

--
-- Name: pppp_procurement_program_matches_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_procurement_program_matches_v1 WITH (security_invoker='true') AS
 WITH tender_base AS (
         SELECT t.id,
            t.created_at,
            t.updated_at,
            t.first_seen_at,
            t.last_seen_at,
            t.source_key,
            t.procurement_no,
            t.publication_no,
            t.authority,
            t.title,
            t.document_type,
            t.fpp,
            t.fpp_description,
            t.contract_type,
            t.contract_value_band,
            t.procedure,
            t.estimated_value,
            t.currency,
            t.deadline,
            t.published_date,
            t.is_retender,
            t.category,
            t.relevance_score,
            t.match_reasons,
            t.status,
            t.project_id,
            t.source_url,
            t.detail_url,
            t.payload,
            upper(COALESCE(NULLIF((t.payload ->> 'source'::text), ''::text), split_part(t.source_key, ':'::text, 1))) AS source_name,
            lower(concat_ws(' '::text, t.title, t.document_type, t.fpp, t.fpp_description, t.contract_type, t.procedure, t.procurement_no, t.publication_no, t.authority, (t.payload)::text)) AS search_text,
            COALESCE(NULLIF((t.payload ->> 'notice_phase'::text), ''::text), 'opportunity'::text) AS notice_phase,
            NULLIF((t.payload ->> 'program_reference'::text), ''::text) AS program_reference
           FROM public.kek_tender_watch t
        ), candidates AS (
         SELECT p.id AS program_watch_id,
            p.program_code,
            p.title AS program_title,
            p.strategic_relevance,
            p.partner_research_policy,
            p.home_notify_new_opportunity,
            pkg.id AS package_watch_id,
            pkg.package_key,
            pkg.title AS package_title,
            pkg.partner_research_required,
            t.id AS tender_watch_id,
            t.source_name AS source,
            t.source_key,
            t.title,
            t.authority,
            t.document_type,
            t.contract_type,
            t.procedure,
            t.relevance_score,
            t.published_date,
            t.deadline,
            t.first_seen_at,
            t.status,
            t.detail_url,
            t.source_url,
            t.payload,
            t.search_text,
            t.program_reference,
            ((upper(COALESCE(t.program_reference, ''::text)) = upper(p.program_code)) OR (t.search_text ~~ (('%'::text || lower(p.program_code)) || '%'::text))) AS program_code_match,
            (EXISTS ( SELECT 1
                   FROM unnest(pkg.match_terms) term(term)
                  WHERE ((term.term <> ''::text) AND (t.search_text ~~ (('%'::text || lower(term.term)) || '%'::text))))) AS package_term_match,
            (NOT (EXISTS ( SELECT 1
                   FROM unnest(pkg.exclude_terms) term(term)
                  WHERE ((term.term <> ''::text) AND (t.search_text ~~ (('%'::text || lower(term.term)) || '%'::text)))))) AS exclusion_clear
           FROM ((tender_base t
             JOIN public.pppp_procurement_program_watches p ON (((p.status = 'active'::text) AND (p.source = t.source_name))))
             JOIN public.pppp_procurement_package_watches pkg ON (((pkg.program_watch_id = p.id) AND (pkg.status = 'watching'::text))))
          WHERE (t.notice_phase = 'opportunity'::text)
        )
 SELECT program_watch_id,
    program_code,
    program_title,
    strategic_relevance,
    partner_research_policy,
    home_notify_new_opportunity,
    package_watch_id,
    package_key,
    package_title,
    partner_research_required,
    tender_watch_id,
    source,
    source_key,
    title,
    authority,
    document_type,
    contract_type,
    procedure,
    relevance_score,
    published_date,
    deadline,
    first_seen_at,
    status,
    detail_url,
    source_url,
    payload,
        CASE
            WHEN (program_code_match AND package_term_match) THEN 'program_code+package_terms'::text
            WHEN package_term_match THEN 'package_terms'::text
            ELSE 'program_code'::text
        END AS match_basis
   FROM candidates
  WHERE (exclusion_clear AND (package_term_match OR program_code_match) AND (package_term_match OR (lower(COALESCE(contract_type, ''::text)) ~ similar_to_escape('%(works|goods|supply)%'::text)) OR (lower(COALESCE(document_type, ''::text)) ~ similar_to_escape('%(bid|tender|quotation|contract notice|specific procurement notice)%'::text))));


ALTER VIEW public.pppp_procurement_program_matches_v1 OWNER TO postgres;

--
-- Name: pppp_procurement_source_policy; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.pppp_procurement_source_policy (
    source text NOT NULL,
    participation_mode text NOT NULL,
    home_eligible boolean DEFAULT false NOT NULL,
    home_min_score integer DEFAULT 65 NOT NULL,
    notes text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pppp_procurement_source_policy_home_min_score_check CHECK (((home_min_score >= 0) AND (home_min_score <= 100))),
    CONSTRAINT pppp_procurement_source_policy_participation_mode_check CHECK ((participation_mode = ANY (ARRAY['bid'::text, 'award_intelligence'::text, 'reference'::text])))
);


ALTER TABLE public.pppp_procurement_source_policy OWNER TO postgres;

--
-- Name: pppp_home_procurement_alerts_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_home_procurement_alerts_v1 WITH (security_invoker='true') AS
 WITH tender_base AS (
         SELECT t.id,
            t.created_at,
            t.updated_at,
            t.first_seen_at,
            t.last_seen_at,
            t.source_key,
            t.procurement_no,
            t.publication_no,
            t.authority,
            t.title,
            t.document_type,
            t.fpp,
            t.fpp_description,
            t.contract_type,
            t.contract_value_band,
            t.procedure,
            t.estimated_value,
            t.currency,
            t.deadline,
            t.published_date,
            t.is_retender,
            t.category,
            t.relevance_score,
            t.match_reasons,
            t.status,
            t.project_id,
            t.source_url,
            t.detail_url,
            t.payload,
            upper(COALESCE(NULLIF((t.payload ->> 'source'::text), ''::text), split_part(t.source_key, ':'::text, 1))) AS source_name,
            COALESCE(NULLIF((t.payload ->> 'notice_phase'::text), ''::text), 'opportunity'::text) AS notice_phase,
            row_number() OVER (PARTITION BY
                CASE
                    WHEN (upper(COALESCE(NULLIF((t.payload ->> 'source'::text), ''::text), split_part(t.source_key, ':'::text, 1))) = 'KRPP'::text) THEN ('KRPP:'::text || COALESCE(NULLIF(t.procurement_no, ''::text), t.source_key))
                    ELSE t.source_key
                END ORDER BY COALESCE(t.published_date, (t.first_seen_at)::date) DESC, t.first_seen_at DESC, t.created_at DESC, t.id DESC) AS identity_rank
           FROM public.kek_tender_watch t
        ), matched AS (
         SELECT m.program_watch_id,
            m.program_code,
            m.program_title,
            m.strategic_relevance,
            m.partner_research_policy,
            m.home_notify_new_opportunity,
            m.package_watch_id,
            m.package_key,
            m.package_title,
            m.partner_research_required,
            m.tender_watch_id,
            m.source,
            m.source_key,
            m.title,
            m.authority,
            m.document_type,
            m.contract_type,
            m.procedure,
            m.relevance_score,
            m.published_date,
            m.deadline,
            m.first_seen_at,
            m.status,
            m.detail_url,
            m.source_url,
            m.payload,
            m.match_basis
           FROM ((public.pppp_procurement_program_matches_v1 m
             JOIN public.pppp_procurement_source_policy sp ON ((sp.source = m.source)))
             JOIN tender_base t ON ((t.id = m.tender_watch_id)))
          WHERE ((sp.participation_mode = 'bid'::text) AND (sp.home_eligible = true) AND (m.source <> 'TED'::text) AND (m.home_notify_new_opportunity = true) AND (COALESCE(m.status, 'new'::text) <> ALL (ARRAY['closed'::text, 'done'::text, 'ignored'::text, 'dismissed'::text, 'superseded'::text, 'won'::text, 'lost'::text])) AND ((m.deadline IS NULL) OR (m.deadline >= CURRENT_DATE)) AND (COALESCE(m.published_date, (m.first_seen_at)::date) >= (CURRENT_DATE - 120)) AND ((m.source <> 'KRPP'::text) OR ((t.identity_rank = 1) AND ((t.payload ->> 'krpp_relevance_layer'::text) = 'main'::text))))
        ), general_alerts AS (
         SELECT t.id AS tender_watch_id,
            t.source_name AS source,
            t.source_key,
            t.title,
            t.authority,
            t.document_type,
            t.contract_type,
            t.procedure,
            t.relevance_score,
            t.published_date,
            t.deadline,
            t.first_seen_at,
            t.status,
            t.detail_url,
            t.source_url,
            t.payload,
            sp.home_min_score
           FROM (tender_base t
             JOIN public.pppp_procurement_source_policy sp ON ((sp.source = t.source_name)))
          WHERE ((sp.participation_mode = 'bid'::text) AND (sp.home_eligible = true) AND (t.source_name <> 'TED'::text) AND (t.notice_phase = 'opportunity'::text) AND (COALESCE(t.relevance_score, 0) >= sp.home_min_score) AND (COALESCE(t.status, 'new'::text) <> ALL (ARRAY['closed'::text, 'done'::text, 'ignored'::text, 'dismissed'::text, 'superseded'::text, 'won'::text, 'lost'::text])) AND ((t.deadline IS NULL) OR (t.deadline >= CURRENT_DATE)) AND (COALESCE(t.published_date, (t.first_seen_at)::date) >= (CURRENT_DATE - 21)) AND ((t.source_name <> 'KRPP'::text) OR ((t.identity_rank = 1) AND ((t.payload ->> 'krpp_relevance_layer'::text) = 'main'::text))) AND ((t.source_name = 'KRPP'::text) OR (lower(COALESCE(t.document_type, ''::text)) !~ '(correction|corrigendum|amendment|erratum|korrig)'::text)) AND (NOT (EXISTS ( SELECT 1
                   FROM matched m
                  WHERE (m.tender_watch_id = t.id)))))
        )
 SELECT ('watch:'::text || (m.tender_watch_id)::text) AS alert_id,
    m.tender_watch_id,
    m.source,
    COALESCE((m.payload ->> 'source_label'::text), m.source) AS source_label,
    m.title,
    m.authority,
    m.document_type,
    m.contract_type,
    m.procedure,
    m.published_date,
    m.deadline,
    m.first_seen_at,
    GREATEST(COALESCE(m.relevance_score, 0), m.strategic_relevance) AS relevance_score,
    'tracked_program'::text AS alert_kind,
    ((('Tender i ri që përputhet me programin '::text || m.program_code) || ' / '::text) || m.package_title) AS alert_reason,
    m.program_watch_id,
    m.program_code,
    m.program_title,
    m.package_watch_id,
    m.package_title,
    m.partner_research_policy,
    m.partner_research_required,
    COALESCE((m.payload -> 'entry_routes'::text), jsonb_build_array('direct_bid', 'consortium_jv', 'local_partner', 'representation', 'subcontractor')) AS entry_routes,
    COALESCE(m.detail_url, m.source_url) AS open_url
   FROM matched m
UNION ALL
 SELECT ('source:'::text || (g.tender_watch_id)::text) AS alert_id,
    g.tender_watch_id,
    g.source,
    COALESCE((g.payload ->> 'source_label'::text), g.source) AS source_label,
    g.title,
    g.authority,
    g.document_type,
    g.contract_type,
    g.procedure,
    g.published_date,
    g.deadline,
    g.first_seen_at,
    g.relevance_score,
    'new_bid_opportunity'::text AS alert_kind,
    'Tender i ri nga burim ku PriSteel mund të marrë pjesë; vlerëso hyrjen direkte, JV/konsorciumin, partnerin lokal ose përfaqësimin.'::text AS alert_reason,
    NULL::uuid AS program_watch_id,
    NULL::text AS program_code,
    NULL::text AS program_title,
    NULL::uuid AS package_watch_id,
    NULL::text AS package_title,
    'dynamic'::text AS partner_research_policy,
    true AS partner_research_required,
    COALESCE((g.payload -> 'entry_routes'::text), jsonb_build_array('direct_bid', 'consortium_jv', 'local_partner', 'representation', 'subcontractor')) AS entry_routes,
    COALESCE(g.detail_url, g.source_url) AS open_url
   FROM general_alerts g;


ALTER VIEW public.pppp_home_procurement_alerts_v1 OWNER TO postgres;

--
-- Name: pppp_home_waiting_projects_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_home_waiting_projects_v1 WITH (security_invoker='true') AS
 WITH open_projects AS (
         SELECT p.id,
            p.created_at,
            p.name,
            p.client,
            p.ref,
            p.location,
            p.deadline,
            p.notes,
            p.drive_folder_id,
            p.drive_folder_url,
            p.status,
            p.pipeline_stage,
            p.deal_type,
            p.execution_bootstrapped_at,
            p.execution_bootstrap_source,
            p.business_ref,
            p.business_type,
            p.identity_aliases,
            p.updated_at,
            p.last_activity_at,
            p.last_email_at,
            p.operational_state,
            p.operational_state_at,
            p.operational_state_source,
            p.origin_type,
            p.work_model
           FROM public.projects p
          WHERE (lower(COALESCE(p.status, ''::text)) <> ALL (ARRAY['humbur'::text, 'lost'::text, 'arkivuar'::text, 'archived'::text, 'mbyllur'::text, 'closed'::text, 'closedlost'::text, 'cancelled'::text, 'canceled'::text, 'realizuar'::text]))
        ), ranked_wait_tasks AS (
         SELECT t.id AS task_id,
            t.project_id,
            p.name AS project_name,
            p.client,
                CASE
                    WHEN (t.source = 'supplier_wait_auto'::text) THEN 'supplier'::text
                    WHEN (t.source = 'invoice_receivable'::text) THEN 'payment'::text
                    WHEN ((t.source = ANY (ARRAY['email_followup'::text, 'auto_followup'::text])) AND (lower(COALESCE(t.category, ''::text)) = 'klient'::text)) THEN 'client'::text
                    WHEN (t.source = ANY (ARRAY['email_followup'::text, 'auto_followup'::text])) THEN 'reply'::text
                    ELSE 'other'::text
                END AS waiting_on,
            t.title AS waiting_reason,
            t.due_date,
            ((t.due_date IS NOT NULL) AND (t.due_date < CURRENT_DATE)) AS is_overdue,
                CASE
                    WHEN ((t.due_date IS NOT NULL) AND (t.due_date < CURRENT_DATE)) THEN (CURRENT_DATE - t.due_date)
                    ELSE 0
                END AS days_overdue,
            t.source,
            t.source_ref,
            t.priority,
            t.created_at,
            p.operational_state,
            p.operational_state_at,
            p.operational_state_source,
            p.pipeline_stage,
            p.last_activity_at,
            p.last_email_at,
            row_number() OVER (PARTITION BY t.project_id ORDER BY t.due_date, t.created_at DESC, t.id) AS rn
           FROM (public.tasks t
             JOIN open_projects p ON ((p.id = t.project_id)))
          WHERE ((lower(COALESCE(t.status, ''::text)) <> ALL (ARRAY['kryer'::text, 'done'::text, 'mbyllur'::text, 'closed'::text, 'arkivuar'::text, 'archived'::text])) AND ((t.source = ANY (ARRAY['supplier_wait_auto'::text, 'invoice_receivable'::text])) OR (t.source = ANY (ARRAY['email_followup'::text, 'auto_followup'::text]))))
        ), task_waits AS (
         SELECT ranked_wait_tasks.task_id,
            ranked_wait_tasks.project_id,
            ranked_wait_tasks.project_name,
            ranked_wait_tasks.client,
            ranked_wait_tasks.waiting_on,
            ranked_wait_tasks.waiting_reason,
            ranked_wait_tasks.due_date,
            ranked_wait_tasks.is_overdue,
            ranked_wait_tasks.days_overdue,
            ranked_wait_tasks.source,
            ranked_wait_tasks.source_ref,
            ranked_wait_tasks.priority,
            ranked_wait_tasks.created_at,
            ranked_wait_tasks.operational_state,
            ranked_wait_tasks.operational_state_at,
            ranked_wait_tasks.operational_state_source,
            ranked_wait_tasks.pipeline_stage,
            ranked_wait_tasks.last_activity_at,
            ranked_wait_tasks.last_email_at,
            ranked_wait_tasks.rn
           FROM ranked_wait_tasks
          WHERE (ranked_wait_tasks.rn = 1)
        ), state_waits AS (
         SELECT NULL::uuid AS task_id,
            p.id AS project_id,
            p.name AS project_name,
            p.client,
                CASE
                    WHEN (p.operational_state_source = 'supplier-wait-auto-v1'::text) THEN 'supplier'::text
                    WHEN (p.operational_state = 'wait_for_client'::text) THEN 'client'::text
                    ELSE 'reply'::text
                END AS waiting_on,
                CASE
                    WHEN (p.operational_state_source = 'supplier-wait-auto-v1'::text) THEN 'Në pritje të furnitorit.'::text
                    WHEN (p.operational_state = 'wait_for_client'::text) THEN 'Në pritje të klientit.'::text
                    ELSE 'Në pritje të palës tjetër.'::text
                END AS waiting_reason,
            NULL::date AS due_date,
            false AS is_overdue,
            0 AS days_overdue,
            'operational_state'::text AS source,
            p.operational_state_source AS source_ref,
            NULL::text AS priority,
            COALESCE(p.operational_state_at, p.updated_at, p.created_at) AS created_at,
            p.operational_state,
            p.operational_state_at,
            p.operational_state_source,
            p.pipeline_stage,
            p.last_activity_at,
            p.last_email_at,
            (1)::bigint AS rn
           FROM open_projects p
          WHERE (((p.operational_state = 'wait_for_client'::text) OR (p.operational_state_source = 'supplier-wait-auto-v1'::text)) AND (NOT (EXISTS ( SELECT 1
                   FROM task_waits tw
                  WHERE (tw.project_id = p.id)))))
        )
 SELECT task_waits.task_id,
    task_waits.project_id,
    task_waits.project_name,
    task_waits.client,
    task_waits.waiting_on,
    task_waits.waiting_reason,
    task_waits.due_date,
    task_waits.is_overdue,
    task_waits.days_overdue,
    task_waits.source,
    task_waits.source_ref,
    task_waits.priority,
    task_waits.created_at,
    task_waits.operational_state,
    task_waits.operational_state_at,
    task_waits.operational_state_source,
    task_waits.pipeline_stage,
    task_waits.last_activity_at,
    task_waits.last_email_at
   FROM task_waits
UNION ALL
 SELECT state_waits.task_id,
    state_waits.project_id,
    state_waits.project_name,
    state_waits.client,
    state_waits.waiting_on,
    state_waits.waiting_reason,
    state_waits.due_date,
    state_waits.is_overdue,
    state_waits.days_overdue,
    state_waits.source,
    state_waits.source_ref,
    state_waits.priority,
    state_waits.created_at,
    state_waits.operational_state,
    state_waits.operational_state_at,
    state_waits.operational_state_source,
    state_waits.pipeline_stage,
    state_waits.last_activity_at,
    state_waits.last_email_at
   FROM state_waits;


ALTER VIEW public.pppp_home_waiting_projects_v1 OWNER TO postgres;

