--
-- Name: pppp_krpp_opportunity_layers_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_krpp_opportunity_layers_v1 WITH (security_invoker='true') AS
 WITH ranked AS (
         SELECT t.id,
            t.created_at,
            t.updated_at,
            t.first_seen_at,
            t.last_seen_at,
            t.source_key,
            t.procurement_no,
            t.publication_no,
            t.authority,
            t.title,
            t.document_type,
            t.fpp,
            t.fpp_description,
            t.contract_type,
            t.contract_value_band,
            t.procedure,
            t.estimated_value,
            t.currency,
            t.deadline,
            t.published_date,
            t.is_retender,
            t.category,
            t.relevance_score,
            t.match_reasons,
            t.status,
            t.project_id,
            t.source_url,
            t.detail_url,
            t.payload,
            row_number() OVER (PARTITION BY COALESCE(NULLIF(t.procurement_no, ''::text), t.source_key) ORDER BY COALESCE(t.published_date, (t.first_seen_at)::date) DESC, t.first_seen_at DESC, t.created_at DESC, t.id DESC) AS identity_rank
           FROM public.kek_tender_watch t
          WHERE (upper(COALESCE((t.payload ->> 'source'::text), ''::text)) = 'KRPP'::text)
        )
 SELECT id,
    created_at,
    updated_at,
    first_seen_at,
    last_seen_at,
    source_key,
    procurement_no,
    publication_no,
    authority,
    title,
    document_type,
    fpp,
    fpp_description,
    contract_type,
    contract_value_band,
    procedure,
    estimated_value,
    currency,
    deadline,
    published_date,
    is_retender,
    category,
    relevance_score,
    match_reasons,
    status,
    project_id,
    source_url,
    detail_url,
    payload,
    (payload ->> 'krpp_relevance_layer'::text) AS relevance_layer
   FROM ranked r
  WHERE ((identity_rank = 1) AND ((payload ->> 'krpp_relevance_layer'::text) = ANY (ARRAY['main'::text, 'review'::text])) AND (COALESCE(status, 'new'::text) <> ALL (ARRAY['ignored'::text, 'closed'::text, 'done'::text, 'dismissed'::text, 'superseded'::text, 'won'::text, 'lost'::text])) AND ((deadline IS NULL) OR (deadline >= CURRENT_DATE)));


ALTER VIEW public.pppp_krpp_opportunity_layers_v1 OWNER TO postgres;

--
-- Name: pppp_material_trade_followup_due_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_material_trade_followup_due_v1 WITH (security_invoker='true') AS
 SELECT q.id AS first_queue_id,
    q.source_record_id AS target_id,
    q.recipient_email,
    q.recipient_name,
    q.contact_role,
    q.company_name,
    q.sent_at,
    (q.sent_at + '7 days'::interval) AS followup_due_at
   FROM (public.pppp_outbound_queue_v1 q
     JOIN public.pppp_dach_steel_targets_v1 t ON ((t.id = q.source_record_id)))
  WHERE ((q.source = 'DACH_STEEL_BUYER'::text) AND (q.touch_no = 1) AND (q.sent_at IS NOT NULL) AND (q.replied_at IS NULL) AND (q.sent_at <= (now() - '7 days'::interval)) AND (t.target_status <> ALL (ARRAY['closed'::text, 'rejected'::text, 'project_promoted'::text])) AND (NOT (EXISTS ( SELECT 1
           FROM public.pppp_outbound_queue_v1 f
          WHERE ((f.source = 'DACH_STEEL_BUYER'::text) AND (f.source_record_id = q.source_record_id) AND (f.touch_no = 2) AND (lower(f.recipient_email) = lower(q.recipient_email)))))));


ALTER VIEW public.pppp_material_trade_followup_due_v1 OWNER TO postgres;

