--
-- Name: pppp_opportunity_action_queue_v2; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_opportunity_action_queue_v2 WITH (security_invoker='true') AS
 SELECT a.id,
    a.tender_watch_id,
    a.project_id,
    a.action_key,
    a.action_type,
    a.route,
    a.status,
    a.priority,
    a.due_date,
    a.target_company,
    a.target_email,
    a.subject_hint,
    a.draft_brief,
    a.payload,
    a.created_at,
    a.updated_at,
    t.title AS tender_title,
    t.authority,
    t.procurement_no,
    t.publication_no,
    t.deadline,
    t.relevance_score,
    upper(COALESCE((t.payload ->> 'source'::text), 'KRPP'::text)) AS source,
    COALESCE((t.payload ->> 'opportunity_route'::text), a.route) AS opportunity_route,
    COALESCE((t.payload ->> 'opportunity_gate'::text), 'unassessed'::text) AS opportunity_gate,
    (t.payload -> 'dossier_analysis'::text) AS dossier_analysis
   FROM (public.pppp_opportunity_actions a
     JOIN public.kek_tender_watch t ON ((t.id = a.tender_watch_id)))
  WHERE (a.status <> ALL (ARRAY['background'::text, 'resolved'::text, 'closed'::text, 'done'::text, 'superseded'::text]));


ALTER VIEW public.pppp_opportunity_action_queue_v2 OWNER TO postgres;

