CREATE TABLE public.pppp_outbound_policy_v1 (
    id text DEFAULT 'global'::text NOT NULL,
    starts_on date DEFAULT '2026-09-21'::date NOT NULL,
    timezone text DEFAULT 'Europe/Belgrade'::text NOT NULL,
    daily_limit integer DEFAULT 50 NOT NULL,
    day_start time without time zone DEFAULT '08:00:00'::time without time zone NOT NULL,
    day_end time without time zone DEFAULT '17:00:00'::time without time zone NOT NULL,
    min_gap_minutes integer DEFAULT 5 NOT NULL,
    planned_gap_minutes integer DEFAULT 10 NOT NULL,
    max_per_domain_per_day integer DEFAULT 1 NOT NULL,
    recipient_cooldown_days integer DEFAULT 30 NOT NULL,
    domain_cooldown_days integer DEFAULT 14 NOT NULL,
    send_enabled boolean DEFAULT false NOT NULL,
    human_send_required boolean DEFAULT true NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pppp_outbound_policy_v1_check CHECK ((planned_gap_minutes >= min_gap_minutes)),
    CONSTRAINT pppp_outbound_policy_v1_daily_limit_check CHECK (((daily_limit >= 1) AND (daily_limit <= 200))),
    CONSTRAINT pppp_outbound_policy_v1_domain_cooldown_days_check CHECK ((domain_cooldown_days >= 1)),
    CONSTRAINT pppp_outbound_policy_v1_human_send_required_check CHECK ((human_send_required = true)),
    CONSTRAINT pppp_outbound_policy_v1_max_per_domain_per_day_check CHECK ((max_per_domain_per_day >= 1)),
    CONSTRAINT pppp_outbound_policy_v1_min_gap_minutes_check CHECK ((min_gap_minutes >= 5)),
    CONSTRAINT pppp_outbound_policy_v1_recipient_cooldown_days_check CHECK ((recipient_cooldown_days >= 1)),
    CONSTRAINT pppp_outbound_policy_v1_singleton_chk CHECK ((id = 'global'::text))
);


