--
-- Name: pppp_opportunity_communication_state_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_opportunity_communication_state_v1 WITH (security_invoker='true') AS
 WITH policy AS (
         SELECT COALESCE(pppp_outbound_policy_v1.recipient_cooldown_days, 30) AS recipient_days
           FROM public.pppp_outbound_policy_v1
          WHERE (pppp_outbound_policy_v1.id = 'global'::text)
        ), actions AS (
         SELECT a_1.id AS action_id,
            a_1.tender_watch_id,
            lower(btrim(COALESCE(a_1.target_email, ''::text))) AS target_email,
            lower(COALESCE(public.pppp_outbound_domain_v1(a_1.target_email, NULL::text), ''::text)) AS target_domain
           FROM public.pppp_opportunity_actions a_1
          WHERE (a_1.status <> ALL (ARRAY['background'::text, 'resolved'::text, 'closed'::text, 'done'::text, 'superseded'::text]))
        ), outgoing AS (
         SELECT a_1.action_id,
            pe.gmail_message_id,
            pe.gmail_thread_id,
            pe.gmail_url,
            pe.subject,
            pe.sent_at,
            'explicit_tender'::text AS match_type,
            row_number() OVER (PARTITION BY a_1.action_id ORDER BY pe.sent_at DESC NULLS LAST, pe.id DESC) AS rn
           FROM (actions a_1
             JOIN public.project_emails pe ON (((pe.tender_watch_id = a_1.tender_watch_id) AND (lower(COALESCE(pe.direction, ''::text)) = 'outgoing'::text) AND (pe.sent_at IS NOT NULL) AND (lower(COALESCE(pe.from_email, ''::text)) ~~ '%@prissteel.com'::text))))
        ), incoming AS (
         SELECT a_1.action_id,
            pe.gmail_message_id,
            pe.gmail_thread_id,
            pe.gmail_url,
            pe.subject,
            pe.sent_at,
            'explicit_tender'::text AS match_type,
            row_number() OVER (PARTITION BY a_1.action_id ORDER BY pe.sent_at DESC NULLS LAST, pe.id DESC) AS rn
           FROM (actions a_1
             JOIN public.project_emails pe ON (((pe.tender_watch_id = a_1.tender_watch_id) AND (lower(COALESCE(pe.direction, ''::text)) = 'incoming'::text) AND (pe.sent_at IS NOT NULL) AND (lower(COALESCE(pe.from_email, ''::text)) !~~ '%@prissteel.com'::text))))
        )
 SELECT a.action_id,
    a.tender_watch_id,
    a.target_email,
    a.target_domain,
    o.sent_at AS last_outgoing_at,
    o.gmail_message_id AS last_outgoing_message_id,
    o.gmail_thread_id AS last_outgoing_thread_id,
    o.gmail_url AS last_outgoing_gmail_url,
    o.subject AS last_outgoing_subject,
    o.match_type AS outgoing_match_type,
    i.sent_at AS last_incoming_at,
    i.gmail_message_id AS last_incoming_message_id,
    i.gmail_thread_id AS last_incoming_thread_id,
    i.gmail_url AS last_incoming_gmail_url,
    i.subject AS last_incoming_subject,
    i.match_type AS incoming_match_type,
        CASE
            WHEN ((i.sent_at IS NOT NULL) AND (o.sent_at IS NOT NULL) AND (i.sent_at > o.sent_at)) THEN 'replied'::text
            WHEN ((o.sent_at IS NOT NULL) AND (o.sent_at >= (now() - make_interval(days => COALESCE(( SELECT policy.recipient_days
               FROM policy), 30))))) THEN 'waiting'::text
            WHEN (o.sent_at IS NOT NULL) THEN 'contacted_history'::text
            ELSE 'new'::text
        END AS communication_state,
        CASE
            WHEN ((i.sent_at IS NOT NULL) AND (o.sent_at IS NOT NULL) AND (i.sent_at > o.sent_at)) THEN i.sent_at
            ELSE o.sent_at
        END AS communication_at,
        CASE
            WHEN ((i.sent_at IS NOT NULL) AND (o.sent_at IS NOT NULL) AND (i.sent_at > o.sent_at)) THEN i.gmail_url
            ELSE o.gmail_url
        END AS communication_gmail_url,
        CASE
            WHEN ((i.sent_at IS NOT NULL) AND (o.sent_at IS NOT NULL) AND (i.sent_at > o.sent_at)) THEN i.gmail_thread_id
            ELSE o.gmail_thread_id
        END AS communication_thread_id
   FROM ((actions a
     LEFT JOIN outgoing o ON (((o.action_id = a.action_id) AND (o.rn = 1))))
     LEFT JOIN incoming i ON (((i.action_id = a.action_id) AND (i.rn = 1))));


ALTER VIEW public.pppp_opportunity_communication_state_v1 OWNER TO postgres;

