CREATE VIEW public.pppp_outbound_review_v1 WITH (security_invoker='true') AS
 SELECT id,
    source,
    touch_no,
    source_key,
    tender_watch_id,
    project_key,
    project_title,
    company_name,
    company_domain,
    recipient_email,
    recipient_name,
    contact_role,
    relevance_score,
    priority_score,
    gmail_draft_id,
    gmail_draft_message_id,
    gmail_thread_id,
    status,
    suppression_reason,
    planned_date,
    planned_at,
    planned_rank,
    approved_for_send,
    human_send_required,
    sent_at,
    replied_at,
    bounced_at,
    source_updated_at,
    updated_at,
    count(*) OVER (PARTITION BY (lower(recipient_email))) AS same_recipient_candidates,
    count(*) OVER (PARTITION BY (lower(COALESCE(company_domain, ''::text)))) AS same_domain_candidates
   FROM public.pppp_outbound_queue_v1 q
  ORDER BY
        CASE status
            WHEN 'planned'::text THEN 1
            WHEN 'candidate'::text THEN 2
            WHEN 'suppressed'::text THEN 3
            ELSE 9
        END, planned_date, planned_rank, priority_score DESC, updated_at DESC;


ALTER VIEW public.pppp_outbound_review_v1 OWNER TO postgres;

--
-- Name: pppp_outgoing_invoice_milestones_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_outgoing_invoice_milestones_v1 WITH (security_invoker='true') AS
 WITH won_offers AS (
         SELECT d.id AS offer_id,
            d.doc_nr AS offer_doc_nr,
            d.project_id,
            d.project AS offer_project,
            d.client,
            COALESCE(d.total_amount, d.total_eur) AS offer_total,
            upper(COALESCE(NULLIF(d.currency, ''::text), 'EUR'::text)) AS currency,
            d.exchange_rate_to_eur,
            d.payment_plan,
            d.offer_state,
            d.created_at AS offer_created_at,
            p.name AS project_name,
            p.status AS project_status,
            p.pipeline_stage,
            p.operational_state,
            public.pppp_project_delivery_date_v1(d.project_id) AS delivery_date
           FROM (public.documents_registry d
             JOIN public.projects p ON ((p.id = d.project_id)))
          WHERE ((d.series = 'QUO'::text) AND (lower(COALESCE(d.followup_status, ''::text)) = 'won'::text) AND (jsonb_typeof(d.payment_plan) = 'array'::text) AND (jsonb_array_length(d.payment_plan) > 0) AND (COALESCE(d.total_amount, d.total_eur) > (0)::numeric))
        ), expanded AS (
         SELECT o.offer_id,
            o.offer_doc_nr,
            o.project_id,
            o.offer_project,
            o.client,
            o.offer_total,
            o.currency,
            o.exchange_rate_to_eur,
            o.payment_plan,
            o.offer_state,
            o.offer_created_at,
            o.project_name,
            o.project_status,
            o.pipeline_stage,
            o.operational_state,
            o.delivery_date,
            ((m.ordinality - 1))::integer AS milestone_index,
            lower(btrim(COALESCE((m.item ->> 'ev'::text), 'milestone'::text))) AS milestone_event,
            COALESCE(NULLIF(btrim((m.item ->> 'label'::text)), ''::text), NULLIF(btrim((m.item ->> 'ev'::text)), ''::text), ('Milestone '::text || (m.ordinality)::text)) AS milestone_label,
                CASE
                    WHEN (COALESCE((m.item ->> 'pct'::text), ''::text) ~ '^\s*[0-9]+([\.,][0-9]+)?\s*$'::text) THEN (replace(btrim((m.item ->> 'pct'::text)), ','::text, '.'::text))::numeric
                    ELSE NULL::numeric
                END AS milestone_pct,
                CASE
                    WHEN (COALESCE((m.item ->> 'days'::text), ''::text) ~ '^\s*[0-9]+\s*$'::text) THEN (btrim((m.item ->> 'days'::text)))::integer
                    ELSE 0
                END AS payment_days
           FROM (won_offers o
             CROSS JOIN LATERAL jsonb_array_elements(o.payment_plan) WITH ORDINALITY m(item, ordinality))
        ), priced AS (
         SELECT e.offer_id,
            e.offer_doc_nr,
            e.project_id,
            e.offer_project,
            e.client,
            e.offer_total,
            e.currency,
            e.exchange_rate_to_eur,
            e.payment_plan,
            e.offer_state,
            e.offer_created_at,
            e.project_name,
            e.project_status,
            e.pipeline_stage,
            e.operational_state,
            e.delivery_date,
            e.milestone_index,
            e.milestone_event,
            e.milestone_label,
            e.milestone_pct,
            e.payment_days,
                CASE
                    WHEN (e.milestone_pct IS NOT NULL) THEN round(((e.offer_total * e.milestone_pct) / 100.0), 2)
                    ELSE NULL::numeric
                END AS milestone_amount
           FROM expanded e
        ), ranked AS (
         SELECT p.offer_id,
            p.offer_doc_nr,
            p.project_id,
            p.offer_project,
            p.client,
            p.offer_total,
            p.currency,
            p.exchange_rate_to_eur,
            p.payment_plan,
            p.offer_state,
            p.offer_created_at,
            p.project_name,
            p.project_status,
            p.pipeline_stage,
            p.operational_state,
            p.delivery_date,
            p.milestone_index,
            p.milestone_event,
            p.milestone_label,
            p.milestone_pct,
            p.payment_days,
            p.milestone_amount,
            row_number() OVER (PARTITION BY p.offer_id, p.milestone_amount ORDER BY p.milestone_index) AS same_amount_rank
           FROM priced p
        ), invoice_mapped AS (
         SELECT r.offer_id,
            r.offer_doc_nr,
            r.project_id,
            r.offer_project,
            r.client,
            r.offer_total,
            r.currency,
            r.exchange_rate_to_eur,
            r.payment_plan,
            r.offer_state,
            r.offer_created_at,
            r.project_name,
            r.project_status,
            r.pipeline_stage,
            r.operational_state,
            r.delivery_date,
            r.milestone_index,
            r.milestone_event,
            r.milestone_label,
            r.milestone_pct,
            r.payment_days,
            r.milestone_amount,
            r.same_amount_rank,
            COALESCE(di.id, li.id) AS invoice_id,
            COALESCE(di.invoice_nr, li.invoice_nr) AS invoice_nr,
            COALESCE(di.paid, li.paid) AS invoice_paid,
            COALESCE(di.paid_date, li.paid_date) AS invoice_paid_date,
            COALESCE(di.date, li.date) AS invoice_date
           FROM ((ranked r
             LEFT JOIN LATERAL ( SELECT i.id,
                    i.invoice_nr,
                    i.paid,
                    i.paid_date,
                    i.date
                   FROM public.invoices_out i
                  WHERE ((i.source_offer_id = r.offer_id) AND (i.source_milestone_index = r.milestone_index))
                  ORDER BY i.created_at DESC
                 LIMIT 1) di ON (true))
             LEFT JOIN LATERAL ( SELECT i.id,
                    i.invoice_nr,
                    i.paid,
                    i.paid_date,
                    i.date
                   FROM public.invoices_out i
                  WHERE ((di.id IS NULL) AND (i.project_id = r.project_id) AND (i.source_offer_id IS NULL) AND (r.milestone_amount IS NOT NULL) AND (abs((COALESCE(i.total_price, i.gross_amount, i.net_amount, (0)::numeric) - r.milestone_amount)) <= 0.01))
                  ORDER BY i.created_at, i.id
                 OFFSET GREATEST((r.same_amount_rank - 1), (0)::bigint)
                 LIMIT 1) li ON (true))
        ), evaluated AS (
         SELECT m.offer_id,
            m.offer_doc_nr,
            m.project_id,
            m.offer_project,
            m.client,
            m.offer_total,
            m.currency,
            m.exchange_rate_to_eur,
            m.payment_plan,
            m.offer_state,
            m.offer_created_at,
            m.project_name,
            m.project_status,
            m.pipeline_stage,
            m.operational_state,
            m.delivery_date,
            m.milestone_index,
            m.milestone_event,
            m.milestone_label,
            m.milestone_pct,
            m.payment_days,
            m.milestone_amount,
            m.same_amount_rank,
            m.invoice_id,
            m.invoice_nr,
            m.invoice_paid,
            m.invoice_paid_date,
            m.invoice_date,
            (EXISTS ( SELECT 1
                   FROM invoice_mapped prior
                  WHERE ((prior.offer_id = m.offer_id) AND (prior.milestone_index < m.milestone_index) AND (prior.invoice_id IS NULL)))) AS prior_invoice_missing
           FROM invoice_mapped m
        ), stated AS (
         SELECT e.offer_id,
            e.offer_doc_nr,
            e.project_id,
            e.offer_project,
            e.client,
            e.offer_total,
            e.currency,
            e.exchange_rate_to_eur,
            e.payment_plan,
            e.offer_state,
            e.offer_created_at,
            e.project_name,
            e.project_status,
            e.pipeline_stage,
            e.operational_state,
            e.delivery_date,
            e.milestone_index,
            e.milestone_event,
            e.milestone_label,
            e.milestone_pct,
            e.payment_days,
            e.milestone_amount,
            e.same_amount_rank,
            e.invoice_id,
            e.invoice_nr,
            e.invoice_paid,
            e.invoice_paid_date,
            e.invoice_date,
            e.prior_invoice_missing,
                CASE
                    WHEN (e.invoice_id IS NOT NULL) THEN 'invoiced'::text
                    WHEN ((e.milestone_pct IS NULL) OR (COALESCE(e.milestone_amount, (0)::numeric) <= (0)::numeric)) THEN 'invalid'::text
                    WHEN e.prior_invoice_missing THEN 'waiting_previous_invoice'::text
                    WHEN ((e.milestone_index = 0) AND ((lower(COALESCE(e.project_status, ''::text)) = ANY (ARRAY['fituar'::text, 'won'::text])) OR (e.operational_state = 'execution'::text))) THEN 'review'::text
                    WHEN ((e.milestone_event ~ '(before.*del|before_del|pred.*ispor|vor.*liefer)'::text) AND (e.delivery_date IS NOT NULL) AND (e.delivery_date <= (CURRENT_DATE + 14))) THEN 'review'::text
                    WHEN ((e.milestone_event ~ '(after.*del|after_del|nakon.*ispor|nach.*liefer)'::text) AND (e.delivery_date IS NOT NULL) AND (e.delivery_date <= CURRENT_DATE)) THEN 'review'::text
                    ELSE 'pending_event'::text
                END AS readiness
           FROM evaluated e
        )
 SELECT s.offer_id,
    s.offer_doc_nr,
    s.project_id,
    s.project_name,
    s.client,
    s.project_status,
    s.pipeline_stage,
    s.operational_state,
    s.offer_total,
    s.currency,
    s.exchange_rate_to_eur,
    s.milestone_index,
    s.milestone_event,
    s.milestone_label,
    s.milestone_pct,
    s.milestone_amount,
    s.payment_days,
    s.delivery_date,
    s.invoice_id,
    s.invoice_nr,
    s.invoice_paid,
    s.invoice_paid_date,
    s.invoice_date,
    ((('outgoing:'::text || (s.offer_id)::text) || ':milestone:'::text) || (s.milestone_index)::text) AS candidate_key,
    s.readiness,
        CASE
            WHEN (s.readiness = 'invoiced'::text) THEN 'Milestone already invoiced.'::text
            WHEN (s.readiness = 'invalid'::text) THEN 'Milestone percentage or amount is invalid and requires data review.'::text
            WHEN (s.readiness = 'waiting_previous_invoice'::text) THEN 'A prior quotation milestone must be invoiced first.'::text
            WHEN ((s.readiness = 'review'::text) AND (s.milestone_index = 0)) THEN 'Initial/order milestone of a won quotation is ready for human invoice approval.'::text
            WHEN ((s.readiness = 'review'::text) AND (s.milestone_event ~ '(before.*del|before_del|pred.*ispor|vor.*liefer)'::text)) THEN 'Confirmed delivery is within 14 days; milestone is ready for human invoice approval.'::text
            WHEN ((s.readiness = 'review'::text) AND (s.milestone_event ~ '(after.*del|after_del|nakon.*ispor|nach.*liefer)'::text)) THEN 'Confirmed delivery date has been reached; milestone is ready for human invoice approval.'::text
            WHEN ((s.milestone_event ~ '(before.*del|before_del|pred.*ispor|vor.*liefer)'::text) AND (s.delivery_date IS NOT NULL)) THEN (('Waiting until 14 days before confirmed delivery ('::text || (s.delivery_date)::text) || ').'::text)
            WHEN ((s.milestone_event ~ '(after.*del|after_del|nakon.*ispor|nach.*liefer)'::text) AND (s.delivery_date IS NOT NULL)) THEN (('Waiting until confirmed delivery date ('::text || (s.delivery_date)::text) || ').'::text)
            WHEN (s.delivery_date IS NULL) THEN 'Waiting for a confirmed delivery/transport date or explicit operator trigger.'::text
            ELSE 'Waiting for the milestone event.'::text
        END AS readiness_reason,
    ic.id AS candidate_id,
    ic.status AS candidate_status,
    ic.canonical_invoice_out_id
   FROM (stated s
     LEFT JOIN public.invoice_candidates ic ON (((ic.candidate_key = ((('outgoing:'::text || (s.offer_id)::text) || ':milestone:'::text) || (s.milestone_index)::text)) AND (ic.direction = 'outgoing'::text))));


ALTER VIEW public.pppp_outgoing_invoice_milestones_v1 OWNER TO postgres;

--
-- Name: pppp_outreach_pattern_library_v2; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_outreach_pattern_library_v2 WITH (security_invoker='true') AS
 SELECT company_reference,
    outreach_motion,
    reusable_pattern,
    lesson
   FROM ( VALUES ('RSB'::text,'material_buyer'::text,'Named purchasing contact + certifications/capacity + DAP question'::text,'A concrete first exchange can progress into real RFQs.'::text), ('KROPP'::text,'material_buyer'::text,'Named Einkauf contact + project-specific basis and optimized alternative'::text,'Specific scope and a commercial option create a useful buying conversation.'::text), ('B+H Bau'::text,'future_supplier_qualification'::text,'Named commercial contact + awarded project context + low-friction future-supplier CTA'::text,'When the current package is already in negotiation, switch to future qualification.'::text), ('ROLEFF'::text,'awarded_project_gc'::text,'Named decision-maker + verified project fact + precise steel relevance'::text,'Project context must be verified before requesting a conversation.'::text)) v(company_reference, outreach_motion, reusable_pattern, lesson);


ALTER VIEW public.pppp_outreach_pattern_library_v2 OWNER TO postgres;

--
-- Name: pppp_outreach_v2_deliverability_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_outreach_v2_deliverability_v1 WITH (security_invoker='true') AS
 SELECT
        CASE
            WHEN (source = 'dach_steel_target'::text) THEN 'material_trade'::text
            ELSE 'ted_awarded'::text
        END AS channel,
    outreach_engine_version,
    count(*) AS total_records,
    count(*) FILTER (WHERE (sent_at IS NOT NULL)) AS sent,
    count(*) FILTER (WHERE (delivered_at IS NOT NULL)) AS delivered,
    count(*) FILTER (WHERE (bounced_at IS NOT NULL)) AS bounced,
    count(*) FILTER (WHERE (replied_at IS NOT NULL)) AS replied,
    round(((100.0 * (count(*) FILTER (WHERE (bounced_at IS NOT NULL)))::numeric) / (NULLIF(count(*) FILTER (WHERE (sent_at IS NOT NULL)), 0))::numeric), 1) AS bounce_rate_pct,
    round(((100.0 * (count(*) FILTER (WHERE (replied_at IS NOT NULL)))::numeric) / (NULLIF(count(*) FILTER (WHERE (delivered_at IS NOT NULL)), 0))::numeric), 1) AS reply_rate_pct
   FROM public.pppp_outbound_queue_v1
  GROUP BY
        CASE
            WHEN (source = 'dach_steel_target'::text) THEN 'material_trade'::text
            ELSE 'ted_awarded'::text
        END, outreach_engine_version;


ALTER VIEW public.pppp_outreach_v2_deliverability_v1 OWNER TO postgres;

--
-- Name: pppp_outreach_v2_workbench_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_outreach_v2_workbench_v1 WITH (security_invoker='true') AS
 SELECT 'material_trade'::text AS channel,
    'dach_target'::text AS source_type,
    t.id AS source_id,
    t.source_key,
    t.company_name,
    COALESCE(t.why_now, t.buyer_type) AS why_company,
    COALESCE(t.procurement_timing, t.why_now) AS commercial_signal,
    t.project_title,
    t.canonical_contact_email AS contact_email,
    t.canonical_contact_name AS contact_name,
    t.canonical_contact_role AS contact_role,
    t.contact_tier,
    t.contact_quality_score,
    t.company_fit_score,
    t.commercial_timing_score,
    t.message_evidence_score,
    t.outreach_readiness_score,
    t.outreach_motion,
    t.timing_classification,
    t.workflow_state,
    t.personalization_facts,
    t.readiness_reasons,
    t.outreach_engine_version,
    t.reply_classification,
    t.reply_evidence,
    q.sent_at AS last_contact_at,
    q.replied_at,
    q.bounced_at,
    q.gmail_thread_id,
    t.project_id,
    COALESCE(t.next_action,
        CASE
            WHEN (t.workflow_state = 'strong_company_contact_gap'::text) THEN 'Find or improve procurement contact'::text
            WHEN (t.workflow_state = 'ready_for_outreach'::text) THEN 'Review evidence-led draft'::text
            WHEN (t.workflow_state = 'thread_review'::text) THEN 'Open Gmail thread'::text
            ELSE 'Research evidence and timing'::text
        END) AS next_action,
    true AS human_send_required
   FROM (public.pppp_dach_steel_targets_v1 t
     LEFT JOIN LATERAL ( SELECT oq.sent_at,
            oq.replied_at,
            oq.bounced_at,
            oq.gmail_thread_id
           FROM public.pppp_outbound_queue_v1 oq
          WHERE (oq.source_record_id = t.id)
          ORDER BY COALESCE(oq.sent_at, oq.updated_at, oq.created_at) DESC
         LIMIT 1) q ON (true))
UNION ALL
 SELECT 'ted_awarded'::text AS channel,
    'opportunity_action'::text AS source_type,
    a.id AS source_id,
    a.action_key AS source_key,
    a.target_company AS company_name,
    COALESCE((a.payload ->> 'why_company'::text), a.draft_brief) AS why_company,
    COALESCE((a.payload ->> 'commercial_signal'::text), a.subject_hint) AS commercial_signal,
    (a.payload ->> 'project_title'::text) AS project_title,
    a.target_email AS contact_email,
    a.target_name AS contact_name,
    a.target_role AS contact_role,
    a.contact_tier,
    a.contact_quality_score,
    a.company_fit_score,
    a.commercial_timing_score,
    a.message_evidence_score,
    a.outreach_readiness_score,
    a.outreach_motion,
    a.timing_classification,
    a.workflow_state,
    a.personalization_facts,
    a.readiness_reasons,
    a.outreach_engine_version,
    a.reply_classification,
    a.reply_evidence,
    r.sent_at AS last_contact_at,
        CASE
            WHEN (r.status = 'replied'::text) THEN r.updated_at
            ELSE NULL::timestamp with time zone
        END AS replied_at,
    NULL::timestamp with time zone AS bounced_at,
    r.gmail_thread_id,
    a.project_id,
        CASE
            WHEN (a.workflow_state = 'strong_company_contact_gap'::text) THEN 'Find or improve procurement contact'::text
            WHEN (a.workflow_state = 'ready_for_outreach'::text) THEN 'Review evidence-led draft'::text
            WHEN (r.gmail_thread_id IS NOT NULL) THEN 'Open Gmail thread'::text
            WHEN (a.timing_classification = 'future_supplier_qualification'::text) THEN 'Qualify for future supplier list'::text
            ELSE 'Research evidence and timing'::text
        END AS next_action,
    true AS human_send_required
   FROM (public.pppp_opportunity_actions a
     LEFT JOIN LATERAL ( SELECT x.sent_at,
            x.updated_at,
            x.status,
            x.gmail_thread_id
           FROM public.pppp_opportunity_outreach_registry_v1 x
          WHERE (x.action_id = a.id)
          ORDER BY COALESCE(x.sent_at, x.updated_at, x.created_at) DESC
         LIMIT 1) r ON (true))
  WHERE (a.action_type = ANY (ARRAY['gc_contact_research'::text, 'gc_project_outreach_draft'::text, 'producer_contact_research'::text, 'producer_capacity_outreach_draft'::text, 'consortium_member_review'::text, 'consortium_project_outreach_draft'::text, 'general_project_outreach_draft'::text, 'manual_tender_outreach_draft'::text]));


ALTER VIEW public.pppp_outreach_v2_workbench_v1 OWNER TO postgres;

--
-- Name: pppp_outreach_v2_funnel_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_outreach_v2_funnel_v1 WITH (security_invoker='true') AS
 SELECT channel,
    outreach_engine_version,
    count(*) AS discovered,
    count(*) FILTER (WHERE (company_fit_score >= 65)) AS qualified,
    count(*) FILTER (WHERE (contact_email IS NOT NULL)) AS contact_found,
    count(*) FILTER (WHERE (contact_tier = ANY (ARRAY['A'::text, 'B'::text]))) AS named_decision_maker,
    count(*) FILTER (WHERE (workflow_state = 'ready_for_outreach'::text)) AS ready_for_outreach,
    count(*) FILTER (WHERE (workflow_state = 'draft_created'::text)) AS drafted,
    count(*) FILTER (WHERE (last_contact_at IS NOT NULL)) AS sent,
    count(*) FILTER (WHERE ((last_contact_at IS NOT NULL) AND (bounced_at IS NULL))) AS delivered,
    count(*) FILTER (WHERE ((replied_at IS NOT NULL) OR (reply_classification IS NOT NULL))) AS replied,
    count(*) FILTER (WHERE (reply_classification = ANY (ARRAY['future_interest'::text, 'meeting_requested'::text]))) AS positive_replies,
    count(*) FILTER (WHERE (reply_classification = 'referral'::text)) AS referrals,
    count(*) FILTER (WHERE (reply_classification = 'rfq_received'::text)) AS rfqs,
    count(*) FILTER (WHERE (project_id IS NOT NULL)) AS projects_created
   FROM public.pppp_outreach_v2_workbench_v1
  GROUP BY channel, outreach_engine_version;


ALTER VIEW public.pppp_outreach_v2_funnel_v1 OWNER TO postgres;

--
-- Name: pppp_outreach_v2_pilot_queue_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_outreach_v2_pilot_queue_v1 WITH (security_invoker='true') AS
 SELECT channel,
    source_type,
    source_id,
    source_key,
    company_name,
    why_company,
    commercial_signal,
    project_title,
    contact_email,
    contact_name,
    contact_role,
    contact_tier,
    contact_quality_score,
    company_fit_score,
    commercial_timing_score,
    message_evidence_score,
    outreach_readiness_score,
    outreach_motion,
    timing_classification,
    workflow_state,
    personalization_facts,
    readiness_reasons,
    outreach_engine_version,
    reply_classification,
    reply_evidence,
    last_contact_at,
    replied_at,
    bounced_at,
    gmail_thread_id,
    project_id,
    next_action,
    human_send_required
   FROM public.pppp_outreach_v2_workbench_v1 w
  WHERE ((outreach_engine_version = 'v2'::text) AND (workflow_state = 'ready_for_outreach'::text) AND (contact_quality_score >= 50) AND (message_evidence_score >= 60) AND (jsonb_array_length(COALESCE(personalization_facts, '[]'::jsonb)) >= 2) AND (last_contact_at IS NULL) AND ((source_type <> 'opportunity_action'::text) OR (EXISTS ( SELECT 1
           FROM ((public.pppp_opportunity_actions a
             JOIN public.kek_tender_watch k ON ((k.id = a.tender_watch_id)))
             CROSS JOIN LATERAL jsonb_array_elements(
                CASE
                    WHEN (jsonb_typeof((k.payload #> '{winner,contact_enrichment,organizations}'::text[])) = 'array'::text) THEN (k.payload #> '{winner,contact_enrichment,organizations}'::text[])
                    ELSE '[]'::jsonb
                END) org(value))
          WHERE ((a.id = w.source_id) AND (lower(regexp_replace(COALESCE((org.value ->> 'name'::text), ''::text), '[^a-z0-9]+'::text, ''::text, 'g'::text)) = lower(regexp_replace(COALESCE(a.target_company, ''::text), '[^a-z0-9]+'::text, ''::text, 'g'::text))) AND (lower(split_part(a.target_email, '@'::text, 2)) = lower(COALESCE(NULLIF((org.value ->> 'domain'::text), ''::text), regexp_replace((org.value ->> 'official_website'::text), '^https?://(www\.)?|/.*$'::text, ''::text, 'g'::text)))))))))
  ORDER BY outreach_readiness_score DESC, company_fit_score DESC
 LIMIT 25;


ALTER VIEW public.pppp_outreach_v2_pilot_queue_v1 OWNER TO postgres;

--
-- Name: VIEW pppp_outreach_v2_pilot_queue_v1; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.pppp_outreach_v2_pilot_queue_v1 IS 'Maximum 25 evidence-ready, contact-qualified prospects. Read-only; draft creation remains an explicit human action and sending is never automatic.';


--
-- Name: pppp_representation_opportunities_v1; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.pppp_representation_opportunities_v1 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_key text NOT NULL,
    project_name text NOT NULL,
    funding_institution text,
    tender_reference text,
    official_source text,
    total_project_value numeric(18,2),
    currency text,
    financing text,
    status text DEFAULT 'pipeline'::text NOT NULL,
    procurement_stage text,
    tender_deadline timestamp with time zone,
    scope text,
    procurement_packages text[] DEFAULT '{}'::text[] NOT NULL,
    qualification_criteria text,
    jv_consortium_rules text,
    mandatory_site_visit boolean,
    bid_guarantee text,
    performance_guarantee text,
    verification_status text DEFAULT 'unknown'::text NOT NULL,
    fact_evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_verified_at timestamp with time zone,
    notes text,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pppp_representation_opportunities_source_url_check CHECK (((official_source IS NULL) OR (official_source ~* '^https?://'::text))),
    CONSTRAINT pppp_representation_opportunities_v1_currency_check CHECK (((currency IS NULL) OR (currency ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT pppp_representation_opportunities_v1_fact_evidence_check CHECK ((jsonb_typeof(fact_evidence) = 'object'::text)),
    CONSTRAINT pppp_representation_opportunities_v1_project_name_check CHECK (((length(btrim(project_name)) >= 1) AND (length(btrim(project_name)) <= 500))),
    CONSTRAINT pppp_representation_opportunities_v1_source_key_check CHECK (((length(btrim(source_key)) >= 1) AND (length(btrim(source_key)) <= 500))),
    CONSTRAINT pppp_representation_opportunities_v1_status_check CHECK ((status = ANY (ARRAY['pipeline'::text, 'approved'::text, 'signed'::text, 'waiting_procurement'::text, 'procurement'::text, 'tender_open'::text, 'partner_search_ready'::text, 'closed'::text]))),
    CONSTRAINT pppp_representation_opportunities_v1_total_project_value_check CHECK (((total_project_value IS NULL) OR (total_project_value >= (0)::numeric))),
    CONSTRAINT pppp_representation_opportunities_v1_verification_status_check CHECK ((verification_status = ANY (ARRAY['unknown'::text, 'review'::text, 'verified'::text])))
);


ALTER TABLE public.pppp_representation_opportunities_v1 OWNER TO postgres;

--
-- Name: TABLE pppp_representation_opportunities_v1; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.pppp_representation_opportunities_v1 IS 'Project/tender opportunity truth for the Representations module. One opportunity may have many candidate companies; no automatic outreach.';


--
-- Name: COLUMN pppp_representation_opportunities_v1.fact_evidence; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.pppp_representation_opportunities_v1.fact_evidence IS 'Per-field evidence object. Each field may carry status confirmed, unknown, or assumption plus source and verified_at. Null/unknown is never a confirmed fact.';


--
-- Name: pppp_partnership_expansion_queue_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_partnership_expansion_queue_v1 WITH (security_invoker='true') AS
 WITH ranked AS (
         SELECT t_1.id,
            t_1.created_at,
            t_1.updated_at,
            t_1.first_seen_at,
            t_1.last_seen_at,
            t_1.source_key,
            t_1.procurement_no,
            t_1.publication_no,
            t_1.authority,
            t_1.title,
            t_1.document_type,
            t_1.fpp,
            t_1.fpp_description,
            t_1.contract_type,
            t_1.contract_value_band,
            t_1.procedure,
            t_1.estimated_value,
            t_1.currency,
            t_1.deadline,
            t_1.published_date,
            t_1.is_retender,
            t_1.category,
            t_1.relevance_score,
            t_1.match_reasons,
            t_1.status,
            t_1.project_id,
            t_1.source_url,
            t_1.detail_url,
            t_1.payload,
            COALESCE(NULLIF(btrim(t_1.procurement_no), ''::text), NULLIF(btrim(t_1.publication_no), ''::text), t_1.source_key) AS canonical_tender_identity,
            row_number() OVER (PARTITION BY COALESCE(NULLIF(btrim(t_1.procurement_no), ''::text), NULLIF(btrim(t_1.publication_no), ''::text), t_1.source_key) ORDER BY t_1.updated_at DESC NULLS LAST, t_1.created_at DESC) AS identity_rank
           FROM public.kek_tender_watch t_1
          WHERE (((t_1.payload ->> 'partnership_expansion_required'::text) = 'true'::text) AND (COALESCE(t_1.status, 'new'::text) <> 'ignored'::text))
        )
 SELECT t.id AS tender_watch_id,
    t.source_key,
    upper(COALESCE((t.payload ->> 'source'::text), 'KRPP'::text)) AS source,
    t.title,
    t.authority,
    t.status AS tender_status,
    t.category,
    t.relevance_score,
    t.estimated_value,
    t.currency,
    t.deadline,
    (t.payload -> 'candidate_business_routes'::text) AS candidate_business_routes,
    (t.payload -> 'partnership_routes'::text) AS partnership_routes,
    (t.payload ->> 'route_screening_status'::text) AS route_screening_status,
    (t.payload ->> 'partnership_expansion_market'::text) AS partnership_expansion_market,
    true AS partnership_expansion_required,
    ro.id AS representation_opportunity_id,
    ro.status AS representation_opportunity_status,
    ro.verification_status AS representation_verification_status,
    t.source_url,
    t.detail_url,
    t.updated_at,
    t.canonical_tender_identity
   FROM (ranked t
     LEFT JOIN public.pppp_representation_opportunities_v1 ro ON ((ro.source_key = ('tenderproc:'::text || t.canonical_tender_identity))))
  WHERE (t.identity_rank = 1);


ALTER VIEW public.pppp_partnership_expansion_queue_v1 OWNER TO postgres;

