CREATE VIEW public.pppp_pristeel_offer_models_v1 WITH (security_invoker='true') AS
 SELECT model_key,
    model_name,
    value_proposition,
    ideal_customer,
    default_low_friction_cta
   FROM ( VALUES ('material_supply'::text,'Steel Material Supply'::text,'Supply of project- or consumption-specific steel material with required certification, optional processing and coordinated DAP logistics.'::text,'Steel buyers, fabricators, OEMs and industrial manufacturers with recurring or project-specific material demand.'::text,'Is this material category handled by you, and would one benchmark position be useful?'::text), ('fabricated_steel_package'::text,'Fabricated Steel Package'::text,'A clearly defined steel package coordinated by PRISTEEL: material procurement, build-to-print fabrication, surface treatment, QA/fabrication documentation, packing and DAP delivery as required.'::text,'General contractors, industrial contractors and project owners with a defined steel scope.'::text,'Is this steel package already fully awarded, or is a clearly defined external package still open?'::text), ('external_production_capacity'::text,'External Production Capacity'::text,'Additional managed fabrication capacity for steel fabricators and manufacturers during peak load, constrained lead times or outsourced packages.'::text,'Steel fabricators and manufacturers that may outsource selected packages or overflow capacity.'::text,'Do you currently outsource selected fabrication packages when internal capacity is constrained?'::text), ('future_supplier_qualification'::text,'Future Supplier Qualification'::text,'Qualification of PRISTEEL as a future material, fabricated-package or managed-capacity source when the current package is already covered.'::text,'Companies with relevant recurring demand where current procurement is already closed or too late.'::text,'Who handles supplier qualification for future steel packages?'::text)) v(model_key, model_name, value_proposition, ideal_customer, default_low_friction_cta);


