-- Name: project_requirements; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.project_requirements (
    id bigint NOT NULL,
    project_id uuid NOT NULL,
    requirement_key text NOT NULL,
    category text NOT NULL,
    value_text text,
    value_json jsonb,
    status text DEFAULT 'confirmed'::text NOT NULL,
    trust_tier text DEFAULT 'text'::text NOT NULL,
    source_type text NOT NULL,
    source_ref text NOT NULL,
    source_name text,
    first_seen timestamp with time zone DEFAULT now() NOT NULL,
    last_seen timestamp with time zone DEFAULT now() NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL
);


ALTER TABLE public.project_requirements OWNER TO postgres;

--
-- Name: pppp_project_requirements_summary_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_project_requirements_summary_v1 WITH (security_invoker='true') AS
 SELECT p.id AS project_id,
    p.name,
    count(r.id) AS requirement_count,
    count(r.id) FILTER (WHERE (r.status = 'review'::text)) AS review_count,
    COALESCE(jsonb_agg(DISTINCT r.value_text) FILTER (WHERE ((r.category = 'standard'::text) AND (r.value_text IS NOT NULL))), '[]'::jsonb) AS standards,
    COALESCE(jsonb_agg(DISTINCT r.value_text) FILTER (WHERE ((r.category = 'execution_class'::text) AND (r.value_text IS NOT NULL))), '[]'::jsonb) AS execution_classes,
    COALESCE(jsonb_agg(DISTINCT r.value_text) FILTER (WHERE ((r.category = 'steel_grade'::text) AND (r.value_text IS NOT NULL))), '[]'::jsonb) AS steel_grades,
    COALESCE(jsonb_agg(DISTINCT r.value_text) FILTER (WHERE ((r.category = 'commercial'::text) AND (r.value_text IS NOT NULL))), '[]'::jsonb) AS commercial_terms,
    COALESCE(jsonb_agg(jsonb_build_object('key', r.requirement_key, 'value', r.value_text, 'value_json', r.value_json, 'status', r.status, 'source', r.source_name, 'source_ref', r.source_ref) ORDER BY r.last_seen DESC) FILTER (WHERE (r.id IS NOT NULL)), '[]'::jsonb) AS requirements
   FROM (public.projects p
     LEFT JOIN public.project_requirements r ON ((r.project_id = p.id)))
  GROUP BY p.id, p.name;


ALTER VIEW public.pppp_project_requirements_summary_v1 OWNER TO postgres;

