--
-- Name: pppp_project_workflow_state_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_project_workflow_state_v1 WITH (security_invoker='true') AS
 WITH evidence AS (
         SELECT p.id AS project_id,
            COALESCE(p.workflow_type,
                CASE
                    WHEN (lower(COALESCE(p.business_type, p.work_model, p.deal_type, ''::text)) ~ '(trading|trade|furniz)'::text) THEN 'steel_trading'::text
                    ELSE NULL::text
                END, 'steel_trading'::text) AS workflow_type,
            p.status,
            p.pipeline_stage,
            p.operational_state,
            (COALESCE(r.rfq_count, (0)::bigint))::integer AS rfq_count,
            (COALESCE(r.rfq_reply_count, (0)::bigint))::integer AS rfq_reply_count,
            (COALESCE(o.supplier_offer_count, (0)::bigint))::integer AS supplier_offer_count,
            (COALESCE(d_1.selected_supplier_count, (0)::bigint))::integer AS selected_supplier_count,
            (COALESCE(q.client_offer_count, (0)::bigint))::integer AS client_offer_count,
            (COALESCE(q.sent_client_offer_count, (0)::bigint))::integer AS sent_client_offer_count,
            (COALESCE(i.invoice_count, (0)::bigint))::integer AS invoice_count,
            (COALESCE(i.paid_invoice_count, (0)::bigint))::integer AS paid_invoice_count
           FROM (((((public.projects p
             LEFT JOIN LATERAL ( SELECT count(*) AS rfq_count,
                    count(*) FILTER (WHERE ((rfq_log.replied_at IS NOT NULL) OR (lower(COALESCE(rfq_log.status, ''::text)) = ANY (ARRAY['replied'::text, 'received'::text])))) AS rfq_reply_count
                   FROM public.rfq_log
                  WHERE (rfq_log.project_id = p.id)) r ON (true))
             LEFT JOIN LATERAL ( SELECT count(*) AS supplier_offer_count
                   FROM public.offers
                  WHERE (offers.project_id = p.id)) o ON (true))
             LEFT JOIN LATERAL ( SELECT count(*) FILTER (WHERE ((lower(COALESCE(project_supplier_decisions.status, 'active'::text)) = 'active'::text) AND (lower(COALESCE(project_supplier_decisions.decision_type, ''::text)) = 'selected_producer'::text))) AS selected_supplier_count
                   FROM public.project_supplier_decisions
                  WHERE (project_supplier_decisions.project_id = p.id)) d_1 ON (true))
             LEFT JOIN LATERAL ( SELECT count(*) AS client_offer_count,
                    count(*) FILTER (WHERE ((COALESCE((documents_registry.offer_state ->> 'sent_at'::text), ''::text) <> ''::text) OR (lower(COALESCE((documents_registry.offer_state ->> 'status'::text), (documents_registry.offer_state ->> 'revision_status'::text), documents_registry.followup_status, ''::text)) ~ '(sent|submitted|issued|delivered|derguar)'::text))) AS sent_client_offer_count
                   FROM public.documents_registry
                  WHERE ((documents_registry.project_id = p.id) AND ((upper(COALESCE(documents_registry.series, ''::text)) = 'QUO'::text) OR (upper(COALESCE(documents_registry.doc_nr, ''::text)) ~~ 'QUO%'::text)))) q ON (true))
             LEFT JOIN LATERAL ( SELECT count(*) AS invoice_count,
                    count(*) FILTER (WHERE ((invoices_out.paid IS TRUE) OR (invoices_out.paid_date IS NOT NULL))) AS paid_invoice_count
                   FROM public.invoices_out
                  WHERE (invoices_out.project_id = p.id)) i ON (true))
        ), derived AS (
         SELECT e.project_id,
            e.workflow_type,
            e.status,
            e.pipeline_stage,
            e.operational_state,
            e.rfq_count,
            e.rfq_reply_count,
            e.supplier_offer_count,
            e.selected_supplier_count,
            e.client_offer_count,
            e.sent_client_offer_count,
            e.invoice_count,
            e.paid_invoice_count,
                CASE
                    WHEN (lower(COALESCE(e.status, ''::text)) ~ '(humbur|lost|cancel|refuz)'::text) THEN 'lost'::text
                    WHEN ((lower(COALESCE(e.status, ''::text)) ~ '(realizuar|mbyllur|closed|arkiv)'::text) OR (e.pipeline_stage = 'closed'::text)) THEN 'closed'::text
                    WHEN ((e.invoice_count > 0) AND (e.paid_invoice_count = e.invoice_count)) THEN 'payment'::text
                    WHEN (e.invoice_count > 0) THEN 'invoice'::text
                    WHEN (e.pipeline_stage = 'delivery'::text) THEN 'delivery'::text
                    WHEN (e.pipeline_stage = 'transport'::text) THEN 'transport'::text
                    WHEN (e.pipeline_stage = ANY (ARRAY['production_control'::text, 'factory_audit'::text, 'procurement'::text])) THEN 'procurement'::text
                    WHEN (e.pipeline_stage = 'supplier_po'::text) THEN 'supplier_po'::text
                    WHEN (e.pipeline_stage = 'customer_po'::text) THEN 'customer_po'::text
                    WHEN ((lower(COALESCE(e.status, ''::text)) ~ '(fituar|won)'::text) OR (lower(COALESCE(e.operational_state, ''::text)) ~ '(execution|ekzekutim)'::text)) THEN 'won'::text
                    WHEN ((e.sent_client_offer_count > 0) AND (e.workflow_type = 'self_tender'::text)) THEN 'application'::text
                    WHEN (e.sent_client_offer_count > 0) THEN 'negotiation'::text
                    WHEN ((e.client_offer_count > 0) AND (e.workflow_type = 'self_tender'::text)) THEN 'dossier'::text
                    WHEN (e.client_offer_count > 0) THEN 'client_offer'::text
                    WHEN ((e.selected_supplier_count > 0) AND (e.workflow_type = 'self_tender'::text)) THEN 'dossier'::text
                    WHEN (e.selected_supplier_count > 0) THEN 'pricing'::text
                    WHEN (e.supplier_offer_count > 0) THEN 'supplier_comparison'::text
                    WHEN (e.rfq_count > 0) THEN 'supplier_rfq'::text
                    WHEN (e.workflow_type = 'eu_award_sales'::text) THEN 'contact'::text
                    WHEN (e.workflow_type = 'self_tender'::text) THEN 'requirements'::text
                    ELSE 'client_rfq'::text
                END AS current_stage
           FROM evidence e
        )
 SELECT project_id,
    workflow_type,
    status,
    pipeline_stage,
    operational_state,
    rfq_count,
    rfq_reply_count,
    supplier_offer_count,
    selected_supplier_count,
    client_offer_count,
    sent_client_offer_count,
    invoice_count,
    paid_invoice_count,
    current_stage,
        CASE current_stage
            WHEN 'opportunity'::text THEN 10
            WHEN 'tender'::text THEN 10
            WHEN 'contact'::text THEN 20
            WHEN 'requirements'::text THEN 20
            WHEN 'client_rfq'::text THEN 30
            WHEN 'supplier_rfq'::text THEN 40
            WHEN 'supplier_comparison'::text THEN 50
            WHEN 'pricing'::text THEN 60
            WHEN 'dossier'::text THEN 60
            WHEN 'client_offer'::text THEN 70
            WHEN 'application'::text THEN 70
            WHEN 'negotiation'::text THEN 80
            WHEN 'won'::text THEN 90
            WHEN 'lost'::text THEN 90
            WHEN 'customer_po'::text THEN 100
            WHEN 'supplier_po'::text THEN 110
            WHEN 'procurement'::text THEN 120
            WHEN 'transport'::text THEN 130
            WHEN 'delivery'::text THEN 140
            WHEN 'invoice'::text THEN 150
            WHEN 'payment'::text THEN 160
            WHEN 'closed'::text THEN 170
            ELSE 0
        END AS stage_order,
        CASE current_stage
            WHEN 'opportunity'::text THEN 'Aprovo Opportunity si Project'::text
            WHEN 'tender'::text THEN 'Shqyrto tenderin dhe vendos'::text
            WHEN 'contact'::text THEN 'Kontrollo kontaktet dhe përgatit emailin'::text
            WHEN 'requirements'::text THEN 'Analizo kërkesat e tenderit'::text
            WHEN 'client_rfq'::text THEN 'Qartëso Client RFQ'::text
            WHEN 'supplier_rfq'::text THEN 'Mblidh ofertat e furnitorëve'::text
            WHEN 'supplier_comparison'::text THEN 'Krahaso dhe aprovo furnitorin'::text
            WHEN 'pricing'::text THEN 'Përgatit çmimin dhe ofertën'::text
            WHEN 'dossier'::text THEN 'Finalizo çmimin dhe dosjen'::text
            WHEN 'client_offer'::text THEN 'Kontrollo dhe dërgo ofertën'::text
            WHEN 'application'::text THEN 'Kontrollo dhe dorëzo aplikimin'::text
            WHEN 'negotiation'::text THEN 'Shqyrto përgjigjen / negociatën'::text
            WHEN 'won'::text THEN 'Regjistro Customer PO'::text
            WHEN 'customer_po'::text THEN 'Përgatit Supplier PO'::text
            WHEN 'supplier_po'::text THEN 'Vazhdo me prokurimin'::text
            WHEN 'procurement'::text THEN 'Vazhdo prodhimin / prokurimin'::text
            WHEN 'transport'::text THEN 'Kontrollo transportin dhe dorëzimin'::text
            WHEN 'delivery'::text THEN 'Konfirmo dorëzimin dhe përgatit faturën'::text
            WHEN 'invoice'::text THEN 'Kontrollo pagesën'::text
            WHEN 'payment'::text THEN 'Mbyll projektin'::text
            WHEN 'lost'::text THEN 'Shiko arsyen dhe historikun'::text
            WHEN 'closed'::text THEN 'Shiko historikun e projektit'::text
            ELSE 'Kontrollo projektin'::text
        END AS next_action_title,
        CASE current_stage
            WHEN 'contact'::text THEN 'communication'::text
            WHEN 'client_offer'::text THEN 'offer'::text
            WHEN 'application'::text THEN 'offer'::text
            WHEN 'negotiation'::text THEN 'communication'::text
            WHEN 'supplier_rfq'::text THEN 'rfq'::text
            WHEN 'supplier_comparison'::text THEN 'comparison'::text
            WHEN 'pricing'::text THEN 'pricing'::text
            WHEN 'dossier'::text THEN 'pricing'::text
            WHEN 'won'::text THEN 'execution'::text
            WHEN 'customer_po'::text THEN 'execution'::text
            WHEN 'supplier_po'::text THEN 'execution'::text
            WHEN 'procurement'::text THEN 'execution'::text
            WHEN 'transport'::text THEN 'execution'::text
            WHEN 'delivery'::text THEN 'execution'::text
            WHEN 'invoice'::text THEN 'finance'::text
            WHEN 'payment'::text THEN 'finance'::text
            WHEN 'lost'::text THEN 'docscomms'::text
            WHEN 'closed'::text THEN 'docscomms'::text
            ELSE 'overview'::text
        END AS next_action_area,
    (current_stage = ANY (ARRAY['supplier_comparison'::text, 'pricing'::text, 'dossier'::text, 'client_offer'::text, 'application'::text, 'negotiation'::text, 'won'::text, 'lost'::text, 'customer_po'::text, 'supplier_po'::text, 'closed'::text])) AS human_gate
   FROM derived d;


ALTER VIEW public.pppp_project_workflow_state_v1 OWNER TO postgres;

