COMMENT ON VIEW public.pppp_project_workflow_state_v1 IS 'Canonical PPPP V2 read model: three entry workflows converge into one supplier, commercial and post-award project flow.';


--
-- Name: pppp_representation_discovery_candidates_v1; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.pppp_representation_discovery_candidates_v1 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid,
    lane text NOT NULL,
    candidate_kind text NOT NULL,
    source_key text NOT NULL,
    source_name text NOT NULL,
    source_url text,
    title text NOT NULL,
    company_name text,
    company_domain text,
    country_code text,
    tender_watch_id uuid,
    opportunity_source_key text,
    score integer DEFAULT 0 NOT NULL,
    reasons text[] DEFAULT '{}'::text[] NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    routing_conflicts text[] DEFAULT '{}'::text[] NOT NULL,
    status text DEFAULT 'new'::text NOT NULL,
    target_id uuid,
    opportunity_id uuid,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    reviewed_at timestamp with time zone,
    reviewed_by uuid,
    review_note text,
    CONSTRAINT pppp_representation_discovery_candidates_v1_country_code_check CHECK (((country_code IS NULL) OR (country_code ~ '^[A-Z]{2}$'::text))),
    CONSTRAINT pppp_representation_discovery_candidates_v1_evidence_check CHECK ((jsonb_typeof(evidence) = 'object'::text)),
    CONSTRAINT pppp_representation_discovery_candidates_v1_lane_check CHECK ((lane = ANY (ARRAY['market_entry'::text, 'consortium_opportunity'::text]))),
    CONSTRAINT pppp_representation_discovery_candidates_v1_score_check CHECK (((score >= 0) AND (score <= 100))),
    CONSTRAINT pppp_representation_discovery_candidates_v1_source_key_check CHECK (((length(btrim(source_key)) >= 3) AND (length(btrim(source_key)) <= 700))),
    CONSTRAINT pppp_representation_discovery_candidates_v1_source_url_check CHECK (((source_url IS NULL) OR (source_url ~* '^https?://'::text))),
    CONSTRAINT pppp_representation_discovery_candidates_v1_status_check CHECK ((status = ANY (ARRAY['new'::text, 'review'::text, 'accepted'::text, 'rejected'::text, 'duplicate'::text]))),
    CONSTRAINT pppp_representation_discovery_candidates_v_candidate_kind_check CHECK ((candidate_kind = ANY (ARRAY['company'::text, 'opportunity'::text])))
);


ALTER TABLE public.pppp_representation_discovery_candidates_v1 OWNER TO postgres;

--
-- Name: TABLE pppp_representation_discovery_candidates_v1; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.pppp_representation_discovery_candidates_v1 IS 'Isolated review inbox for market-entry companies and serious consortium/JV opportunities. Discovery never mutates other commercial modules.';


--
-- Name: pppp_representation_discovery_runs_v1; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.pppp_representation_discovery_runs_v1 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lane text NOT NULL,
    run_date date DEFAULT CURRENT_DATE NOT NULL,
    status text DEFAULT 'running'::text NOT NULL,
    discovered_count integer DEFAULT 0 NOT NULL,
    new_count integer DEFAULT 0 NOT NULL,
    duplicate_count integer DEFAULT 0 NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_message text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    CONSTRAINT pppp_representation_discovery_runs_v1_discovered_count_check CHECK ((discovered_count >= 0)),
    CONSTRAINT pppp_representation_discovery_runs_v1_duplicate_count_check CHECK ((duplicate_count >= 0)),
    CONSTRAINT pppp_representation_discovery_runs_v1_lane_check CHECK ((lane = ANY (ARRAY['market_entry'::text, 'consortium_opportunity'::text]))),
    CONSTRAINT pppp_representation_discovery_runs_v1_new_count_check CHECK ((new_count >= 0)),
    CONSTRAINT pppp_representation_discovery_runs_v1_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT pppp_representation_discovery_runs_v1_status_check CHECK ((status = ANY (ARRAY['running'::text, 'succeeded'::text, 'failed'::text, 'skipped'::text])))
);


ALTER TABLE public.pppp_representation_discovery_runs_v1 OWNER TO postgres;

--
-- Name: pppp_representation_discovery_summary_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_representation_discovery_summary_v1 WITH (security_invoker='true') AS
 SELECT count(*) FILTER (WHERE (status = ANY (ARRAY['new'::text, 'review'::text]))) AS total_review,
    count(*) FILTER (WHERE ((lane = 'market_entry'::text) AND (status = ANY (ARRAY['new'::text, 'review'::text])))) AS market_entry_review,
    count(*) FILTER (WHERE ((lane = 'consortium_opportunity'::text) AND (status = ANY (ARRAY['new'::text, 'review'::text])))) AS consortium_review,
    count(*) FILTER (WHERE (status = 'duplicate'::text)) AS duplicates,
    max(last_seen_at) AS last_seen_at
   FROM public.pppp_representation_discovery_candidates_v1;


ALTER VIEW public.pppp_representation_discovery_summary_v1 OWNER TO postgres;

--
-- Name: pppp_representation_opportunity_targets_v1; Type: TABLE; Schema: public; Owner: postgres
