    CONSTRAINT pppp_representation_opportunity_targets_v1_candidate_role_check CHECK ((candidate_role = ANY (ARRAY['lead_epc_candidate'::text, 'oem_specialist_partner'::text, 'local_partner'::text, 'representation'::text, 'jv_consortium_candidate'::text, 'fabrication_partner'::text, 'material_supply_partner'::text, 'competitor_intelligence'::text]))),
    CONSTRAINT pppp_representation_opportunity_targets_v1_fit_evidence_check CHECK ((jsonb_typeof(fit_evidence) = 'object'::text))
);


