-- Name: TABLE pppp_representation_opportunity_targets_v1; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.pppp_representation_opportunity_targets_v1 IS 'Many-to-many candidate links. Outreach is eligible only after project verification, known procurement stage and verified company fit; sending remains manual.';


--
-- Name: pppp_representation_outreach_readiness_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_representation_outreach_readiness_v1 WITH (security_invoker='true') AS
 SELECT l.opportunity_id,
    l.target_id,
    o.project_name,
    t.company_name,
    o.verification_status AS project_verification_status,
    o.procurement_stage,
    l.company_fit_status,
    ((o.verification_status = 'verified'::text) AND (NULLIF(btrim(o.procurement_stage), ''::text) IS NOT NULL) AND (l.company_fit_status = 'verified'::text)) AS outreach_eligible,
    jsonb_strip_nulls(jsonb_build_object('project_verified',
        CASE
            WHEN (o.verification_status <> 'verified'::text) THEN 'Project verification is required'::text
            ELSE NULL::text
        END, 'procurement_stage_known',
        CASE
            WHEN (NULLIF(btrim(o.procurement_stage), ''::text) IS NULL) THEN 'Procurement stage is required'::text
            ELSE NULL::text
        END, 'company_fit_verified',
        CASE
            WHEN (l.company_fit_status <> 'verified'::text) THEN 'Company fit verification is required'::text
            ELSE NULL::text
        END)) AS blockers
   FROM ((public.pppp_representation_opportunity_targets_v1 l
     JOIN public.pppp_representation_opportunities_v1 o ON ((o.id = l.opportunity_id)))
     JOIN public.pppp_representation_targets_v1 t ON ((t.id = l.target_id)))
  WHERE ((l.archived_at IS NULL) AND (o.archived_at IS NULL) AND (t.archived_at IS NULL));


ALTER VIEW public.pppp_representation_outreach_readiness_v1 OWNER TO postgres;

--
-- Name: pppp_representation_relationships_v1; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.pppp_representation_relationships_v1 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    target_id uuid NOT NULL,
    opportunity_id uuid,
    source_key text NOT NULL,
    related_company_name text NOT NULL,
    related_company_domain text,
    related_company_domain_normalized text,
    related_company_country text,
    relationship_type text DEFAULT 'unknown'::text NOT NULL,
    relationship_status text DEFAULT 'unknown'::text NOT NULL,
    project_or_tender text,
    project_reference text,
    relationship_scope text,
    verification_status text DEFAULT 'unknown'::text NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    source_name text,
    source_url text,
    last_verified_at timestamp with time zone,
    notes text,
    created_source text DEFAULT 'manual'::text NOT NULL,
    created_source_command_id text,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pppp_representation_relationships_v1_created_source_check CHECK ((created_source = ANY (ARRAY['manual'::text, 'chatgpt'::text, 'import'::text]))),
    CONSTRAINT pppp_representation_relationships_v1_evidence_check CHECK ((jsonb_typeof(evidence) = 'object'::text)),
    CONSTRAINT pppp_representation_relationships_v1_related_company_name_check CHECK (((length(btrim(related_company_name)) >= 1) AND (length(btrim(related_company_name)) <= 500))),
    CONSTRAINT pppp_representation_relationships_v1_relationship_status_check CHECK ((relationship_status = ANY (ARRAY['current'::text, 'historical'::text, 'unknown'::text]))),
    CONSTRAINT pppp_representation_relationships_v1_relationship_type_check CHECK ((relationship_type = ANY (ARRAY['joint_venture'::text, 'consortium'::text, 'subcontractor'::text, 'supplier'::text, 'representative'::text, 'distributor'::text, 'implementation_partner'::text, 'local_partner'::text, 'other'::text, 'unknown'::text]))),
    CONSTRAINT pppp_representation_relationships_v1_source_key_check CHECK (((length(btrim(source_key)) >= 1) AND (length(btrim(source_key)) <= 500))),
    CONSTRAINT pppp_representation_relationships_v1_source_url_check CHECK (((source_url IS NULL) OR (source_url ~* '^https?://'::text))),
    CONSTRAINT pppp_representation_relationships_v1_verification_status_check CHECK ((verification_status = ANY (ARRAY['unknown'::text, 'review'::text, 'verified'::text])))
);


ALTER TABLE public.pppp_representation_relationships_v1 OWNER TO postgres;

--
-- Name: TABLE pppp_representation_relationships_v1; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.pppp_representation_relationships_v1 IS 'Historical/current local and regional company relationships for Representation targets: JV, consortium, subcontractor, supplier, representative, distributor and similar. No automatic outreach or partner commitment.';


--
-- Name: COLUMN pppp_representation_relationships_v1.verification_status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.pppp_representation_relationships_v1.verification_status IS 'verified requires evidence; review is a lead requiring human review; unknown is not evidence of absence.';


