ALTER TABLE public.pppp_representation_target_update_audit OWNER TO postgres;

--
-- Name: pppp_sales_engine_v3_workbench_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_sales_engine_v3_workbench_v1 WITH (security_invoker='true') AS
 SELECT 'material_trade'::text AS channel,
    'dach_target'::text AS source_type,
    t.id AS source_id,
    t.source_key,
    t.company_name,
    COALESCE(t.why_now, t.buyer_type) AS why_company,
    COALESCE(t.procurement_timing, t.why_now) AS commercial_signal,
    t.project_title,
    t.canonical_contact_email AS contact_email,
    t.canonical_contact_name AS contact_name,
    t.canonical_contact_role AS contact_role,
    t.contact_tier,
    t.contact_quality_score,
    t.company_fit_score,
    t.commercial_timing_score,
    t.message_evidence_score,
    t.outreach_readiness_score,
    t.outreach_motion,
    COALESCE(t.pristeel_offer_model, public.pppp_pristeel_offer_model_v1('material_trade'::text, t.buyer_type, t.outreach_motion, t.timing_classification, NULL::text)) AS pristeel_offer_model,
    t.secondary_pristeel_offer_model,
    t.timing_classification,
    t.workflow_state,
    t.personalization_facts,
    t.readiness_reasons,
    t.outreach_engine_version,
    t.reply_classification,
    t.reply_evidence,
    q.sent_at AS last_contact_at,
    q.replied_at,
    q.bounced_at,
    q.gmail_thread_id,
    t.project_id,
    COALESCE(t.next_action,
        CASE
            WHEN (t.workflow_state = 'strong_company_contact_gap'::text) THEN 'Find or improve procurement contact'::text
            WHEN (t.workflow_state = 'ready_for_outreach'::text) THEN 'Review evidence-led draft'::text
            WHEN (t.workflow_state = 'thread_review'::text) THEN 'Open Gmail thread'::text
            ELSE 'Research evidence and timing'::text
        END) AS next_action,
    true AS human_send_required
   FROM (public.pppp_dach_steel_targets_v1 t
     LEFT JOIN LATERAL ( SELECT oq.sent_at,
            oq.replied_at,
            oq.bounced_at,
            oq.gmail_thread_id
           FROM public.pppp_outbound_queue_v1 oq
          WHERE (oq.source_record_id = t.id)
          ORDER BY COALESCE(oq.sent_at, oq.updated_at, oq.created_at) DESC
         LIMIT 1) q ON (true))
UNION ALL
 SELECT 'ted_awarded'::text AS channel,
    'opportunity_action'::text AS source_type,
    a.id AS source_id,
    a.action_key AS source_key,
    a.target_company AS company_name,
    COALESCE((a.payload ->> 'why_company'::text), a.draft_brief) AS why_company,
    COALESCE((a.payload ->> 'commercial_signal'::text), a.subject_hint) AS commercial_signal,
    (a.payload ->> 'project_title'::text) AS project_title,
    a.target_email AS contact_email,
    a.target_name AS contact_name,
    a.target_role AS contact_role,
    a.contact_tier,
    a.contact_quality_score,
    a.company_fit_score,
    a.commercial_timing_score,
    a.message_evidence_score,
    a.outreach_readiness_score,
    a.outreach_motion,
    COALESCE(a.pristeel_offer_model, public.pppp_pristeel_offer_model_v1('ted_awarded'::text, a.action_type, a.outreach_motion, a.timing_classification, a.route)) AS pristeel_offer_model,
    a.secondary_pristeel_offer_model,
    a.timing_classification,
    a.workflow_state,
    a.personalization_facts,
    a.readiness_reasons,
    a.outreach_engine_version,
    a.reply_classification,
    a.reply_evidence,
    r.sent_at AS last_contact_at,
        CASE
            WHEN (r.status = 'replied'::text) THEN r.updated_at
            ELSE NULL::timestamp with time zone
        END AS replied_at,
    NULL::timestamp with time zone AS bounced_at,
    r.gmail_thread_id,
    a.project_id,
        CASE
            WHEN (a.workflow_state = 'strong_company_contact_gap'::text) THEN 'Find or improve procurement contact'::text
            WHEN (a.workflow_state = 'ready_for_outreach'::text) THEN 'Review evidence-led draft'::text
            WHEN (r.gmail_thread_id IS NOT NULL) THEN 'Open Gmail thread'::text
            WHEN (a.timing_classification = 'future_supplier_qualification'::text) THEN 'Qualify for future supplier list'::text
            ELSE 'Research evidence and timing'::text
        END AS next_action,
    true AS human_send_required
   FROM (public.pppp_opportunity_actions a
     LEFT JOIN LATERAL ( SELECT x.sent_at,
            x.updated_at,
            x.status,
            x.gmail_thread_id
           FROM public.pppp_opportunity_outreach_registry_v1 x
          WHERE (x.action_id = a.id)
          ORDER BY COALESCE(x.sent_at, x.updated_at, x.created_at) DESC
         LIMIT 1) r ON (true))
  WHERE (a.action_type = ANY (ARRAY['gc_contact_research'::text, 'gc_project_outreach_draft'::text, 'producer_contact_research'::text, 'producer_capacity_outreach_draft'::text, 'consortium_member_review'::text, 'consortium_project_outreach_draft'::text, 'general_project_outreach_draft'::text, 'manual_tender_outreach_draft'::text]))
UNION ALL
 SELECT 'gc_direct'::text AS channel,
    'gc_prospect'::text AS source_type,
    g.id AS source_id,
    g.company_key AS source_key,
    g.company_name,
    COALESCE(g.company_type, 'GC/GU'::text) AS why_company,
        CASE
            WHEN ((jsonb_typeof(COALESCE(g.current_projects, '[]'::jsonb)) = 'array'::text) AND (jsonb_array_length(COALESCE(g.current_projects, '[]'::jsonb)) > 0)) THEN COALESCE(((g.current_projects -> 0) ->> 'status'::text), 'active project signal'::text)
            ELSE 'Verified GC/GU target'::text
        END AS commercial_signal,
        CASE
            WHEN ((jsonb_typeof(COALESCE(g.current_projects, '[]'::jsonb)) = 'array'::text) AND (jsonb_array_length(COALESCE(g.current_projects, '[]'::jsonb)) > 0)) THEN ((g.current_projects -> 0) ->> 'name'::text)
            WHEN ((jsonb_typeof(COALESCE(g.recent_projects, '[]'::jsonb)) = 'array'::text) AND (jsonb_array_length(COALESCE(g.recent_projects, '[]'::jsonb)) > 0)) THEN ((g.recent_projects -> 0) ->> 'name'::text)
            ELSE NULL::text
        END AS project_title,
    g.contact_email,
    g.contact_name,
    g.contact_role,
    g.contact_tier,
    g.contact_quality_score,
    g.company_fit_score,
    g.commercial_timing_score,
    g.message_evidence_score,
    g.outreach_readiness_score,
    g.outreach_motion,
    COALESCE(g.pristeel_offer_model, 'fabricated_steel_package'::text) AS pristeel_offer_model,
    g.secondary_pristeel_offer_model,
    g.timing_classification,
    g.workflow_state,
    g.personalization_facts,
    g.readiness_reasons,
    g.outreach_engine_version,
    g.reply_classification,
    g.reply_evidence,
    g.first_sent_at AS last_contact_at,
    g.replied_at,
    g.bounced_at,
    g.first_gmail_thread_id AS gmail_thread_id,
    NULL::uuid AS project_id,
        CASE
            WHEN (g.replied_at IS NOT NULL) THEN 'Open Gmail thread and classify reply'::text
            WHEN (g.workflow_state = 'strong_company_contact_gap'::text) THEN 'Find or improve procurement contact'::text
            WHEN ((g.workflow_state = 'ready_for_outreach'::text) AND (g.first_draft_id IS NOT NULL)) THEN 'Refresh/review V2 draft before sending'::text
            WHEN (g.workflow_state = 'ready_for_outreach'::text) THEN 'Review evidence-led draft'::text
            WHEN (g.first_sent_at IS NOT NULL) THEN 'Wait for reply / contextual follow-up only when due'::text
            ELSE 'Research evidence and timing'::text
        END AS next_action,
    true AS human_send_required
   FROM public.pppp_gc_prospects_v1 g;


ALTER VIEW public.pppp_sales_engine_v3_workbench_v1 OWNER TO postgres;

--
-- Name: pppp_sales_engine_v3_funnel_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_sales_engine_v3_funnel_v1 WITH (security_invoker='true') AS
 SELECT channel,
    outreach_engine_version,
    count(*) AS discovered,
    count(*) FILTER (WHERE (company_fit_score >= 65)) AS qualified,
    count(*) FILTER (WHERE (contact_email IS NOT NULL)) AS contact_found,
    count(*) FILTER (WHERE (contact_tier = ANY (ARRAY['A'::text, 'B'::text]))) AS named_decision_maker,
    count(*) FILTER (WHERE (workflow_state = 'strong_company_contact_gap'::text)) AS contact_gap,
    count(*) FILTER (WHERE (workflow_state = 'ready_for_outreach'::text)) AS ready_for_outreach,
    count(*) FILTER (WHERE ((workflow_state = 'draft_created'::text) OR ((source_type = 'gc_prospect'::text) AND (last_contact_at IS NULL) AND (gmail_thread_id IS NOT NULL)))) AS drafted,
    count(*) FILTER (WHERE (last_contact_at IS NOT NULL)) AS sent,
    count(*) FILTER (WHERE ((last_contact_at IS NOT NULL) AND (bounced_at IS NULL))) AS delivered,
    count(*) FILTER (WHERE ((replied_at IS NOT NULL) OR (reply_classification IS NOT NULL))) AS replied,
    count(*) FILTER (WHERE (reply_classification = ANY (ARRAY['future_interest'::text, 'meeting_requested'::text]))) AS positive_replies,
    count(*) FILTER (WHERE (reply_classification = 'referral'::text)) AS referrals,
    count(*) FILTER (WHERE (reply_classification = 'rfq_received'::text)) AS rfqs,
    count(*) FILTER (WHERE (project_id IS NOT NULL)) AS projects_created
   FROM public.pppp_sales_engine_v3_workbench_v1
  GROUP BY channel, outreach_engine_version;


ALTER VIEW public.pppp_sales_engine_v3_funnel_v1 OWNER TO postgres;

--
-- Name: pppp_sales_engine_v3_pilot_queue_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_sales_engine_v3_pilot_queue_v1 WITH (security_invoker='true') AS
 SELECT channel,
    source_type,
    source_id,
    source_key,
    company_name,
    why_company,
    commercial_signal,
    project_title,
    contact_email,
    contact_name,
    contact_role,
    contact_tier,
    contact_quality_score,
    company_fit_score,
    commercial_timing_score,
    message_evidence_score,
    outreach_readiness_score,
    outreach_motion,
    pristeel_offer_model,
    secondary_pristeel_offer_model,
    timing_classification,
    workflow_state,
    personalization_facts,
    readiness_reasons,
    outreach_engine_version,
    reply_classification,
    reply_evidence,
    last_contact_at,
    replied_at,
    bounced_at,
    gmail_thread_id,
    project_id,
    next_action,
    human_send_required
   FROM public.pppp_sales_engine_v3_workbench_v1 w
  WHERE ((outreach_engine_version = 'v2'::text) AND (workflow_state = 'ready_for_outreach'::text) AND (contact_quality_score >= 50) AND (message_evidence_score >= 60) AND (jsonb_array_length(COALESCE(personalization_facts, '[]'::jsonb)) >= 2) AND (last_contact_at IS NULL) AND ((source_type <> 'opportunity_action'::text) OR (EXISTS ( SELECT 1
           FROM ((public.pppp_opportunity_actions a
             JOIN public.kek_tender_watch k ON ((k.id = a.tender_watch_id)))
             CROSS JOIN LATERAL jsonb_array_elements(
                CASE
                    WHEN (jsonb_typeof((k.payload #> '{winner,contact_enrichment,organizations}'::text[])) = 'array'::text) THEN (k.payload #> '{winner,contact_enrichment,organizations}'::text[])
                    ELSE '[]'::jsonb
                END) org(value))
          WHERE ((a.id = w.source_id) AND (regexp_replace(lower(COALESCE((org.value ->> 'name'::text), ''::text)), '[^a-z0-9]+'::text, ''::text, 'g'::text) = regexp_replace(lower(COALESCE(a.target_company, ''::text)), '[^a-z0-9]+'::text, ''::text, 'g'::text)) AND (lower(split_part(a.target_email, '@'::text, 2)) = lower(COALESCE(NULLIF((org.value ->> 'domain'::text), ''::text), regexp_replace((org.value ->> 'official_website'::text), '^https?://(www\\.)?|/.*$'::text, ''::text, 'g'::text)))))))))
  ORDER BY outreach_readiness_score DESC, company_fit_score DESC, contact_quality_score DESC
 LIMIT 25;


ALTER VIEW public.pppp_sales_engine_v3_pilot_queue_v1 OWNER TO postgres;

--
-- Name: pppp_selected_supplier_cost_basis_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_selected_supplier_cost_basis_v1 WITH (security_invoker='true') AS
 WITH ranked_decisions AS (
         SELECT d.id,
            d.project_id,
            d.supplier_offer_id,
            d.supplier_name,
            d.decision_type,
            d.status,
            d.source,
            d.evidence,
            d.notes,
            d.decided_at,
            d.created_at,
            d.updated_at,
            row_number() OVER (PARTITION BY d.project_id ORDER BY
                CASE d.decision_type
                    WHEN 'selected_producer'::text THEN 1
                    ELSE 2
                END, d.decided_at DESC, d.id DESC) AS rn
           FROM public.project_supplier_decisions d
          WHERE (d.status = 'active'::text)
        ), base AS (
         SELECT d.id AS decision_id,
            d.project_id,
            p.name AS project_name,
            p.client,
            p.status AS project_status,
            p.pipeline_stage,
            p.operational_state,
            d.decision_type,
            d.supplier_name AS selected_supplier,
            d.supplier_offer_id,
            d.source AS decision_source,
            d.evidence AS decision_evidence,
            d.notes AS decision_notes,
            d.decided_at,
            o.currency,
            lower(COALESCE(NULLIF(TRIM(BOTH FROM o.pricing_unit), ''::text),
                CASE
                    WHEN (COALESCE(o.price_kg, (0)::numeric) > (0)::numeric) THEN 'kg'::text
                    WHEN (COALESCE(o.unit_price, (0)::numeric) > (0)::numeric) THEN 'unit'::text
                    ELSE 'total'::text
                END)) AS pricing_basis,
            o.price_kg,
            o.unit_price,
            o.total_amount,
            o.total_eur,
            o.qty_kg,
            o.exchange_rate_to_eur,
            o.transport_eur,
            o.zinc_kg,
            o.delivery_weeks,
            o.incoterms,
            o.payment_terms,
            o.validity_days,
            o.cert,
            o.offer_ref,
            o.inclusions,
            o.exclusions,
            o.created_at AS supplier_offer_created_at
           FROM ((ranked_decisions d
             JOIN public.projects p ON ((p.id = d.project_id)))
             LEFT JOIN public.offers o ON ((o.id = d.supplier_offer_id)))
          WHERE (d.rn = 1)
        ), calc AS (
         SELECT b.decision_id,
            b.project_id,
            b.project_name,
            b.client,
            b.project_status,
            b.pipeline_stage,
            b.operational_state,
            b.decision_type,
            b.selected_supplier,
            b.supplier_offer_id,
            b.decision_source,
            b.decision_evidence,
            b.decision_notes,
            b.decided_at,
            b.currency,
            b.pricing_basis,
            b.price_kg,
            b.unit_price,
            b.total_amount,
            b.total_eur,
            b.qty_kg,
            b.exchange_rate_to_eur,
            b.transport_eur,
            b.zinc_kg,
            b.delivery_weeks,
            b.incoterms,
            b.payment_terms,
            b.validity_days,
            b.cert,
            b.offer_ref,
            b.inclusions,
            b.exclusions,
            b.supplier_offer_created_at,
                CASE
                    WHEN (upper(COALESCE(NULLIF(TRIM(BOTH FROM b.currency), ''::text), 'EUR'::text)) = 'EUR'::text) THEN (1)::numeric
                    ELSE b.exchange_rate_to_eur
                END AS rate_to_eur,
                CASE
                    WHEN (COALESCE(b.price_kg, (0)::numeric) > (0)::numeric) THEN b.price_kg
                    WHEN (COALESCE(b.unit_price, (0)::numeric) > (0)::numeric) THEN b.unit_price
                    ELSE NULL::numeric
                END AS unit_cost_original,
                CASE
                    WHEN (COALESCE(b.total_eur, (0)::numeric) > (0)::numeric) THEN b.total_eur
                    WHEN ((upper(COALESCE(NULLIF(TRIM(BOTH FROM b.currency), ''::text), 'EUR'::text)) = 'EUR'::text) AND (COALESCE(b.total_amount, (0)::numeric) > (0)::numeric)) THEN b.total_amount
                    WHEN ((COALESCE(b.total_amount, (0)::numeric) > (0)::numeric) AND (COALESCE(b.exchange_rate_to_eur, (0)::numeric) > (0)::numeric)) THEN (b.total_amount * b.exchange_rate_to_eur)
                    ELSE NULL::numeric
                END AS explicit_total_eur
           FROM base b
        )
 SELECT decision_id,
    project_id,
    project_name,
    client,
    project_status,
    pipeline_stage,
    operational_state,
    decision_type,
    selected_supplier,
    supplier_offer_id,
    decision_source,
    decision_evidence,
    decision_notes,
    decided_at,
    currency,
    pricing_basis,
    price_kg,
    unit_price,
    total_amount,
    total_eur,
    qty_kg,
    exchange_rate_to_eur,
    transport_eur,
    zinc_kg,
    delivery_weeks,
    incoterms,
    payment_terms,
    validity_days,
    cert,
    offer_ref,
    inclusions,
    exclusions,
    supplier_offer_created_at,
    rate_to_eur,
    unit_cost_original,
    explicit_total_eur,
        CASE
            WHEN ((unit_cost_original IS NOT NULL) AND (rate_to_eur IS NOT NULL)) THEN (unit_cost_original * rate_to_eur)
            ELSE NULL::numeric
        END AS unit_cost_eur,
    (supplier_offer_id IS NULL) AS missing_linked_offer,
    ((supplier_offer_id IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM COALESCE(currency, ''::text)), ''::text) IS NULL)) AS missing_currency,
    ((supplier_offer_id IS NOT NULL) AND (COALESCE(price_kg, (0)::numeric) <= (0)::numeric) AND (COALESCE(unit_price, (0)::numeric) <= (0)::numeric) AND (COALESCE(total_amount, (0)::numeric) <= (0)::numeric) AND (COALESCE(total_eur, (0)::numeric) <= (0)::numeric)) AS missing_commercial_value,
    ((supplier_offer_id IS NOT NULL) AND (upper(COALESCE(NULLIF(TRIM(BOTH FROM currency), ''::text), 'EUR'::text)) <> 'EUR'::text) AND (COALESCE(exchange_rate_to_eur, (0)::numeric) <= (0)::numeric)) AS non_eur_missing_fx,
    ((pricing_basis = 'kg'::text) AND (COALESCE(qty_kg, (0)::numeric) <= (0)::numeric)) AS missing_qty_for_kg_basis,
        CASE
            WHEN ((supplier_offer_id IS NULL) OR ((supplier_offer_id IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM COALESCE(currency, ''::text)), ''::text) IS NULL)) OR ((supplier_offer_id IS NOT NULL) AND (COALESCE(price_kg, (0)::numeric) <= (0)::numeric) AND (COALESCE(unit_price, (0)::numeric) <= (0)::numeric) AND (COALESCE(total_amount, (0)::numeric) <= (0)::numeric) AND (COALESCE(total_eur, (0)::numeric) <= (0)::numeric)) OR ((supplier_offer_id IS NOT NULL) AND (upper(COALESCE(NULLIF(TRIM(BOTH FROM currency), ''::text), 'EUR'::text)) <> 'EUR'::text) AND (COALESCE(exchange_rate_to_eur, (0)::numeric) <= (0)::numeric))) THEN 'blocked'::text
            ELSE 'review'::text
        END AS cost_basis_readiness,
    ((lower(COALESCE(project_status, ''::text)) <> ALL (ARRAY['humbur'::text, 'lost'::text, 'mbyllur'::text, 'closed'::text, 'arkivuar'::text, 'archived'::text, 'realizuar'::text, 'cancelled'::text, 'canceled'::text])) AND (COALESCE(operational_state, ''::text) <> ALL (ARRAY['wait_for_client'::text, 'execution'::text])) AND (pipeline_stage = ANY (ARRAY['rfq_in'::text, 'technical_review'::text, 'supplier_selection'::text, 'pricing'::text]))) AS eligible_for_client_offer_handoff,
    concat_ws(' | '::text,
        CASE
            WHEN (supplier_offer_id IS NULL) THEN 'BLOCKER: human supplier decision is not linked to a canonical supplier offer'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((supplier_offer_id IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM COALESCE(currency, ''::text)), ''::text) IS NULL)) THEN 'BLOCKER: selected offer currency missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((supplier_offer_id IS NOT NULL) AND (COALESCE(price_kg, (0)::numeric) <= (0)::numeric) AND (COALESCE(unit_price, (0)::numeric) <= (0)::numeric) AND (COALESCE(total_amount, (0)::numeric) <= (0)::numeric) AND (COALESCE(total_eur, (0)::numeric) <= (0)::numeric)) THEN 'BLOCKER: selected offer has no reviewed commercial value'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((supplier_offer_id IS NOT NULL) AND (upper(COALESCE(NULLIF(TRIM(BOTH FROM currency), ''::text), 'EUR'::text)) <> 'EUR'::text) AND (COALESCE(exchange_rate_to_eur, (0)::numeric) <= (0)::numeric)) THEN 'BLOCKER: non-EUR selected offer has no reviewed FX rate'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((pricing_basis = 'kg'::text) AND (COALESCE(qty_kg, (0)::numeric) <= (0)::numeric)) THEN 'Cost basis: quantity is missing for kg pricing; verify BOQ/project quantity before total-price preparation'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (delivery_weeks IS NULL) THEN 'Missing supplier term: delivery'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE(incoterms, ''::text)), ''::text) IS NULL) THEN 'Missing supplier term: Incoterms'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE(payment_terms, ''::text)), ''::text) IS NULL) THEN 'Missing supplier term: payment terms'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (validity_days IS NULL) THEN 'Missing supplier term: validity'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE(cert, ''::text)), ''::text) IS NULL) THEN 'Missing supplier term: certificate/quality'::text
            ELSE NULL::text
        END) AS warning_text
   FROM calc c;


ALTER VIEW public.pppp_selected_supplier_cost_basis_v1 OWNER TO postgres;

--
-- Name: pppp_steel_buyer_discovery_candidates_v1; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.pppp_steel_buyer_discovery_candidates_v1 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid,
    external_key text NOT NULL,
    company_name text NOT NULL,
    normalized_name text NOT NULL,
    official_domain text,
    website text,
    country_code text,
    industry text,
    employees integer,
    revenue_text text,
    size_band text DEFAULT 'unknown'::text NOT NULL,
    consumption_potential text DEFAULT 'unknown'::text NOT NULL,
    business_summary text,
    evidence jsonb DEFAULT '[]'::jsonb NOT NULL,
    source_url text,
    status text DEFAULT 'new'::text NOT NULL,
    canonical_company_id uuid,
    target_id uuid,
    routing_conflicts text[] DEFAULT '{}'::text[] NOT NULL,
    reason text,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pppp_steel_buyer_discovery_candidat_consumption_potential_check CHECK ((consumption_potential = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'unknown'::text]))),
    CONSTRAINT pppp_steel_buyer_discovery_candidates_v1_size_band_check CHECK ((size_band = ANY (ARRAY['micro'::text, 'small'::text, 'medium'::text, 'large'::text, 'enterprise'::text, 'unknown'::text]))),
    CONSTRAINT pppp_steel_buyer_discovery_candidates_v1_status_check CHECK ((status = ANY (ARRAY['new'::text, 'accepted'::text, 'duplicate'::text, 'routing_review'::text, 'rejected'::text, 'error'::text])))
);


ALTER TABLE public.pppp_steel_buyer_discovery_candidates_v1 OWNER TO postgres;

