);


ALTER TABLE public.pppp_steel_buyer_discovery_runs_v1 OWNER TO postgres;

--
-- Name: pppp_steel_buyer_discovery_summary_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_steel_buyer_discovery_summary_v1 WITH (security_invoker='true') AS
 SELECT ( SELECT count(*) AS count
           FROM public.pppp_steel_buyer_discovery_candidates_v1
          WHERE (pppp_steel_buyer_discovery_candidates_v1.status = 'new'::text)) AS new_candidates,
    ( SELECT count(*) AS count
           FROM public.pppp_steel_buyer_discovery_candidates_v1
          WHERE (pppp_steel_buyer_discovery_candidates_v1.status = 'routing_review'::text)) AS routing_review,
    ( SELECT count(*) AS count
           FROM public.pppp_steel_buyer_discovery_candidates_v1
          WHERE (pppp_steel_buyer_discovery_candidates_v1.status = 'accepted'::text)) AS accepted,
    ( SELECT max(pppp_steel_buyer_discovery_runs_v1.finished_at) AS max
           FROM public.pppp_steel_buyer_discovery_runs_v1
          WHERE (pppp_steel_buyer_discovery_runs_v1.status = 'succeeded'::text)) AS last_success_at,
    ( SELECT pppp_steel_buyer_discovery_runs_v1.status
           FROM public.pppp_steel_buyer_discovery_runs_v1
          ORDER BY pppp_steel_buyer_discovery_runs_v1.started_at DESC
         LIMIT 1) AS last_status,
    COALESCE(( SELECT jsonb_agg(to_jsonb(c.*) ORDER BY
                CASE c.consumption_potential
                    WHEN 'high'::text THEN 1
                    WHEN 'medium'::text THEN 2
                    ELSE 3
                END, c.company_name) AS jsonb_agg
           FROM ( SELECT pppp_steel_buyer_discovery_candidates_v1.id,
                    pppp_steel_buyer_discovery_candidates_v1.company_name,
                    pppp_steel_buyer_discovery_candidates_v1.official_domain,
                    pppp_steel_buyer_discovery_candidates_v1.website,
                    pppp_steel_buyer_discovery_candidates_v1.country_code,
                    pppp_steel_buyer_discovery_candidates_v1.industry,
                    pppp_steel_buyer_discovery_candidates_v1.employees,
                    pppp_steel_buyer_discovery_candidates_v1.revenue_text,
                    pppp_steel_buyer_discovery_candidates_v1.size_band,
                    pppp_steel_buyer_discovery_candidates_v1.consumption_potential,
                    pppp_steel_buyer_discovery_candidates_v1.business_summary,
                    pppp_steel_buyer_discovery_candidates_v1.evidence,
                    pppp_steel_buyer_discovery_candidates_v1.source_url,
                    pppp_steel_buyer_discovery_candidates_v1.first_seen_at
                   FROM public.pppp_steel_buyer_discovery_candidates_v1
                  WHERE (pppp_steel_buyer_discovery_candidates_v1.status = 'new'::text)
                  ORDER BY
                        CASE pppp_steel_buyer_discovery_candidates_v1.consumption_potential
                            WHEN 'high'::text THEN 1
                            WHEN 'medium'::text THEN 2
                            ELSE 3
                        END, pppp_steel_buyer_discovery_candidates_v1.company_name
                 LIMIT 40) c), '[]'::jsonb) AS candidates;


ALTER VIEW public.pppp_steel_buyer_discovery_summary_v1 OWNER TO postgres;

--
-- Name: supplier_contact_relationship_audit_v1; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.supplier_contact_relationship_audit_v1 (
    company_key text NOT NULL,
    company_name text NOT NULL,
    classification text NOT NULL,
    matched_partner_id uuid,
    confidence integer DEFAULT 50 NOT NULL,
    evidence_source text DEFAULT 'pppp_audit'::text NOT NULL,
    source_ref text,
    evidence_summary text DEFAULT ''::text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT supplier_contact_relationship_audit_v1_classification_check CHECK ((classification = ANY (ARRAY['supplier_verified'::text, 'supplier_candidate'::text, 'buyer_prospect'::text, 'unknown'::text]))),
    CONSTRAINT supplier_contact_relationship_audit_v1_confidence_check CHECK (((confidence >= 0) AND (confidence <= 100)))
);


ALTER TABLE public.supplier_contact_relationship_audit_v1 OWNER TO postgres;

--
-- Name: pppp_supplier_contact_audit_summary_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_supplier_contact_audit_summary_v1 WITH (security_invoker='true') AS
 SELECT a.company_key,
    a.company_name,
    a.classification,
    a.matched_partner_id,
    p.name AS supplier_master_name,
    a.confidence,
    a.evidence_source,
    a.source_ref,
    a.evidence_summary,
    (COALESCE(c.contact_rows, (0)::bigint))::integer AS contact_rows,
    COALESCE(c.emails, '{}'::text[]) AS emails,
    c.last_contact,
        CASE
            WHEN (a.classification = ANY (ARRAY['supplier_verified'::text, 'supplier_candidate'::text])) THEN true
            ELSE false
        END AS procurement_supplier_side,
        CASE
            WHEN (a.classification = 'supplier_verified'::text) THEN true
            ELSE false
        END AS safe_for_verified_supplier_reporting
   FROM ((public.supplier_contact_relationship_audit_v1 a
     LEFT JOIN public.partners p ON ((p.id = a.matched_partner_id)))
     LEFT JOIN LATERAL ( SELECT count(*) AS contact_rows,
            array_remove(array_agg(DISTINCT lower(NULLIF(btrim(c_1.email), ''::text))), NULL::text) AS emails,
            max(c_1.last_contact) AS last_contact
           FROM public.contacts c_1
          WHERE ((lower(COALESCE(c_1.kind, ''::text)) = 'supplier'::text) AND (private.pppp_supplier_norm_v1(c_1.company) = a.company_key))) c ON (true));


ALTER VIEW public.pppp_supplier_contact_audit_summary_v1 OWNER TO postgres;

