--
-- Name: pppp_supplier_identity_reconcile_source_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_supplier_identity_reconcile_source_v1 WITH (security_invoker='true') AS
 WITH public_domains(domain) AS (
         VALUES ('gmail.com'::text), ('googlemail.com'::text), ('outlook.com'::text), ('hotmail.com'::text), ('live.com'::text), ('yahoo.com'::text), ('icloud.com'::text), ('aol.com'::text), ('gmx.com'::text), ('gmx.de'::text), ('web.de'::text), ('mail.com'::text), ('proton.me'::text), ('protonmail.com'::text)
        ), contact_domains AS (
         SELECT lower(split_part(c.email, '@'::text, 2)) AS domain,
            array_agg(DISTINCT c.id) AS contact_ids,
            array_agg(DISTINCT lower(COALESCE(c.kind, ''::text))) FILTER (WHERE (NULLIF(TRIM(BOTH FROM c.kind), ''::text) IS NOT NULL)) AS kinds,
            (array_agg(NULLIF(TRIM(BOTH FROM c.company), ''::text) ORDER BY
                CASE
                    WHEN (NULLIF(TRIM(BOTH FROM c.company), ''::text) IS NULL) THEN 1
                    ELSE 0
                END, (length(COALESCE(c.company, ''::text))) DESC))[1] AS company,
            (array_agg(NULLIF(TRIM(BOTH FROM c.country), ''::text) ORDER BY
                CASE
                    WHEN (NULLIF(TRIM(BOTH FROM c.country), ''::text) IS NULL) THEN 1
                    ELSE 0
                END))[1] AS country,
            (array_agg(lower(c.email) ORDER BY
                CASE
                    WHEN (lower(COALESCE(c.kind, ''::text)) = 'supplier'::text) THEN 0
                    ELSE 1
                END, c.created_at DESC NULLS LAST))[1] AS email,
            (array_agg(NULLIF(TRIM(BOTH FROM c.person), ''::text) ORDER BY
                CASE
                    WHEN (NULLIF(TRIM(BOTH FROM c.person), ''::text) IS NULL) THEN 1
                    ELSE 0
                END, c.created_at DESC NULLS LAST))[1] AS person
           FROM public.contacts c
          WHERE ((c.email ~~ '%@%'::text) AND (NOT (lower(split_part(c.email, '@'::text, 2)) IN ( SELECT public_domains.domain
                   FROM public_domains))) AND (lower(split_part(c.email, '@'::text, 2)) <> ALL (ARRAY['prissteel.com'::text, 'pristeel.com'::text])))
          GROUP BY (lower(split_part(c.email, '@'::text, 2)))
        ), message_domains AS (
         SELECT lower(split_part(e.from_email, '@'::text, 2)) AS domain,
            'incoming'::text AS side,
            e.gmail_message_id,
            e.subject,
            e.snippet,
            e.sent_at
           FROM public.project_emails e
          WHERE ((lower(COALESCE(e.direction, ''::text)) = 'incoming'::text) AND (e.from_email ~~ '%@%'::text))
        UNION ALL
         SELECT lower(split_part(x.x, '@'::text, 2)) AS domain,
            'outgoing'::text AS side,
            e.gmail_message_id,
            e.subject,
            e.snippet,
            e.sent_at
           FROM (public.project_emails e
             CROSS JOIN LATERAL unnest(COALESCE(e.to_emails, '{}'::text[])) x(x))
          WHERE ((lower(COALESCE(e.direction, ''::text)) = 'outgoing'::text) AND (x.x ~~ '%@%'::text))
        ), msg_score AS (
         SELECT m.domain,
            (count(DISTINCT m.gmail_message_id) FILTER (WHERE (((m.side = 'outgoing'::text) AND (lower(COALESCE(m.subject, ''::text)) ~ '(\brfq\b|request for quotation|request for offer|request for quote|anfrage.*angebot|zahtev za ponudu|k[eë]rkes[ëe].*ofert)'::text)) OR ((m.side = 'incoming'::text) AND (lower(((COALESCE(m.subject, ''::text) || ' '::text) || COALESCE(m.snippet, ''::text))) ~ '(quotation|\bquote\b|\boffer\b|angebot|ponuda|eur/t|eur\/t|price/set|price\/set|unit price)'::text)))))::integer AS procurement_messages,
            (count(DISTINCT m.gmail_message_id) FILTER (WHERE ((m.side = 'incoming'::text) AND (lower(((COALESCE(m.subject, ''::text) || ' '::text) || COALESCE(m.snippet, ''::text))) ~ '(quotation|\bquote\b|\boffer\b|angebot|ponuda|eur/t|eur\/t|price/set|price\/set|unit price)'::text))))::integer AS incoming_offer_signals,
            (count(DISTINCT m.gmail_message_id) FILTER (WHERE ((m.side = 'outgoing'::text) AND (lower(COALESCE(m.subject, ''::text)) ~ '(\brfq\b|request for quotation|request for offer|request for quote|anfrage.*angebot|zahtev za ponudu|k[eë]rkes[ëe].*ofert)'::text))))::integer AS outgoing_rfq_signals,
            min(m.sent_at) FILTER (WHERE (((m.side = 'outgoing'::text) AND (lower(COALESCE(m.subject, ''::text)) ~ '(\brfq\b|request for quotation|request for offer|request for quote|anfrage.*angebot|zahtev za ponudu|k[eë]rkes[ëe].*ofert)'::text)) OR ((m.side = 'incoming'::text) AND (lower(((COALESCE(m.subject, ''::text) || ' '::text) || COALESCE(m.snippet, ''::text))) ~ '(quotation|\bquote\b|\boffer\b|angebot|ponuda|eur/t|eur\/t|price/set|price\/set|unit price)'::text)))) AS first_evidence_at,
            max(m.sent_at) FILTER (WHERE (((m.side = 'outgoing'::text) AND (lower(COALESCE(m.subject, ''::text)) ~ '(\brfq\b|request for quotation|request for offer|request for quote|anfrage.*angebot|zahtev za ponudu|k[eë]rkes[ëe].*ofert)'::text)) OR ((m.side = 'incoming'::text) AND (lower(((COALESCE(m.subject, ''::text) || ' '::text) || COALESCE(m.snippet, ''::text))) ~ '(quotation|\bquote\b|\boffer\b|angebot|ponuda|eur/t|eur\/t|price/set|price\/set|unit price)'::text)))) AS last_evidence_at,
            (array_agg(DISTINCT m.subject) FILTER (WHERE (NULLIF(TRIM(BOTH FROM m.subject), ''::text) IS NOT NULL)))[1:8] AS sample_subjects
           FROM message_domains m
          WHERE ((NOT (m.domain IN ( SELECT public_domains.domain
                   FROM public_domains))) AND (m.domain <> ALL (ARRAY['prissteel.com'::text, 'pristeel.com'::text])))
          GROUP BY m.domain
        ), partner_domains AS (
         SELECT p.id AS partner_id,
            lower(regexp_replace(split_part(regexp_replace(COALESCE(p.website, ''::text), '^https?://(www\.)?'::text, ''::text, 'i'::text), '/'::text, 1), '^www\.'::text, ''::text, 'i'::text)) AS domain
           FROM public.partners p
          WHERE (NULLIF(TRIM(BOTH FROM p.website), ''::text) IS NOT NULL)
        UNION
         SELECT pc.partner_id,
            lower(split_part(pc.email, '@'::text, 2)) AS domain
           FROM public.partner_contacts pc
          WHERE (pc.email ~~ '%@%'::text)
        ), domain_base AS (
         SELECT COALESCE(cd.domain, ms.domain) AS domain,
            cd.contact_ids,
            cd.kinds,
            cd.company,
            cd.country,
            cd.email,
            cd.person,
            COALESCE(ms.procurement_messages, 0) AS procurement_messages,
            COALESCE(ms.incoming_offer_signals, 0) AS incoming_offer_signals,
            COALESCE(ms.outgoing_rfq_signals, 0) AS outgoing_rfq_signals,
            ms.first_evidence_at,
            ms.last_evidence_at,
            ms.sample_subjects
           FROM (contact_domains cd
             FULL JOIN msg_score ms ON ((ms.domain = cd.domain)))
          WHERE (COALESCE(cd.domain, ms.domain) IS NOT NULL)
        )
 SELECT ('domain:'::text || d.domain) AS identity_key,
    COALESCE(NULLIF(TRIM(BOTH FROM d.company), ''::text), split_part(d.domain, '.'::text, 1)) AS company_name,
    d.domain AS company_domain,
    d.country,
    d.email AS primary_email,
    d.person AS contact_name,
    COALESCE(d.contact_ids, '{}'::uuid[]) AS source_contact_ids,
    COALESCE(d.kinds, '{}'::text[]) AS contact_kinds,
    d.procurement_messages,
    d.incoming_offer_signals,
    d.outgoing_rfq_signals,
    d.first_evidence_at,
    d.last_evidence_at,
    pd.partner_id AS linked_partner_id,
        CASE
            WHEN (pd.partner_id IS NOT NULL) THEN 'linked_existing'::text
            WHEN ((d.incoming_offer_signals > 0) OR (d.outgoing_rfq_signals > 0)) THEN 'confirmed_procurement_identity'::text
            WHEN ('supplier'::text = ANY (COALESCE(d.kinds, '{}'::text[]))) THEN 'contact_supplier_unverified'::text
            ELSE 'review'::text
        END AS identity_status,
        CASE
            WHEN ((pd.partner_id IS NOT NULL) AND (EXISTS ( SELECT 1
               FROM public.supplier_capabilities_v1 sc
              WHERE ((sc.partner_id = pd.partner_id) AND sc.is_active AND (sc.confidence >= 70))))) THEN 'profiled'::text
            WHEN (pd.partner_id IS NOT NULL) THEN 'needs_enrichment'::text
            WHEN ((d.incoming_offer_signals > 0) OR (d.outgoing_rfq_signals > 0)) THEN 'needs_supplier_master'::text
            ELSE 'unknown'::text
        END AS profile_status,
    jsonb_build_object('domain', d.domain, 'sample_subjects', COALESCE(to_jsonb(d.sample_subjects), '[]'::jsonb), 'source', 'contacts+project_emails', 'contact_kinds', COALESCE(to_jsonb(d.kinds), '[]'::jsonb)) AS evidence
   FROM (domain_base d
     LEFT JOIN LATERAL ( SELECT x.partner_id
           FROM partner_domains x
          WHERE (x.domain = d.domain)
          ORDER BY x.partner_id
         LIMIT 1) pd ON (true))
  WHERE ((d.procurement_messages > 0) OR ('supplier'::text = ANY (COALESCE(d.kinds, '{}'::text[]))));


ALTER VIEW public.pppp_supplier_identity_reconcile_source_v1 OWNER TO postgres;

--
-- Name: supplier_evidence_v1; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.supplier_evidence_v1 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    partner_id uuid NOT NULL,
    source text NOT NULL,
    source_ref text NOT NULL,
    evidence_type text NOT NULL,
    evidence_summary text NOT NULL,
    direction text,
    evidence_at timestamp with time zone,
    confidence integer DEFAULT 50 NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT supplier_evidence_v1_confidence_check CHECK (((confidence >= 0) AND (confidence <= 100)))
);


ALTER TABLE public.supplier_evidence_v1 OWNER TO postgres;

--
-- Name: pppp_supplier_master_audit_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_supplier_master_audit_v1 WITH (security_invoker='true') AS
 SELECT p.id AS partner_id,
    p.name,
    p.aliases,
    p.country,
    p.city,
    p.website,
    p.business_type,
    p.stage,
    p.importance,
    p.data_confidence,
    p.categories,
    p.grades,
    p.certifications,
    p.class_approval,
    COALESCE(ct.contacts, '[]'::jsonb) AS contacts,
    COALESCE(cp.capabilities, '[]'::jsonb) AS capabilities,
    COALESCE(ev.evidence, '[]'::jsonb) AS evidence,
    (COALESCE(ct.contact_count, (0)::bigint))::integer AS contact_count,
    (COALESCE(cp.capability_count, (0)::bigint))::integer AS capability_count,
    (COALESCE(ev.evidence_count, (0)::bigint))::integer AS evidence_count,
    (COALESCE(ev.gmail_evidence_count, (0)::bigint))::integer AS gmail_evidence_count,
    cp.max_confidence,
    ev.last_evidence_at,
        CASE
            WHEN (COALESCE(cp.capability_count, (0)::bigint) = 0) THEN 'missing_capability'::text
            WHEN (COALESCE(ct.contact_count, (0)::bigint) = 0) THEN 'missing_contact'::text
            WHEN ((COALESCE(cp.max_confidence, 0) >= 85) AND (COALESCE(ev.evidence_count, (0)::bigint) > 0)) THEN 'verified'::text
            WHEN (COALESCE(cp.max_confidence, 0) >= 70) THEN 'usable_partial'::text
            ELSE 'needs_enrichment'::text
        END AS profile_status,
    array_remove(ARRAY[
        CASE
            WHEN (COALESCE(ct.contact_count, (0)::bigint) = 0) THEN 'contact'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (COALESCE(cp.capability_count, (0)::bigint) = 0) THEN 'capability'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (COALESCE(cardinality(p.grades), 0) = 0) THEN 'grades'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (COALESCE(ev.evidence_count, (0)::bigint) = 0) THEN 'evidence'::text
            ELSE NULL::text
        END], NULL::text) AS missing_fields
   FROM (((public.partners p
     LEFT JOIN LATERAL ( SELECT count(*) AS contact_count,
            jsonb_agg(jsonb_build_object('id', pc.id, 'name', pc.full_name, 'email', pc.email, 'role', pc.role, 'language', pc.language, 'primary', pc.is_primary, 'source', pc.source) ORDER BY pc.is_primary DESC NULLS LAST, pc.created_at) AS contacts
           FROM public.partner_contacts pc
          WHERE (pc.partner_id = p.id)) ct ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS capability_count,
            max(c.confidence) AS max_confidence,
            jsonb_agg(jsonb_build_object('family', c.family, 'product_type', c.product_type, 'product_tags', c.product_tags, 'standards', c.standards, 'grades', c.grades, 'certifications', c.certifications, 'confidence', c.confidence, 'source', c.source, 'source_ref', c.source_ref) ORDER BY c.confidence DESC, c.family) AS capabilities
           FROM public.supplier_capabilities_v1 c
          WHERE ((c.partner_id = p.id) AND c.is_active)) cp ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS evidence_count,
            count(*) FILTER (WHERE (lower(e.source) = 'gmail'::text)) AS gmail_evidence_count,
            max(e.evidence_at) AS last_evidence_at,
            jsonb_agg(jsonb_build_object('source', e.source, 'source_ref', e.source_ref, 'type', e.evidence_type, 'summary', e.evidence_summary, 'direction', e.direction, 'at', e.evidence_at, 'confidence', e.confidence) ORDER BY e.evidence_at DESC NULLS LAST, e.created_at DESC) AS evidence
           FROM public.supplier_evidence_v1 e
          WHERE (e.partner_id = p.id)) ev ON (true))
  WHERE ((p.relation @> ARRAY['supplier'::text]) AND (COALESCE(p.stage, 'active'::text) <> 'archived'::text));


ALTER VIEW public.pppp_supplier_master_audit_v1 OWNER TO postgres;

--
-- Name: pppp_supplier_offer_comparison_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_supplier_offer_comparison_v1 WITH (security_invoker='true') AS
 WITH base AS (
         SELECT o.id AS offer_id,
            o.project_id,
            o.supplier,
            o.created_at,
            upper(COALESCE(NULLIF(btrim(o.currency), ''::text), 'UNKNOWN'::text)) AS currency,
            lower(COALESCE(NULLIF(btrim(o.pricing_unit), ''::text),
                CASE
                    WHEN (COALESCE(o.price_kg, (0)::numeric) > (0)::numeric) THEN 'kg'::text
                    WHEN (COALESCE(o.unit_price, (0)::numeric) > (0)::numeric) THEN 'unit'::text
                    WHEN (COALESCE(o.total_eur, o.total_amount, (0)::numeric) > (0)::numeric) THEN 'total'::text
                    ELSE 'unknown'::text
                END)) AS pricing_basis,
            o.price_kg,
            o.unit_price,
            o.total_amount,
            o.total_eur,
            o.qty_kg,
            o.delivery_weeks,
            o.incoterms,
            o.payment_terms,
            o.validity_days,
            o.cert,
            o.offer_ref,
            o.transport_eur,
            o.zinc_kg,
            o.exchange_rate_to_eur,
                CASE
                    WHEN (upper(COALESCE(NULLIF(btrim(o.currency), ''::text), 'UNKNOWN'::text)) = 'EUR'::text) THEN (1)::numeric
                    ELSE o.exchange_rate_to_eur
                END AS rate_to_eur
           FROM public.offers o
        ), calc AS (
         SELECT b.offer_id,
            b.project_id,
            b.supplier,
            b.created_at,
            b.currency,
            b.pricing_basis,
            b.price_kg,
            b.unit_price,
            b.total_amount,
            b.total_eur,
            b.qty_kg,
            b.delivery_weeks,
            b.incoterms,
            b.payment_terms,
            b.validity_days,
            b.cert,
            b.offer_ref,
            b.transport_eur,
            b.zinc_kg,
            b.exchange_rate_to_eur,
            b.rate_to_eur,
                CASE
                    WHEN ((COALESCE(b.price_kg, (0)::numeric) > (0)::numeric) AND (b.rate_to_eur IS NOT NULL)) THEN (b.price_kg * b.rate_to_eur)
                    WHEN ((COALESCE(b.unit_price, (0)::numeric) > (0)::numeric) AND (b.rate_to_eur IS NOT NULL)) THEN (b.unit_price * b.rate_to_eur)
                    WHEN (COALESCE(b.total_eur, (0)::numeric) > (0)::numeric) THEN b.total_eur
                    WHEN ((COALESCE(b.total_amount, (0)::numeric) > (0)::numeric) AND (b.rate_to_eur IS NOT NULL)) THEN (b.total_amount * b.rate_to_eur)
                    ELSE NULL::numeric
                END AS comparison_value_eur,
            (((((((
                CASE
                    WHEN (COALESCE(b.price_kg, b.unit_price, b.total_eur, b.total_amount) IS NOT NULL) THEN 30
                    ELSE 0
                END +
                CASE
                    WHEN ((b.rate_to_eur IS NOT NULL) OR (COALESCE(b.total_eur, (0)::numeric) > (0)::numeric)) THEN 15
                    ELSE 0
                END) +
                CASE
                    WHEN (NULLIF(btrim(COALESCE(b.incoterms, ''::text)), ''::text) IS NOT NULL) THEN 10
                    ELSE 0
                END) +
                CASE
                    WHEN (b.delivery_weeks IS NOT NULL) THEN 15
                    ELSE 0
                END) +
                CASE
                    WHEN (NULLIF(btrim(COALESCE(b.payment_terms, ''::text)), ''::text) IS NOT NULL) THEN 10
                    ELSE 0
                END) +
                CASE
                    WHEN (NULLIF(btrim(COALESCE(b.cert, ''::text)), ''::text) IS NOT NULL) THEN 10
                    ELSE 0
                END) +
                CASE
                    WHEN (b.validity_days IS NOT NULL) THEN 5
                    ELSE 0
                END) +
                CASE
                    WHEN (NULLIF(btrim(COALESCE(b.offer_ref, ''::text)), ''::text) IS NOT NULL) THEN 5
                    ELSE 0
                END) AS completeness_score
           FROM base b
        )
 SELECT offer_id,
    project_id,
    supplier,
    created_at,
    currency,
    pricing_basis,
    price_kg,
    unit_price,
    total_amount,
    total_eur,
    qty_kg,
    delivery_weeks,
    incoterms,
    payment_terms,
    validity_days,
    cert,
    offer_ref,
    transport_eur,
    zinc_kg,
    exchange_rate_to_eur,
    rate_to_eur,
    comparison_value_eur,
    completeness_score,
    ((comparison_value_eur IS NOT NULL) AND (comparison_value_eur > (0)::numeric) AND (pricing_basis <> 'unknown'::text)) AS comparable,
        CASE
            WHEN ((comparison_value_eur IS NOT NULL) AND (comparison_value_eur > (0)::numeric)) THEN dense_rank() OVER (PARTITION BY project_id, pricing_basis ORDER BY comparison_value_eur, created_at DESC)
            ELSE NULL::bigint
        END AS price_rank_within_basis,
    count(*) FILTER (WHERE ((comparison_value_eur IS NOT NULL) AND (comparison_value_eur > (0)::numeric))) OVER (PARTITION BY project_id, pricing_basis) AS comparable_count_in_basis
   FROM calc c;


ALTER VIEW public.pppp_supplier_offer_comparison_v1 OWNER TO postgres;

--
-- Name: supplier_offer_candidates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.supplier_offer_candidates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    candidate_key text NOT NULL,
    project_id uuid NOT NULL,
    gmail_message_id text,
    attachment_link_ids bigint[] DEFAULT '{}'::bigint[] NOT NULL,
    supplier_name text,
    supplier_email text,
    subject text,
    source_kind text DEFAULT 'email'::text NOT NULL,
    extracted jsonb DEFAULT '{}'::jsonb NOT NULL,
    raw_text text,
    confidence integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'review'::text NOT NULL,
    canonical_offer_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    reviewed_at timestamp with time zone,
    matched_rfq_id uuid,
    CONSTRAINT supplier_offer_candidates_confidence_check CHECK (((confidence >= 0) AND (confidence <= 100))),
    CONSTRAINT supplier_offer_candidates_source_kind_check CHECK ((source_kind = ANY (ARRAY['email'::text, 'attachment'::text, 'email_attachment'::text]))),
    CONSTRAINT supplier_offer_candidates_status_check CHECK ((status = ANY (ARRAY['review'::text, 'approved'::text, 'ignored'::text, 'superseded'::text])))
);


ALTER TABLE public.supplier_offer_candidates OWNER TO postgres;

--
-- Name: pppp_supplier_offer_review_intelligence_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_supplier_offer_review_intelligence_v1 WITH (security_invoker='true') AS
 WITH base AS (
         SELECT c_1.id AS candidate_id,
            c_1.project_id,
            p.name AS project_name,
            p.status AS project_status,
            p.pipeline_stage,
            p.operational_state,
            c_1.supplier_name,
            c_1.supplier_email,
            c_1.confidence,
            c_1.gmail_message_id,
            c_1.matched_rfq_id,
            c_1.created_at,
            COALESCE(( SELECT max(pe.sent_at) AS max
                   FROM public.project_emails pe
                  WHERE (pe.gmail_message_id = c_1.gmail_message_id)), c_1.created_at) AS source_at,
            NULLIF(upper(TRIM(BOTH FROM (c_1.extracted ->> 'currency'::text))), ''::text) AS currency,
                CASE
                    WHEN (COALESCE((c_1.extracted ->> 'price_kg'::text), ''::text) ~ '^[0-9]+([.][0-9]+)?$'::text) THEN ((c_1.extracted ->> 'price_kg'::text))::numeric
                    ELSE NULL::numeric
                END AS price_kg,
                CASE
                    WHEN (COALESCE((c_1.extracted ->> 'unit_price'::text), ''::text) ~ '^[0-9]+([.][0-9]+)?$'::text) THEN ((c_1.extracted ->> 'unit_price'::text))::numeric
                    ELSE NULL::numeric
                END AS unit_price,
            COALESCE(
                CASE
                    WHEN (COALESCE((c_1.extracted ->> 'total_amount'::text), ''::text) ~ '^[0-9]+([.][0-9]+)?$'::text) THEN ((c_1.extracted ->> 'total_amount'::text))::numeric
                    ELSE NULL::numeric
                END,
                CASE
                    WHEN ((COALESCE((c_1.extracted ->> 'total_eur'::text), ''::text) ~ '^[0-9]+([.][0-9]+)?$'::text) AND (upper(COALESCE((c_1.extracted ->> 'currency'::text), 'EUR'::text)) = 'EUR'::text)) THEN ((c_1.extracted ->> 'total_eur'::text))::numeric
                    ELSE NULL::numeric
                END) AS total_amount,
                CASE
                    WHEN (COALESCE((c_1.extracted ->> 'qty_kg'::text), ''::text) ~ '^[0-9]+([.][0-9]+)?$'::text) THEN ((c_1.extracted ->> 'qty_kg'::text))::numeric
                    ELSE NULL::numeric
                END AS qty_kg,
                CASE
                    WHEN (COALESCE((c_1.extracted ->> 'exchange_rate_to_eur'::text), ''::text) ~ '^[0-9]+([.][0-9]+)?$'::text) THEN ((c_1.extracted ->> 'exchange_rate_to_eur'::text))::numeric
                    ELSE NULL::numeric
                END AS exchange_rate_to_eur,
            NULLIF(lower(TRIM(BOTH FROM (c_1.extracted ->> 'pricing_unit'::text))), ''::text) AS extracted_pricing_unit,
            NULLIF(TRIM(BOTH FROM (c_1.extracted ->> 'incoterms'::text)), ''::text) AS incoterms,
            NULLIF(TRIM(BOTH FROM (c_1.extracted ->> 'payment_terms'::text)), ''::text) AS payment_terms,
                CASE
                    WHEN (COALESCE((c_1.extracted ->> 'validity_days'::text), ''::text) ~ '^[0-9]+$'::text) THEN ((c_1.extracted ->> 'validity_days'::text))::integer
                    ELSE NULL::integer
                END AS validity_days,
                CASE
                    WHEN (COALESCE((c_1.extracted ->> 'delivery_weeks'::text), ''::text) ~ '^[0-9]+([.][0-9]+)?$'::text) THEN ((c_1.extracted ->> 'delivery_weeks'::text))::numeric
                    ELSE NULL::numeric
                END AS delivery_weeks,
            NULLIF(TRIM(BOTH FROM (c_1.extracted ->> 'cert'::text)), ''::text) AS cert,
            NULLIF(TRIM(BOTH FROM (c_1.extracted ->> 'offer_ref'::text)), ''::text) AS offer_ref,
                CASE
                    WHEN (jsonb_typeof((c_1.extracted -> 'source_attachment_names'::text)) = 'array'::text) THEN (c_1.extracted -> 'source_attachment_names'::text)
                    ELSE '[]'::jsonb
                END AS attachments
           FROM (public.supplier_offer_candidates c_1
             JOIN public.projects p ON ((p.id = c_1.project_id)))
          WHERE (c_1.status = 'review'::text)
        ), ranked AS (
         SELECT b.candidate_id,
            b.project_id,
            b.project_name,
            b.project_status,
            b.pipeline_stage,
            b.operational_state,
            b.supplier_name,
            b.supplier_email,
            b.confidence,
            b.gmail_message_id,
            b.matched_rfq_id,
            b.created_at,
            b.source_at,
            b.currency,
            b.price_kg,
            b.unit_price,
            b.total_amount,
            b.qty_kg,
            b.exchange_rate_to_eur,
            b.extracted_pricing_unit,
            b.incoterms,
            b.payment_terms,
            b.validity_days,
            b.delivery_weeks,
            b.cert,
            b.offer_ref,
            b.attachments,
            count(*) OVER (PARTITION BY b.project_id, (lower(COALESCE(NULLIF(b.supplier_email, ''::text), NULLIF(b.supplier_name, ''::text), '?'::text)))) AS same_supplier_review_count,
            row_number() OVER (PARTITION BY b.project_id, (lower(COALESCE(NULLIF(b.supplier_email, ''::text), NULLIF(b.supplier_name, ''::text), '?'::text))) ORDER BY b.source_at DESC, b.created_at DESC, b.candidate_id DESC) AS revision_rank
           FROM base b
        ), calc AS (
         SELECT r.candidate_id,
            r.project_id,
            r.project_name,
            r.project_status,
            r.pipeline_stage,
            r.operational_state,
            r.supplier_name,
            r.supplier_email,
            r.confidence,
            r.gmail_message_id,
            r.matched_rfq_id,
            r.created_at,
            r.source_at,
            r.currency,
            r.price_kg,
            r.unit_price,
            r.total_amount,
            r.qty_kg,
            r.exchange_rate_to_eur,
            r.extracted_pricing_unit,
            r.incoterms,
            r.payment_terms,
            r.validity_days,
            r.delivery_weeks,
            r.cert,
            r.offer_ref,
            r.attachments,
            r.same_supplier_review_count,
            r.revision_rank,
                CASE
                    WHEN (COALESCE(r.price_kg, (0)::numeric) > (0)::numeric) THEN 'kg'::text
                    WHEN (COALESCE(r.unit_price, (0)::numeric) > (0)::numeric) THEN COALESCE(r.extracted_pricing_unit, 'unit'::text)
                    WHEN (COALESCE(r.total_amount, (0)::numeric) > (0)::numeric) THEN 'total'::text
                    ELSE COALESCE(r.extracted_pricing_unit, 'unknown'::text)
                END AS pricing_basis,
                CASE
                    WHEN ((COALESCE(r.price_kg, (0)::numeric) > (0)::numeric) AND (COALESCE(r.total_amount, (0)::numeric) > (0)::numeric)) THEN (r.total_amount / r.price_kg)
                    ELSE NULL::numeric
                END AS implied_qty_kg,
                CASE
                    WHEN ((COALESCE(r.price_kg, (0)::numeric) > (0)::numeric) AND (COALESCE(r.total_amount, (0)::numeric) > (0)::numeric) AND (COALESCE(r.qty_kg, (0)::numeric) > (0)::numeric)) THEN (abs((r.qty_kg - (r.total_amount / r.price_kg))) / GREATEST(r.qty_kg, (r.total_amount / r.price_kg)))
                    ELSE NULL::numeric
                END AS qty_relative_mismatch,
            (r.currency IS NULL) AS missing_currency,
            ((COALESCE(r.price_kg, (0)::numeric) <= (0)::numeric) AND (COALESCE(r.unit_price, (0)::numeric) <= (0)::numeric) AND (COALESCE(r.total_amount, (0)::numeric) <= (0)::numeric)) AS missing_commercial_value,
            ((upper(COALESCE(r.currency, ''::text)) <> ALL (ARRAY[''::text, 'EUR'::text])) AND (COALESCE(r.exchange_rate_to_eur, (0)::numeric) <= (0)::numeric)) AS non_eur_missing_fx,
            (r.same_supplier_review_count > 1) AS possible_revision,
            (r.revision_rank = 1) AS latest_revision,
            ((jsonb_array_length(r.attachments) = 0) OR (NOT (EXISTS ( SELECT 1
                   FROM jsonb_array_elements_text(r.attachments) a(v)
                  WHERE (lower(a.v) ~ '(quot|offer|ponud|price|commercial|proposal|quotation)'::text))))) AS attachment_quote_evidence_missing
           FROM ranked r
        )
 SELECT candidate_id,
    project_id,
    project_name,
    project_status,
    pipeline_stage,
    operational_state,
    supplier_name,
    supplier_email,
    confidence,
    gmail_message_id,
    matched_rfq_id,
    created_at,
    source_at,
    currency,
    price_kg,
    unit_price,
    total_amount,
    qty_kg,
    exchange_rate_to_eur,
    extracted_pricing_unit,
    incoterms,
    payment_terms,
    validity_days,
    delivery_weeks,
    cert,
    offer_ref,
    attachments,
    same_supplier_review_count,
    revision_rank,
    pricing_basis,
    implied_qty_kg,
    qty_relative_mismatch,
    missing_currency,
    missing_commercial_value,
    non_eur_missing_fx,
    possible_revision,
    latest_revision,
    attachment_quote_evidence_missing,
    (COALESCE(qty_relative_mismatch, (0)::numeric) > 0.20) AS quantity_total_mismatch,
    (delivery_weeks IS NULL) AS missing_delivery,
    (incoterms IS NULL) AS missing_incoterms,
    (payment_terms IS NULL) AS missing_payment_terms,
    (validity_days IS NULL) AS missing_validity,
    (cert IS NULL) AS missing_cert,
        CASE
            WHEN (missing_currency OR missing_commercial_value OR (COALESCE(qty_relative_mismatch, (0)::numeric) > 0.20)) THEN 'blocked'::text
            ELSE 'review'::text
        END AS approval_readiness,
        CASE
            WHEN (missing_currency OR missing_commercial_value OR (COALESCE(qty_relative_mismatch, (0)::numeric) > 0.20) OR non_eur_missing_fx) THEN 'blocked'::text
            ELSE 'review'::text
        END AS comparison_readiness,
    ((lower(COALESCE(project_status, ''::text)) <> ALL (ARRAY['humbur'::text, 'lost'::text, 'mbyllur'::text, 'closed'::text, 'arkivuar'::text, 'archived'::text, 'realizuar'::text, 'cancelled'::text, 'canceled'::text])) AND (COALESCE(operational_state, ''::text) <> ALL (ARRAY['wait_for_client'::text, 'execution'::text]))) AS eligible_for_review_task,
    concat_ws(' | '::text,
        CASE
            WHEN missing_currency THEN 'BLOCKER: currency missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN missing_commercial_value THEN 'BLOCKER: commercial price/total not extracted'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (COALESCE(qty_relative_mismatch, (0)::numeric) > 0.20) THEN (((((('BLOCKER: extracted qty '::text || (round(qty_kg, 3))::text) || ' kg conflicts with total/price implied '::text) || (round(implied_qty_kg, 3))::text) || ' kg ('::text) || (round((qty_relative_mismatch * (100)::numeric), 1))::text) || '% mismatch); verify quantity/unit and whether total includes fabrication/erection'::text)
            ELSE NULL::text
        END,
        CASE
            WHEN non_eur_missing_fx THEN 'Comparison: non-EUR offer has no reviewed FX rate'::text
            ELSE NULL::text
        END,
        CASE
            WHEN possible_revision THEN
            CASE
                WHEN latest_revision THEN (('Revision: latest of '::text || (same_supplier_review_count)::text) || ' review candidates from this supplier; verify whether it replaces earlier terms'::text)
                ELSE (('Revision: earlier of '::text || (same_supplier_review_count)::text) || ' review candidates from this supplier; do not assume it is still current'::text)
            END
            ELSE NULL::text
        END,
        CASE
            WHEN attachment_quote_evidence_missing THEN 'Evidence: no quotation-like attachment detected; verify original email/source before approval'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (delivery_weeks IS NULL) THEN 'Missing: delivery'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (incoterms IS NULL) THEN 'Missing: Incoterms'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (payment_terms IS NULL) THEN 'Missing: payment terms'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (validity_days IS NULL) THEN 'Missing: validity'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (cert IS NULL) THEN 'Missing: certificate/quality term'::text
            ELSE NULL::text
        END) AS warning_text
   FROM calc c;


ALTER VIEW public.pppp_supplier_offer_review_intelligence_v1 OWNER TO postgres;

--
-- Name: supplier_identity_candidates_v1; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.supplier_identity_candidates_v1 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    identity_key text NOT NULL,
    company_name text,
    company_domain text,
    country text,
    primary_email text,
    contact_name text,
    source_contact_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    contact_kinds text[] DEFAULT '{}'::text[] NOT NULL,
    procurement_messages integer DEFAULT 0 NOT NULL,
    incoming_offer_signals integer DEFAULT 0 NOT NULL,
    outgoing_rfq_signals integer DEFAULT 0 NOT NULL,
    first_evidence_at timestamp with time zone,
    last_evidence_at timestamp with time zone,
    linked_partner_id uuid,
    identity_status text DEFAULT 'review'::text NOT NULL,
    profile_status text DEFAULT 'unknown'::text NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.supplier_identity_candidates_v1 OWNER TO postgres;

--
-- Name: pppp_supplier_profile_status_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_supplier_profile_status_v1 WITH (security_invoker='true') AS
 SELECT s.id,
    s.identity_key,
    s.company_name,
    s.company_domain,
    s.country,
    s.primary_email,
    s.contact_name,
    s.linked_partner_id,
    p.name AS partner_name,
    p.stage AS partner_stage,
    p.business_type,
    p.categories,
    p.grades,
    p.certifications,
    p.data_confidence,
    s.procurement_messages,
    s.incoming_offer_signals,
    s.outgoing_rfq_signals,
    s.first_evidence_at,
    s.last_evidence_at,
    s.identity_status,
    s.profile_status,
    s.evidence,
    COALESCE(( SELECT count(*) AS count
           FROM public.supplier_capabilities_v1 sc
          WHERE ((sc.partner_id = s.linked_partner_id) AND sc.is_active)), (0)::bigint) AS capability_rows,
        CASE
            WHEN ((s.linked_partner_id IS NULL) AND (s.procurement_messages > 0)) THEN 'register_supplier_master'::text
            WHEN ((s.linked_partner_id IS NOT NULL) AND (COALESCE(( SELECT count(*) AS count
               FROM public.supplier_capabilities_v1 sc
              WHERE ((sc.partner_id = s.linked_partner_id) AND sc.is_active AND (sc.confidence >= 70))), (0)::bigint) = 0)) THEN 'enrich_profile'::text
            WHEN (s.linked_partner_id IS NOT NULL) THEN 'ready_or_review_details'::text
            ELSE 'review_identity'::text
        END AS recommended_action
   FROM (public.supplier_identity_candidates_v1 s
     LEFT JOIN public.partners p ON ((p.id = s.linked_partner_id)));


ALTER VIEW public.pppp_supplier_profile_status_v1 OWNER TO postgres;

