--
-- Name: pppp_supplier_relationship_health_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_supplier_relationship_health_v1 WITH (security_invoker='true') AS
 WITH partner_map AS (
         SELECT p.id AS partner_id,
            p.name AS canonical_supplier,
            p.importance,
            p.stage,
            regexp_replace(lower(p.name), '[^a-z0-9]+'::text, ''::text, 'g'::text) AS key
           FROM public.partners p
        UNION ALL
         SELECT p.id,
            p.name,
            p.importance,
            p.stage,
            regexp_replace(lower(a.a), '[^a-z0-9]+'::text, ''::text, 'g'::text) AS regexp_replace
           FROM (public.partners p
             CROSS JOIN LATERAL unnest(COALESCE(p.aliases, ARRAY[]::text[])) a(a))
        ), rfq_raw AS (
         SELECT r_1.id,
            r_1.created_at,
            r_1.project_id,
            r_1.project_name,
            r_1.supplier_name,
            r_1.supplier_email,
            r_1.lang,
            r_1.subject,
            r_1.body,
            r_1.sent_at,
            r_1.status,
            r_1.followup_count,
            r_1.last_followup_at,
            r_1.replied_at,
            r_1.offer_id,
            r_1.notes,
            r_1.rfq_mode,
            r_1.supplier_relationship_state,
            r_1.supplier_gate_snapshot,
            r_1.human_send_required,
            regexp_replace(lower(COALESCE(r_1.supplier_name, ''::text)), '[^a-z0-9]+'::text, ''::text, 'g'::text) AS raw_key
           FROM public.rfq_log r_1
          WHERE ((r_1.sent_at IS NOT NULL) AND (COALESCE(r_1.supplier_name, ''::text) <> ''::text) AND (lower(COALESCE(r_1.supplier_name, ''::text)) <> ALL (ARRAY['gmail'::text, 'hotmail'::text])))
        ), rfq_mapped AS (
         SELECT r_1.id,
            r_1.created_at,
            r_1.project_id,
            r_1.project_name,
            r_1.supplier_name,
            r_1.supplier_email,
            r_1.lang,
            r_1.subject,
            r_1.body,
            r_1.sent_at,
            r_1.status,
            r_1.followup_count,
            r_1.last_followup_at,
            r_1.replied_at,
            r_1.offer_id,
            r_1.notes,
            r_1.rfq_mode,
            r_1.supplier_relationship_state,
            r_1.supplier_gate_snapshot,
            r_1.human_send_required,
            r_1.raw_key,
            COALESCE(pm.canonical_supplier, r_1.supplier_name) AS canonical_supplier,
            pm.partner_id,
            pm.importance,
            pm.stage AS partner_stage
           FROM (rfq_raw r_1
             LEFT JOIN LATERAL ( SELECT m.partner_id,
                    m.canonical_supplier,
                    m.importance,
                    m.stage,
                    m.key
                   FROM partner_map m
                  WHERE ((r_1.raw_key = m.key) OR ((length(m.key) >= 5) AND (r_1.raw_key ~~ (m.key || '%'::text))) OR ((length(r_1.raw_key) >= 5) AND (m.key ~~ (r_1.raw_key || '%'::text))))
                  ORDER BY
                        CASE
                            WHEN (r_1.raw_key = m.key) THEN 0
                            ELSE 1
                        END, (length(m.key)) DESC
                 LIMIT 1) pm ON (true))
        ), rfq AS (
         SELECT rfq_mapped.canonical_supplier,
            (array_agg(rfq_mapped.partner_id) FILTER (WHERE (rfq_mapped.partner_id IS NOT NULL)))[1] AS partner_id,
            max(rfq_mapped.importance) AS importance,
            max(rfq_mapped.partner_stage) AS partner_stage,
            count(*) AS sent_rfqs,
            count(*) FILTER (WHERE ((rfq_mapped.replied_at IS NOT NULL) OR (rfq_mapped.offer_id IS NOT NULL))) AS answered_rfqs,
            count(DISTINCT rfq_mapped.project_id) AS rfq_projects,
            max(rfq_mapped.sent_at) AS last_rfq_sent_at,
            count(*) FILTER (WHERE (rfq_mapped.sent_at >= (now() - '90 days'::interval))) AS sent_rfqs_90d
           FROM rfq_mapped
          GROUP BY rfq_mapped.canonical_supplier
        ), offers_raw AS (
         SELECT o_1.id,
            o_1.project_id,
            o_1.created_at,
            o_1.supplier,
            o_1.price_kg,
            o_1.total_eur,
            o_1.delivery_weeks,
            o_1.incoterms,
            o_1.cert,
            o_1.notes,
            o_1.score,
            o_1.origin,
            o_1.zinc_kg,
            o_1.transport_eur,
            o_1.vat_pct,
            o_1.qty_kg,
            o_1.positions,
            o_1.currency,
            o_1.pricing_unit,
            o_1.payment_terms,
            o_1.inclusions,
            o_1.exclusions,
            o_1.validity_days,
            o_1.offer_ref,
            o_1.contact_person,
            o_1.raw_text,
            o_1.exchange_rate_to_eur,
            o_1.total_amount,
            o_1.unit_price,
            regexp_replace(lower(COALESCE(o_1.supplier, ''::text)), '[^a-z0-9]+'::text, ''::text, 'g'::text) AS raw_key
           FROM public.offers o_1
          WHERE (COALESCE(o_1.supplier, ''::text) <> ''::text)
        ), offer_mapped AS (
         SELECT o_1.id,
            o_1.project_id,
            o_1.created_at,
            o_1.supplier,
            o_1.price_kg,
            o_1.total_eur,
            o_1.delivery_weeks,
            o_1.incoterms,
            o_1.cert,
            o_1.notes,
            o_1.score,
            o_1.origin,
            o_1.zinc_kg,
            o_1.transport_eur,
            o_1.vat_pct,
            o_1.qty_kg,
            o_1.positions,
            o_1.currency,
            o_1.pricing_unit,
            o_1.payment_terms,
            o_1.inclusions,
            o_1.exclusions,
            o_1.validity_days,
            o_1.offer_ref,
            o_1.contact_person,
            o_1.raw_text,
            o_1.exchange_rate_to_eur,
            o_1.total_amount,
            o_1.unit_price,
            o_1.raw_key,
            pm.canonical_supplier
           FROM (offers_raw o_1
             JOIN LATERAL ( SELECT m.partner_id,
                    m.canonical_supplier,
                    m.importance,
                    m.stage,
                    m.key
                   FROM partner_map m
                  WHERE ((o_1.raw_key = m.key) OR ((length(m.key) >= 5) AND (o_1.raw_key ~~ (m.key || '%'::text))) OR ((length(o_1.raw_key) >= 5) AND (m.key ~~ (o_1.raw_key || '%'::text))))
                  ORDER BY
                        CASE
                            WHEN (o_1.raw_key = m.key) THEN 0
                            ELSE 1
                        END, (length(m.key)) DESC
                 LIMIT 1) pm ON (true))
        ), offers_agg AS (
         SELECT offer_mapped.canonical_supplier,
            count(*) AS supplier_offers,
            count(DISTINCT offer_mapped.project_id) AS offer_projects,
            max(offer_mapped.created_at) AS last_offer_at
           FROM offer_mapped
          GROUP BY offer_mapped.canonical_supplier
        ), decisions_raw AS (
         SELECT d.id,
            d.project_id,
            d.supplier_offer_id,
            d.supplier_name,
            d.decision_type,
            d.status,
            d.source,
            d.evidence,
            d.notes,
            d.decided_at,
            d.created_at,
            d.updated_at,
            regexp_replace(lower(COALESCE(d.supplier_name, ''::text)), '[^a-z0-9]+'::text, ''::text, 'g'::text) AS raw_key
           FROM public.project_supplier_decisions d
          WHERE ((d.decision_type = 'selected_producer'::text) AND (COALESCE(d.supplier_name, ''::text) <> ''::text))
        ), decisions_mapped AS (
         SELECT d.id,
            d.project_id,
            d.supplier_offer_id,
            d.supplier_name,
            d.decision_type,
            d.status,
            d.source,
            d.evidence,
            d.notes,
            d.decided_at,
            d.created_at,
            d.updated_at,
            d.raw_key,
            COALESCE(pm.canonical_supplier, d.supplier_name) AS canonical_supplier
           FROM (decisions_raw d
             LEFT JOIN LATERAL ( SELECT m.partner_id,
                    m.canonical_supplier,
                    m.importance,
                    m.stage,
                    m.key
                   FROM partner_map m
                  WHERE ((d.raw_key = m.key) OR ((length(m.key) >= 5) AND (d.raw_key ~~ (m.key || '%'::text))) OR ((length(d.raw_key) >= 5) AND (m.key ~~ (d.raw_key || '%'::text))))
                  ORDER BY
                        CASE
                            WHEN (d.raw_key = m.key) THEN 0
                            ELSE 1
                        END, (length(m.key)) DESC
                 LIMIT 1) pm ON (true))
        ), realized AS (
         SELECT decisions_mapped.canonical_supplier,
            count(*) AS realized_orders,
            count(DISTINCT decisions_mapped.project_id) AS realized_projects,
            max(decisions_mapped.decided_at) AS last_realization_at
           FROM decisions_mapped
          GROUP BY decisions_mapped.canonical_supplier
        ), names AS (
         SELECT rfq.canonical_supplier
           FROM rfq
        UNION
         SELECT offers_agg.canonical_supplier
           FROM offers_agg
        UNION
         SELECT realized.canonical_supplier
           FROM realized
        )
 SELECT n.canonical_supplier AS supplier_name,
    r.partner_id,
    r.importance,
    r.partner_stage,
    COALESCE(r.sent_rfqs, (0)::bigint) AS sent_rfqs,
    COALESCE(r.sent_rfqs_90d, (0)::bigint) AS sent_rfqs_90d,
    COALESCE(r.answered_rfqs, (0)::bigint) AS answered_rfqs,
    COALESCE(o.supplier_offers, (0)::bigint) AS supplier_offers,
    COALESCE(z.realized_orders, (0)::bigint) AS realized_orders,
    COALESCE(r.rfq_projects, (0)::bigint) AS rfq_projects,
    COALESCE(o.offer_projects, (0)::bigint) AS offer_projects,
    COALESCE(z.realized_projects, (0)::bigint) AS realized_projects,
    r.last_rfq_sent_at,
    o.last_offer_at,
    z.last_realization_at,
    round(((100.0 * (COALESCE(r.answered_rfqs, (0)::bigint))::numeric) / (NULLIF(COALESCE(r.sent_rfqs, (0)::bigint), 0))::numeric), 1) AS response_rate_pct,
    round(((100.0 * (COALESCE(z.realized_orders, (0)::bigint))::numeric) / (NULLIF(COALESCE(r.sent_rfqs, (0)::bigint), 0))::numeric), 1) AS sent_to_order_rate_pct,
        CASE
            WHEN ((COALESCE(r.sent_rfqs, (0)::bigint) > 0) AND (r.last_rfq_sent_at < (now() - '120 days'::interval))) THEN 'dormant'::text
            WHEN ((COALESCE(z.realized_orders, (0)::bigint) > 0) AND (COALESCE(r.importance, 0) >= 4)) THEN 'strategic'::text
            WHEN ((COALESCE(r.sent_rfqs_90d, (0)::bigint) >= 5) AND (COALESCE(z.realized_orders, (0)::bigint) = 0)) THEN 'fatigue_risk'::text
            WHEN ((COALESCE(r.sent_rfqs_90d, (0)::bigint) >= 3) AND (COALESCE(z.realized_orders, (0)::bigint) = 0)) THEN 'watch'::text
            ELSE 'healthy'::text
        END AS relationship_state,
        CASE
            WHEN ((COALESCE(r.sent_rfqs_90d, (0)::bigint) >= 5) AND (COALESCE(z.realized_orders, (0)::bigint) = 0)) THEN 'Protect relationship: use only for a qualified firm RFQ, not exploratory pricing.'::text
            WHEN ((COALESCE(r.sent_rfqs_90d, (0)::bigint) >= 3) AND (COALESCE(z.realized_orders, (0)::bigint) = 0)) THEN 'Review project qualification before requesting another detailed quotation.'::text
            WHEN (COALESCE(z.realized_orders, (0)::bigint) > 0) THEN 'Established commercial history; continue sending only scope-fit RFQs.'::text
            ELSE 'No current fatigue signal from sent RFQs.'::text
        END AS relationship_guidance
   FROM (((names n
     LEFT JOIN rfq r USING (canonical_supplier))
     LEFT JOIN offers_agg o USING (canonical_supplier))
     LEFT JOIN realized z USING (canonical_supplier));


ALTER VIEW public.pppp_supplier_relationship_health_v1 OWNER TO postgres;

