--
-- Name: pppp_ted_sales_outreach_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_ted_sales_outreach_v1 WITH (security_invoker='true') AS
 SELECT k.id AS tender_watch_id,
    k.publication_no,
    k.procurement_no,
    k.published_date,
    k.authority,
    k.title,
    k.category,
    k.relevance_score,
    k.status AS opportunity_status,
    k.project_id,
    (k.payload #>> '{winner,name}'::text[]) AS winner_name,
    COALESCE(NULLIF(oc.company_type, ''::text), (k.payload #>> '{winner,company_type}'::text[]), 'unknown'::text) AS winner_company_type,
    COALESCE(NULLIF(oc.cooperation_angle, ''::text), (k.payload ->> 'cooperation_angle'::text)) AS cooperation_angle,
    COALESCE(((k.payload ->> 'human_action_required'::text))::boolean, false) AS human_action_required,
    (NULLIF((k.payload ->> 'next_check_on'::text), ''::text))::date AS next_check_on,
    oc.company_name,
    oc.contact_email,
    oc.company_domain,
    oc.touch_1,
    oc.touch_2,
    oc.touch_3,
    oc.status AS outreach_status,
    oc.replied,
    oc.meeting,
    oc.bounced,
    oc.closed,
    oc.follow_up_date,
    oc.gmail_message_id AS outreach_gmail_message_id,
    oc.gmail_thread_id AS outreach_gmail_thread_id,
    le.gmail_message_id AS latest_gmail_message_id,
    le.gmail_thread_id AS latest_gmail_thread_id,
    le.direction AS latest_email_direction,
    le.subject AS latest_email_subject,
    le.sent_at AS latest_email_at,
    le.gmail_url AS latest_gmail_url,
    le.match_method AS latest_email_match_method,
    le.match_confidence AS latest_email_match_confidence,
    ( SELECT count(*) AS count
           FROM public.tender_email_links telc
          WHERE (telc.tender_watch_id = k.id)) AS linked_email_count,
    COALESCE((k.payload #>> '{winner,company_type}'::text[]), 'unknown'::text) AS source_winner_company_type,
    oc.outreach_kind
   FROM ((public.kek_tender_watch k
     LEFT JOIN LATERAL ( SELECT o.id,
            o.master_no,
            o.company_domain,
            o.contact_email,
            o.country,
            o.touch_1,
            o.touch_2,
            o.touch_3,
            o.status,
            o.bounced,
            o.replied,
            o.meeting,
            o.closed,
            o.follow_up_date,
            o.notes,
            o.created_at,
            o.updated_at,
            o.tender_watch_id,
            o.gmail_thread_id,
            o.gmail_message_id,
            o.company_name,
            o.source,
            o.company_type,
            o.cooperation_angle,
            o.outreach_kind
           FROM public.outreach_contacts o
          WHERE (o.tender_watch_id = k.id)
          ORDER BY COALESCE(o.touch_3, o.touch_2, o.touch_1) DESC NULLS LAST, o.updated_at DESC NULLS LAST, o.id DESC
         LIMIT 1) oc ON (true))
     LEFT JOIN LATERAL ( SELECT pe.id,
            pe.project_id,
            pe.suggested_project_id,
            pe.gmail_message_id,
            pe.gmail_thread_id,
            pe.rfc822_message_id,
            pe.from_email,
            pe.from_name,
            pe.to_emails,
            pe.cc_emails,
            pe.subject,
            pe.snippet,
            pe.sent_at,
            pe.direction,
            pe.has_attachments,
            pe.gmail_url,
            pe.match_method,
            pe.match_confidence,
            pe.created_at,
            pe.updated_at,
            pe.needs_review,
            pe.review_reason,
            pe.body_hydrated_at,
            pe.body_hydration_method,
            pe.tender_watch_id
           FROM (public.tender_email_links tel
             JOIN public.project_emails pe ON ((pe.gmail_message_id = tel.gmail_message_id)))
          WHERE (tel.tender_watch_id = k.id)
          ORDER BY pe.sent_at DESC, pe.id DESC
         LIMIT 1) le ON (true))
  WHERE ((upper(COALESCE((k.payload ->> 'source'::text), ''::text)) = 'TED'::text) AND (COALESCE((k.payload ->> 'notice_phase'::text), ''::text) = 'award'::text));


ALTER VIEW public.pppp_ted_sales_outreach_v1 OWNER TO postgres;

--
-- Name: pppp_tender_watch_company_role_v2; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_tender_watch_company_role_v2 WITH (security_invoker='true') AS
 SELECT id,
    created_at,
    updated_at,
    first_seen_at,
    last_seen_at,
    source_key,
    procurement_no,
    publication_no,
    authority,
    title,
    document_type,
    fpp,
    fpp_description,
    contract_type,
    contract_value_band,
    procedure,
    estimated_value,
    currency,
    deadline,
    published_date,
    is_retender,
    category,
    relevance_score,
    match_reasons,
    status,
    project_id,
    source_url,
    detail_url,
    payload,
        CASE
            WHEN ((upper(COALESCE((payload ->> 'source'::text), ''::text)) = 'TED'::text) AND (COALESCE((payload ->> 'notice_phase'::text), ''::text) = 'award'::text) AND (jsonb_typeof((payload -> 'winner'::text)) = 'object'::text)) THEN public.pppp_ted_company_role_context_v2((payload -> 'winner'::text), COALESCE((payload -> 'award_role'::text), '{}'::jsonb))
            ELSE NULL::jsonb
        END AS winner_role_v2
   FROM public.kek_tender_watch k;


