--
-- Name: pppp_ted_sales_outreach_role_v2; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_ted_sales_outreach_role_v2 WITH (security_invoker='true') AS
 SELECT s.tender_watch_id,
    s.publication_no,
    s.procurement_no,
    s.published_date,
    s.authority,
    s.title,
    s.category,
    s.relevance_score,
    s.opportunity_status,
    s.project_id,
    s.winner_name,
    s.winner_company_type,
    s.cooperation_angle,
    s.human_action_required,
    s.next_check_on,
    s.company_name,
    s.contact_email,
    s.company_domain,
    s.touch_1,
    s.touch_2,
    s.touch_3,
    s.outreach_status,
    s.replied,
    s.meeting,
    s.bounced,
    s.closed,
    s.follow_up_date,
    s.outreach_gmail_message_id,
    s.outreach_gmail_thread_id,
    s.latest_gmail_message_id,
    s.latest_gmail_thread_id,
    s.latest_email_direction,
    s.latest_email_subject,
    s.latest_email_at,
    s.latest_gmail_url,
    s.latest_email_match_method,
    s.latest_email_match_confidence,
    s.linked_email_count,
    s.source_winner_company_type,
    s.outreach_kind,
    r.winner_role_v2
   FROM (public.pppp_ted_sales_outreach_v1 s
     JOIN public.pppp_tender_watch_company_role_v2 r ON ((r.id = s.tender_watch_id)));


ALTER VIEW public.pppp_ted_sales_outreach_role_v2 OWNER TO postgres;

--
-- Name: pppp_ted_sales_outreach_v2; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_ted_sales_outreach_v2 WITH (security_invoker='true') AS
 SELECT v.tender_watch_id,
    v.publication_no,
    v.procurement_no,
    v.published_date,
    v.authority,
    v.title,
    v.category,
    v.relevance_score,
    v.opportunity_status,
    v.project_id,
    v.winner_name,
    v.winner_company_type,
    v.cooperation_angle,
    v.human_action_required,
    v.next_check_on,
    v.company_name,
    v.contact_email,
    v.company_domain,
    v.touch_1,
    v.touch_2,
    v.touch_3,
    v.outreach_status,
    v.replied,
    v.meeting,
    v.bounced,
    v.closed,
    v.follow_up_date,
    v.outreach_gmail_message_id,
    v.outreach_gmail_thread_id,
    v.latest_gmail_message_id,
    v.latest_gmail_thread_id,
    v.latest_email_direction,
    v.latest_email_subject,
    v.latest_email_at,
    v.latest_gmail_url,
    v.latest_email_match_method,
    v.latest_email_match_confidence,
    v.linked_email_count,
    v.source_winner_company_type,
    v.outreach_kind,
    (seg.segment ->> 'category'::text) AS company_segment,
    (seg.segment ->> 'label'::text) AS company_segment_label,
    (seg.segment ->> 'confidence'::text) AS company_segment_confidence,
    ((seg.segment ->> 'score'::text))::integer AS company_segment_score,
    (seg.segment ->> 'source'::text) AS company_segment_source,
    (seg.segment -> 'evidence'::text) AS company_segment_evidence,
        CASE
            WHEN (lower(COALESCE(v.contact_email, ''::text)) ~ '(procurement|purchasing|einkauf|tender|vergabe)'::text) THEN 'procurement'::text
            WHEN (lower(COALESCE(v.contact_email, ''::text)) ~ '(technical|technik|engineering)'::text) THEN 'technical'::text
            WHEN (lower(COALESCE(v.contact_email, ''::text)) ~ '(project|projekt)'::text) THEN 'project'::text
            WHEN (lower(COALESCE(v.contact_email, ''::text)) ~ '(sales|commercial|verkauf)'::text) THEN 'commercial'::text
            WHEN (v.contact_email IS NOT NULL) THEN 'general'::text
            ELSE NULL::text
        END AS contact_functional_role,
        CASE
            WHEN (lower(COALESCE(((k.payload #> '{winner,company_classification,evidence}'::text[]))::text, ''::text)) ~ '(multiple awarded organizations|consortium members classified separately)'::text) THEN 'multi_award_or_consortium'::text
            WHEN (lower(COALESCE(v.winner_name, ''::text)) ~ '(consortium|konsortium|joint[ -]?venture|arbeitsgemeinschaft|(^|[^a-z])arge([^a-z]|$)|bige )'::text) THEN 'explicit_jv_entity'::text
            ELSE 'single_or_unspecified'::text
        END AS award_structure
   FROM ((public.pppp_ted_sales_outreach_v1 v
     JOIN public.kek_tender_watch k ON ((k.id = v.tender_watch_id)))
     CROSS JOIN LATERAL ( SELECT public.pppp_ted_company_segment_v3(COALESCE(NULLIF(v.company_name, ''::text), NULLIF(v.winner_name, ''::text)), v.company_domain, COALESCE(NULLIF(v.winner_company_type, ''::text), NULLIF(v.source_winner_company_type, ''::text)), k.title, COALESCE((k.payload ->> 'scope'::text), (k.payload ->> 'description'::text), k.fpp_description, ''::text), COALESCE((k.payload #> '{winner,company_classification,evidence}'::text[]), '[]'::jsonb), v.cooperation_angle) AS segment) seg);


ALTER VIEW public.pppp_ted_sales_outreach_v2 OWNER TO postgres;

