--
-- Name: pppp_tender_operating_lanes_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_tender_operating_lanes_v1 WITH (security_invoker='true') AS
 SELECT k.id,
    k.created_at,
    k.updated_at,
    k.first_seen_at,
    k.last_seen_at,
    k.source_key,
    k.procurement_no,
    k.publication_no,
    k.authority,
    k.title,
    k.document_type,
    k.fpp,
    k.fpp_description,
    k.contract_type,
    k.contract_value_band,
    k.procedure,
    k.estimated_value,
    k.currency,
    k.deadline,
    k.published_date,
    k.is_retender,
    k.category,
    k.relevance_score,
    k.match_reasons,
    k.status,
    k.project_id,
    k.source_url,
    k.detail_url,
    k.payload,
        CASE
            WHEN ((upper(COALESCE((k.payload ->> 'source'::text), 'KRPP'::text)) = ANY (ARRAY['KRPP'::text, 'APP'::text, 'APP_AL'::text, 'MCA_KOSOVO'::text, 'KCF'::text, 'RCF'::text, 'EBRD_ECEPP'::text, 'WORLD_BANK'::text, 'UNGM'::text, 'UNDP_KOSOVO'::text, 'EU_OFFICE_KOSOVO'::text])) AND ((COALESCE((k.payload ->> 'workflow_mode'::text), ''::text) = 'program_monitoring'::text) OR (COALESCE((k.payload ->> 'recommended_lane'::text), ''::text) = 'pipeline_watch'::text) OR (COALESCE((k.payload ->> 'notice_phase'::text), ''::text) = 'pipeline'::text) OR (lower(COALESCE(k.document_type, ''::text)) ~~ '%general procurement notice%'::text))) THEN 'pipeline_watch'::text
            WHEN ((upper(COALESCE((k.payload ->> 'source'::text), 'KRPP'::text)) = ANY (ARRAY['KRPP'::text, 'APP'::text, 'APP_AL'::text, 'MCA_KOSOVO'::text, 'KCF'::text, 'RCF'::text, 'EBRD_ECEPP'::text, 'WORLD_BANK'::text, 'UNGM'::text, 'UNDP_KOSOVO'::text, 'EU_OFFICE_KOSOVO'::text])) AND (COALESCE((k.payload ->> 'notice_phase'::text), 'opportunity'::text) = 'opportunity'::text)) THEN 'direct_tender'::text
            WHEN ((upper(COALESCE((k.payload ->> 'source'::text), ''::text)) = 'TED'::text) AND (COALESCE((k.payload ->> 'notice_phase'::text), 'opportunity'::text) = 'opportunity'::text)) THEN 'ted_watch'::text
            WHEN ((upper(COALESCE((k.payload ->> 'source'::text), ''::text)) = 'TED'::text) AND (COALESCE((k.payload ->> 'notice_phase'::text), ''::text) = 'award'::text)) THEN 'ted_award_sales'::text
            ELSE 'reference'::text
        END AS operating_lane,
    (NULLIF((k.payload ->> 'next_check_on'::text), ''::text))::date AS next_check_on,
    COALESCE(((k.payload ->> 'human_action_required'::text))::boolean, false) AS human_action_required,
    COALESCE(NULLIF(oc.company_type, ''::text), (k.payload #>> '{winner,company_type}'::text[]), 'unknown'::text) AS winner_company_type,
    COALESCE(NULLIF(oc.cooperation_angle, ''::text), (k.payload ->> 'cooperation_angle'::text)) AS cooperation_angle
   FROM (public.kek_tender_watch k
     LEFT JOIN LATERAL ( SELECT o.company_type,
            o.cooperation_angle
           FROM public.outreach_contacts o
          WHERE (o.tender_watch_id = k.id)
          ORDER BY COALESCE(o.touch_3, o.touch_2, o.touch_1) DESC NULLS LAST, o.updated_at DESC NULLS LAST, o.id DESC
         LIMIT 1) oc ON (true));


ALTER VIEW public.pppp_tender_operating_lanes_v1 OWNER TO postgres;

--
-- Name: pppp_tender_price_features_v1; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.pppp_tender_price_features_v1 (
    tender_watch_id uuid NOT NULL,
    schema_version text DEFAULT 'v1'::text NOT NULL,
    extraction_state text DEFAULT 'pending'::text NOT NULL,
    extraction_source text,
    extracted_at timestamp with time zone,
    total_weight_kg numeric,
    structural_steel_weight_kg numeric,
    steel_grades text[] DEFAULT '{}'::text[] NOT NULL,
    execution_classes text[] DEFAULT '{}'::text[] NOT NULL,
    surface_treatments text[] DEFAULT '{}'::text[] NOT NULL,
    fabrication_complexity text,
    erection_scope text,
    delivery_scope text,
    incoterms text,
    country text,
    lot_count integer,
    bid_count integer,
    award_value numeric,
    award_currency text,
    estimated_contract_value numeric,
    steel_scope_purity_score integer,
    technical_completeness_score integer,
    confidence numeric,
    evidence jsonb DEFAULT '[]'::jsonb NOT NULL,
    raw_features jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pppp_tender_price_features_v1_award_value_check CHECK (((award_value IS NULL) OR (award_value >= (0)::numeric))),
    CONSTRAINT pppp_tender_price_features_v1_bid_count_check CHECK (((bid_count IS NULL) OR (bid_count >= 0))),
    CONSTRAINT pppp_tender_price_features_v1_confidence_check CHECK (((confidence IS NULL) OR ((confidence >= (0)::numeric) AND (confidence <= (1)::numeric)))),
    CONSTRAINT pppp_tender_price_features_v1_erection_scope_check CHECK (((erection_scope IS NULL) OR (erection_scope = ANY (ARRAY['included'::text, 'excluded'::text, 'partial'::text, 'unknown'::text])))),
    CONSTRAINT pppp_tender_price_features_v1_estimated_contract_value_check CHECK (((estimated_contract_value IS NULL) OR (estimated_contract_value >= (0)::numeric))),
    CONSTRAINT pppp_tender_price_features_v1_extraction_source_check CHECK (((extraction_source IS NULL) OR (extraction_source = ANY (ARRAY['dossier_ai'::text, 'ted_enrichment'::text, 'derived'::text, 'manual'::text])))),
    CONSTRAINT pppp_tender_price_features_v1_extraction_state_check CHECK ((extraction_state = ANY (ARRAY['pending'::text, 'extracted'::text, 'review'::text, 'error'::text]))),
    CONSTRAINT pppp_tender_price_features_v1_fabrication_complexity_check CHECK (((fabrication_complexity IS NULL) OR (fabrication_complexity = ANY (ARRAY['simple'::text, 'medium'::text, 'complex'::text, 'very_complex'::text, 'unknown'::text])))),
    CONSTRAINT pppp_tender_price_features_v1_lot_count_check CHECK (((lot_count IS NULL) OR (lot_count >= 0))),
    CONSTRAINT pppp_tender_price_features_v1_steel_scope_purity_score_check CHECK (((steel_scope_purity_score IS NULL) OR ((steel_scope_purity_score >= 0) AND (steel_scope_purity_score <= 100)))),
    CONSTRAINT pppp_tender_price_features_v1_structural_steel_weight_kg_check CHECK (((structural_steel_weight_kg IS NULL) OR (structural_steel_weight_kg >= (0)::numeric))),
    CONSTRAINT pppp_tender_price_features_v1_total_weight_kg_check CHECK (((total_weight_kg IS NULL) OR (total_weight_kg >= (0)::numeric))),
    CONSTRAINT pppp_tender_price_features_v_technical_completeness_score_check CHECK (((technical_completeness_score IS NULL) OR ((technical_completeness_score >= 0) AND (technical_completeness_score <= 100))))
);


ALTER TABLE public.pppp_tender_price_features_v1 OWNER TO postgres;

--
-- Name: pppp_tender_price_dataset_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_tender_price_dataset_v1 WITH (security_invoker='true') AS
 SELECT t.id AS tender_watch_id,
    COALESCE(NULLIF((t.payload ->> 'source'::text), ''::text), NULLIF(t.source_key, ''::text), 'UNKNOWN'::text) AS source,
    t.publication_no,
    t.procurement_no,
    t.title,
    t.authority,
    t.published_date,
    t.deadline,
    t.relevance_score,
    t.category,
    t.contract_type,
    t.procedure,
    t.currency AS source_currency,
    t.estimated_value AS source_estimated_value,
    (t.payload ->> 'cpv'::text) AS cpv_raw,
    COALESCE(NULLIF(f.country, ''::text), NULLIF((t.payload ->> 'country'::text), ''::text), NULLIF((t.payload ->> 'place_of_performance'::text), ''::text)) AS country,
    (t.payload ->> 'notice_phase'::text) AS notice_phase,
    ((t.payload -> 'winner'::text) ->> 'name'::text) AS winner_name,
    COALESCE(f.award_value, (NULLIF(((t.payload -> 'winner'::text) ->> 'award_value'::text), ''::text))::numeric, (NULLIF(((t.payload -> 'winner'::text) ->> 'value'::text), ''::text))::numeric) AS award_value,
    COALESCE(NULLIF(f.award_currency, ''::text), NULLIF(((t.payload -> 'winner'::text) ->> 'currency'::text), ''::text), NULLIF(t.currency, ''::text)) AS award_currency,
    f.estimated_contract_value,
    f.total_weight_kg,
    f.structural_steel_weight_kg,
    f.steel_grades,
    f.execution_classes,
    f.surface_treatments,
    f.fabrication_complexity,
    f.erection_scope,
    f.delivery_scope,
    f.incoterms,
    f.lot_count,
    f.bid_count,
    f.steel_scope_purity_score,
    f.technical_completeness_score,
    f.confidence,
    f.extraction_state,
    f.extraction_source,
    f.extracted_at,
    COALESCE((((t.payload -> 'dossier_analysis'::text) ->> 'dossier_complete'::text))::boolean, ((t.payload ->> 'opportunity_dossier_complete'::text))::boolean, false) AS dossier_complete,
        CASE
            WHEN (COALESCE((((t.payload -> 'dossier_analysis'::text) ->> 'dossier_complete'::text))::boolean, ((t.payload ->> 'opportunity_dossier_complete'::text))::boolean, false) AND ((jsonb_array_length(COALESCE((((t.payload -> 'dossier_analysis'::text) -> 'analysis'::text) -> 'known_quantities_specs'::text), '[]'::jsonb)) > 0) OR (jsonb_array_length(COALESCE((((t.payload -> 'dossier_analysis'::text) -> 'analysis'::text) -> 'steel_scope'::text), '[]'::jsonb)) > 0) OR (f.structural_steel_weight_kg IS NOT NULL) OR (f.total_weight_kg IS NOT NULL))) THEN 'FULL_TECHNICAL'::text
            WHEN ((t.payload ? 'dossier_analysis'::text) OR (f.tender_watch_id IS NOT NULL)) THEN 'PARTIAL'::text
            ELSE 'MARKET_ONLY'::text
        END AS dataset_class,
    LEAST(100, (((((((((10 +
        CASE
            WHEN (NULLIF(t.title, ''::text) IS NOT NULL) THEN 5
            ELSE 0
        END) +
        CASE
            WHEN (NULLIF(t.authority, ''::text) IS NOT NULL) THEN 5
            ELSE 0
        END) +
        CASE
            WHEN (t.published_date IS NOT NULL) THEN 5
            ELSE 0
        END) +
        CASE
            WHEN (NULLIF((t.payload ->> 'cpv'::text), ''::text) IS NOT NULL) THEN 10
            ELSE 0
        END) +
        CASE
            WHEN (NULLIF(((t.payload -> 'winner'::text) ->> 'name'::text), ''::text) IS NOT NULL) THEN 10
            ELSE 0
        END) +
        CASE
            WHEN (COALESCE(f.award_value, (NULLIF(((t.payload -> 'winner'::text) ->> 'award_value'::text), ''::text))::numeric, (NULLIF(((t.payload -> 'winner'::text) ->> 'value'::text), ''::text))::numeric) IS NOT NULL) THEN 15
            ELSE 0
        END) +
        CASE
            WHEN (t.payload ? 'dossier_analysis'::text) THEN 10
            ELSE 0
        END) +
        CASE
            WHEN COALESCE((((t.payload -> 'dossier_analysis'::text) ->> 'dossier_complete'::text))::boolean, ((t.payload ->> 'opportunity_dossier_complete'::text))::boolean, false) THEN 15
            ELSE 0
        END) +
        CASE
            WHEN ((f.structural_steel_weight_kg IS NOT NULL) OR (f.total_weight_kg IS NOT NULL)) THEN 15
            ELSE 0
        END)) AS data_quality_score,
        CASE
            WHEN ((COALESCE(NULLIF((t.payload ->> 'source'::text), ''::text), NULLIF(t.source_key, ''::text)) = 'TED'::text) AND (COALESCE(f.award_value, (NULLIF(((t.payload -> 'winner'::text) ->> 'award_value'::text), ''::text))::numeric, (NULLIF(((t.payload -> 'winner'::text) ->> 'value'::text), ''::text))::numeric) IS NULL)) THEN true
            ELSE false
        END AS needs_ted_enrichment,
        CASE
            WHEN ((COALESCE(NULLIF((t.payload ->> 'source'::text), ''::text), NULLIF(t.source_key, ''::text)) = ANY (ARRAY['KRPP'::text, 'APP_AL'::text, 'APP'::text])) AND (NOT (COALESCE((((t.payload -> 'dossier_analysis'::text) ->> 'dossier_complete'::text))::boolean, ((t.payload ->> 'opportunity_dossier_complete'::text))::boolean, false) OR public.pppp_tender_saved_archive_complete_v1(t.payload)))) THEN true
            ELSE false
        END AS needs_dossier_upload,
        CASE
            WHEN (COALESCE((((t.payload -> 'dossier_analysis'::text) ->> 'dossier_complete'::text))::boolean, ((t.payload ->> 'opportunity_dossier_complete'::text))::boolean, false) AND (t.category = 'steel_structure'::text) AND ((jsonb_array_length(COALESCE((((t.payload -> 'dossier_analysis'::text) -> 'analysis'::text) -> 'steel_scope'::text), '[]'::jsonb)) > 0) OR ((jsonb_array_length(COALESCE((((t.payload -> 'dossier_analysis'::text) -> 'analysis'::text) -> 'known_quantities_specs'::text), '[]'::jsonb)) > 0) AND (COALESCE(((((t.payload -> 'dossier_analysis'::text) -> 'analysis'::text) -> 'capability_fit'::text) ->> 'rating'::text), ''::text) = ANY (ARRAY['strong'::text, 'possible'::text]))) OR (f.structural_steel_weight_kg IS NOT NULL) OR (f.total_weight_kg IS NOT NULL)) AND ((f.tender_watch_id IS NULL) OR (f.extraction_state IS DISTINCT FROM 'extracted'::text))) THEN true
            ELSE false
        END AS needs_feature_extraction,
        CASE
            WHEN ((COALESCE(f.structural_steel_weight_kg, f.total_weight_kg) > (0)::numeric) AND (COALESCE(f.award_value, (NULLIF(((t.payload -> 'winner'::text) ->> 'award_value'::text), ''::text))::numeric, (NULLIF(((t.payload -> 'winner'::text) ->> 'value'::text), ''::text))::numeric) > (0)::numeric) AND (COALESCE(f.steel_scope_purity_score, 0) >= 60)) THEN true
            ELSE false
        END AS price_model_eligible,
    (((t.payload -> 'dossier_analysis'::text) -> 'analysis'::text) -> 'steel_scope'::text) AS steel_scope,
    (((t.payload -> 'dossier_analysis'::text) -> 'analysis'::text) -> 'known_quantities_specs'::text) AS known_quantities_specs,
    (((t.payload -> 'dossier_analysis'::text) -> 'analysis'::text) -> 'technical_requirements'::text) AS technical_requirements,
    f.evidence AS price_feature_evidence,
    f.raw_features AS price_raw_features,
    GREATEST(t.updated_at, COALESCE(f.updated_at, t.updated_at)) AS updated_at
   FROM (public.kek_tender_watch t
     LEFT JOIN public.pppp_tender_price_features_v1 f ON ((f.tender_watch_id = t.id)));


ALTER VIEW public.pppp_tender_price_dataset_v1 OWNER TO postgres;

--
-- Name: pppp_tender_price_work_queue_v1; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pppp_tender_price_work_queue_v1 WITH (security_invoker='true') AS
 SELECT tender_watch_id,
    source,
    publication_no,
    procurement_no,
    title,
    authority,
    published_date,
    relevance_score,
    dataset_class,
    data_quality_score,
    (needs_ted_enrichment AND (COALESCE((price_raw_features ->> 'ted_enrichment_checked_at'::text), ''::text) = ''::text)) AS needs_ted_enrichment,
    needs_dossier_upload,
    (needs_feature_extraction AND (category = 'steel_structure'::text)) AS needs_feature_extraction,
    price_model_eligible,
        CASE
            WHEN needs_dossier_upload THEN 'UPLOAD_DOSSIER'::text
            WHEN (needs_feature_extraction AND (category = 'steel_structure'::text)) THEN 'EXTRACT_FEATURES'::text
            WHEN (needs_ted_enrichment AND (COALESCE((price_raw_features ->> 'ted_enrichment_checked_at'::text), ''::text) = ''::text)) THEN 'ENRICH_TED'::text
            WHEN price_model_eligible THEN 'READY'::text
            ELSE 'REVIEW_DATA'::text
        END AS next_action,
    LEAST(100, (((COALESCE(relevance_score, 0) +
        CASE
            WHEN (needs_feature_extraction AND (category = 'steel_structure'::text)) THEN 15
            ELSE 0
        END) +
        CASE
            WHEN needs_dossier_upload THEN 10
            ELSE 0
        END) +
        CASE
            WHEN (needs_ted_enrichment AND (COALESCE((price_raw_features ->> 'ted_enrichment_checked_at'::text), ''::text) = ''::text)) THEN 5
            ELSE 0
        END)) AS queue_priority,
        CASE
            WHEN (source = 'TED'::text) THEN 'PUBLIC_API_FIRST'::text
            WHEN (source = ANY (ARRAY['KRPP'::text, 'APP_AL'::text, 'APP'::text])) THEN 'USER_UPLOAD_THEN_AI'::text
            ELSE 'REVIEW'::text
        END AS processing_mode,
    updated_at
   FROM public.pppp_tender_price_dataset_v1 d;


ALTER VIEW public.pppp_tender_price_work_queue_v1 OWNER TO postgres;

--
-- Name: pppp_tender_project_promotions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.pppp_tender_project_promotions (
    tender_watch_id uuid NOT NULL,
    operating_lane text NOT NULL,
    promotion_state text DEFAULT 'candidate'::text NOT NULL,
    eligibility_reason text,
    project_id uuid,
    last_evaluated_at timestamp with time zone DEFAULT now() NOT NULL,
    promoted_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
