--
-- Name: pppp_company_cross_module_v1 _RETURN; Type: RULE; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW public.pppp_company_cross_module_v1 WITH (security_invoker='true') AS
 SELECT c.id AS company_id,
    c.legal_name,
    c.official_domain,
    c.country_code,
    c.size_band,
    c.primary_activity,
    c.consumption_potential,
    array_agg(DISTINCT r.module ORDER BY r.module) FILTER (WHERE r.active) AS modules,
    count(*) FILTER (WHERE r.active) AS active_roles
   FROM (public.pppp_company_identity_v1 c
     LEFT JOIN public.pppp_company_module_roles_v1 r ON ((r.company_id = c.id)))
  GROUP BY c.id;


--
-- Name: pppp_gc_daily_summary_v1 _RETURN; Type: RULE; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW public.pppp_gc_daily_summary_v1 WITH (security_invoker='true') AS
 SELECT r.run_date,
    r.lane,
    r.status,
    r.requested_count,
    r.discovered_count,
    r.accepted_count,
    r.duplicate_count,
    r.contact_ready_count,
    r.response_id,
    r.error_message,
    r.started_at,
    r.finished_at,
    count(p.id) AS prospect_rows,
    count(p.id) FILTER (WHERE (p.status = 'already_contacted'::text)) AS already_contacted_rows,
    count(p.id) FILTER (WHERE (p.status = 'contact_ready'::text)) AS contact_ready_rows,
    count(p.id) FILTER (WHERE (p.status = 'research_ready'::text)) AS research_ready_rows
   FROM (public.pppp_gc_discovery_runs_v1 r
     LEFT JOIN public.pppp_gc_prospects_v1 p ON ((p.discovery_run_id = r.id)))
  GROUP BY r.id;


